local D=ns.AthenaLoreCodexInput
local rows={{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"753:description:1-88","753:description:90-132","753:description:134-201","753:description:206-235","753:description:237-289","753:description:291-376","753:description:381-455","753:objective:1-41","753:objective:46-137"},["minimumStage"]=2,["questID"]=753,["sourceHash"]="a28f0e445190bd807a5c9d705716a64d31bfb85b943eb7c8df72b6cba9bd0da5"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-2991",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Greatmother Hawkwind was an elderly woman whose legs no longer had their former vigor. She still carried out her duties for the tribe, taking longer rather than setting them aside.",["title"]="Greatmother Hawkwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"752:description:1-54","752:description:56-90","752:description:95-172","752:description:174-204","752:description:209-296","752:description:298-329","752:description:331-406","752:objective:1-103"},["minimumStage"]=2,["questID"]=752,["sourceHash"]="06fb61977eea2327a80dbd7b957f20ce3a760bd3e964a1525535b31750c94862"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-2981",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Chief Hawkwind regarded shared work and responsibility as part of the tribe's harmony. Even checking on his mother at the well belonged to that duty toward one another.",["title"]="Chief Hawkwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"757:description:1-105","757:description:110-150","757:description:152-224","757:description:229-312","757:description:314-380","757:description:385-506","757:objective:1-106"},["minimumStage"]=2,["questID"]=757,["sourceHash"]="374b0db0524cf79ac4252a0e23d91fd534c30ce1c42ad16c0286aa0f116611dd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-2982",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Seer Graytongue guided the first of the Earthmother's rites, testing courage against enemies encroaching on the tribe's lands.",["title"]="Seer Graytongue"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"763:description:1-83","763:description:85-134","763:description:139-221","763:description:223-313","763:description:318-342","763:description:344-399","763:description:404-461","763:description:463-501","763:objective:1-67","763:objective:69-104"},["minimumStage"]=2,["questID"]=763,["sourceHash"]="0dbf1744274073721cc8159083ee0c9af58ad88e0e3a9d4db5991409df470a51"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-2993",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Baine Bloodhoof, Cairne's son, led Bloodhoof Village. Hawkwind's carved totem introduced travelers continuing the Earthmother's rites to him.",["title"]="Baine Bloodhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"767:description:1-135","767:description:140-203","767:description:205-328","767:objective:1-50"},["minimumStage"]=2,["questID"]=767,["sourceHash"]="0beb31d9639837e78d224ed67fa47b0f9f8bf2ea41def902f1b967e89cf93157"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3054",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zarlman Two-Moons was Bloodhoof Village's spiritual leader, consulted by those preparing for the Rite of Vision.",["title"]="Zarlman Two-Moons"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"771:description:1-112","771:description:117-194","771:description:196-280","771:description:285-415","771:description:417-484","771:objective:1-100"},["minimumStage"]=2,["questID"]=771,["sourceHash"]="e63afb114c516aadea27c1d5cc24e21981219a7e38758e8f66bc7e6bcd625c78"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3054",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zarlman Two-Moons brewed the Water of the Seers from well stones and ambercorn. The land's gathered reagents would support a vision sought before the tribal fire.",["title"]="Zarlman Two-Moons"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"773:description:1-97","773:description:102-225","773:description:227-298","773:description:303-383","773:objective:1-78"},["minimumStage"]=2,["questID"]=773,["sourceHash"]="ab291b60cdbbad04b7060edbd83a3c09640700a38ec28fd8f63a1c9ad8573aca"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2984",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Seer Wiserunner directed those who had passed the vision toward the ancestral spirits at Red Rocks for the Rite of Wisdom.",["title"]="Seer Wiserunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2118:description:1-89","2118:description:94-152","2118:description:154-233","2118:description:235-269","2118:description:274-327","2118:description:329-411","2118:description:413-457","2118:description:459-480","2118:objective:1-68","2118:objective:73-197"},["minimumStage"]=2,["questID"]=2118,["sourceHash"]="2a5b1103abe6c706fc6de5e4fc33d7b5e7c03febb0a51d38e8627e6310412e0e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3701",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tharnariun Treetender hoped to find a cure for Darkshore's rabid thistle bears. A living specimen, made briefly docile by his trap, was the first thing he required.",["title"]="Tharnariun Treetender"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2138:description:1-40","2138:description:45-168","2138:description:173-232","2138:description:234-391","2138:objective:1-94"},["minimumStage"]=2,["questID"]=2138,["sourceHash"]="ef0d5a2e37446aa5733ab4cfa1c44893dd0b8335df4c12b83d37bf48ed9d6f3a"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3701",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tharnariun Treetender's proposed cure failed. He turned reluctantly to culling sick thistle bears to slow the harm they caused, while acknowledging that this would not end the plague.",["title"]="Tharnariun Treetender"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"218:description:1-11","218:description:13-42","218:description:44-65","218:description:67-129","218:description:131-172","218:description:177-252","218:objective:1-80"},["minimumStage"]=2,["questID"]=218,["sourceHash"]="cfb63fbe77b3a18c95cb0fe76bd1e49349e102164536c80b2ee2f8a3443d4a79"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-808",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grelin described Grik'nir the Cold as a large brute with unusual markings on his skin and face. Recovering the stolen journal meant seeking the one who had carried it into the cave.",["title"]="Grik'nir the Cold"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1136:description:1-54","1136:description:57-70","1136:description:75-129","1136:description:132-206","1136:description:209-232","1136:description:237-292","1136:description:295-317","1136:description:320-366","1136:description:371-381","1136:description:384-436","1136:description:439-508","1136:objective:1-58"},["minimumStage"]=2,["questID"]=1136,["sourceHash"]="5738e3767ee316402a726abd8fccaa1bd366bcb69db85d3862911402b56f386f"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-4504",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Frostmaw's white coat concealed the elusive yeti among Alterac's snows. Melor's instructions made luring him part of the hunt.",["title"]="Frostmaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1131:description:1-26","1131:description:29-55","1131:description:58-114","1131:description:119-174","1131:description:177-236","1131:description:241-309","1131:description:312-418","1131:description:423-441","1131:description:444-468","1131:objective:1-58"},["minimumStage"]=2,["questID"]=1131,["sourceHash"]="a08d23077fca21d8ed9d82737de3569244340f113977f1b0fc419c7726023be9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4548",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Melor saw Steelsnap's terror over peaceful beasts as a taint beyond ordinary hunting for food or honor. His charge against the hyena followed from that judgment.",["title"]="Steelsnap"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2139:description:1-68","2139:description:73-155","2139:description:157-260","2139:description:265-338","2139:description:340-405","2139:description:410-478","2139:description:480-488","2139:objective:1-29"},["minimumStage"]=2,["questID"]=2139,["sourceHash"]="144f6837f3c483d095483736e6b6e2e9046105e0c02b71b0da5bbf956556ae88"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6788",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tharnariun placed the Den Mother in a cave northeast of Auberdine near Bashal'Aran. His final charge against her followed the failed attempt to cure the infected bears.",["title"]="Den Mother"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"182:description:1-112","182:description:114-202","182:description:207-310","182:description:312-355","182:description:357-401","182:description:406-451","182:description:453-509","182:objective:1-67"},["minimumStage"]=2,["questID"]=182,["sourceHash"]="73288de300a82169bed0458c0305e31050fce3f7640e5dc01467812c26099013"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-786",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grelin Whitebeard and his brother Senir investigated the trolls in different parts of Dun Morogh. With the Senate occupied by troggs, Grelin initially thought a few capable fighters could handle the Coldridge threat.",["title"]="Grelin Whitebeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"287:description:1-53","287:description:55-156","287:description:161-181","287:description:183-269","287:description:274-396","287:description:398-443","287:description:445-481","287:objective:1-90"},["minimumStage"]=2,["questID"]=287,["sourceHash"]="b96d77c23b7e11258b6dc86abd9af989e5b1ee09badf74a3a667dfb0b9fb2d6f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1252",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senir Whitebeard had fallen behind on his report. An expedition into Frostmane Hold could supply the observations he still needed, where the number of trolls had made him hesitate to enter.",["title"]="Senir Whitebeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"763:description:1-83","763:description:85-134","763:description:139-221","763:description:223-313","763:description:318-342","763:description:344-399","763:description:404-461","763:description:463-501","763:objective:1-67","763:objective:69-104"},["minimumStage"]=2,["questID"]=763,["sourceHash"]="0dbf1744274073721cc8159083ee0c9af58ad88e0e3a9d4db5991409df470a51"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-222",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Baine Bloodhoof led the village, where travelers carrying Hawkwind's totem could continue their path toward acceptance in Thunder Bluff.",["title"]="Bloodhoof Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"772:description:1-46","772:description:51-110","772:description:112-225","772:description:230-292","772:objective:1-118"},["minimumStage"]=2,["questID"]=772,["sourceHash"]="1b64461fc9fac566caf8ebbdfadb10dba64fb1651127e13cf3601b47b0e0b134"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-222",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The tribal fire in Bloodhoof Village was the appointed place to drink the Water of the Seers and await the vision that would guide the next part of the rites.",["title"]="Bloodhoof Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"757:description:1-105","757:description:110-150","757:description:152-224","757:description:229-312","757:description:314-380","757:description:385-506","757:objective:1-106"},["minimumStage"]=2,["questID"]=757,["sourceHash"]="374b0db0524cf79ac4252a0e23d91fd534c30ce1c42ad16c0286aa0f116611dd"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="brambleblade-ravine",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bristlebacks in Brambleblade Ravine encroached on tauren lands, ambushing hunters and stealing from the village after dark. Their attacks gave the Rite of Strength a purpose in the tribe's defense.",["title"]="Brambleblade Ravine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"748:description:1-63","748:description:66-86","748:description:91-218","748:description:223-291","748:description:294-333","748:description:335-410","748:description:413-438","748:description:443-484","748:objective:1-85"},["minimumStage"]=2,["questID"]=748,["sourceHash"]="f4dee6e1ee072c9419d5596d79eaa24cf824a7fc3e6bbe90a7f4979596a4fb43"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-396",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mull Thunderhorn blamed goblins and their servants for tainting the sacred wells. Winterhoof was the first well for which he prepared a cleansing totem.",["title"]="Winterhoof Water Well"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"758:description:1-23","758:description:26-87","758:description:92-202","758:description:205-236","758:description:241-266","758:objective:1-87","758:completion:1-104","758:completion:109-158"},["minimumStage"]=4,["questID"]=758,["sourceHash"]="45fd37bfdad0b11895e31dc037608627082da08034551e7dd540520d5a849564"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-397",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mull Thunderhorn reported a dream in which the Thunderhorn ancestors praised the actions at their well. Their gratitude belonged to his account of the completed ritual.",["title"]="Thunderhorn Water Well"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"760:description:1-93","760:description:96-153","760:description:158-209","760:description:212-230","760:description:233-270","760:description:273-304","760:objective:1-93","760:completion:1-15","760:completion:17-64","760:completion:66-99","760:completion:104-209"},["minimumStage"]=4,["questID"]=760,["sourceHash"]="785c748c6b8f21237d76ea118fa1f3e316bcdac3c9cb8565a7f354b337630e5e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-398",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mull Thunderhorn acknowledged the wells' cleansing after the Wildmane ritual. His wish that Mulgore's waters remain pure was a blessing for the future, not a guarantee against later harm.",["title"]="Wildmane Water Well"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"773:description:1-97","773:description:102-225","773:description:227-298","773:description:303-383","773:objective:1-78","773:completion:1-89","773:completion:94-230","773:completion:232-285","773:completion:290-334","773:completion:336-366"},["minimumStage"]=4,["questID"]=773,["sourceHash"]="ab291b60cdbbad04b7060edbd83a3c09640700a38ec28fd8f63a1c9ad8573aca"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="red-rocks",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The ancestral spirits at Red Rocks remembered tauren who had died founding and protecting Thunder Bluff. Their blessing passed the duty of that protection to those completing the Rite of Wisdom.",["title"]="Red Rocks"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"287:description:1-53","287:description:55-156","287:description:161-181","287:description:183-269","287:description:274-396","287:description:398-443","287:description:445-481","287:objective:1-90"},["minimumStage"]=2,["questID"]=287,["sourceHash"]="b96d77c23b7e11258b6dc86abd9af989e5b1ee09badf74a3a667dfb0b9fb2d6f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-135",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senir's directions placed Frostmane Hold southwest of Brewnall Village, beyond the frozen river and Iceflow Lake.",["title"]="Frostmane Hold"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"287:description:1-53","287:description:55-156","287:description:161-181","287:description:183-269","287:description:274-396","287:description:398-443","287:description:445-481","287:objective:1-90"},["minimumStage"]=2,["questID"]=287,["sourceHash"]="b96d77c23b7e11258b6dc86abd9af989e5b1ee09badf74a3a667dfb0b9fb2d6f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-135",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The trolls gathered in Frostmane Hold in numbers that had deterred Senir from entering. Scouting the cave and confronting its headhunters would supply his unfinished report.",["title"]="Frostmane Hold"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"966:description:1-71","966:description:73-198","966:description:203-289","966:description:294-416","966:description:418-510","966:objective:1-80"},["minimumStage"]=2,["questID"]=966,["sourceHash"]="9f4012bafcf8365e87c1804fb171d3631c31ff7b88281e11700f5f1c4aa8e193"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-444",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Warlocks occupied the ground around the Tower of Althalaxx as well as its interior. Balthule warned that those within were more powerful than the ones outside.",["title"]="Tower of Althalaxx"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"966:description:1-71","966:description:73-198","966:description:203-289","966:description:294-416","966:description:418-510","966:objective:1-80","966:completion:1-16","966:completion:18-75","966:completion:80-85","966:completion:87-116","966:completion:118-157","966:completion:159-253","966:completion:258-288","966:completion:290-338"},["minimumStage"]=4,["questID"]=966,["sourceHash"]="9f4012bafcf8365e87c1804fb171d3631c31ff7b88281e11700f5f1c4aa8e193"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-444",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The recovered parchments identified the warlocks as the Cult of the Dark Strand. Balthule sought Delgren's help because the cult's intentions were still unclear.",["title"]="Tower of Althalaxx"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"176:description:1-14","176:description:19-85","176:description:88-134","176:description:139-199","176:description:202-305","176:objective:1-70"},["minimumStage"]=2,["questID"]=176,["sourceHash"]="e3ed6754a117194bb78692507a4f61b5673fecc960b46031e81208eb4e3e14b8"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-448",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Stormwind Army’s wanted notice described Hogger as a huge gnoll who prowled southwestern Elwynn’s woods and had overpowered earlier attempts to capture him.",["title"]="Hogger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"176:description:1-14","176:description:19-85","176:description:88-134","176:description:139-199","176:description:202-305","176:objective:1-70"},["minimumStage"]=2,["questID"]=176,["sourceHash"]="e3ed6754a117194bb78692507a4f61b5673fecc960b46031e81208eb4e3e14b8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-448",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hogger’s resistance to capture had brought a bounty from the Stormwind Army, payable through Marshal Dughan upon proof of the gnoll’s death.",["title"]="Hogger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"104:description:1-84","104:description:87-178","104:description:181-309","104:description:312-399","104:description:404-506","104:objective:1-76"},["minimumStage"]=2,["questID"]=104,["sourceHash"]="52426014bd50b6208676b7cd382f95adb4cd71bc511255b403a9f9c8b8f19983"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-391",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Captain Grayson blamed Old Murk-Eye for driving the lighthouse keeper’s family away, then leading the later attack in which they died.",["title"]="Old Murk-Eye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"103:description:1-59","103:description:62-113","103:description:116-269","103:description:272-348","103:description:353-436","103:objective:1-68"},["minimumStage"]=2,["questID"]=103,["sourceHash"]="5e026671cb91345423bea194b5a775ab384a2e3192e5b1c6044f1828889b712b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-392",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Captain Grayson’s own death on Westfall’s rocks left him determined to keep the lighthouse flame burning so that other sailors would not share his fate.",["title"]="Captain Grayson"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"88:description:1-50","88:description:53-136","88:description:141-194","88:description:197-279","88:description:284-380","88:description:383-433","88:objective:1-91"},["minimumStage"]=2,["questID"]=88,["sourceHash"]="7e097c57e80ac4fafa3eea4e51cfc0effddf6d7d4118ca8a3afcb9c8fd942467"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-330",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Princess was the Brackwells’ enormous, prize-winning sow. Ma Stonefield blamed her appetite for the vegetables disappearing from the neighboring farm.",["title"]="Princess"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"88:description:1-50","88:description:53-136","88:description:141-194","88:description:197-279","88:description:284-380","88:description:383-433","88:objective:1-91"},["minimumStage"]=2,["questID"]=88,["sourceHash"]="7e097c57e80ac4fafa3eea4e51cfc0effddf6d7d4118ca8a3afcb9c8fd942467"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-330",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Princess’s raids on the Stonefields’ vegetables turned a farm animal into a dispute between neighboring households. Ma Stonefield demanded the sow’s collar as proof that the crop was safe.",["title"]="Princess"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"88:description:1-50","88:description:53-136","88:description:141-194","88:description:197-279","88:description:284-380","88:description:383-433","88:objective:1-91"},["minimumStage"]=2,["questID"]=88,["sourceHash"]="7e097c57e80ac4fafa3eea4e51cfc0effddf6d7d4118ca8a3afcb9c8fd942467"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-244",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ma Stonefield wanted to protect her family’s vegetables from the Brackwells’ voracious sow, Princess, before another visit stripped the fields.",["title"]="Ma Stonefield"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"314:description:1-46","314:description:49-110","314:description:113-184","314:description:187-304","314:description:309-372","314:description:375-422","314:description:425-492","314:objective:1-85"},["minimumStage"]=2,["questID"]=314,["sourceHash"]="98f149351e76aeb892f2515d10cea7e0527e87d0f63cc810542461b40d795dac"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1388",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vagash preyed on the Amberstills’ rams above their ranch. After cries in the night, two animals were missing from the herd.",["title"]="Vagash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"314:description:1-46","314:description:49-110","314:description:113-184","314:description:187-304","314:description:309-372","314:description:375-422","314:description:425-492","314:objective:1-85"},["minimumStage"]=2,["questID"]=314,["sourceHash"]="98f149351e76aeb892f2515d10cea7e0527e87d0f63cc810542461b40d795dac"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1265",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rudra Amberstill needed help protecting the ranch’s livelihood from Vagash while much of King Magni’s army was away fighting alongside the Alliance.",["title"]="Rudra Amberstill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"417:description:1-152","417:description:157-249","417:description:254-312","417:description:317-342","417:objective:1-15","417:objective:20-83"},["minimumStage"]=2,["questID"]=417,["sourceHash"]="c9915170b97f1b8ed4350fae5e08d05a819803ff3d9edb829a0e070131cc63bb"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-1961",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hildelve’s journal described Mangeclaw as a huge Ice Claw Bear, powerful enough to maul the pilot despite being driven off during their first encounter.",["title"]="Mangeclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"417:description:1-152","417:description:157-249","417:description:254-312","417:description:317-342","417:objective:1-15","417:objective:20-83"},["minimumStage"]=2,["questID"]=417,["sourceHash"]="c9915170b97f1b8ed4350fae5e08d05a819803ff3d9edb829a0e070131cc63bb"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1961",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The journal and the condition of Hildelve’s body led Pilot Hammerfoot to believe Mangeclaw had returned after the first attack and killed him.",["title"]="Mangeclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"417:description:1-152","417:description:157-249","417:description:254-312","417:description:317-342","417:objective:1-15","417:objective:20-83"},["minimumStage"]=2,["questID"]=417,["sourceHash"]="c9915170b97f1b8ed4350fae5e08d05a819803ff3d9edb829a0e070131cc63bb"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1960",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pilot Hammerfoot’s grief for Hildelve was joined to the dead pilot’s written request for vengeance against Mangeclaw.",["title"]="Pilot Hammerfoot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5056:description:1-93","5056:description:95-150","5056:description:152-253","5056:description:258-342","5056:description:344-391","5056:description:393-463","5056:description:468-505","5056:objective:1-75"},["minimumStage"]=2,["questID"]=5056,["sourceHash"]="621cf1b02ef3ef91000b1bc0c00d162a9811022630034156e62ecce1e27d4d9a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shy-Rotam was the matriarch of the frostsabers gathering around Frostsaber Rock in northern Winterspring.",["title"]="Shy-Rotam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5056:description:1-93","5056:description:95-150","5056:description:152-253","5056:description:258-342","5056:description:344-391","5056:description:393-463","5056:description:468-505","5056:objective:1-75"},["minimumStage"]=2,["questID"]=5056,["sourceHash"]="621cf1b02ef3ef91000b1bc0c00d162a9811022630034156e62ecce1e27d4d9a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Storm Shadowhoof described a hunt in which sacred meat from the frostsabers would be placed upon Shy-Rotam’s stone, drawing the angered matriarch into view.",["title"]="Shy-Rotam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5056:description:1-93","5056:description:95-150","5056:description:152-253","5056:description:258-342","5056:description:344-391","5056:description:393-463","5056:description:468-505","5056:objective:1-75"},["minimumStage"]=2,["questID"]=5056,["sourceHash"]="621cf1b02ef3ef91000b1bc0c00d162a9811022630034156e62ecce1e27d4d9a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10303",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Storm Shadowhoof set the confrontation with Shy-Rotam as a test of strength and determination worthy of respect among fellow travelers.",["title"]="Storm Shadowhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"881:description:1-76","881:description:79-157","881:description:160-220","881:description:225-266","881:description:271-349","881:description:352-421","881:description:431-469","881:description:472-503","881:objective:1-61"},["minimumStage"]=2,["questID"]=881,["sourceHash"]="1f8a1c1efef038d6719ca3228f123e00095c76b403490d93cbd62f0829117262"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-3475",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Echeyakee’s name meant Whitemist in the tauren tongue. Tales compared the savannah cat’s stealth to a thin white mist moving close to the ground.",["title"]="Echeyakee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"881:description:1-76","881:description:79-157","881:description:160-220","881:description:225-266","881:description:271-349","881:description:352-421","881:description:431-469","881:description:472-503","881:objective:1-61"},["minimumStage"]=2,["questID"]=881,["sourceHash"]="1f8a1c1efef038d6719ca3228f123e00095c76b403490d93cbd62f0829117262"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3475",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tauren accounts described Echeyakee as both mercy and death, killing so swiftly that his prey had no time for fear or pain.",["title"]="Echeyakee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"881:description:1-76","881:description:79-157","881:description:160-220","881:description:225-266","881:description:271-349","881:description:352-421","881:description:431-469","881:description:472-503","881:objective:1-61"},["minimumStage"]=2,["questID"]=881,["sourceHash"]="1f8a1c1efef038d6719ca3228f123e00095c76b403490d93cbd62f0829117262"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3475",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sergra Darkthorn placed Echeyakee’s lair northeast of the Crossroads among the bones of giant kodo, where a horn could call him forth.",["title"]="Echeyakee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"881:description:1-76","881:description:79-157","881:description:160-220","881:description:225-266","881:description:271-349","881:description:352-421","881:description:431-469","881:description:472-503","881:objective:1-61"},["minimumStage"]=2,["questID"]=881,["sourceHash"]="1f8a1c1efef038d6719ca3228f123e00095c76b403490d93cbd62f0829117262"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3338",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sergra Darkthorn’s hunt for Echeyakee carried a lesson about strength in subtlety and honor in mercy, framed through tauren tales of Whitemist.",["title"]="Sergra Darkthorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"882:description:1-71","882:description:74-114","882:description:117-156","882:description:159-200","882:description:205-301","882:description:306-320","882:description:323-417","882:description:420-472","882:description:477-499","882:objective:1-48"},["minimumStage"]=2,["questID"]=882,["sourceHash"]="5e771b9aa8e08e6549e3319ebd66a2171cb305ee27ab065ecee9ada8560bbb30"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3257",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ishamuhale, called Speartooth, was described as the fiercest sunscale raptor of the Barrens, driven by the hunt itself rather than sport or hunger.",["title"]="Ishamuhale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"882:description:1-71","882:description:74-114","882:description:117-156","882:description:159-200","882:description:205-301","882:description:306-320","882:description:323-417","882:description:420-472","882:description:477-499","882:objective:1-48"},["minimumStage"]=2,["questID"]=882,["sourceHash"]="5e771b9aa8e08e6549e3319ebd66a2171cb305ee27ab065ecee9ada8560bbb30"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3257",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The hunt for Ishamuhale used a zhevra carcass beside the dead tree northwest of Ratchet, relying on the scent of his favored prey to draw him out.",["title"]="Ishamuhale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"790:description:5-59","790:description:61-157","790:description:159-259","790:description:264-383","790:description:385-425","790:description:427-450","790:description:452-494","790:objective:1-49"},["minimumStage"]=2,["questID"]=790,["sourceHash"]="3bafa7c82bd289860a9ac931a8839fb985a186501b417db99b67c3bfa2fee2dc"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-3281",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hana’zua remembered Sarkoth as a vicious scorpid whose closing claw and descending stinger turned the hunt against him. His own blow had damaged the creature’s claw.",["title"]="Sarkoth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"790:description:5-59","790:description:61-157","790:description:159-259","790:description:264-383","790:description:385-425","790:description:427-450","790:description:452-494","790:objective:1-49"},["minimumStage"]=2,["questID"]=790,["sourceHash"]="3bafa7c82bd289860a9ac931a8839fb985a186501b417db99b67c3bfa2fee2dc"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3281",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sarkoth wounded Hana’zua on the plateau south of the valley. The hunter’s demand for the scorpid’s claw grew from both his injuries and his fear of dying without honor.",["title"]="Sarkoth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"790:description:5-59","790:description:61-157","790:description:159-259","790:description:264-383","790:description:385-425","790:description:427-450","790:description:452-494","790:objective:1-49"},["minimumStage"]=2,["questID"]=790,["sourceHash"]="3bafa7c82bd289860a9ac931a8839fb985a186501b417db99b67c3bfa2fee2dc"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3287",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hana’zua clung to the damage he had inflicted upon Sarkoth as a small source of pride, asking for the scorpid’s death to uphold his honor.",["title"]="Hana'zua"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"766:description:1-82","766:description:84-156","766:description:161-281","766:description:283-329","766:description:331-476","766:description:481-510","766:objective:1-128"},["minimumStage"]=2,["questID"]=766,["sourceHash"]="8b1bd0e7ce521c71846b12932d7f7b11ad99b8cf028dd259263ab06c4daf87ff"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-3068",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maur Raincaller’s family stories described Mazzranache with red eyes, razor-sharp talons and a venomous bite. His own injured shoulder made the warning painfully immediate.",["title"]="Mazzranache"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"766:description:1-82","766:description:84-156","766:description:161-281","766:description:283-329","766:description:331-476","766:description:481-510","766:objective:1-128"},["minimumStage"]=2,["questID"]=766,["sourceHash"]="8b1bd0e7ce521c71846b12932d7f7b11ad99b8cf028dd259263ab06c4daf87ff"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3068",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mazzranache’s bite left Maur Raincaller with an infection, prompting an urgent search for several animal parts to prepare a remedy.",["title"]="Mazzranache"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"766:description:1-82","766:description:84-156","766:description:161-281","766:description:283-329","766:description:331-476","766:description:481-510","766:objective:1-128"},["minimumStage"]=2,["questID"]=766,["sourceHash"]="8b1bd0e7ce521c71846b12932d7f7b11ad99b8cf028dd259263ab06c4daf87ff"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3055",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maur Raincaller needed a wolf heart, cougar femur, plainstrider scale and swoop gizzard to treat the infection spreading from Mazzranache’s bite.",["title"]="Maur Raincaller"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"776:description:1-84","776:description:89-212","776:description:217-235","776:description:237-297","776:description:299-391","776:objective:1-79"},["minimumStage"]=2,["questID"]=776,["sourceHash"]="1c9c3b8ad541c813622c11792c29a08dbc138431b99d0f626c5ad132f4613455"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3058",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Arra’chea was a mighty kodo roaming Mulgore, chosen by Cairne as a further test of a hunter’s service to the tauren people.",["title"]="Arra'chea"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2:description:1-122","2:description:125-242","2:objective:1-79"},["minimumStage"]=2,["questID"]=2,["sourceHash"]="1156a12b5bd46c6de5fe1db5a30c2b104380d9427de11b14f8ff799d0638bd15"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-12676",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sharptalon was a formidable hippogryph of the Ashenvale Hunt, whose claw served as the identifying trophy in Senani Thunderheart’s account.",["title"]="Sharptalon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2:description:1-122","2:description:125-242","2:objective:1-79","2:completion:1-22","2:completion:24-78","2:completion:80-116","2:completion:121-247","2:completion:249-416"},["minimumStage"]=4,["questID"]=2,["sourceHash"]="1156a12b5bd46c6de5fe1db5a30c2b104380d9427de11b14f8ff799d0638bd15"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12676",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senani Thunderheart reported that Sharptalon had long threatened peons traveling from nearby lumber camps to Splintertree Post.",["title"]="Sharptalon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"24:description:1-69","24:description:72-161","24:description:164-291","24:objective:1-78"},["minimumStage"]=2,["questID"]=24,["sourceHash"]="8b11bd4c375aede7ff4edeca2cf46c864825d102db91fa589b47cfef0b371a13"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-12677",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shadumbra was a swift nightsaber whose head was the trophy requested for that part of the Ashenvale Hunt.",["title"]="Shadumbra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"24:description:1-69","24:description:72-161","24:description:164-291","24:objective:1-78","24:completion:1-39","24:completion:41-142","24:completion:147-207","24:completion:209-334","24:completion:336-373"},["minimumStage"]=4,["questID"]=24,["sourceHash"]="8b11bd4c375aede7ff4edeca2cf46c864825d102db91fa589b47cfef0b371a13"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12677",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senani Thunderheart remembered Shadumbra as a danger to travelers heading west toward the Zoram Strand, especially those walking the route.",["title"]="Shadumbra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"23:description:1-88","23:description:91-186","23:description:191-349","23:objective:1-77"},["minimumStage"]=2,["questID"]=23,["sourceHash"]="c9eee9db19ac6a8194c8ed14b6b1fba14d36131ff6adfaecc3b697f259a7699f"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-12678",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ursangous was a mighty bear with a small quarter-crescent emblem upon one paw. The initial trophy account left the emblem’s significance unexplained.",["title"]="Ursangous"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"23:description:1-88","23:description:91-186","23:description:191-349","23:objective:1-77","23:completion:1-25","23:completion:27-91","23:completion:93-201","23:completion:203-217","23:completion:219-275","23:completion:277-347","23:completion:352-381"},["minimumStage"]=4,["questID"]=23,["sourceHash"]="c9eee9db19ac6a8194c8ed14b6b1fba14d36131ff6adfaecc3b697f259a7699f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-12678",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senani Thunderheart interpreted the crescent on Ursangous’s paw as evidence of night elf training. That interpretation belonged to Senani’s account, rather than a witnessed history of the bear.",["title"]="Ursangous"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5062:description:1-61","5062:description:63-162","5062:description:167-215","5062:description:217-321","5062:description:323-424","5062:description:429-491","5062:objective:1-102"},["minimumStage"]=2,["questID"]=5062,["sourceHash"]="f1ca7777429ae7f3d2c7ede139b1d770be57a45e0ddff7ac5dfc608d5405b20c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10882",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Motega’s instructions connected the hunt for Arikara to the sacred fire of life and Incendia agave that Magatha could enchant into a fire-lighting powder.",["title"]="Arikara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5088:description:1-106","5088:description:108-196","5088:description:201-291","5088:description:296-410","5088:description:412-447","5088:objective:1-13","5088:objective:15-116"},["minimumStage"]=2,["questID"]=5088,["sourceHash"]="ac0a01d2fd0fac3c2eab707f87b9653fc0ad62c212371806652c587788dfc159"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10882",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magatha feared that Arikara might be stalking Cairne because tauren traditions had changed. Her warning expressed a suspicion, not knowledge of the creature’s purpose.",["title"]="Arikara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5088:description:1-106","5088:description:108-196","5088:description:201-291","5088:description:296-410","5088:description:412-447","5088:objective:1-13","5088:objective:15-116","5088:completion:1-25","5088:completion:27-70","5088:completion:72-131","5088:completion:136-160","5088:completion:165-283"},["minimumStage"]=4,["questID"]=5088,["sourceHash"]="ac0a01d2fd0fac3c2eab707f87b9653fc0ad62c212371806652c587788dfc159"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10428",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Motega Firemane questioned why Arikara would pursue Cairne, even while struggling to doubt Magatha’s judgment as a powerful shaman.",["title"]="Motega Firemane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7816:description:5-52","7816:description:54-145","7816:description:150-177","7816:description:179-207","7816:description:209-257","7816:description:262-311","7816:objective:1-134","7816:objective:139-216"},["minimumStage"]=2,["questID"]=7816,["sourceHash"]="d6bcdd6bbda190f95d2a50daf6a751945fcb709370ea455d9dea22151d83906b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7977",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gammerita was the leader of the saltwater snapjaws along the Hinterlands coast, singled out by Katoom after she bit his best lure from the fishing line.",["title"]="Gammerita"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2944:description:1-44","2944:description:46-142","2944:description:147-209","2944:description:211-220","2944:description:222-249","2944:description:251-323","2944:description:328-365","2944:description:367-375","2944:objective:1-111"},["minimumStage"]=2,["questID"]=2944,["sourceHash"]="ce6b5e1c8ae8f74d701353d88fd3652fec90ae90d85907d2541b21480741f6a1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7977",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gammerita was also the subject of Daryn Lightwind’s requested picture, using Curgle’s Super Snapper FX rather than demanding the turtle’s death.",["title"]="Gammerita"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7816:description:5-52","7816:description:54-145","7816:description:150-177","7816:description:179-207","7816:description:209-257","7816:description:262-311","7816:objective:1-134","7816:objective:139-216"},["minimumStage"]=2,["questID"]=7816,["sourceHash"]="d6bcdd6bbda190f95d2a50daf6a751945fcb709370ea455d9dea22151d83906b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14740",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Katoom the Angler wanted his best lure recovered from Gammerita, blaming its loss for his disappointing fishing.",["title"]="Katoom the Angler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2944:description:1-44","2944:description:46-142","2944:description:147-209","2944:description:211-220","2944:description:222-249","2944:description:251-323","2944:description:328-365","2944:description:367-375","2944:objective:1-111"},["minimumStage"]=2,["questID"]=2944,["sourceHash"]="ce6b5e1c8ae8f74d701353d88fd3652fec90ae90d85907d2541b21480741f6a1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7907",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Daryn Lightwind was the intended recipient of the Super Snapper FX picture of Gammerita, connecting Rut’theran Village to the creature on the Hinterlands coast.",["title"]="Daryn Lightwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"197:description:1-139","197:description:142-182","197:description:187-266","197:description:269-334","197:objective:1-89"},["minimumStage"]=2,["questID"]=197,["sourceHash"]="4016eaad99fb67f9cc905680b725f91ece982528e46462fdf290756a5c93c47d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-730",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hemet Nesingwary described Tethis as a dangerous, elusive Stranglethorn raptor that he himself had failed to kill; Ajeck had given the quarry its name.",["title"]="Tethis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"628:description:1-68","628:description:70-116","628:description:118-244","628:description:249-367","628:description:369-478","628:objective:1-55"},["minimumStage"]=2,["questID"]=628,["sourceHash"]="45cacc1d6b122d285fb393afe8f3868f120cbafc019828193b04b7c1d0fb7728"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-2635",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Drizzlik prized elder saltwater crocolisk skins as durable material suited to the designs of his Excelsior boots.",["title"]="Elder Saltwater Crocolisk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"628:description:1-68","628:description:70-116","628:description:118-244","628:description:249-367","628:description:369-478","628:objective:1-55"},["minimumStage"]=2,["questID"]=628,["sourceHash"]="45cacc1d6b122d285fb393afe8f3868f120cbafc019828193b04b7c1d0fb7728"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2635",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="According to Drizzlik’s hunting advice, elder saltwater crocolisks emerged to defend the other saltwater crocs.",["title"]="Elder Saltwater Crocolisk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"628:description:1-68","628:description:70-116","628:description:118-244","628:description:249-367","628:description:369-478","628:objective:1-55"},["minimumStage"]=2,["questID"]=628,["sourceHash"]="45cacc1d6b122d285fb393afe8f3868f120cbafc019828193b04b7c1d0fb7728"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2495",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Drizzlik needed an elder crocolisk skin to finish the outer layer of a carefully designed pair of Excelsior boots.",["title"]="Drizzlik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"104:description:1-84","104:description:87-178","104:description:181-309","104:description:312-399","104:description:404-506","104:objective:1-76"},["minimumStage"]=2,["questID"]=104,["sourceHash"]="52426014bd50b6208676b7cd382f95adb4cd71bc511255b403a9f9c8b8f19983"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-115",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Captain Grayson’s account tied the lighthouse’s darkness to Old Murk-Eye’s raids. The keeper’s family returned to relight the flame but died in the later attack.",["title"]="Westfall Lighthouse"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"88:description:1-50","88:description:53-136","88:description:141-194","88:description:197-279","88:description:284-380","88:description:383-433","88:objective:1-91"},["minimumStage"]=2,["questID"]=88,["sourceHash"]="7e097c57e80ac4fafa3eea4e51cfc0effddf6d7d4118ca8a3afcb9c8fd942467"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16156",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Brackwell Pumpkin Patch was Princess’s usual haunt, east beyond the Maclure farm. Her raids on the Stonefields’ vegetables turned the neighboring farms against one another.",["title"]="Brackwell Pumpkin Patch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"314:description:1-46","314:description:49-110","314:description:113-184","314:description:187-304","314:description:309-372","314:description:375-422","314:description:425-492","314:objective:1-85"},["minimumStage"]=2,["questID"]=314,["sourceHash"]="98f149351e76aeb892f2515d10cea7e0527e87d0f63cc810542461b40d795dac"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-803",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vagash’s attacks on the rams threatened the Amberstills’ livelihood, with the predator lurking above the ranch while outside military help was scarce.",["title"]="Amberstill Ranch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5056:description:1-93","5056:description:95-150","5056:description:152-253","5056:description:258-342","5056:description:344-391","5056:description:393-463","5056:description:468-505","5056:objective:1-75"},["minimumStage"]=2,["questID"]=5056,["sourceHash"]="621cf1b02ef3ef91000b1bc0c00d162a9811022630034156e62ecce1e27d4d9a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2241",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Great cats gathered around Frostsaber Rock in northern Winterspring under Shy-Rotam’s leadership. Her stone was the place Storm Shadowhoof named for the hunt’s offering.",["title"]="Frostsaber Rock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5088:description:1-106","5088:description:108-196","5088:description:201-291","5088:description:296-410","5088:description:412-447","5088:objective:1-13","5088:objective:15-116"},["minimumStage"]=2,["questID"]=5088,["sourceHash"]="ac0a01d2fd0fac3c2eab707f87b9653fc0ad62c212371806652c587788dfc159"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2097",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The sacred fire of life lay on an isolated needle at Darkcloud Pinnacle, at a place where the dead were buried. Magatha’s ritual directed the enchanted powder there.",["title"]="Darkcloud Pinnacle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1051:description:1-63","1051:description:65-109","1051:description:111-137","1051:description:142-176","1051:description:178-199","1051:description:201-245","1051:description:247-258","1051:description:263-272","1051:description:274-288","1051:description:293-380","1051:description:382-473","1051:description:478-500","1051:objective:1-70"},["minimumStage"]=2,["questID"]=1051,["sourceHash"]="aaaea25f5d1a6fcc8a71086f84e109cd81d62ddbcfdff82b8afa7ffbc4e03676"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2368",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Monika Sengutz lived in Tarren Mill, the destination Vorrel named for the wedding ring taken during his torture in the Scarlet Monastery.",["title"]="Tarren Mill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"475:description:1-44","475:description:49-158","475:description:161-283","475:description:288-344","475:description:347-500","475:objective:1-51"},["minimumStage"]=2,["questID"]=475,["sourceHash"]="75434eb6abd9ac836b269d56374c34cf47a92a0d0c15c83cf00f12fd4ebcb245"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2107",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gaerolas Talvethren was Great Warden to the sleeping Druids of the Talon in Ban’ethil, charged with protecting their hibernation and their pact with Ysera.",["title"]="Gaerolas Talvethren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"476:description:1-39","476:description:44-119","476:description:122-221","476:description:224-317","476:description:322-389","476:description:392-425","476:description:428-507","476:objective:1-42"},["minimumStage"]=2,["questID"]=476,["sourceHash"]="2e4adfcc0385abb257e5a0bfc5cf1107ce241325ddee2d5566e42ef130bd2f02"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2107",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gnarlpines ambushed Gaerolas on his way to Ban’ethil. Wounded too badly to return with his warning, he reported their attack on Starbreeze and the corruption spread by Ursal.",["title"]="Gaerolas Talvethren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"483:description:1-75","483:description:80-190","483:description:192-271","483:description:276-390","483:description:392-430","483:description:433-490","483:objective:1-82"},["minimumStage"]=2,["questID"]=483,["sourceHash"]="42cda196ce182c2136decd22ec3703b83e8d589d6d1ed44d0aca10b54232281a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2078",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Athridas Bearmantle sought the four Relics of Wakening so he could safely interrupt the druids’ hibernation before Gnarlpine invaders left them trapped in the Dream.",["title"]="Athridas Bearmantle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"476:description:1-39","476:description:44-119","476:description:122-221","476:description:224-317","476:description:322-389","476:description:392-425","476:description:428-507","476:objective:1-42"},["minimumStage"]=2,["questID"]=476,["sourceHash"]="2e4adfcc0385abb257e5a0bfc5cf1107ce241325ddee2d5566e42ef130bd2f02"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2039",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gaerolas named Ursal the Mauler as the Gnarlpine chieftain using Fel Moss’s evil power to drive the once peaceful furbolgs mad.",["title"]="Ursal the Mauler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2541:description:1-130","2541:description:132-258","2541:description:260-321","2541:description:326-342","2541:description:344-451","2541:description:453-480","2541:objective:1-73"},["minimumStage"]=2,["questID"]=2541,["sourceHash"]="3e100dbe798abf50c21113ca8b1a75cec8abe67e0bfd9a517fe426a5ed3fb8ae"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-7317",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Oben Rageclaw’s spirit was separated from his sleeping body by Gnarlpine shamans. They animated his physical form to attack intruders while he remained trapped in the Emerald Dream.",["title"]="Oben Rageclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2561:description:1-60","2561:description:62-93","2561:description:98-162","2561:description:164-203","2561:description:205-319","2561:description:324-386","2561:description:389-446","2561:description:448-503","2561:objective:1-81"},["minimumStage"]=2,["questID"]=2561,["sourceHash"]="0299d015823a9968d4102a27650ad46fc43e8152a5cf9d12b66dce739e471684"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7317",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After studying the shaman’s charm, Oben saw no escape from the Gnarlpines except the destruction of his soulless body and the use of the charm upon its remains.",["title"]="Oben Rageclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2438:description:1-119","2438:description:121-229","2438:description:234-316","2438:description:318-436","2438:description:441-500","2438:objective:1-66"},["minimumStage"]=2,["questID"]=2438,["sourceHash"]="19e132e756333dff364f21040effed5893c598d0ec9198cd0ca37cfa9c14a298"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3567",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tallonkai Swiftroot’s emerald dreamcatcher was a gift from Gaerolas, able to draw energy from the Dream. Its loss tied him to the abandoned possessions in Starbreeze Village.",["title"]="Tallonkai Swiftroot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2459:description:1-14","2459:description:16-29","2459:description:31-63","2459:description:68-139","2459:description:141-264","2459:description:266-335","2459:description:337-392","2459:description:397-424","2459:description:426-498","2459:objective:1-97"},["minimumStage"]=2,["questID"]=2459,["sourceHash"]="11af6e8aac175bf9cbc477a1253287762d0ed2af7cacff178935e1e84eed6dbf"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-7234",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Reports described Ferocitas the Dream Eater wearing a necklace that shone green at night; Tallonkai believed its jewel was the missing emerald from his damaged dreamcatcher.",["title"]="Ferocitas the Dream Eater"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2459:description:1-14","2459:description:16-29","2459:description:31-63","2459:description:68-139","2459:description:141-264","2459:description:266-335","2459:description:337-392","2459:description:397-424","2459:description:426-498","2459:objective:1-97"},["minimumStage"]=2,["questID"]=2459,["sourceHash"]="11af6e8aac175bf9cbc477a1253287762d0ed2af7cacff178935e1e84eed6dbf"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7234",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ferocitas led the Gnarlpine mystics north of Starbreeze Village, the band Tallonkai suspected of taking his dreamcatcher’s emerald.",["title"]="Ferocitas the Dream Eater"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"918:description:1-55","918:description:58-141","918:description:146-210","918:description:215-261","918:description:264-371","918:description:374-461","918:objective:1-53"},["minimumStage"]=2,["questID"]=918,["sourceHash"]="e8fcf02978bcd602bdce702c32e0441acc70bab3a0bef3e0963dd46c5e3bd28b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2080",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Denalan suspected the soil behind the timberlings’ growing anger and wanted their seeds to test methods developed through his work nurturing plants.",["title"]="Denalan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"918:description:1-55","918:description:58-141","918:description:146-210","918:description:215-261","918:description:264-371","918:description:374-461","918:objective:1-53"},["minimumStage"]=2,["questID"]=918,["sourceHash"]="e8fcf02978bcd602bdce702c32e0441acc70bab3a0bef3e0963dd46c5e3bd28b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Denalan described timberlings as nature elementals whose condition reflected the order of plant and animal life upon Teldrassil.",["title"]="Timberling"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"923:description:1-50","923:description:53-190","923:description:193-270","923:description:273-293","923:description:298-383","923:description:386-435","923:objective:1-56"},["minimumStage"]=2,["questID"]=923,["sourceHash"]="8cbbd2a1a722ba2c95d43464efeb99a3907b71e95fa6ee97c0dc75d7cbe782a9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3517",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rellian Greenspyre wanted the most corrupted timberlings removed from Wellspring Lake while the source of their malevolence remained under investigation.",["title"]="Rellian Greenspyre"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2518:description:1-39","2518:description:41-143","2518:description:145-218","2518:description:223-270","2518:description:272-321","2518:description:326-370","2518:description:372-445","2518:description:447-502","2518:objective:1-114"},["minimumStage"]=2,["questID"]=2518,["sourceHash"]="e8e8b5db0d2d3fbcc9ca2009530fc488325d85ed6fcd2ca42c43a40f2d312ed0"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-7319",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A’moora remembered Lady Sathrah as a graceful spider spinning silver threads through moonlight and gathering the evening mist in their web.",["title"]="Lady Sathrah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2518:description:1-39","2518:description:41-143","2518:description:145-218","2518:description:223-270","2518:description:272-321","2518:description:326-370","2518:description:372-445","2518:description:447-502","2518:objective:1-114"},["minimumStage"]=2,["questID"]=2518,["sourceHash"]="e8e8b5db0d2d3fbcc9ca2009530fc488325d85ed6fcd2ca42c43a40f2d312ed0"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-7319",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lady Sathrah’s silvery dew had once supplied the temple with a potent healing substance. Her descent into madness now endangered her future brood as well.",["title"]="Lady Sathrah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2518:description:1-39","2518:description:41-143","2518:description:145-218","2518:description:223-270","2518:description:272-321","2518:description:326-370","2518:description:372-445","2518:description:447-502","2518:objective:1-114"},["minimumStage"]=2,["questID"]=2518,["sourceHash"]="e8e8b5db0d2d3fbcc9ca2009530fc488325d85ed6fcd2ca42c43a40f2d312ed0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7313",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Priestess A’moora’s charge against Sathrah grew from sorrow over a creature once beloved of Elune. She wanted the suffering ended and the silvery spinnerets brought to the temple.",["title"]="Priestess A'moora"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"953:description:1-50","953:description:52-239","953:description:244-363","953:description:365-428","953:description:433-510","953:objective:1-113"},["minimumStage"]=2,["questID"]=953,["sourceHash"]="015dd1c09572e1ac775b637f19aa8d8644c7b48c6db91174c73f8b1b46d573b4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3639",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sentinel Tysha Moonblade had found two tablets recounting Ameth’Aran’s fall, but restless Highborne spirits drove her away before she could finish studying them.",["title"]="Sentinel Tysha Moonblade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"963:description:1-143","963:description:148-252","963:description:254-343","963:description:345-389","963:description:394-442","963:description:444-472","963:objective:1-99"},["minimumStage"]=2,["questID"]=963,["sourceHash"]="d328a7552bfcaa92f52e5c174e007eeb46fe2983032d9190dac75216eef75e91"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3644",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cerellean Whiteclaw had mourned Anaya since Ameth’Aran’s destruction near the time of the Well of Eternity’s battles. Thousands of years later he found her haunted spirit among the ruins.",["title"]="Cerellean Whiteclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"963:description:1-143","963:description:148-252","963:description:254-343","963:description:345-389","963:description:394-442","963:description:444-472","963:objective:1-99"},["minimumStage"]=2,["questID"]=963,["sourceHash"]="d328a7552bfcaa92f52e5c174e007eeb46fe2983032d9190dac75216eef75e91"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3644",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cerellean wanted Anaya released from her haunting but could not bring himself to destroy the spirit of the woman he still loved.",["title"]="Cerellean Whiteclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"963:description:1-143","963:description:148-252","963:description:254-343","963:description:345-389","963:description:394-442","963:description:444-472","963:objective:1-99"},["minimumStage"]=2,["questID"]=963,["sourceHash"]="d328a7552bfcaa92f52e5c174e007eeb46fe2983032d9190dac75216eef75e91"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3667",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anaya Dawnrunner was Cerellean Whiteclaw’s lost beloved, whose spirit he discovered in Ameth’Aran long after believing her dead.",["title"]="Anaya Dawnrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"957:description:1-106","957:description:108-221","957:description:223-265","957:description:270-296","957:objective:1-110"},["minimumStage"]=2,["questID"]=957,["sourceHash"]="c762bbd20452d4836b2705736e8a17ae2f8a7ceca131b94fbe60628591c954c8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3650",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Asterion’s prison depended on an Ancient Moonstone Seal fashioned through Highborne craft. He believed the blue flame still burning in neighboring Ameth’Aran could destroy it.",["title"]="Asterion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"947:description:1-96","947:description:99-189","947:description:194-294","947:description:297-385","947:description:390-429","947:description:432-497","947:objective:1-74"},["minimumStage"]=2,["questID"]=947,["sourceHash"]="b50ced2e576c0bacb7e405c54329de95f23989f617f041ea8298134a157d5cb1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3583",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Barithras Moonshade needed rare mushrooms from behind Cliffspring Falls for a potion, but the Ancients’ warning of evil there made him ask for scouting as well as gathering.",["title"]="Barithras Moonshade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4762:description:1-59","4762:description:62-141","4762:description:144-269","4762:description:274-343","4762:description:346-421","4762:description:424-452","4762:description:455-504","4762:objective:1-115","4762:objective:120-196"},["minimumStage"]=2,["questID"]=4762,["sourceHash"]="86a695beb4f205510af4889fdd3dadeb3613a37374e0fcd0c5b77d45128f82c3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3649",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thundris Windweaver feared corruption in the Cliffspring River would flow toward Auberdine. He suspected the Blackwoods upstream without treating them as the proven root of the taint.",["title"]="Thundris Windweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6122:description:1-211","6122:description:214-341","6122:description:346-407","6122:description:410-498","6122:objective:1-106","6122:objective:111-204"},["minimumStage"]=2,["questID"]=6122,["sourceHash"]="0c004012c5cbb47689bfb2c8cc7b9be6c15a382cd07fc41c59bc8a66c5e5f5d7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11802",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dendrite Starblaze suspected Cliffspring Falls, a principal drinking-water source, of carrying poison harmful to local deer and directed a sample to Alanndarian Nightsong.",["title"]="Dendrite Starblaze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"985:description:1-54","985:description:56-103","985:description:108-191","985:description:196-319","985:description:321-366","985:description:368-427","985:objective:1-84"},["minimumStage"]=2,["questID"]=985,["sourceHash"]="0f1f0c1d199ff92d8d8359b5a81bf193a58c41d7445918e837b29fb3d550212e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3693",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Terenthis regarded the Blackwood camp south of Auberdine as the largest immediate threat to its people, after earlier scouting revealed the furbolgs’ presence.",["title"]="Terenthis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6441:description:1-5","6441:description:7-118","6441:description:120-229","6441:description:234-364","6441:description:366-397","6441:description:399-429","6441:description:434-510","6441:objective:1-54"},["minimumStage"]=2,["questID"]=6441,["sourceHash"]="58b1d175ca29f7dc9d7430bed1e3d6624dcc5e44ffde6853cfeb07a720f83d71"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12724",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pixel saw profit in Ratchet’s demand for satyr horns and sought a hunter who could face the satyrs he was unable to challenge himself.",["title"]="Pixel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1035:description:1-54","1035:description:57-129","1035:description:132-179","1035:description:184-250","1035:description:252-280","1035:description:285-375","1035:description:378-428","1035:description:433-478","1035:objective:1-97"},["minimumStage"]=2,["questID"]=1035,["sourceHash"]="7eaa00de9e7c479a1d5f40838426695ea1973ce1ef2a53bc3bfc2fb241110b53"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3931",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Shadethicket Oracle was said to hoard the moonstones once gathered at Fallen Sky Lake, preventing Pelturas from obtaining the stone he hoped would restore Relara’s strength.",["title"]="Shadethicket Oracle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1033:description:1-109","1033:description:112-147","1033:description:150-234","1033:description:239-341","1033:description:344-394","1033:description:396-470","1033:objective:1-44"},["minimumStage"]=2,["questID"]=1033,["sourceHash"]="a8aa3e76b0a64cf96dbe02f974fc86df0abe4df87fc83ccd3d851dde361e2264"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3894",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pelturas sought Elune’s Tear for his daughter Relara after the first remedy only slowed her illness, following Orendil’s advice toward the island in Iris Lake.",["title"]="Pelturas Whitemoon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"827:description:6-83","827:description:86-175","827:description:180-263","827:description:266-335","827:description:340-416","827:description:419-469","827:objective:1-55","827:objective:60-92"},["minimumStage"]=2,["questID"]=827,["sourceHash"]="1fbe49fd85177385f2cb33fa91b425982780e5bb4ec8755df945ff79a45e3301"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3208",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Margoz wanted Searing Collars from Skull Rock to test his belief that the Burning Blade used the painful implements to attune themselves to demonic power.",["title"]="Margoz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"826:description:1-62","826:description:65-103","826:description:108-210","826:description:215-233","826:description:238-312","826:description:315-374","826:objective:1-16","826:objective:21-60","826:objective:65-96"},["minimumStage"]=2,["questID"]=826,["sourceHash"]="a69ba6903cf8683881ed2ee7b5b33b9f5cc1e7219d493a111d68fa6949f0be85"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3205",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zalazane ruled from the Echo Isles, sending hexed former Darkspear trolls to the mainland to bring more people under his control, in Master Gadrin’s account.",["title"]="Zalazane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"808:description:1-69","808:description:74-141","808:description:143-157","808:description:162-201","808:description:203-274","808:description:276-362","808:description:364-419","808:description:424-434","808:description:436-481","808:description:483-497","808:description:502-510","808:objective:1-69","808:objective:74-118"},["minimumStage"]=2,["questID"]=808,["sourceHash"]="2b33574e28a906d70d81d352b30f5bc7c36a5f6425a308f0f56901c85302242e"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-3188",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Master Gadrin believed his dead brother Minshina’s spirit remained imprisoned by Zalazane within a skull on the largest Echo Isle, and sought its recovery to free him.",["title"]="Master Gadrin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"806:description:1-56","806:description:59-105","806:description:110-266","806:description:269-314","806:description:319-369","806:objective:1-53"},["minimumStage"]=2,["questID"]=806,["sourceHash"]="8355bfd2ec9fcbf184ea7d8df15c260e17bb30290c9340a65a8d857e19506da9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3203",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Orgnil Soulscar identified Fizzle Darkstorm as a Burning Blade goblin warlock spreading chaos with cult followers from a camp in Thunder Ridge.",["title"]="Fizzle Darkstorm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"806:description:1-56","806:description:59-105","806:description:110-266","806:description:269-314","806:description:319-369","806:objective:1-53"},["minimumStage"]=2,["questID"]=806,["sourceHash"]="8355bfd2ec9fcbf184ea7d8df15c260e17bb30290c9340a65a8d857e19506da9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-3142",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Orgnil Soulscar’s investigation of Fizzle’s camp led him to demand action before the Burning Blade could establish a stronger foothold in Durotar.",["title"]="Orgnil Soulscar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"825:description:1-157","825:description:162-296","825:description:298-364","825:description:366-425","825:description:430-506","825:objective:1-93"},["minimumStage"]=2,["questID"]=825,["sourceHash"]="f3d300e92d95dae8e276988d91548bc9eb3aa22d0ca8f849d2940e48469517ac"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3139",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gar’Thok sought gnomish tools from Proudmoore’s wrecked fleet to understand the Alliance’s mechanical knowledge and put that knowledge to use for his people.",["title"]="Gar'Thok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"896:description:1-92","896:description:94-169","896:description:174-284","896:description:286-347","896:description:349-486","896:objective:1-57","896:objective:59-117"},["minimumStage"]=2,["questID"]=896,["sourceHash"]="913e76d2b3053473cb81ee53c29ef2cfd1bfb8f63ef5880bd76953676545d9ad"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3453",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wharfmaster Dizzywig’s interest in the Boulder Lode emerald grew from Ratchet’s trade with Booty Bay and buyers he believed would pay for an unusually large gem.",["title"]="Wharfmaster Dizzywig"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"924:description:1-57","924:description:59-126","924:description:131-232","924:description:237-318","924:description:320-363","924:description:365-394","924:description:396-447","924:description:452-508","924:objective:1-26","924:objective:29-109"},["minimumStage"]=2,["questID"]=924,["sourceHash"]="bb14e3a38d2959dec0778ebe96fe8967905e13073f1f2f900cc39e5a5eee5c47"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3521",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ak’Zeloth prepared short-lived power stones to disrupt the Demon Seed’s connection with the Legion at Dreadmist Peak’s altar of fire.",["title"]="Ak'Zeloth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6462:description:1-145","6462:description:148-167","6462:description:172-259","6462:description:262-320","6462:description:323-367","6462:description:372-404","6462:description:407-505","6462:objective:1-57"},["minimumStage"]=2,["questID"]=6462,["sourceHash"]="cab399a968df07047bd8a7746b051ba320578000cdcd129e1e908015f4f16891"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12721",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mitsuwa mourned kin killed by Thistlefur attackers on the way to Zoram’gar and wanted their sacred troll charms recovered from the furbolgs’ chests.",["title"]="Mitsuwa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6421:description:1-38","6421:description:40-79","6421:description:84-141","6421:description:143-214","6421:description:216-312","6421:description:315-368","6421:description:373-446","6421:objective:1-135"},["minimumStage"]=2,["questID"]=6421,["sourceHash"]="869c6c3f3c44aed61f477f4f96bffcadbf4c74dc96da369c68fac90c27f56f43"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11861",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mor’rogal sought samples of the rare Resonite being mined by Boulderslide’s kobolds, together with a report on the cave’s depths to understand what troubled Stonetalon.",["title"]="Mor'rogal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1057:description:1-80","1057:description:85-145","1057:description:147-208","1057:description:210-264","1057:description:269-360","1057:description:362-460","1057:description:465-499","1057:objective:1-147"},["minimumStage"]=2,["questID"]=1057,["sourceHash"]="5a0f2b26705a03f82bc6bb3de0a8e5c4012a6754dec8f46b2beb587743ab8635"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3994",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keeper Albagorm wanted the Bloodfury harpies driven from the burned Charred Vale so that those protecting the forest could begin its regrowth.",["title"]="Keeper Albagorm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6393:description:1-101","6393:description:103-228","6393:description:233-331","6393:description:333-386","6393:description:388-422","6393:objective:1-53"},["minimumStage"]=2,["questID"]=6393,["sourceHash"]="a10d52f7a08ac19767464b2e89ae503d8c56e1fb8497f8bd5cf74aaf045a2a14"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11862",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tsunaman carried the Tribunal of the Tides’ campaign against Stonetalon’s fire elementals, seeking Incendrites as proof of attacks on those in the Charred Vale.",["title"]="Tsunaman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6283:description:1-60","6283:description:62-146","6283:description:151-199","6283:description:201-248","6283:description:253-328","6283:description:330-392","6283:objective:1-108"},["minimumStage"]=2,["questID"]=6283,["sourceHash"]="b5e5ba5c12d9a88d9964db924d9ed1476cf37466f23a543d01bc96d8d40bb205"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12579",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bloodfury Ripper was the harpies’ queen-like leader in the Charred Vale, placed by Maggran along the western hills.",["title"]="Bloodfury Ripper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"475:description:1-44","475:description:49-158","475:description:161-283","475:description:288-344","475:description:347-500","475:objective:1-51"},["minimumStage"]=2,["questID"]=475,["sourceHash"]="75434eb6abd9ac836b269d56374c34cf47a92a0d0c15c83cf00f12fd4ebcb245"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-262",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ban’ethil sheltered hibernating Druids of the Talon under Great Warden Gaerolas Talvethren, whose charge protected their safety and their pact with Ysera.",["title"]="Ban'ethil Barrow Den"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"483:description:1-75","483:description:80-190","483:description:192-271","483:description:276-390","483:description:392-430","483:description:433-490","483:objective:1-82"},["minimumStage"]=2,["questID"]=483,["sourceHash"]="42cda196ce182c2136decd22ec3703b83e8d589d6d1ed44d0aca10b54232281a"}},["questSourceProofsMode"]="ALL"},["field"]="stakes",["id"]="catalog-location-area-262",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gnarlpine raids threatened the sleepers within Ban’ethil. The four Relics of Wakening were needed to break the hibernation ritual safely before the druids were lost in the Dream.",["title"]="Ban'ethil Barrow Den"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"476:description:1-39","476:description:44-119","476:description:122-221","476:description:224-317","476:description:322-389","476:description:392-425","476:description:428-507","476:objective:1-42"},["minimumStage"]=2,["questID"]=476,["sourceHash"]="2e4adfcc0385abb257e5a0bfc5cf1107ce241325ddee2d5566e42ef130bd2f02"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-260",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Starbreeze’s pillaging followed the Gnarlpines’ corruption under Ursal the Mauler. Gaerolas’s injuries kept the warning from reaching Dolanaar without another messenger.",["title"]="Starbreeze Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2438:description:1-119","2438:description:121-229","2438:description:234-316","2438:description:318-436","2438:description:441-500","2438:objective:1-66"},["minimumStage"]=2,["questID"]=2438,["sourceHash"]="19e132e756333dff364f21040effed5893c598d0ec9198cd0ca37cfa9c14a298"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-260",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tallonkai’s dreamcatcher remained in a dresser within Starbreeze after furbolg corruption overtook the once tranquil village.",["title"]="Starbreeze Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"918:description:1-55","918:description:58-141","918:description:146-210","918:description:215-261","918:description:264-371","918:description:374-461","918:objective:1-53"},["minimumStage"]=2,["questID"]=918,["sourceHash"]="e8fcf02978bcd602bdce702c32e0441acc70bab3a0bef3e0963dd46c5e3bd28b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-259",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The timberlings around Lake Al’Ameth supplied the seeds Denalan wanted for his work on the growing anger of Teldrassil’s nature elementals.",["title"]="Lake Al'Ameth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"923:description:1-50","923:description:53-190","923:description:193-270","923:description:273-293","923:description:298-383","923:description:386-435","923:objective:1-56"},["minimumStage"]=2,["questID"]=923,["sourceHash"]="8cbbd2a1a722ba2c95d43464efeb99a3907b71e95fa6ee97c0dc75d7cbe782a9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rellian identified the timberlings around northern Wellspring Lake as especially tainted, carrying mossy tumors he wanted collected and burned.",["title"]="Wellspring Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2518:description:1-39","2518:description:41-143","2518:description:145-218","2518:description:223-270","2518:description:272-321","2518:description:326-370","2518:description:372-445","2518:description:447-502","2518:objective:1-114"},["minimumStage"]=2,["questID"]=2518,["sourceHash"]="e8e8b5db0d2d3fbcc9ca2009530fc488325d85ed6fcd2ca42c43a40f2d312ed0"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lady Sathrah’s dwelling near the northern lake connected Wellspring to A’moora’s account of healing silver dew and the spider’s later madness.",["title"]="Wellspring Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"934:description:1-42","934:description:44-234","934:description:239-276","934:description:278-348","934:description:350-431","934:description:433-479","934:objective:1-76"},["minimumStage"]=2,["questID"]=934,["sourceHash"]="2c50ed0b1042f32ab8d4d3b6e89dddc3a1a235a0ee9e09df053192967815212a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-264",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Oracle Glade held the first and most powerful moonwell beneath the Oracle Tree’s boughs, the last well named in Corithras’s series of water-gathering charges.",["title"]="The Oracle Glade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"953:description:1-50","953:description:52-239","953:description:244-363","953:description:365-428","953:description:433-510","953:objective:1-113"},["minimumStage"]=2,["questID"]=953,["sourceHash"]="015dd1c09572e1ac775b637f19aa8d8644c7b48c6db91174c73f8b1b46d573b4"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-15821",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ameth’Aran had been a place where Azshara’s servants practiced powerful magic. Its ruined walls now held restless Highborne spirits and tablets recounting the settlement’s fall.",["title"]="Ameth'Aran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"957:description:1-106","957:description:108-221","957:description:223-265","957:description:270-296","957:objective:1-110"},["minimumStage"]=2,["questID"]=957,["sourceHash"]="c762bbd20452d4836b2705736e8a17ae2f8a7ceca131b94fbe60628591c954c8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-15821",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="An ancient blue flame persisted in Ameth’Aran, the southern twin of Bashal’Aran; Asterion believed it could break the seal that imprisoned him.",["title"]="Ameth'Aran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"957:description:1-106","957:description:108-221","957:description:223-265","957:description:270-296","957:objective:1-110"},["minimumStage"]=2,["questID"]=957,["sourceHash"]="c762bbd20452d4836b2705736e8a17ae2f8a7ceca131b94fbe60628591c954c8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-446",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bashal’Aran’s trapped Asterion depended on an ancient flame in its twin ruins, Ameth’Aran, to destroy the Highborne seal forming his prison.",["title"]="Bashal'Aran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"951:description:1-97","951:description:100-272","951:description:277-391","951:description:394-496","951:objective:1-61"},["minimumStage"]=2,["questID"]=951,["sourceHash"]="3c56ec6118af122803d2f336579a713db1b2422b4baa26f8f0abde0207b46235"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-443",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ancient relics lay among Mathystra’s grass and broken stones, remnants Onu hoped could illuminate the Twilight’s Hammer’s use of elven magic.",["title"]="Ruins of Mathystra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"951:description:1-97","951:description:100-272","951:description:277-391","951:description:394-496","951:objective:1-61"},["minimumStage"]=2,["questID"]=951,["sourceHash"]="3c56ec6118af122803d2f336579a713db1b2422b4baa26f8f0abde0207b46235"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-443",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Study of Mathystra’s relics was meant to clarify a cursed elven text recovered at the Master’s Glaive and the cult’s attempt to bring back its ancient masters.",["title"]="Ruins of Mathystra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"949:description:1-68","949:description:71-90","949:description:95-136","949:description:138-194","949:description:199-255","949:objective:1-65"},["minimumStage"]=2,["questID"]=949,["sourceHash"]="484d6dc8a257c00e253213666d7452d6858873c6c75e7ae7ab5b60a5b4456521"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-15820",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Twilight’s Hammer cultists camped at the Master’s Glaive. Onu sought a clue there because their precise purpose was still unknown.",["title"]="The Master's Glaive"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6122:description:1-211","6122:description:214-341","6122:description:346-407","6122:description:410-498","6122:objective:1-106","6122:objective:111-204"},["minimumStage"]=2,["questID"]=6122,["sourceHash"]="0c004012c5cbb47689bfb2c8cc7b9be6c15a382cd07fc41c59bc8a66c5e5f5d7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-445",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cliffspring Falls supplied drinking water for the region, but suspected poison and naga in a nearby cave made its waters a concern for the druids seeking to aid Darkshore’s deer.",["title"]="Cliffspring Falls"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"947:description:1-96","947:description:99-189","947:description:194-294","947:description:297-385","947:description:390-429","947:description:432-497","947:objective:1-74"},["minimumStage"]=2,["questID"]=947,["sourceHash"]="b50ced2e576c0bacb7e405c54329de95f23989f617f041ea8298134a157d5cb1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-445",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The cave behind the falls held the rare mushrooms Barithras wanted, along with a danger the Grove of the Ancients had warned him to avoid.",["title"]="Cliffspring Falls"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4762:description:1-59","4762:description:62-141","4762:description:144-269","4762:description:274-343","4762:description:346-421","4762:description:424-452","4762:description:455-504","4762:objective:1-115","4762:objective:120-196"},["minimumStage"]=2,["questID"]=4762,["sourceHash"]="86a695beb4f205510af4889fdd3dadeb3613a37374e0fcd0c5b77d45128f82c3"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-456",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The first waterfall inland from the river mouth fed a pool beneath a bridge, the place Thundris named for drawing his water sample.",["title"]="Cliffspring River"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4762:description:1-59","4762:description:62-141","4762:description:144-269","4762:description:274-343","4762:description:346-421","4762:description:424-452","4762:description:455-504","4762:objective:1-115","4762:objective:120-196"},["minimumStage"]=2,["questID"]=4762,["sourceHash"]="86a695beb4f205510af4889fdd3dadeb3613a37374e0fcd0c5b77d45128f82c3"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-456",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fouling of the Cliffspring River threatened to carry corruption into Mist’s Edge and toward Auberdine; the Blackwoods upstream were a suspicion still requiring investigation.",["title"]="Cliffspring River"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6441:description:1-5","6441:description:7-118","6441:description:120-229","6441:description:234-364","6441:description:366-397","6441:description:399-429","6441:description:434-510","6441:objective:1-54"},["minimumStage"]=2,["questID"]=6441,["sourceHash"]="58b1d175ca29f7dc9d7430bed1e3d6624dcc5e44ffde6853cfeb07a720f83d71"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-16007",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Satyrnaar was one of three Ashenvale satyr haunts whose horns Pixel believed could meet Ratchet’s demand, alongside Night Run and Xavian.",["title"]="Satyrnaar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1035:description:1-54","1035:description:57-129","1035:description:132-179","1035:description:184-250","1035:description:252-280","1035:description:285-375","1035:description:378-428","1035:description:433-478","1035:objective:1-97"},["minimumStage"]=2,["questID"]=1035,["sourceHash"]="7eaa00de9e7c479a1d5f40838426695ea1973ce1ef2a53bc3bfc2fb241110b53"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-422",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Shadethickets’ arrival stopped the old gathering of moonstones at Fallen Sky Lake. Their Oracle was said to have hoarded the stones Pelturas needed for Relara.",["title"]="Fallen Sky Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1033:description:1-109","1033:description:112-147","1033:description:150-234","1033:description:239-341","1033:description:344-394","1033:description:396-470","1033:objective:1-44"},["minimumStage"]=2,["questID"]=1033,["sourceHash"]="a8aa3e76b0a64cf96dbe02f974fc86df0abe4df87fc83ccd3d851dde361e2264"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="iris-lake",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The island in Iris Lake was the only place Pelturas knew to obtain Elune’s Tear, a stone Orendil recommended against Relara’s corruption.",["title"]="Iris Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"827:description:6-83","827:description:86-175","827:description:180-263","827:description:266-335","827:description:340-416","827:description:419-469","827:objective:1-55","827:objective:60-92"},["minimumStage"]=2,["questID"]=827,["sourceHash"]="1fbe49fd85177385f2cb33fa91b425982780e5bb4ec8755df945ff79a45e3301"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-817",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Burning Blade used Skull Rock, east of Orgrimmar, for rituals involving Searing Collars. Margoz sought the collars to investigate their connection to demonic power.",["title"]="Skull Rock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"826:description:1-62","826:description:65-103","826:description:108-210","826:description:215-233","826:description:238-312","826:description:315-374","826:objective:1-16","826:objective:21-60","826:objective:65-96"},["minimumStage"]=2,["questID"]=826,["sourceHash"]="a69ba6903cf8683881ed2ee7b5b33b9f5cc1e7219d493a111d68fa6949f0be85"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-368",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Echo Isles had been home to the Darkspears before Zalazane’s control. His followers were described as former Darkspear trolls turned against their people.",["title"]="Echo Isles"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"808:description:1-69","808:description:74-141","808:description:143-157","808:description:162-201","808:description:203-274","808:description:276-362","808:description:364-419","808:description:424-434","808:description:436-481","808:description:483-497","808:description:502-510","808:objective:1-69","808:objective:74-118"},["minimumStage"]=2,["questID"]=808,["sourceHash"]="2b33574e28a906d70d81d352b30f5bc7c36a5f6425a308f0f56901c85302242e"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-368",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A circle of power on the largest Echo Isle held skulls in Zalazane’s ritual, including the skull in which Gadrin believed his brother Minshina’s spirit was trapped.",["title"]="Echo Isles"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"784:description:1-171","784:description:176-233","784:description:235-367","784:description:369-411","784:description:416-499","784:objective:1-108"},["minimumStage"]=2,["questID"]=784,["sourceHash"]="ca5b88ff3293c6498ee9dff10420c5c4490039bd20bed115299143157ef55f33"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-372",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tiragarde fell when Proudmoore’s aggression was repelled, but Lieutenant Benedict later led the Admiral’s reserve forces back into the keep, renewing the threat to Durotar.",["title"]="Tiragarde Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"825:description:1-157","825:description:162-296","825:description:298-364","825:description:366-425","825:description:430-506","825:objective:1-93"},["minimumStage"]=2,["questID"]=825,["sourceHash"]="f3d300e92d95dae8e276988d91548bc9eb3aa22d0ca8f849d2940e48469517ac"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-372",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Proudmoore’s wrecked ships remained off the coast east of Tiragarde, where Gar’Thok’s scouts reported tools that might reveal Alliance mechanical knowledge.",["title"]="Tiragarde Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"806:description:1-56","806:description:59-105","806:description:110-266","806:description:269-314","806:description:319-369","806:objective:1-53"},["minimumStage"]=2,["questID"]=806,["sourceHash"]="8355bfd2ec9fcbf184ea7d8df15c260e17bb30290c9340a65a8d857e19506da9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-369",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fizzle Darkstorm and Burning Blade followers camped within Thunder Ridge northwest of Razor Hill, the target of Orgnil Soulscar’s investigation.",["title"]="Thunder Ridge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"896:description:1-92","896:description:94-169","896:description:174-284","896:description:286-347","896:description:349-486","896:objective:1-57","896:objective:59-117"},["minimumStage"]=2,["questID"]=896,["sourceHash"]="913e76d2b3053473cb81ee53c29ef2cfd1bfb8f63ef5880bd76953676545d9ad"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-381",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Boulder Lode was the Venture Company mine northeast of the Sludge Fen where reports of a fist-sized emerald attracted Wharfmaster Dizzywig’s commercial interest.",["title"]="Boulder Lode Mine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"924:description:1-57","924:description:59-126","924:description:131-232","924:description:237-318","924:description:320-363","924:description:365-394","924:description:396-447","924:description:452-508","924:objective:1-26","924:objective:29-109"},["minimumStage"]=2,["questID"]=924,["sourceHash"]="bb14e3a38d2959dec0778ebe96fe8967905e13073f1f2f900cc39e5a5eee5c47"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-384",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A cave on Dreadmist Peak held the Demon Seed above an altar of fire. Ak’Zeloth wanted its connection to the Legion disrupted with prepared power stones.",["title"]="Dreadmist Peak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6127:description:1-130","6127:description:133-203","6127:description:206-279","6127:description:284-356","6127:description:359-419","6127:description:422-509","6127:objective:1-98","6127:objective:103-190"},["minimumStage"]=2,["questID"]=6127,["sourceHash"]="0ebfda682c29c786c6eeb87226dbc5c5a422e0170faf39e2882c2a9540b15b70"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-384",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pools near Dreadmist’s airy summit were thought to influence surrounding weather; Dendrite suspected their water had been tainted by the Burning Blade.",["title"]="Dreadmist Peak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"894:description:1-107","894:description:109-249","894:description:254-288","894:description:290-364","894:description:369-502","894:objective:1-64"},["minimumStage"]=2,["questID"]=894,["sourceHash"]="512d640a04d23a32695c5547dd2ca7440998d9528de7bf508d038e43491351e0"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-382",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A Venture Company research facility southwest of the Sludge Fen experimented with a samophlange, drawing interest from those who wanted to examine the unfamiliar device.",["title"]="The Sludge Fen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"216:description:1-248","216:objective:1-115"},["minimumStage"]=2,["questID"]=216,["sourceHash"]="9502ed671cfcbc1428d4ff7a49b576da55375e2ad1dafa7325e536135a88fdef"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2301",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/216",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thistlefur Village blocked a route between Zoram’gar and Splintertree that would bypass Astranaar, making the furbolg settlement a target of Horde expansion.",["title"]="Thistlefur Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6462:description:1-145","6462:description:148-167","6462:description:172-259","6462:description:262-320","6462:description:323-367","6462:description:372-404","6462:description:407-505","6462:objective:1-57"},["minimumStage"]=2,["questID"]=6462,["sourceHash"]="cab399a968df07047bd8a7746b051ba320578000cdcd129e1e908015f4f16891"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2301",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thistlefur Hold lay at the village’s far end. Mitsuwa’s stolen troll charms were reported in chests inside that cave, north of Astranaar.",["title"]="Thistlefur Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6421:description:1-38","6421:description:40-79","6421:description:84-141","6421:description:143-214","6421:description:216-312","6421:description:315-368","6421:description:373-446","6421:objective:1-135"},["minimumStage"]=2,["questID"]=6421,["sourceHash"]="869c6c3f3c44aed61f477f4f96bffcadbf4c74dc96da369c68fac90c27f56f43"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-3157",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kobolds in the deep Boulderslide cave mined Resonite with an urgency that worried Mor’rogal. His requested samples and scouting were meant to explain the disturbance.",["title"]="Boulderslide Cavern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6421:description:1-38","6421:description:40-79","6421:description:84-141","6421:description:143-214","6421:description:216-312","6421:description:315-368","6421:description:373-446","6421:objective:1-135"},["minimumStage"]=2,["questID"]=6421,["sourceHash"]="869c6c3f3c44aed61f477f4f96bffcadbf4c74dc96da369c68fac90c27f56f43"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2540",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Boulderslide Ravine held the deep cave where kobolds mined rare Resonite, southeast of the position from which Mor’rogal directed the investigation.",["title"]="Boulderslide Ravine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1057:description:1-80","1057:description:85-145","1057:description:147-208","1057:description:210-264","1057:description:269-360","1057:description:362-460","1057:description:465-499","1057:objective:1-147"},["minimumStage"]=2,["questID"]=1057,["sourceHash"]="5a0f2b26705a03f82bc6bb3de0a8e5c4012a6754dec8f46b2beb587743ab8635"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-465",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keeper Albagorm blamed an industrial army’s greed for the burning of the Charred Vale. Bloodfury occupation then blocked access for efforts to begin regrowth.",["title"]="The Charred Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6393:description:1-101","6393:description:103-228","6393:description:233-331","6393:description:333-386","6393:description:388-422","6393:objective:1-53"},["minimumStage"]=2,["questID"]=6393,["sourceHash"]="a10d52f7a08ac19767464b2e89ae503d8c56e1fb8497f8bd5cf74aaf045a2a14"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-465",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Charred Vale’s fire elementals became a target of Tsunaman’s campaign for the Tribunal of the Tides and Neptulon.",["title"]="The Charred Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6283:description:1-60","6283:description:62-146","6283:description:151-199","6283:description:201-248","6283:description:253-328","6283:description:330-392","6283:objective:1-108"},["minimumStage"]=2,["questID"]=6283,["sourceHash"]="b5e5ba5c12d9a88d9964db924d9ed1476cf37466f23a543d01bc96d8d40bb205"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-465",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bloodfury Ripper led the harpies from the Vale’s western hills; Maggran believed striking at their queen-like leader would weaken the flock.",["title"]="The Charred Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"369:description:1-153","369:description:156-268","369:description:273-352","369:description:355-442","369:description:445-509","369:objective:1-113"},["minimumStage"]=2,["questID"]=369,["sourceHash"]="1afb471e5cba60be8cb9d011af0a99fe663993e303ec054c420e9d64993e1c50"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1518",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Apothecary Johaan's old tomes described an ancient plague preserved in Night Web spider venom. He sought fresh venom to test its contagious element in a new concoction, rather than treating the experiment as an established success.",["title"]="Apothecary Johaan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"363:description:1-23","363:description:25-111","363:description:116-168","363:description:170-211","363:description:216-330","363:objective:1-32"},["minimumStage"]=2,["questID"]=363,["sourceHash"]="61a13f0010c399131204716385c754bc6421e06020ace516ca23c3d3e6ea651f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mordo tended Deathknell's crypt, watching newly awakened undead before directing those freed from the Lich King's control to Shadow Priest Sarvis.",["title"]="Undertaker Mordo"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"382:description:1-151","382:description:153-238","382:description:240-306","382:description:311-362","382:description:364-430","382:objective:1-111"},["minimumStage"]=2,["questID"]=382,["sourceHash"]="ad774deacfcd9f660bffe652c669491590f546d8262719991decf2eab8dc475a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1667",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Meven Korgal was the Scarlet messenger Executor Arren's reports placed at the Crusader camp near Deathknell, carrying information dispatched from the Scarlet Monastery.",["title"]="Meven Korgal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"382:description:1-151","382:description:153-238","382:description:240-306","382:description:311-362","382:description:364-430","382:objective:1-111"},["minimumStage"]=2,["questID"]=382,["sourceHash"]="ad774deacfcd9f660bffe652c669491590f546d8262719991decf2eab8dc475a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="reviewed-executor-arren",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Executor Arren sought the Scarlet messenger's documents on orders reported from Brill. Their contents were still unknown when he sent someone to intercept the courier.",["title"]="Executor Arren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"383:description:1-70","383:description:72-155","383:description:157-315","383:description:320-357","383:description:359-419","383:description:421-463","383:description:465-508","383:objective:1-66"},["minimumStage"]=2,["questID"]=383,["sourceHash"]="e22955a51cd4281cfad785606a12bcce68a29494f75e0d4a3440fc23409445ce"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="reviewed-executor-arren",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Arren answered to Executor Zygand in Brill. Intelligence recovered around Deathknell was to pass to that superior for action against the Scarlet Crusade.",["title"]="Executor Arren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6395:description:1-144","6395:description:149-229","6395:description:232-330","6395:description:335-409","6395:description:412-503","6395:objective:1-75"},["minimumStage"]=2,["questID"]=6395,["sourceHash"]="5cedea796feaa87c4a50e81f94375830d7074ec84a936792d46f70b9cfb04636"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1661",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Novice Elreth remembered her friend Marla Fipps's dying wish to share a grave with Samuel, the husband who had killed her after the plague left him mindless.",["title"]="Novice Elreth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6395:description:1-144","6395:description:149-229","6395:description:232-330","6395:description:335-409","6395:description:412-503","6395:objective:1-75"},["minimumStage"]=2,["questID"]=6395,["sourceHash"]="5cedea796feaa87c4a50e81f94375830d7074ec84a936792d46f70b9cfb04636"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1919",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Samuel Fipps succumbed to the plague and joined the Scourge. Elreth's account said that he then killed his wife Marla, whose last wish was burial beside him.",["title"]="Samuel Fipps"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6395:description:1-144","6395:description:149-229","6395:description:232-330","6395:description:335-409","6395:description:412-503","6395:objective:1-75"},["minimumStage"]=2,["questID"]=6395,["sourceHash"]="5cedea796feaa87c4a50e81f94375830d7074ec84a936792d46f70b9cfb04636"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1919",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Samuel Fipps was reported roaming a ruined camp beside the road northeast of Deathknell; Marla's grave lay in the first row of Deathknell's graveyard.",["title"]="Samuel Fipps"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"426:description:1-59","426:description:62-125","426:description:130-156","426:description:159-201","426:description:206-221","426:description:224-334","426:description:339-380","426:description:383-456","426:description:459-504","426:objective:1-91"},["minimumStage"]=2,["questID"]=426,["sourceHash"]="457ab3525968e573cd5eeaa822e57fa45b6e6a60b41a4ecb3411c5c0167f5344"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1496",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Deathguard Dillinger feared that a Scourge base at Agamand Mills would support further attacks across Tirisfal. The bones and skulls he requested were proof of action against that foothold.",["title"]="Deathguard Dillinger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"362:description:1-114","362:description:117-197","362:description:202-301","362:description:304-384","362:description:389-455","362:description:458-503","362:objective:1-77"},["minimumStage"]=2,["questID"]=362,["sourceHash"]="288b7cb0ef0d616cd6a444bd7ac0f036c4c4fa71d84858ace6f9478134add1e0"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-1657",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Coleman Farthing contrasted the Agamand brothers in life: Thurman was tall and gentle, while younger Devlin was physically weak and sharp-tongued.",["title"]="Devlin Agamand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"362:description:1-114","362:description:117-197","362:description:202-301","362:description:304-384","362:description:389-455","362:description:458-503","362:objective:1-77"},["minimumStage"]=2,["questID"]=362,["sourceHash"]="288b7cb0ef0d616cd6a444bd7ac0f036c4c4fa71d84858ace6f9478134add1e0"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1657",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Devlin Agamand fell to the plague with the mills. Coleman described his mad chattering along the approach road and wanted his remains collected with those of the family.",["title"]="Devlin Agamand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"354:description:1-69","354:description:72-118","354:description:123-252","354:description:255-302","354:description:307-357","354:description:360-399","354:description:404-471","354:description:474-511","354:objective:1-91"},["minimumStage"]=2,["questID"]=354,["sourceHash"]="11ffa69f5957ec55cc1834bae4f2ac052b7bd3e6d9beb6e542e4ed19c56b044c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1500",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Coleman Farthing had worked the Agamands' mills in life. He blamed their decision to fortify the family home and keep their workers defending it for the undeath that followed.",["title"]="Coleman Farthing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1821:description:1-82","1821:description:85-158","1821:description:163-208","1821:description:211-314","1821:description:317-333","1821:description:338-451","1821:objective:1-127"},["minimumStage"]=2,["questID"]=1821,["sourceHash"]="4ac9a1c246dd93ebd551233786fcfb9f7ab5c9f018f7ce52da7ed9820df09351"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1500",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Farthing's resentment extended to the Agamands' surviving honor and possessions. He demanded four family weapons from their crypt after seeking the family's remains.",["title"]="Coleman Farthing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"408:description:1-61","408:description:64-199","408:description:202-294","408:description:299-337","408:description:340-414","408:description:419-460","408:objective:1-49","408:objective:54-124"},["minimumStage"]=2,["questID"]=408,["sourceHash"]="c5872f4277712947be70f3a0f9f3eb136b08038928e6a7dafff14a910262f653"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1658",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Captain Dargol was the skeletal local commander headquartered in the Agamand Family Crypt. Magistrate Sevren accused him of raising the family's ancestors for the Scourge's forces.",["title"]="Captain Dargol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"358:description:1-165","358:description:172-334","358:description:337-359","358:description:364-504","358:objective:1-49","358:objective:56-110"},["minimumStage"]=2,["questID"]=358,["sourceHash"]="7c3638dc209abb8f3c3dda4bb2e067720eca598ab527860c47646dfcd8ed7474"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1499",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magistrate Sevren wanted the mass graves protected from Rot Hide corpse thieves, fearing the dead would be raised to strengthen the Scourge.",["title"]="Magistrate Sevren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"398:description:1-19","398:description:24-137","398:description:140-221","398:description:224-310","398:description:315-407","398:description:410-470","398:description:475-496","398:objective:1-81"},["minimumStage"]=2,["questID"]=398,["sourceHash"]="9e398b2840862bf0f2aac63e44bc2a8a0ceeb17b32c71a2a9a5f12596327600b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1753",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brill's wanted notice accused Maggot Eye of stealing corpses for the Lich King's army. It placed the gnoll near Garren's Haunt and offered a reward through Executor Zygand.",["title"]="Maggot Eye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"442:description:1-86","442:description:91-148","442:description:151-166","442:description:171-218","442:description:221-238","442:objective:1-60"},["minimumStage"]=2,["questID"]=442,["sourceHash"]="94c55ed092fb0f61aee40236b548a533b1d33c70ffc4c89203a116bf0e148ca8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1952",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="High Executor Hadrec identified Fenris Isle as a Scourge stronghold in Silverpine and made Thule Ravenclaw the target of his planned assault.",["title"]="High Executor Hadrec"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"443:description:1-96","443:description:99-198","443:description:203-307","443:description:310-375","443:objective:1-75"},["minimumStage"]=2,["questID"]=443,["sourceHash"]="29ecd187696965b4b79e5dd1bbda3841db6d1b36b6f015b5f9432b28e3df2e56"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-1937",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Apothecary Renferrel was assigned the Rot Hide ichor samples from Fenris Isle. The fluid was being investigated as a clue to the gnolls' origin before the assault.",["title"]="Apothecary Renferrel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"460:description:1-31","460:description:34-38","460:description:41-58","460:description:63-131","460:description:134-262","460:description:265-331","460:description:333-378","460:description:383-409","460:description:412-501","460:objective:1-33"},["minimumStage"]=2,["questID"]=460,["sourceHash"]="428e6f01462674b8a1a6fde7f9751dd88183765026507e643eaea03405fbd50d"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1947",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alaric's account accused Thule of promising protection from the plague but instead trapping him in unlife. After creating the Rot Hide gnolls, Thule had him beheaded and gave his head to them.",["title"]="Thule Ravenclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99:description:1-84","99:description:87-147","99:description:152-272","99:description:275-314","99:description:317-383","99:description:388-457","99:description:460-507","99:objective:1-63"},["minimumStage"]=2,["questID"]=99,["sourceHash"]="0a4181e9754cccb5c3c0abe6b4f908b62b7eee206c225cda68f4a02d5e7acc1d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1938",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dalar Dawnweaver investigated Arugal's enchantments through Pyrewood's human villagers and their transformation into Moonrage worgen at night. He sought enchanted shackles to understand the spell.",["title"]="Dalar Dawnweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"452:description:1-42","452:description:47-96","452:description:99-146","452:description:149-243","452:description:246-360","452:description:365-399","452:description:402-423","452:description:426-484","452:objective:1-53"},["minimumStage"]=2,["questID"]=452,["sourceHash"]="2a04280c4dfb18e39a941d08b6bc6cf45f6ec9609d647b59963bb84f9ad55f66"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2058",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Deathstalker Faerleia planned an attack on the Pyrewood Council, believing Arugal's control over the village depended on those intermediaries. Her hope that his followers would turn on him remained a theory.",["title"]="Deathstalker Faerleia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"450:description:1-66","450:description:71-184","450:description:187-244","450:description:247-290","450:description:293-390","450:description:395-499","450:objective:1-112"},["minimumStage"]=2,["questID"]=450,["sourceHash"]="9b755730afa19a8595d1232a52a2ea237e1b8b13ed68b22510b7efd3517bd7a1"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2106",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Apothecary Berard had studied an ancient plague blamed for killing Lake Lordamere's aquatic life. The Royal Apothecary Society's account said Arugal's curse then reduced him to a mindless servant.",["title"]="Apothecary Berard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"450:description:1-66","450:description:71-184","450:description:187-244","450:description:247-290","450:description:293-390","450:description:395-499","450:objective:1-112"},["minimumStage"]=2,["questID"]=450,["sourceHash"]="9b755730afa19a8595d1232a52a2ea237e1b8b13ed68b22510b7efd3517bd7a1"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-2106",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Berard's study was in the Pyrewood Village Inn, where his journal was sought so that his research could reach Apothecary Renferrel.",["title"]="Apothecary Berard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"482:description:1-10","482:description:12-38","482:description:43-151","482:description:153-250","482:description:255-287","482:description:292-428","482:description:433-502","482:objective:1-51"},["minimumStage"]=2,["questID"]=482,["sourceHash"]="da845d5dd9985173047a46c8dad57961d6de9e131fd5a9bb23eeff40e8f72eca"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1938",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dalar believed Ambermill's wizards intended to awaken a dormant ley node. Taking their pendants was proposed as a way to delay the activation while Allister decided the response.",["title"]="Dalar Dawnweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"479:description:1-70","479:description:72-134","479:description:139-209","479:description:211-235","479:description:240-300","479:objective:1-70"},["minimumStage"]=2,["questID"]=479,["sourceHash"]="d37e6f8cacf21757409c737ac3ba86329647a114bd201f7849bc31f4100a539b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-2121",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shadow Priest Allister sought pendants carried by Ambermill's conjurers, mages and protectors while Dalar tried to locate the source of their spellcasting.",["title"]="Shadow Priest Allister"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"425:description:1-97","425:description:100-198","425:description:203-254","425:description:257-341","425:description:346-387","425:description:390-454","425:objective:1-75"},["minimumStage"]=2,["questID"]=425,["sourceHash"]="0a87f028bc39eed5cb7b26c0938646de1b204df731974c4817e63671191cc488"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1950",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rane Yorick and her brother Quinn were scouting Silverpine for High Executor Hadrec when Ivar the Foul attacked them. Quinn's severe injuries left Rane guarding his recovery.",["title"]="Rane Yorick"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"425:description:1-97","425:description:100-198","425:description:203-254","425:description:257-341","425:description:346-387","425:description:390-454","425:objective:1-75"},["minimumStage"]=2,["questID"]=425,["sourceHash"]="0a87f028bc39eed5cb7b26c0938646de1b204df731974c4817e63671191cc488"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1971",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The ghoul Ivar the Foul mauled Quinn during a scouting mission. Rane feared another attack before her brother recovered and placed Ivar's usual hiding place in the nearby barn.",["title"]="Ivar the Foul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"429:description:1-236","429:objective:1-76"},["minimumStage"]=2,["questID"]=429,["sourceHash"]="0dcf30803e23dbba8882744a91db7ee711d1461b16e450126471d33c6d208323"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1937",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/429",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Renferrel was the apothecary Rane sought for a potion to treat Quinn's wounds, using the discolored hearts of local worgs as ingredients.",["title"]="Apothecary Renferrel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"424:description:1-118","424:description:123-219","424:description:222-315","424:description:320-389","424:description:394-464","424:description:467-505","424:objective:1-78"},["minimumStage"]=2,["questID"]=424,["sourceHash"]="6108fae2461625eb8c45eb203ca58382f4ce9b8122383b9f6aa5b07819f47570"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1972",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grimson the Pale was the tainted foreman of Deep Elem Mine. Dalar's agents connected the mine's corruption to Arugal's spreading enchantments.",["title"]="Grimson the Pale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"433:description:1-157","433:description:162-230","433:description:232-331","433:description:333-429","433:description:434-506","433:objective:1-82"},["minimumStage"]=2,["questID"]=433,["sourceHash"]="ed89cfebdcfb956e77c61ab92b3d579a3260f8ed04557fc22de06894afb31494"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1977",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senator Mehr Stonehallow belonged to both the Senate and the Explorers' League. His work at Gol'Bolar combined political responsibility with an effort to reclaim the quarry from troggs.",["title"]="Senator Mehr Stonehallow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"161:description:1-68","161:description:71-161","161:description:164-249","161:description:252-303","161:description:308-411","161:description:414-469","161:objective:1-128"},["minimumStage"]=2,["questID"]=161,["sourceHash"]="85ca4f58f8ae6a38af068123cebfcd0fe7af5f55ae0131cb2b0fda80a4ab7227"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1073",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ashlan Stonesmirk was an explosives expert assigned to the regiment guarding Dun Modr and the Thandol Span, the specialist sought to analyze suspicious powder.",["title"]="Ashlan Stonesmirk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"161:description:1-68","161:description:71-161","161:description:164-249","161:description:252-303","161:description:308-411","161:description:414-469","161:objective:1-128"},["minimumStage"]=2,["questID"]=161,["sourceHash"]="85ca4f58f8ae6a38af068123cebfcd0fe7af5f55ae0131cb2b0fda80a4ab7227"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1093",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hinderweir suspected the strange-smelling powder was explosive, but required Stonesmirk's analysis before claiming to know its nature.",["title"]="Chief Engineer Hinderweir VII"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"156:description:1-81","156:description:86-121","156:description:124-223","156:description:225-266","156:description:271-324","156:description:327-396","156:description:399-438","156:objective:1-71"},["minimumStage"]=2,["questID"]=156,["sourceHash"]="a28cb6b1c6106e12c9e554f2af876b4184607282743fa3e3337a7c203a4c2f80"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-273",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tavernkeep Smitts brewed zombie juice from rot blossoms. He had heard that the blossoms grew inside the skulls of Raven Hill's skeletons, though he admitted he had not inspected them himself.",["title"]="Tavernkeep Smitts"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"165:description:1-130","165:description:132-212","165:description:214-261","165:objective:1-59"},["minimumStage"]=2,["questID"]=165,["sourceHash"]="be4d286a72e2d8888551b0eb46a0a5b8e6fa191e522849c82ab9572d5dc1ae02"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-633",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Elaine Carevin remembered a hermit who had stopped coming into town for supplies. His absence prompted her concern for the old man in the shack overlooking Raven Hill Cemetery.",["title"]="Elaine Carevin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"56:description:1-89","56:description:92-194","56:description:199-248","56:description:250-392","56:description:395-429","56:objective:1-99"},["minimumStage"]=2,["questID"]=56,["sourceHash"]="59f75d213ea4a884962af47d85c5d0152e2722dfb377a08546d1c7ee5d9109a6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-264",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Althea Ebonlocke commanded the Night Watch after Stormwind withdrew its commissioned guards from Duskwood. Protecting Darkshire now depended on local Watchers and outside help.",["title"]="Commander Althea Ebonlocke"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"58:description:1-42","58:description:45-89","58:description:92-142","58:description:145-246","58:objective:1-114"},["minimumStage"]=2,["questID"]=58,["sourceHash"]="6a682c0e4e29b230aaf08a2a787f92a51894d13eb8617a22c3c92c35b342a5fa"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-264",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ebonlocke reported too few Watchers to keep Darkshire safe while plague spreaders occupied Raven Hill's eastern mausoleum, extending the defense beyond the town itself.",["title"]="Commander Althea Ebonlocke"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"55:description:1-111","55:description:114-158","55:description:163-193","55:description:196-242","55:description:247-255","55:description:258-299","55:description:302-357","55:objective:1-100"},["minimumStage"]=2,["questID"]=55,["sourceHash"]="45c79219ec369b1a4ea61280efd32b84fb25c2d46664ce62ff202ca6675b34a2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1200",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sven's plan against Morbent Fel depended on Morbent's Bane stripping away the protective magic around him. This was a proposed means of attack, not evidence that any traveler had defeated him.",["title"]="Morbent Fel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"55:description:1-111","55:description:114-158","55:description:163-193","55:description:196-242","55:description:247-255","55:description:258-299","55:description:302-357","55:objective:1-100"},["minimumStage"]=2,["questID"]=55,["sourceHash"]="45c79219ec369b1a4ea61280efd32b84fb25c2d46664ce62ff202ca6675b34a2"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1200",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Morbent Fel's lair was the house high on the hill east of Raven Hill Cemetery, overlooking the graves below.",["title"]="Morbent Fel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"177:description:1-55","177:description:59-72","177:description:75-126","177:description:129-182","177:description:185-208","177:description:211-283","177:objective:1-94"},["minimumStage"]=2,["questID"]=177,["sourceHash"]="1cc9dceccf85e6fcb82ea00d0db020c3cb5e015b666a55e8558c72bc758f0ca1"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-302",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Blind Mary remembered a looking glass she had discarded behind a barn after an unnamed incident. She suspected the wandering ghoul had taken it, without claiming she had seen the theft.",["title"]="Blind Mary"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"177:description:1-55","177:description:59-72","177:description:75-126","177:description:129-182","177:description:185-208","177:description:211-283","177:objective:1-94"},["minimumStage"]=2,["questID"]=177,["sourceHash"]="1cc9dceccf85e6fcb82ea00d0db020c3cb5e015b666a55e8558c72bc758f0ca1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-511",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Blind Mary's missing looking glass was thought to have passed to the Insane Ghoul. Rumor placed the creature in Tranquil Gardens Cemetery, the lead given to those seeking the glass for Viktori.",["title"]="Insane Ghoul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"363:description:1-23","363:description:25-111","363:description:116-168","363:description:170-211","363:description:216-330","363:objective:1-32"},["minimumStage"]=2,["questID"]=363,["sourceHash"]="61a13f0010c399131204716385c754bc6421e06020ace516ca23c3d3e6ea651f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-154",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Deathknell's crypt was tended by Mordo; the chapel at the foot of its hill housed Shadow Priest Sarvis, to whom the newly awakened were directed.",["title"]="Deathknell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6395:description:1-144","6395:description:149-229","6395:description:232-330","6395:description:335-409","6395:description:412-503","6395:objective:1-75"},["minimumStage"]=2,["questID"]=6395,["sourceHash"]="5cedea796feaa87c4a50e81f94375830d7074ec84a936792d46f70b9cfb04636"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-154",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The village graveyard held Marla Fipps's grave in its first row. Her wish to be buried beside Samuel connected the graves to a family destroyed by the plague.",["title"]="Deathknell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"354:description:1-69","354:description:72-118","354:description:123-252","354:description:255-302","354:description:307-357","354:description:360-399","354:description:404-471","354:description:474-511","354:objective:1-91"},["minimumStage"]=2,["questID"]=354,["sourceHash"]="11ffa69f5957ec55cc1834bae4f2ac052b7bd3e6d9beb6e542e4ed19c56b044c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-157",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Agamands had been Tirisfal's most prosperous family. Their former worker Coleman recalled the family's fortified stand against the Scourge and blamed it for the fate of the workers who stayed.",["title"]="Agamand Mills"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"426:description:1-59","426:description:62-125","426:description:130-156","426:description:159-201","426:description:206-221","426:description:224-334","426:description:339-380","426:description:383-456","426:description:459-504","426:objective:1-91"},["minimumStage"]=2,["questID"]=426,["sourceHash"]="457ab3525968e573cd5eeaa822e57fa45b6e6a60b41a4ecb3411c5c0167f5344"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-157",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scourge soldiers and bonecasters occupied the mills, whose windmills marked the approach. Dillinger feared the position would become a base for attacks elsewhere in Tirisfal.",["title"]="Agamand Mills"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"408:description:1-61","408:description:64-199","408:description:202-294","408:description:299-337","408:description:340-414","408:description:419-460","408:objective:1-49","408:objective:54-124"},["minimumStage"]=2,["questID"]=408,["sourceHash"]="c5872f4277712947be70f3a0f9f3eb136b08038928e6a7dafff14a910262f653"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-158",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The crypt was the Scourge's strongest point around Agamand Mills, serving as Captain Dargol's headquarters while necromancy raised the family's ancestors.",["title"]="Agamand Family Crypt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1821:description:1-82","1821:description:85-158","1821:description:163-208","1821:description:211-314","1821:description:317-333","1821:description:338-451","1821:objective:1-127"},["minimumStage"]=2,["questID"]=1821,["sourceHash"]="4ac9a1c246dd93ebd551233786fcfb9f7ab5c9f018f7ce52da7ed9820df09351"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-158",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The family crypt stood at the mills' northern end, guarded by Scourge and dead Agamands. Its heirlooms included an axe, sword, mace and dagger sought by Coleman Farthing.",["title"]="Agamand Family Crypt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"358:description:1-165","358:description:172-334","358:description:337-359","358:description:364-504","358:objective:1-49","358:objective:56-110"},["minimumStage"]=2,["questID"]=358,["sourceHash"]="7c3638dc209abb8f3c3dda4bb2e067720eca598ab527860c47646dfcd8ed7474"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-164",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rot Hide gnolls robbed the graves around Garren's Haunt for bodies to reinforce the Scourge. The nearby mass graves had been dug for Tirisfal's plague dead.",["title"]="Garren's Haunt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"398:description:1-19","398:description:24-137","398:description:140-221","398:description:224-310","398:description:315-407","398:description:410-470","398:description:475-496","398:objective:1-81"},["minimumStage"]=2,["questID"]=398,["sourceHash"]="9e398b2840862bf0f2aac63e44bc2a8a0ceeb17b32c71a2a9a5f12596327600b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-164",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brill's wanted notice placed Maggot Eye near Garren's Haunt north of town and connected his corpse stealing to the Lich King's army.",["title"]="Garren's Haunt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"383:description:1-70","383:description:72-155","383:description:157-315","383:description:320-357","383:description:359-419","383:description:421-463","383:description:465-508","383:objective:1-66"},["minimumStage"]=2,["questID"]=383,["sourceHash"]="e22955a51cd4281cfad785606a12bcce68a29494f75e0d4a3440fc23409445ce"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="reviewed-cold-hearth-manor",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cold Hearth Manor lay along the eastward road from the crossroads reached after leaving Deathknell, on the route Executor Arren described toward Brill.",["title"]="Cold Hearth Manor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"442:description:1-86","442:description:91-148","442:description:151-166","442:description:171-218","442:description:221-238","442:objective:1-60"},["minimumStage"]=2,["questID"]=442,["sourceHash"]="94c55ed092fb0f61aee40236b548a533b1d33c70ffc4c89203a116bf0e148ca8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-172",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hadrec treated Fenris Isle as the Scourge's place of strength in Silverpine, with Thule Ravenclaw the intended target of the assault.",["title"]="Fenris Isle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"443:description:1-96","443:description:99-198","443:description:203-307","443:description:310-375","443:objective:1-75"},["minimumStage"]=2,["questID"]=443,["sourceHash"]="29ecd187696965b4b79e5dd1bbda3841db6d1b36b6f015b5f9432b28e3df2e56"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-172",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fenris Isle lay east of the Decrepit Ferry. Its Rot Hide gnolls supplied the ichor Renferrel was asked to study before the attack.",["title"]="Fenris Isle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"460:description:1-31","460:description:34-38","460:description:41-58","460:description:63-131","460:description:134-262","460:description:265-331","460:description:333-378","460:description:383-409","460:description:412-501","460:objective:1-33"},["minimumStage"]=2,["questID"]=460,["sourceHash"]="428e6f01462674b8a1a6fde7f9751dd88183765026507e643eaea03405fbd50d"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-235",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alaric's severed head told of service as Thule's bodyguard, magical betrayal and beheading. He believed his body had been buried near the keep's stable in an unmarked grave.",["title"]="Fenris Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"99:description:1-84","99:description:87-147","99:description:152-272","99:description:275-314","99:description:317-383","99:description:388-457","99:description:460-507","99:objective:1-63"},["minimumStage"]=2,["questID"]=99,["sourceHash"]="0a4181e9754cccb5c3c0abe6b4f908b62b7eee206c225cda68f4a02d5e7acc1d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-204",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dalar's investigation described Pyrewood's peasants appearing human by day and becoming Moonrage worgen after sunset, a transformation tied to Arugal's enchanted shackles.",["title"]="Pyrewood Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"452:description:1-42","452:description:47-96","452:description:99-146","452:description:149-243","452:description:246-360","452:description:365-399","452:description:402-423","452:description:426-484","452:objective:1-53"},["minimumStage"]=2,["questID"]=452,["sourceHash"]="2a04280c4dfb18e39a941d08b6bc6cf45f6ec9609d647b59963bb84f9ad55f66"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-204",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Pyrewood Council acted as Arugal's intermediaries in the village, according to Faerleia. She hoped that breaking the Council would loosen his hold on its inhabitants.",["title"]="Pyrewood Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"482:description:1-10","482:description:12-38","482:description:43-151","482:description:153-250","482:description:255-287","482:description:292-428","482:description:433-502","482:objective:1-51"},["minimumStage"]=2,["questID"]=482,["sourceHash"]="da845d5dd9985173047a46c8dad57961d6de9e131fd5a9bb23eeff40e8f72eca"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-233",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ambermill housed a dormant ley-energy node marked out by the Kirin Tor. Dalar interpreted the wizards' activity there as preparations to reactivate it, with their larger purpose still uncertain.",["title"]="Ambermill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"479:description:1-70","479:description:72-134","479:description:139-209","479:description:211-235","479:description:240-300","479:objective:1-70"},["minimumStage"]=2,["questID"]=479,["sourceHash"]="d37e6f8cacf21757409c737ac3ba86329647a114bd201f7849bc31f4100a539b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-233",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ambermill's conjurers, mages and protectors carried the Dalaran pendants Allister sought to remove while investigating their magic.",["title"]="Ambermill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"438:description:1-68","438:description:71-163","438:description:168-231","438:description:234-297","438:objective:1-25","438:objective:30-73"},["minimumStage"]=2,["questID"]=438,["sourceHash"]="80acf1b91d68e88a24f5b93c1ce0d25344cb30c4d3c974c5c47865ebaf9435f2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-237",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Decrepit Ferry, east of the Sepulcher, was heavily patrolled by Rot Hides and other undead. Hadrec sought an explanation for the Scourge occupation rather than claiming its purpose was known.",["title"]="The Decrepit Ferry"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"425:description:1-97","425:description:100-198","425:description:203-254","425:description:257-341","425:description:346-387","425:description:390-454","425:objective:1-75"},["minimumStage"]=2,["questID"]=425,["sourceHash"]="0a87f028bc39eed5cb7b26c0938646de1b204df731974c4817e63671191cc488"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-239",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rane and Quinn's reconnaissance ended at this farm when Ivar the Foul mauled Quinn. The barn sheltered the ghoul while Rane guarded her injured brother nearby.",["title"]="The Ivar Patch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"424:description:1-118","424:description:123-219","424:description:222-315","424:description:320-389","424:description:394-464","424:description:467-505","424:objective:1-78"},["minimumStage"]=2,["questID"]=424,["sourceHash"]="6108fae2461625eb8c45eb203ca58382f4ce9b8122383b9f6aa5b07819f47570"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-213",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Reports linked Deep Elem's tainted foreman to Arugal's spreading magic. Dalar wanted the mine reclaimed as a resource for Varimathras's advance.",["title"]="Deep Elem Mine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"433:description:1-157","433:description:162-230","433:description:232-331","433:description:333-429","433:description:434-506","433:objective:1-82"},["minimumStage"]=2,["questID"]=433,["sourceHash"]="ed89cfebdcfb956e77c61ab92b3d579a3260f8ed04557fc22de06894afb31494"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-134",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Troggs poured out as the miners dug deeper into Gol'Bolar, destroying equipment and driving the workforce out. Stonehallow's plan was to reclaim the quarry, rebuild and resume work.",["title"]="Gol'Bolar Quarry"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1558:description:1-51","1558:description:54-133","1558:description:136-194","1558:description:197-200","1558:description:205-266","1558:description:269-294","1558:description:302-317","1558:description:320-332","1558:description:335-361","1558:description:364-407","1558:description:410-445","1558:objective:1-54","1558:objective:57-144"},["minimumStage"]=2,["questID"]=1558,["sourceHash"]="2a01c4756acb020ceb07364e3cd2878001612de7919b4074ba0964a09a2f5f05"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-146",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The dwarves' great Stonewrought Dam in Loch Modan overlooked an immense waterfall, visible from the middle of the structure in the orphan's requested visit.",["title"]="Stonewrought Dam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"455:description:1-56","455:description:59-100","455:description:103-237","455:description:242-325","455:description:328-372","455:description:377-456","455:description:461-486","455:description:489-500","455:objective:1-19","455:objective:24-70","455:objective:75-119"},["minimumStage"]=2,["questID"]=455,["sourceHash"]="524fc92094783dd80c19c622aad1bc8823e273df6cb37f75623f64b57af86ca8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-269",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dragonmaw expansion into Dun Algaz threatened to sever Loch Modan's connection with Menethil Harbor, making the passage a concern for both travel and military supply.",["title"]="Dun Algaz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"163:description:1-36","163:description:38-110","163:description:112-232","163:description:237-334","163:objective:1-37"},["minimumStage"]=2,["questID"]=163,["sourceHash"]="bc37f6b2b223b68303e27517aaca2fa37244ec2859fe591ba8996fd8150f194c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16168",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Calor's reports of moving shadows and a light in a window made Raven Hill's buildings a subject of investigation. The account offered signs of a haunting, not an established identity for it.",["title"]="Raven Hill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"58:description:1-42","58:description:45-89","58:description:92-142","58:description:145-246","58:objective:1-114"},["minimumStage"]=2,["questID"]=58,["sourceHash"]="6a682c0e4e29b230aaf08a2a787f92a51894d13eb8617a22c3c92c35b342a5fa"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16162",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The eastern mausoleum held plague spreaders during the Night Watch's defense of Darkshire, adding to the skeletal infestation reported among the graves.",["title"]="Raven Hill Cemetery"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"165:description:1-130","165:description:132-212","165:description:214-261","165:objective:1-59"},["minimumStage"]=2,["questID"]=165,["sourceHash"]="be4d286a72e2d8888551b0eb46a0a5b8e6fa191e522849c82ab9572d5dc1ae02"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-16162",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A hermit's shack overlooked Raven Hill Cemetery. His unexplained absence from supply visits to town drew Elaine Carevin's concern.",["title"]="Raven Hill Cemetery"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"56:description:1-89","56:description:92-194","56:description:199-248","56:description:250-392","56:description:395-429","56:objective:1-99"},["minimumStage"]=2,["questID"]=56,["sourceHash"]="59f75d213ea4a884962af47d85c5d0152e2722dfb377a08546d1c7ee5d9109a6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-121",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Skeletal warriors and mages occupied Tranquil Gardens just south of Darkshire, where the Night Watch sought help after Stormwind's guards withdrew.",["title"]="Tranquil Gardens Cemetery"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"177:description:1-55","177:description:59-72","177:description:75-126","177:description:129-182","177:description:185-208","177:description:211-283","177:objective:1-94"},["minimumStage"]=2,["questID"]=177,["sourceHash"]="1cc9dceccf85e6fcb82ea00d0db020c3cb5e015b666a55e8558c72bc758f0ca1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-121",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rumor placed the Insane Ghoul at Tranquil Gardens. Blind Mary suspected it had taken the looking glass discarded behind her barn, linking the cemetery to Viktori's search.",["title"]="Tranquil Gardens Cemetery"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"173:description:1-44","173:description:46-104","173:description:106-163","173:description:168-206","173:description:211-232","173:description:234-304","173:description:306-365","173:description:370-488","173:objective:1-61"},["minimumStage"]=2,["questID"]=173,["sourceHash"]="5a1ea0ae215df1fc540b570c76dd87a71927a334ff5c32794f6913f57b441f1f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-663",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Calor joined Carevin after becoming disillusioned with what he considered the Watch's complacency. He tested would-be allies against the worgen while describing his work as the expulsion of evil and heresy.",["title"]="Calor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"20:description:1-100","20:description:103-204","20:description:209-242","20:description:245-321","20:description:326-447","20:description:450-503","20:objective:1-56"},["minimumStage"]=2,["questID"]=20,["sourceHash"]="6e4ebe91765f1e6daa10ec8d6ce3f8c46a9323efe40a1ac1fada8d508a82b43b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-382",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marshal Marris sought help because Blackrock raiders operating from Stonewatch kept Lakeshire's citizens confined to town. He requested battleworn axes as proof of action against the marauders.",["title"]="Marshal Marris"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"19:description:1-89","19:description:92-165","19:description:168-199","19:objective:1-54"},["minimumStage"]=2,["questID"]=19,["sourceHash"]="ce86264a823f491954fef6ceb0e5042afc9a26497146de83c3a6a70d9795f0af"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-486",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tharil'zun led Blackrock outrunners whose ambushes threatened the route between Lakeshire and Stonewatch Keep, prompting Marshal Marris's demand for his head.",["title"]="Tharil'zun"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"169:description:1-7","169:description:9-116","169:description:122-156","169:description:159-277","169:description:280-328","169:description:331-443","169:objective:1-86"},["minimumStage"]=2,["questID"]=169,["sourceHash"]="4823df1fc8847c050c5966922c08a371c07c75cb84f3b04810ba688f1ee5541a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-334",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lakeshire's wanted notice named Gath'Ilzogg as the leader of the capture of Stonewatch Keep and the raids on the town, with a bounty paid through Magistrate Solomon.",["title"]="Gath'Ilzogg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94:description:1-99","94:description:102-193","94:description:198-226","94:description:228-249","94:description:254-325","94:description:328-372","94:description:377-460","94:objective:1-81"},["minimumStage"]=2,["questID"]=94,["sourceHash"]="4d71889f9c4c99d6c7aa6fac59e944e533be455e84eaabe5b06b7fb651bdcc74"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-397",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Morganth was Theocritus's powerful rival at the Tower of Ilgalar. Theocritus developed the Eye of Azora to watch him from afar and sought a glyph to probe his plans.",["title"]="Morganth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"249:description:1-59","249:description:64-126","249:description:129-228","249:description:233-319","249:description:322-378","249:description:383-429","249:description:432-474","249:objective:1-16","249:objective:21-101"},["minimumStage"]=2,["questID"]=249,["sourceHash"]="c678aed984412dad316027c5f70ebd91cf4e22386b1eb4b23831731a2d0f8230"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-397",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theocritus's observations led him to believe Morganth sought the Scythe of Elune. Whether Morganth had actually found it remained uncertain in the warning sent to his would-be opponent.",["title"]="Morganth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94:description:1-99","94:description:102-193","94:description:198-226","94:description:228-249","94:description:254-325","94:description:328-372","94:description:377-460","94:objective:1-81"},["minimumStage"]=2,["questID"]=94,["sourceHash"]="4d71889f9c4c99d6c7aa6fac59e944e533be455e84eaabe5b06b7fb651bdcc74"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-313",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theocritus's Glyph of Azora was to be set on a lion statue near Ilgalar, extending his remote observation of Morganth toward the rival's thoughts.",["title"]="Theocritus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"361:description:1-70","361:description:73-159","361:objective:1-73","361:completion:1-21","361:completion:23-119","361:completion:121-134","361:completion:136-177","361:completion:179-217","361:completion:222-266","361:completion:271-299","361:completion:301-360","361:completion:362-456","361:completion:461-482","361:completion:484-491"},["minimumStage"]=4,["questID"]=361,["sourceHash"]="1048bb601a24ab96b77774b87e404d389727436798bfcca959c0e3de1aa65c5d"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1560",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yvette Farthing remembered begging Thurman to leave Agamand Mills with her and her father. His family loyalty kept him there; receiving his undelivered letter brought grief before she rejected that former life and love.",["title"]="Yvette Farthing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"361:description:1-70","361:description:73-159","361:objective:1-73"},["minimumStage"]=2,["questID"]=361,["sourceHash"]="1048bb601a24ab96b77774b87e404d389727436798bfcca959c0e3de1aa65c5d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1656",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thurman was Gregor Agamand's eldest son and the author of an undelivered letter addressed to Yvette Farthing.",["title"]="Thurman Agamand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"491:description:1-140","491:description:143-287","491:description:290-337","491:description:342-346","491:description:349-421","491:description:424-448","491:objective:1-77"},["minimumStage"]=2,["questID"]=491,["sourceHash"]="adbdd8d8291119316a5e7b848b0c4c8e81b02e81f0c248710c424e2297b25a4a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1947",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thule and two fellow apprentices had woven their wands into a token of friendship. The account accompanying the Woven Wand said he later stole it and hid it in Fenris Keep rather than surrender it to his estranged companions.",["title"]="Thule Ravenclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"491:description:1-140","491:description:143-287","491:description:290-337","491:description:342-346","491:description:349-421","491:description:424-448","491:objective:1-77","491:completion:1-16","491:completion:18-42","491:completion:44-126","491:completion:131-203","491:completion:205-244","491:completion:249-273","491:completion:275-322"},["minimumStage"]=4,["questID"]=491,["sourceHash"]="adbdd8d8291119316a5e7b848b0c4c8e81b02e81f0c248710c424e2297b25a4a"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1498",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bethor Iceshard recognized the Woven Wand as a relic of his friendship with Thule. He said their friendship had broken when Thule sided with the Lich King, and believed he would have sensed the wand's power if Thule had invoked it.",["title"]="Bethor Iceshard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7845:description:1-79","7845:description:81-167","7845:description:169-270","7845:description:275-296","7845:description:298-343","7845:objective:1-119","7845:objective:124-269"},["minimumStage"]=2,["questID"]=7845,["sourceHash"]="4017e983314306a744d1de2d47f2a8eb58bc3e35a2650cd4d9cae1360a6d566c"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-14736",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Primal Torntusk's mate, Elder Torntusk, was taken in a midnight Vilebranch raid. Reports that he remained alive at Jintha'Alor made rescuing him a personal and communal urgency.",["title"]="Primal Torntusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7845:description:1-79","7845:description:81-167","7845:description:169-270","7845:description:275-296","7845:description:298-343","7845:objective:1-119","7845:objective:124-269"},["minimumStage"]=2,["questID"]=7845,["sourceHash"]="4017e983314306a744d1de2d47f2a8eb58bc3e35a2650cd4d9cae1360a6d566c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-14757",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Spies reported Elder Torntusk alive atop Jintha'Alor after his abduction from Revantusk. Priestess Hexx was said to be preparing him as a sacrifice to Hakkar.",["title"]="Elder Torntusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7845:description:1-79","7845:description:81-167","7845:description:169-270","7845:description:275-296","7845:description:298-343","7845:objective:1-119","7845:objective:124-269"},["minimumStage"]=2,["questID"]=7845,["sourceHash"]="4017e983314306a744d1de2d47f2a8eb58bc3e35a2650cd4d9cae1360a6d566c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7995",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vile Priestess Hexx presided over the threatened sacrifice of Elder Torntusk to Hakkar at Jintha'Alor, according to the reports received by Primal Torntusk.",["title"]="Vile Priestess Hexx"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7850:description:1-48","7850:description:50-117","7850:description:122-188","7850:description:190-310","7850:description:315-435","7850:objective:1-122","7850:objective:124-176"},["minimumStage"]=2,["questID"]=7850,["sourceHash"]="0ee4b4a6f30f217e1c5ba716e534cdd32b9399aee3afc58ae87236a8737aa84b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7995",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Primal Torntusk attributed the Vilebranch's supernatural ferocity to Hexx's magic and vessels of tainted blood scattered through Jintha'Alor, which she said empowered the trolls while driving them mad.",["title"]="Vile Priestess Hexx"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7839:description:1-55","7839:description:57-188","7839:description:193-248","7839:description:253-341","7839:description:346-409","7839:description:414-430","7839:objective:1-95","7839:objective:97-137","7839:objective:142-281","7839:objective:283-315"},["minimumStage"]=2,["questID"]=7839,["sourceHash"]="f4cb9066a73d4618e3135debe8725437a8920236aa291947b45351392e5796c4"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-14737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Slagtree treasured a set of tools given to him by a gnome who had saved his life when he was a young orc. The Vilebranch theft mattered for that memory as much as for his work.",["title"]="Smith Slagtree"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7839:description:1-55","7839:description:57-188","7839:description:193-248","7839:description:253-341","7839:description:346-409","7839:description:414-430","7839:objective:1-95","7839:objective:97-137","7839:objective:142-281","7839:objective:283-315"},["minimumStage"]=2,["questID"]=7839,["sourceHash"]="f4cb9066a73d4618e3135debe8725437a8920236aa291947b45351392e5796c4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Smith Slagtree had spare tools but wanted the stolen gift recovered. Markhor's report placed the missing set near the northeastern Vilebranch temples.",["title"]="Smith Slagtree"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2995:description:1-88","2995:description:90-276","2995:description:278-349","2995:description:354-415","2995:description:420-450","2995:description:453-499","2995:description:501-510","2995:objective:1-136"},["minimumStage"]=2,["questID"]=2995,["sourceHash"]="19e5562cdd68fcc7d53ede0c575c05cf8781aed8770f648f9bdd9a54e7b4ac9f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-7825",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Oran Snakewrithe wanted to break the Highvale elves' communications and alliances by burning their records at Quel'Danil Lodge, where ambassadors shared knowledge about the Witherbark.",["title"]="Oran Snakewrithe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2877:description:1-70","2877:description:73-143","2877:description:148-267","2877:description:270-355","2877:description:360-394","2877:description:397-491","2877:description:494-502","2877:objective:1-101"},["minimumStage"]=2,["questID"]=2877,["sourceHash"]="d7a0502d1f6a03d888b925aecd34bef841dc6c584302190a14f7e5e527aeed56"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7884",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fraggar Thundermantle wanted Skulk Rock cleared of sludges and oozes before the Wildhammers moved into the Horde's abandoned positions there.",["title"]="Fraggar Thundermantle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2937:description:1-113","2937:description:116-154","2937:objective:1-99"},["minimumStage"]=2,["questID"]=2937,["sourceHash"]="5c3ecbd8e9ec993290e4508aaa66817f04e01ca2387574e7149eb8cadf204d96"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2707",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shadra was the spider god invoked by a parchment read at Shadra'Alor's altar. The charge accompanying the summons sought her venom for Apothecary Lydon.",["title"]="Shadra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2934:description:1-55","2934:description:58-196","2934:description:199-260","2934:description:265-334","2934:objective:1-64"},["minimumStage"]=2,["questID"]=2934,["sourceHash"]="c36531929e2aa4b23ef42b1079b707fccb2db47f919bfce8ce8da85f52c8db46"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2216",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lydon required fresh, undamaged venom sacs from Hinterlands spiders, especially those near Shadra'Alor, because the sample's condition mattered to his research.",["title"]="Apothecary Lydon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2994:description:1-23","2994:description:28-202","2994:objective:1-110"},["minimumStage"]=2,["questID"]=2994,["sourceHash"]="96b66b79ab09a282cabf7812d518c820bcd85475cf89c9e31415fdf66939fb5f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-8023",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sharpbeak was held in a cage near the top of Jintha'Alor. The rescue plan depended on obtaining its key from Priestess Hexx.",["title"]="Sharpbeak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4787:description:1-50","4787:description:53-159","4787:description:162-221","4787:description:226-254","4787:description:257-382","4787:objective:1-46"},["minimumStage"]=2,["questID"]=4787,["sourceHash"]="2a28491591be75f7ab10dbf673c8001e7215170c3153e9c9efc1a2d145dceab6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8579",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yeh'kinya described the Ancient Egg as a relic of the old troll empires capable of holding Hakkar's essence. His appeal presented it as protection against the blood god, rather than revealing a verified outcome.",["title"]="Yeh'kinya"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7849:description:1-67","7849:description:69-167","7849:description:172-302","7849:description:307-372","7849:description:374-397","7849:objective:1-105","7849:objective:107-196","7849:objective:201-296","7849:objective:298-397","7849:objective:399-450"},["minimumStage"]=2,["questID"]=7849,["sourceHash"]="4a4ab15c5a3cd48508cee77143147bf724b95703762d471b8ebdd8f230e105be"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-14741",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Huntsman Markhor's twin, Malkhor, was abducted in the same raid as Elder Torntusk. Markhor reported his brother executed and his remains fed to Vilebranch wolves and oozes, and sought their recovery for his soul.",["title"]="Huntsman Markhor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"663:description:1-20","663:description:22-52","663:description:57-81","663:description:84-138","663:description:141-206","663:description:211-272","663:description:275-321","663:description:324-368","663:description:371-409","663:description:414-491","663:objective:1-41"},["minimumStage"]=2,["questID"]=663,["sourceHash"]="df801e49d3944cb4730fad89d858936ce8d950271aa8a8bcdc1a1a39b682fdd0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2766",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lolo the Lookout greeted visitors to Faldir's Cove while worrying that O'Breen's brief treasure stop would become a longer stay after the loss of two ships.",["title"]="Lolo the Lookout"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"685:description:1-100","685:description:103-231","685:description:236-348","685:description:353-403","685:objective:1-75"},["minimumStage"]=2,["questID"]=685,["sourceHash"]="dcfcec2e568c6fb177a2219c67ed183fac2719d6c2851a9b4ad9609e93488256"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2597",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Stromgarde Militia identified Lord Falconcrest as the leader of the Syndicate's operations in Arathi, making his removal a strategic purpose of its bounty.",["title"]="Lord Falconcrest"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"685:description:1-100","685:description:103-231","685:description:236-348","685:description:353-403","685:objective:1-75"},["minimumStage"]=2,["questID"]=685,["sourceHash"]="dcfcec2e568c6fb177a2219c67ed183fac2719d6c2851a9b4ad9609e93488256"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2599",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Otto was Falconcrest's bodyguard. The militia's notice called him a fierce opponent responsible for killing many defenders, although he was not himself its strategic target.",["title"]="Otto"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"644:description:1-100","644:description:102-178","644:description:180-286","644:objective:1-84"},["minimumStage"]=2,["questID"]=644,["sourceHash"]="c498f8ee0d0d6bdb632781d114fcd856debcc74fc9d62892987bc8d2c742a318"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2607",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Prince Galen, son of Thoras Trollbane, personally held the last sigil sought to open his father's tomb. Zengu placed him in the chapel within Stromgarde's militia-held district.",["title"]="Prince Galen Trollbane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"684:description:1-104","684:description:107-180","684:description:185-227","684:description:232-320","684:description:323-366","684:objective:1-53"},["minimumStage"]=2,["questID"]=684,["sourceHash"]="0f13e19f89f7d0863f6a3b5e69efdbec2784164f4c8bbe0473f6a30208bab7c1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2783",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marez Cowl was a Syndicate adviser and operative last reported in its quarter of Stromgarde. The militia's warning described a cunning warlock dealing with demons.",["title"]="Marez Cowl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"691:description:1-67","691:description:69-182","691:description:187-280","691:description:285-312","691:description:314-360","691:objective:1-121"},["minimumStage"]=2,["questID"]=691,["sourceHash"]="dac7d02c82e662b285310a4d0beb15612ed6f57376a85201f48c38a2e9d533df"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2788",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Archmage Malin sent Kryten and Skuerto to Arathi to gather reagents, including Witherbark tusks, medicine pouches and a shadow hunter's knife.",["title"]="Apprentice Kryten"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"694:description:1-11","694:description:16-98","694:description:100-229","694:description:231-315","694:description:317-402","694:description:407-511","694:objective:1-71"},["minimumStage"]=2,["questID"]=694,["sourceHash"]="f22f4e0464f2195f2112130b5a7369287d3bf3f9449e13544f835e2db2f4f20d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2788",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kryten knew the spell to enchant an azure agate into a key for the Tower of Arathor's defenses, using a gem taken back from Boulderfist shamans.",["title"]="Apprentice Kryten"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"693:description:1-8","693:description:10-48","693:description:50-74","693:description:79-166","693:description:168-312","693:description:317-379","693:description:381-417","693:description:422-493","693:objective:1-76"},["minimumStage"]=2,["questID"]=693,["sourceHash"]="06c7cff386f5fe382153a0b2aa81c55f267ab6289a149249f542963c0db66957"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2789",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Skuerto traced Trelane's Wand of Invocation to Kor'gresh in Boulderfist Hall, reporting that the ogre had begun using its ice magic to intimidate his own kin.",["title"]="Skuerto"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"677:description:1-166","677:description:168-230","677:description:236-365","677:description:370-435","677:description:437-511","677:objective:1-118"},["minimumStage"]=2,["questID"]=677,["sourceHash"]="739e65f38a8eb18de6b10d23d9964e8864155da64328745ede4db734049a600a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2771",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Drum Fel saw the Witherbark and Boulderfists as allies trying to drive Hammerfall's people from Arathi. His campaign was framed as the defense of a home against their pressure.",["title"]="Drum Fel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"679:description:1-49","679:description:51-71","679:description:73-155","679:description:157-272","679:description:277-382","679:objective:1-99"},["minimumStage"]=2,["questID"]=679,["sourceHash"]="974fcddfa5e2b7d5f6511726cf52f26bc7a2729f32ca6a0962e570f192642451"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2771",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Drum Fel placed the leadership of the attacks within Stromgarde's ruins and made the Boulderfist lords and shamans there the final targets of his campaign.",["title"]="Drum Fel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1172:description:1-56","1172:description:58-116","1172:description:121-175","1172:description:177-212","1172:description:214-264","1172:description:269-358","1172:description:363-382","1172:description:384-414","1172:objective:1-71"},["minimumStage"]=2,["questID"]=1172,["sourceHash"]="ede75b30db890fb6b85529a7ce467b18e0a0a1192b75ea087eea27b7e1d68076"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4501",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Draz'Zilb believed reclaiming Stonemaul Village required ending the dragon breeding grounds around it. He sought the destruction of Onyxia's eggs scattered across Dragonmurk toward Wyrmbog.",["title"]="Draz'Zilb"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6570:description:1-134","6570:description:139-306","6570:description:311-386","6570:description:388-456","6570:objective:1-73","6570:objective:75-153"},["minimumStage"]=2,["questID"]=6570,["sourceHash"]="24f6133e5ff370a4b93975603eb5b862e3d399b3d7c5b3c81a65cb3054e2a706"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10321",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Emberstrife was described as an ancient drake and Nefarian's gatekeeper, testing dragonspawn who would become elite guards to Onyxia.",["title"]="Emberstrife"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1287:description:1-7","1287:description:9-20","1287:description:25-132","1287:description:134-209","1287:description:214-288","1287:description:293-316","1287:description:318-377","1287:objective:1-58"},["minimumStage"]=2,["questID"]=1287,["sourceHash"]="e8e89c8fd297f7bd7368f007387027efc46d8b1913c55d1180f65ecb461dd8a2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5089",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Balos said his deserters had expelled Reethe for repeatedly raiding the Brackenwall ogres' supplies. He feared their small band could not withstand the retaliation and asked to be forgotten after giving the information.",["title"]="Balos Jacken"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1201:description:1-44","1201:description:47-175","1201:description:180-213","1201:description:218-288","1201:description:291-375","1201:description:380-420","1201:description:423-510","1201:objective:1-86"},["minimumStage"]=2,["questID"]=1201,["sourceHash"]="30c64ab5eeed36845b953fc600fc2ae2ca543d840bc36f92d9e7e3a56e5edec6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4791",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nazeer Bloodpike described the Horde-Alliance truce as uneasy and accused infiltrators east of Brackenwall of reporting Horde movements to Theramore. Removing those spies was his immediate concern.",["title"]="Nazeer Bloodpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1389:description:1-88","1389:description:90-140","1389:description:143-252","1389:description:257-322","1389:description:327-475","1389:description:477-500","1389:objective:1-81"},["minimumStage"]=2,["questID"]=1389,["sourceHash"]="a980185ab6be116ef9bff33ca8df8c845f8f8480e10e5e24da7a052314e9e048"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1776",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magtoor sought sacred draenethyst crystals taken by the Lost Ones, fearing his own people might lose their way without them. His appeal paired recovery of the crystals with sorrow for former kin.",["title"]="Magtoor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1421:description:1-180","1421:description:185-307","1421:description:310-351","1421:description:354-383","1421:objective:1-104"},["minimumStage"]=2,["questID"]=1421,["sourceHash"]="0100491f9d896ab15f0630b8ab130a10e746ddf692860ef03a1506a857eb77b9"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5476",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Watcher Biggs was stunned during a Lost One attack but saw a wagon dragged toward Fallow Sanctuary before losing consciousness. It carried reagents needed by Nethergarde's wizards.",["title"]="Watcher Biggs"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5863:description:1-64","5863:description:66-150","5863:description:152-256","5863:description:261-300","5863:description:302-349","5863:description:354-504","5863:objective:1-146"},["minimumStage"]=2,["questID"]=5863,["sourceHash"]="49d2c2bdfcf4dbc2a376bdecfebdc06cdcfa840e834d88cea97dd4624cb1dd8c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11758",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Andi Lynn feared the nomadic Dunemaul ogres would build a lasting force in Tanaris. She believed striking their leader Gor'marok would begin the compound's collapse.",["title"]="Andi Lynn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5863:description:1-64","5863:description:66-150","5863:description:152-256","5863:description:261-300","5863:description:302-349","5863:description:354-504","5863:objective:1-146"},["minimumStage"]=2,["questID"]=5863,["sourceHash"]="49d2c2bdfcf4dbc2a376bdecfebdc06cdcfa840e834d88cea97dd4624cb1dd8c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12046",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gor'marok the Ravager led the band of Dunemaul ogres that had recently occupied a broad stretch of Tanaris desert south of Gadgetzan.",["title"]="Gor'marok the Ravager"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8366:description:1-5","8366:description:7-39","8366:description:44-115","8366:description:118-209","8366:description:214-315","8366:description:317-396","8366:description:401-472","8366:description:475-502","8366:objective:1-179"},["minimumStage"]=2,["questID"]=8366,["sourceHash"]="bb5bc52a4a3a8194cf19eab8b4e24552b3e76bf999e2dd8241898951207b8367"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7882",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bilgewhizzle had to keep the peace at Steamwheedle while the cartel demanded action against Southsea pirates ignoring its protection payments. Deputizing outside help let him address both duties.",["title"]="Security Chief Bilgewhizzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8365:description:1-32","8365:description:34-53","8365:description:55-74","8365:description:76-163","8365:description:166-277","8365:description:280-340","8365:description:345-377","8365:description:379-463","8365:description:465-497","8365:objective:1-116"},["minimumStage"]=2,["questID"]=8365,["sourceHash"]="f4fe9c9a8df5b7844783c1b04961fe0583bd2b2cc3b273260722cd53fee7408d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15165",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Haughty Modiste procured fashionable apparel for wealthy customers and demanded pirate hats from Lost Rigger Cove. Her claims to dress Azeroth's rulers formed part of her own boastful salesmanship.",["title"]="Haughty Modiste"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2875:description:1-88","2875:description:93-234","2875:description:239-475","2875:objective:1-71"},["minimumStage"]=2,["questID"]=2875,["sourceHash"]="d92d5d88ddd21489a7c4ec8113832cc240a99d8a47eac2c1af06908432fbc66d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7883",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Andre Firebeard was wanted for crimes against Steamwheedle and Gadgetzan. The governing council authorized lethal force and named Bilgewhizzle as the recipient of the bounty proof.",["title"]="Andre Firebeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"173:description:1-44","173:description:46-104","173:description:106-163","173:description:168-206","173:description:211-232","173:description:234-304","173:description:306-365","173:description:370-488","173:objective:1-61"},["minimumStage"]=2,["questID"]=173,["sourceHash"]="5a1ea0ae215df1fc540b570c76dd87a71927a334ff5c32794f6913f57b441f1f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16167",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nightbane Shadow Weaver worgen occupied the Rotting Orchard and Brightwood Grove, where Calor sent would-be allies to prove themselves against the threat to Darkshire.",["title"]="The Rotting Orchard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"20:description:1-100","20:description:103-204","20:description:209-242","20:description:245-321","20:description:326-447","20:description:450-503","20:objective:1-56"},["minimumStage"]=2,["questID"]=20,["sourceHash"]="6e4ebe91765f1e6daa10ec8d6ce3f8c46a9323efe40a1ac1fada8d508a82b43b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-2099",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Blackrock orcs came from the Burning Steppes and seized Stonewatch Keep. Marris reported that raids launched from the captured position kept Lakeshire's residents penned in town.",["title"]="Stonewatch Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"169:description:1-7","169:description:9-116","169:description:122-156","169:description:159-277","169:description:280-328","169:description:331-443","169:objective:1-86"},["minimumStage"]=2,["questID"]=169,["sourceHash"]="4823df1fc8847c050c5966922c08a371c07c75cb84f3b04810ba688f1ee5541a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2099",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gath'Ilzogg led the Blackrock attack on the keep and the raids against Lakeshire; the town's wanted notice reported him sheltering within the captured stronghold.",["title"]="Stonewatch Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94:description:1-99","94:description:102-193","94:description:198-226","94:description:228-249","94:description:254-325","94:description:328-372","94:description:377-460","94:objective:1-81"},["minimumStage"]=2,["questID"]=94,["sourceHash"]="4d71889f9c4c99d6c7aa6fac59e944e533be455e84eaabe5b06b7fb651bdcc74"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-96",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Tower of Ilgalar housed Morganth. A nearby lion statue was the intended resting place of Theocritus's glyph, part of a magical effort to spy on the tower's occupant.",["title"]="Tower of Ilgalar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"249:description:1-59","249:description:64-126","249:description:129-228","249:description:233-319","249:description:322-378","249:description:383-429","249:description:432-474","249:objective:1-16","249:objective:21-101"},["minimumStage"]=2,["questID"]=249,["sourceHash"]="c678aed984412dad316027c5f70ebd91cf4e22386b1eb4b23831731a2d0f8230"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-96",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theocritus's warning connected Ilgalar to Morganth's search for the Scythe of Elune, though he remained uncertain whether the object had been found.",["title"]="Tower of Ilgalar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"427:description:1-115","427:description:118-178","427:description:183-221","427:description:224-271","427:description:274-363","427:description:368-509","427:objective:1-63"},["minimumStage"]=2,["questID"]=427,["sourceHash"]="d0e18c0727635879e5d46d07d10cc3895d30652d2862761a9e86093b70cddd48"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-156",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A tower west beyond Solliden Farmstead was one of the Scarlet positions identified by captured intelligence, the first target named in Zygand's renewed campaign.",["title"]="Solliden Farmstead"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4787:description:1-50","4787:description:53-159","4787:description:162-221","4787:description:226-254","4787:description:257-382","4787:objective:1-46"},["minimumStage"]=2,["questID"]=4787,["sourceHash"]="2a28491591be75f7ab10dbf673c8001e7215170c3153e9c9efc1a2d145dceab6"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-354",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="An amphitheater crowned Jintha'Alor; a cave behind it was the reported hiding place of an ancient egg from the era of the troll empires.",["title"]="Jintha'Alor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7850:description:1-48","7850:description:50-117","7850:description:122-188","7850:description:190-310","7850:description:315-435","7850:objective:1-122","7850:objective:124-176"},["minimumStage"]=2,["questID"]=7850,["sourceHash"]="0ee4b4a6f30f217e1c5ba716e534cdd32b9399aee3afc58ae87236a8737aa84b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-354",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vessels of tainted blood were scattered through the Vilebranch city. Torntusk blamed their magic for the inhabitants' unnatural ferocity and madness and sought to cleanse them.",["title"]="Jintha'Alor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7849:description:1-67","7849:description:69-167","7849:description:172-302","7849:description:307-372","7849:description:374-397","7849:objective:1-105","7849:objective:107-196","7849:objective:201-296","7849:objective:298-397","7849:objective:399-450"},["minimumStage"]=2,["questID"]=7849,["sourceHash"]="4a4ab15c5a3cd48508cee77143147bf724b95703762d471b8ebdd8f230e105be"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-354",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Near the temple's upper reaches, a refuse pit of oozes and a wolf den were the places Markhor named in the search for his executed brother's remains.",["title"]="Jintha'Alor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2995:description:1-88","2995:description:90-276","2995:description:278-349","2995:description:354-415","2995:description:420-450","2995:description:453-499","2995:description:501-510","2995:objective:1-136"},["minimumStage"]=2,["questID"]=2995,["sourceHash"]="19e5562cdd68fcc7d53ede0c575c05cf8781aed8770f648f9bdd9a54e7b4ac9f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-350",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Quel'Danil Lodge served as a communications center for the Hinterlands' high elves. Ambassadors kept records there while building alliances and sharing information about the Witherbark.",["title"]="Quel'Danil Lodge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2877:description:1-70","2877:description:73-143","2877:description:148-267","2877:description:270-355","2877:description:360-394","2877:description:397-491","2877:description:494-502","2877:objective:1-101"},["minimumStage"]=2,["questID"]=2877,["sourceHash"]="d7a0502d1f6a03d888b925aecd34bef841dc6c584302190a14f7e5e527aeed56"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-16036",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Horde had abandoned its positions around Skulk Rock, leaving sludges and oozes in control. Fraggar wanted the area cleared before Wildhammer plans for it could proceed.",["title"]="Skulk Rock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2937:description:1-113","2937:description:116-154","2937:objective:1-99"},["minimumStage"]=2,["questID"]=2937,["sourceHash"]="5c3ecbd8e9ec993290e4508aaa66817f04e01ca2387574e7149eb8cadf204d96"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-353",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shadra'Alor's altar, deep in Witherbark territory, was the place named for reading the parchment that would summon the spider god Shadra.",["title"]="Shadra'Alor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2934:description:1-55","2934:description:58-196","2934:description:199-260","2934:description:265-334","2934:objective:1-64"},["minimumStage"]=2,["questID"]=2934,["sourceHash"]="c36531929e2aa4b23ef42b1079b707fccb2db47f919bfce8ce8da85f52c8db46"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-353",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Spiders gathered near Shadra'Alor, supplying the fresh venom sacs sought for Lydon's apothecary research.",["title"]="Shadra'Alor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7839:description:1-55","7839:description:57-188","7839:description:193-248","7839:description:253-341","7839:description:346-409","7839:description:414-430","7839:objective:1-95","7839:objective:97-137","7839:objective:142-281","7839:objective:283-315"},["minimumStage"]=2,["questID"]=7839,["sourceHash"]="f4cb9066a73d4618e3135debe8725437a8920236aa291947b45351392e5796c4"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-16040",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shaol'watha and Agol'watha were northeastern Vilebranch temples named in Markhor's report on Slagtree's stolen tools. The report offered leads, not proof of which temple held them.",["title"]="Shaol'watha"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7839:description:1-55","7839:description:57-188","7839:description:193-248","7839:description:253-341","7839:description:346-409","7839:description:414-430","7839:objective:1-95","7839:objective:97-137","7839:objective:142-281","7839:objective:283-315"},["minimumStage"]=2,["questID"]=7839,["sourceHash"]="f4cb9066a73d4618e3135debe8725437a8920236aa291947b45351392e5796c4"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-16039",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Agol'watha was one of the northeastern Vilebranch temples where Slagtree's stolen tools might be found, together with Shaol'watha in the report he received.",["title"]="Agol'watha"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7845:description:1-79","7845:description:81-167","7845:description:169-270","7845:description:275-296","7845:description:298-343","7845:objective:1-119","7845:objective:124-269"},["minimumStage"]=2,["questID"]=7845,["sourceHash"]="4017e983314306a744d1de2d47f2a8eb58bc3e35a2650cd4d9cae1360a6d566c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-3317",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A midnight Vilebranch raid on Revantusk took Elder Torntusk prisoner, leaving Primal Torntusk seeking rescue before the threatened sacrifice at Jintha'Alor.",["title"]="Revantusk Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"663:description:1-20","663:description:22-52","663:description:57-81","663:description:84-138","663:description:141-206","663:description:211-272","663:description:275-321","663:description:324-368","663:description:371-409","663:description:414-491","663:objective:1-41"},["minimumStage"]=2,["questID"]=663,["sourceHash"]="df801e49d3944cb4730fad89d858936ce8d950271aa8a8bcdc1a1a39b682fdd0"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-327",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="O'Breen's formation reached Faldir's Cove for a treasure stop but lost the Spirit of Silverpine and Maiden's Folly. Lolo feared the wrecks would delay the return to Booty Bay.",["title"]="Faldir's Cove"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"644:description:1-100","644:description:102-178","644:description:180-286","644:objective:1-84"},["minimumStage"]=2,["questID"]=644,["sourceHash"]="c498f8ee0d0d6bdb632781d114fcd856debcc74fc9d62892987bc8d2c742a318"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-324",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stromgarde's militia-held district contained the chapel where Prince Galen held the last sigil needed to open Thoras Trollbane's tomb.",["title"]="Stromgarde Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"645:description:1-12","645:description:14-98","645:description:100-195","645:description:200-279","645:description:281-300","645:objective:1-56"},["minimumStage"]=2,["questID"]=645,["sourceHash"]="c65cf0e6fda3049fb29c19968ce6e1ae130611453883c36e87ba83b421ec4a78"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-324",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The sanctum behind Stromgarde's chapel held Trollbane's tomb and Trol'kalar. Four sigils were to be united to break its warding.",["title"]="Stromgarde Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"694:description:1-11","694:description:16-98","694:description:100-229","694:description:231-315","694:description:317-402","694:description:407-511","694:objective:1-71"},["minimumStage"]=2,["questID"]=694,["sourceHash"]="f22f4e0464f2195f2112130b5a7369287d3bf3f9449e13544f835e2db2f4f20d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-325",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Boulderfist ogres surrounded the Tower of Arathor. Gems taken by their shamans were needed to reactivate the tower's defenses and reach Trelane's possessions safely.",["title"]="The Tower of Arathor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"693:description:1-8","693:description:10-48","693:description:50-74","693:description:79-166","693:description:168-312","693:description:317-379","693:description:381-417","693:description:422-493","693:objective:1-76"},["minimumStage"]=2,["questID"]=693,["sourceHash"]="06c7cff386f5fe382153a0b2aa81c55f267ab6289a149249f542963c0db66957"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-316",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Boulderfist Hall lay south of Refuge Pointe and east of Thandol Span. Skuerto placed Kor'gresh and the stolen Wand of Invocation there.",["title"]="Boulderfist Hall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6570:description:1-134","6570:description:139-306","6570:description:311-386","6570:description:388-456","6570:objective:1-73","6570:objective:75-153"},["minimumStage"]=2,["questID"]=6570,["sourceHash"]="24f6133e5ff370a4b93975603eb5b862e3d399b3d7c5b3c81a65cb3054e2a706"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-511",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Emberstrife's den lay in Wyrmbog, the destination for a draconic disguise intended to gain an audience with Nefarian's gatekeeper.",["title"]="Wyrmbog"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1172:description:1-56","1172:description:58-116","1172:description:121-175","1172:description:177-212","1172:description:214-264","1172:description:269-358","1172:description:363-382","1172:description:384-414","1172:objective:1-71"},["minimumStage"]=2,["questID"]=1172,["sourceHash"]="ede75b30db890fb6b85529a7ce467b18e0a0a1192b75ea087eea27b7e1d68076"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-511",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Draz'Zilb directed the search for Onyxia's eggs toward southern Dustwallow's Wyrmbog, fearing the breeding grounds would prevent Stonemaul's reclamation.",["title"]="Wyrmbog"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1201:description:1-44","1201:description:47-175","1201:description:180-213","1201:description:218-288","1201:description:291-375","1201:description:380-420","1201:description:423-510","1201:objective:1-86"},["minimumStage"]=2,["questID"]=1201,["sourceHash"]="30c64ab5eeed36845b953fc600fc2ae2ca543d840bc36f92d9e7e3a56e5edec6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-496",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nazeer reported Alliance spies east of Brackenwall sending the village's movements to Theramore despite the uneasy truce.",["title"]="Brackenwall Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1389:description:1-88","1389:description:90-140","1389:description:143-252","1389:description:257-322","1389:description:327-475","1389:description:477-500","1389:objective:1-81"},["minimumStage"]=2,["questID"]=1389,["sourceHash"]="a980185ab6be116ef9bff33ca8df8c845f8f8480e10e5e24da7a052314e9e048"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-76",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Huts and campfires marked Fallow Sanctuary, where Magtoor said the Lost Ones kept the sacred draenethyst stolen from his people.",["title"]="Fallow Sanctuary"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1421:description:1-180","1421:description:185-307","1421:description:310-351","1421:description:354-383","1421:objective:1-104"},["minimumStage"]=2,["questID"]=1421,["sourceHash"]="0100491f9d896ab15f0630b8ab130a10e746ddf692860ef03a1506a857eb77b9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-76",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A wagon taken in the attack on Biggs's caravan was dragged toward Fallow Sanctuary, carrying reagents needed by Nethergarde's wizards.",["title"]="Fallow Sanctuary"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5863:description:1-64","5863:description:66-150","5863:description:152-256","5863:description:261-300","5863:description:302-349","5863:description:354-504","5863:objective:1-146"},["minimumStage"]=2,["questID"]=5863,["sourceHash"]="49d2c2bdfcf4dbc2a376bdecfebdc06cdcfa840e834d88cea97dd4624cb1dd8c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-983",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A recently arrived band of nomadic ogres established the Dunemaul Compound south of Gadgetzan, while smaller bands spread through the desert and old troll ruins.",["title"]="Dunemaul Compound"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8366:description:1-5","8366:description:7-39","8366:description:44-115","8366:description:118-209","8366:description:214-315","8366:description:317-396","8366:description:401-472","8366:description:475-502","8366:objective:1-179"},["minimumStage"]=2,["questID"]=8366,["sourceHash"]="bb5bc52a4a3a8194cf19eab8b4e24552b3e76bf999e2dd8241898951207b8367"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1336",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lost Rigger Cove sheltered Southsea pirates whose disregard for the cartel's protection payments prompted Bilgewhizzle's campaign from Steamwheedle.",["title"]="Lost Rigger Cove"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8365:description:1-32","8365:description:34-53","8365:description:55-74","8365:description:76-163","8365:description:166-277","8365:description:280-340","8365:description:345-377","8365:description:379-463","8365:description:465-497","8365:objective:1-116"},["minimumStage"]=2,["questID"]=8365,["sourceHash"]="f4fe9c9a8df5b7844783c1b04961fe0583bd2b2cc3b273260722cd53fee7408d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1336",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The pirates' hats drew a second kind of interest from Steamwheedle: Haughty Modiste wanted them for her trade in fashionable apparel.",["title"]="Lost Rigger Cove"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8366:description:1-5","8366:description:7-39","8366:description:44-115","8366:description:118-209","8366:description:214-315","8366:description:317-396","8366:description:401-472","8366:description:475-502","8366:objective:1-179"},["minimumStage"]=2,["questID"]=8366,["sourceHash"]="bb5bc52a4a3a8194cf19eab8b4e24552b3e76bf999e2dd8241898951207b8367"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-977",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keeping order at the port prevented Bilgewhizzle from leading the cartel's campaign against Lost Rigger himself, so he sought temporary deputies for the task.",["title"]="Steamwheedle Port"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2875:description:1-88","2875:description:93-234","2875:description:239-475","2875:objective:1-71"},["minimumStage"]=2,["questID"]=2875,["sourceHash"]="d92d5d88ddd21489a7c4ec8113832cc240a99d8a47eac2c1af06908432fbc66d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-977",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The port's Security Chief Bilgewhizzle handled the council's bounty on Andre Firebeard for crimes against Steamwheedle and Gadgetzan.",["title"]="Steamwheedle Port"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4243:description:1-69","4243:description:71-108","4243:description:110-235","4243:description:240-303","4243:description:305-398","4243:description:400-480","4243:description:485-509","4243:objective:1-31"},["minimumStage"]=2,["questID"]=4243,["sourceHash"]="a6c6c486f64488960025a5d4e0f719a317c815addbb67f414ad50d94cada6667"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9618",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Karna Remtravel built a mechanical ape to observe Un'Goro's apes from within their own company. Losing contact at Fungal Rock turned the experiment into a search for her missing invention.",["title"]="Karna Remtravel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4243:description:1-69","4243:description:71-108","4243:description:110-235","4243:description:240-303","4243:description:305-398","4243:description:400-480","4243:description:485-509","4243:objective:1-31"},["minimumStage"]=2,["questID"]=4243,["sourceHash"]="a6c6c486f64488960025a5d4e0f719a317c815addbb67f414ad50d94cada6667"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-9623",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A-Me 01 was a mechanical ape with scrying gems for eyes, designed to blend among Un'Goro's apes while transmitting what she saw to Karna.",["title"]="A-Me 01"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4243:description:1-69","4243:description:71-108","4243:description:110-235","4243:description:240-303","4243:description:305-398","4243:description:400-480","4243:description:485-509","4243:objective:1-31"},["minimumStage"]=2,["questID"]=4243,["sourceHash"]="a6c6c486f64488960025a5d4e0f719a317c815addbb67f414ad50d94cada6667"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-9623",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Karna's last view through A-Me's eyes showed an alpha male approaching at Fungal Rock, just before contact failed. The account did not establish what happened afterward.",["title"]="A-Me 01"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"974:description:1-51","974:description:53-82","974:description:87-208","974:description:210-324","974:description:326-374","974:description:379-472","974:objective:1-80","974:objective:85-167","974:objective:169-212"},["minimumStage"]=2,["questID"]=974,["sourceHash"]="5990713b2038ba5fd950a9963446397ec58af950c5a0944aad022f57250a8129"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10302",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krakle wondered whether Fire Plume Ridge heated the crater's nearby springs. He devised a thermometer to locate the volcano's hottest point and test that explanation.",["title"]="Krakle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3882:description:1-81","3882:description:84-133","3882:description:135-163","3882:description:168-278","3882:description:281-326","3882:description:329-418","3882:description:421-503","3882:objective:1-59"},["minimumStage"]=2,["questID"]=3882,["sourceHash"]="5b55b7324e002c9d598eb2d19c196fa5dcca67a969d71c3d326ae78c5d2dc1c8"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9272",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Spark Nilminer was chief digger for Marshal Expeditions, tasked with obtaining dinosaur bones from Terror Run despite his dislike of digging and the danger from living beasts.",["title"]="Spark Nilminer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9052:description:1-105","9052:description:108-192","9052:description:197-292","9052:description:295-412","9052:objective:1-90"},["minimumStage"]=2,["questID"]=9052,["sourceHash"]="151973476dd4f0fcb4cc65c2637d4cd04e5bc7e66cbd25c8a4e4c4ddaa7c3c10"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9619",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Torwa prepared a nonlethal toxin to pacify a great crater creature, using bloodcap mushrooms from bloodpetal sprouts and stings from the Gorishi insects near the Slithering Scar.",["title"]="Torwa Pathfinder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4505:description:1-45","4505:description:47-161","4505:description:166-271","4505:description:273-399","4505:description:404-460","4505:description:462-494","4505:objective:1-120"},["minimumStage"]=2,["questID"]=4505,["sourceHash"]="1a41002a00b0a94ff8d34b61d663d6c87df398bf92847d2ef7eba4dd86e38657"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9996",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Winna Hazzard sought any advantage for the Horde against the Alliance. Her interest in a corrupted moonwell was experimental: she wanted a sample for use on a nearby feline.",["title"]="Winna Hazzard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4421:description:1-31","4421:description:33-86","4421:description:91-189","4421:description:194-301","4421:description:303-421","4421:description:426-469","4421:description:471-511","4421:objective:1-88","4421:objective:90-159"},["minimumStage"]=2,["questID"]=4421,["sourceHash"]="e79343c55989f3d1f87ee7db2352032c40834b1d381a131c6fc4fb7ddaa5da7f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9454",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eridan Bluewind named Xavathras as the Jadefire leader at the Ruins of Constellas, accusing him and his followers of spreading Felwood's corruption to other creatures.",["title"]="Xavathras"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4421:description:1-31","4421:description:33-86","4421:description:91-189","4421:description:194-301","4421:description:303-421","4421:description:426-469","4421:description:471-511","4421:objective:1-88","4421:objective:90-159"},["minimumStage"]=2,["questID"]=4421,["sourceHash"]="e79343c55989f3d1f87ee7db2352032c40834b1d381a131c6fc4fb7ddaa5da7f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9116",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eridan belonged to the Emerald Circle and sought to heal Felwood. The Jadefire satyrs' deliberate spread of corruption made them an obstacle to that work.",["title"]="Eridan Bluewind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5157:description:1-86","5157:description:91-178","5157:description:180-294","5157:description:296-375","5157:description:380-464","5157:description:466-489","5157:objective:1-124"},["minimumStage"]=2,["questID"]=5157,["sourceHash"]="5447af1f574656f2e381ac0a09687d5ff1d210c966c42cb978315ec5833319b2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10922",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Greta wanted Shadow Hold's protective braziers extinguished so she could scry upon the Shadow Council and discover its leaders. Her request for Jaedenar's moonwell water was a step toward breaching that concealment.",["title"]="Greta Mosshoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4102:description:1-74","4102:description:77-173","4102:description:176-244","4102:description:249-286","4102:description:289-359","4102:description:362-488","4102:objective:1-55"},["minimumStage"]=2,["questID"]=4102,["sourceHash"]="4c05972e77864970d0833ec9c0faab73e1b67bcab78a375ef01f9f317d4e3803"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9529",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maybess Riverbreeze believed Irontree's Warpwood elementals were beyond cleansing, but hoped studying their blood amber would help save other forms of life in Felwood.",["title"]="Maybess Riverbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5086:description:1-122","5086:description:124-196","5086:description:201-392","5086:description:397-481","5086:objective:1-67"},["minimumStage"]=2,["questID"]=5086,["sourceHash"]="d01c60104955c52cf0ed6a2837219b13632ffd3cb2269b8cdecce730a7fe8af4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9298",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Donova suspected toxic material in a recovered sample and wanted droplets from Irontree's toxic horrors for comparison. Her belief that Deadwood furbolgs gathered it there remained a hypothesis.",["title"]="Donova Snowden"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5086:description:1-122","5086:description:124-196","5086:description:201-392","5086:description:397-481","5086:objective:1-67"},["minimumStage"]=2,["questID"]=5086,["sourceHash"]="d01c60104955c52cf0ed6a2837219b13632ffd3cb2269b8cdecce730a7fe8af4"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-7132",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Donova placed the toxic horrors among the corrupted elementals of Felwood's Irontree Woods, where their droplets could supply a comparison for her investigation.",["title"]="Toxic Horror"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4084:description:1-39","4084:description:44-135","4084:description:140-201","4084:description:203-265","4084:description:267-310","4084:description:315-321","4084:description:323-362","4084:description:364-397","4084:description:402-420","4084:description:422-510","4084:objective:1-77"},["minimumStage"]=2,["questID"]=4084,["sourceHash"]="63e9a262c48206c158ff48d5e3991161390d9e87a306e1a4e6c3de69f288120a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9376",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eridan described Blazerunner as an elemental within Un'Goro's heart, protected by a powerful aura. He offered to teach a means of overcoming it after obtaining ingredients from Felwood.",["title"]="Blazerunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4521:description:1-62","4521:description:64-83","4521:description:88-153","4521:description:155-228","4521:description:233-286","4521:description:291-459","4521:description:461-504","4521:objective:1-88"},["minimumStage"]=2,["questID"]=4521,["sourceHash"]="5feff277ad8d4144489d98cedcc32effd0b4192352bfb858c1b315b8276b13d8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10306",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Trull Failbane believed Winterspring's wildkin guarded night elf secrets and sought access to the land by clearing the owlbeasts. His claim about the hidden secrets was based on what he had heard.",["title"]="Trull Failbane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5160:description:1-23","5160:description:25-90","5160:description:92-148","5160:description:153-212","5160:description:214-320","5160:description:325-423","5160:objective:1-38","5160:objective:40-62"},["minimumStage"]=2,["questID"]=5160,["sourceHash"]="b1982e859e21d67d865c150af06ef541f7a25163441c9a9496e77bb3e92405de"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10929",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Haleh was the matron protectorate Awbee sought in Winterspring. His scale was to let her scry what he had seen and felt in his captivity.",["title"]="Haleh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5160:description:1-23","5160:description:25-90","5160:description:92-148","5160:description:153-212","5160:description:214-320","5160:description:325-423","5160:objective:1-38","5160:objective:40-62"},["minimumStage"]=2,["questID"]=5160,["sourceHash"]="b1982e859e21d67d865c150af06ef541f7a25163441c9a9496e77bb3e92405de"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10740",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Awbee explained that one of his scales, held while standing on Mazthoril's cobalt runes, would transport its bearer to Haleh.",["title"]="Awbee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5244:description:1-117","5244:description:122-277","5244:description:279-384","5244:description:389-501","5244:objective:1-49"},["minimumStage"]=2,["questID"]=5244,["sourceHash"]="c1389a605aebd8d8cebf3a1d45e431f210c69a2a4fff36b2259a9df8b03ed144"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11079",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wynd Nightchaser recounted Kel'Theril's Highborne stealing a sacred artifact to siphon its power. Its explosive destruction scattered fragments beneath the lake's ice and left the spirits bound to the site.",["title"]="Wynd Nightchaser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5245:description:1-63","5245:description:65-181","5245:description:186-311","5245:description:316-403","5245:description:405-502","5245:objective:1-60","5245:objective:62-115"},["minimumStage"]=2,["questID"]=5245,["sourceHash"]="1e8f221d094c1d5bbc52ae5f85048b5f2d355030414d1a094ad6b716ffb67c04"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10301",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jaron had investigated Kel'Theril and offered his pick for recovering the relic fragments below the ice. He directed their interpretation to Aurora rather than claiming to understand them himself.",["title"]="Jaron Stoneshaper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5248:description:1-45","5248:description:47-107","5248:description:109-254","5248:description:260-293","5248:description:298-358","5248:description:360-445","5248:description:447-499","5248:objective:1-116"},["minimumStage"]=2,["questID"]=5248,["sourceHash"]="dcaf5e75f76bdb08a37314309eac24296def905eff5ab3a55f554ca5b44e7efd"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10304",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aurora Skycaller saw the shattered crystal as an echo of the elves' own division. She sent the restored Crystal of Zin-Malor back to a repentant spirit at Kel'Theril as a small act of reconciliation with the past.",["title"]="Aurora Skycaller"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3510:description:1-30","3510:description:32-80","3510:description:82-107","3510:description:109-150","3510:description:155-244","3510:description:249-271","3510:description:273-294","3510:description:299-338","3510:objective:1-120"},["minimumStage"]=2,["questID"]=3510,["sourceHash"]="2fc0d529491ed77f967f9d1f6d28f84a27ad53330537f5f56b63cf73e210dd95"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6134",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lord Arkkoroc accused Hetaera of killing his children and falsely claiming rule over the oceans. His demand for her heads was tied to the name and knowledge he offered in return.",["title"]="Lord Arkkoroc"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3510:description:1-30","3510:description:32-80","3510:description:82-107","3510:description:109-150","3510:description:155-244","3510:description:249-271","3510:description:273-294","3510:description:299-338","3510:objective:1-120"},["minimumStage"]=2,["questID"]=3510,["sourceHash"]="2fc0d529491ed77f967f9d1f6d28f84a27ad53330537f5f56b63cf73e210dd95"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6140",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hetaera roamed the clutch southwest of Arkkoroc. He portrayed her as a rival claiming dominion over the sea and blamed her for the deaths of his children.",["title"]="Hetaera"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3510:description:1-30","3510:description:32-80","3510:description:82-107","3510:description:109-150","3510:description:155-244","3510:description:249-271","3510:description:273-294","3510:description:299-338","3510:objective:1-120"},["minimumStage"]=2,["questID"]=3510,["sourceHash"]="2fc0d529491ed77f967f9d1f6d28f84a27ad53330537f5f56b63cf73e210dd95"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-6140",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Arkkoroc's charge identified three separate heads to be brought back from Hetaera: bloodied, beaten and bruised. The account supplies that distinction without describing her coloration or size.",["title"]="Hetaera"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3449:description:1-57","3449:description:59-178","3449:description:180-237","3449:description:242-315","3449:description:317-402","3449:description:404-486","3449:objective:1-261"},["minimumStage"]=2,["questID"]=3449,["sourceHash"]="10c8978c78aba4e3e86d18668ee7199f495f1ecdbc3dbf88de41fdfd1ecf9ca6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8507",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tymor sought rubbings of the arcane runes in Eldarath for the Explorers' League, preserving the rules and discoveries ancient elven mages had set in public places.",["title"]="Tymor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3517:description:1-59","3517:description:61-111","3517:description:116-218","3517:description:223-332","3517:description:337-411","3517:description:413-455","3517:description:457-497","3517:objective:1-142"},["minimumStage"]=2,["questID"]=3517,["sourceHash"]="08b033702643a315ec811b21d43ba29a63fd64759740fa29172632642b74ba47"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8587",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jediga turned her punishment posting in Azshara toward profit, researching valuable relics and seeking four tablets named for Highborne wizards in Eldarath.",["title"]="Jediga"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5534:description:1-6","5534:description:8-13","5534:description:18-49","5534:description:51-94","5534:description:96-111","5534:description:113-126","5534:description:128-166","5534:description:168-303","5534:description:308-432","5534:description:434-481","5534:objective:1-116"},["minimumStage"]=2,["questID"]=5534,["sourceHash"]="899c492717afb2387832dcdd9f575d121d74f72c84b649b55f3f26343d4dae37"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8420",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kim'jael sent the search for a rune into naga-held Eldarath after hearing that blood elves wanted it. He framed the work as proof of an employee's value before offering greater rewards.",["title"]="Kim'jael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5535:description:1-108","5535:description:110-235","5535:description:237-262","5535:description:267-363","5535:description:365-427","5535:description:432-496","5535:objective:1-97"},["minimumStage"]=2,["questID"]=5535,["sourceHash"]="9ec60890f15faffa2d2f1a16c24e0410fe2c0aa95840186bdc93ac2e107ec808"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11548",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Loh'atu had promised the Sentinels to release restless spirits from their mortal bonds, and sought help with the apparitions and lichlings haunting Shadowsong Shrine.",["title"]="Loh'atu"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3823:description:1-55","3823:description:60-89","3823:description:94-167","3823:description:169-295","3823:description:300-319","3823:description:321-379","3823:description:384-437","3823:description:442-464","3823:objective:1-116"},["minimumStage"]=2,["questID"]=3823,["sourceHash"]="fcb7476f123532f38a3590f57cb3f6569cc7ebf33471f8fc526f5f058337b104"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9177",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Oralius wanted the Firegut ogres weakened because they guarded Dreadmaul Rock's mineral wealth and kept supply lines open for their Blackrock allies.",["title"]="Oralius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3824:description:1-27","3824:description:29-61","3824:description:66-105","3824:description:107-229","3824:description:234-357","3824:description:362-391","3824:description:393-432","3824:description:434-467","3824:description:472-486","3824:objective:1-55","3824:objective:57-146"},["minimumStage"]=2,["questID"]=3824,["sourceHash"]="eac2aab1d498400c32ab604b5b46238d21eb0a75457b2dc2327227bc3a233038"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-9176",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gor'tesh ruled from a Blackrock orc building west of Dreadmaul Rock, rather than from the rock itself, according to Oralius's instructions.",["title"]="Gor'tesh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3824:description:1-27","3824:description:29-61","3824:description:66-105","3824:description:107-229","3824:description:234-357","3824:description:362-391","3824:description:393-432","3824:description:434-467","3824:description:472-486","3824:objective:1-55","3824:objective:57-146"},["minimumStage"]=2,["questID"]=3824,["sourceHash"]="eac2aab1d498400c32ab604b5b46238d21eb0a75457b2dc2327227bc3a233038"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9176",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gor'tesh was the brute lord targeted in Oralius's second strike against the Firegut. Oralius wanted his head to prepare the next phase of the campaign.",["title"]="Gor'tesh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3701:description:1-112","3701:description:117-167","3701:description:169-215","3701:description:217-342","3701:objective:1-109","3701:objective:111-187"},["minimumStage"]=2,["questID"]=3701,["sourceHash"]="d1b48a5eff0e2ad2de3108d9c6f79b4aa0aa783e6a87104fc5f85fe0268c4d7f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8879",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Royal Historian Archesonus sought information from the mysterious relics among Thaurissan's ruins, warning that assassins protected the secrets still buried there.",["title"]="Royal Historian Archesonus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4243:description:1-69","4243:description:71-108","4243:description:110-235","4243:description:240-303","4243:description:305-398","4243:description:400-480","4243:description:485-509","4243:objective:1-31"},["minimumStage"]=2,["questID"]=4243,["sourceHash"]="a6c6c486f64488960025a5d4e0f719a317c815addbb67f414ad50d94cada6667"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-542",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fungal Rock was the Un'Goro apes' lair where Karna lost contact with A-Me 01 after an alpha male approached the disguised mechanical observer.",["title"]="Fungal Rock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"974:description:1-51","974:description:53-82","974:description:87-208","974:description:210-324","974:description:326-374","974:description:379-472","974:objective:1-80","974:objective:85-167","974:objective:169-212"},["minimumStage"]=2,["questID"]=974,["sourceHash"]="5990713b2038ba5fd950a9963446397ec58af950c5a0944aad022f57250a8129"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-537",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The volcanic ridge stood close to Un'Goro's hot springs. Krakle's temperature survey was intended to test whether the volcano supplied their heat.",["title"]="Fire Plume Ridge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3882:description:1-81","3882:description:84-133","3882:description:135-163","3882:description:168-278","3882:description:281-326","3882:description:329-418","3882:description:421-503","3882:objective:1-59"},["minimumStage"]=2,["questID"]=3882,["sourceHash"]="5b55b7324e002c9d598eb2d19c196fa5dcca67a969d71c3d326ae78c5d2dc1c8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-539",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marshal Expeditions sought stegodon and diemetradon remains in Terror Run, but living dinosaurs made the excavation hazardous. Spark was willing to accept bones from those beasts as well.",["title"]="Terror Run"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"9052:description:1-105","9052:description:108-192","9052:description:197-292","9052:description:295-412","9052:objective:1-90"},["minimumStage"]=2,["questID"]=9052,["sourceHash"]="151973476dd4f0fcb4cc65c2637d4cd04e5bc7e66cbd25c8a4e4c4ddaa7c3c10"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-540",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gorishi insects lived inside and around the southern crater's Slithering Scar. Their stings were ingredients in Torwa's proposed pacifying toxin.",["title"]="The Slithering Scar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4505:description:1-45","4505:description:47-161","4505:description:166-271","4505:description:273-399","4505:description:404-460","4505:description:462-494","4505:objective:1-120"},["minimumStage"]=2,["questID"]=4505,["sourceHash"]="1a41002a00b0a94ff8d34b61d663d6c87df398bf92847d2ef7eba4dd86e38657"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-15815",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jadefire satyrs tended a corrupted moonwell at Constellas. Winna's account said the former place of renewal was now used to bring forth more satyrs.",["title"]="Ruins of Constellas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4421:description:1-31","4421:description:33-86","4421:description:91-189","4421:description:194-301","4421:description:303-421","4421:description:426-469","4421:description:471-511","4421:objective:1-88","4421:objective:90-159"},["minimumStage"]=2,["questID"]=4421,["sourceHash"]="e79343c55989f3d1f87ee7db2352032c40834b1d381a131c6fc4fb7ddaa5da7f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-15815",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xavathras led the Jadefire at Constellas, where Eridan accused the satyrs of deliberately spreading the land's disease to creatures they encountered.",["title"]="Ruins of Constellas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5155:description:1-75","5155:description:80-188","5155:description:193-219","5155:description:221-272","5155:description:274-332","5155:description:337-422","5155:description:424-459","5155:description:461-503","5155:objective:1-154"},["minimumStage"]=2,["questID"]=5155,["sourceHash"]="c8a501ff11426aa12fa21fc4672f051cb4ab37d85693bdbc441a0aeb5d68a8ce"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-15813",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Shadow Council occupied corrupted barrow dens at Jaedenar and plotted there with the Burning Legion, in Greta Mosshoof's account.",["title"]="Jaedenar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5157:description:1-86","5157:description:91-178","5157:description:180-294","5157:description:296-375","5157:description:380-464","5157:description:466-489","5157:objective:1-124"},["minimumStage"]=2,["questID"]=5157,["sourceHash"]="5447af1f574656f2e381ac0a09687d5ff1d210c966c42cb978315ec5833319b2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-15813",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A moonwell stood at Jaedenar's center, while deeper Shadow Hold formed the main fortress of the enemy Greta sought to spy upon.",["title"]="Jaedenar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5157:description:1-86","5157:description:91-178","5157:description:180-294","5157:description:296-375","5157:description:380-464","5157:description:466-489","5157:objective:1-124"},["minimumStage"]=2,["questID"]=5157,["sourceHash"]="5447af1f574656f2e381ac0a09687d5ff1d210c966c42cb978315ec5833319b2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16362",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Protective spells linked to braziers concealed the Shadow Council's lair in Shadow Hold. Greta believed extinguishing them would permit her scrying to reveal its leadership.",["title"]="Shadow Hold"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4102:description:1-74","4102:description:77-173","4102:description:176-244","4102:description:249-286","4102:description:289-359","4102:description:362-488","4102:objective:1-55"},["minimumStage"]=2,["questID"]=4102,["sourceHash"]="4c05972e77864970d0833ec9c0faab73e1b67bcab78a375ef01f9f317d4e3803"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1768",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maybess judged the Warpwood elementals of Irontree Cavern beyond cleansing. Their blood amber was nevertheless sought for research into saving Felwood's remaining life.",["title"]="Irontree Cavern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5086:description:1-122","5086:description:124-196","5086:description:201-392","5086:description:397-481","5086:objective:1-67"},["minimumStage"]=2,["questID"]=5086,["sourceHash"]="d01c60104955c52cf0ed6a2837219b13632ffd3cb2269b8cdecce730a7fe8af4"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1767",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The woods held toxic horrors whose droplets Donova wanted to compare with suspect material associated with Deadwood furbolgs. She had not yet proved the link.",["title"]="Irontree Woods"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5160:description:1-23","5160:description:25-90","5160:description:92-148","5160:description:153-212","5160:description:214-320","5160:description:325-423","5160:objective:1-38","5160:objective:40-62"},["minimumStage"]=2,["questID"]=5160,["sourceHash"]="b1982e859e21d67d865c150af06ef541f7a25163441c9a9496e77bb3e92405de"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-2245",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cobalt runes lay on Mazthoril's icy cave floors. Awbee's instructions used his scale and those runes as the means of reaching the flight's matron, Haleh.",["title"]="Mazthoril"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5244:description:1-117","5244:description:122-277","5244:description:279-384","5244:description:389-501","5244:objective:1-49"},["minimumStage"]=2,["questID"]=5244,["sourceHash"]="c1389a605aebd8d8cebf3a1d45e431f210c69a2a4fff36b2259a9df8b03ed144"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-2252",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Highborne at Kel'Theril attempted to draw power from a stolen sacred relic. Its shattering explosion drove fragments under the lake's ice and left the spirits bound to the place.",["title"]="The Ruins of Kel'Theril"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5245:description:1-63","5245:description:65-181","5245:description:186-311","5245:description:316-403","5245:description:405-502","5245:objective:1-60","5245:objective:62-115"},["minimumStage"]=2,["questID"]=5245,["sourceHash"]="1e8f221d094c1d5bbc52ae5f85048b5f2d355030414d1a094ad6b716ffb67c04"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2251",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pieces of the stolen relic lay within Kel'Theril's ice while the spirits continued seeking them. Jaron's pick was offered for their recovery and examination by Aurora Skycaller.",["title"]="Lake Kel'Theril"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5248:description:1-45","5248:description:47-107","5248:description:109-254","5248:description:260-293","5248:description:298-358","5248:description:360-445","5248:description:447-499","5248:objective:1-116"},["minimumStage"]=2,["questID"]=5248,["sourceHash"]="dcaf5e75f76bdb08a37314309eac24296def905eff5ab3a55f554ca5b44e7efd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-2251",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aurora's attempt to make amends sent the restored Crystal of Zin-Malor back to the lake, seeking a Highborne spirit willing to recognize the ancient mistake.",["title"]="Lake Kel'Theril"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3510:description:1-30","3510:description:32-80","3510:description:82-107","3510:description:109-150","3510:description:155-244","3510:description:249-271","3510:description:273-294","3510:description:299-338","3510:objective:1-120"},["minimumStage"]=2,["questID"]=3510,["sourceHash"]="2fc0d529491ed77f967f9d1f6d28f84a27ad53330537f5f56b63cf73e210dd95"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1222",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hetaera roamed the clutch southwest of Lord Arkkoroc, whose grievance accused her of slaying his children and falsely claiming the oceans as her realm.",["title"]="Hetaera's Clutch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3449:description:1-57","3449:description:59-178","3449:description:180-237","3449:description:242-315","3449:description:317-402","3449:description:404-486","3449:objective:1-261"},["minimumStage"]=2,["questID"]=3449,["sourceHash"]="10c8978c78aba4e3e86d18668ee7199f495f1ecdbc3dbf88de41fdfd1ecf9ca6"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-1221",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eldarath preserved public tablets and runes in which powerful elven mages recorded arcane rules and discoveries, later sought as rubbings by the Explorers' League.",["title"]="Ruins of Eldarath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3517:description:1-59","3517:description:61-111","3517:description:116-218","3517:description:223-332","3517:description:337-411","3517:description:413-455","3517:description:457-497","3517:objective:1-142"},["minimumStage"]=2,["questID"]=3517,["sourceHash"]="08b033702643a315ec811b21d43ba29a63fd64759740fa29172632642b74ba47"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1221",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The tablets of Beth'Amara, Jin'yael, Markri and Sael'hai were named for Highborne wizards and became the objects of Jediga's profitable relic hunting.",["title"]="Ruins of Eldarath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5535:description:1-108","5535:description:110-235","5535:description:237-262","5535:description:267-363","5535:description:365-427","5535:description:432-496","5535:objective:1-97"},["minimumStage"]=2,["questID"]=5535,["sourceHash"]="9ec60890f15faffa2d2f1a16c24e0410fe2c0aa95840186bdc93ac2e107ec808"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1235",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Highborne apparitions and lichlings haunted Shadowsong Shrine. Loh'atu's promise to the Sentinels made releasing those spirits the purpose of the requested intervention.",["title"]="Shadowsong Shrine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3823:description:1-55","3823:description:60-89","3823:description:94-167","3823:description:169-295","3823:description:300-319","3823:description:321-379","3823:description:384-437","3823:description:442-464","3823:objective:1-116"},["minimumStage"]=2,["questID"]=3823,["sourceHash"]="fcb7476f123532f38a3590f57cb3f6569cc7ebf33471f8fc526f5f058337b104"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-249",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The mineral-rich rock was guarded by Firegut ogres allied with the Blackrock orcs, helping keep the orcs' supply lines open in the Burning Steppes.",["title"]="Dreadmaul Rock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3824:description:1-27","3824:description:29-61","3824:description:66-105","3824:description:107-229","3824:description:234-357","3824:description:362-391","3824:description:393-432","3824:description:434-467","3824:description:472-486","3824:objective:1-55","3824:objective:57-146"},["minimumStage"]=2,["questID"]=3824,["sourceHash"]="eac2aab1d498400c32ab604b5b46238d21eb0a75457b2dc2327227bc3a233038"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-249",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Firegut brute lord Gor'tesh was based in a Blackrock building west of Dreadmaul Rock, a distinction Oralius stressed when directing the attack on him.",["title"]="Dreadmaul Rock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3701:description:1-112","3701:description:117-167","3701:description:169-215","3701:description:217-342","3701:objective:1-109","3701:objective:111-187"},["minimumStage"]=2,["questID"]=3701,["sourceHash"]="d1b48a5eff0e2ad2de3108d9c6f79b4aa0aa783e6a87104fc5f85fe0268c4d7f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-250",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mysterious relics littered the smoldering ruins, while Thaurissan assassins guarded the secrets that Archesonus wanted investigated.",["title"]="Ruins of Thaurissan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5154:description:1-56","5154:description:59-147","5154:description:152-170","5154:description:173-221","5154:description:223-232","5154:objective:1-55"},["minimumStage"]=2,["questID"]=5154,["sourceHash"]="b85ed32692c2b78ced56c520a70ca8a40bbaa569753fff7b37ec205898bda53c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10667",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Chromie sought Joseph Redpath's past in the Annals of Darrowshire, believing that learning his fate might make it possible to change it.",["title"]="Chromie"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5721:description:1-87","5721:description:92-188","5721:description:191-358","5721:description:363-426","5721:description:429-479","5721:objective:1-54","5721:objective:59-116","5721:objective:121-188","5721:objective:193-221","5721:objective:226-336"},["minimumStage"]=2,["questID"]=5721,["sourceHash"]="7d275444d71be12ab7f4d28ac2cfad50810eaf6f53bbb5744118b6fc4df53030"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10667",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Chromie's ritual used a relic bundle to call Darrowshire's spirits into battle again. Its intended salvation required Davil's survival, Redpath's corruption and defeat, and a final meeting with Joseph's freed spirit.",["title"]="Chromie"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5721:description:1-87","5721:description:92-188","5721:description:191-358","5721:description:363-426","5721:description:429-479","5721:objective:1-54","5721:objective:59-116","5721:objective:121-188","5721:objective:193-221","5721:objective:226-336"},["minimumStage"]=2,["questID"]=5721,["sourceHash"]="7d275444d71be12ab7f4d28ac2cfad50810eaf6f53bbb5744118b6fc4df53030"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10936",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The rescue proposed for Joseph Redpath concerned his spirit: he was to survive long enough to become corrupted, then be defeated so that he could be freed and return to his daughter Pamela.",["title"]="Joseph Redpath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5181:description:1-63","5181:description:66-163","5181:description:166-255","5181:description:260-340","5181:description:343-402","5181:description:407-431","5181:description:434-491","5181:objective:1-101"},["minimumStage"]=2,["questID"]=5181,["sourceHash"]="f647db93e6b0eb22fadf462e41207796cd9970ad4d4cca82a7c86512211ab3d9"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-10939",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Annals named Marduk the Black among Darrowshire's villains. Unlike Horgus, he was not defeated in that battle, though his shattered sword was lost in the gorge west of Corin's Crossing.",["title"]="Marduk the Black"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5181:description:1-63","5181:description:66-163","5181:description:166-255","5181:description:260-340","5181:description:343-402","5181:description:407-431","5181:description:434-491","5181:objective:1-101"},["minimumStage"]=2,["questID"]=5181,["sourceHash"]="f647db93e6b0eb22fadf462e41207796cd9970ad4d4cca82a7c86512211ab3d9"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-10946",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The ghoul lord Horgus the Ravager was destroyed by Alliance defenders at Darrowshire. The Annals placed his discarded body in a lake northwest of Corin's Crossing, where his skull remained.",["title"]="Horgus the Ravager"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5721:description:1-87","5721:description:92-188","5721:description:191-358","5721:description:363-426","5721:description:429-479","5721:objective:1-54","5721:objective:59-116","5721:objective:121-188","5721:objective:193-221","5721:objective:226-336"},["minimumStage"]=2,["questID"]=5721,["sourceHash"]="7d275444d71be12ab7f4d28ac2cfad50810eaf6f53bbb5744118b6fc4df53030"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Davil Lightfire's survival beyond Horgus's death was one of the conditions Chromie set for the reawakened battle, linking his defense to the attempt to save Redpath's spirit.",["title"]="Davil Lightfire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5941:description:1-59","5941:description:62-129","5941:description:131-166","5941:description:171-262","5941:description:265-298","5941:description:303-380","5941:description:383-441","5941:objective:1-49"},["minimumStage"]=2,["questID"]=5941,["sourceHash"]="06e6448ed8c763e0c91d70cf535faf3f4329812ef1ab9d83ddeed7ca013fb110"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11063",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gathering Darrowshire's relics renewed Carlin's longing to protect his village from its fate. Chromie's promise of a possible rescue led him to send the assembled bundle to Andorhal.",["title"]="Carlin Redpath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5211:description:1-56","5211:description:59-117","5211:description:120-162","5211:description:167-226","5211:description:229-345","5211:description:350-460","5211:objective:1-57"},["minimumStage"]=2,["questID"]=5211,["sourceHash"]="eabf9de17fea88bc58db06798408a926269bf4aab547843ad8cda7fc0116a324"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11063",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Carlin believed many of Darrowshire's fallen defenders now served the Scourge as ghouls and flayers. His charge sought release for their souls rather than treating them as strangers to the village.",["title"]="Carlin Redpath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6136:description:1-123","6136:description:128-170","6136:description:172-196","6136:description:198-246","6136:description:251-363","6136:description:365-428","6136:objective:1-77","6136:objective:79-139"},["minimumStage"]=2,["questID"]=6136,["sourceHash"]="ad1faa7e84189d5883abd7f8e15a294302e7fc76bc7bf83bdd1232fd08891454"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-11896",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nathanos described Borelgore as an enormous maggot beast whose girth increased as it fed, a creature capable of devouring those who tried to hunt it.",["title"]="Borelgore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6136:description:1-123","6136:description:128-170","6136:description:172-196","6136:description:198-246","6136:description:251-363","6136:description:365-428","6136:objective:1-77","6136:objective:79-139"},["minimumStage"]=2,["questID"]=6136,["sourceHash"]="ad1faa7e84189d5883abd7f8e15a294302e7fc76bc7bf83bdd1232fd08891454"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-11896",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Borelgore was reported west of Northdale, beyond the Argent Dawn's encampment at Light's Hope in the northern Eastern Plaguelands.",["title"]="Borelgore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6136:description:1-123","6136:description:128-170","6136:description:172-196","6136:description:198-246","6136:description:251-363","6136:description:365-428","6136:objective:1-77","6136:objective:79-139"},["minimumStage"]=2,["questID"]=6136,["sourceHash"]="ad1faa7e84189d5883abd7f8e15a294302e7fc76bc7bf83bdd1232fd08891454"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="atlas-figure-nathanos-blightcaller",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nathanos claimed to have lost entire regiments to Borelgore. His order to hunt the creature carried both that military grievance and a warning about its appetite.",["title"]="Nathanos Blightcaller"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6145:description:1-91","6145:description:93-180","6145:description:182-236","6145:description:241-336","6145:description:338-405","6145:description:407-433","6145:description:435-483","6145:description:485-506","6145:objective:1-65","6145:objective:67-124","6145:objective:129-194"},["minimumStage"]=2,["questID"]=6145,["sourceHash"]="ca7fbd09d221c6d3d2c164a74053c8a0a3f6dd211d3110d0beda38c21cc9dbfa"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12337",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Crimson Courier carried a daily report from Scarlet central command to Tyr's Hand, a communications link Varimathras wanted intercepted to undermine Stratholme's guarded leadership.",["title"]="Crimson Courier"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6148:description:1-48","6148:description:50-107","6148:description:109-200","6148:description:205-349","6148:description:351-390","6148:description:395-434","6148:description:436-487","6148:description:489-508","6148:objective:1-35","6148:objective:37-145","6148:objective:147-173","6148:objective:175-225"},["minimumStage"]=2,["questID"]=6148,["sourceHash"]="66a96c84d11090ba68ce7b7ac9bf7e8a7a12bbc9f4c56f5d7a974db54e7f80cd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12339",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Demetria was chief adviser to the Grand Crusader, called the Scarlet Oracle for her reputed otherworldly senses. Nathanos credited her help in victories over the Scourge without claiming her psychic powers were proven.",["title"]="Demetria"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6148:description:1-48","6148:description:50-107","6148:description:109-200","6148:description:205-349","6148:description:351-390","6148:description:395-434","6148:description:436-487","6148:description:489-508","6148:objective:1-35","6148:objective:37-145","6148:objective:147-173","6148:objective:175-225"},["minimumStage"]=2,["questID"]=6148,["sourceHash"]="66a96c84d11090ba68ce7b7ac9bf7e8a7a12bbc9f4c56f5d7a974db54e7f80cd"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-12339",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Demetria and her entourage were expected on the road from Tyr's Hand to Stratholme after Nathanos's deception drew them out.",["title"]="Demetria"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6145:description:1-91","6145:description:93-180","6145:description:182-236","6145:description:241-336","6145:description:338-405","6145:description:407-433","6145:description:435-483","6145:description:485-506","6145:objective:1-65","6145:objective:67-124","6145:objective:129-194"},["minimumStage"]=2,["questID"]=6145,["sourceHash"]="ca7fbd09d221c6d3d2c164a74053c8a0a3f6dd211d3110d0beda38c21cc9dbfa"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2425",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Varimathras judged Stratholme's Scarlet command too well defended for a direct strike. Intercepting the report to Tyr's Hand was meant to expose the wider organization instead.",["title"]="Varimathras"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5845:description:1-72","5845:description:77-117","5845:description:119-186","5845:description:191-255","5845:description:260-369","5845:description:371-427","5845:description:432-498","5845:objective:1-113","5845:objective:115-174"},["minimumStage"]=2,["questID"]=5845,["sourceHash"]="3c5cf5179f3921f883601e9f43d0b9803ea57699b15b8d643b0eb48819d15f54"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1855",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tirion recalled Taelan's final stand at Northdale after Uther's death and the Silver Hand's destruction. Believing the order lost, Taelan cast down its standard and renounced his former allegiance.",["title"]="Tirion Fordring"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5461:description:1-51","5461:description:53-181","5461:description:186-338","5461:description:343-442","5461:description:444-468","5461:objective:1-59","5461:objective:61-108","5461:objective:110-172"},["minimumStage"]=2,["questID"]=5461,["sourceHash"]="8e97d3b385045ccefceeddec9227ef9c389d8f481ddb722ac9c58793a68177cf"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-10508",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marduke identified Stromgarde as Ras Frostwhisper's home in life and sought a surviving keepsake from those mortal years as the basis for undoing his lich form.",["title"]="Ras Frostwhisper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5466:description:1-36","5466:description:38-86","5466:description:91-172","5466:description:175-248","5466:description:250-276","5466:description:281-338","5466:description:340-381","5466:description:383-422","5466:objective:1-41","5466:objective:43-115","5466:objective:117-228","5466:objective:230-270"},["minimumStage"]=2,["questID"]=5466,["sourceHash"]="8a9a6f1c34ee9953fa4da45f69e0f0cf0f0eb7995c30faef52c45b82174a5ed8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10508",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marduke's plan required a Soulbound Keepsake used against Ras in Scholomance until the lich became mortal. Only then was the final blow intended; the instructions do not establish that the ritual succeeded for any particular traveler.",["title"]="Ras Frostwhisper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5461:description:1-51","5461:description:53-181","5461:description:186-338","5461:description:343-442","5461:description:444-468","5461:objective:1-59","5461:objective:61-108","5461:objective:110-172"},["minimumStage"]=2,["questID"]=5461,["sourceHash"]="8e97d3b385045ccefceeddec9227ef9c389d8f481ddb722ac9c58793a68177cf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11286",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magistrate Marduke believed a remnant of Ras's mortal life could anchor an artifact to reverse his undeath, despite the tendency of sentient undead to destroy such reminders.",["title"]="Magistrate Marduke"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5721:description:1-87","5721:description:92-188","5721:description:191-358","5721:description:363-426","5721:description:429-479","5721:objective:1-54","5721:objective:59-116","5721:objective:121-188","5721:objective:193-221","5721:objective:226-336"},["minimumStage"]=2,["questID"]=5721,["sourceHash"]="7d275444d71be12ab7f4d28ac2cfad50810eaf6f53bbb5744118b6fc4df53030"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16033",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The town square was the place appointed for Chromie's relic bundle, which would call up the battle's spirits for an attempt to save Joseph Redpath's soul.",["title"]="Darrowshire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5211:description:1-56","5211:description:59-117","5211:description:120-162","5211:description:167-226","5211:description:229-345","5211:description:350-460","5211:objective:1-57"},["minimumStage"]=2,["questID"]=5211,["sourceHash"]="eabf9de17fea88bc58db06798408a926269bf4aab547843ad8cda7fc0116a324"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-16033",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Many defenders who fell at Darrowshire were said to roam again in the Scourge's ghoul and flayer bodies. Carlin sought their release in Plaguewood, Corin's Crossing and other strongholds.",["title"]="Darrowshire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5154:description:1-56","5154:description:59-147","5154:description:152-170","5154:description:173-221","5154:description:223-232","5154:objective:1-55"},["minimumStage"]=2,["questID"]=5154,["sourceHash"]="b85ed32692c2b78ced56c520a70ca8a40bbaa569753fff7b37ec205898bda53c"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-193",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Andorhal's city hall held the Annals of Darrowshire, the historical account Chromie needed to investigate Joseph Redpath's fate.",["title"]="Ruins of Andorhal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5941:description:1-59","5941:description:62-129","5941:description:131-166","5941:description:171-262","5941:description:265-298","5941:description:303-380","5941:description:383-441","5941:objective:1-49"},["minimumStage"]=2,["questID"]=5941,["sourceHash"]="06e6448ed8c763e0c91d70cf535faf3f4329812ef1ab9d83ddeed7ca013fb110"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-193",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Chromie waited in Andorhal's ruined inn for the gathered Darrowshire relics, the reagents for her proposed intervention in the village's fate.",["title"]="Ruins of Andorhal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5181:description:1-63","5181:description:66-163","5181:description:166-255","5181:description:260-340","5181:description:343-402","5181:description:407-431","5181:description:434-491","5181:objective:1-101"},["minimumStage"]=2,["questID"]=5181,["sourceHash"]="f647db93e6b0eb22fadf462e41207796cd9970ad4d4cca82a7c86512211ab3d9"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2264",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Darrowshire's villain relics were scattered near Corin's Crossing: Horgus's skull in the lake to the northwest and Marduk's shattered sword in the gorge to the west.",["title"]="Corin's Crossing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5211:description:1-56","5211:description:59-117","5211:description:120-162","5211:description:167-226","5211:description:229-345","5211:description:350-460","5211:objective:1-57"},["minimumStage"]=2,["questID"]=5211,["sourceHash"]="eabf9de17fea88bc58db06798408a926269bf4aab547843ad8cda7fc0116a324"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2264",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ghouls and flayers around Corin's Crossing included former Darrowshire defenders, according to Carlin's appeal to release their spirits.",["title"]="Corin's Crossing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5211:description:1-56","5211:description:59-117","5211:description:120-162","5211:description:167-226","5211:description:229-345","5211:description:350-460","5211:objective:1-57"},["minimumStage"]=2,["questID"]=5211,["sourceHash"]="eabf9de17fea88bc58db06798408a926269bf4aab547843ad8cda7fc0116a324"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2277",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Carlin placed some of Darrowshire's fallen defenders among the Scourge ghouls and flayers in Plaguewood, making release of those souls part of the struggle there.",["title"]="Plaguewood"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5206:description:1-164","5206:description:169-230","5206:description:233-360","5206:description:363-395","5206:description:409-504","5206:objective:1-90"},["minimumStage"]=2,["questID"]=5206,["sourceHash"]="dcfa45ab0c182c7ef7a2af55714d5574bcc6d044ffbada3945bab19768a0fe30"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-2270",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scourge champions in the Noxious Glade were sought for skulls that could resonate with Chromie's crystal if they had fought at Darrowshire.",["title"]="The Noxious Glade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5206:description:1-164","5206:description:169-230","5206:description:233-360","5206:description:363-395","5206:description:409-504","5206:objective:1-90"},["minimumStage"]=2,["questID"]=5206,["sourceHash"]="dcfa45ab0c182c7ef7a2af55714d5574bcc6d044ffbada3945bab19768a0fe30"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-2258",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Fungal Vale was another hunting ground for the champions whose skulls might retain a magical connection to Darrowshire's battle, needed for Chromie's ritual.",["title"]="The Fungal Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5845:description:1-72","5845:description:77-117","5845:description:119-186","5845:description:191-255","5845:description:260-369","5845:description:371-427","5845:description:432-498","5845:objective:1-113","5845:objective:115-174"},["minimumStage"]=2,["questID"]=5845,["sourceHash"]="3c5cf5179f3921f883601e9f43d0b9803ea57699b15b8d643b0eb48819d15f54"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-2272",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="At the war-torn hamlet of Northdale, Taelan made a final stand before throwing down the Silver Hand's standard. Tirion sought that abandoned symbol as a means of reaching his son's lost honor.",["title"]="Northdale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6145:description:1-91","6145:description:93-180","6145:description:182-236","6145:description:241-336","6145:description:338-405","6145:description:407-433","6145:description:435-483","6145:description:485-506","6145:objective:1-65","6145:objective:67-124","6145:objective:129-194"},["minimumStage"]=2,["questID"]=6145,["sourceHash"]="ca7fbd09d221c6d3d2c164a74053c8a0a3f6dd211d3110d0beda38c21cc9dbfa"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-16370",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A daily courier brought commands from Scarlet central leadership to Tyr's Hand. That route became the target of the Deathstalkers' effort to weaken the Crusade beyond Stratholme's walls.",["title"]="Tyr's Hand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6148:description:1-48","6148:description:50-107","6148:description:109-200","6148:description:205-349","6148:description:351-390","6148:description:395-434","6148:description:436-487","6148:description:489-508","6148:objective:1-35","6148:objective:37-145","6148:objective:147-173","6148:objective:175-225"},["minimumStage"]=2,["questID"]=6148,["sourceHash"]="66a96c84d11090ba68ce7b7ac9bf7e8a7a12bbc9f4c56f5d7a974db54e7f80cd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16370",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The road from Tyr's Hand to Stratholme was the expected route of Demetria's entourage when Nathanos's ruse exposed the Scarlet Oracle to attack.",["title"]="Tyr's Hand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5741:description:1-117","5741:description:119-199","5741:description:201-260","5741:description:265-316","5741:description:319-423","5741:objective:1-91"},["minimumStage"]=2,["questID"]=5741,["sourceHash"]="63a54de4adf1efe2ad2604acdc16b2a9cc89a8c9c6d3150c9f6904d9c6db3bc3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11863",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Azore Aldamort feared the Burning Blade's rumored acquisition of the Sceptre of Light. Legends said it could sink cities, making its retrieval urgent without proving the legend true.",["title"]="Azore Aldamort"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5741:description:1-117","5741:description:119-199","5741:description:201-260","5741:description:265-316","5741:description:319-423","5741:objective:1-91"},["minimumStage"]=2,["questID"]=5741,["sourceHash"]="63a54de4adf1efe2ad2604acdc16b2a9cc89a8c9c6d3150c9f6904d9c6db3bc3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13019",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A Burning Blade seer studied the Sceptre of Light atop one of Thunder Axe Fortress's watchtowers, the custodian named in Azore's retrieval instructions.",["title"]="Burning Blade Seer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5381:description:1-42","5381:description:44-86","5381:description:88-155","5381:description:157-211","5381:description:216-310","5381:objective:1-131"},["minimumStage"]=2,["questID"]=5381,["sourceHash"]="bc6580a2b6be2fa4ffb2c78314460ff2087efaf72111a3befcb07cda05d9e062"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11624",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Taiga Wisemane sought the Demon Box because its Hand of Iruxos enabled the Burning Blade to open portals at Mannoroc Coven. Stemming the demons required first obtaining that tool.",["title"]="Taiga Wisemane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5581:description:1-28","5581:description:30-53","5581:description:58-137","5581:description:139-172","5581:description:174-277","5581:description:279-294","5581:description:296-331","5581:objective:1-86"},["minimumStage"]=2,["questID"]=5581,["sourceHash"]="b79a558245ab05af774173b13958f52bcb3a61ee860a140afd8c03b3650f41c8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11624",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Taiga's plan used the Hand of Iruxos to banish Mannoroc's portals, with a warning that their guardians remained dangerous even once the means of closing them was secured.",["title"]="Taiga Wisemane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1954:description:1-47","1954:description:50-114","1954:description:116-159","1954:description:162-193","1954:description:198-269","1954:description:272-315","1954:description:320-355","1954:objective:1-53"},["minimumStage"]=2,["questID"]=1954,["sourceHash"]="124d8c813bdaabf6ebd33df72586883a26fb0c95ca7589397e0b9170e9c3958e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4668",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Burning Blade summoners at Mannoroc possessed infernal orbs with demons bound inside, making them the source Tabetha named for an orb she hoped to cleanse.",["title"]="Burning Blade Summoner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1954:description:1-47","1954:description:50-114","1954:description:116-159","1954:description:162-193","1954:description:198-269","1954:description:272-315","1954:description:320-355","1954:objective:1-53"},["minimumStage"]=2,["questID"]=1954,["sourceHash"]="124d8c813bdaabf6ebd33df72586883a26fb0c95ca7589397e0b9170e9c3958e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6546",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tabetha wanted an orb of sufficient power and judged the Burning Blade's vessels suitable despite their imprisoned demons, believing the corruption could be remedied.",["title"]="Tabetha"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1799:description:1-26","1799:description:31-89","1799:description:91-150","1799:description:155-258","1799:description:260-368","1799:description:370-418","1799:description:423-489","1799:objective:1-98","1799:objective:103-167"},["minimumStage"]=2,["questID"]=1799,["sourceHash"]="25fd7f7a74c463ba4afbd90189d83ba3b0dbc89ce541b49afc8f1a8d104e3608"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Menara sent the chosen bearer of an infernal orb to Tabetha in southern Dustwallow, relying on their shared history for the mage's help in cleansing it.",["title"]="Menara Voidrender"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1432:description:1-148","1432:description:150-190","1432:description:192-261","1432:description:266-362","1432:description:364-451","1432:description:453-496","1432:objective:1-39"},["minimumStage"]=2,["questID"]=1432,["sourceHash"]="584bee312191ade9ccc90bb19b09230b22e195d8912eaab5ba9185ec5bbf173c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5640",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keldran wanted demonic forces removed from Desolace partly to prevent advancing Alliance observers from mistaking their presence for a Horde pact with the Legion.",["title"]="Keldran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5501:description:1-58","5501:description:61-103","5501:description:105-195","5501:description:200-300","5501:description:303-419","5501:description:422-434","5501:objective:1-82"},["minimumStage"]=2,["questID"]=5501,["sourceHash"]="496d642a957817a19917074bbcbf7b0fc1aca4297641ddedcc0e4bb58ba8c45a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11438",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bibbly F'utzbuckle saw commercial promise in kodo bones used for furniture, musical instruments and blasting powder. A caravan carried his stock to Shadowprey for sale.",["title"]="Bibbly F'utzbuckle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6132:description:1-19","6132:description:24-83","6132:description:86-136","6132:description:138-165","6132:description:168-195","6132:description:200-258","6132:description:261-317","6132:description:322-337","6132:description:340-428","6132:objective:1-96"},["minimumStage"]=2,["questID"]=6132,["sourceHash"]="2c339373249a2ab1c11ed39871de6ac2f4dfda6d43ef411fb6a6411aff77ec82"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-12277",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Melizza entered the Valley of Spears hoping to trade with the Maraudines, but found herself a captive fearing their cookpot instead. She offered her brother's payment for an escort out.",["title"]="Melizza Brimbuzzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6132:description:1-19","6132:description:24-83","6132:description:86-136","6132:description:138-165","6132:description:168-195","6132:description:200-258","6132:description:261-317","6132:description:322-337","6132:description:340-428","6132:objective:1-96"},["minimumStage"]=2,["questID"]=6132,["sourceHash"]="2c339373249a2ab1c11ed39871de6ac2f4dfda6d43ef411fb6a6411aff77ec82"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6019",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hornizz Brimbuzzle was Melizza's brother, camped beside the Kodo Graveyard east of her captivity. She named him as the person who would reward her rescue.",["title"]="Hornizz Brimbuzzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1367:description:1-59","1367:description:62-156","1367:description:161-231","1367:description:234-277","1367:description:280-406","1367:objective:1-66"},["minimumStage"]=2,["questID"]=1367,["sourceHash"]="38e7fe5819cfe974b47081526a8b246d6b2217efaabb3191a508dc796422caf7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5398",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Warug was the Magram spokesman on the edge of their southeastern Desolace village, approached by outsiders who had earned the clan's favor by opposing the Gelkis.",["title"]="Warug"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1367:description:1-59","1367:description:62-156","1367:description:161-231","1367:description:234-277","1367:description:280-406","1367:objective:1-66"},["minimumStage"]=2,["questID"]=1367,["sourceHash"]="38e7fe5819cfe974b47081526a8b246d6b2217efaabb3191a508dc796422caf7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5412",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gurda proposed exploiting the centaur clans' hatred through a temporary alliance, learning their weaknesses by gaining the Magram's trust against the Gelkis.",["title"]="Gurda Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1382:description:1-129","1382:description:132-188","1382:description:193-273","1382:description:276-355","1382:description:360-448","1382:description:451-506","1382:objective:1-75"},["minimumStage"]=2,["questID"]=1382,["sourceHash"]="b22490daafdc1769d5b41c607c0ca46812b5f2eb13c0b23602b189472e593981"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5396",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pentigast feared the strength of a united centaur force and sought advantage in the Gelkis-Magram war. An approach to Uthek depended on first demonstrating hostility to the Magram.",["title"]="Captain Pentigast"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1373:description:1-118","1373:description:123-174","1373:description:177-214","1373:description:217-269","1373:description:272-336","1373:description:341-406","1373:description:409-489","1373:objective:1-124"},["minimumStage"]=2,["questID"]=1373,["sourceHash"]="8da0019cace26c99fbd08c3fc40137cfbe558fbbe8d254a2f45299dcdf1595ea"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5397",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Uthek sought a draenethyst shard to strengthen her magic, following what she described as the earth's whispered knowledge to Ongeku in the Swamp of Sorrows.",["title"]="Uthek the Wise"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1370:description:1-41","1370:description:44-113","1370:description:118-148","1370:description:151-211","1370:description:214-312","1370:objective:1-75"},["minimumStage"]=2,["questID"]=1370,["sourceHash"]="490285d8543c151e49f83cfa5daeb2cc19972fc25c090d2c8cd1c5938304c6af"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5397",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Uthek treated food stores as a military resource. Raiding the Magram's dried meat would shorten the time they could fight between hunts and weaken their resistance.",["title"]="Uthek the Wise"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1373:description:1-118","1373:description:123-174","1373:description:177-214","1373:description:217-269","1373:description:272-336","1373:description:341-406","1373:description:409-489","1373:objective:1-124"},["minimumStage"]=2,["questID"]=1373,["sourceHash"]="8da0019cace26c99fbd08c3fc40137cfbe558fbbe8d254a2f45299dcdf1595ea"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5622",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ongeku was the Lost One holding the draenethyst shard Uthek wanted, connecting the Gelkis' local struggle in Desolace to a journey across the sea to the Swamp of Sorrows.",["title"]="Ongeku"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2987:description:1-130","2987:description:132-205","2987:description:207-318","2987:description:323-367","2987:description:369-444","2987:description:446-488","2987:objective:1-67"},["minimumStage"]=2,["questID"]=2987,["sourceHash"]="217678eddd5af90225d60a8f32077ae82ebe92b585ab974627766dee74348953"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8021",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Newly arrived Orwin Gizzmick wanted to investigate the minerals the Gordunni buried. A blue glow marked the cobalt deposits for the shovel he offered.",["title"]="Orwin Gizzmick"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2978:description:1-104","2978:description:106-190","2978:objective:1-55"},["minimumStage"]=2,["questID"]=2978,["sourceHash"]="3fd1034adfee6c2acc4832e6ca5bde06a6bfe7509192e273f7936bedb32191ee"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7777",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A soiled Gordunni scroll appeared to show a meeting or ceremony. Rok Orhan was its intended interpreter, while the meaning remained uncertain at the moment of discovery.",["title"]="Rok Orhan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2982:description:1-107","2982:description:112-213","2982:description:215-325","2982:description:330-435","2982:description:437-507","2982:objective:1-99"},["minimumStage"]=2,["questID"]=2982,["sourceHash"]="3b761e33fb9aa7d61f8aba940039a1e86dfef18526f87183b6fd73dfd3c0dc05"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7900",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Angelas and Troyas investigated Feralas's forest ruins together. Troyas's solitary trips into the Gordunni-held High Wilderness left Angelas seeking help to make the ruins safer for him.",["title"]="Angelas Moonbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2969:description:1-59","2969:description:61-158","2969:description:163-279","2969:description:284-431","2969:description:433-469","2969:description:471-495","2969:objective:1-86","2969:objective:88-148","2969:objective:153-238"},["minimumStage"]=2,["questID"]=2969,["sourceHash"]="b8075775f0827a5a4a612f70c19d35145e01bd6d3ae6c5ad17306e7b59b7a244"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7956",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kindal and Jer'kai did not know why the Grimtotem were capturing faerie dragons. Kindal offered to fight beside those opening the bamboo pen, making the creatures' survival the purpose of the rescue.",["title"]="Kindal Moonweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5064:description:1-86","5064:description:88-135","5064:description:137-222","5064:description:224-308","5064:description:313-384","5064:objective:1-65"},["minimumStage"]=2,["questID"]=5064,["sourceHash"]="6649b11206493fc8f7167af0712af3821c9c7a1e0576333eef586dbd28a775fd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10537",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cliffwatcher Longhorn sought three guarded messages after unfamiliar agents visited the Grimtotem, believing the chests at Darkcloud Pinnacle could explain the secret activity.",["title"]="Cliffwatcher Longhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6548:description:1-62","6548:description:64-117","6548:description:122-170","6548:description:172-215","6548:objective:1-131"},["minimumStage"]=2,["questID"]=6548,["sourceHash"]="33a9b8d2daf6c186593e41d08e8d0598b909ec0c87e4ae42ca81979c3b3df35b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11857",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Makaba Flathoof survived a Grimtotem raid that killed most of his village. His injuries and narrow escape left him seeking vengeance against the nearby attackers.",["title"]="Makaba Flathoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2902:description:1-132","2902:description:135-232","2902:description:237-332","2902:description:335-427","2902:description:430-476","2902:objective:1-86"},["minimumStage"]=2,["questID"]=2902,["sourceHash"]="e6c4df369e36d54af5ea92530dd86c05428750d2b95cf1179569d2ccaec08698"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7875",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hadoken suspected the Woodpaws' coordinated attacks depended on written plans. Recovering those plans could explain the gnolls' recent agitation rather than merely answer it with force.",["title"]="Hadoken Swiftstrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4131:description:1-112","4131:description:115-161","4131:description:166-399","4131:description:402-503","4131:objective:1-115"},["minimumStage"]=2,["questID"]=4131,["sourceHash"]="2a8a91865c77ff8661154226b25e695e7635fcb6e335c5f0c8303021fd4e0b78"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7880",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ginro considered the Woodpaw camps the best lead for Raschal's belongings but doubted the gnolls had necessarily killed him. Quint's vision prompted a more determined search for the missing courier's packs.",["title"]="Ginro Hearthkindle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2870:description:1-80","2870:description:83-173","2870:description:178-251","2870:description:254-415","2870:description:420-504","2870:objective:1-124"},["minimumStage"]=2,["questID"]=2870,["sourceHash"]="3ba94cd6cb879f44bf9041b2c56f96317b98201f3b2ff1e5524372647765c73e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-8136",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scouts identified Lord Shalzaru as one of the naga royals directing their forces. His recent excavation uncovered an odd relic that Latronicus wanted recovered for study.",["title"]="Lord Shalzaru"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2870:description:1-80","2870:description:83-173","2870:description:178-251","2870:description:254-415","2870:description:420-504","2870:objective:1-124"},["minimumStage"]=2,["questID"]=2870,["sourceHash"]="3ba94cd6cb879f44bf9041b2c56f96317b98201f3b2ff1e5524372647765c73e"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-8136",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shalzaru's reported excavation was in a cave south of the main ruins, across the water on the Isle of Dread, in the directions given by Latronicus.",["title"]="Lord Shalzaru"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8585:description:1-121","8585:description:123-235","8585:description:240-320","8585:description:322-351","8585:description:353-426","8585:description:431-506","8585:objective:1-89"},["minimumStage"]=2,["questID"]=8585,["sourceHash"]="6733dbfce28a710a1422cf66e3c0c59beac288f69e15ecc6f9ea4b308d60434f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12803",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dirge called Lord Lakmaeran the great progenitor among the Isle of Dread's chimaerok and wanted his carcass for a culinary commission.",["title"]="Lord Lakmaeran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8585:description:1-121","8585:description:123-235","8585:description:240-320","8585:description:322-351","8585:description:353-426","8585:description:431-506","8585:objective:1-89"},["minimumStage"]=2,["questID"]=8585,["sourceHash"]="6733dbfce28a710a1422cf66e3c0c59beac288f69e15ecc6f9ea4b308d60434f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12800",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A culinary legend prized the Isle of Dread's chimaerok as exceptionally tender. Dirge's request for tenderloins was an attempt to put that reputation to use, not an account of every creature's qualities.",["title"]="Chimaerok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8585:description:1-121","8585:description:123-235","8585:description:240-320","8585:description:322-351","8585:description:353-426","8585:description:431-506","8585:objective:1-89"},["minimumStage"]=2,["questID"]=8585,["sourceHash"]="6733dbfce28a710a1422cf66e3c0c59beac288f69e15ecc6f9ea4b308d60434f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8125",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dirge hoped to satisfy an extraordinary poultry-sized order by preparing Lakmaeran's carcass, while securing chimaerok tenderloins for his own cooking.",["title"]="Dirge Quikcleave"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5741:description:1-117","5741:description:119-199","5741:description:201-260","5741:description:265-316","5741:description:319-423","5741:objective:1-91"},["minimumStage"]=2,["questID"]=5741,["sourceHash"]="63a54de4adf1efe2ad2604acdc16b2a9cc89a8c9c6d3150c9f6904d9c6db3bc3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-599",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A seer on one of the fortress's watchtowers studied the Sceptre of Light, rumored to have passed from naga hands into Burning Blade possession.",["title"]="Thunder Axe Fortress"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5381:description:1-42","5381:description:44-86","5381:description:88-155","5381:description:157-211","5381:description:216-310","5381:objective:1-131"},["minimumStage"]=2,["questID"]=5381,["sourceHash"]="bc6580a2b6be2fa4ffb2c78314460ff2087efaf72111a3befcb07cda05d9e062"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-599",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A red crystal in Thunder Axe Fortress barred access to the Demon Box. Taiga supplied a demon pick to recover the Hand of Iruxos held within it.",["title"]="Thunder Axe Fortress"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5381:description:1-42","5381:description:44-86","5381:description:88-155","5381:description:157-211","5381:description:216-310","5381:objective:1-131"},["minimumStage"]=2,["questID"]=5381,["sourceHash"]="bc6580a2b6be2fa4ffb2c78314460ff2087efaf72111a3befcb07cda05d9e062"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Burning Blade used the Hand of Iruxos to open demonic portals at Mannoroc, drawing Taiga's efforts to halt the influx into the world.",["title"]="Mannoroc Coven"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1954:description:1-47","1954:description:50-114","1954:description:116-159","1954:description:162-193","1954:description:198-269","1954:description:272-315","1954:description:320-355","1954:objective:1-53"},["minimumStage"]=2,["questID"]=1954,["sourceHash"]="124d8c813bdaabf6ebd33df72586883a26fb0c95ca7589397e0b9170e9c3958e"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-16022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mannoroc's Burning Blade summoners held the demon-bound infernal orbs Tabetha named as useful vessels for her cleansing work.",["title"]="Mannoroc Coven"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5741:description:1-117","5741:description:119-199","5741:description:201-260","5741:description:265-316","5741:description:319-423","5741:objective:1-91"},["minimumStage"]=2,["questID"]=5741,["sourceHash"]="63a54de4adf1efe2ad2604acdc16b2a9cc89a8c9c6d3150c9f6904d9c6db3bc3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2405",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Azore Aldamort worked from Ethel Rethor's tower, the destination for the sceptre he feared the Burning Blade might use against coastal cities.",["title"]="Ethel Rethor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5501:description:1-58","5501:description:61-103","5501:description:105-195","5501:description:200-300","5501:description:303-419","5501:description:422-434","5501:objective:1-82"},["minimumStage"]=2,["questID"]=5501,["sourceHash"]="496d642a957817a19917074bbcbf7b0fc1aca4297641ddedcc0e4bb58ba8c45a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-596",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The graveyard's kodo bones fed a trade in furniture, instruments and blasting powder through Bibbly's collection and the caravan to Shadowprey.",["title"]="Kodo Graveyard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1432:description:1-148","1432:description:150-190","1432:description:192-261","1432:description:266-362","1432:description:364-451","1432:description:453-496","1432:objective:1-39"},["minimumStage"]=2,["questID"]=1432,["sourceHash"]="584bee312191ade9ccc90bb19b09230b22e195d8912eaab5ba9185ec5bbf173c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-597",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Horde agents gathered at Ghost Walker Post north of the Kodo Graveyard as part of Keldran's effort to remove demonic forces from Desolace.",["title"]="Ghost Walker Post"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1382:description:1-129","1382:description:132-188","1382:description:193-273","1382:description:276-355","1382:description:360-448","1382:description:451-506","1382:objective:1-75"},["minimumStage"]=2,["questID"]=1382,["sourceHash"]="b22490daafdc1769d5b41c607c0ca46812b5f2eb13c0b23602b189472e593981"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-16021",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Uthek spoke for the Gelkis on the outskirts of their southwestern camps. Outsiders seeking an alliance were told to earn favor by opposing the Magram.",["title"]="Gelkis Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1370:description:1-41","1370:description:44-113","1370:description:118-148","1370:description:151-211","1370:description:214-312","1370:objective:1-75"},["minimumStage"]=2,["questID"]=1370,["sourceHash"]="490285d8543c151e49f83cfa5daeb2cc19972fc25c090d2c8cd1c5938304c6af"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16021",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Gelkis campaign sought the Magram's dried meat as well as victories in battle, treating stored food as the strength that sustained the rival clan.",["title"]="Gelkis Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1367:description:1-59","1367:description:62-156","1367:description:161-231","1367:description:234-277","1367:description:280-406","1367:objective:1-66"},["minimumStage"]=2,["questID"]=1367,["sourceHash"]="38e7fe5819cfe974b47081526a8b246d6b2217efaabb3191a508dc796422caf7"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-604",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Warug, the Magram spokesman, received outsiders on the village's southeastern Desolace outskirts after they had earned the clan's favor against the Gelkis.",["title"]="Magram Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1370:description:1-41","1370:description:44-113","1370:description:118-148","1370:description:151-211","1370:description:214-312","1370:objective:1-75"},["minimumStage"]=2,["questID"]=1370,["sourceHash"]="490285d8543c151e49f83cfa5daeb2cc19972fc25c090d2c8cd1c5938304c6af"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-604",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Magram kept surplus dried meat to lengthen their fighting between hunts, making the village's stores a target in Uthek's plans.",["title"]="Magram Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"6132:description:1-19","6132:description:24-83","6132:description:86-136","6132:description:138-165","6132:description:168-195","6132:description:200-258","6132:description:261-317","6132:description:322-337","6132:description:340-428","6132:objective:1-96"},["minimumStage"]=2,["questID"]=6132,["sourceHash"]="2c339373249a2ab1c11ed39871de6ac2f4dfda6d43ef411fb6a6411aff77ec82"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-607",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Melizza's attempted trade with the Maraudines ended in captivity in the Valley of Spears. She feared being eaten and sought an escort to her brother near the Kodo Graveyard.",["title"]="Valley of Spears"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2987:description:1-130","2987:description:132-205","2987:description:207-318","2987:description:323-367","2987:description:369-444","2987:description:446-488","2987:objective:1-67"},["minimumStage"]=2,["questID"]=2987,["sourceHash"]="217678eddd5af90225d60a8f32077ae82ebe92b585ab974627766dee74348953"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1103",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Gordunni buried cobalt at their outpost north of Camp Mojache. Orwin's advice was to watch for a blue glow before digging with his shovel.",["title"]="Gordunni Outpost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2980:description:1-125","2980:description:130-178","2980:description:180-276","2980:description:278-386","2980:description:388-402","2980:description:407-475","2980:description:477-485","2980:objective:1-109"},["minimumStage"]=2,["questID"]=2980,["sourceHash"]="cfa19ca5b9a0070d1e37ba9f27d3723928c45839c511f67a86610b1f41531a05"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-1136",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Abandoned, broken structures stood among withered trees and desecrated ground in the High Wilderness, land Rok Orhan remembered as once belonging to the night elves.",["title"]="High Wilderness"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2982:description:1-107","2982:description:112-213","2982:description:215-325","2982:description:330-435","2982:description:437-507","2982:objective:1-99"},["minimumStage"]=2,["questID"]=2982,["sourceHash"]="3b761e33fb9aa7d61f8aba940039a1e86dfef18526f87183b6fd73dfd3c0dc05"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1136",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gordunni occupation made the ruins dangerous for Troyas's solitary research. Angelas sought intervention so that the investigation could continue more safely.",["title"]="High Wilderness"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5064:description:1-86","5064:description:88-135","5064:description:137-222","5064:description:224-308","5064:description:313-384","5064:objective:1-65"},["minimumStage"]=2,["questID"]=5064,["sourceHash"]="6649b11206493fc8f7167af0712af3821c9c7a1e0576333eef586dbd28a775fd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-2097",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Guarded chests on Darkcloud Pinnacle held separate secret notes sought after three unfamiliar agents were seen visiting the Grimtotem.",["title"]="Darkcloud Pinnacle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8585:description:1-121","8585:description:123-235","8585:description:240-320","8585:description:322-351","8585:description:353-426","8585:description:431-506","8585:objective:1-89"},["minimumStage"]=2,["questID"]=8585,["sourceHash"]="6733dbfce28a710a1422cf66e3c0c59beac288f69e15ecc6f9ea4b308d60434f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1121",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The island's chimaerok and Lord Lakmaeran became the quarry in Dirge's ambitious cooking commission, seeking carcass and tenderloins for different parts of the meal.",["title"]="Isle of Dread"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7141:description:1-114","7141:description:117-172","7141:description:175-214","7141:description:217-261","7141:description:266-328","7141:description:331-366","7141:objective:1-124"},["minimumStage"]=2,["questID"]=7141,["sourceHash"]="73fe6a038b66a08630e7e4fd7d6358deb9ae47e10fa77e58b24d66848320d9df"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13816",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stonehewer's account of Alterac centered on the Explorers' League's search for artifacts. He saw Frostwolf resistance as an obstacle to scholarship and called for Drek'Thar's defeat to break it.",["title"]="Prospector Stonehewer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7141:description:1-114","7141:description:117-172","7141:description:175-214","7141:description:217-261","7141:description:266-328","7141:description:331-366","7141:objective:1-124"},["minimumStage"]=2,["questID"]=7141,["sourceHash"]="73fe6a038b66a08630e7e4fd7d6358deb9ae47e10fa77e58b24d66848320d9df"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-11946",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Frostwolf general Drek'Thar was based in Frostwolf Keep in southern Alterac Valley, the target identified in Stonehewer's military charge.",["title"]="Drek'Thar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7142:description:1-95","7142:description:98-176","7142:description:181-248","7142:description:253-291","7142:objective:1-71","7142:objective:74-131"},["minimumStage"]=2,["questID"]=7142,["sourceHash"]="b472df5f37997a811ea1b22cbb20aadc433cb3d4f0da2b0d52df7e4e7bfd55f8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13817",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Voggah Deathgrip viewed the Stormpike presence as an invasion and sought Vanndar's defeat to drive the dwarves and their allies from the valley.",["title"]="Voggah Deathgrip"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7142:description:1-95","7142:description:98-176","7142:description:181-248","7142:description:253-291","7142:objective:1-71","7142:objective:74-131"},["minimumStage"]=2,["questID"]=7142,["sourceHash"]="b472df5f37997a811ea1b22cbb20aadc433cb3d4f0da2b0d52df7e4e7bfd55f8"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-11948",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vanndar Stormpike commanded from Dun Baldar in northern Alterac Valley, the stronghold Voggah named when directing the attack on the Alliance general.",["title"]="Vanndar Stormpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7162:description:1-32","7162:description:34-76","7162:description:78-122","7162:description:124-156","7162:description:161-253","7162:description:258-316","7162:description:318-371","7162:description:373-410","7162:description:412-485","7162:objective:1-113","7162:objective:115-191"},["minimumStage"]=2,["questID"]=7162,["sourceHash"]="7ba86a0a5237751cb91b56ee6abd5c60c8b85c24c36de98979b652db96335470"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13841",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Haggerdin tested prospective Stormpike initiates by sending them for a banner planted deep in Icewing Cavern. Recovering it would earn the insignia of entry into the force.",["title"]="Lieutenant Haggerdin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7302:description:1-35","7302:description:37-92","7302:description:94-163","7302:description:168-217","7302:description:219-280","7302:description:282-293","7302:description:295-364","7302:description:369-402","7302:description:404-412","7302:description:414-449","7302:objective:1-97","7302:objective:99-159"},["minimumStage"]=2,["questID"]=7302,["sourceHash"]="0095ae534746f40721bdf3eb3fb1901f89c4789096fbbd6a619c3e3f3c6b0d61"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13153",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mulfort's air support had collapsed after the wing commanders were shot down over enemy territory. He first needed their locations before attempting rescues.",["title"]="Commander Mulfort"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7302:description:1-35","7302:description:37-92","7302:description:94-163","7302:description:168-217","7302:description:219-280","7302:description:282-293","7302:description:295-364","7302:description:369-402","7302:description:404-412","7302:description:414-449","7302:objective:1-97","7302:objective:99-159"},["minimumStage"]=2,["questID"]=7302,["sourceHash"]="0095ae534746f40721bdf3eb3fb1901f89c4789096fbbd6a619c3e3f3c6b0d61"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-13179",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Guse was last seen flying over Icewing Bunker before Mulfort's search for the missing wing commanders. Her fate remained unresolved in the initial report.",["title"]="Wing Commander Guse"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7302:description:1-35","7302:description:37-92","7302:description:94-163","7302:description:168-217","7302:description:219-280","7302:description:282-293","7302:description:295-364","7302:description:369-402","7302:description:404-412","7302:description:414-449","7302:objective:1-97","7302:objective:99-159"},["minimumStage"]=2,["questID"]=7302,["sourceHash"]="0095ae534746f40721bdf3eb3fb1901f89c4789096fbbd6a619c3e3f3c6b0d61"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-13180",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jeztor's war rider had been spotted near the Stormpike lumber mill. Mulfort treated that sighting as the lead for finding the missing commander, rather than proof of her death.",["title"]="Wing Commander Jeztor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7302:description:1-35","7302:description:37-92","7302:description:94-163","7302:description:168-217","7302:description:219-280","7302:description:282-293","7302:description:295-364","7302:description:369-402","7302:description:404-412","7302:description:414-449","7302:objective:1-97","7302:objective:99-159"},["minimumStage"]=2,["questID"]=7302,["sourceHash"]="0095ae534746f40721bdf3eb3fb1901f89c4789096fbbd6a619c3e3f3c6b0d61"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-13181",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mulverick was reported crashing near Dun Baldar's North Bunker. Mulfort called him reckless but still sought his whereabouts for a rescue.",["title"]="Wing Commander Mulverick"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7367:description:1-65","7367:description:67-124","7367:description:129-279","7367:description:281-330","7367:description:332-389","7367:description:394-458","7367:description:460-469","7367:objective:1-50","7367:objective:52-119"},["minimumStage"]=2,["questID"]=7367,["sourceHash"]="b4bc2c16bb7580d49b63a1faeaa27df5a7be45b28a361520bbd3d0698d1af675"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13597",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Frostwolf explosives expert supplied the anti-personnel traps protecting the clan's lines and bases. The opposing expert believed removing him would let the mines be safely disarmed.",["title"]="Frostwolf Explosives Expert"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7367:description:1-65","7367:description:67-124","7367:description:129-279","7367:description:281-330","7367:description:332-389","7367:description:394-458","7367:description:460-469","7367:objective:1-50","7367:objective:52-119"},["minimumStage"]=2,["questID"]=7367,["sourceHash"]="b4bc2c16bb7580d49b63a1faeaa27df5a7be45b28a361520bbd3d0698d1af675"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-13597",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Stormpike's account placed the Frostwolf explosives expert in a tower near Iceblood Garrison, using that position as the lead for a strike against the traps' source.",["title"]="Frostwolf Explosives Expert"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7367:description:1-65","7367:description:67-124","7367:description:129-279","7367:description:281-330","7367:description:332-389","7367:description:394-458","7367:description:460-469","7367:objective:1-50","7367:objective:52-119"},["minimumStage"]=2,["questID"]=7367,["sourceHash"]="b4bc2c16bb7580d49b63a1faeaa27df5a7be45b28a361520bbd3d0698d1af675"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13598",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Stormpike explosives expert sought a way through Frostwolf booby traps by attacking the specialist who maintained them, rather than confronting each mine in isolation.",["title"]="Stormpike Explosives Expert"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7202:description:1-143","7202:description:148-175","7202:description:180-259","7202:description:261-396","7202:description:401-450","7202:description:452-471","7202:objective:1-127","7202:objective:132-237"},["minimumStage"]=2,["questID"]=7202,["sourceHash"]="55e1f2f04bb32928ee5303568c58c4fecb0417c053136c26dfe87a74a3153126"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12159",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Recovered Winterax tomes identified Korrak as their hidden leader. The Stormpike account expected him to emerge when provoked, without knowing when he would appear.",["title"]="Korrak the Bloodrager"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7181:description:1-70","7181:description:72-116","7181:description:118-165","7181:description:170-236","7181:description:241-319","7181:description:321-351","7181:objective:1-127","7181:objective:132-210"},["minimumStage"]=2,["questID"]=7181,["sourceHash"]="dbc3e4961c1daf15a782185e81d2fb7c0354c20a9ec28555e0d4f7463042e22b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12159",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Laggrond regarded the Winterax as a second enemy alongside the Stormpike and identified Korrak as their cruel, cunning leader. Striking him was intended to weaken the troll clan.",["title"]="Korrak the Bloodrager"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7381:description:1-87","7381:description:89-147","7381:description:149-251","7381:description:256-298","7381:description:303-384","7381:description:389-421","7381:description:423-458","7381:description:463-472","7381:objective:1-96","7381:objective:101-176"},["minimumStage"]=2,["questID"]=7381,["sourceHash"]="5fc889b54c92d0f27c96ec3e1f46b732409466033222da816622fa85cb498682"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12159",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Laggrond feared that Winterax magic might restore Korrak after his death. His order to watch for a return and bring back the skull was precautionary, not proof that a resurrection had occurred.",["title"]="Korrak the Bloodrager"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7181:description:1-70","7181:description:72-116","7181:description:118-165","7181:description:170-236","7181:description:241-319","7181:description:321-351","7181:objective:1-127","7181:objective:132-210"},["minimumStage"]=2,["questID"]=7181,["sourceHash"]="dbc3e4961c1daf15a782185e81d2fb7c0354c20a9ec28555e0d4f7463042e22b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13840",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Warmaster Laggrond saw Alterac as a war on two fronts: the invading Stormpike and the competing Winterax trolls. Removing Korrak was his proposed blow against the latter.",["title"]="Warmaster Laggrond"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8294:description:1-77","8294:description:79-145","8294:description:147-176","8294:description:178-253","8294:description:258-351","8294:description:353-419","8294:description:422-481","8294:objective:1-144"},["minimumStage"]=2,["questID"]=8294,["sourceHash"]="5201a8c3beb33779117294dd05eb007235d635bfcb787c450d87a91bbda0b841"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14781",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Captain Shatterskull defended the Horde's claimed right to harvest Ashenvale, viewing Silverwing resistance as an attempt to block that expansion. His charge sought marks from victories in the gulch.",["title"]="Captain Shatterskull"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7788:description:1-73","7788:description:75-190","7788:description:195-241","7788:description:243-278","7788:description:283-320","7788:description:323-375","7788:objective:1-135"},["minimumStage"]=2,["questID"]=7788,["sourceHash"]="bc7d36f5002997a657ff97e6cb9b14f25ba4e1230b40cc61b3e9f4eebd7f35e6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14733",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sentinel Farsong called for Silverwing Hold's defense because Horde logging was consuming the sacred forest for war machines. The fighting in Warsong Gulch answered that continuing destruction.",["title"]="Sentinel Farsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7141:description:1-114","7141:description:117-172","7141:description:175-214","7141:description:217-261","7141:description:266-328","7141:description:331-366","7141:objective:1-124"},["minimumStage"]=2,["questID"]=7141,["sourceHash"]="73fe6a038b66a08630e7e4fd7d6358deb9ae47e10fa77e58b24d66848320d9df"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2978",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Frostwolf Keep was Drek'Thar's southern headquarters in Alterac Valley, making it the destination of the Stormpike charge against the clan's general.",["title"]="Frostwolf Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7142:description:1-95","7142:description:98-176","7142:description:181-248","7142:description:253-291","7142:objective:1-71","7142:objective:74-131"},["minimumStage"]=2,["questID"]=7142,["sourceHash"]="b472df5f37997a811ea1b22cbb20aadc433cb3d4f0da2b0d52df7e4e7bfd55f8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2959",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dun Baldar held Vanndar Stormpike in northern Alterac Valley. Voggah's plan to force the Alliance out depended on an attack on that command position.",["title"]="Dun Baldar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7162:description:1-32","7162:description:34-76","7162:description:78-122","7162:description:124-156","7162:description:161-253","7162:description:258-316","7162:description:318-371","7162:description:373-410","7162:description:412-485","7162:objective:1-113","7162:objective:115-191"},["minimumStage"]=2,["questID"]=7162,["sourceHash"]="7ba86a0a5237751cb91b56ee6abd5c60c8b85c24c36de98979b652db96335470"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-3058",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A Stormpike banner was planted deep within Icewing Cavern southwest of Dun Baldar, serving as Haggerdin's trial for an initiate's insignia.",["title"]="Icewing Cavern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7302:description:1-35","7302:description:37-92","7302:description:94-163","7302:description:168-217","7302:description:219-280","7302:description:282-293","7302:description:295-364","7302:description:369-402","7302:description:404-412","7302:description:414-449","7302:objective:1-97","7302:objective:99-159"},["minimumStage"]=2,["questID"]=7302,["sourceHash"]="0095ae534746f40721bdf3eb3fb1901f89c4789096fbbd6a619c3e3f3c6b0d61"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-3304",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The airspace above Icewing Bunker was Guse's last reported position when Mulfort sent scouts to locate the missing wing commanders.",["title"]="Icewing Bunker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7367:description:1-65","7367:description:67-124","7367:description:129-279","7367:description:281-330","7367:description:332-389","7367:description:394-458","7367:description:460-469","7367:objective:1-50","7367:objective:52-119"},["minimumStage"]=2,["questID"]=7367,["sourceHash"]="b4bc2c16bb7580d49b63a1faeaa27df5a7be45b28a361520bbd3d0698d1af675"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2977",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A tower near Iceblood Garrison was the reported station of the Frostwolf explosives expert, linking the garrison's surroundings to the traps guarding the clan's lines.",["title"]="Iceblood Garrison"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7381:description:1-87","7381:description:89-147","7381:description:149-251","7381:description:256-298","7381:description:303-384","7381:description:389-421","7381:description:423-458","7381:description:463-472","7381:objective:1-96","7381:objective:101-176"},["minimumStage"]=2,["questID"]=7381,["sourceHash"]="5fc889b54c92d0f27c96ec3e1f46b732409466033222da816622fa85cb498682"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-3057",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Laggrond's warning about Korrak named the Field of Strife as the place to watch for a possible return. It offered a contingency against Winterax magic rather than a certain appearance.",["title"]="Field of Strife"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7788:description:1-73","7788:description:75-190","7788:description:195-241","7788:description:243-278","7788:description:283-320","7788:description:323-375","7788:objective:1-135"},["minimumStage"]=2,["questID"]=7788,["sourceHash"]="bc7d36f5002997a657ff97e6cb9b14f25ba4e1230b40cc61b3e9f4eebd7f35e6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16604",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Farsong called defenders to Silverwing Hold against Horde logging forces, placing the hold within the night elves' struggle to protect Ashenvale's sacred forest.",["title"]="Silverwing Hold"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7788:description:1-73","7788:description:75-190","7788:description:195-241","7788:description:243-278","7788:description:283-320","7788:description:323-375","7788:objective:1-135"},["minimumStage"]=2,["questID"]=7788,["sourceHash"]="bc7d36f5002997a657ff97e6cb9b14f25ba4e1230b40cc61b3e9f4eebd7f35e6"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-3319",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sentinel Farsong received the marks brought back from victories in Warsong Gulch at Silverwing Grove, connecting the fighting to the forest's defense.",["title"]="Silverwing Grove"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9034:description:1-199","9034:objective:1-219"},["minimumStage"]=2,["questID"]=9034,["sourceHash"]="2057e5644c32b696835ea441bb10aeac60ac6d10f90e74bb22d7f895288267ad"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16112",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Korfax offered to restore heroic battle armor from the desecrated pieces and war-torn plate recovered in Naxxramas, using new materials brought to Light's Hope Chapel.",["title"]="Korfax, Champion of the Light"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9045:description:1-89","9045:description:91-273","9045:objective:1-234"},["minimumStage"]=2,["questID"]=9045,["sourceHash"]="9f0a57fed1dc56d91c982997e9460e0d385e0f7b625d3166724302ff501dc221"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16115",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eligor's armor work sought keepsakes from fallen heroes carried by Naxxramas's lords. He believed restorative crafting materials could revitalize those cursed remnants.",["title"]="Commander Eligor Dawnbringer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9056:description:1-60","9056:description:62-218","9056:description:223-354","9056:objective:1-220"},["minimumStage"]=2,["questID"]=9056,["sourceHash"]="6ec9e0dfcdac6dde1790267ae390a7ce79423f349c375d2e1a80c01b838a4eb4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16132",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Leopold had discovered how to combine crypt fiend carapace with fragments of desecrated magical armor, intending to make unusually light, deadly Cryptstalker protection.",["title"]="Huntsman Leopold"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9068:description:1-91","9068:description:96-267","9068:description:272-380","9068:description:385-401","9068:objective:1-221"},["minimumStage"]=2,["questID"]=9068,["sourceHash"]="fd09f3966fc341f6c823ba59030be9e52530afcbac878cb25c16353518a7af44"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16134",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rimblat sought to honor the defenders who had fallen by renewing their desecrated armor. Purification materials and battle-torn scraps would prepare it to be worn in battle again.",["title"]="Rimblat Earthshatter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9077:description:1-74","9077:description:79-198","9077:description:200-300","9077:description:302-349","9077:description:351-372","9077:objective:1-230"},["minimumStage"]=2,["questID"]=9077,["sourceHash"]="a8543b860c68fbf5b0d72fca43e2803102abbb9bb163775de0c67520670833bb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16131",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rohan supplied the bones for Bonescythe but demanded the other materials and payment from the client. The ruined armor and scraps had to be recovered from Naxxramas before his work could begin.",["title"]="Rohan the Assassin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9086:description:1-101","9086:description:103-216","9086:description:221-366","9086:objective:1-207"},["minimumStage"]=2,["questID"]=9086,["sourceHash"]="c270dafb446275e5b8ea3e2db865f706054c046450d54a8188f1d2e03dc9fb7f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16135",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rayne sought armor stripped from heroes lost to the Scourge. Its unknown use inside Naxxramas troubled her, and recovering it offered a means of crafting Dreamwalker armor for the living.",["title"]="Rayne"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9095:description:1-72","9095:description:74-128","9095:description:130-228","9095:description:230-321","9095:description:326-353","9095:description:358-505","9095:objective:1-211"},["minimumStage"]=2,["questID"]=9095,["sourceHash"]="2716ac5cb0af114360d5c79374609f986ea550310bae9587f042fba4962816f9"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-16116",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Angela's position as a Watcher allowed her to examine Medivh's personal effects. Among his tomes she found the method of making Frostfire armor, knowledge she offered to apply for those supplying the materials.",["title"]="Archmage Angela Dosantos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9103:description:1-28","9103:description:30-104","9103:description:106-138","9103:description:140-191","9103:description:196-274","9103:description:276-368","9103:objective:1-211"},["minimumStage"]=2,["questID"]=9103,["sourceHash"]="1adf46d40c00425dc0488370f6bd38234ecc0a2e4cc308b72b71b96278fad811"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16133",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mataus warned that Plagueheart's darkness might destroy both maker and bearer. He demanded a high price for that risk, bluntly declaring his wish to be wealthy if the work killed him.",["title"]="Mataus the Wrathcaster"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9111:description:1-71","9111:description:76-140","9111:description:142-258","9111:description:263-372","9111:objective:1-205"},["minimumStage"]=2,["questID"]=9111,["sourceHash"]="09c63c02d75c22c78c46d4103f66fef1c54ffbf201e000d7c64cb31d0a5e742e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16113",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Montoy presented his craft as the restoration of dignity to fallen heroes whose vestments had been stripped away. He sought their desecrated remains and purifying reagents for new armor of faith.",["title"]="Father Inigo Montoy"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"9034:description:1-199","9034:objective:1-219"},["minimumStage"]=2,["questID"]=9034,["sourceHash"]="2057e5644c32b696835ea441bb10aeac60ac6d10f90e74bb22d7f895288267ad"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2268",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Korfax received desecrated battle armor and crafting materials at Light's Hope, offering to return the heroic equipment recovered from Naxxramas to useful service.",["title"]="Light's Hope Chapel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4126:description:1-125","4126:description:128-140","4126:description:143-178","4126:description:183-214","4126:description:217-363","4126:description:368-460","4126:objective:1-68"},["minimumStage"]=2,["questID"]=4126,["sourceHash"]="90bd80ae3e3ef5349e787963ca2c959add47e2a43fef9cfa57f53c82fafa06fe"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1267",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ragnar Thunderbrew sought the return of a prized family lager recipe stolen by Hurley's Dark Irons. He also demanded the stolen brew's destruction rather than allow the thieves to enjoy it.",["title"]="Ragnar Thunderbrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4128:description:10-88","4128:description:91-155","4128:description:160-195","4128:description:198-259","4128:objective:1-30","4128:completion:1-21","4128:completion:24-40","4128:completion:43-78","4128:completion:81-94","4128:completion:97-159","4128:completion:162-171","4128:completion:173-194"},["minimumStage"]=4,["questID"]=4128,["sourceHash"]="0ff05ad48acf2676868d592b606d8e95fb0662e94580631e400c7a2eecc1f782"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1267",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The loss of a family recipe intensified Ragnar's existing hatred of the Dark Iron dwarves. His anger at the distillery became a call for adventurers willing to recover it.",["title"]="Ragnar Thunderbrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4134:description:1-80","4134:description:83-173","4134:description:176-202","4134:description:205-263","4134:description:265-315","4134:description:320-427","4134:description:432-507","4134:objective:1-63"},["minimumStage"]=2,["questID"]=4134,["sourceHash"]="aae49439b1b1e1c3a1b8817ef709b27623cee6f0fe60c3ab0f9e6160d342742c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9078",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vivian wanted Thunderbrew Lager's reputed strength and courage studied for Forsaken purposes. She suggested threatening Hurley's precious ale to draw out the dwarf who held its stolen recipe.",["title"]="Shadowmage Vivian Lagrave"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4134:description:1-80","4134:description:83-173","4134:description:176-202","4134:description:205-263","4134:description:265-315","4134:description:320-427","4134:description:432-507","4134:objective:1-63","4134:completion:1-10","4134:completion:12-109","4134:completion:111-200","4134:completion:205-233","4134:completion:235-288","4134:completion:290-302"},["minimumStage"]=4,["questID"]=4134,["sourceHash"]="aae49439b1b1e1c3a1b8817ef709b27623cee6f0fe60c3ab0f9e6160d342742c"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9078",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vivian planned to send the recovered recipe to the Apothecarium. She took grim amusement in the prospect of using a dwarven invention against the Alliance.",["title"]="Shadowmage Vivian Lagrave"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4768:description:1-80","4768:description:83-194","4768:description:199-330","4768:description:333-401","4768:description:406-509","4768:objective:1-68"},["minimumStage"]=2,["questID"]=4768,["sourceHash"]="0fd4111f1bab7fdf9479cb2731e14c1688dcb11fa6b23c39d8872bb6673b470d"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-9078",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vivian's research led her to Urheld Darkstone, an alchemist dismissed as mad by his contemporaries. She believed his privately recorded formulae survived in Blackrock Spire's former Hall of Fortune.",["title"]="Shadowmage Vivian Lagrave"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4136:description:1-117","4136:description:122-244","4136:description:247-301","4136:description:304-347","4136:description:352-401","4136:description:404-440","4136:description:445-483","4136:description:485-507","4136:objective:1-63"},["minimumStage"]=2,["questID"]=4136,["sourceHash"]="bbefc61a6901f661d9990dc5f34724728c5bb98b3a1d5d0a12491c8a6bd4e002"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9544",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yuka hoped to collect Revilgaz's bounty on her brother Ribbly after his failed schemes had drained the family. She accepted his head if he could not be brought out of Blackrock Depths alive.",["title"]="Yuka Screwspigot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4324:description:1-105","4324:description:108-113","4324:description:115-179","4324:description:184-273","4324:description:276-324","4324:description:329-348","4324:description:351-363","4324:description:366-398","4324:description:401-476","4324:objective:1-51"},["minimumStage"]=2,["questID"]=4324,["sourceHash"]="a40f5a109b6130da081f87ef1040fb05aa95d567e8ad7be3816e2b9fd4ea2889"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-9544",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yuka waited at Flame Crest, a cave northwest of Dreadmaul Rock, after tracing her missing brother into the Burning Steppes.",["title"]="Yuka Screwspigot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4201:description:1-22","4201:description:25-71","4201:description:74-86","4201:description:89-103","4201:description:108-124","4201:description:127-231","4201:description:234-392","4201:description:395-431","4201:description:436-491","4201:objective:1-108"},["minimumStage"]=2,["questID"]=4201,["sourceHash"]="978f1a61f809857cc5381876a725d7cea2c850324de3581ee7d93ac949d8f2a8"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-9500",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nagmara identified herself as a succubus while appealing for help with her unrequited attraction to Private Rocknot.",["title"]="Mistress Nagmara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4201:description:1-22","4201:description:25-71","4201:description:74-86","4201:description:89-103","4201:description:108-124","4201:description:127-231","4201:description:234-392","4201:description:395-431","4201:description:436-491","4201:objective:1-108"},["minimumStage"]=2,["questID"]=4201,["sourceHash"]="978f1a61f809857cc5381876a725d7cea2c850324de3581ee7d93ac949d8f2a8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9500",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rocknot's indifference drove Nagmara to seek a love potion. She requested gromsblood, giant silver veins and Golakka spring water, intending the mixture to overcome his resistance to her charms.",["title"]="Mistress Nagmara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4286:description:1-80","4286:description:82-105","4286:description:110-159","4286:description:164-174","4286:description:176-187","4286:description:192-211","4286:description:213-286","4286:description:291-329","4286:objective:1-64","4286:objective:66-117","4286:objective:119-218"},["minimumStage"]=2,["questID"]=4286,["sourceHash"]="15743bb88ee94038e02e69b1fe54b51a8fb511f310b29d73830b75ba2d46a7c6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9177",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Oralius appealed to Captain Winky's supposed knowledge of Dark Iron supplies, then supplied a pirate's answer in his own voice. The eccentric conversation led to his demand for packs from the Depths.",["title"]="Oralius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4729:description:1-50","4729:description:52-69","4729:description:71-87","4729:description:92-156","4729:description:158-266","4729:description:271-409","4729:description:411-452","4729:objective:1-54","4729:objective:56-105","4729:objective:107-144"},["minimumStage"]=2,["questID"]=4729,["sourceHash"]="1a1bdd94233d1ace24c8f5bf6cf9f7ed7cdf886385db1cdabc9e706f5cdb9297"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10260",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kibler combined a professed love of animals with a trade in exotic pets for rich patrons. He offered to domesticate captured Bloodaxe worg pups brought out of Blackrock Spire.",["title"]="Kibler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4862:description:1-101","4862:description:106-224","4862:description:226-251","4862:description:256-278","4862:description:280-343","4862:description:345-447","4862:objective:1-70","4862:objective:75-133"},["minimumStage"]=2,["questID"]=4862,["sourceHash"]="54e9a04378ca6afa7fda3b724f83d53ed7de7cb14224bf0bd5bb803a0aa1b605"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-10260",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kibler had sent Bijou into Blackrock Spire for spider eggs and had heard nothing from her for weeks. He offered money and a domesticated creature to another collector willing to complete the commission.",["title"]="Kibler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4734:description:1-63","4734:description:66-144","4734:description:146-165","4734:description:168-190","4734:description:195-290","4734:description:293-386","4734:description:391-406","4734:description:409-446","4734:description:449-495","4734:objective:1-58"},["minimumStage"]=2,["questID"]=4734,["sourceHash"]="6b1e14bb03b7c24d70ae7cded7f4dc44f7d88c1ad1b0ef96e815ec113d77c645"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10267",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tinkee developed an eggscilloscope that projected cold at black dragon eggs. Her rookery experiment was intended to freeze them before they hatched.",["title"]="Tinkee Steamboil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4735:description:1-54","4735:description:57-92","4735:description:95-161","4735:description:164-221","4735:description:226-312","4735:description:317-360","4735:objective:1-116"},["minimumStage"]=2,["questID"]=4735,["sourceHash"]="c33d1dacc6afe079a74ad684133dd67c89c7122304c644b3f6d83d5d1cbc770e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10267",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tinkee sought actual rookery eggs for an unnamed patron after testing her freezing device. Her collectronic module extracted and prepared the frozen samples for transport.",["title"]="Tinkee Steamboil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4907:description:10-35","4907:description:38-61","4907:description:64-123","4907:description:125-150","4907:description:153-211","4907:description:216-282","4907:objective:1-28"},["minimumStage"]=2,["questID"]=4907,["sourceHash"]="025c7455433c7d3e7cbcce66634bf35129cfe6f4976bf54cccb2ac8554563152"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-10267",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tinkee pursued her dragon studies at Flame Crest in the Burning Steppes, sending word through Felnok when she needed another expedition's help.",["title"]="Tinkee Steamboil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4742:description:1-59","4742:description:61-151","4742:description:153-271","4742:description:276-412","4742:description:414-448","4742:description:450-467","4742:objective:1-116","4742:objective:118-184","4742:objective:189-346"},["minimumStage"]=2,["questID"]=4742,["sourceHash"]="e00aca0dc61cb6fcdaa5961efe2a1e382b5dcdde41ea28581b695bf16961de20"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10296",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vaelan prepared a seal from command gemstones associated with Voone, Omokk and Wyrmthalak. Their three sockets represented the lower citadel's leadership.",["title"]="Vaelan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4743:description:1-132","4743:description:134-195","4743:description:200-250","4743:description:252-320","4743:description:322-349","4743:description:351-397","4743:description:399-490","4743:objective:1-42","4743:objective:44-131","4743:objective:136-231","4743:objective:233-355","4743:objective:357-457","4743:completion:1-61","4743:completion:66-108","4743:completion:113-148","4743:completion:153-226","4743:completion:228-331"},["minimumStage"]=4,["questID"]=4743,["sourceHash"]="7711c9fce37046cb3229b33bcd16979cc053a307c2de1e918979fb3ddd4641b9"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-10296",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After the seal was forged, Vaelan invoked protective wards and promised the red flight's support in a desperate hour. His final blessing connected the artifact to that flight's aid.",["title"]="Vaelan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4866:description:1-62","4866:description:67-152","4866:description:154-258","4866:description:263-349","4866:description:351-393","4866:description:395-436","4866:description:441-447","4866:description:449-465","4866:description:470-511","4866:objective:1-64","4866:objective:66-102","4866:objective:104-159","4866:objective:161-230","4866:completion:1-36","4866:completion:41-88","4866:completion:90-110","4866:completion:115-127"},["minimumStage"]=4,["questID"]=4866,["sourceHash"]="bd55edf2b2bb57b36c17895e15b944a04593fd0eb3dd5a9a23d8a276e3ab519b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9563",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ragged John's dangerous request for Mother Smolderweb's venom concealed a brewing experiment. Once the living carrier returned, he revealed that the extracted poison was destined for ale.",["title"]="Ragged John"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4866:description:1-62","4866:description:67-152","4866:description:154-258","4866:description:263-349","4866:description:351-393","4866:description:395-436","4866:description:441-447","4866:description:449-465","4866:description:470-511","4866:objective:1-64","4866:objective:66-102","4866:objective:104-159","4866:objective:161-230"},["minimumStage"]=2,["questID"]=4866,["sourceHash"]="bd55edf2b2bb57b36c17895e15b944a04593fd0eb3dd5a9a23d8a276e3ab519b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9563",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="John insisted that Smolderweb's poison had to be brought back circulating in a living body. A gland alone would not supply the sample his proposed extraction required.",["title"]="Ragged John"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4867:description:1-5","4867:description:8-24","4867:description:29-43","4867:description:46-60","4867:objective:1-21","4867:objective:24-53","4867:completion:1-4","4867:completion:6-50","4867:completion:52-100","4867:completion:105-118","4867:completion:120-173","4867:completion:178-240","4867:completion:242-338"},["minimumStage"]=4,["questID"]=4867,["sourceHash"]="eb144c15767e31e37d8f611e70e7d4b3e205ed7486cc45e2f52538baaaf70f91"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10799",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Warosh attributed his tormented mind to Urok's curse. Recovering his mojo restored his sense of power and freedom from that affliction.",["title"]="Warosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4867:description:1-5","4867:description:8-24","4867:description:29-43","4867:description:46-60","4867:objective:1-21","4867:objective:24-53"},["minimumStage"]=2,["questID"]=4867,["sourceHash"]="eb144c15767e31e37d8f611e70e7d4b3e205ed7486cc45e2f52538baaaf70f91"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-10799",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="When he pleaded for his missing mojo, Warosh struggled to speak and handed over a scroll rather than explain the task fully aloud.",["title"]="Warosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4982:description:1-166","4982:description:171-220","4982:description:222-271","4982:description:273-314","4982:description:316-360","4982:description:362-404","4982:description:406-434","4982:description:439-490","4982:description:492-502","4982:objective:1-47","4982:objective:49-128"},["minimumStage"]=2,["questID"]=4982,["sourceHash"]="866c1e2b10e101c9baba9018a8b785fc27e5e9a15cb93cc4ed4947b48f20d8c0"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-10257",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bijou said a tripwire had exposed her night-time reconnaissance in Blackrock Spire. She stashed the equipment and fled, leaving increased patrols between her and the intelligence she had gathered.",["title"]="Bijou"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4981:description:1-21","4981:description:23-55","4981:description:60-113","4981:description:115-242","4981:description:244-306","4981:description:311-345","4981:description:350-392","4981:description:394-421","4981:description:426-463","4981:objective:1-62","4981:completion:1-23","4981:completion:25-43","4981:completion:45-101","4981:completion:103-113","4981:completion:118-146","4981:completion:148-178","4981:completion:180-255","4981:completion:257-330","4981:completion:332-397","4981:completion:402-416","4981:completion:421-478"},["minimumStage"]=4,["questID"]=4981,["sourceHash"]="27fe44c7412578b6132450c84ea1ca012c83c84f787861ed90219e79a12b6f17"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-10257",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bijou admitted taking Kibler's better-paid work while serving the Kargath Expeditionary Force, but denied disloyalty. Lexlort's accusation concerned the use of Horde funds for those competing commissions.",["title"]="Bijou"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4983:description:1-33","4983:description:35-93","4983:description:95-143","4983:description:148-161","4983:description:163-195","4983:description:197-251","4983:objective:1-74"},["minimumStage"]=2,["questID"]=4983,["sourceHash"]="675d7b2061b62d6f823b4d8e4ac62d4d1b0203fd3297d92d5f3ae3c5e5109bb4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10257",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bijou sent her reconnaissance report to Lexlort to recover her standing and improve the expedition's position against the orcs. She refused to abandon her remaining work merely to accompany the courier.",["title"]="Bijou"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4701:description:1-66","4701:description:71-145","4701:description:147-285","4701:description:287-360","4701:description:362-372","4701:description:374-385","4701:description:390-403","4701:description:405-431","4701:objective:1-68","4701:objective:70-118","4701:objective:120-171"},["minimumStage"]=2,["questID"]=4701,["sourceHash"]="d6aa7606359cda632d741c49496f32262d1f03175e3321d02c002ab5bc251ba9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9562",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Helendis wanted Blackrock's worg breeding disrupted because killing exported animals had not reduced their numbers. His scouts placed their breeding and training within Blackrock Spire.",["title"]="Helendis Riverhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4724:description:1-92","4724:description:94-202","4724:description:207-267","4724:description:269-321","4724:description:323-369","4724:description:371-379","4724:description:381-431","4724:description:436-467","4724:description:469-486","4724:description:488-511","4724:objective:1-49"},["minimumStage"]=2,["questID"]=4724,["sourceHash"]="86f161373affd087bd190c4ac8c1515e067bf4a6bff8359a60ddee7e1f8cd5d4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9081",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Galamav rejected rumors that Blackrock's worgs were demon gifts, naming Halycon and her mate as their source. His warning about the den mother included the danger posed by the poorly understood second beast.",["title"]="Galamav the Marksman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4866:description:1-62","4866:description:67-152","4866:description:154-258","4866:description:263-349","4866:description:351-393","4866:description:395-436","4866:description:441-447","4866:description:449-465","4866:description:470-511","4866:objective:1-64","4866:objective:66-102","4866:objective:104-159","4866:objective:161-230"},["minimumStage"]=2,["questID"]=4866,["sourceHash"]="bd55edf2b2bb57b36c17895e15b944a04593fd0eb3dd5a9a23d8a276e3ab519b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10596",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ragged John called Smolderweb's venom Mother's Milk and repeated Blackrock accounts of its lethality. His experiment required a poisoned traveler to carry a live sample out of the Spire.",["title"]="Mother Smolderweb"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4743:description:1-132","4743:description:134-195","4743:description:200-250","4743:description:252-320","4743:description:322-349","4743:description:351-397","4743:description:399-490","4743:objective:1-42","4743:objective:44-131","4743:objective:136-231","4743:objective:233-355","4743:objective:357-457"},["minimumStage"]=2,["questID"]=4743,["sourceHash"]="7711c9fce37046cb3229b33bcd16979cc053a307c2de1e918979fb3ddd4641b9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vaelan counted Wyrmthalak among the few lower-citadel dragonkin whose breath could forge the seal. His unbreakable will made him unsuitable for the control required by that plan.",["title"]="Overlord Wyrmthalak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4742:description:1-59","4742:description:61-151","4742:description:153-271","4742:description:276-412","4742:description:414-448","4742:description:450-467","4742:objective:1-116","4742:objective:118-184","4742:objective:189-346"},["minimumStage"]=2,["questID"]=4742,["sourceHash"]="e00aca0dc61cb6fcdaa5961efe2a1e382b5dcdde41ea28581b695bf16961de20"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vaelan associated Wyrmthalak with the Bloodaxe command gemstone, alongside Voone's Smolderthorn stone and Omokk's Spirestone stone.",["title"]="Overlord Wyrmthalak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4974:description:1-95","4974:description:100-163","4974:description:165-250","4974:description:255-297","4974:description:302-428","4974:description:430-475","4974:objective:1-59","4974:objective:61-98"},["minimumStage"]=2,["questID"]=4974,["sourceHash"]="721f66a3fa32f4caa831d765f7174845e2764b72041bed5aa8e985adca30df0a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10429",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thrall ordered Rend's death as a blow against a rival Warchief sustained by the black flight. The mission required reaching him beyond the Halls of Ascension and bringing his head to Orgrimmar.",["title"]="Warchief Rend Blackhand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4743:description:1-132","4743:description:134-195","4743:description:200-250","4743:description:252-320","4743:description:322-349","4743:description:351-397","4743:description:399-490","4743:objective:1-42","4743:objective:44-131","4743:objective:136-231","4743:objective:233-355","4743:objective:357-457"},["minimumStage"]=2,["questID"]=4743,["sourceHash"]="7711c9fce37046cb3229b33bcd16979cc053a307c2de1e918979fb3ddd4641b9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-511",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vaelan directed the forging attempt to the Wyrmbog in Dustwallow Marsh, where the ancient Emberstrife could be weakened and compelled to heat the seal.",["title"]="Wyrmbog"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4201:description:1-22","4201:description:25-71","4201:description:74-86","4201:description:89-103","4201:description:108-124","4201:description:127-231","4201:description:234-392","4201:description:395-431","4201:description:436-491","4201:objective:1-108"},["minimumStage"]=2,["questID"]=4201,["sourceHash"]="978f1a61f809857cc5381876a725d7cea2c850324de3581ee7d93ac949d8f2a8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-543",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nagmara's potion required water from Un'Goro's Golakka springs, linking the hot pools to her attempt to win Private Rocknot's affection.",["title"]="Golakka Hot Springs"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4965:description:1-19","4965:description:21-66","4965:description:68-143","4965:description:145-350","4965:description:355-430","4965:objective:1-42"},["minimumStage"]=2,["questID"]=4965,["sourceHash"]="4490dcc0a98ef0a82a16687de8f0bcde680f957ef5576784be075e3235e113d6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Menara was recommended as an expert maker of orbs capable of imprisoning demons for a warlock's service. She worked from Strahad's tower above Ratchet.",["title"]="Menara Voidrender"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4736:description:1-14","4736:description:16-56","4736:description:58-178","4736:description:183-242","4736:description:244-315","4736:description:320-375","4736:description:377-436","4736:objective:1-42","4736:completion:1-24","4736:completion:26-30","4736:completion:32-87","4736:completion:89-104","4736:completion:109-176","4736:completion:178-322","4736:completion:327-449"},["minimumStage"]=4,["questID"]=4736,["sourceHash"]="9798c90074d303a55d9da31bc0160e4141bb05bdf2921ce725e9b3af60789551"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Menara urged warlocks to support one another regardless of race because the beings they bargained with showed equal malice toward any failure of control. Her instruction offered tools to complement the student's existing skills.",["title"]="Menara Voidrender"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4975:description:1-88","4975:description:90-168","4975:description:170-240","4975:description:242-287","4975:objective:1-89"},["minimumStage"]=2,["questID"]=4975,["sourceHash"]="e1f5bfa063e9a656369df723f9575ef7e330a770d402f84ef4506f21984bfdda"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Menara could shape a demon-bound implement as either a staff or an orb, accommodating those who favored a two-handed weapon and those who carried a blade.",["title"]="Menara Voidrender"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4781:description:1-80","4781:description:85-212","4781:description:214-323","4781:description:328-376","4781:description:378-444","4781:description:446-485","4781:description:487-507","4781:objective:1-58"},["minimumStage"]=2,["questID"]=4781,["sourceHash"]="10310f5356b1d8fe50acd88cbf1615b9f840a02b287276f43c36f96a6938d9ef"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2670",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xizk was a master tailor in Booty Bay who knew the uncommon craft of spinning gold thread. Menara directed students to bring him a gold bar for the embroidery of her robe.",["title"]="Xizk Goodstitch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4781:description:1-80","4781:description:85-212","4781:description:214-323","4781:description:328-376","4781:description:378-444","4781:description:446-485","4781:description:487-507","4781:objective:1-58","4781:completion:1-12","4781:completion:14-72","4781:completion:74-106","4781:completion:108-136","4781:completion:138-173","4781:completion:178-360","4781:completion:362-375","4781:completion:377-388","4781:completion:390-406"},["minimumStage"]=4,["questID"]=4781,["sourceHash"]="10310f5356b1d8fe50acd88cbf1615b9f840a02b287276f43c36f96a6938d9ef"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2670",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xizk teased a client with a story about a princess confined to spinning gold thread, then admitted it was a joke. The work itself still required time.",["title"]="Xizk Goodstitch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7582:description:1-155","7582:description:157-218","7582:description:223-329","7582:description:334-399","7582:objective:1-127","7582:objective:129-197"},["minimumStage"]=2,["questID"]=7582,["sourceHash"]="eacad3eb0882af97ff16c8c7326dc24c03d3bdcde8d51e69ed628958a95efdb0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14463",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Daio described Tears of the Hederine as crystals formed when the demons' potent fel poison matured and hardened. He intended their anti-magic walls to contain a Doomguard.",["title"]="Daio the Decrepit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7581:description:1-78","7581:description:83-154","7581:description:156-235","7581:objective:1-117","7581:objective:119-171"},["minimumStage"]=2,["questID"]=7581,["sourceHash"]="bd91409d4e034fab77d88c649890d51c67592bc461f099d64ca35e944b0c7300"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14463",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Daio's crystal prison required Wildspawn satyr blood to bond its Hederine shards and power the binding. The blood was to be gathered in Dire Maul's Warpwood Quarter.",["title"]="Daio the Decrepit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7601:description:1-149","7601:description:151-193","7601:description:195-237","7601:description:239-297","7601:description:299-379","7601:description:384-424","7601:objective:1-28"},["minimumStage"]=2,["questID"]=7601,["sourceHash"]="86b330a1d9015b87118c473c23ad074533984b936527a51cceef3d3d7cfa1b66"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14469",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Niby offered infernal-summoning instruction in exchange for Kroshius's core. Because the fallen infernal had burned nearly out, he directed the preparation of a fire strong enough to revive it first.",["title"]="Niby the Almighty"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7602:description:1-69","7602:description:71-132","7602:description:137-220","7602:description:225-399","7602:description:404-509","7602:objective:1-116","7602:objective:121-196","7602:objective:198-281","7602:objective:283-371","7602:objective:376-441"},["minimumStage"]=2,["questID"]=7602,["sourceHash"]="f91b407277cd7a0c2718d8793f9486a93dcc28e8c566ae247a37be7c38103162"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14470",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Impsy could combine flawless fel essences into the fire needed to reanimate Kroshius. His instructions required essences from Legashi satyrs, Jaedenar legionnaires and the Blasted Lands' felguard sentries.",["title"]="Impsy"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7622:description:1-97","7622:description:102-166","7622:description:168-248","7622:description:253-322","7622:description:324-353","7622:objective:1-37","7622:objective:39-96","7622:objective:101-170"},["minimumStage"]=2,["questID"]=7622,["sourceHash"]="491109f6947fdee5fb85866b10ab46e380a5130160427450e27176b135221ea9"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-14494",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eris remembered failing to save peasants fleeing Stratholme. Their continued suffering became the trial she offered another priest, who had to protect the fugitives on their passage toward the Light.",["title"]="Eris Havenfire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7622:description:1-97","7622:description:102-166","7622:description:168-248","7622:description:253-322","7622:description:324-353","7622:objective:1-37","7622:objective:39-96","7622:objective:101-170"},["minimumStage"]=2,["questID"]=7622,["sourceHash"]="491109f6947fdee5fb85866b10ab46e380a5130160427450e27176b135221ea9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14494",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eris sought an end to the cursed existence shared with the fallen peasants. Too many deaths during the attempt would leave that suffering unresolved.",["title"]="Eris Havenfire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7626:description:1-143","7626:description:146-245","7626:description:250-364","7626:description:367-431","7626:objective:1-77"},["minimumStage"]=2,["questID"]=7626,["sourceHash"]="7357aeab9c96b42735ecaa1df9408e240cc51dd7fd84c6ec2f048c02cbf62673"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14436",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mor'zul identified a bell named for Dethmoora Darkeyes as one of three instruments for the Circle of Greater Summoning. Attuned with the wheel and candle, it would conduct the ritual's arcane power.",["title"]="Mor'zul Bloodbringer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7631:description:1-30","7631:description:33-163","7631:description:165-191","7631:description:196-256","7631:description:259-338","7631:description:343-361","7631:description:364-442","7631:objective:1-28","7631:objective:31-100"},["minimumStage"]=2,["questID"]=7631,["sourceHash"]="417cf0053b3e833c1834694668c5914191e3d179e5596b9517fa9529e911edfa"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14436",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mor'zul prepared written instructions for opening a portal to Xoroth and binding a dreadsteed. He insisted that the circle's stages be followed exactly rather than trusting improvised magic.",["title"]="Mor'zul Bloodbringer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7629:description:1-105","7629:description:108-113","7629:description:115-146","7629:description:149-175","7629:description:180-236","7629:description:239-309","7629:description:314-361","7629:description:364-405","7629:description:408-469","7629:objective:1-61","7629:objective:64-131"},["minimumStage"]=2,["questID"]=7629,["sourceHash"]="2d51d82e416a869d47291d79acc2d42e6686497be161f05efaf8597c07a78690"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14437",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gorzeeki prepared the parchment and implements for Mor'zul's ritual. Lacking an appropriate local laboratory, he sent a clever imp in a jar to perform the infusion inside Scholomance.",["title"]="Gorzeeki Wildeyes"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7627:description:1-114","7627:description:117-248","7627:description:253-295","7627:objective:1-87","7627:completion:1-15","7627:completion:17-138","7627:completion:140-191","7627:completion:193-263","7627:completion:265-293","7627:completion:298-323","7627:completion:325-401"},["minimumStage"]=4,["questID"]=7627,["sourceHash"]="376f76dc147f0ad548e7d84a2621e28132d18472c6beac123cc4038c823f40d2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14437",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gorzeeki compared a warlock's dedication to the effort that could instead be spent catching bugs, a pursuit he imagined as a feast. The digression accompanied his promise to make the ritual wheel.",["title"]="Gorzeeki Wildeyes"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7624:description:1-33","7624:description:36-52","7624:description:57-169","7624:description:172-237","7624:description:242-283","7624:description:286-350","7624:description:353-412","7624:description:415-449","7624:objective:1-80"},["minimumStage"]=2,["questID"]=7624,["sourceHash"]="2df178147cfe60d7bf6885aa519683bd97c7ed579d1e63b73ab5c96399ef3c06"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9516",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Banehollow accused Ulathek of spying for Hel'nurath, his rival on Xoroth. He demanded the servant's heart as a test of loyalty from anyone seeking his favor.",["title"]="Lord Banehollow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7625:description:1-45","7625:description:48-118","7625:description:121-187","7625:description:192-201","7625:description:204-256","7625:description:259-287","7625:description:289-313","7625:objective:1-40","7625:objective:43-95"},["minimumStage"]=2,["questID"]=7625,["sourceHash"]="2232b036584d6150a4fa5b512347f03aa9959dac1bce1be3b0e684621692d060"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9516",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Banehollow's servant Ur'dan held Xorothian stardust. The dreadlord allowed a would-be dreadsteed captor to buy it, recognizing that the theft would strike at Hel'nurath's domain.",["title"]="Lord Banehollow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7623:description:1-54","7623:description:57-99","7623:description:102-136","7623:description:141-240","7623:description:243-293","7623:description:298-408","7623:description:411-481","7623:objective:1-62","7623:objective:67-141","7623:completion:1-40","7623:completion:43-109"},["minimumStage"]=4,["questID"]=7623,["sourceHash"]="f6e7503b62c3181697b40bdfa028a91dc3d1977b3819297eafa1622723787538"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9516",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Banehollow claimed patience measured in millennia but afforded a visiting warlock only a moment of his attention. The audience offered no assurance of his goodwill.",["title"]="Lord Banehollow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7624:description:1-33","7624:description:36-52","7624:description:57-169","7624:description:172-237","7624:description:242-283","7624:description:286-350","7624:description:353-412","7624:description:415-449","7624:objective:1-80"},["minimumStage"]=2,["questID"]=7624,["sourceHash"]="2df178147cfe60d7bf6885aa519683bd97c7ed579d1e63b73ab5c96399ef3c06"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-14523",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ulathek served Banehollow in Shadow Hold. His master's accusation cast him as a spy plotting with Hel'nurath to undermine the dreadlord's power; the charge supplied Banehollow's reason for ordering his death.",["title"]="Ulathek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7625:description:1-45","7625:description:48-118","7625:description:121-187","7625:description:192-201","7625:description:204-256","7625:description:259-287","7625:description:289-313","7625:objective:1-40","7625:objective:43-95"},["minimumStage"]=2,["questID"]=7625,["sourceHash"]="2232b036584d6150a4fa5b512347f03aa9959dac1bce1be3b0e684621692d060"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14522",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ur'dan kept a supply of Xorothian stardust that Banehollow permitted visitors to purchase. The substance was needed for the portal parchment in Mor'zul's dreadsteed ritual.",["title"]="Ur'dan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7629:description:1-105","7629:description:108-113","7629:description:115-146","7629:description:149-175","7629:description:180-236","7629:description:239-309","7629:description:314-361","7629:description:364-405","7629:description:408-469","7629:objective:1-61","7629:objective:64-131","7629:completion:1-9","7629:completion:11-40","7629:completion:42-65","7629:completion:67-92","7629:completion:94-114","7629:completion:116-140","7629:completion:145-194","7629:completion:196-225","7629:completion:227-248"},["minimumStage"]=4,["questID"]=7629,["sourceHash"]="2d51d82e416a869d47291d79acc2d42e6686497be161f05efaf8597c07a78690"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14500",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="J'eevee was the clever imp sent in Gorzeeki's jar to Scholomance's alchemy lab. Gorzeeki credited him with infusing the parchment needed for the portal to Xoroth.",["title"]="J'eevee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7631:description:1-30","7631:description:33-163","7631:description:165-191","7631:description:196-256","7631:description:259-338","7631:description:343-361","7631:description:364-442","7631:objective:1-28","7631:objective:31-100","7631:completion:1-44","7631:completion:47-137","7631:completion:142-240"},["minimumStage"]=4,["questID"]=7631,["sourceHash"]="417cf0053b3e833c1834694668c5914191e3d179e5596b9517fa9529e911edfa"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-14504",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After defeat, the dreadsteed's spirit retained ghostly flanks through which rage still seemed to pulse. Its submission imparted the magic by which it could be summoned.",["title"]="Dreadsteed Spirit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7636:description:1-63","7636:description:65-105","7636:description:107-147","7636:description:152-217","7636:description:219-280","7636:description:282-337","7636:description:339-399","7636:description:404-483","7636:description:485-505","7636:objective:1-56","7636:objective:61-82","7636:objective:87-106","7636:objective:111-129","7636:objective:134-158","7636:objective:163-248","7636:objective:253-332","7636:objective:337-376"},["minimumStage"]=2,["questID"]=7636,["sourceHash"]="54a41bcdfc9347d9d01992aa8f13d725043e6c6e85dd633e75b9caa154a9a4dd"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14524",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vartrus sought the destruction of four Legion corrupters whose presence withered nature. He warned that they would flee a group but confront a solitary challenger, making an unaided hunt essential to his plan.",["title"]="Vartrus the Ancient"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7635:description:1-123","7635:description:128-157","7635:description:159-221","7635:description:223-320","7635:objective:1-75","7635:objective:77-134"},["minimumStage"]=2,["questID"]=7635,["sourceHash"]="fa43bf275481a8a99ccfd996a70028c6711fa5b3b39b440c22eaa0a5ea3dd4b6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14525",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stoma supplied the enchantment for a bowstring to accompany Vartrus's stave. He required mature black-dragon sinew, which he promised to turn into an almost indestructible string.",["title"]="Stoma the Ancient"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7635:description:1-123","7635:description:128-157","7635:description:159-221","7635:description:223-320","7635:objective:1-75","7635:objective:77-134","7635:completion:1-32","7635:completion:34-57","7635:completion:62-149"},["minimumStage"]=4,["questID"]=7635,["sourceHash"]="fa43bf275481a8a99ccfd996a70028c6711fa5b3b39b440c22eaa0a5ea3dd4b6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14525",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stoma judged the delivered dragon sinew foul with evil and undertook to cleanse it before applying the bowstring's enchantments.",["title"]="Stoma the Ancient"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7634:description:1-14","7634:description:16-44","7634:description:46-76","7634:description:81-197","7634:description:199-277","7634:description:282-361","7634:objective:1-75","7634:objective:77-135"},["minimumStage"]=2,["questID"]=7634,["sourceHash"]="d3f9f7aa820b1504b513f7ab82c42bb466e7976327d1460ee2ca65a584241434"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14526",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hastat identified himself as an Ancient of Lore, preserving knowledge lost across ages. One of his leaves, properly bound with adult blue-dragon sinew, could become an exceptional quiver.",["title"]="Hastat the Ancient"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7638:description:1-137","7638:description:139-151","7638:description:156-232","7638:description:235-381","7638:description:386-419","7638:description:422-463","7638:objective:1-72","7638:completion:1-24","7638:completion:26-121","7638:completion:126-267","7638:completion:269-360","7638:completion:362-461","7638:completion:466-495"},["minimumStage"]=4,["questID"]=7638,["sourceHash"]="8ee62ac83469d4eb840083bf1a29842520d1847c3188b78d4d6211e32fdea46a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-928",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grayson treated the charger's recovery as a rescue of a future companion rather than another educational exercise. The paladin's stature did not remove the duty to overcome the evil holding the beast.",["title"]="Lord Grayson Shadowbreaker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7637:description:1-93","7637:description:95-124","7637:description:129-195","7637:description:198-290","7637:description:295-346","7637:description:349-451","7637:description:456-489","7637:objective:1-64","7637:objective:67-133"},["minimumStage"]=2,["questID"]=7637,["sourceHash"]="f3c85fa5416cdff98688395933055a8f8dfb3de8d4768b7f6fe7eb0ddb738fdb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-928",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grayson required compensation for Rohan's exorcism censer even though its intended use was righteous. The donation made sacrifice part of the charger's preparation.",["title"]="Lord Grayson Shadowbreaker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7641:description:1-85","7641:description:88-274","7641:description:279-331","7641:description:334-425","7641:description:428-487","7641:description:490-504","7641:objective:1-58"},["minimumStage"]=2,["questID"]=7641,["sourceHash"]="2e6d7bcbf2672691e301f672cf0704a8016b92f47d27bb5aa5cd4f8bf3f0a7f0"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-928",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grayson recommended Grimand Elmore for barding of exceptional quality, including the spiritual attunement the charger would need. He warned that the craftsman's work would not be cheap.",["title"]="Lord Grayson Shadowbreaker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7639:description:1-35","7639:description:38-147","7639:description:152-209","7639:description:212-241","7639:objective:1-96"},["minimumStage"]=2,["questID"]=7639,["sourceHash"]="407f99a693b0628f2e56d934a4878af34dbe4d6ae1d7289a9851d8cb9fa323d4"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11406",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rohan had used his censer in several exorcisms before entrusting it to the paladin pursuing Grayson's trial.",["title"]="High Priest Rohan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7637:description:1-93","7637:description:95-124","7637:description:129-195","7637:description:198-290","7637:description:295-346","7637:description:349-451","7637:description:456-489","7637:objective:1-64","7637:objective:67-133","7637:completion:1-30","7637:completion:32-77","7637:completion:79-204","7637:completion:209-289"},["minimumStage"]=4,["questID"]=7637,["sourceHash"]="f3c85fa5416cdff98688395933055a8f8dfb3de8d4768b7f6fe7eb0ddb738fdb"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11406",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rohan intended the substantial donation for his censer to replace the lost tool and support Ironforge's people in need. He regarded the gift as more than sufficient compensation.",["title"]="High Priest Rohan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7642:description:1-197","7642:description:200-232","7642:description:234-249","7642:description:252-324","7642:description:329-390","7642:description:393-499","7642:objective:1-154"},["minimumStage"]=2,["questID"]=7642,["sourceHash"]="a7d3a86bcf7cdb6fe5ed336e3c986985fb4786926151c9cf7e50064f299338ca"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1416",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grimand crafted barding lined with runecloth and plated with arcanite. Arthas' Tears and Stratholme holy water served its spiritual preparation, while his fee included the saddle and stirrups.",["title"]="Grimand Elmore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7648:description:1-67","7648:description:72-96","7648:description:99-228","7648:description:231-291","7648:description:296-358","7648:description:361-436","7648:objective:1-109"},["minimumStage"]=2,["questID"]=7648,["sourceHash"]="3d23921422ecaf5cb87fae9d1545d2f61aa0836c48c358f1c9a8bbf6277212ae"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1416",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grimand had personally made barding for Grayson's own charger. He took pride in judging a later commission equal to that earlier work.",["title"]="Grimand Elmore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7643:description:1-78","7643:description:81-137","7643:description:140-198","7643:description:201-239","7643:description:244-283","7643:description:286-342","7643:description:345-383","7643:description:386-454","7643:description:456-486","7643:objective:1-59","7643:objective:62-131","7643:objective:136-204","7643:objective:207-251","7643:objective:254-313","7643:objective:316-372","7643:completion:1-154","7643:completion:156-292"},["minimumStage"]=4,["questID"]=7643,["sourceHash"]="b652d6f4d95c9769bcfed3f90b9aa7d7874d5b9462f4868cb703af257f39873f"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-14566",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Ancient Equine Spirit accepted enchanted horse feed and nuzzled the container as it ate. It then positioned itself as if inviting the offered barding onto its back.",["title"]="Ancient Equine Spirit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7644:description:1-89","7644:description:92-233","7644:description:238-285","7644:description:288-379","7644:objective:1-110"},["minimumStage"]=2,["questID"]=7644,["sourceHash"]="76418579e06da38d381bf87a0a29962791776b3e63e77e71c61b410cc48d6cb2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14566",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The barding glowed faintly while resting on the spirit's back, then returned to its bearer. That moment was understood as the blessing needed for the fallen charger's harness.",["title"]="Ancient Equine Spirit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7646:description:1-118","7646:description:121-158","7646:description:161-276","7646:description:281-333","7646:description:336-436","7646:description:439-511","7646:objective:1-126","7646:completion:1-65","7646:completion:67-99","7646:completion:104-193","7646:completion:195-231","7646:completion:233-318","7646:completion:320-402","7646:completion:404-483"},["minimumStage"]=4,["questID"]=7646,["sourceHash"]="834433d036546e6626f907e6c768b9dc6553d98294c867fb5c70d02cb884b8e2"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-14568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The fallen charger had once been noble, but its hollowed soul served Death Knight Darkreaver. Grayson placed its skeletal remains among the dead in Scholomance's Great Ossuary.",["title"]="Darkreaver's Fallen Charger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7647:description:1-68","7647:description:73-195","7647:description:198-288","7647:description:291-391","7647:description:394-480","7647:description:485-494","7647:objective:1-90","7647:objective:93-145","7647:objective:148-213","7647:objective:216-274","7647:objective:279-376","7647:completion:1-112","7647:completion:114-233","7647:completion:235-317","7647:completion:319-418","7647:completion:423-461","7647:completion:463-478"},["minimumStage"]=4,["questID"]=7647,["sourceHash"]="db046d5646a961ae4c786b068073c8bac5b3270d5cf83e0e4fd929fc177d3513"}},["questSourceProofsMode"]="ALL"},["field"]="outcome",["id"]="catalog-unit-14568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Returning the redeemed soul and blessed barding brought a glimmer of life to the charger's eyes. The beast nuzzled its rescuer's hand as the burden of its past service lifted.",["title"]="Darkreaver's Fallen Charger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7582:description:1-155","7582:description:157-218","7582:description:223-329","7582:description:334-399","7582:objective:1-127","7582:objective:129-197"},["minimumStage"]=2,["questID"]=7582,["sourceHash"]="eacad3eb0882af97ff16c8c7326dc24c03d3bdcde8d51e69ed628958a95efdb0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16005",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Daio directed crystal gatherers to the Hederine demons in Darkwhisper Gorge beneath Mount Hyjal's foothills. Their matured fel poison supplied the anti-magic Tears needed for his proposed Doomguard prison.",["title"]="Darkwhisper Gorge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7624:description:1-33","7624:description:36-52","7624:description:57-169","7624:description:172-237","7624:description:242-283","7624:description:286-350","7624:description:353-412","7624:description:415-449","7624:objective:1-80"},["minimumStage"]=2,["questID"]=7624,["sourceHash"]="2df178147cfe60d7bf6885aa519683bd97c7ed579d1e63b73ab5c96399ef3c06"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16362",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Banehollow placed Ulathek's quarters in western Shadow Hold. His demand to confront the suspected spy made the location part of his rivalry with Hel'nurath.",["title"]="Shadow Hold"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7640:description:1-108","7640:description:111-212","7640:description:215-377","7640:description:382-473","7640:objective:1-73","7640:objective:76-194"},["minimumStage"]=2,["questID"]=7640,["sourceHash"]="5922a689d7c235a6ef04f6643c0ddbcd6eb9d6c0a5d6ff74382907c0580835f2"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-2627",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Green auras marked disturbed ground in Terrordale, where spiritual torment strained the physical world. Grayson's censer was attuned to expose the spirits at those places.",["title"]="Terrordale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8960:description:1-48","8960:description:51-99","8960:description:102-195","8960:description:200-304","8960:objective:1-110","8960:completion:1-33","8960:completion:35-61","8960:completion:66-86","8960:completion:88-154","8960:completion:156-359","8960:completion:364-404","8960:completion:406-422"},["minimumStage"]=4,["questID"]=8960,["sourceHash"]="52365c4d2a2b121df9488cca32345e2c48daeae30893d552476fa1a42fa9a023"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16033",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bodley asked for help undoing his mercenary company's theft from Valthalak. Reuniting the amulet's stolen fragments offered a way to address the curse that had followed the company.",["title"]="Bodley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8996:description:1-135","8996:description:137-264","8996:description:269-337","8996:description:339-381","8996:description:383-390","8996:objective:1-81","8996:completion:1-27","8996:completion:29-188","8996:completion:193-216","8996:completion:218-318","8996:completion:323-332","8996:completion:334-386","8996:completion:388-501"},["minimumStage"]=4,["questID"]=8996,["sourceHash"]="52e7950c144b54e5205be6e7f9cb71377726f64b166785c3356efc1e76c6f625"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-16033",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bodley understood Valthalak's response as a reprieve from spectral assassins and stalkers, though not an unconditional pardon. He regarded the restoration of the spirit as partial absolution for the company's past.",["title"]="Bodley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8961:description:1-105","8961:description:107-179","8961:description:184-344","8961:description:346-507","8961:objective:1-170"},["minimumStage"]=2,["questID"]=8961,["sourceHash"]="f8601570b43320a8013e8f4354b00a877a12328fc999854866dc994e0a140d81"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16033",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bodley's brazier required fire drawn from Incendius, Emberseer and the Duke of Cynders. A later focus tied to a particular mercenary would determine which corrupted spirit it could call.",["title"]="Bodley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8948:description:1-61","8948:description:64-116","8948:description:121-216","8948:description:221-296","8948:description:299-327","8948:description:329-347","8948:description:350-396","8948:objective:1-91"},["minimumStage"]=2,["questID"]=8948,["sourceHash"]="f8b0fd29126e5a7827afa411b19e83204d375d42261b3d98a8237f028c01d9c3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-16016",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anthion knew Falrin as an old acquaintance skilled in aggravating people. He sent the unfinished banner to Dire Maul's library for the enchantment that would force Theldren into a challenge.",["title"]="Anthion Harmon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8949:description:1-73","8949:description:76-162","8949:description:167-236","8949:description:239-340","8949:description:345-368","8949:description:371-388","8949:description:391-460","8949:description:463-507","8949:objective:1-138","8949:completion:1-7","8949:completion:9-103","8949:completion:108-146","8949:completion:148-179"},["minimumStage"]=4,["questID"]=8949,["sourceHash"]="2ca1f7200b5b037f242c1999d6c3de4d9f397f99f3ac3406e6eb14ffe136a47c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16032",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Falrin's hatred of Gordok and Omokk's ogres stemmed from his brother's death at their hands. Even a pile of warbeads failed to ease the grief behind his demand for vengeance.",["title"]="Falrin Treeshaper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8950:description:1-71","8950:description:74-183","8950:description:188-335","8950:description:338-399","8950:objective:1-130"},["minimumStage"]=2,["questID"]=8950,["sourceHash"]="0c4508847ff428cd2c50670055fb85477eb79155adc7b62cb89e53223accd32e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16032",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Falrin's unusual provocation enchantment required an Eldreth ghost's essence, dark runes and brilliant shards. He lacked the materials because such a charm was rarely requested.",["title"]="Falrin Treeshaper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7703:description:1-103","7703:description:106-233","7703:description:238-284","7703:description:287-356","7703:description:359-481","7703:description:484-499","7703:objective:1-82","7703:objective:87-239"},["minimumStage"]=2,["questID"]=7703,["sourceHash"]="30ec8c2fbcfbb917e18eb4504f998c6afcea32b48cda0902a86fd5d70162af28"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14325",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kromcrush's inherited stories made the return of the Gauntlet of Gordok Might proof of a true ruler. He accused Tortheldrin of stealing it from an earlier Gordok king.",["title"]="Captain Kromcrush"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7703:description:1-103","7703:description:106-233","7703:description:238-284","7703:description:287-356","7703:description:359-481","7703:description:484-499","7703:objective:1-82","7703:objective:87-239","7703:completion:1-6","7703:completion:8-37","7703:completion:39-83","7703:completion:85-127","7703:completion:129-172","7703:completion:174-200","7703:completion:205-299","7703:completion:301-432","7703:completion:437-467","7703:completion:469-508"},["minimumStage"]=4,["questID"]=7703,["sourceHash"]="30ec8c2fbcfbb917e18eb4504f998c6afcea32b48cda0902a86fd5d70162af28"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14325",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="As Gordok captain, Kromcrush had learned how to awaken the ancient mark on the recovered gauntlet. He offered to restore its power after recognizing the artifact.",["title"]="Captain Kromcrush"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7848:description:1-49","7848:description:51-172","7848:description:177-186","7848:description:188-194","7848:description:196-273","7848:description:278-334","7848:description:339-364","7848:description:366-386","7848:description:388-446","7848:description:448-511","7848:objective:1-88","7848:objective:90-180"},["minimumStage"]=2,["questID"]=7848,["sourceHash"]="55bf4662ffa66b3e3938b70becac2831727cc03c9000b9c3044adc7619f92edb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14387",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lothos perceived rifts invisible to ordinary senses, including a passage from Blackrock Mountain to the Firelord's domain. A core fragment would let him attune another traveler to that portal.",["title"]="Lothos Riftwaker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7786:description:1-36","7786:description:38-72","7786:description:74-130","7786:description:135-178","7786:objective:1-218"},["minimumStage"]=2,["questID"]=7786,["sourceHash"]="ca675488a539a708e258162500d9dcb875a4d0f6220a9c6f2cbc1bcfc69d9c35"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14347",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Demitrian sought Thunderaan's release from his prison, demanding both bindings, elementium and the Firelord's essence. He promised the Windseeker's blessing in return for those preparations.",["title"]="Highlord Demitrian"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7787:description:1-34","7787:description:36-168","7787:objective:1-60","7787:completion:1-22","7787:completion:24-31","7787:completion:33-47","7787:completion:49-93"},["minimumStage"]=4,["questID"]=7787,["sourceHash"]="7a5a3bb7fd5f0adec3ede6486d83878c618d32b5146bed0dce951f9716e14380"}},["questSourceProofsMode"]="ALL"},["field"]="outcome",["id"]="catalog-unit-14347",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After the Windseeker's defeat, Demitrian pleaded for his life and yielded the awakened blade. The confrontation exposed the betrayal behind his earlier promise.",["title"]="Highlord Demitrian"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7604:description:1-152","7604:description:154-358","7604:description:363-432","7604:description:458-466","7604:objective:1-118"},["minimumStage"]=2,["questID"]=7604,["sourceHash"]="111e3580eff37fdd136b53d6b360d8cbe7b206b8a6e776bb6b25c183e847e127"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lokhtos received a Thorium Brotherhood contract exchanging a genuine Sulfuron ingot for forging plans. Its terms denied the Brotherhood's liability for harm arising from the signatory's pursuit of Sulfuras.",["title"]="Lokhtos Darkbargainer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8883:description:1-78","8883:description:81-239","8883:description:244-377","8883:objective:1-75","8883:objective:77-134"},["minimumStage"]=2,["questID"]=8883,["sourceHash"]="3892d56311ab2750611e902fb85eb4c80532a2b476a0f11f754b0a8478861ab9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15864",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Valadar and his sister Fariel received Lunar Festival visitors in Nighthaven, opening the secluded village to people eager to share the celebration.",["title"]="Valadar Starsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8868:description:1-45","8868:description:48-179","8868:description:182-274","8868:description:279-364","8868:description:367-417","8868:description:422-478","8868:description:481-507","8868:objective:1-50","8868:objective:53-92","8868:completion:1-19","8868:completion:22-84","8868:completion:87-192","8868:completion:197-352"},["minimumStage"]=4,["questID"]=8868,["sourceHash"]="a0c8822f1860b70c39a85b50c06518052543c629fa947f4f7b85fcd4b5100a7d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15864",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Valadar described victory over Omen as a temporary gift of peace. Elune's blessing prevented the beast's true death, but defeat returned his spirit to the lake and quieted his anger for another year.",["title"]="Valadar Starsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8897:description:1-93","8897:description:95-173","8897:description:175-252","8897:description:257-287","8897:description:289-323","8897:description:325-343","8897:description:348-390","8897:description:392-461","8897:objective:1-96","8897:completion:1-21","8897:completion:23-73","8897:completion:75-110","8897:completion:115-129","8897:completion:131-160","8897:completion:162-197","8897:completion:199-208"},["minimumStage"]=4,["questID"]=8897,["sourceHash"]="81f42bde3cd3ad3eb69c6d44efafec79ac6309fe89d39e7dc4f871386d865161"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-16002",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Colara received Heldric's first written gift with pleasure and briefly imagined taking his name. His gate duty, modest pay and fear of deployment had made the letter an anxious declaration.",["title"]="Colara Dean"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8902:description:1-73","8902:description:75-171","8902:description:176-280","8902:description:285-315","8902:description:317-358","8902:description:360-397","8902:objective:1-85","8902:completion:1-50","8902:completion:52-62","8902:completion:64-102","8902:completion:104-168","8902:completion:170-216","8902:completion:221-240","8902:completion:245-301","8902:completion:303-337"},["minimumStage"]=4,["questID"]=8902,["sourceHash"]="fd015e1ed6f0d02d34d72ca628ea71dacff66cf6dd6ae83109ab3a97270d416f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-16004",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Elenia remembered a childhood betrothal, a hoped-for lakeside wedding and a quiet farm in retirement. Her changed body made her fear that the former beloved would no longer recognize the woman in those memories.",["title"]="Elenia Haydon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8901:description:1-36","8901:description:38-125","8901:description:127-218","8901:description:223-282","8901:description:287-332","8901:description:334-368","8901:description:370-398","8901:objective:1-85","8901:completion:1-36","8901:completion:38-111","8901:completion:113-160","8901:completion:165-232","8901:completion:234-269"},["minimumStage"]=4,["questID"]=8901,["sourceHash"]="688da989e4d39ce584bf7794c03f4d8b3b23eade9237e4f1c34f9cff6a53678a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16004",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Elenia was moved by Temma's kindness but could not imagine accepting a tauren's love. She was grateful to receive his words through a letter rather than have to wound him face to face.",["title"]="Elenia Haydon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8984:description:1-59","8984:description:61-153","8984:description:158-212","8984:description:217-270","8984:description:272-353","8984:description:355-407","8984:objective:1-81","8984:completion:1-29","8984:completion:31-56","8984:completion:58-70","8984:completion:75-223","8984:completion:228-261","8984:completion:263-324","8984:completion:329-355","8984:completion:357-399","8984:completion:401-441","8984:completion:443-497"},["minimumStage"]=4,["questID"]=8984,["sourceHash"]="43bd0a3712e1cbf3d57eb4e86a2963b8aa4d03bdd8437baaedb77190b570ed91"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16107",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Staffron admitted designing fragrances to distract both Alliance and Horde warriors through obsessive affection. He expected their concern for loved ones to leave them unable to oppose the Shadow Council.",["title"]="Apothecary Staffron Lerent"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8979:description:1-51","8979:description:53-129","8979:description:131-188","8979:description:193-243","8979:description:248-351","8979:description:353-401","8979:description:406-462","8979:objective:1-96"},["minimumStage"]=2,["questID"]=8979,["sourceHash"]="01b778a213a719758e7ffd2bc25d3b073e96f99f24526cc37d3622169228c4aa"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16108",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fenstad suspected the fashionable perfumes and colognes of clouding minds through alchemy. He sent samples to Zinge rather than accepting the city's sudden infatuation as harmless.",["title"]="Fenstad Argyle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8903:description:1-56","8903:description:58-167","8903:description:172-248","8903:description:250-272","8903:description:277-372","8903:objective:1-74"},["minimumStage"]=2,["questID"]=8903,["sourceHash"]="9b3d5dd69c0ca265aef329dffdd8d5129d09681ef7e03d52f4c65c2999ee31f6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16105",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aristan feared that unnatural affection had reached Stormwind's guards and weakened the Alliance's safety. A guard's card was his first requested evidence that the watch shared the affliction.",["title"]="Aristan Mottar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8980:description:1-19","8980:description:21-77","8980:description:79-136","8980:description:141-237","8980:description:239-327","8980:objective:1-59"},["minimumStage"]=2,["questID"]=8980,["sourceHash"]="b6f2b664a2018f9d6246b0b6e5e0ac4998eef6620e46f5d9de28a7b4572e3212"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5204",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zinge detected substances associated with mind-control draughts in the fashionable fragrances. Some ingredients suggested work sophisticated enough for a Royal Apothecary Society practitioner.",["title"]="Apothecary Zinge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9025:description:1-14","9025:description:16-72","9025:description:74-160","9025:description:165-261","9025:description:263-275","9025:objective:1-72"},["minimumStage"]=2,["questID"]=9025,["sourceHash"]="d84497b09aa859fbda4c09014d7f25c4add713d59a13a4139811571af38fa281"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-279",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Morgan found traces associated with love potions and more insidious mind-altering mixtures in the fragrances. The analysis made him reconsider his initial dismissal of Aristan's concerns.",["title"]="Morgan Pestle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9051:description:1-56","9051:description:59-151","9051:description:154-266","9051:description:271-335","9051:description:338-410","9051:objective:1-41","9051:objective:43-121"},["minimumStage"]=2,["questID"]=9051,["sourceHash"]="b3cad26ebc7ad650b5c77a8960849516dbeba338ba41cab8f62d4ee3f512937a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9619",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Torwa sought to pacify Un'Goro's devilsaurs because killing one merely allowed another to occupy its territory. His proposed toxin was intended to make hunting and survival safer without simply repeating that cycle.",["title"]="Torwa Pathfinder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"9053:description:1-79","9053:description:84-278","9053:description:281-347","9053:description:352-382","9053:objective:1-107","9053:completion:1-42","9053:completion:44-138","9053:completion:143-173","9053:completion:175-210"},["minimumStage"]=4,["questID"]=9053,["sourceHash"]="a9ee3079523291f0ef226542cb793ed39d9c86f0df0705657005e476bff892eb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9619",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Torwa's original toxin was too weak for its intended beast. A guardian's putrid vine from the Sunken Temple allowed a stronger preparation, but he declined to demand a second dangerous test.",["title"]="Torwa Pathfinder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9033:description:1-32","9033:description:37-86","9033:description:88-127","9033:description:132-170","9033:description:172-239","9033:description:244-264","9033:description:266-287","9033:description:289-439","9033:description:444-492","9033:objective:1-188"},["minimumStage"]=2,["questID"]=9033,["sourceHash"]="942bce3ea220243682961b1964722cf3822271863c84ee09ec4a41eea5c7abe9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16115",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eligor saw Kel'Thuzad's renewed preparations as proof that the last war had never extinguished the Scourge threat. He demanded a demonstration inside Naxxramas before offering the defenders' support.",["title"]="Commander Eligor Dawnbringer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9153:description:1-86","9153:description:88-206","9153:description:211-269","9153:description:274-362","9153:description:364-474","9153:objective:1-52","9153:objective:54-123","9153:objective:125-237"},["minimumStage"]=2,["questID"]=9153,["sourceHash"]="b43e0c35a4573c60b7090b3a8c9be29e01f74c1356db9f8161ed1725eb141d42"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16361",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Helleran coordinated attacks on the Scourge's invasion circles. Destroying surrounding undead weakened their defenses, while recovered necrotic runes could support further resistance.",["title"]="Commander Thomas Helleran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9085:description:1-172","9085:description:177-204","9085:description:206-274","9085:description:276-383","9085:objective:1-139"},["minimumStage"]=2,["questID"]=9085,["sourceHash"]="741e70480d5d1c96b6dfa5cfb79be2cdb8803507b65be2b288815a451de4e593"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16361",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Helleran warned that the acolytes guarding exposed circles were really shadows. Necrotic runes could reveal the creatures before defenders fought them directly.",["title"]="Commander Thomas Helleran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9229:description:1-103","9229:description:105-174","9229:description:179-266","9229:description:268-325","9229:description:327-431","9229:description:433-449","9229:description:454-503","9229:objective:1-50"},["minimumStage"]=2,["questID"]=9229,["sourceHash"]="6454d20e2918819502b5983d335973fefdd2299025d90fa695829d6922593ac7"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-16112",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Korfax remembered Ramaladni as Mograine's pupil from before the Argent Dawn. News of his teacher's death drove the warrior into Naxxramas in rage, and he never returned.",["title"]="Korfax, Champion of the Light"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9230:description:1-55","9230:description:57-150","9230:description:152-249","9230:description:251-319","9230:objective:1-130"},["minimumStage"]=2,["questID"]=9230,["sourceHash"]="b784edcd9ad6b048f919c22c61b7e8b54494a1f52ab4322726de17f9a5985d9b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16112",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Korfax could repair Ramaladni's ruined ring with a frozen rune, blue sapphire and arcanite. The original band had been made from the same runes that formed within Scourge structures.",["title"]="Korfax, Champion of the Light"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9232:description:1-42","9232:description:44-114","9232:description:116-177","9232:description:182-197","9232:description:202-227","9232:description:229-277","9232:description:282-313","9232:description:315-342","9232:description:344-423","9232:objective:1-163"},["minimumStage"]=2,["questID"]=9232,["sourceHash"]="4e47e5ece6e8406cdb2a75afd8d9355f4560c79da58eb513e31931639176cbff"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16376",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wilhelm initially had only one recipe from Omarion, adaptable into several pairs of trousers. He offered the craft to Naxxramas's hopeful defenders for their materials and a fee.",["title"]="Craftsman Wilhelm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"9233:description:1-8","9233:description:13-63","9233:description:65-175","9233:description:177-274","9233:description:279-327","9233:description:329-379","9233:description:381-473","9233:description:478-488","9233:description:493-499","9233:objective:1-95","9233:completion:1-55","9233:completion:57-97","9233:completion:102-160","9233:completion:162-245"},["minimumStage"]=4,["questID"]=9233,["sourceHash"]="6c9b8e93d76178300f5cddcdcc10007ef58d8327475b3d55626289d8d76e9ae1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-16376",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wilhelm insisted that he and Omarion had been close despite the dead craftsman's insulting final letter. The recovered handbook expanded the work he could offer at Light's Hope.",["title"]="Craftsman Wilhelm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9233:description:1-8","9233:description:13-63","9233:description:65-175","9233:description:177-274","9233:description:279-327","9233:description:329-379","9233:description:381-473","9233:description:478-488","9233:description:493-499","9233:objective:1-95"},["minimumStage"]=2,["questID"]=9233,["sourceHash"]="6c9b8e93d76178300f5cddcdcc10007ef58d8327475b3d55626289d8d76e9ae1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16365",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Omarion's final handbook left his remaining recipes to Wilhelm with orders to serve its bearer. His message mixed that practical bequest with contemptuous judgments of his associate's craft and fees.",["title"]="Master Craftsman Omarion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"9154:description:1-70","9154:description:73-112","9154:description:115-202","9154:description:207-328","9154:objective:1-115","9154:completion:1-78","9154:completion:80-132","9154:completion:134-235"},["minimumStage"]=4,["questID"]=9154,["sourceHash"]="4041979e811241a14e40a7725e5d4f79bda702abcf49dc81752c44f1c254aec6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16281",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Keeper of the Rolls received recruits answering the Argent Dawn's invasion call. With no time to train them, he trusted the abilities they brought to Light's Hope.",["title"]="Keeper of the Rolls"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9362:description:1-26","9362:description:29-87","9362:description:90-190","9362:description:195-303","9362:description:306-372","9362:objective:1-48","9362:objective:51-109"},["minimumStage"]=2,["questID"]=9362,["sourceHash"]="65c7d9db9fff24cda7e5b04e9f1e2a7e165e250c7576e19d543592f7e00067cb"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8379",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xylem's scrying revealed powerful magic in Krellian's prismatic shell. Unable to leave his tower, he sought someone to take it from the warlord at Zin-Malor's temple.",["title"]="Archmage Xylem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9364:description:1-66","9364:description:71-144","9364:description:147-274","9364:description:277-359","9364:description:364-403","9364:objective:1-89","9364:objective:92-168"},["minimumStage"]=2,["questID"]=9364,["sourceHash"]="64429407bde4921cb1960db26bdd640eac5d05555cb8b0a5d36c63281d7873ac"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8379",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xylem discovered that the shell's aura could split polymorphed Spitelash into temporary clones. Destroying the copies would collect their essence for the creation of a new spell.",["title"]="Archmage Xylem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8963:description:1-19","8963:description:21-231","8963:description:236-305","8963:description:307-485","8963:objective:1-85"},["minimumStage"]=2,["questID"]=8963,["sourceHash"]="8ca11256fdbfb36cf4af9d4a080e063be70d38feb9ef55f5d4e563f2c5b29649"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-260",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bodley remembered Starbreeze as Isalien's childhood home. A relic taken by Frostmaul raiders could serve as a focus for summoning her corrupted spirit.",["title"]="Starbreeze Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8985:description:1-19","8985:description:21-239","8985:description:244-313","8985:description:315-493","8985:objective:1-85"},["minimumStage"]=2,["questID"]=8985,["sourceHash"]="9d7358a665c88045e8243a32f85d311ccbad5aaa75625087fa937bbde3c1a40c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-2249",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Frostmaul giants of Frostwhisper Gorge were known to raid northward. Bodley's search for Isalien's summoning focus led to a Starbreeze relic among the spoils they carried.",["title"]="Frostwhisper Gorge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"8964:description:1-19","8964:description:21-233","8964:description:238-319","8964:description:321-377","8964:description:379-488","8964:objective:1-89"},["minimumStage"]=2,["questID"]=8964,["sourceHash"]="eeca6bd46ea4abb400be0c308c6aa19d8bee983ff083866f573f781ae3c5121d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16370",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bodley sought a brilliant sword from Tyr's Hand's praetorians to evoke Jarien and Sothos's ambition to become Scarlet knights. The weapon would be infused into the summoning brazier.",["title"]="Tyr's Hand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"9362:description:1-26","9362:description:29-87","9362:description:90-190","9362:description:195-303","9362:description:306-372","9362:objective:1-48","9362:objective:51-109"},["minimumStage"]=2,["questID"]=9362,["sourceHash"]="65c7d9db9fff24cda7e5b04e9f1e2a7e165e250c7576e19d543592f7e00067cb"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1223",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krellian guarded a prismatic shell within the Temple of Zin-Malor. Xylem's scrying drew an expedition there to recover the artifact's unusual magic.",["title"]="Temple of Zin-Malor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"9052:description:1-105","9052:description:108-192","9052:description:197-292","9052:description:295-412","9052:objective:1-90"},["minimumStage"]=2,["questID"]=9052,["sourceHash"]="151973476dd4f0fcb4cc65c2637d4cd04e5bc7e66cbd25c8a4e4c4ddaa7c3c10"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-540",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gorishi insects inside and around the Slithering Scar supplied stings for Torwa's nonlethal toxin. Bloodcap mushrooms gathered elsewhere in the crater completed the first preparation.",["title"]="The Slithering Scar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7945:description:1-48","7945:description:53-114","7945:description:117-185","7945:description:188-278","7945:objective:1-61"},["minimumStage"]=2,["questID"]=7945,["sourceHash"]="da86ba411afa18a7cc3d8a6b8f6d7b0860c7d0d3cc22ace03016236154b4cafb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-818",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sayge's fortune showed a stump near Palemane Rock's cave entrance. The warm slip's vision turned the surrounding Mulgore landmark into the destination of a hidden-treasure search.",["title"]="Palemane Rock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3520:description:1-53","3520:description:56-132","3520:description:137-177","3520:description:180-290","3520:description:293-337","3520:description:340-380","3520:description:385-502","3520:objective:1-94"},["minimumStage"]=2,["questID"]=3520,["sourceHash"]="79a7cd0a92add0e26661b2830affb43f76001f4da25bb98edff5c26552762952"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8579",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yeh’kinya sought the spirits of Feralas’s vale screechers, claiming that their kinship to an ancient god linked their souls to him.",["title"]="Yeh'kinya"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3520:description:1-53","3520:description:56-132","3520:description:137-177","3520:description:180-290","3520:description:293-337","3520:description:340-380","3520:description:385-502","3520:objective:1-94"},["minimumStage"]=2,["questID"]=3520,["sourceHash"]="79a7cd0a92add0e26661b2830affb43f76001f4da25bb98edff5c26552762952"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8579",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His bramble wand could coax a fallen screecher’s spirit into view so that its essence could be gathered.",["title"]="Yeh'kinya"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3524:description:1-111","3524:description:113-185","3524:description:188-324","3524:description:329-436","3524:description:439-508","3524:objective:1-144"},["minimumStage"]=2,["questID"]=3524,["sourceHash"]="744aa49c2dbbc084db686a4bc522d107aa1e6ee09d742fb0eb5de5ced41ac48b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10219",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Temple of the Moon sent Gwennyth to investigate the growing number of sea creatures dying on Darkshore’s beaches.",["title"]="Gwennyth Bly'Leggonde"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3524:description:1-111","3524:description:113-185","3524:description:188-324","3524:description:329-436","3524:description:439-508","3524:objective:1-144"},["minimumStage"]=2,["questID"]=3524,["sourceHash"]="744aa49c2dbbc084db686a4bc522d107aa1e6ee09d742fb0eb5de5ced41ac48b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10219",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Greymist murlocs crowded the stranded creature south of Auberdine, preventing her from collecting the bones she needed for study.",["title"]="Gwennyth Bly'Leggonde"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1030:description:1-58","1030:description:63-168","1030:description:170-195","1030:description:200-348","1030:description:350-455","1030:description:460-511","1030:objective:1-97"},["minimumStage"]=2,["questID"]=1030,["sourceHash"]="9bc44ba7d94e6f385f8cf57b3bda881d801cc2bd35003245098b82d790b6aa3c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3691",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Raene believed Dartol’s rod might let someone approach the tainted furbolgs in another form, though she did not yet know what that form would be.",["title"]="Raene Wolfrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1031:description:1-60","1031:description:62-179","1031:description:181-199","1031:description:201-315","1031:objective:1-76"},["minimumStage"]=2,["questID"]=1031,["sourceHash"]="bd776a9bb44d01b7c7ddae4cc22ac3f741e37def10742f08e3f0b433266cce1a"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3920",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anilia’s last words named Geltharis as the one who had taken the Branch of Cenarius; her dying wish was its return to dryad hands.",["title"]="Anilia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1031:description:1-60","1031:description:62-179","1031:description:181-199","1031:description:201-315","1031:objective:1-76"},["minimumStage"]=2,["questID"]=1031,["sourceHash"]="bd776a9bb44d01b7c7ddae4cc22ac3f741e37def10742f08e3f0b433266cce1a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4619",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anilia accused Geltharis of taking the Branch of Cenarius as she lay dying near the northern arch.",["title"]="Geltharis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"973:description:1-17","973:description:19-47","973:description:49-176","973:description:181-299","973:objective:1-72"},["minimumStage"]=2,["questID"]=973,["sourceHash"]="9eb1fb71cdeaa2997be301118be536df63ac07c30d5c28faf4e5cec139d5f73b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3663",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Delgren had long known of Ilkrud Magthrull’s evil at Fire Scar Shrine, but the orc warlock’s growing involvement finally demanded action.",["title"]="Delgren the Purifier"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"973:description:1-17","973:description:19-47","973:description:49-176","973:description:181-299","973:objective:1-72"},["minimumStage"]=2,["questID"]=973,["sourceHash"]="9eb1fb71cdeaa2997be301118be536df63ac07c30d5c28faf4e5cec139d5f73b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3664",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ilkrud was a powerful orc warlock dwelling at Fire Scar Shrine in southwestern Ashenvale.",["title"]="Ilkrud Magthrull"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"974:description:1-51","974:description:53-82","974:description:87-208","974:description:210-324","974:description:326-374","974:description:379-472","974:objective:1-80","974:objective:85-167","974:objective:169-212"},["minimumStage"]=2,["questID"]=974,["sourceHash"]="5990713b2038ba5fd950a9963446397ec58af950c5a0944aad022f57250a8129"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10302",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krakle wanted to determine whether Fire Plume Ridge heated the nearby hot springs. His own thermometer measured the volcano in degrees Kraklenheit.",["title"]="Krakle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1011:description:1-107","1011:description:110-189","1011:description:192-212","1011:description:217-352","1011:description:355-414","1011:description:417-442","1011:description:445-480","1011:objective:1-62"},["minimumStage"]=2,["questID"]=1011,["sourceHash"]="f9bfa6651d92897ee71909daa78ebd2c7cdf5bdf0f044834ec5d40ee68263c22"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3848",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kayneth wanted a disease sample from the Forsaken camp near Dor’Danil so he could test whether their work threatened Ashenvale.",["title"]="Kayneth Stillwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1012:description:1-61","1012:description:64-132","1012:description:134-156","1012:description:159-227","1012:description:232-418","1012:description:423-449","1012:objective:1-119"},["minimumStage"]=2,["questID"]=1012,["sourceHash"]="e14da351eb73371793cb7ce01e49cac2273bf3590cde639fae50ef29da4d07d5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3848",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="While struggling with Forsaken poisons, Kayneth experienced a vision of the barrow druids murdered and driven mad as disembodied spirits.",["title"]="Kayneth Stillwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1012:description:1-61","1012:description:64-132","1012:description:134-156","1012:description:159-227","1012:description:232-418","1012:description:423-449","1012:objective:1-119"},["minimumStage"]=2,["questID"]=1012,["sourceHash"]="e14da351eb73371793cb7ce01e49cac2273bf3590cde639fae50ef29da4d07d5"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3940",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kayneth’s vision named Taneel among Dor’Danil’s former druid leaders, now a restless spirit after the Forsaken poisoning.",["title"]="Taneel Darkwood"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1012:description:1-61","1012:description:64-132","1012:description:134-156","1012:description:159-227","1012:description:232-418","1012:description:423-449","1012:objective:1-119"},["minimumStage"]=2,["questID"]=1012,["sourceHash"]="e14da351eb73371793cb7ce01e49cac2273bf3590cde639fae50ef29da4d07d5"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3941",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Uthil was one of the barrow’s former druid leaders whom Kayneth’s vision described as poisoned and severed from his body.",["title"]="Uthil Mooncall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1012:description:1-61","1012:description:64-132","1012:description:134-156","1012:description:159-227","1012:description:232-418","1012:description:423-449","1012:objective:1-119"},["minimumStage"]=2,["questID"]=1012,["sourceHash"]="e14da351eb73371793cb7ce01e49cac2273bf3590cde639fae50ef29da4d07d5"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3942",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kayneth named Mavoris among the once-great leaders now haunting Dor’Danil after the druids’ poisoning.",["title"]="Mavoris Cloudsbreak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"986:description:1-54","986:description:56-122","986:description:124-255","986:description:260-379","986:description:381-473","986:objective:1-72"},["minimumStage"]=2,["questID"]=986,["sourceHash"]="dc2d4568b57915a77e6bac628b15fc11516599c581c74e6499a05259fd95cd4d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3693",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Terenthis wanted to reunite Grimclaw with his missing master Volcor, offering to make a cloak that would let the searcher pass unhindered among Darkshore’s beasts.",["title"]="Terenthis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2241:description:1-47","2241:description:52-110","2241:description:112-169","2241:description:171-279","2241:description:281-297","2241:description:302-322","2241:description:328-425","2241:description:430-466","2241:description:468-509","2241:objective:1-42"},["minimumStage"]=2,["questID"]=2241,["sourceHash"]="4704dc321d649d6fc8f76501ad70bd6fba6db2158debdd61133c7778db392989"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3599",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jannok’s obsessive affection for Syurna filled his home with her likeness and drove him to neglect food and sleep; she refused his messages.",["title"]="Jannok Breezesong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2241:description:1-47","2241:description:52-110","2241:description:112-169","2241:description:171-279","2241:description:281-297","2241:description:302-322","2241:description:328-425","2241:description:430-466","2241:description:468-509","2241:objective:1-42"},["minimumStage"]=2,["questID"]=2241,["sourceHash"]="4704dc321d649d6fc8f76501ad70bd6fba6db2158debdd61133c7778db392989"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4163",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Syurna refused to receive Jannok’s messages and would only speak to a fellow rogue, prompting him to seek another messenger.",["title"]="Syurna"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2381:description:1-121","2381:description:126-202","2381:description:204-261","2381:description:263-362","2381:description:367-427","2381:description:429-503","2381:objective:1-67","2381:objective:69-100","2381:objective:102-156","2381:objective:158-216","2381:objective:221-295"},["minimumStage"]=2,["questID"]=2381,["sourceHash"]="5c1fbcf44b5f726de5abc10ed62f6fbd72a91324d71bcb4aa76e5c069ec177af"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-7161",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wrenix sought the Southsea treasure in the hold of the Tide Razor, despite the deaths of the last five thieves he had sent.",["title"]="Wrenix the Wretched"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2381:description:1-121","2381:description:126-202","2381:description:204-261","2381:description:263-362","2381:description:367-427","2381:description:429-503","2381:objective:1-67","2381:objective:69-100","2381:objective:102-156","2381:objective:158-216","2381:objective:221-295"},["minimumStage"]=2,["questID"]=2381,["sourceHash"]="5c1fbcf44b5f726de5abc10ed62f6fbd72a91324d71bcb4aa76e5c069ec177af"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-7161",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The freebooters trained thieves on the ship’s second level, making their own den a dangerous place to practice the craft.",["title"]="Wrenix the Wretched"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1499:description:1-143","1499:description:148-216","1499:description:218-315","1499:objective:1-28"},["minimumStage"]=2,["questID"]=1499,["sourceHash"]="42b132e15351473d43bad79374209cabab70cf60f71c246180b094156d9e91e1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5765",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ruzan directed novice warlocks toward Zureetha after their work against the imps, treating further service as useful experience.",["title"]="Ruzan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1499:description:1-143","1499:description:148-216","1499:description:218-315","1499:objective:1-28"},["minimumStage"]=2,["questID"]=1499,["sourceHash"]="42b132e15351473d43bad79374209cabab70cf60f71c246180b094156d9e91e1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3145",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zureetha recruited novices to reduce the dangerous creatures in the cave beyond the vile familiars.",["title"]="Zureetha Fargaze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1520:description:1-63","1520:description:65-171","1520:description:173-314","1520:description:319-387","1520:description:392-461","1520:objective:1-41"},["minimumStage"]=2,["questID"]=1520,["sourceHash"]="9e821ecaff1224aecdc7029c6aaf3db88e5935deabe7bf3d414ffb29714f1547"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5888",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ravenfeather knew how to prepare a sapta that would bind a shaman’s spirit to an element and reveal it to the drinker.",["title"]="Seer Ravenfeather"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1519:description:1-28","1519:description:30-101","1519:description:103-146","1519:description:151-226","1519:description:228-250","1519:description:252-317","1519:description:322-436","1519:description:438-496","1519:objective:1-74"},["minimumStage"]=2,["questID"]=1519,["sourceHash"]="5e69c91927c7139f3ca22561591ba6eee48146f5c804e92472e88336821783b1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5888",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="For an initiate’s first potion, Ravenfeather sought the ritual salve used by Bristleback shamans in the eastern ravine.",["title"]="Seer Ravenfeather"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1521:description:1-89","1521:description:91-162","1521:description:164-296","1521:description:301-315","1521:description:317-330","1521:description:332-347","1521:description:349-379","1521:description:381-464","1521:objective:1-60"},["minimumStage"]=2,["questID"]=1521,["sourceHash"]="e98141152fd1d8fd23b91c951d325ac2198caa8b2a97c52b22e62a625e45d4ae"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5891",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The earth manifestation offered a small piece of quartz as a totem’s heart, teaching patience, endurance and respect through the strength of a humble stone.",["title"]="Minor Manifestation of Earth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1501:description:1-25","1501:description:27-68","1501:description:70-174","1501:description:179-228","1501:description:233-395","1501:description:397-475","1501:objective:1-63"},["minimumStage"]=2,["questID"]=1501,["sourceHash"]="c176b89672d1eb624be8c6ab0853b2f05fff6115586a2b50324d2504bbac83cc"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5875",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gan’rul wanted young warlocks to mature quickly enough to serve the Horde. Recovering the Burning Blade’s stolen Tablet of Verga would unlock the next summoning lesson.",["title"]="Gan'rul Bloodeye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1504:description:1-93","1504:description:95-176","1504:description:178-227","1504:description:232-318","1504:description:320-451","1504:objective:1-132"},["minimumStage"]=2,["questID"]=1504,["sourceHash"]="560671acd75bdfe859651f947e7afa80f2623f417a265c05cdbaa8ddee8bae46"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5875",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He taught the tablet’s glyphs and required an initiate to subdue a summoned voidwalker before learning to bind it.",["title"]="Gan'rul Bloodeye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1516:description:1-26","1516:description:28-86","1516:description:88-166","1516:description:171-254","1516:description:256-298","1516:description:300-362","1516:description:367-444","1516:description:446-503","1516:objective:1-72"},["minimumStage"]=2,["questID"]=1516,["sourceHash"]="32de5d228e4d4fad7de70510890b25b803f21a8bccdf1b781e2bf9692f017887"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5887",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Canaga guided young shamans toward their first meeting with earth, beginning the preparation with hooves taken from the northern felstalkers.",["title"]="Canaga Earthcaller"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"973:description:1-17","973:description:19-47","973:description:49-176","973:description:181-299","973:objective:1-72"},["minimumStage"]=2,["questID"]=973,["sourceHash"]="9eb1fb71cdeaa2997be301118be536df63ac07c30d5c28faf4e5cec139d5f73b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-417",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The powerful orc warlock Ilkrud Magthrull made his home in this place of evil in southwestern Ashenvale.",["title"]="Fire Scar Shrine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1012:description:1-61","1012:description:64-132","1012:description:134-156","1012:description:159-227","1012:description:232-418","1012:description:423-449","1012:objective:1-119"},["minimumStage"]=2,["questID"]=1012,["sourceHash"]="e14da351eb73371793cb7ce01e49cac2273bf3590cde639fae50ef29da4d07d5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-432",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kayneth’s vision described the old druid leaders as murdered by Forsaken poison, leaving errant spirits within their own barrow.",["title"]="The Dor'Danil Barrow Den"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1030:description:1-58","1030:description:63-168","1030:description:170-195","1030:description:200-348","1030:description:350-455","1030:description:460-511","1030:objective:1-97"},["minimumStage"]=2,["questID"]=1030,["sourceHash"]="9bc44ba7d94e6f385f8cf57b3bda881d801cc2bd35003245098b82d790b6aa3c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-421",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Raene’s search for a furbolg untouched by Fel Moss began southeast of the lake, where the transformed bearer of Dartol’s rod might safely seek answers.",["title"]="Mystral Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"986:description:1-54","986:description:56-122","986:description:124-255","986:description:260-379","986:description:381-473","986:objective:1-72"},["minimumStage"]=2,["questID"]=986,["sourceHash"]="dc2d4568b57915a77e6bac628b15fc11516599c581c74e6499a05259fd95cd4d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-15817",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Moonstalker sires and matriarchs near the river supplied the pelts Terenthis needed for a cloak of concealment.",["title"]="Wildbend River"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1501:description:1-25","1501:description:27-68","1501:description:70-174","1501:description:179-228","1501:description:233-395","1501:description:397-475","1501:objective:1-63"},["minimumStage"]=2,["questID"]=1501,["sourceHash"]="c176b89672d1eb624be8c6ab0853b2f05fff6115586a2b50324d2504bbac83cc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-817",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Burning Blade warlocks kept the stolen Tablet of Verga in their lair east of Orgrimmar.",["title"]="Skull Rock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1140:description:1-73","1140:description:75-210","1140:description:215-388","1140:description:393-509","1140:objective:1-115"},["minimumStage"]=2,["questID"]=1140,["sourceHash"]="7216b52ce07916d9325ef384b3c5d645f40417f6b5f1503a3fb706ee47a75272"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3663",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Delgren learned the orcs’ language despite his order’s ridicule, finding that understanding an enemy’s words helped uncover its designs.",["title"]="Delgren the Purifier"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"970:description:1-26","970:description:28-99","970:description:101-186","970:description:188-280","970:description:285-355","970:objective:1-83"},["minimumStage"]=2,["questID"]=970,["sourceHash"]="ea7a8fc10073f7205fdfb1bda39eb1d7d65719973cff021307a6c1762ea07a42"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3663",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Delgren sought a Dark Strand soul gem from Ordil’Aran, believing it held the secret of the cult’s power.",["title"]="Delgren the Purifier"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1141:description:1-15","1141:description:18-55","1141:description:58-89","1141:description:94-176","1141:description:179-296","1141:description:299-344","1141:description:349-395","1141:description:398-459","1141:description:462-502","1141:objective:1-56"},["minimumStage"]=2,["questID"]=1141,["sourceHash"]="a48265904e00e77306a73ac48bf367d9a248affb7b1014dbb2aa1774216da3f5"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10216",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gubber took pride in his family’s fishing tradition and the grouper caught along Darkshore.",["title"]="Gubber Blump"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1141:description:1-15","1141:description:18-55","1141:description:58-89","1141:description:94-176","1141:description:179-296","1141:description:299-344","1141:description:349-395","1141:description:398-459","1141:description:462-502","1141:objective:1-56"},["minimumStage"]=2,["questID"]=1141,["sourceHash"]="a48265904e00e77306a73ac48bf367d9a248affb7b1014dbb2aa1774216da3f5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10216",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Murlocs had halted the fishing boats Gubber used, leaving him to seek help catching the local grouper.",["title"]="Gubber Blump"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1138:description:1-12","1138:description:15-45","1138:description:48-99","1138:description:102-147","1138:description:150-263","1138:description:266-274","1138:description:276-291","1138:description:296-359","1138:description:362-428","1138:description:431-457","1138:description:460-499","1138:objective:1-57"},["minimumStage"]=2,["questID"]=1138,["sourceHash"]="4ca0c63b9fcbbce71b9f4085691cd860b0c5f662ebf15dda52cd73da9ef03ecc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10216",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gubber delighted in the many ways of cooking crab but was too occupied with fishing to gather the meat himself.",["title"]="Gubber Blump"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1142:description:1-26","1142:description:40-44","1142:description:49-120","1142:description:125-139","1142:description:141-150","1142:description:155-177","1142:description:179-209","1142:description:211-219","1142:description:221-256","1142:description:261-281","1142:description:283-323","1142:description:328-365","1142:description:367-372","1142:objective:1-72"},["minimumStage"]=2,["questID"]=1142,["sourceHash"]="6a873ff2803c25b73e470073cef28578cf79459e70a78a4376b1a4c37f9e53e0"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4510",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Heralath lay dying in Razorfen Kraul after sending the dwarf Lonebrow to warn Falfindel.",["title"]="Heralath Fallowbrook"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1142:description:1-26","1142:description:40-44","1142:description:49-120","1142:description:125-139","1142:description:141-150","1142:description:155-177","1142:description:179-209","1142:description:211-219","1142:description:221-256","1142:description:261-281","1142:description:283-323","1142:description:328-365","1142:description:367-372","1142:objective:1-72"},["minimumStage"]=2,["questID"]=1142,["sourceHash"]="6a873ff2803c25b73e470073cef28578cf79459e70a78a4376b1a4c37f9e53e0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4510",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted his stolen bonding pendant returned to his wife Treshala, together with word of his lonely death.",["title"]="Heralath Fallowbrook"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1142:description:1-26","1142:description:40-44","1142:description:49-120","1142:description:125-139","1142:description:141-150","1142:description:155-177","1142:description:179-209","1142:description:211-219","1142:description:221-256","1142:description:261-281","1142:description:283-323","1142:description:328-365","1142:description:367-372","1142:objective:1-72"},["minimumStage"]=2,["questID"]=1142,["sourceHash"]="6a873ff2803c25b73e470073cef28578cf79459e70a78a4376b1a4c37f9e53e0"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4521",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Treshala was Heralath’s wife in Darnassus; the pendant he sought to return was the token of their bond.",["title"]="Treshala Fallowbrook"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1144:description:1-26","1144:description:31-85","1144:description:87-149","1144:description:154-183","1144:description:185-221","1144:description:223-314","1144:description:316-373","1144:description:375-408","1144:description:413-501","1144:objective:1-49"},["minimumStage"]=2,["questID"]=1144,["sourceHash"]="d717bbfdc99e72acb94806e823468dbc51c4502d99859af219736a3272ac6822"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4508",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Willix entered Razorfen Kraul hoping to profit from Mebok Mizzyrix’s demand for blueleaf tubers, only to become a prisoner.",["title"]="Willix the Importer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1144:description:1-26","1144:description:31-85","1144:description:87-149","1144:description:154-183","1144:description:185-221","1144:description:223-314","1144:description:316-373","1144:description:375-408","1144:description:413-501","1144:objective:1-49"},["minimumStage"]=2,["questID"]=1144,["sourceHash"]="d717bbfdc99e72acb94806e823468dbc51c4502d99859af219736a3272ac6822"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4508",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The captive entrepreneur promised payment to anyone who could escort him back outside.",["title"]="Willix the Importer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1145:description:1-158","1145:description:160-253","1145:description:258-322","1145:description:324-403","1145:description:408-466","1145:objective:1-62"},["minimumStage"]=2,["questID"]=1145,["sourceHash"]="8127e70068280313557e695fcf42fbef2377dd509c43ae797f9d216afd2027ae"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3428",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Reports from travelers gathering insect eggs convinced Korran that the swarm was more dangerous than his masters had assumed.",["title"]="Korran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1146:description:1-113","1146:description:118-190","1146:description:192-287","1146:description:289-393","1146:description:398-490","1146:description:492-511","1146:objective:1-65"},["minimumStage"]=2,["questID"]=1146,["sourceHash"]="228d6482690ac2cdfde5e087791313ddc143d4f1641ad255437002052e943bdf"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4485",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Belgrom learned that insects erupting from a cave had nearly destroyed Moktar’s raiding party at a dwarven excavation in the Shimmering Flats.",["title"]="Belgrom Rockmaul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1146:description:1-113","1146:description:118-190","1146:description:192-287","1146:description:289-393","1146:description:398-490","1146:description:492-511","1146:objective:1-65"},["minimumStage"]=2,["questID"]=1146,["sourceHash"]="228d6482690ac2cdfde5e087791313ddc143d4f1641ad255437002052e943bdf"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4483",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Moktar’s party attacked a dwarven dig but barely survived when insects emerged from its cave; the survivors took refuge at the flats’ edge.",["title"]="Moktar Krin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1137:description:1-43","1137:description:46-88","1137:description:91-144","1137:description:149-247","1137:description:250-285","1137:description:290-353","1137:description:358-374","1137:description:377-501","1137:objective:1-53"},["minimumStage"]=2,["questID"]=1137,["sourceHash"]="f602f9d0d5c56ea9d7730262fe39a492d79db555d87995e590151ecc9c07a9e1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4618",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Martek recognized indurium’s heat resistance as useful for Fizzle’s pistons, explaining that true ore lay deep within Uldaman.",["title"]="Martek the Exiled"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1137:description:1-43","1137:description:46-88","1137:description:91-144","1137:description:149-247","1137:description:250-285","1137:description:290-353","1137:description:358-374","1137:description:377-501","1137:objective:1-53"},["minimumStage"]=2,["questID"]=1137,["sourceHash"]="f602f9d0d5c56ea9d7730262fe39a492d79db555d87995e590151ecc9c07a9e1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4454",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The indurium sought for Fizzle’s pistons needed to be ore from Uldaman rather than the flakes available elsewhere.",["title"]="Fizzle Brassbolts"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1139:description:1-119","1139:description:121-150","1139:description:152-353","1139:description:358-427","1139:description:432-495","1139:objective:1-73"},["minimumStage"]=2,["questID"]=1139,["sourceHash"]="ff64302cb001d608c643e32166b2e458df57c52b155a1138e8953bc2f1ebf575"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2918",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Belgrum wanted the legendary Tablet of Will recovered before the Shadowforge clan claimed it, so Hammertoe’s search would not end in vain.",["title"]="Advisor Belgrum"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1139:description:1-119","1139:description:121-150","1139:description:152-353","1139:description:358-427","1139:description:432-495","1139:objective:1-73"},["minimumStage"]=2,["questID"]=1139,["sourceHash"]="ff64302cb001d608c643e32166b2e458df57c52b155a1138e8953bc2f1ebf575"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2909",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hammertoe had dreamed of finding the Tablet of Will, said to be a titan-inscribed stone that gave their creations wills of their own.",["title"]="Hammertoe Grez"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"963:description:1-143","963:description:148-252","963:description:254-343","963:description:345-389","963:description:394-442","963:description:444-472","963:objective:1-99"},["minimumStage"]=2,["questID"]=963,["sourceHash"]="d328a7552bfcaa92f52e5c174e007eeb46fe2983032d9190dac75216eef75e91"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3644",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cerellean had mourned Anaya since Ameth’Aran’s destruction; thousands of years later, he found her haunted spirit still among the ruins.",["title"]="Cerellean Whiteclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"963:description:1-143","963:description:148-252","963:description:254-343","963:description:345-389","963:description:394-442","963:description:444-472","963:objective:1-99"},["minimumStage"]=2,["questID"]=963,["sourceHash"]="d328a7552bfcaa92f52e5c174e007eeb46fe2983032d9190dac75216eef75e91"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3644",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Anaya released from her haunting but could not bring himself to destroy his beloved’s spirit.",["title"]="Cerellean Whiteclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"963:description:1-143","963:description:148-252","963:description:254-343","963:description:345-389","963:description:394-442","963:description:444-472","963:objective:1-99"},["minimumStage"]=2,["questID"]=963,["sourceHash"]="d328a7552bfcaa92f52e5c174e007eeb46fe2983032d9190dac75216eef75e91"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3667",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anaya was Cerellean Whiteclaw’s lost love, whose spirit lingered in Ameth’Aran long after the city’s fall.",["title"]="Anaya Dawnrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"951:description:1-97","951:description:100-272","951:description:277-391","951:description:394-496","951:objective:1-61"},["minimumStage"]=2,["questID"]=951,["sourceHash"]="3c56ec6118af122803d2f336579a713db1b2422b4baa26f8f0abde0207b46235"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3616",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Onu recognized the Master’s Glaive parchment as cursed elven writing and feared the Twilight’s Hammer was using old magic to return its masters.",["title"]="Onu"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"953:description:1-50","953:description:52-239","953:description:244-363","953:description:365-428","953:description:433-510","953:objective:1-113"},["minimumStage"]=2,["questID"]=953,["sourceHash"]="015dd1c09572e1ac775b637f19aa8d8644c7b48c6db91174c73f8b1b46d573b4"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3639",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tysha found tablets recounting Ameth’Aran’s fall but fled when the spirits attacked as she read them.",["title"]="Sentinel Tysha Moonblade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"958:description:5-30","958:description:35-72","958:description:74-161","958:description:163-283","958:description:288-417","958:description:419-483","958:objective:1-65"},["minimumStage"]=2,["questID"]=958,["sourceHash"]="59074a550ae016bf9815327728aee076cd6e5a60835ea39b57f56de9b7ad256a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3649",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thundris wanted the magical implements carried by Ameth’Aran’s Highborne spirits recovered and destroyed.",["title"]="Thundris Windweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"955:description:1-103","955:description:105-218","955:description:223-259","955:description:261-400","955:description:402-501","955:objective:1-53"},["minimumStage"]=2,["questID"]=955,["sourceHash"]="1a0170ccbb423e2e56c02d1c03167080405737f1d7e03bdab81e2b9f1a7d4cc6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3650",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A magical seal bound Asterion in a spectral prison at Bashal’Aran, making his long existence an enduring torment.",["title"]="Asterion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"957:description:1-106","957:description:108-221","957:description:223-265","957:description:270-296","957:objective:1-110"},["minimumStage"]=2,["questID"]=957,["sourceHash"]="c762bbd20452d4836b2705736e8a17ae2f8a7ceca131b94fbe60628591c954c8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3650",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He believed the blue flame persisting in neighboring Ameth’Aran could destroy the powerful Highborne seal of his imprisonment.",["title"]="Asterion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"959:description:1-5","959:description:10-45","959:description:47-97","959:description:99-109","959:description:111-136","959:description:138-229","959:description:231-272","959:description:277-391","959:description:393-434","959:description:436-463","959:description:468-505","959:objective:1-145"},["minimumStage"]=2,["questID"]=959,["sourceHash"]="931a04bca7387387ba15444b80098009bdfb5f025f8d01a3a15dddd921b70225"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3665",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bigglefuzz overloaded a huge Booty Bay shipment while unloading it, sending crates tumbling across the Ratchet docks.",["title"]="Crane Operator Bigglefuzz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"959:description:1-5","959:description:10-45","959:description:47-97","959:description:99-109","959:description:111-136","959:description:138-229","959:description:231-272","959:description:277-391","959:description:393-434","959:description:436-463","959:description:468-505","959:objective:1-145"},["minimumStage"]=2,["questID"]=959,["sourceHash"]="931a04bca7387387ba15444b80098009bdfb5f025f8d01a3a15dddd921b70225"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3665",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted a stolen bottle of aged port recovered after chasing Mad Magglish as far as the Wailing Caverns.",["title"]="Crane Operator Bigglefuzz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"959:description:1-5","959:description:10-45","959:description:47-97","959:description:99-109","959:description:111-136","959:description:138-229","959:description:231-272","959:description:277-391","959:description:393-434","959:description:436-463","959:description:468-505","959:objective:1-145"},["minimumStage"]=2,["questID"]=959,["sourceHash"]="931a04bca7387387ba15444b80098009bdfb5f025f8d01a3a15dddd921b70225"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3655",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magglish seized a bottle of ninety-nine-year-old port during the dockside accident and fled into the Wailing Caverns.",["title"]="Mad Magglish"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"962:description:1-122","962:description:124-216","962:description:221-283","962:description:285-346","962:description:351-490","962:objective:1-71"},["minimumStage"]=2,["questID"]=962,["sourceHash"]="fc220f1dce4a37ff93cb3dbf4088f2e725ba9d418c358f6b4834400338096b22"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3419",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Royal Apothecary Society sent Zamah to advance its work far from the Undercity.",["title"]="Apothecary Zamah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"962:description:1-122","962:description:124-216","962:description:221-283","962:description:285-346","962:description:351-490","962:objective:1-71"},["minimumStage"]=2,["questID"]=962,["sourceHash"]="fc220f1dce4a37ff93cb3dbf4088f2e725ba9d418c358f6b4834400338096b22"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3419",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zamah believed the rare serpentbloom of the Wailing Caverns had great potential and sought larger quantities for study.",["title"]="Apothecary Zamah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"969:description:1-77","969:description:79-99","969:description:104-115","969:description:117-167","969:description:169-264","969:description:266-313","969:description:318-381","969:objective:1-64"},["minimumStage"]=2,["questID"]=969,["sourceHash"]="14b9d31c0ac3e732e272d74a3d213837e9a8df210af375a4834d633cf7322e0d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10307",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mau’ari fashioned lucky charms from highly reflective frostmaul shards found in the southern canyon or carried by its ice giants.",["title"]="Witch Doctor Mau'ari"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"971:description:1-34","971:description:37-45","971:description:48-61","971:description:64-130","971:description:135-249","971:description:252-301","971:description:304-365","971:description:370-413","971:description:416-449","971:description:452-469","971:description:471-483","971:objective:1-84"},["minimumStage"]=2,["questID"]=971,["sourceHash"]="912350310fbe46d8f6ddfca4a3d2c39015ce73e69bf75e0a91f29fa03d758c71"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2786",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gerrig coveted ancient lore that could open doorways and awaken sleepers; rumors drew his attention to the Lorgalis Manuscript in Blackfathom Deeps.",["title"]="Gerrig Bonegrip"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1140:description:1-73","1140:description:75-210","1140:description:215-388","1140:description:393-509","1140:objective:1-115"},["minimumStage"]=2,["questID"]=1140,["sourceHash"]="7216b52ce07916d9325ef384b3c5d645f40417f6b5f1503a3fb706ee47a75272"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-428",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The satyr-held grounds and blood-soaked temples concealed one of Athrikus’s remaining soul gems.",["title"]="Night Run"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1140:description:1-73","1140:description:75-210","1140:description:215-388","1140:description:393-509","1140:objective:1-115"},["minimumStage"]=2,["questID"]=1140,["sourceHash"]="7216b52ce07916d9325ef384b3c5d645f40417f6b5f1503a3fb706ee47a75272"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16007",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Satyrs held one of the two soul gems that Ilkrud’s writings linked to Athrikus.",["title"]="Satyrnaar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"953:description:1-50","953:description:52-239","953:description:244-363","953:description:365-428","953:description:433-510","953:objective:1-113"},["minimumStage"]=2,["questID"]=953,["sourceHash"]="015dd1c09572e1ac775b637f19aa8d8644c7b48c6db91174c73f8b1b46d573b4"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-15821",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The ruined city had housed Azshara’s servants and their powerful magic; their restless spirits remained among tablets recording its fall.",["title"]="Ameth'Aran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"952:description:1-195","952:description:200-318","952:description:320-357","952:description:359-441","952:objective:1-95"},["minimumStage"]=2,["questID"]=952,["sourceHash"]="374fc977e3938c7992d81f819926d848d6583b9a3233f1392944e180ef92145d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-15816",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Onu, the Ancient of Lore, awaited Fandral Staghelm’s message in the grove south of Auberdine.",["title"]="Grove of the Ancients"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1145:description:1-158","1145:description:160-253","1145:description:258-322","1145:description:324-403","1145:description:408-466","1145:objective:1-62"},["minimumStage"]=2,["questID"]=1145,["sourceHash"]="8127e70068280313557e695fcf42fbef2377dd509c43ae797f9d216afd2027ae"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-390",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Travelers gathering eggs reported insects dangerous enough to change Korran’s assessment of the growing swarm.",["title"]="Field of Giants"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1146:description:1-113","1146:description:118-190","1146:description:192-287","1146:description:289-393","1146:description:398-490","1146:description:492-511","1146:objective:1-65"},["minimumStage"]=2,["questID"]=1146,["sourceHash"]="228d6482690ac2cdfde5e087791313ddc143d4f1641ad255437002052e943bdf"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-439",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Moktar’s raid on a dwarven excavation met insects bursting from a cave, turning an attack on the dig into a struggle to survive.",["title"]="The Shimmering Flats"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2766:description:1-75","2766:description:78-194","2766:description:197-249","2766:description:254-318","2766:description:321-394","2766:description:399-495","2766:objective:1-85"},["minimumStage"]=2,["questID"]=2766,["sourceHash"]="89c941c73df8410e3c95df51097ea2dbcf4f23d6924b71d82e49a52beae45973"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-7807",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="OOX-22/FE was a chicken-like homing robot whose distress beacon took the form of a metal egg.",["title"]="Homing Robot OOX-22/FE"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2766:description:1-75","2766:description:78-194","2766:description:197-249","2766:description:254-318","2766:description:321-394","2766:description:399-495","2766:objective:1-85"},["minimumStage"]=2,["questID"]=2766,["sourceHash"]="89c941c73df8410e3c95df51097ea2dbcf4f23d6924b71d82e49a52beae45973"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-7807",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Oglethorpe’s beacon placed the damaged robot in a cave near Feral Scar Vale.",["title"]="Homing Robot OOX-22/FE"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2766:description:1-75","2766:description:78-194","2766:description:197-249","2766:description:254-318","2766:description:321-394","2766:description:399-495","2766:objective:1-85","2766:completion:1-20","2766:completion:22-39","2766:completion:41-61","2766:completion:63-75","2766:completion:80-154","2766:completion:156-255","2766:completion:260-318","2766:completion:320-362","2766:completion:364-390","2766:completion:392-434"},["minimumStage"]=4,["questID"]=2766,["sourceHash"]="89c941c73df8410e3c95df51097ea2dbcf4f23d6924b71d82e49a52beae45973"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7807",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The beacon could restore its operation, but Oglethorpe warned that the homing robot still needed major repairs and was too heavy to carry.",["title"]="Homing Robot OOX-22/FE"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2781:description:1-28","2781:description:33-176","2781:description:179-197","2781:description:206-234","2781:description:236-245","2781:description:248-277","2781:description:279-288","2781:description:291-319","2781:description:321-329","2781:description:334-432","2781:objective:1-82"},["minimumStage"]=2,["questID"]=2781,["sourceHash"]="6ef6ba832e7fb5e0674993745f2b172f56e9c0fa4c906d9eb82f5adb644e794e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7407",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Chief Engineer Bilgewhizzle administered the Gadgetzan Water Company’s bounty against the Wastewander leader Caliph Scorpidsting.",["title"]="Chief Engineer Bilgewhizzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2781:description:1-28","2781:description:33-176","2781:description:179-197","2781:description:206-234","2781:description:236-245","2781:description:248-277","2781:description:279-288","2781:description:291-319","2781:description:321-329","2781:description:334-432","2781:objective:1-82"},["minimumStage"]=2,["questID"]=2781,["sourceHash"]="6ef6ba832e7fb5e0674993745f2b172f56e9c0fa4c906d9eb82f5adb644e794e"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7407",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The company accused Scorpidsting of killing its employees and seizing its water, resources and property.",["title"]="Chief Engineer Bilgewhizzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2847:description:1-53","2847:description:56-105","2847:description:107-125","2847:description:128-267","2847:description:270-348","2847:description:353-417","2847:description:420-472","2847:description:475-507","2847:objective:1-68"},["minimumStage"]=2,["questID"]=2847,["sourceHash"]="a6c6ca7f0ac109d6cc7947b1bce93bbbb4ef350dce820b9a2528fe7fd3f4e3c7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7852",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pratt McGrubben taught Wild Leather patterns at Feathermoon Stronghold, exchanging instruction for leatherworking materials and finished pieces.",["title"]="Pratt McGrubben"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2847:description:1-53","2847:description:56-105","2847:description:107-125","2847:description:128-267","2847:description:270-348","2847:description:353-417","2847:description:420-472","2847:description:475-507","2847:objective:1-68"},["minimumStage"]=2,["questID"]=2847,["sourceHash"]="a6c6ca7f0ac109d6cc7947b1bce93bbbb4ef350dce820b9a2528fe7fd3f4e3c7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7852",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His Wild Leather craft drew on wildvine’s potent, chaotic properties, imparting unpredictable enchantments to the armor.",["title"]="Pratt McGrubben"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2848:description:1-143","2848:description:146-259","2848:description:264-332","2848:description:335-389","2848:objective:1-85","2848:completion:1-42","2848:completion:44-145","2848:completion:150-239","2848:completion:245-249"},["minimumStage"]=4,["questID"]=2848,["sourceHash"]="30782a543e37ea06f051ff69a1491792f819ed5c299d8f684503832089543a62"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7852",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pratt insisted on quality in both his own craft and the work of those learning from him.",["title"]="Pratt McGrubben"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2973:description:1-13","2973:description:15-106","2973:description:111-251","2973:description:253-281","2973:description:283-349","2973:objective:1-79"},["minimumStage"]=2,["questID"]=2973,["sourceHash"]="ec9e9dc5695b946d625b54d1329b7a7ef648fe65a641d93cf85bba34dc8aada6"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4544",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krueg Skullsplitter’s life-mate, Korrin, delighted in new clothing. He planned a cloak adorned with sprite darter wings for her.",["title"]="Krueg Skullsplitter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2973:description:1-13","2973:description:15-106","2973:description:111-251","2973:description:253-281","2973:description:283-349","2973:objective:1-79"},["minimumStage"]=2,["questID"]=2973,["sourceHash"]="ec9e9dc5695b946d625b54d1329b7a7ef648fe65a641d93cf85bba34dc8aada6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4544",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krueg had traveled to Feralas with companions on a mission for their Orgrimmar masters.",["title"]="Krueg Skullsplitter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2974:description:1-6","2974:description:8-42","2974:description:44-57","2974:description:59-83","2974:description:88-106","2974:description:108-130","2974:description:132-192","2974:description:194-224","2974:description:229-252","2974:description:254-288","2974:description:290-314","2974:description:316-374","2974:description:376-454","2974:objective:1-64"},["minimumStage"]=2,["questID"]=2974,["sourceHash"]="7f5f70a2d1cf63353e13cf9b948ead1569d89167ebb26fa801d52a3b903bc582"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4544",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krueg served Belgrom’s interest in the Grimtotem, demanding their horns as bounty trophies and warning that the clan should not be underestimated.",["title"]="Krueg Skullsplitter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2975:description:1-76","2975:description:78-130","2975:description:132-199","2975:description:204-259","2975:description:261-287","2975:description:289-341","2975:objective:1-108"},["minimumStage"]=2,["questID"]=2975,["sourceHash"]="2bced290408064fdd5bafd9c4d01a3f6e6c3fab7f62840424b39494d04842bc2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7777",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rok Orhan saw the Gordunni’s expanding occupation as a scar upon Feralas and wanted their northern outpost checked before it spread farther.",["title"]="Rok Orhan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2987:description:1-130","2987:description:132-205","2987:description:207-318","2987:description:323-367","2987:description:369-444","2987:description:446-488","2987:objective:1-67"},["minimumStage"]=2,["questID"]=2987,["sourceHash"]="217678eddd5af90225d60a8f32077ae82ebe92b585ab974627766dee74348953"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8021",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Orwin supplied a shovel for unearthing the blue-glowing cobalt deposits that the Gordunni buried around their outpost.",["title"]="Orwin Gizzmick"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2988:description:1-41","2988:description:43-173","2988:description:178-193","2988:description:196-278","2988:objective:1-88"},["minimumStage"]=2,["questID"]=2988,["sourceHash"]="46e7583269dad21a27e70fb96b44a624d45724db799bdead7cf51fe04c6ff83a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5636",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Talonaxe regarded the missing gryphon Sharpbeak as an heir vital to the next generation of Aerie Peak’s flock.",["title"]="Gryphon Master Talonaxe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2989:description:1-45","2989:description:48-86","2989:description:89-188","2989:objective:1-74"},["minimumStage"]=2,["questID"]=2989,["sourceHash"]="24dfe6e75283cb2c46622df004a4ca30dd079fe0fecbcc3cb91b192a6bd255b7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5636",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His search for Sharpbeak moved from Witherbark cages toward the Vilebranch’s sacrificial Altar of Zul.",["title"]="Gryphon Master Talonaxe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2990:description:1-52","2990:description:55-153","2990:description:158-208","2990:description:213-280","2990:description:283-374","2990:description:379-392","2990:description:395-476","2990:objective:1-68"},["minimumStage"]=2,["questID"]=2990,["sourceHash"]="2a4d2fec1daf94e740a7cbddf4b17490a6affe7984c7fea881b9ef94219073cb"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-8022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thadius Grimshade had left Aerie Peak years earlier to pursue darker knowledge, though Talonaxe still regarded the diviner as a Wildhammer at heart.",["title"]="Thadius Grimshade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2990:description:1-52","2990:description:55-153","2990:description:158-208","2990:description:213-280","2990:description:283-374","2990:description:379-392","2990:description:395-476","2990:objective:1-68"},["minimumStage"]=2,["questID"]=2990,["sourceHash"]="2a4d2fec1daf94e740a7cbddf4b17490a6affe7984c7fea881b9ef94219073cb"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-8022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thadius worked in the mage tower of Nethergarde Keep in the Blasted Lands.",["title"]="Thadius Grimshade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2991:description:1-79","2991:description:82-188","2991:description:191-255","2991:description:260-328","2991:objective:1-67"},["minimumStage"]=2,["questID"]=2991,["sourceHash"]="003e44fca7f79927721fd9c831e419d9b0ecadba378cc6bcd4aa91ec98668e12"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered to divine Sharpbeak’s whereabouts in exchange for Nekrum Gutchewer’s medallion, whose powers he wished to study.",["title"]="Thadius Grimshade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2991:description:1-79","2991:description:82-188","2991:description:191-255","2991:description:260-328","2991:objective:1-67","2991:completion:1-28","2991:completion:31-106","2991:completion:109-184","2991:completion:186-209","2991:completion:214-244","2991:completion:247-287"},["minimumStage"]=4,["questID"]=2991,["sourceHash"]="003e44fca7f79927721fd9c831e419d9b0ecadba378cc6bcd4aa91ec98668e12"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thadius repeated a rumor that Nekrum’s medallion prolonged life at an unpleasant cost; he hoped to separate its power from those effects.",["title"]="Thadius Grimshade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2993:description:1-90","2993:description:93-194","2993:description:199-204","2993:description:207-226","2993:description:229-264","2993:objective:1-35"},["minimumStage"]=2,["questID"]=2993,["sourceHash"]="502a7e305d75ca93649883bf0ad863c9c2d2a4a524956f7d09f2dde7cd7678d2"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-8023",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grimshade’s divination placed Sharpbeak in a cage on a cliff at the top of Jintha’Alor, with the key held by Vile Priestess Hexx.",["title"]="Sharpbeak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3380:description:1-45","3380:description:47-134","3380:description:139-266","3380:description:271-373","3380:description:375-510","3380:objective:1-35"},["minimumStage"]=2,["questID"]=3380,["sourceHash"]="9ac73c3e856874fdb39905ab4e37caea941206cc7a2c6797268031438a553c60"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8115",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Uzer’i directed those curious about the Sunken Temple to Marvon, whose studies of ancient sites could explain the isolated, tainted spirits below.",["title"]="Witch Doctor Uzer'i"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3444:description:1-60","3444:description:62-199","3444:description:201-293","3444:description:298-396","3444:description:398-454","3444:description:456-505","3444:objective:1-72"},["minimumStage"]=2,["questID"]=3444,["sourceHash"]="5d915d44f48bd83eb21186f6da197935994398033d305712b6717886156df7d3"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-7771",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marvon had entered the Sunken Temple and barely escaped its ooze-covered chambers. A serpent-marked stone later stirred his cloudy memories.",["title"]="Marvon Rivetseeker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3446:description:1-106","3446:description:108-181","3446:description:183-227","3446:description:229-356","3446:description:358-387","3446:description:392-492","3446:objective:1-66"},["minimumStage"]=2,["questID"]=3446,["sourceHash"]="24f20d8321db2319982e83a4b4a67b157caede0c183dc4323348a37e475ca339"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7771",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recalled six balconies bearing serpent statues and a violent trap triggered by touching one. Beneath them lay an altar he associated with Hakkar.",["title"]="Marvon Rivetseeker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3448:description:1-115","3448:description:117-161","3448:description:163-295","3448:description:300-423","3448:description:428-504","3448:objective:1-28"},["minimumStage"]=2,["questID"]=3448,["sourceHash"]="eaf3acc73f7dfb764333309b3c61244ef2e7fee07d0a80e25510ce2c6c07431e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2916",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Historian Karnik investigated Azshara’s elven past and enlisted Tymor, whose particular interests suited the work.",["title"]="Historian Karnik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3448:description:1-115","3448:description:117-161","3448:description:163-295","3448:description:300-423","3448:description:428-504","3448:objective:1-28","3448:completion:1-28","3448:completion:30-62","3448:completion:64-116","3448:completion:118-204","3448:completion:206-249","3448:completion:251-303","3448:completion:308-410","3448:completion:412-470","3448:completion:472-504"},["minimumStage"]=4,["questID"]=3448,["sourceHash"]="eaf3acc73f7dfb764333309b3c61244ef2e7fee07d0a80e25510ce2c6c07431e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8507",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tymor studied the magical knowledge of the old elven cities, convinced that even long-lived survivors could forget painful events.",["title"]="Tymor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3568:description:1-86","3568:description:88-115","3568:description:117-207","3568:description:212-312","3568:description:314-342","3568:description:344-362","3568:description:367-402","3568:description:404-455","3568:description:457-499","3568:objective:1-127"},["minimumStage"]=2,["questID"]=3568,["sourceHash"]="fe11380a3028d9a5805cdf682b238cebf5601b73f803f8b28c177e550f3dd492"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8390",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cuely sought samples from Azshara’s coastal tide pools after a wounded tauren became sick upon drinking their water.",["title"]="Chemist Cuely"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3569:description:1-20","3569:description:22-48","3569:description:50-61","3569:description:63-109","3569:objective:1-52"},["minimumStage"]=2,["questID"]=3569,["sourceHash"]="610f0ce045e152761e59a69a7adab138d59c121898cc24f5a9787e1d33e49b67"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8390",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He proposed an experimental elixir for Thersa without promising that it would cure her.",["title"]="Chemist Cuely"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3568:description:1-86","3568:description:88-115","3568:description:117-207","3568:description:212-312","3568:description:314-342","3568:description:344-362","3568:description:367-402","3568:description:404-455","3568:description:457-499","3568:objective:1-127"},["minimumStage"]=2,["questID"]=3568,["sourceHash"]="fe11380a3028d9a5805cdf682b238cebf5601b73f803f8b28c177e550f3dd492"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-8393",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thersa reported naga wounds in the Ruins of Eldarath and illness after drinking from a nearby tide pool.",["title"]="Thersa Windsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3569:description:1-20","3569:description:22-48","3569:description:50-61","3569:description:63-109","3569:objective:1-52","3569:completion:1-44","3569:completion:46-61","3569:completion:63-124","3569:completion:126-170","3569:completion:172-243","3569:completion:248-303"},["minimumStage"]=4,["questID"]=3569,["sourceHash"]="610f0ce045e152761e59a69a7adab138d59c121898cc24f5a9787e1d33e49b67"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8393",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Priests and shamans had failed to help her. With little time left, she reluctantly trusted Cuely’s remedy and invoked the Earthmother’s protection.",["title"]="Thersa Windsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3601:description:1-17","3601:description:19-73","3601:description:75-87","3601:description:89-111","3601:description:113-128","3601:description:133-214","3601:description:216-370","3601:description:379-424","3601:description:429-497","3601:description:499-510","3601:objective:1-132"},["minimumStage"]=2,["questID"]=3601,["sourceHash"]="09626e8f372720e89cc1df8a55a837adf3184bcbb8dcbfaadcf59e706fded4f5"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-8420",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kim’jael said blood elves had hired him to scout for treasure, then turned on him and kept his equipment.",["title"]="Kim'jael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3601:description:1-17","3601:description:19-73","3601:description:75-87","3601:description:89-111","3601:description:113-128","3601:description:133-214","3601:description:216-370","3601:description:379-424","3601:description:429-497","3601:description:499-510","3601:objective:1-132"},["minimumStage"]=2,["questID"]=3601,["sourceHash"]="09626e8f372720e89cc1df8a55a837adf3184bcbb8dcbfaadcf59e706fded4f5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8420",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stranded without his belongings, the goblin sought the return of his compass, scope, stuffed chicken and Wizzlegoober.",["title"]="Kim'jael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3761:description:1-80","3761:description:83-229","3761:description:234-354","3761:description:357-450","3761:description:453-502","3761:objective:1-74"},["minimumStage"]=2,["questID"]=3761,["sourceHash"]="81517dfa3ba0fd3ee505567f85734cf6fbe7a936710908a3c1f203e25db45cb3"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9076",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ghede received Un’Goro soil for Hamuul Runetotem’s research on Thunder Bluff’s Elder Rise.",["title"]="Ghede"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3761:description:1-80","3761:description:83-229","3761:description:234-354","3761:description:357-450","3761:description:453-502","3761:objective:1-74","3761:completion:1-97","3761:completion:99-195","3761:completion:200-346","3761:completion:348-407"},["minimumStage"]=4,["questID"]=3761,["sourceHash"]="81517dfa3ba0fd3ee505567f85734cf6fbe7a936710908a3c1f203e25db45cb3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9076",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ghede’s brusque, drill-master manner accompanied the practical work of unloading and piling the collected soil.",["title"]="Ghede"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3781:description:1-107","3781:description:110-167","3781:description:170-269","3781:description:274-364","3781:description:367-422","3781:objective:1-97"},["minimumStage"]=2,["questID"]=3781,["sourceHash"]="dd6e595962d0168d467766c829cb8abae3fc93a38f60423cbd10d9b8d52d7a7b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4217",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mathrengyl supplied Tharlendris seeds for Fandral’s morrowgrain research in the Cenarion Enclave.",["title"]="Mathrengyl Bearwalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3785:description:1-78","3785:description:81-166","3785:description:169-250","3785:description:255-325","3785:description:328-482","3785:objective:1-130","3785:objective:135-193"},["minimumStage"]=2,["questID"]=3785,["sourceHash"]="215097020f19ff0666da281a8039d89da11b17c5f633f292a34ed48572198196"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4217",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His Evergreen Pouch cultivated the seeds with Un’Goro soil; he gathered the resulting morrowgrain on the archdruid’s behalf.",["title"]="Mathrengyl Bearwalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2987:description:1-130","2987:description:132-205","2987:description:207-318","2987:description:323-367","2987:description:369-444","2987:description:446-488","2987:objective:1-67"},["minimumStage"]=2,["questID"]=2987,["sourceHash"]="217678eddd5af90225d60a8f32077ae82ebe92b585ab974627766dee74348953"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1103",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Gordunni buried cobalt around their outpost. Orwin described a blue glow that revealed where to dig.",["title"]="Gordunni Outpost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2973:description:1-13","2973:description:15-106","2973:description:111-251","2973:description:253-281","2973:description:283-349","2973:objective:1-79"},["minimumStage"]=2,["questID"]=2973,["sourceHash"]="ec9e9dc5695b946d625b54d1329b7a7ef648fe65a641d93cf85bba34dc8aada6"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1099",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krueg and his companions carried out an Orgrimmar mission from the camp, while his thoughts also turned to a gift for his life-mate.",["title"]="Camp Mojache"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2766:description:1-75","2766:description:78-194","2766:description:197-249","2766:description:254-318","2766:description:321-394","2766:description:399-495","2766:objective:1-85"},["minimumStage"]=2,["questID"]=2766,["sourceHash"]="89c941c73df8410e3c95df51097ea2dbcf4f23d6924b71d82e49a52beae45973"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1105",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A cave near the vale held one of Oglethorpe Obnoticus’s crashed homing robots.",["title"]="Feral Scar Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2989:description:1-45","2989:description:48-86","2989:description:89-188","2989:objective:1-74","2989:completion:1-23","2989:completion:26-69","2989:completion:74-182","2989:completion:187-268"},["minimumStage"]=4,["questID"]=2989,["sourceHash"]="24dfe6e75283cb2c46622df004a4ca30dd079fe0fecbcc3cb91b192a6bd255b7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-355",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Talonaxe feared the altar because of the Vilebranch’s sacrifices; finding Sharpbeak absent there was a relief as well as a setback.",["title"]="The Altar of Zul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2994:description:1-23","2994:description:28-202","2994:objective:1-110"},["minimumStage"]=2,["questID"]=2994,["sourceHash"]="96b66b79ab09a282cabf7812d518c820bcd85475cf89c9e31415fdf66939fb5f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-354",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Vilebranch held Sharpbeak in a cage above the settlement, guarded through a key carried by their high priestess.",["title"]="Jintha'Alor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2995:description:1-88","2995:description:90-276","2995:description:278-349","2995:description:354-415","2995:description:420-450","2995:description:453-499","2995:description:501-510","2995:objective:1-136"},["minimumStage"]=2,["questID"]=2995,["sourceHash"]="19e5562cdd68fcc7d53ede0c575c05cf8781aed8770f648f9bdd9a54e7b4ac9f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-350",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The lodge coordinated Highvale diplomacy and held records of efforts to share knowledge of the Witherbark with other peoples.",["title"]="Quel'Danil Lodge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3601:description:1-17","3601:description:19-73","3601:description:75-87","3601:description:89-111","3601:description:113-128","3601:description:133-214","3601:description:216-370","3601:description:379-424","3601:description:429-497","3601:description:499-510","3601:objective:1-132"},["minimumStage"]=2,["questID"]=3601,["sourceHash"]="09626e8f372720e89cc1df8a55a837adf3184bcbb8dcbfaadcf59e706fded4f5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1220",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kim’jael said his former blood elf employers kept his belongings at their camp after betraying him.",["title"]="Thalassian Base Camp"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3568:description:1-86","3568:description:88-115","3568:description:117-207","3568:description:212-312","3568:description:314-342","3568:description:344-362","3568:description:367-402","3568:description:404-455","3568:description:457-499","3568:objective:1-127"},["minimumStage"]=2,["questID"]=3568,["sourceHash"]="fe11380a3028d9a5805cdf682b238cebf5601b73f803f8b28c177e550f3dd492"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1221",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thersa’s account connected the ruins’ naga and coastal tide pools with the injuries and illness Cuely investigated.",["title"]="Ruins of Eldarath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8:description:1-10","8:description:12-115","8:description:120-170","8:description:172-218","8:description:220-266","8:description:271-376","8:description:378-439","8:description:441-466","8:description:468-496","8:objective:1-69"},["minimumStage"]=2,["questID"]=8,["sourceHash"]="b7ce0e8a6d27adee4aefa4b40c76d988109fa98c99b8ad99fdfb300d90d8b29d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6784",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Calvin Montague presented himself as a young man wearied by fighting mindless zombies and spiders, offering payment to have a letter carried to Brill.",["title"]="Calvin Montague"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8:description:1-10","8:description:12-115","8:description:120-170","8:description:172-218","8:description:220-266","8:description:271-376","8:description:378-439","8:description:441-466","8:description:468-496","8:objective:1-69"},["minimumStage"]=2,["questID"]=8,["sourceHash"]="b7ce0e8a6d27adee4aefa4b40c76d988109fa98c99b8ad99fdfb300d90d8b29d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6784",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His letter was addressed to Brill’s innkeeper Renee; he recommended her inn as a refuge for plague survivors.",["title"]="Calvin Montague"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9:description:1-40","9:description:43-91","9:description:94-141","9:description:144-158","9:description:161-222","9:description:227-300","9:description:303-342","9:description:345-435","9:objective:1-53"},["minimumStage"]=2,["questID"]=9,["sourceHash"]="c81552d17de719e6e330882a5d97ad8ed44495b5aae5630ce4656c15d416a151"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-233",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Saldean refused to abandon his farm after thieves drove other households from Westfall. Harvest Watchers then occupied his own fields and the neighboring land.",["title"]="Farmer Saldean"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9:description:1-40","9:description:43-91","9:description:94-141","9:description:144-158","9:description:161-222","9:description:227-300","9:description:303-342","9:description:345-435","9:objective:1-53"},["minimumStage"]=2,["questID"]=9,["sourceHash"]="c81552d17de719e6e330882a5d97ad8ed44495b5aae5630ce4656c15d416a151"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-233",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He paid for the destruction of the machines so that the fields could be reclaimed.",["title"]="Farmer Saldean"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"10:description:1-26","10:description:29-119","10:description:122-161","10:description:164-250","10:description:253-322","10:description:327-399","10:description:402-408","10:description:410-450","10:description:453-504","10:objective:1-142"},["minimumStage"]=2,["questID"]=10,["sourceHash"]="6f42d017d4c43e4e6b15e3b5573d895ca3bea867a7fdad1b190cc6cecbefaadd"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7724",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fizzledowser sent his leading assistant, Junior Surveyor Scrimshank, to investigate the Gaping Chasm.",["title"]="Senior Surveyor Fizzledowser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"10:description:1-26","10:description:29-119","10:description:122-161","10:description:164-250","10:description:253-322","10:description:327-399","10:description:402-408","10:description:410-450","10:description:453-504","10:objective:1-142"},["minimumStage"]=2,["questID"]=10,["sourceHash"]="6f42d017d4c43e4e6b15e3b5573d895ca3bea867a7fdad1b190cc6cecbefaadd"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7724",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scrimshank vanished after reporting strange insects. Fizzledowser feared the surveyor was dead and needed at least his equipment recovered.",["title"]="Senior Surveyor Fizzledowser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"11:description:1-116","11:description:119-232","11:description:235-305","11:description:310-366","11:description:369-428","11:objective:1-64"},["minimumStage"]=2,["questID"]=11,["sourceHash"]="60b84da9264d1e823061a3a4b840978224a7fa48131e977ffb64093643918b49"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-963",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Deputy Rainer offered the Stormwind Army’s commendation for painted armbands taken from Elwynn’s Riverpaw gnolls.",["title"]="Deputy Rainer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"11:description:1-116","11:description:119-232","11:description:235-305","11:description:310-366","11:description:369-428","11:objective:1-64"},["minimumStage"]=2,["questID"]=11,["sourceHash"]="60b84da9264d1e823061a3a4b840978224a7fa48131e977ffb64093643918b49"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-963",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gnoll packs south of the guard tower and near Stone Cairn Lake exceeded what his own force could handle.",["title"]="Deputy Rainer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"12:description:1-109","12:description:112-160","12:description:166-250","12:description:253-394","12:description:396-492","12:objective:1-115"},["minimumStage"]=2,["questID"]=12,["sourceHash"]="ca931237fbf24d9fb1703086d37ba10225b4b81652c6587e2a0b33480b1a8ead"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-234",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gryan Stoutmantle defined the People’s Militia’s purpose as defending Westfall and restoring peace to its farms.",["title"]="Gryan Stoutmantle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"12:description:1-109","12:description:112-160","12:description:166-250","12:description:253-394","12:description:396-492","12:objective:1-115"},["minimumStage"]=2,["questID"]=12,["sourceHash"]="ca931237fbf24d9fb1703086d37ba10225b4b81652c6587e2a0b33480b1a8ead"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-234",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scouts brought him reports of Defias trappers and smugglers around Jangolode Mine, Molsen Farm and the Furlbrows’ pumpkin fields.",["title"]="Gryan Stoutmantle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"17:description:1-73","17:description:76-199","17:description:202-278","17:description:283-338","17:description:341-402","17:description:407-495","17:objective:1-60"},["minimumStage"]=2,["questID"]=17,["sourceHash"]="ce89051da206b7c5890b4c0e7710572c17d83f454827cea2a91e60c4055a4f0e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1470",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ghak Healtouch wanted to study Uldaman’s newly discovered magenta fungus caps for their potential in alchemy.",["title"]="Ghak Healtouch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"17:description:1-73","17:description:76-199","17:description:202-278","17:description:283-338","17:description:341-402","17:description:407-495","17:objective:1-60"},["minimumStage"]=2,["questID"]=17,["sourceHash"]="ce89051da206b7c5890b4c0e7710572c17d83f454827cea2a91e60c4055a4f0e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1470",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned that disturbing the fungus clusters could release poisonous spores, and offered his restorative elixirs for the specimens.",["title"]="Ghak Healtouch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"25:description:1-98","25:description:103-244","25:description:246-276","25:description:279-478","25:description:483-506","25:objective:1-121","25:objective:126-201","25:objective:206-264"},["minimumStage"]=2,["questID"]=25,["sourceHash"]="0453200b67133f27b3d7f8bf8743b72dc760172de036b8d4135665da3f8402bf"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mastok faced halted transport between Ashenvale and Stonetalon because water elementals attacked travelers near Talondeep Path.",["title"]="Mastok Wrilehiss"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"25:description:1-98","25:description:103-244","25:description:246-276","25:description:279-478","25:description:483-506","25:objective:1-121","25:objective:126-201","25:objective:206-264"},["minimumStage"]=2,["questID"]=25,["sourceHash"]="0453200b67133f27b3d7f8bf8743b72dc760172de036b8d4135665da3f8402bf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alongside confronting the elementals, he wanted Mystral Lake’s gazebo scouted for its view of the Alliance outpost.",["title"]="Mastok Wrilehiss"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"27:description:1-58","27:description:61-137","27:description:142-338","27:description:341-471","27:description:474-499","27:objective:1-70"},["minimumStage"]=2,["questID"]=27,["sourceHash"]="564248f30f2f8643885b62d8c5a200955aba7b2a95ec4463a04afc58a1ac6bee"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="reviewed-turak-runetotem",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Turak guided developing druids toward their animal aspects and referred aquatic training to Dendrite Starblaze in Moonglade.",["title"]="Turak Runetotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"30:description:1-87","30:description:90-249","30:description:252-335","30:description:340-450","30:description:453-504","30:objective:1-83","30:objective:86-177","30:objective:182-242","30:objective:245-308","30:objective:313-399"},["minimumStage"]=2,["questID"]=30,["sourceHash"]="5d4aad6a491b54fc4456741a9ea27458aef8b7162046efe794a6044592ec567e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11799",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tajarri instructed druids in the trial of the Sea Lion, joining the aspect’s agility and endurance through the two halves of its pendant.",["title"]="Tajarri"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"34:description:1-47","34:description:50-86","34:description:89-167","34:description:172-235","34:description:238-244","34:description:247-283","34:description:286-309","34:description:312-359","34:description:362-488","34:objective:1-57","34:objective:60-87"},["minimumStage"]=2,["questID"]=34,["sourceHash"]="f1bc27b7bb41d85bd59f74a36e66baba7d6973f7d984df99a745439153bcbce8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-342",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Martie Jainrose blamed Bellygrub for trampling her garden and ruining daffodils that could not be replanted until the next season.",["title"]="Martie Jainrose"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"34:description:1-47","34:description:50-86","34:description:89-167","34:description:172-235","34:description:238-244","34:description:247-283","34:description:286-309","34:description:312-359","34:description:362-488","34:objective:1-57","34:objective:60-87"},["minimumStage"]=2,["questID"]=34,["sourceHash"]="f1bc27b7bb41d85bd59f74a36e66baba7d6973f7d984df99a745439153bcbce8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-342",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She offered a reward for the boar’s tusk to end his repeated foraging visits from southwest of Lakeshire.",["title"]="Martie Jainrose"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"63:description:1-115","63:description:117-238","63:description:243-352","63:description:354-433","63:description:438-508","63:objective:1-186"},["minimumStage"]=2,["questID"]=63,["sourceHash"]="617e736899d433c51367fbb4c0d2eb68680a6ab12c3965d6c4ccac39c38f754e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5901",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Islen Waterseer directed a cleansing rite at a plague-tainted shrine on Silverpine’s coast.",["title"]="Islen Waterseer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"63:description:1-115","63:description:117-238","63:description:243-352","63:description:354-433","63:description:438-508","63:objective:1-186"},["minimumStage"]=2,["questID"]=63,["sourceHash"]="617e736899d433c51367fbb4c0d2eb68680a6ab12c3965d6c4ccac39c38f754e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5901",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her rite used a corrupted elemental’s bracers and Brine’s remaining potion at the brazier to summon a pure spirit.",["title"]="Islen Waterseer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"64:description:1-16","64:description:19-70","64:description:73-106","64:description:109-163","64:description:166-265","64:description:268-324","64:description:327-390","64:description:393-441","64:objective:1-122"},["minimumStage"]=2,["questID"]=64,["sourceHash"]="443a3f052e05e1250f33543606479146a228dde4b7323beeee962c7baac0c8c1"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-237",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Furlbrow and Verna fled their farm after she heard intruders in the fields, leaving his pocket watch behind in a wardrobe.",["title"]="Farmer Furlbrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"64:description:1-16","64:description:19-70","64:description:73-106","64:description:109-163","64:description:166-265","64:description:268-324","64:description:327-390","64:description:393-441","64:objective:1-122"},["minimumStage"]=2,["questID"]=64,["sourceHash"]="443a3f052e05e1250f33543606479146a228dde4b7323beeee962c7baac0c8c1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-237",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Verna’s father had given Furlbrow the watch on their wedding day; recovering it meant preserving a family keepsake.",["title"]="Farmer Furlbrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"66:description:1-59","66:description:62-121","66:description:124-186","66:description:191-296","66:description:299-337","66:description:342-431","66:description:434-451","66:objective:1-53"},["minimumStage"]=2,["questID"]=66,["sourceHash"]="ac82b5b671db17cc1441ad56a4d7d28d3ac7fa52c9eeb401abeadda76eba5d99"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-265",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Madame Eva feared for her granddaughter Alyssa after a disturbing vision and a reading of the cards.",["title"]="Madame Eva"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"66:description:1-59","66:description:62-121","66:description:124-186","66:description:191-296","66:description:299-337","66:description:342-431","66:description:434-451","66:objective:1-53"},["minimumStage"]=2,["questID"]=66,["sourceHash"]="ac82b5b671db17cc1441ad56a4d7d28d3ac7fa52c9eeb401abeadda76eba5d99"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-265",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The name Stalvan emerged during her trance. She sent an investigator to the town clerk, seeking an explanation for the danger she sensed.",["title"]="Madame Eva"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"70:description:1-30","70:description:33-47","70:description:52-137","70:description:140-231","70:description:234-296","70:description:301-357","70:description:360-386","70:description:388-470","70:description:473-492","70:objective:1-103"},["minimumStage"]=2,["questID"]=70,["sourceHash"]="ef8baf1292f0f73de5eb8625ad126700b8996c6665cbe3477ce8bf474133fced"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-295",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Farley remembered a frightened messenger fleeing his inn into a midnight storm and abandoning letters in an upstairs chest.",["title"]="Innkeeper Farley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"70:description:1-30","70:description:33-47","70:description:52-137","70:description:140-231","70:description:234-296","70:description:301-357","70:description:360-386","70:description:388-470","70:description:473-492","70:objective:1-103"},["minimumStage"]=2,["questID"]=70,["sourceHash"]="ef8baf1292f0f73de5eb8625ad126700b8996c6665cbe3477ce8bf474133fced"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-295",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Among the unclaimed papers remained a letter from Stalvan intended for Stormwind’s Canal District.",["title"]="Innkeeper Farley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"75:description:1-84","75:description:87-178","75:description:184-341","75:description:344-421","75:description:424-468","75:objective:1-81"},["minimumStage"]=2,["questID"]=75,["sourceHash"]="0f2901b79b670d41b387dad4d7f34c217b0459863823855148e101f093340773"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-294",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marshal Haggard was elderly and nearly blind, struggling to read the papers left in his house.",["title"]="Marshal Haggard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"75:description:1-84","75:description:87-178","75:description:184-341","75:description:344-421","75:description:424-468","75:objective:1-81"},["minimumStage"]=2,["questID"]=75,["sourceHash"]="0f2901b79b670d41b387dad4d7f34c217b0459863823855148e101f093340773"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-294",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="An old bundle in his upstairs chest included a faded journal page he believed might illuminate Stalvan’s past.",["title"]="Marshal Haggard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"77:description:1-74","77:description:77-149","77:description:151-201","77:description:204-280","77:description:285-433","77:description:436-502","77:objective:1-117"},["minimumStage"]=2,["questID"]=77,["sourceHash"]="06fc4a010c8f0e88e0b453f2698325918ef980cd9fa6f5130953d919a51ca34b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7801",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gilveradin would package ripple for Malton’s father, charging two extra bottles for his assistance.",["title"]="Gilveradin Sunchaser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"77:description:1-74","77:description:77-149","77:description:151-201","77:description:204-280","77:description:285-433","77:description:436-502","77:objective:1-117"},["minimumStage"]=2,["questID"]=77,["sourceHash"]="06fc4a010c8f0e88e0b453f2698325918ef980cd9fa6f5130953d919a51ca34b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7801",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the search toward crates in an abandoned Horde base near Skulk Rock, warning of slimes and a rumored master ooze.",["title"]="Gilveradin Sunchaser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"89:description:1-101","89:description:104-256","89:description:261-325","89:description:328-414","89:description:420-441","89:objective:1-67"},["minimumStage"]=2,["questID"]=89,["sourceHash"]="396469655bdb9f02d6e100782f1802d25dfbc6bd2ee30b3ebeefc9111ff97e75"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-341",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Redridge’s defenders had smelted their iron into weapons during the orc invasion; gnolls then hijacked Stormwind’s replacement shipment.",["title"]="Foreman Oslow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"89:description:1-101","89:description:104-256","89:description:261-325","89:description:328-414","89:description:420-441","89:objective:1-67"},["minimumStage"]=2,["questID"]=89,["sourceHash"]="396469655bdb9f02d6e100782f1802d25dfbc6bd2ee30b3ebeefc9111ff97e75"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-341",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Oslow needed iron pikes and rivets recovered so his crew could rebuild the Everstill bridge.",["title"]="Foreman Oslow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91:description:1-82","91:description:84-176","91:description:178-233","91:description:238-309","91:description:311-401","91:description:406-438","91:description:443-506","91:objective:1-76"},["minimumStage"]=2,["questID"]=91,["sourceHash"]="b9c8b5d1cd532609e36471f3f4cd0ab8153c15a01060bf9c8e3e0416adf41e60"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-900",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bailiff Conacher enforced Lakeshire’s law against those assisting criminals of the kingdom.",["title"]="Bailiff Conacher"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91:description:1-82","91:description:84-176","91:description:178-233","91:description:238-309","91:description:311-401","91:description:406-438","91:description:443-506","91:objective:1-76"},["minimumStage"]=2,["questID"]=91,["sourceHash"]="b9c8b5d1cd532609e36471f3f4cd0ab8153c15a01060bf9c8e3e0416adf41e60"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-900",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He accused Morganth of spreading misery through arcane power and commanding the Shadowhide gnolls.",["title"]="Bailiff Conacher"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"105:description:1-85","105:description:90-173","105:description:176-328","105:description:331-410","105:description:415-482","105:objective:1-94"},["minimumStage"]=2,["questID"]=105,["sourceHash"]="93bd2bff3b235b4a3e8356fc862ce7e7c5d80a4d0720185307b403dfd5802984"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10837",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Derrington sought an allied assault on Araj’s stronghold in ruined Andorhal, requiring a shard of the lich’s phylactery as proof.",["title"]="High Executor Derrington"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"113:description:1-66","113:description:69-79","113:description:81-127","113:description:130-262","113:description:265-363","113:description:368-464","113:description:466-502","113:objective:1-64","113:objective:67-147"},["minimumStage"]=2,["questID"]=113,["sourceHash"]="e3adcaf88fe30077acbfa587616aa04cc718d2096df92e61be066efc6db6571c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5594",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pestlezugg’s analysis convinced him that the insect infestation threatened far beyond Tanaris if it remained unchecked.",["title"]="Alchemist Pestlezugg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"113:description:1-66","113:description:69-79","113:description:81-127","113:description:130-262","113:description:265-363","113:description:368-464","113:description:466-502","113:objective:1-64","113:objective:67-147"},["minimumStage"]=2,["questID"]=113,["sourceHash"]="e3adcaf88fe30077acbfa587616aa04cc718d2096df92e61be066efc6db6571c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5594",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Fizzledowser’s report copied and distributed so that both local authorities and distant allies understood the danger.",["title"]="Alchemist Pestlezugg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"116:description:1-40","116:description:43-79","116:description:82-123","116:description:126-156","116:description:161-194","116:description:199-406","116:description:409-469","116:objective:1-127"},["minimumStage"]=2,["questID"]=116,["sourceHash"]="7f224694e08edaddb99a794c0e5a1893e21f5583e2228fc5ca9cfe4d1796530a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-346",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Daniels’s overdue drink shipment left Lakeshire’s supply nearly exhausted amid the orc invasion.",["title"]="Barkeep Daniels"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"116:description:1-40","116:description:43-79","116:description:82-123","116:description:126-156","116:description:161-194","116:description:199-406","116:description:409-469","116:objective:1-127"},["minimumStage"]=2,["questID"]=116,["sourceHash"]="7f224694e08edaddb99a794c0e5a1893e21f5583e2228fc5ca9cfe4d1796530a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-346",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought lager from Westfall, wine from Stormwind, moonshine from Darkshire and rum from Goldshire to replenish the bar.",["title"]="Barkeep Daniels"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"128:description:1-37","128:description:39-70","128:description:72-143","128:description:145-233","128:description:235-330","128:description:335-382","128:description:384-428","128:objective:1-72"},["minimumStage"]=2,["questID"]=128,["sourceHash"]="876664840eddccec16f684f4aae84426522fea6c57aa7e2b51c4dcf97297d5f8"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-903",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Guard Howe carried Magistrate Solomon’s charge against the Blackrock champions camped on the road toward the Burning Steppes.",["title"]="Guard Howe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"128:description:1-37","128:description:39-70","128:description:72-143","128:description:145-233","128:description:235-330","128:description:335-382","128:description:384-428","128:objective:1-72"},["minimumStage"]=2,["questID"]=128,["sourceHash"]="876664840eddccec16f684f4aae84426522fea6c57aa7e2b51c4dcf97297d5f8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-903",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His reports identified champions as leaders of individual units in the invading clan.",["title"]="Guard Howe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"133:description:1-106","133:description:109-193","133:description:198-257","133:description:260-293","133:description:296-392","133:description:397-453","133:objective:1-63"},["minimumStage"]=2,["questID"]=133,["sourceHash"]="2747f099c75fd0607c17cb34aacda2d6d1e00a24aeee9f3ed270c6def3cb4cdc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-289",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Abercrombie claimed that ghouls had attacked his isolated house and requested ribs to build an effigy against them. That explanation was his stated purpose.",["title"]="Abercrombie"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"143:description:1-47","143:description:50-92","143:description:95-134","143:description:137-242","143:description:245-302","143:description:307-356","143:description:359-441","143:objective:1-87"},["minimumStage"]=2,["questID"]=143,["sourceHash"]="d4884feac081e6479bfecf8f23f64ba946d6c037059643596a702bd5d28a5e92"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-344",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With Stormwind’s reinforcements absent, Solomon appealed to Stoutmantle’s People’s Militia rather than leave Lakeshire without help.",["title"]="Magistrate Solomon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"167:description:1-76","167:description:78-131","167:description:133-172","167:description:174-200","167:description:202-208","167:description:210-244","167:description:249-298","167:description:300-349","167:description:352-397","167:description:399-474","167:objective:1-91"},["minimumStage"]=2,["questID"]=167,["sourceHash"]="03aa326f35343f7ba1b58855193f07d52afa0c03160f3e3007012c5f17ba3e6e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-656",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wilder escaped a tunnel collapse in a mine beneath Moonbrook, while his brother and the other miners remained missing.",["title"]="Wilder Thistlenettle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"167:description:1-76","167:description:78-131","167:description:133-172","167:description:174-200","167:description:202-208","167:description:210-244","167:description:249-298","167:description:300-349","167:description:352-397","167:description:399-474","167:objective:1-91"},["minimumStage"]=2,["questID"]=167,["sourceHash"]="03aa326f35343f7ba1b58855193f07d52afa0c03160f3e3007012c5f17ba3e6e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-656",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="If his brother could not be found alive, Wilder wanted his Explorers’ League badge returned for peace of mind.",["title"]="Wilder Thistlenettle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"170:description:1-41","170:description:43-108","170:description:113-220","170:description:222-303","170:description:308-397","170:description:403-502","170:objective:1-80"},["minimumStage"]=2,["questID"]=170,["sourceHash"]="a9c0ae56614d06605cb50d1225a45880a8ac52070f11a0c6bedb98c0707c5d62"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-713",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Balir’s force was shorthanded after trogg attacks across Coldridge Valley, including the loss of a camp to the west.",["title"]="Balir Frosthammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"170:description:1-41","170:description:43-108","170:description:113-220","170:description:222-303","170:description:308-397","170:description:403-502","170:objective:1-80"},["minimumStage"]=2,["questID"]=170,["sourceHash"]="a9c0ae56614d06605cb50d1225a45880a8ac52070f11a0c6bedb98c0707c5d62"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-713",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought help driving the invaders from the southeastern hills and frozen lake.",["title"]="Balir Frosthammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"171:description:1-37","171:description:40-104","171:description:107-116","171:description:119-241","171:description:244-288","171:description:290-303","171:description:308-360","171:description:363-432","171:objective:1-138"},["minimumStage"]=2,["questID"]=171,["sourceHash"]="c4eb706df456fa35dffa1fadca59ccf7386dc4e49f9fc65b10e19b1c2aa60518"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14305",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The orphan hoped to rise above the loss of his parents and grow into a hero, remembering their advice to face hardship with courage.",["title"]="Human Orphan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"172:description:1-48","172:description:51-120","172:description:125-142","172:description:145-254","172:description:257-341","172:description:344-381","172:description:386-438","172:description:441-490","172:objective:1-102"},["minimumStage"]=2,["questID"]=172,["sourceHash"]="4728bd0e35798c4c10c6a1e0c91a3afb5d20e54226d51cb26a19454b92fa1634"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14451",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Matron Battlewail arranged temporary wards during Children’s Week, entrusting volunteers with a whistle to call the child in their care.",["title"]="Orphan Matron Battlewail"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"179:description:1-21","179:description:23-94","179:description:99-157","179:description:159-253","179:description:255-282","179:description:287-325","179:description:327-347","179:description:349-435","179:description:437-458","179:objective:1-53"},["minimumStage"]=2,["questID"]=179,["sourceHash"]="8a023be338d4b6c5fc0d6688b08aa4689f8c8ce1e5b645ef77759421e328eb96"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-658",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sten Stoutarm offered warm gloves in exchange for wolf meat, attending to new arrivals’ need for protection from Coldridge’s chill.",["title"]="Sten Stoutarm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"189:description:1-12","189:description:14-63","189:description:65-138","189:description:140-163","189:description:165-206","189:description:211-228","189:description:230-244","189:description:246-314","189:description:316-327","189:description:329-334","189:description:347-372","189:description:374-397","189:description:402-419","189:description:421-501","189:objective:1-65"},["minimumStage"]=2,["questID"]=189,["sourceHash"]="a6aa939eb2bb1e6ce8cd3cdd3e796d5628a6ae008f605131e1b80f128f67fc52"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bloodscalp attacks had cost Kebok guards and agents in the jungle, leaving him anxious about the losses he would report to Revilgaz.",["title"]="Kebok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"189:description:1-12","189:description:14-63","189:description:65-138","189:description:140-163","189:description:165-206","189:description:211-228","189:description:230-244","189:description:246-314","189:description:316-327","189:description:329-334","189:description:347-372","189:description:374-397","189:description:402-419","189:description:421-501","189:objective:1-65"},["minimumStage"]=2,["questID"]=189,["sourceHash"]="a6aa939eb2bb1e6ce8cd3cdd3e796d5628a6ae008f605131e1b80f128f67fc52"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He posted payment for Bloodscalp ears, treating retaliation as a way to contain the mounting expense.",["title"]="Kebok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"198:description:1-4","198:description:6-53","198:description:55-141","198:description:146-232","198:description:234-320","198:description:322-421","198:description:423-446","198:description:451-499","198:objective:1-61"},["minimumStage"]=2,["questID"]=198,["sourceHash"]="4c1933ab7418d5bf6443a5556962872f0be29f4a8f844203fb10e182c9d82e2e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-773",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krazek supplied Lieutenant Doren’s followers in northern Stranglethorn and sought a courier when troll attacks interrupted delivery.",["title"]="Krazek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"198:description:1-4","198:description:6-53","198:description:55-141","198:description:146-232","198:description:234-320","198:description:322-421","198:description:423-446","198:description:451-499","198:objective:1-61"},["minimumStage"]=2,["questID"]=198,["sourceHash"]="4c1933ab7418d5bf6443a5556962872f0be29f4a8f844203fb10e182c9d82e2e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-773",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He named Private Thorsen as the recipient and insisted that a failed delivery would require restitution.",["title"]="Krazek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"200:description:1-66","200:description:69-112","200:description:117-172","200:description:175-270","200:description:273-362","200:description:367-470","200:description:473-509","200:objective:1-28"},["minimumStage"]=2,["questID"]=200,["sourceHash"]="9d6ace0a44c51e98d5efaf6a4f130d433ee953ed8c61f08c1694d972b98f826e"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-469",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Doren feared a spy had exposed Thorsen’s contact inside Kurzen’s camp. Herod’s logistics records might reveal how the secret escaped.",["title"]="Lieutenant Doren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"200:description:1-66","200:description:69-112","200:description:117-172","200:description:175-270","200:description:273-362","200:description:367-470","200:description:473-509","200:objective:1-28"},["minimumStage"]=2,["questID"]=200,["sourceHash"]="9d6ace0a44c51e98d5efaf6a4f130d433ee953ed8c61f08c1694d972b98f826e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-469",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Doren had once served with Kurzen and remembered Herod’s office in the compound’s two-story house.",["title"]="Lieutenant Doren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"204:description:1-73","204:description:76-212","204:description:217-264","204:description:267-427","204:objective:1-85"},["minimumStage"]=2,["questID"]=204,["sourceHash"]="995fbf6431ad0293d2f46dea55c552e947dfe26edec0fc6b3f3df28fd7c32aa6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-733",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yohwa wanted Kurzen’s healing support disrupted by seizing the medicine men’s Jungle Remedies and the fighters’ Venom Fern Extracts.",["title"]="Sergeant Yohwa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"206:description:1-67","206:description:70-208","206:description:211-301","206:description:306-418","206:description:423-500","206:objective:1-57"},["minimumStage"]=2,["questID"]=206,["sourceHash"]="91481e176e5c99c064c9d82f78615f344f21d19438e86206d85538a3dcb1dc77"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-739",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nimetz attributed Kurzen’s corruption to Mai’Zoth’s rumored mind-controlling powers; the conclusion belonged to his studies and suspicions.",["title"]="Brother Nimetz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"206:description:1-67","206:description:70-208","206:description:211-301","206:description:306-418","206:description:423-500","206:objective:1-57"},["minimumStage"]=2,["questID"]=206,["sourceHash"]="91481e176e5c99c064c9d82f78615f344f21d19438e86206d85538a3dcb1dc77"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-739",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought the ogre mage’s Mind’s Eye to prevent another leader from falling under the same influence.",["title"]="Brother Nimetz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"211:description:1-85","211:description:90-173","211:description:176-328","211:description:331-410","211:description:415-482","211:objective:1-99"},["minimumStage"]=2,["questID"]=211,["sourceHash"]="3b308f2f09727008a9faf4b355685bc2ac3d12d30285480cf91de755f1d00af1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10838",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ashlam called for an assault on Araj and his Scourge guardians in Andorhal, with a phylactery shard brought back as evidence.",["title"]="Commander Ashlam Valorfist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"212:description:1-69","212:description:72-92","212:description:94-188","212:description:193-326","212:description:331-453","212:description:456-468","212:objective:1-106"},["minimumStage"]=2,["questID"]=212,["sourceHash"]="8bf9c49c5fdc78fe186ceff6fa000d8efbc497c6293ff4dc8254420c96c7805f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1141",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Angus Stern prepared food for nobles, including a birthday feast featuring his chilled basilisk with lime vinaigrette.",["title"]="Angus Stern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"212:description:1-69","212:description:72-92","212:description:94-188","212:description:193-326","212:description:331-453","212:description:456-468","212:objective:1-106"},["minimumStage"]=2,["questID"]=212,["sourceHash"]="8bf9c49c5fdc78fe186ceff6fa000d8efbc497c6293ff4dc8254420c96c7805f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1141",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The dish required fresh meat that would not keep, making a swiftly delivered Cold Eye Basilisk haunch essential.",["title"]="Angus Stern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"214:description:1-75","214:description:78-176","214:description:181-268","214:description:271-353","214:description:356-449","214:description:452-465","214:objective:1-83"},["minimumStage"]=2,["questID"]=214,["sourceHash"]="70f43bf5b54b5c758782b86376fa7796b63868904cd0318dd81405429ba369ca"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-820",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Riell explained that the material of a Defias bandana marked rank, with silk identifying senior members in VanCleef’s hideout.",["title"]="Scout Riell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"214:description:1-75","214:description:78-176","214:description:181-268","214:description:271-353","214:description:356-449","214:description:452-465","214:objective:1-83"},["minimumStage"]=2,["questID"]=214,["sourceHash"]="70f43bf5b54b5c758782b86376fa7796b63868904cd0318dd81405429ba369ca"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-820",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She offered payment for silk bandanas as evidence of an attack on the Brotherhood’s leadership.",["title"]="Scout Riell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"215:description:1-28","215:description:31-79","215:description:84-228","215:description:231-313","215:description:316-360","215:description:365-419","215:description:422-465","215:objective:1-46"},["minimumStage"]=2,["questID"]=215,["sourceHash"]="fbe14e337078fcb1e0c4ca59494548a785d84812ba8b79f9f42a3dfad039058c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-738",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thorsen served Doren’s rebels as a covert agent, ordered to re-enlist among Kurzen’s men and bring back intelligence.",["title"]="Private Thorsen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"215:description:1-28","215:description:31-79","215:description:84-228","215:description:231-313","215:description:316-360","215:description:365-419","215:description:422-465","215:objective:1-46"},["minimumStage"]=2,["questID"]=215,["sourceHash"]="fbe14e337078fcb1e0c4ca59494548a785d84812ba8b79f9f42a3dfad039058c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-738",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His attempt to infiltrate Kurzen’s compound went wrong, leaving his mission exposed and his safety dependent on rescue.",["title"]="Private Thorsen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"216:description:1-248","216:objective:1-115"},["minimumStage"]=2,["questID"]=216,["sourceHash"]="9502ed671cfcbc1428d4ff7a49b576da55375e2ad1dafa7325e536135a88fdef"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12757",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/216",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Karang wanted a route from the Zoram coast toward Splintertree that would bypass Astranaar and deny the Alliance an advantage.",["title"]="Karang Amakkar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"216:description:1-248","216:objective:1-115"},["minimumStage"]=2,["questID"]=216,["sourceHash"]="9502ed671cfcbc1428d4ff7a49b576da55375e2ad1dafa7325e536135a88fdef"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12757",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/216",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He regarded Thistlefur Village as the obstacle to that route and called for force against its furbolgs.",["title"]="Karang Amakkar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"224:description:1-32","224:description:35-156","224:description:159-201","224:description:204-263","224:description:266-308","224:description:313-394","224:description:397-469","224:objective:1-122"},["minimumStage"]=2,["questID"]=224,["sourceHash"]="25af1add7edc17ab4fcda47789626d341226e29fae63bff6b4290e17e6f02d74"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1089",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With many soldiers fighting abroad, Cobbleflint’s defenders struggled against Stonesplinter troggs tunneling into Loch Modan.",["title"]="Mountaineer Cobbleflint"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"224:description:1-32","224:description:35-156","224:description:159-201","224:description:204-263","224:description:266-308","224:description:313-394","224:description:397-469","224:objective:1-122"},["minimumStage"]=2,["questID"]=224,["sourceHash"]="25af1add7edc17ab4fcda47789626d341226e29fae63bff6b4290e17e6f02d74"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1089",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He appealed for help securing the Loch against what he considered a major threat to Ironforge.",["title"]="Mountaineer Cobbleflint"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"226:description:1-90","226:description:93-155","226:description:158-292","226:description:295-352","226:description:357-434","226:description:437-493","226:objective:1-123"},["minimumStage"]=2,["questID"]=226,["sourceHash"]="fc5cb76f42f9f1c41c464019fbb737d4cbdebd993fc928c43e96a71c777ebc87"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-893",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lars shared an isolated camp with Sven, hunting for food while they faced the necromancer to the east.",["title"]="Lars"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"226:description:1-90","226:description:93-155","226:description:158-292","226:description:295-352","226:description:357-434","226:description:437-493","226:objective:1-123"},["minimumStage"]=2,["questID"]=226,["sourceHash"]="fc5cb76f42f9f1c41c464019fbb737d4cbdebd993fc928c43e96a71c777ebc87"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-893",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Starving and rabid dire wolves repeatedly followed his meat back toward camp from the northern and eastern woods.",["title"]="Lars"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"235:description:1-29","235:description:32-64","235:description:69-146","235:description:149-251","235:description:254-317","235:description:320-469","235:objective:1-63"},["minimumStage"]=2,["questID"]=235,["sourceHash"]="8f201d121f121023b1c307bafc1a5ad6f985e1deb373bc30727d3cd21cff9e6e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10880",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Warcaller Gorlach recruited adventurers for the Horde’s Ashenvale outposts and Senani Thunderheart’s great hunt.",["title"]="Warcaller Gorlach"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"245:description:1-9","245:description:11-84","245:description:86-213","245:description:218-295","245:description:297-403","245:description:408-477","245:objective:1-83"},["minimumStage"]=2,["questID"]=245,["sourceHash"]="90d92964d374715321676b0f89233828b740f780a5358338369b09db63d06dd7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-888",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dodds lacked the manpower to control venomous spiders on Duskwood’s western border, far from Darkshire’s protection.",["title"]="Watcher Dodds"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"253:description:1-61","253:description:64-133","253:description:136-229","253:description:234-343","253:description:348-370","253:description:373-455","253:description:458-494","253:objective:1-19","253:objective:22-91"},["minimumStage"]=2,["questID"]=253,["sourceHash"]="599d2ea4ad5c2233466974e63f3164881afb0a39dbd98186f0e3640724169f1c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-263",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ebonlocke knew the Embalmer through a children’s tale: an alchemist’s attempt to revive Eliza with his own heart had cursed her with hunger for human flesh.",["title"]="Lord Ello Ebonlocke"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"253:description:1-61","253:description:64-133","253:description:136-229","253:description:234-343","253:description:348-370","253:description:373-455","253:description:458-494","253:objective:1-19","253:objective:22-91"},["minimumStage"]=2,["questID"]=253,["sourceHash"]="599d2ea4ad5c2233466974e63f3164881afb0a39dbd98186f0e3640724169f1c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-263",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He proposed recovering the beating heart from Eliza’s grave to break the Embalmer’s power; the explanation came from that local story.",["title"]="Lord Ello Ebonlocke"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"255:description:1-144","255:description:146-258","255:description:263-292","255:description:294-314","255:description:319-332","255:description:334-360","255:description:362-423","255:description:425-485","255:objective:1-117"},["minimumStage"]=2,["questID"]=255,["sourceHash"]="c28d3a52ee25e4f020b61af2b064cc6c99b550dc7aa7f295efbc485e1266c3e1"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1139",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bluntnose faced months of delay before Ironforge’s reinforcements could protect the town, excavation and dam.",["title"]="Magistrate Bluntnose"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"255:description:1-144","255:description:146-258","255:description:263-292","255:description:294-314","255:description:319-332","255:description:334-360","255:description:362-423","255:description:425-485","255:objective:1-117"},["minimumStage"]=2,["questID"]=255,["sourceHash"]="c28d3a52ee25e4f020b61af2b064cc6c99b550dc7aa7f295efbc485e1266c3e1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1139",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He turned to hired adventurers to remove an ogre camp northeast of the lake while the soldiers were still absent.",["title"]="Magistrate Bluntnose"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"257:description:1-50","257:description:52-70","257:description:72-114","257:description:116-229","257:description:234-283","257:description:285-334","257:description:336-423","257:description:428-460","257:description:465-507","257:objective:1-101"},["minimumStage"]=2,["questID"]=257,["sourceHash"]="5e000e97fe9a1b4e066cd82def054250754d5b19cb11f555c7dc501dbb383735"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1187",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Daryl challenged other hunters with a boastful, dismissive manner, wagering his bow or gun on a timed buzzard hunt.",["title"]="Daryl the Youngling"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"271:description:1-73","271:description:75-121","271:description:126-241","271:description:243-290","271:description:292-357","271:description:362-429","271:description:434-511","271:objective:1-87"},["minimumStage"]=2,["questID"]=271,["sourceHash"]="c58369da9e18e0e5a6d4640c941bea5b9929ceec41cf162274f46ae3d173f21c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1187",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vyrin recalled that Daryl’s attempt to hunt Ol’ Sooty left him with a scar over one eye.",["title"]="Daryl the Youngling"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"261:description:1-16","261:description:19-49","261:description:52-111","261:description:114-188","261:description:191-267","261:description:272-420","261:description:425-466","261:objective:1-74"},["minimumStage"]=2,["questID"]=261,["sourceHash"]="e0058dfb5aa4fd0c187207456db9da75b302d07ba330dcfc5fd9b25962eed42b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1182",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brother Anton sought recruits for the Scarlet Crusade’s war against the Scourge.",["title"]="Brother Anton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"261:description:1-16","261:description:19-49","261:description:52-111","261:description:114-188","261:description:191-267","261:description:272-420","261:description:425-466","261:objective:1-74"},["minimumStage"]=2,["questID"]=261,["sourceHash"]="e0058dfb5aa4fd0c187207456db9da75b302d07ba330dcfc5fd9b25962eed42b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1182",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He demanded proof against the undead ravagers in Desolace’s Valley of Bones before offering the Crusade’s welcome.",["title"]="Brother Anton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"264:description:1-12","264:description:14-44","264:description:46-137","264:description:142-172","264:description:174-188","264:description:190-241","264:description:243-276","264:description:281-324","264:description:326-388","264:description:393-456","264:description:458-496","264:description:498-504","264:objective:1-54"},["minimumStage"]=2,["questID"]=264,["sourceHash"]="9ac151a0dafbb95c4477306e7f6a4fe44abda88ac7d3d08038e4d91b83d0562f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5543",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Clarice’s husband left his family for a holy crusade and died; she survived bearing the undeath he had opposed.",["title"]="Clarice Foster"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"264:description:1-12","264:description:14-44","264:description:46-137","264:description:142-172","264:description:174-188","264:description:190-241","264:description:243-276","264:description:281-324","264:description:326-388","264:description:393-456","264:description:458-496","264:description:498-504","264:objective:1-54"},["minimumStage"]=2,["questID"]=264,["sourceHash"]="9ac151a0dafbb95c4477306e7f6a4fe44abda88ac7d3d08038e4d91b83d0562f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5543",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bitter at the duty that had taken him away, she wanted his keepsake left on his Sepulcher tomb and out of her life.",["title"]="Clarice Foster"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"270:description:1-141","270:description:144-189","270:description:194-272","270:description:275-339","270:description:344-418","270:description:421-478","270:objective:1-71"},["minimumStage"]=2,["questID"]=270,["sourceHash"]="13fe7c5b0da40654d202886d1dbef1799e8ce62369d65025dd9d22b1730bb23d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1212",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Farthing valued Lightforge Iron for weapons capable of striking with holy power, seeing it as a means to confront Morbent Fel.",["title"]="Bishop Farthing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"270:description:1-141","270:description:144-189","270:description:194-272","270:description:275-339","270:description:344-418","270:description:421-478","270:objective:1-71"},["minimumStage"]=2,["questID"]=270,["sourceHash"]="13fe7c5b0da40654d202886d1dbef1799e8ce62369d65025dd9d22b1730bb23d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1212",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the search for the lost Third Fleet cargo to his dwarven colleague Glorin Steelbrow in Menethil Harbor.",["title"]="Bishop Farthing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"271:description:1-73","271:description:75-121","271:description:126-241","271:description:243-290","271:description:292-357","271:description:362-429","271:description:434-511","271:objective:1-87"},["minimumStage"]=2,["questID"]=271,["sourceHash"]="c58369da9e18e0e5a6d4640c941bea5b9929ceec41cf162274f46ae3d173f21c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1156",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vyrin wanted Ol’ Sooty defeated partly to silence Daryl’s boasting, despite acknowledging his skill.",["title"]="Vyrin Swiftwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"271:description:1-73","271:description:75-121","271:description:126-241","271:description:243-290","271:description:292-357","271:description:362-429","271:description:434-511","271:objective:1-87"},["minimumStage"]=2,["questID"]=271,["sourceHash"]="c58369da9e18e0e5a6d4640c941bea5b9929ceec41cf162274f46ae3d173f21c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1156",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She remembered the Farstrider Lodge’s unsuccessful hunt for the bear a year earlier and placed his lair above Thelsamar.",["title"]="Vyrin Swiftwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"279:description:1-91","279:description:94-158","279:description:163-331","279:description:334-395","279:description:400-444","279:description:447-492","279:objective:1-25","279:objective:30-60","279:objective:65-118"},["minimumStage"]=2,["questID"]=279,["sourceHash"]="37ce3b4ced8a78466e3bdf0b724f638f3f6e7ee7e0c5be280f371c7a0dba7018"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1242",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Karl Boran sought to protect fishers and merchants from coastal murlocs, particularly Gobbler’s attacks along the road.",["title"]="Karl Boran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"279:description:1-91","279:description:94-158","279:description:163-331","279:description:334-395","279:description:400-444","279:description:447-492","279:objective:1-25","279:objective:30-60","279:objective:65-118"},["minimumStage"]=2,["questID"]=279,["sourceHash"]="37ce3b4ced8a78466e3bdf0b724f638f3f6e7ee7e0c5be280f371c7a0dba7018"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1242",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered payment for securing the trade route and demanded the raider’s head as proof.",["title"]="Karl Boran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"288:description:1-90","288:description:93-109","288:description:112-181","288:description:184-210","288:description:215-319","288:description:322-367","288:description:372-405","288:description:408-492","288:objective:1-44"},["minimumStage"]=2,["questID"]=288,["sourceHash"]="896815493d230e088a634aab4679d887b048e1036ce2ee5761d1993970a8628b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1239",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fitzsimmons had been first mate of the Wave Mistress in Kul Tiras’s Third Fleet. He described orc-controlled red dragons burning and sinking the ships off the Wetlands.",["title"]="First Mate Fitzsimmons"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"288:description:1-90","288:description:93-109","288:description:112-181","288:description:184-210","288:description:215-319","288:description:322-367","288:description:372-405","288:description:408-492","288:objective:1-44"},["minimumStage"]=2,["questID"]=288,["sourceHash"]="896815493d230e088a634aab4679d887b048e1036ce2ee5761d1993970a8628b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1239",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Calling himself the fleet’s sole survivor, he struggled through his recollections with a pounding hangover.",["title"]="First Mate Fitzsimmons"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"297:description:1-116","297:description:119-235","297:description:238-289","297:description:292-316","297:description:321-396","297:description:399-454","297:objective:1-42"},["minimumStage"]=2,["questID"]=297,["sourceHash"]="80ec90e28c6f87597b10880935b6553e9c028929170f3281e6172603447132f0"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1345",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Troggs drove Magmar’s team from the dig shortly after carved idols were uncovered.",["title"]="Magmar Fellhew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"297:description:1-116","297:description:119-235","297:description:238-289","297:description:292-316","297:description:321-396","297:description:399-454","297:objective:1-42"},["minimumStage"]=2,["questID"]=297,["sourceHash"]="80ec90e28c6f87597b10880935b6553e9c028929170f3281e6172603447132f0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1345",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the idols recovered both for study and to remove objects that seemed to drive the troggs berserk.",["title"]="Magmar Fellhew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"303:description:1-31","303:description:34-199","303:description:202-237","303:description:240-264","303:description:269-320","303:description:323-460","303:description:465-479","303:objective:1-145"},["minimumStage"]=2,["questID"]=303,["sourceHash"]="df4d3eeac3bd68d405fd29ef020fa05118d0c577d4d50ceb058bc86f448b1901"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1074",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Garmason reported the Dark Irons’ destruction of the Thandol Span and the subsequent fall of Dun Modr.",["title"]="Motley Garmason"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"303:description:1-31","303:description:34-199","303:description:202-237","303:description:240-264","303:description:269-320","303:description:323-460","303:description:465-479","303:objective:1-145"},["minimumStage"]=2,["questID"]=303,["sourceHash"]="df4d3eeac3bd68d405fd29ef020fa05118d0c577d4d50ceb058bc86f448b1901"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1074",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought an immediate counterattack to hold the front until reserve troops could arrive.",["title"]="Motley Garmason"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"304:description:1-51","304:description:53-133","304:description:136-183","304:description:186-298","304:description:300-418","304:description:423-488","304:description:490-511","304:objective:1-83"},["minimumStage"]=2,["questID"]=304,["sourceHash"]="6331ad2e11c65eb84d1d1e311382d73afd33414fbe340bf5e57082ea04f9a4e1"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1071",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Longbraid lost many soldiers at Dun Modr and his own brother when the western Thandol bridge was destroyed.",["title"]="Longbraid the Grim"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"304:description:1-51","304:description:53-133","304:description:136-183","304:description:186-298","304:description:300-418","304:description:423-488","304:description:490-511","304:objective:1-83"},["minimumStage"]=2,["questID"]=304,["sourceHash"]="6331ad2e11c65eb84d1d1e311382d73afd33414fbe340bf5e57082ea04f9a4e1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1071",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Roggo’s intelligence identified Balgaras as the enemy leader; Longbraid posted a reward for the warlock’s ear.",["title"]="Longbraid the Grim"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"305:description:1-58","305:description:61-103","305:description:108-181","305:description:184-226","305:description:229-291","305:description:294-319","305:description:324-425","305:description:428-458","305:description:461-507","305:objective:1-91"},["minimumStage"]=2,["questID"]=305,["sourceHash"]="b9b06f9f2744d8607af04de591a7aef62d747f16195056d778ee3777635fc828"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2096",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tarrel’s wife Merrin worked with Whelgar’s excavation team and usually wrote to him each week.",["title"]="Tarrel Rockweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"305:description:1-58","305:description:61-103","305:description:108-181","305:description:184-226","305:description:229-291","305:description:294-319","305:description:324-425","305:description:428-458","305:description:461-507","305:objective:1-91"},["minimumStage"]=2,["questID"]=305,["sourceHash"]="b9b06f9f2744d8607af04de591a7aef62d747f16195056d778ee3777635fc828"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2096",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After nearly two weeks without a letter, he feared for her safety and appealed through Longbraid for a scout.",["title"]="Tarrel Rockweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"307:description:1-52","307:description:55-195","307:description:200-354","307:description:357-417","307:description:422-485","307:description:488-497","307:objective:1-65","307:objective:70-101"},["minimumStage"]=2,["questID"]=307,["sourceHash"]="dba753abe09b8286207d47bb03f19a6869b0ffb3f1088209633d02007b89372d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1343",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stormpike wanted Miners’ League equipment recovered from Silver Stream Mine before an armed assault damaged the stored tools.",["title"]="Mountaineer Stormpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"307:description:1-52","307:description:55-195","307:description:200-354","307:description:357-417","307:description:422-485","307:description:488-497","307:objective:1-65","307:objective:70-101"},["minimumStage"]=2,["questID"]=307,["sourceHash"]="dba753abe09b8286207d47bb03f19a6869b0ffb3f1088209633d02007b89372d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1343",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The exhausted mine had become a storage depot, then fallen into kobold hands.",["title"]="Mountaineer Stormpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"310:description:1-58","310:description:61-122","310:description:125-171","310:description:176-220","310:description:223-343","310:description:346-403","310:description:408-484","310:objective:1-127"},["minimumStage"]=2,["questID"]=310,["sourceHash"]="306889ec3bd1e34e7af6fd93631edc0a2790320a1813217e2543fc7875263756"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1375",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marleth wanted the Thunderbrews’ patrons to taste Barleybrew Scalder, planning to substitute a barrel in their Kharanos distillery.",["title"]="Marleth Barleybrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"310:description:1-58","310:description:61-122","310:description:125-171","310:description:176-220","310:description:223-343","310:description:346-403","310:description:408-484","310:objective:1-127"},["minimumStage"]=2,["questID"]=310,["sourceHash"]="306889ec3bd1e34e7af6fd93631edc0a2790320a1813217e2543fc7875263756"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1375",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Despite admitting that the rival family made good drinks, she resented the notion that theirs was the only worthy brew.",["title"]="Marleth Barleybrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"312:description:1-80","312:description:83-126","312:description:129-218","312:description:221-274","312:description:277-321","312:description:326-362","312:description:365-398","312:description:401-481","312:objective:1-90"},["minimumStage"]=2,["questID"]=312,["sourceHash"]="9d7163773302fedd50413b151714cfba4e9a4a9f947cb1be1443a5de391fc767"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-1266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A bad leg prevented MacGrann from moving quickly enough to recover his stolen food from Old Icebeard’s cave.",["title"]="Tundra MacGrann"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"312:description:1-80","312:description:83-126","312:description:129-218","312:description:221-274","312:description:277-321","312:description:326-362","312:description:365-398","312:description:401-481","312:objective:1-90"},["minimumStage"]=2,["questID"]=312,["sourceHash"]="9d7163773302fedd50413b151714cfba4e9a4a9f947cb1be1443a5de391fc767"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The beast took a thorium meat locker holding a month’s salted provisions while MacGrann was away hunting deer.",["title"]="Tundra MacGrann"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"318:description:1-45","318:description:48-145","318:description:150-246","318:description:249-299","318:description:304-398","318:description:401-465","318:objective:1-67"},["minimumStage"]=2,["questID"]=318,["sourceHash"]="cc3dbf5698ad2fde34741a12b71a0aa954d105cb4b672e12e61c19c947a7f781"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1378",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bellowfiz prized Evershine both for warmth on cold roads and for the burst of furnace power it could give Jetsteam’s machine.",["title"]="Pilot Bellowfiz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"318:description:1-45","318:description:48-145","318:description:150-246","318:description:249-299","318:description:304-398","318:description:401-465","318:objective:1-67"},["minimumStage"]=2,["questID"]=318,["sourceHash"]="cc3dbf5698ad2fde34741a12b71a0aa954d105cb4b672e12e61c19c947a7f781"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1378",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He depended on Rejold Barleybrew’s experiments at Brewnall Village for that unusually potent drink.",["title"]="Pilot Bellowfiz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"321:description:1-132","321:description:137-231","321:description:234-317","321:description:320-361","321:description:366-380","321:description:383-443","321:description:446-499","321:objective:1-57"},["minimumStage"]=2,["questID"]=321,["sourceHash"]="6bdfb95a12024d7e7a5ef7be6da916d45964f170c5059d13297f891b3bee046e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1217",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Glorin identified the Flying Osprey as an elven destroyer carrying Lightforge Iron when it joined the doomed fleet for protection.",["title"]="Glorin Steelbrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"321:description:1-132","321:description:137-231","321:description:234-317","321:description:320-361","321:description:366-380","321:description:383-443","321:description:446-499","321:objective:1-57"},["minimumStage"]=2,["questID"]=321,["sourceHash"]="6bdfb95a12024d7e7a5ef7be6da916d45964f170c5059d13297f891b3bee046e"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1217",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the search for the iron to the Flying Osprey’s wreck south of Menethil Harbor.",["title"]="Glorin Steelbrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"334:description:1-79","334:description:82-139","334:description:142-262","334:description:267-277","334:description:280-319","334:description:322-437","334:objective:1-100"},["minimumStage"]=2,["questID"]=334,["sourceHash"]="50cb2d1be202bfe69552f92e2763d72fefc5c3d97772f82b74488e916a6d1c70"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1428",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rema’s son Thurman was an apprentice at Larson Clothiers in Stormwind’s Mage Quarter.",["title"]="Rema Schneider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"334:description:1-79","334:description:82-139","334:description:142-262","334:description:267-277","334:description:280-319","334:description:322-437","334:objective:1-100"},["minimumStage"]=2,["questID"]=334,["sourceHash"]="50cb2d1be202bfe69552f92e2763d72fefc5c3d97772f82b74488e916a6d1c70"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1428",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="When Thurman hurried off without his shears and needles, she sought someone to deliver his sewing kit so he could work.",["title"]="Rema Schneider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"335:description:1-65","335:description:68-166","335:description:169-237","335:description:243-323","335:description:326-380","335:description:383-506","335:objective:1-116"},["minimumStage"]=2,["questID"]=335,["sourceHash"]="fda8565b2928bea69003f4daac3140870444d5659ac49ffd72bbe98267aae1af"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1435",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lord Wishock had learned of Zardeth’s establishment and pressed the House of Nobles for an investigation.",["title"]="Zardeth of the Black Claw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"335:description:1-65","335:description:68-166","335:description:169-237","335:description:243-323","335:description:326-380","335:description:383-506","335:objective:1-116"},["minimumStage"]=2,["questID"]=335,["sourceHash"]="fda8565b2928bea69003f4daac3140870444d5659ac49ffd72bbe98267aae1af"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1435",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zardeth sought Tear of Tilloa and Musquash Root for a plan to keep the inquisitive noble preoccupied.",["title"]="Zardeth of the Black Claw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"343:description:1-222","343:description:225-251","343:description:254-308","343:description:313-424","343:description:427-472","343:objective:1-70","343:objective:73-158"},["minimumStage"]=2,["questID"]=343,["sourceHash"]="8c53d2926b455e395e6b918cbd0d975e54e117239bd1c9a3645fce177a754356"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1444",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kristoff wanted passages from The Stresses of Iron for a speech on spiritual fortitude.",["title"]="Brother Kristoff"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"343:description:1-222","343:description:225-251","343:description:254-308","343:description:313-424","343:description:427-472","343:objective:1-70","343:objective:73-158"},["minimumStage"]=2,["questID"]=343,["sourceHash"]="8c53d2926b455e395e6b918cbd0d975e54e117239bd1c9a3645fce177a754356"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1444",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He trusted Royal Librarian Milton Sheaf to locate the volume among Stormwind Keep’s shelves.",["title"]="Brother Kristoff"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"344:description:1-21","344:description:24-44","344:description:47-127","344:description:130-201","344:description:204-216","344:description:221-236","344:description:239-267","344:description:270-323","344:description:326-433","344:description:438-461","344:description:464-502","344:objective:1-50"},["minimumStage"]=2,["questID"]=344,["sourceHash"]="6c8b08f2e132f156a8a10159a0c11e151dd10e7fa71da342ca74485054e69a4d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1440",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Milton knew the Royal Library’s collection and identified Margulf Blaggon as the dwarven author of The Stresses of Iron.",["title"]="Milton Sheaf"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"344:description:1-21","344:description:24-44","344:description:47-127","344:description:130-201","344:description:204-216","344:description:221-236","344:description:239-267","344:description:270-323","344:description:326-433","344:description:438-461","344:description:464-502","344:objective:1-50"},["minimumStage"]=2,["questID"]=344,["sourceHash"]="6c8b08f2e132f156a8a10159a0c11e151dd10e7fa71da342ca74485054e69a4d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1440",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He had lent the book to Brother Paxton for copying at Northshire and wondered why it had not returned after months.",["title"]="Milton Sheaf"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"345:description:1-67","345:description:72-120","345:description:123-230","345:description:233-340","345:description:345-409","345:description:412-459","345:objective:1-71"},["minimumStage"]=2,["questID"]=345,["sourceHash"]="22c203d384c2c88041e080ed1285070092606a6349008b95615d382dddaf0a4d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-951",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Paxton copied books for Northshire’s library using an ink of his own making, resistant to running and smearing.",["title"]="Brother Paxton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"345:description:1-67","345:description:72-120","345:description:123-230","345:description:233-340","345:description:345-409","345:description:412-459","345:objective:1-71"},["minimumStage"]=2,["questID"]=345,["sourceHash"]="22c203d384c2c88041e080ed1285070092606a6349008b95615d382dddaf0a4d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-951",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His fast-drying ink hardened before he finished copying The Stresses of Iron; new ink required Rethban ore from Oslow.",["title"]="Brother Paxton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"350:description:1-83","350:description:88-236","350:description:238-319","350:description:321-359","350:description:364-386","350:description:388-451","350:description:453-504","350:objective:1-35"},["minimumStage"]=2,["questID"]=350,["sourceHash"]="25382028bce1d5658f18aae6e030bc6617d1c616561e8013e29ad506235ff358"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-332",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shaw believed Lescovar’s noble connections and the loss of crucial witnesses would frustrate ordinary justice.",["title"]="Master Mathias Shaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"350:description:1-83","350:description:88-236","350:description:238-319","350:description:321-359","350:description:364-386","350:description:388-451","350:description:453-504","350:objective:1-35"},["minimumStage"]=2,["questID"]=350,["sourceHash"]="25382028bce1d5658f18aae6e030bc6617d1c616561e8013e29ad506235ff358"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-332",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He reluctantly directed the investigation toward Trias in the Trade District for help beyond the usual legal channels.",["title"]="Master Mathias Shaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"356:description:1-92","356:description:95-136","356:description:141-294","356:description:299-317","356:description:320-361","356:description:364-423","356:description:426-471","356:objective:1-88"},["minimumStage"]=2,["questID"]=356,["sourceHash"]="f5748a7a09225ef297c95de3920d3f7d448f50dcc8c13bd5b424ba3118f380f9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1495",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Linnea sought to protect the Bulwark’s rear and supply line by clearing Scourge that slipped into Tirisfal.",["title"]="Deathguard Linnea"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"356:description:1-92","356:description:95-136","356:description:141-294","356:description:299-317","356:description:320-361","356:description:364-423","356:description:426-471","356:objective:1-88"},["minimumStage"]=2,["questID"]=356,["sourceHash"]="f5748a7a09225ef297c95de3920d3f7d448f50dcc8c13bd5b424ba3118f380f9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-1495",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Balnir Farmstead had become a refuge for undead interlopers behind the defenders’ front.",["title"]="Deathguard Linnea"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"365:description:1-18","365:description:21-49","365:description:52-142","365:description:147-177","365:description:180-232","365:description:235-301","365:description:304-369","365:description:374-431","365:objective:1-114"},["minimumStage"]=2,["questID"]=365,["sourceHash"]="f015eff1d9ab933afd2b0fa31eb654dd231d1d8c38d05edbdabe9a8d01c3a019"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1519",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Simmer sent new Forsaken to steal pumpkins from a human farm and deliver them to Apothecary Johaan.",["title"]="Deathguard Simmer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"374:description:1-67","374:description:69-106","374:description:111-246","374:description:248-340","374:description:345-407","374:description:409-506","374:objective:1-63"},["minimumStage"]=2,["questID"]=374,["sourceHash"]="b4579e670ee215c153e40f358e098a7dba420d442d825b5b209f8b4946277278"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1652",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Burgess demanded Scarlet insignia rings as proof of service to Varimathras and the Dark Lady.",["title"]="Deathguard Burgess"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"374:description:1-67","374:description:69-106","374:description:111-246","374:description:248-340","374:description:345-407","374:description:409-506","374:objective:1-63"},["minimumStage"]=2,["questID"]=374,["sourceHash"]="b4579e670ee215c153e40f358e098a7dba420d442d825b5b209f8b4946277278"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1652",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His instructions expressed open hatred of humans and framed the local Scarlet offensive as loyalty to Forsaken leadership.",["title"]="Deathguard Burgess"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"10:description:1-26","10:description:29-119","10:description:122-161","10:description:164-250","10:description:253-322","10:description:327-399","10:description:402-408","10:description:410-450","10:description:453-504","10:objective:1-142"},["minimumStage"]=2,["questID"]=10,["sourceHash"]="6f42d017d4c43e4e6b15e3b5573d895ca3bea867a7fdad1b190cc6cecbefaadd"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-981",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scrimshank vanished while surveying the chasm southeast of Gadgetzan after reporting an increasing insect presence.",["title"]="The Gaping Chasm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"11:description:1-116","11:description:119-232","11:description:235-305","11:description:310-366","11:description:369-428","11:objective:1-64"},["minimumStage"]=2,["questID"]=11,["sourceHash"]="60b84da9264d1e823061a3a4b840978224a7fa48131e977ffb64093643918b49"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="reviewed-stone-cairn-lake",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rainer’s report placed one of the Riverpaw packs around the lake, beyond what his guards could handle alone.",["title"]="Stone Cairn Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"64:description:1-16","64:description:19-70","64:description:73-106","64:description:109-163","64:description:166-265","64:description:268-324","64:description:327-390","64:description:393-441","64:objective:1-122"},["minimumStage"]=2,["questID"]=64,["sourceHash"]="443a3f052e05e1250f33543606479146a228dde4b7323beeee962c7baac0c8c1"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-109",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Furlbrows fled intruders in their fields, leaving a wedding keepsake among the belongings in their farmhouse.",["title"]="Furlbrow's Pumpkin Farm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"12:description:1-109","12:description:112-160","12:description:166-250","12:description:253-394","12:description:396-492","12:objective:1-115"},["minimumStage"]=2,["questID"]=12,["sourceHash"]="ca931237fbf24d9fb1703086d37ba10225b4b81652c6587e2a0b33480b1a8ead"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="reviewed-jangolode-mine",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Militia scouts reported Defias trappers operating around the mine and nearby farms.",["title"]="Jangolode Mine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"307:description:1-52","307:description:55-195","307:description:200-354","307:description:357-417","307:description:422-485","307:description:488-497","307:objective:1-65","307:objective:70-101"},["minimumStage"]=2,["questID"]=307,["sourceHash"]="dba753abe09b8286207d47bb03f19a6869b0ffb3f1088209633d02007b89372d"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-149",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After its ore ran out, the Miners’ League converted the mine into a tool depot. Kobolds later occupied the workings.",["title"]="Silver Stream Mine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"303:description:1-31","303:description:34-199","303:description:202-237","303:description:240-264","303:description:269-320","303:description:323-460","303:description:465-479","303:objective:1-145"},["minimumStage"]=2,["questID"]=303,["sourceHash"]="df4d3eeac3bd68d405fd29ef020fa05118d0c577d4d50ceb058bc86f448b1901"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-330",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dark Iron attacks destroyed the span before Dun Modr fell, opening a dangerous front in the dwarven homeland.",["title"]="Thandol Span"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"304:description:1-51","304:description:53-133","304:description:136-183","304:description:186-298","304:description:300-418","304:description:423-488","304:description:490-511","304:objective:1-83"},["minimumStage"]=2,["questID"]=304,["sourceHash"]="6331ad2e11c65eb84d1d1e311382d73afd33414fbe340bf5e57082ea04f9a4e1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-330",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Longbraid’s brother died in the destruction of the western bridge, giving the campaign a personal cost beyond the lost crossing.",["title"]="Thandol Span"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"304:description:1-51","304:description:53-133","304:description:136-183","304:description:186-298","304:description:300-418","304:description:423-488","304:description:490-511","304:objective:1-83"},["minimumStage"]=2,["questID"]=304,["sourceHash"]="6331ad2e11c65eb84d1d1e311382d73afd33414fbe340bf5e57082ea04f9a4e1"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-205",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The battle cost Longbraid many soldiers and left the Dark Irons holding ground in the Wetlands.",["title"]="Dun Modr"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"304:description:1-51","304:description:53-133","304:description:136-183","304:description:186-298","304:description:300-418","304:description:423-488","304:description:490-511","304:objective:1-83"},["minimumStage"]=2,["questID"]=304,["sourceHash"]="6331ad2e11c65eb84d1d1e311382d73afd33414fbe340bf5e57082ea04f9a4e1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1016",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Roggo’s intelligence placed the Dark Iron warlock Balgaras and his camp on the hill southeast of Dun Modr.",["title"]="Direforge Hill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"264:description:1-12","264:description:14-44","264:description:46-137","264:description:142-172","264:description:174-188","264:description:190-241","264:description:243-276","264:description:281-324","264:description:326-388","264:description:393-456","264:description:458-496","264:description:498-504","264:objective:1-54"},["minimumStage"]=2,["questID"]=264,["sourceHash"]="9ac151a0dafbb95c4477306e7f6a4fe44abda88ac7d3d08038e4d91b83d0562f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-228",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A crusader’s tomb here became the destination for the keepsake his embittered widow Clarice no longer wanted.",["title"]="The Sepulcher"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"318:description:1-45","318:description:48-145","318:description:150-246","318:description:249-299","318:description:304-398","318:description:401-465","318:objective:1-67"},["minimumStage"]=2,["questID"]=318,["sourceHash"]="cc3dbf5698ad2fde34741a12b71a0aa954d105cb4b672e12e61c19c947a7f781"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-137",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rejold Barleybrew experimented with potent drinks in the village west of Kharanos, including the fiery Evershine.",["title"]="Brewnall Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"335:description:1-65","335:description:68-166","335:description:169-237","335:description:243-323","335:description:326-380","335:description:383-506","335:objective:1-116"},["minimumStage"]=2,["questID"]=335,["sourceHash"]="fda8565b2928bea69003f4daac3140870444d5659ac49ffd72bbe98267aae1af"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-146",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Musquash Root grew at the foot of the falls far beneath the dam.",["title"]="Stonewrought Dam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"356:description:1-92","356:description:95-136","356:description:141-294","356:description:299-317","356:description:320-361","356:description:364-423","356:description:426-471","356:objective:1-88"},["minimumStage"]=2,["questID"]=356,["sourceHash"]="f5748a7a09225ef297c95de3920d3f7d448f50dcc8c13bd5b424ba3118f380f9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="reviewed-balnir-farmstead",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scourge slipping past the Bulwark gathered at the farmstead, endangering the defenders from behind.",["title"]="Balnir Farmstead"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"356:description:1-92","356:description:95-136","356:description:141-294","356:description:299-317","356:description:320-361","356:description:364-423","356:description:426-471","356:objective:1-88"},["minimumStage"]=2,["questID"]=356,["sourceHash"]="f5748a7a09225ef297c95de3920d3f7d448f50dcc8c13bd5b424ba3118f380f9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-152",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The defenders’ line depended on keeping their rear and supply route secure against Scourge infiltration.",["title"]="The Bulwark"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"216:description:1-248","216:objective:1-115"},["minimumStage"]=2,["questID"]=216,["sourceHash"]="9502ed671cfcbc1428d4ff7a49b576da55375e2ad1dafa7325e536135a88fdef"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2301",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/216",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Karang saw the village as blocking a Horde route to Splintertree that would bypass Astranaar.",["title"]="Thistlefur Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"305:description:1-58","305:description:61-103","305:description:108-181","305:description:184-226","305:description:229-291","305:description:294-319","305:description:324-425","305:description:428-458","305:description:461-507","305:objective:1-91"},["minimumStage"]=2,["questID"]=305,["sourceHash"]="b9b06f9f2744d8607af04de591a7aef62d747f16195056d778ee3777635fc828"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-118",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Merrin worked with the excavation team. When her weekly letters stopped, her husband Tarrel feared the dig had met disaster.",["title"]="Whelgar's Excavation Site"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"261:description:1-16","261:description:19-49","261:description:52-111","261:description:114-188","261:description:191-267","261:description:272-420","261:description:425-466","261:objective:1-74"},["minimumStage"]=2,["questID"]=261,["sourceHash"]="e0058dfb5aa4fd0c187207456db9da75b302d07ba330dcfc5fd9b25962eed42b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16020",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brother Anton directed would-be Scarlet allies against the undead ravagers in this southern part of Desolace.",["title"]="Valley of Bones"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"375:description:1-18","375:description:21-86","375:description:89-128","375:description:131-195","375:description:198-285","375:description:290-323","375:description:326-418","375:description:421-475","375:objective:1-76"},["minimumStage"]=2,["questID"]=375,["sourceHash"]="876fc0e94c9de0e286b6471028f25fb0095a1b6c0d3b272edc9d65cd7b067955"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1521",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gretchen sewed body bags for Sylvanas’s fallen soldiers and wanted to keep serving despite the chill shaking her hands.",["title"]="Gretchen Dedmar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"375:description:1-18","375:description:21-86","375:description:89-128","375:description:131-195","375:description:198-285","375:description:290-323","375:description:326-418","375:description:421-475","375:objective:1-76"},["minimumStage"]=2,["questID"]=375,["sourceHash"]="876fc0e94c9de0e286b6471028f25fb0095a1b6c0d3b272edc9d65cd7b067955"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1521",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She feared that the plague would soon leave her mindless; duskbat pelts and thread could at least provide a blanket against the cold she felt.",["title"]="Gretchen Dedmar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"377:description:1-256","377:description:261-353","377:description:356-399","377:description:404-491","377:objective:1-82"},["minimumStage"]=2,["questID"]=377,["sourceHash"]="4502e1273d84d4d5bd96674b3f9e43efc1d00f8f2591f7ab660015d8ff8fc3b5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-270",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Millstipe resented Stormwind’s decision to imprison Dextren Ward instead of carrying out Ebonlocke’s death sentence for selling cemetery bodies to Morbent Fel.",["title"]="Councilman Millstipe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"377:description:1-256","377:description:261-353","377:description:356-399","377:description:404-491","377:objective:1-82"},["minimumStage"]=2,["questID"]=377,["sourceHash"]="4502e1273d84d4d5bd96674b3f9e43efc1d00f8f2591f7ab660015d8ff8fc3b5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-270",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered payment for Ward’s severed hand, seeking an execution inside the Stockade outside the city’s chosen sentence.",["title"]="Councilman Millstipe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"385:description:1-66","385:description:68-210","385:description:215-353","385:description:355-449","385:description:454-474","385:objective:1-97"},["minimumStage"]=2,["questID"]=385,["sourceHash"]="4724b7f3e82f91e61af50b9f70f9713d978e9c5c0b6970afa439b46cb932c687"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1154",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marek described a modest local trade in crocolisk skins and meat, limited by the ferocity of the beasts on the Loch’s islands.",["title"]="Marek Ironheart"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"385:description:1-66","385:description:68-210","385:description:215-353","385:description:355-449","385:description:454-474","385:objective:1-97"},["minimumStage"]=2,["questID"]=385,["sourceHash"]="4724b7f3e82f91e61af50b9f70f9713d978e9c5c0b6970afa439b46cb932c687"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1154",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He encouraged hunters to test themselves against the crocolisks rather than let his warnings discourage them.",["title"]="Marek Ironheart"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"386:description:1-66","386:description:69-124","386:description:127-197","386:description:200-264","386:description:267-289","386:description:292-350","386:description:353-388","386:description:393-428","386:description:431-495","386:objective:1-65"},["minimumStage"]=2,["questID"]=386,["sourceHash"]="a38611f9b241e21d14873caf3309af55433e13e0c26a4d1e3ba00e8088dca48b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-859",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Berton recalled Targorr as Gath’Ilzogg’s ruthless executioner, responsible for torturing Stormwind’s defenders.",["title"]="Guard Berton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"386:description:1-66","386:description:69-124","386:description:127-197","386:description:200-264","386:description:267-289","386:description:292-350","386:description:353-388","386:description:393-428","386:description:431-495","386:objective:1-65"},["minimumStage"]=2,["questID"]=386,["sourceHash"]="a38611f9b241e21d14873caf3309af55433e13e0c26a4d1e3ba00e8088dca48b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-859",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A noble’s stay of the prisoner’s execution aroused his suspicion; Berton wanted Targorr beheaded before any further intervention.",["title"]="Guard Berton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"388:description:1-52","388:description:55-92","388:description:95-114","388:description:117-193","388:description:196-262","388:description:265-374","388:description:377-413","388:description:418-432","388:description:435-478","388:description:481-508","388:objective:1-69"},["minimumStage"]=2,["questID"]=388,["sourceHash"]="baee3b1d8241bb27e9f8a43472b59af548249a99f5380bf048c50dee8fcf2314"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1721",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nikova’s fourteen-year-old grandson Mac took guard duty in the Stockade while the army was away, then was stabbed after reprimanding Defias prisoners.",["title"]="Nikova Raskol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"388:description:1-52","388:description:55-92","388:description:95-114","388:description:117-193","388:description:196-262","388:description:265-374","388:description:377-413","388:description:418-432","388:description:435-478","388:description:481-508","388:objective:1-69"},["minimumStage"]=2,["questID"]=388,["sourceHash"]="baee3b1d8241bb27e9f8a43472b59af548249a99f5380bf048c50dee8fcf2314"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1721",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She demanded the gang’s wool bandanas in revenge for Mac, linking their red insignia with his spilled blood.",["title"]="Nikova Raskol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"389:description:1-53","389:description:55-110","389:description:115-163","389:description:165-206","389:description:208-344","389:description:346-395","389:description:400-468","389:description:470-510","389:objective:1-44"},["minimumStage"]=2,["questID"]=389,["sourceHash"]="73bfdf066e57bcaf71594b5e6813863f134f8a247111db521b64bf8430e1e0f1"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1646",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Baros and VanCleef belonged to the Stonemasons who rebuilt Stormwind after the war and were denied their promised payment.",["title"]="Baros Alexston"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"389:description:1-53","389:description:55-110","389:description:115-163","389:description:165-206","389:description:208-344","389:description:346-395","389:description:400-468","389:description:470-510","389:objective:1-44"},["minimumStage"]=2,["questID"]=389,["sourceHash"]="73bfdf066e57bcaf71594b5e6813863f134f8a247111db521b64bf8430e1e0f1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1646",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He remembered senior masons being offered government posts while VanCleef refused, led a riot and left the city vowing revenge.",["title"]="Baros Alexston"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"391:description:1-52","391:description:54-124","391:description:129-205","391:description:207-292","391:description:294-354","391:description:356-419","391:objective:1-78"},["minimumStage"]=2,["questID"]=391,["sourceHash"]="8471649e1a584af1309f6b5ad7d46a561493fab65b20c1836d0ee90085519bc7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1719",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thelwater openly distrusted the visitor seeking Thredd, but the Stockade crisis left him willing to permit the meeting.",["title"]="Warden Thelwater"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"391:description:1-52","391:description:54-124","391:description:129-205","391:description:207-292","391:description:294-354","391:description:356-419","391:objective:1-78"},["minimumStage"]=2,["questID"]=391,["sourceHash"]="8471649e1a584af1309f6b5ad7d46a561493fab65b20c1836d0ee90085519bc7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1719",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He demanded Thredd’s head as proof of allegiance and threatened anyone choosing the prisoners’ side.",["title"]="Warden Thelwater"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"394:description:1-22","394:description:24-145","394:description:147-218","394:description:223-302","394:description:304-337","394:description:339-435","394:objective:1-35"},["minimumStage"]=2,["questID"]=394,["sourceHash"]="602d3b26db9c8cd517ec32f523fb52fd70cfedf61bf5cab3b6ee3478ac5d861b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-482",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Trias regarded the nobles’ apparent control of Stormwind with skepticism, insisting that some affairs lay beyond their grasp.",["title"]="Elling Trias"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"394:description:1-22","394:description:24-145","394:description:147-218","394:description:223-302","394:description:304-337","394:description:339-435","394:objective:1-35"},["minimumStage"]=2,["questID"]=394,["sourceHash"]="602d3b26db9c8cd517ec32f523fb52fd70cfedf61bf5cab3b6ee3478ac5d861b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-482",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the report on Lescovar’s plot back to Shaw in Old Town.",["title"]="Elling Trias"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"400:description:1-93","400:description:96-131","400:description:134-209","400:description:214-253","400:description:256-320","400:description:325-384","400:description:387-502","400:objective:1-48"},["minimumStage"]=2,["questID"]=400,["sourceHash"]="ce1f9910e687ce1d355645aa697b3dba0bf38af18e8f1d717c82caf75ce8272b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1872",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tharek arranged a fresh tool delivery for Beldin Steelgrill’s mechanic shop northeast of Kharanos.",["title"]="Tharek Blackstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"400:description:1-93","400:description:96-131","400:description:134-209","400:description:214-253","400:description:256-320","400:description:325-384","400:description:387-502","400:objective:1-48"},["minimumStage"]=2,["questID"]=400,["sourceHash"]="ce1f9910e687ce1d355645aa697b3dba0bf38af18e8f1d717c82caf75ce8272b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1872",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He praised Beldin’s siege-engine skill while joking that the mechanic broke arclight spanners almost faster than they could be supplied.",["title"]="Tharek Blackstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"412:description:1-223","412:description:228-327","412:description:330-436","412:description:439-505","412:objective:1-86"},["minimumStage"]=2,["questID"]=412,["sourceHash"]="f918d1a33f85ba9e2fd5ab9d29257aa8a2d2cb94c342e16a70a6017488b8e604"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1269",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Razzle and Ozzie built a Recombobulator in the hope of reversing the leper gnomes’ condition.",["title"]="Razzle Sprysprocket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"412:description:1-223","412:description:228-327","412:description:330-436","412:description:439-505","412:objective:1-86"},["minimumStage"]=2,["questID"]=412,["sourceHash"]="f918d1a33f85ba9e2fd5ab9d29257aa8a2d2cb94c342e16a70a6017488b8e604"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1269",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The machine was nearly complete but lacked restabilization cogs and gyromechanic gears, which he sought from Gnomeregan’s afflicted inhabitants.",["title"]="Razzle Sprysprocket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"414:description:1-81","414:description:84-121","414:description:124-212","414:description:217-322","414:description:325-365","414:description:370-444","414:objective:1-54"},["minimumStage"]=2,["questID"]=414,["sourceHash"]="8ce741c5be37a91a404b04bcbd1f7ee7cd143e569aca3700f1fd8a8d52eeb739"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1959",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Barleybrew wanted fellow mountaineer Kadrell to try the Shimmer Stout his brother had made.",["title"]="Mountaineer Barleybrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"418:description:1-149","418:description:151-226","418:description:235-359","418:description:364-444","418:description:446-502","418:objective:1-101"},["minimumStage"]=2,["questID"]=418,["sourceHash"]="f8a4682a45a66a6f38203f9431a205a6bd59abbc41a85e484e58095da0bb4feb"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1963",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vidra fed Thelsamar’s children and returning excavation workers, taking pride in the town’s blood sausages.",["title"]="Vidra Hearthstove"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"418:description:1-149","418:description:151-226","418:description:235-359","418:description:364-444","418:description:446-502","418:objective:1-101"},["minimumStage"]=2,["questID"]=418,["sourceHash"]="f8a4682a45a66a6f38203f9431a205a6bd59abbc41a85e484e58095da0bb4feb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1963",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her recipe used bear meat, boar intestines for casings and spider ichor for seasoning; even adventurers were expected to supply ingredients for a meal.",["title"]="Vidra Hearthstove"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"427:description:1-115","427:description:118-178","427:description:183-221","427:description:224-271","427:description:274-363","427:description:368-509","427:objective:1-63"},["minimumStage"]=2,["questID"]=427,["sourceHash"]="d0e18c0727635879e5d46d07d10cc3895d30652d2862761a9e86093b70cddd48"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="reviewed-executor-zygand",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Arren’s documents gave Zygand the Scarlet positions he needed, but the growing Scourge threat kept his Deathguard occupied elsewhere.",["title"]="Executor Zygand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"427:description:1-115","427:description:118-178","427:description:183-221","427:description:224-271","427:description:274-363","427:description:368-509","427:objective:1-63"},["minimumStage"]=2,["questID"]=427,["sourceHash"]="d0e18c0727635879e5d46d07d10cc3895d30652d2862761a9e86093b70cddd48"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="reviewed-executor-zygand",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent an independent recruit against the warriors at the tower beyond Solliden Farmstead as proof of service to Sylvanas.",["title"]="Executor Zygand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"432:description:1-62","432:description:64-113","432:description:118-202","432:description:204-227","432:description:232-293","432:description:295-322","432:description:324-331","432:description:336-386","432:description:388-446","432:description:448-460","432:description:462-487","432:objective:1-75"},["minimumStage"]=2,["questID"]=432,["sourceHash"]="8f9209db23c7513c3fc478269797f3543b1b5a46986b0bface6904643f43117a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1254",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Troggs wrecked Stonebrow’s quarry and its powder barrels, leaving the foreman furious and distressed.",["title"]="Foreman Stonebrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"432:description:1-62","432:description:64-113","432:description:118-202","432:description:204-227","432:description:232-293","432:description:295-322","432:description:324-331","432:description:336-386","432:description:388-446","432:description:448-460","432:description:462-487","432:objective:1-75"},["minimumStage"]=2,["questID"]=432,["sourceHash"]="8f9209db23c7513c3fc478269797f3543b1b5a46986b0bface6904643f43117a"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1254",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stonebrow admitted that his aim was no longer good enough to deal with the invaders himself.",["title"]="Foreman Stonebrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"434:description:1-68","434:description:70-111","434:description:116-240","434:description:242-279","434:description:284-359","434:description:361-422","434:description:424-475","434:description:477-509","434:objective:1-104","434:objective:106-178"},["minimumStage"]=2,["questID"]=434,["sourceHash"]="d202eaa40829edf1f4fdb3efb864375ad658d5001c59c885af04c943472db28c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7766",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tyrion prepared a disguised spybot to reach Lescovar and arranged a meeting through false information sent to Marzon.",["title"]="Tyrion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"434:description:1-68","434:description:70-111","434:description:116-240","434:description:242-279","434:description:284-359","434:description:361-422","434:description:424-475","434:description:477-509","434:objective:1-104","434:objective:106-178"},["minimumStage"]=2,["questID"]=434,["sourceHash"]="d202eaa40829edf1f4fdb3efb864375ad658d5001c59c885af04c943472db28c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7766",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His plan depended on overhearing their Defias discussion and striking after the guards were dismissed but before they returned.",["title"]="Tyrion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"436:description:1-79","436:description:82-171","436:description:176-285","436:description:290-347","436:description:350-421","436:description:426-511","436:objective:1-28"},["minimumStage"]=2,["questID"]=436,["sourceHash"]="238c47d8343b779c2017db16644c08be3f427587628e6e6ab2fb43a00e51dcd2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1105",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jern trusted Ironband as an honest, results-minded prospector and knew that Magmar managed the excavation’s practical details.",["title"]="Jern Hornhelm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"436:description:1-79","436:description:82-171","436:description:176-285","436:description:290-347","436:description:350-421","436:description:426-511","436:objective:1-28"},["minimumStage"]=2,["questID"]=436,["sourceHash"]="238c47d8343b779c2017db16644c08be3f427587628e6e6ab2fb43a00e51dcd2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1105",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Slow progress despite repeated supply shipments made him fear that something was obstructing the dig east of the lake.",["title"]="Jern Hornhelm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"455:description:1-56","455:description:59-100","455:description:103-237","455:description:242-325","455:description:328-372","455:description:377-456","455:description:461-486","455:description:489-500","455:objective:1-19","455:objective:24-70","455:objective:75-119"},["minimumStage"]=2,["questID"]=455,["sourceHash"]="524fc92094783dd80c19c622aad1bc8823e273df6cb37f75623f64b57af86ca8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1342",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rockgar feared that the Dragonmaw foothold in Dun Algaz would sever Loch Modan’s road to Menethil Harbor.",["title"]="Mountaineer Rockgar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"455:description:1-56","455:description:59-100","455:description:103-237","455:description:242-325","455:description:328-372","455:description:377-456","455:description:461-486","455:description:489-500","455:objective:1-19","455:objective:24-70","455:objective:75-119"},["minimumStage"]=2,["questID"]=455,["sourceHash"]="524fc92094783dd80c19c622aad1bc8823e273df6cb37f75623f64b57af86ca8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1342",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He called for a breakthrough into the Wetlands and a report to Valstag Ironjaw at the port.",["title"]="Mountaineer Rockgar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"456:description:1-14","456:description:17-44","456:description:47-125","456:description:130-251","456:description:256-329","456:description:332-387","456:description:390-497","456:objective:1-88"},["minimumStage"]=2,["questID"]=456,["sourceHash"]="e3aeee2bdb83486a5040f96f823fdf7afc9c32a5e85151134d59a12ad6a30ef4"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2079",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ilthalaine maintained Shadowglen’s natural balance, judging animal populations against the food the forest could provide.",["title"]="Conservator Ilthalaine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"456:description:1-14","456:description:17-44","456:description:47-125","456:description:130-251","456:description:256-329","456:description:332-387","456:description:390-497","456:objective:1-88"},["minimumStage"]=2,["questID"]=456,["sourceHash"]="e3aeee2bdb83486a5040f96f823fdf7afc9c32a5e85151134d59a12ad6a30ef4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2079",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Heavy spring rains had favored nightsabers and thistle boars over other beasts, prompting a cull to restore that balance.",["title"]="Conservator Ilthalaine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"458:description:1-32","458:description:34-111","458:description:116-190","458:description:192-266","458:description:268-332","458:description:337-405","458:description:407-477","458:objective:1-40"},["minimumStage"]=2,["questID"]=458,["sourceHash"]="b7ea0cfcc33a619649257fe433f77265fbbfbede00776e509ee996399bfa09d0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2077",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Forest spirits brought Melithar news that the dryad Tarindrella had returned to Shadowglen after years away from Kalimdor’s forests.",["title"]="Melithar Staghelm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"458:description:1-32","458:description:34-111","458:description:116-190","458:description:192-266","458:description:268-332","458:description:337-405","458:description:407-477","458:objective:1-40"},["minimumStage"]=2,["questID"]=458,["sourceHash"]="b7ea0cfcc33a619649257fe433f77265fbbfbede00776e509ee996399bfa09d0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2077",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He suspected a serious disturbance behind her return and sought someone to learn her purpose near Aldrassil.",["title"]="Melithar Staghelm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"459:description:1-55","459:description:58-122","459:description:125-210","459:description:215-287","459:description:290-384","459:description:391-507","459:objective:1-49"},["minimumStage"]=2,["questID"]=459,["sourceHash"]="a86e4c10edf18330954d833e5e759536635c3ba91cb55425c2b8a34a4563f57f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1992",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tarindrella connected the Gnarlpine furbolgs’ corruption with Fel Moss and the grell infestation threatening Shadowglen.",["title"]="Tarindrella"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"459:description:1-55","459:description:58-122","459:description:125-210","459:description:215-287","459:description:290-384","459:description:391-507","459:objective:1-49"},["minimumStage"]=2,["questID"]=459,["sourceHash"]="a86e4c10edf18330954d833e5e759536635c3ba91cb55425c2b8a34a4563f57f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1992",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She asked for grells and grellkin to be examined through the struggle against them, seeking confirmation of the enchantment.",["title"]="Tarindrella"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"466:description:1-99","466:description:102-272","466:description:277-356","466:description:361-428","466:description:431-460","466:description:462-498","466:objective:1-66"},["minimumStage"]=2,["questID"]=466,["sourceHash"]="1a0a103bfe378882053e2977f15117ea3a221b5b0762318a70cd3302cf5405a7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1377",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stonegear wanted volatile incendicite from a cave northwest of Algaz Gate, hoping properly smelted ore could strengthen cannon shells.",["title"]="Pilot Stonegear"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"469:description:1-20","469:description:25-99","469:description:101-210","469:description:215-375","469:description:380-495","469:objective:1-88"},["minimumStage"]=2,["questID"]=469,["sourceHash"]="adbbc85273a53ca247971d63e8e6297d0145cecaaa1e06de1f6e4b9b903120fe"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2093",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Einar sent crocolisk skins to James Halloran, the Menethil tanner.",["title"]="Einar Stonegrip"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"469:description:1-20","469:description:25-99","469:description:101-210","469:description:215-375","469:description:380-495","469:objective:1-88"},["minimumStage"]=2,["questID"]=469,["sourceHash"]="adbbc85273a53ca247971d63e8e6297d0145cecaaa1e06de1f6e4b9b903120fe"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2093",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He praised the harbor’s goods and hospitality while admitting that he was putting off facing his wife at home.",["title"]="Einar Stonegrip"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"470:description:1-82","470:description:84-105","470:description:110-158","470:description:160-194","470:description:196-243","470:description:248-312","470:description:317-384","470:description:386-438","470:description:440-457","470:objective:1-109"},["minimumStage"]=2,["questID"]=470,["sourceHash"]="cfe8dbd6b48d7215847de42327cb6f7206d7c5e93fbc391a98b8051962ced6ef"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2111",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sida lost her bag to an ooze while making a weekly visit to Ironbeard’s Tomb; throwing it bought time to escape.",["title"]="Sida"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"470:description:1-82","470:description:84-105","470:description:110-158","470:description:160-194","470:description:196-243","470:description:248-312","470:description:317-384","470:description:386-438","470:description:440-457","470:objective:1-109"},["minimumStage"]=2,["questID"]=470,["sourceHash"]="cfe8dbd6b48d7215847de42327cb6f7206d7c5e93fbc391a98b8051962ced6ef"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2111",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted its contents recovered but could not distinguish the creature that swallowed it from the others.",["title"]="Sida"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"472:description:1-45","472:description:50-73","472:description:76-107","472:description:110-194","472:description:199-246","472:description:249-305","472:description:308-322","472:description:327-385","472:description:388-414","472:description:417-449","472:description:452-493","472:objective:1-47"},["minimumStage"]=2,["questID"]=472,["sourceHash"]="f7184ebfb952f16670049fdfbb9736af5059fe05e05791ea69b39365577837af"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2097",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Harlo survived Dun Modr’s fall after a stray axe struck his back during Longbraid’s retreat. He awoke wounded in Menethil.",["title"]="Harlo Barnaby"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"472:description:1-45","472:description:50-73","472:description:76-107","472:description:110-194","472:description:199-246","472:description:249-305","472:description:308-322","472:description:327-385","472:description:388-414","472:description:417-449","472:description:452-493","472:objective:1-47"},["minimumStage"]=2,["questID"]=472,["sourceHash"]="f7184ebfb952f16670049fdfbb9736af5059fe05e05791ea69b39365577837af"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2097",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Unable to return to the front, he hoped someone could find Longbraid and the other soldiers still near the lost town.",["title"]="Harlo Barnaby"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"487:description:1-40","487:description:43-171","487:description:176-259","487:description:262-330","487:description:335-384","487:description:387-436","487:description:439-496","487:objective:1-88"},["minimumStage"]=2,["questID"]=487,["sourceHash"]="ce5e405d766bed0dad67a7911f415816dc6abb3aa0916f73a0432053a48352b5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2151",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Amara sought to protect the road between Dolanaar and Darnassus because news and commerce depended on it.",["title"]="Moon Priestess Amara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"487:description:1-40","487:description:43-171","487:description:176-259","487:description:262-330","487:description:335-384","487:description:387-436","487:description:439-496","487:objective:1-88"},["minimumStage"]=2,["questID"]=487,["sourceHash"]="ce5e405d766bed0dad67a7911f415816dc6abb3aa0916f73a0432053a48352b5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2151",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gnarlpine ambushers from a nearby den were attacking travelers along that route.",["title"]="Moon Priestess Amara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"488:description:1-22","488:description:25-119","488:description:124-218","488:description:221-284","488:description:289-337","488:description:341-350","488:description:353-446","488:description:451-488","488:objective:1-121"},["minimumStage"]=2,["questID"]=488,["sourceHash"]="26b585f13e96c6f28f20630140abb27a37aa4d1f204ce30da8c87278c7757f5d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2150",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zenn promised extraordinary favors in exchange for nightsaber fangs, owl feathers and spider silk for his private reagents.",["title"]="Zenn Foulhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"488:description:1-22","488:description:25-119","488:description:124-218","488:description:221-284","488:description:289-337","488:description:341-350","488:description:353-446","488:description:451-488","488:objective:1-121"},["minimumStage"]=2,["questID"]=488,["sourceHash"]="26b585f13e96c6f28f20630140abb27a37aa4d1f204ce30da8c87278c7757f5d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2150",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He asked that the gathering remain secret between himself and the new adventurer he recruited.",["title"]="Zenn Foulhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"489:description:1-64","489:description:66-101","489:description:103-190","489:description:195-291","489:description:296-345","489:description:347-401","489:description:403-431","489:description:436-457","489:description:459-508","489:objective:1-71"},["minimumStage"]=2,["questID"]=489,["sourceHash"]="9b20884085ad9aaaa522c7e528c0b791d8985f6cd96519702e7e2749e1b32032"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2083",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Syral spoke for the Council of the Forest in demanding restitution from those who aided Zenn Foulhoof.",["title"]="Syral Bladeleaf"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"489:description:1-64","489:description:66-101","489:description:103-190","489:description:195-291","489:description:296-345","489:description:347-401","489:description:403-431","489:description:436-457","489:description:459-508","489:objective:1-71"},["minimumStage"]=2,["questID"]=489,["sourceHash"]="9b20884085ad9aaaa522c7e528c0b791d8985f6cd96519702e7e2749e1b32032"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2083",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her answer used corrupted Fel Cones, seeds billowing green smoke that Zenn might mistake for a harmless snack.",["title"]="Syral Bladeleaf"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"494:description:1-32","494:description:37-105","494:description:108-143","494:description:146-231","494:description:234-300","494:description:305-348","494:description:353-417","494:description:420-430","494:description:433-488","494:objective:1-88"},["minimumStage"]=2,["questID"]=494,["sourceHash"]="aa31a65bd1c3af92980751cd01daf398fc1312e2f8c9c8af51bda31d2f270c60"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2214",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lesh conducted covert reconnaissance of Hillsbrad and sent an urgent coded message to Darthalia in Tarren Mill.",["title"]="Deathstalker Lesh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"495:description:1-98","495:description:100-172","495:description:174-228","495:description:233-297","495:description:299-392","495:description:397-506","495:objective:1-61"},["minimumStage"]=2,["questID"]=495,["sourceHash"]="aa0427d172b67081b5f6d905b4c80e8a511c6c9eb4847ce55e1351b317f6813d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2227",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mug’Thol’s use of the Crown of Will broke the possession binding him to Sylvanas, turning its recovery mission into a problem for Sharlindra.",["title"]="Sharlindra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"495:description:1-98","495:description:100-172","495:description:174-228","495:description:233-297","495:description:299-392","495:description:397-506","495:objective:1-61"},["minimumStage"]=2,["questID"]=495,["sourceHash"]="aa0427d172b67081b5f6d905b4c80e8a511c6c9eb4847ce55e1351b317f6813d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2227",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She referred the response to Melisara, her lieutenant in Tarren Mill.",["title"]="Sharlindra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"498:description:1-134","498:description:139-244","498:description:246-313","498:description:315-370","498:description:375-428","498:description:430-498","498:objective:1-78"},["minimumStage"]=2,["questID"]=498,["sourceHash"]="2811d557acd056545ecc6d3cfc8ede8fe612b64533fe4b83c18fe1df8e2d9f24"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2229",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krusk escaped a Syndicate ambush at Durnholde while Drull and Tog’thar remained prisoners.",["title"]="Krusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"498:description:1-134","498:description:139-244","498:description:246-313","498:description:315-370","498:description:375-428","498:description:430-498","498:objective:1-78"},["minimumStage"]=2,["questID"]=498,["sourceHash"]="2811d557acd056545ecc6d3cfc8ede8fe612b64533fe4b83c18fe1df8e2d9f24"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2229",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Warchief had sent his party to investigate the Syndicate and recover an object; he now needed help rescuing his captured companions.",["title"]="Krusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"506:description:1-64","506:description:66-133","506:description:135-285","506:description:290-367","506:description:369-421","506:description:426-495","506:objective:1-67"},["minimumStage"]=2,["questID"]=506,["sourceHash"]="39e672ae61ceb220eeeb796e202c2fda501957da2b8901a5fd0f79cd9a579671"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2316",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gol’dir reported Aliden Perenolde’s plan to enslave opposing orcs in the tradition of his father and Blackmoore.",["title"]="Gol'dir"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"506:description:1-64","506:description:66-133","506:description:135-285","506:description:290-367","506:description:369-421","506:description:426-495","506:objective:1-67"},["minimumStage"]=2,["questID"]=506,["sourceHash"]="39e672ae61ceb220eeeb796e202c2fda501957da2b8901a5fd0f79cd9a579671"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2316",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He saw the pendant sought by the Warchief around Elysa’s neck when Aliden visited with her.",["title"]="Gol'dir"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"540:description:1-133","540:description:136-165","540:description:170-237","540:description:240-348","540:description:351-484","540:objective:1-114"},["minimumStage"]=2,["questID"]=540,["sourceHash"]="946c2d728f425a6deef1259f4e99f70fd4fa9bcca379f1bda3f7eb747e70c084"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2277",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dibbs sought books from ogre-occupied Alterac, particularly The Arm of Gri’lek and its ancient troll lore.",["title"]="Loremaster Dibbs"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"543:description:1-129","543:description:132-235","543:description:240-429","543:description:434-476","543:objective:1-62"},["minimumStage"]=2,["questID"]=543,["sourceHash"]="b412cd89ed40eecd103cd7befcdbb7186fb854d26aa48ac8fc57d73745a30e69"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2285",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ridgewell described the Perenolde Tiara as an emerald-set Alterac heirloom, reportedly made by Ironforge jewelers.",["title"]="Count Remington Ridgewell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"543:description:1-129","543:description:132-235","543:description:240-429","543:description:434-476","543:objective:1-62"},["minimumStage"]=2,["questID"]=543,["sourceHash"]="b412cd89ed40eecd103cd7befcdbb7186fb854d26aa48ac8fc57d73745a30e69"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2285",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He pursued rumors that Grel’borg the Miser had found the lost tiara and still wandered Alterac’s ruins seeking treasure.",["title"]="Count Remington Ridgewell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"544:description:1-65","544:description:68-126","544:description:129-220","544:description:225-341","544:description:344-388","544:description:393-503","544:objective:1-93"},["minimumStage"]=2,["questID"]=544,["sourceHash"]="8828acb59e0e39cb4074505175a777b812830fd5882a107ba0a7689f34da2e33"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2410",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wordeen came to Tarren Mill to research, then was diverted to the recovery of four artifacts stolen from the Undercity.",["title"]="Magus Wordeen Voidglare"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"544:description:1-65","544:description:68-126","544:description:129-220","544:description:225-341","544:description:344-388","544:description:393-503","544:objective:1-93"},["minimumStage"]=2,["questID"]=544,["sourceHash"]="8828acb59e0e39cb4074505175a777b812830fd5882a107ba0a7689f34da2e33"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2410",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He accused four Forsaken fugitives of the theft and said Dalaran’s wizards had quarantined them at Lordamere Internment Camp.",["title"]="Magus Wordeen Voidglare"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"546:description:1-77","546:description:80-95","546:description:104-255","546:description:260-317","546:description:320-356","546:description:359-410","546:description:413-504","546:objective:1-64"},["minimumStage"]=2,["questID"]=546,["sourceHash"]="0f7a9b9ec9fe330a9af7e5cc1d63531473efc60d572cb9c7a7bddbbeb51179b8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Samsa resented standing guard while others fought in Hillsbrad and spoke with relish of terrorizing its human inhabitants.",["title"]="Deathguard Samsa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"546:description:1-77","546:description:80-95","546:description:104-255","546:description:260-317","546:description:320-356","546:description:359-410","546:description:413-504","546:objective:1-64"},["minimumStage"]=2,["questID"]=546,["sourceHash"]="0f7a9b9ec9fe330a9af7e5cc1d63531473efc60d572cb9c7a7bddbbeb51179b8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He collected human skulls and offered a reward for thirty gathered during the campaign.",["title"]="Deathguard Samsa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"600:description:1-136","600:description:139-163","600:description:168-236","600:description:239-374","600:description:379-461","600:description:466-471","600:description:479-511","600:objective:1-63"},["minimumStage"]=2,["questID"]=600,["sourceHash"]="87f821a4791ba01f24c2dbea04fa5c04a05332aec2ac3c2f263103b7a3ae111b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2498",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Crank resented the Venture Company’s Stranglethorn operations, claiming they denied independent goblins an honest profit.",["title"]="Crank Fizzlebub"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"600:description:1-136","600:description:139-163","600:description:168-236","600:description:239-374","600:description:379-461","600:description:466-471","600:description:479-511","600:objective:1-63"},["minimumStage"]=2,["questID"]=600,["sourceHash"]="87f821a4791ba01f24c2dbea04fa5c04a05332aec2ac3c2f263103b7a3ae111b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2498",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Singing Crystals seized from the miners working the hills around basilisk-infested Crystalvein Mine.",["title"]="Crank Fizzlebub"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"601:description:1-123","601:description:125-229","601:description:234-283","601:description:285-382","601:description:384-448","601:objective:1-66"},["minimumStage"]=2,["questID"]=601,["sourceHash"]="70efcfa2a4babe84f7a2ca5416e323b531b155a2fbf0fae61680315eebb2c069"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2496",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Revilgaz attributed the island’s water elementals to Gazban and the Stone of the Tides, whose bearer faded in and out of existence.",["title"]="Baron Revilgaz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"601:description:1-123","601:description:125-229","601:description:234-283","601:description:285-382","601:description:384-448","601:objective:1-66"},["minimumStage"]=2,["questID"]=601,["sourceHash"]="70efcfa2a4babe84f7a2ca5416e323b531b155a2fbf0fae61680315eebb2c069"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2496",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought elemental bracers for a Dalaran mage to analyze, hoping the magical residue might reveal a way around the curse.",["title"]="Baron Revilgaz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"603:description:1-95","603:description:97-118","603:description:120-171","603:description:176-252","603:description:254-272","603:description:274-288","603:description:293-447","603:objective:1-29"},["minimumStage"]=2,["questID"]=603,["sourceHash"]="6cdd8041611608e6b9a26b0c67c32d990b595caf5cfaf59fc49d577738b68781"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2543",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ansirem had given an ancient troll dagger to his daughter Catelyn, who left for Booty Bay to become a pirate.",["title"]="Archmage Ansirem Runeweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"603:description:1-95","603:description:97-118","603:description:120-171","603:description:176-252","603:description:254-272","603:description:274-288","603:description:293-447","603:objective:1-29"},["minimumStage"]=2,["questID"]=603,["sourceHash"]="6cdd8041611608e6b9a26b0c67c32d990b595caf5cfaf59fc49d577738b68781"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2543",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He believed the dagger could overpower the altar amplifying the Stone of the Tides, but recovering his gift required finding Catelyn.",["title"]="Archmage Ansirem Runeweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"606:description:1-83","606:description:86-126","606:description:128-157","606:description:162-211","606:description:214-272","606:description:275-313","606:description:318-365","606:description:368-425","606:description:428-493","606:objective:1-58"},["minimumStage"]=2,["questID"]=606,["sourceHash"]="3e950ba2d86cfd0df5cee6efdf58cffaeb51ec83164d4c04e881aaa49bc48bab"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2501",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="MacKinley demanded payment of gambling debts, beginning with Shaky Phillipe at the docks.",["title"]="\"Sea Wolf\" MacKinley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"606:description:1-83","606:description:86-126","606:description:128-157","606:description:162-211","606:description:214-272","606:description:275-313","606:description:318-365","606:description:368-425","606:description:428-493","606:objective:1-58"},["minimumStage"]=2,["questID"]=606,["sourceHash"]="3e950ba2d86cfd0df5cee6efdf58cffaeb51ec83164d4c04e881aaa49bc48bab"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2501",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He planned to frighten the debtor with gorilla remains passed off as something more sinister.",["title"]="\"Sea Wolf\" MacKinley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"608:description:1-28","608:description:31-118","608:description:123-179","608:description:182-266","608:description:271-346","608:description:349-464","608:description:467-502","608:objective:1-115"},["minimumStage"]=2,["questID"]=608,["sourceHash"]="875baa463318223cd35ae31470db94075e45069c13841becce0783bea75c16e1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2487",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Seahorn wanted Firallon and the Bloodsail leaders struck at their landing place before they could carry out the attack on Booty Bay.",["title"]="Fleet Master Seahorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"608:description:1-28","608:description:31-118","608:description:123-179","608:description:182-266","608:description:271-346","608:description:349-464","608:description:467-502","608:objective:1-115"},["minimumStage"]=2,["questID"]=608,["sourceHash"]="875baa463318223cd35ae31470db94075e45069c13841becce0783bea75c16e1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2487",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With the enemy’s plan known, he favored a small adventuring party over committing the whole fleet.",["title"]="Fleet Master Seahorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"610:description:1-19","610:description:21-86","610:description:91-284","610:description:289-396","610:description:398-462","610:objective:1-46"},["minimumStage"]=2,["questID"]=610,["sourceHash"]="d4c77f34bb6ff8396764e90e11e0a0c7b7a5c85ccac2754133ced7e9ac65d17a"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2542",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Catelyn left her father’s scholarly world because she wanted more than musty books and the company of stuffy mages.",["title"]="Catelyn the Blade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"610:description:1-19","610:description:21-86","610:description:91-284","610:description:289-396","610:description:398-462","610:objective:1-46"},["minimumStage"]=2,["questID"]=610,["sourceHash"]="d4c77f34bb6ff8396764e90e11e0a0c7b7a5c85ccac2754133ced7e9ac65d17a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2542",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The dagger Ansirem needed was no longer hers to hand over: Pretty Boy Duncan of the Bloodsail Buccaneers had it.",["title"]="Catelyn the Blade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"623:description:1-73","623:description:75-201","623:description:206-342","623:description:347-366","623:description:368-413","623:description:415-498","623:objective:1-62"},["minimumStage"]=2,["questID"]=623,["sourceHash"]="381aedd4059c5698b643fdbd9afbcebad48a19180413b1eb3f99c354ae463e12"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2494",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bloads arranged shipments for Groy and his clients, using couriers when his own voyage to Theramore was still a week away.",["title"]="Privateer Bloads"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"623:description:1-73","623:description:75-201","623:description:206-342","623:description:347-366","623:description:368-413","623:description:415-498","623:objective:1-62"},["minimumStage"]=2,["questID"]=623,["sourceHash"]="381aedd4059c5698b643fdbd9afbcebad48a19180413b1eb3f99c354ae463e12"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2494",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned that Theramore’s welcome depended on who arrived, even while recommending the trip through Dustwallow.",["title"]="Privateer Bloads"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"629:description:1-118","629:description:121-232","629:description:237-341","629:description:344-494","629:objective:1-61"},["minimumStage"]=2,["questID"]=629,["sourceHash"]="2e165d64a12e0b296a3537176212d9f119ca3911e244f6e41cc8624b5ffa0dcc"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2519",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kin’weelay wanted a fragment of the Vile Reef’s Gri’lek tablet preserved in the Darkspear’s new home in Orgrimmar.",["title"]="Kin'weelay"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"629:description:1-118","629:description:121-232","629:description:237-341","629:description:344-494","629:objective:1-61"},["minimumStage"]=2,["questID"]=629,["sourceHash"]="2e165d64a12e0b296a3537176212d9f119ca3911e244f6e41cc8624b5ffa0dcc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2519",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He called the hero’s tale sacred to his tribe and explained that the complete tablet was too large to move.",["title"]="Kin'weelay"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"639:description:1-133","639:description:135-213","639:description:218-294","639:description:299-418","639:description:423-506","639:objective:1-47"},["minimumStage"]=2,["questID"]=639,["sourceHash"]="24bcf6f293f2c9d7f3fca5f6c484058058e05df52f13e0d0cc4158f64836602e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2703",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zengu recalled Ignaeus Trollbane and the sword Trol’kalar as formidable enemies of the ancient trolls.",["title"]="Zengu"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"639:description:1-133","639:description:135-213","639:description:218-294","639:description:299-418","639:description:423-506","639:objective:1-47"},["minimumStage"]=2,["questID"]=639,["sourceHash"]="24bcf6f293f2c9d7f3fca5f6c484058058e05df52f13e0d0cc4158f64836602e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2703",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With Stromgarde weakened, he sought the scattered protective sigils to gain access to that old weapon.",["title"]="Zengu"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"647:description:1-48","647:description:51-124","647:description:129-162","647:description:165-247","647:description:252-275","647:description:277-376","647:description:381-434","647:description:437-474","647:description:477-486","647:objective:1-62"},["minimumStage"]=2,["questID"]=647,["sourceHash"]="988a4090c5324d1591e042258c4cd494ffbe7373187050abc90d7989cb28edd0"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2696",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Foggy had drunk himself unconscious during his watch and feared Longbraid finding out.",["title"]="Foggy MacKreel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"647:description:1-48","647:description:51-124","647:description:129-162","647:description:165-247","647:description:252-275","647:description:277-376","647:description:381-434","647:description:437-474","647:description:477-486","647:objective:1-62"},["minimumStage"]=2,["questID"]=647,["sourceHash"]="988a4090c5324d1591e042258c4cd494ffbe7373187050abc90d7989cb28edd0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2696",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A promised moonshine delivery to Brewmeister Bilger was nearly overdue, making a fast courier his immediate concern.",["title"]="Foggy MacKreel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"648:description:1-53","648:description:58-151","648:description:154-234","648:description:237-326","648:description:329-400","648:description:405-473","648:description:476-503","648:objective:1-88"},["minimumStage"]=2,["questID"]=648,["sourceHash"]="1c1c7b37a7cf4f93fab9e11f814625cd48732e2a6614e290179b3b72027200e3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7784",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="OOX-17/TN needed open, safe ground for a lengthy takeoff. Oglethorpe sought time to restore its built-in cloaking while it was escorted to Steamwheedle.",["title"]="Homing Robot OOX-17/TN"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"649:description:1-117","649:description:120-126","649:description:131-154","649:description:159-257","649:description:260-303","649:description:306-447","649:description:450-498","649:objective:1-37"},["minimumStage"]=2,["questID"]=649,["sourceHash"]="42412ea23d0cc9cfd0ae98057fa7e8feb842ed33d51d78b153eafea4fb7919ce"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6986",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dran sought rare Hinterlands Honey Ripple from an abandoned Horde outpost, demanding a packaged case and extra bottles for his private collection.",["title"]="Dran Droffers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"649:description:1-117","649:description:120-126","649:description:131-154","649:description:159-257","649:description:260-303","649:description:306-447","649:description:450-498","649:objective:1-37"},["minimumStage"]=2,["questID"]=649,["sourceHash"]="42412ea23d0cc9cfd0ae98057fa7e8feb842ed33d51d78b153eafea4fb7919ce"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6986",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He relied on his son Malton’s contacts to locate the old stock and arrange its recovery.",["title"]="Dran Droffers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"650:description:1-57","650:description:60-118","650:description:121-190","650:description:193-271","650:description:273-304","650:description:307-380","650:description:385-484","650:description:487-495","650:objective:1-69"},["minimumStage"]=2,["questID"]=650,["sourceHash"]="2877ed3a8a3c38a7ee40e3333db98a51edb0e8e3985fb5e7fc1b188852e46ec6"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6987",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Malton recommended Gilveradin Sunchaser, praising the elf’s ability to identify wine by smell and package the ripple.",["title"]="Malton Droffers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"650:description:1-57","650:description:60-118","650:description:121-190","650:description:193-271","650:description:273-304","650:description:307-380","650:description:385-484","650:description:487-495","650:objective:1-69"},["minimumStage"]=2,["questID"]=650,["sourceHash"]="2877ed3a8a3c38a7ee40e3333db98a51edb0e8e3985fb5e7fc1b188852e46ec6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6987",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He expected the recovery to satisfy both his father’s order and Gilveradin’s own appetite for the drink.",["title"]="Malton Droffers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"656:description:1-53","656:description:56-141","656:description:144-273","656:description:278-293","656:description:298-379","656:description:382-466","656:description:471-509","656:objective:1-55","656:objective:60-127"},["minimumStage"]=2,["questID"]=656,["sourceHash"]="290547ae18787557dd755acc67de4e0d88475744256d71b2e3f3a35e7fff8fbe"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2785",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theldurin wanted Myzrael defeated and rebound before her growing strength let her challenge the giants who had chained her.",["title"]="Theldurin the Lost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"656:description:1-53","656:description:56-141","656:description:144-273","656:description:278-293","656:description:298-379","656:description:382-466","656:description:471-509","656:objective:1-55","656:objective:60-127"},["minimumStage"]=2,["questID"]=656,["sourceHash"]="290547ae18787557dd755acc67de4e0d88475744256d71b2e3f3a35e7fff8fbe"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2785",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His plan called for summoning her at the shards and using her Eldritch Shackles to restore the binding.",["title"]="Theldurin the Lost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"657:description:1-39","657:description:44-63","657:description:65-148","657:description:150-242","657:description:247-348","657:description:350-504","657:objective:1-18"},["minimumStage"]=2,["questID"]=657,["sourceHash"]="096103cfa4cf4176d2cfb34e3d0f02f568666af9748b0c2b7306b72b5d0b2360"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2712",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="An orc encounter left Quae too injured to accompany Kinelory into Go’Shek Farm.",["title"]="Quae"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"657:description:1-39","657:description:44-63","657:description:65-148","657:description:150-242","657:description:247-348","657:description:350-504","657:objective:1-18"},["minimumStage"]=2,["questID"]=657,["sourceHash"]="096103cfa4cf4176d2cfb34e3d0f02f568666af9748b0c2b7306b72b5d0b2360"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2712",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jorell’s papers suggested deadly experimentation, so she wanted Kinelory protected while the remaining research was stolen.",["title"]="Quae"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"659:description:1-23","659:description:25-96","659:description:101-258","659:description:263-342","659:description:347-471","659:description:473-489","659:description:491-507","659:objective:1-69"},["minimumStage"]=2,["questID"]=659,["sourceHash"]="921e5e8efbd1fc39e23d8cf1836e91dd9b7aceee6a653790eb0621e496a9f824"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2711",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Phin led a small band investigating disturbing changes around Hillsbrad and Arathi.",["title"]="Phin Odelic"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"659:description:1-23","659:description:25-96","659:description:101-258","659:description:263-342","659:description:347-471","659:description:473-489","659:description:491-507","659:objective:1-69"},["minimumStage"]=2,["questID"]=659,["sourceHash"]="921e5e8efbd1fc39e23d8cf1836e91dd9b7aceee6a653790eb0621e496a9f824"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2711",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His cousin’s dog Stanley had grown unnaturally large and violent. Suspecting undead involvement, Phin sought evidence and news of missing companions Quae and Kinelory.",["title"]="Phin Odelic"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"662:description:1-36","662:description:39-96","662:description:99-213","662:description:216-246","662:description:251-295","662:description:297-328","662:description:331-372","662:description:377-447","662:description:450-504","662:objective:1-114"},["minimumStage"]=2,["questID"]=662,["sourceHash"]="996ea66f3994b1f1e032660223e678e68262bf987f2988e3e68ed09c2c9c766f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2767",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nilzlix recalled O’Breen leading three ships into the cove. The Harbinger docked, but the Maiden’s Folly and Spirit of Silverpine struck a reef structure as the tide fell and sank.",["title"]="First Mate Nilzlix"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"662:description:1-36","662:description:39-96","662:description:99-213","662:description:216-246","662:description:251-295","662:description:297-328","662:description:331-372","662:description:377-447","662:description:450-504","662:objective:1-114"},["minimumStage"]=2,["questID"]=662,["sourceHash"]="996ea66f3994b1f1e032660223e678e68262bf987f2988e3e68ed09c2c9c766f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2767",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the lost ships’ logs and charts salvaged before outsiders could obtain their information.",["title"]="First Mate Nilzlix"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"676:description:1-12","676:description:14-25","676:description:27-59","676:description:61-96","676:description:98-114","676:description:119-166","676:description:168-223","676:description:228-297","676:description:299-384","676:description:386-474","676:objective:1-120"},["minimumStage"]=2,["questID"]=676,["sourceHash"]="3be3498770431850f8ab95ae8fa4ac33c32dc88d3f5f72cf43b732d2bdf85eae"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2770",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tallow sought help for beleaguered Hammerfall but first demanded proof against Boulderfist ogres northeast of Stromgarde.",["title"]="Tallow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"676:description:1-12","676:description:14-25","676:description:27-59","676:description:61-96","676:description:98-114","676:description:119-166","676:description:168-223","676:description:228-297","676:description:299-384","676:description:386-474","676:objective:1-120"},["minimumStage"]=2,["questID"]=676,["sourceHash"]="3be3498770431850f8ab95ae8fa4ac33c32dc88d3f5f72cf43b732d2bdf85eae"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2770",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Those who passed his test were to report to Drum Fel at the outpost.",["title"]="Tallow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"680:description:1-83","680:description:88-242","680:description:247-367","680:description:372-499","680:objective:1-72"},["minimumStage"]=2,["questID"]=680,["sourceHash"]="3cf4cf4497e59b2cb94b37b3c241492c1ec4e0b2f2dba54a8425fbce59a1a254"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2772",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Korin concealed Or’Kalar’s whereabouts from her husband Drum Fel, fearing he would rush into the revenge trap she foresaw.",["title"]="Korin Fel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"680:description:1-83","680:description:88-242","680:description:247-367","680:description:372-499","680:objective:1-72"},["minimumStage"]=2,["questID"]=680,["sourceHash"]="3cf4cf4497e59b2cb94b37b3c241492c1ec4e0b2f2dba54a8425fbce59a1a254"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2772",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She sought an outside fighter to stop the ogre, whose hatred followed a defeat at her husband’s hands years earlier.",["title"]="Korin Fel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"681:description:1-56","681:description:59-183","681:description:188-232","681:description:237-363","681:description:368-425","681:description:428-510","681:objective:1-57","681:objective:62-102"},["minimumStage"]=2,["questID"]=681,["sourceHash"]="4388382be54d139a78a57d94dbb39d4bcae735669bb4f0b24e35748bd7e475da"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2700",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nials described Stromgarde divided among its militia, ogres and Syndicate, with her dwindling troops trapped in a bloody stalemate.",["title"]="Captain Nials"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"681:description:1-56","681:description:59-183","681:description:188-232","681:description:237-363","681:description:368-425","681:description:428-510","681:objective:1-57","681:objective:62-102"},["minimumStage"]=2,["questID"]=681,["sourceHash"]="4388382be54d139a78a57d94dbb39d4bcae735669bb4f0b24e35748bd7e475da"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2700",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted Northfold Manor’s Syndicate weakened so supplies from Southshore could reach the defenders.",["title"]="Captain Nials"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"686:description:1-38","686:description:40-137","686:description:139-256","686:description:261-349","686:description:354-443","686:description:448-472","686:description:474-510","686:objective:1-70"},["minimumStage"]=2,["questID"]=686,["sourceHash"]="649ec407f53157887d3dc2e45cf012e4a90d4a27967dfe3437c3e89ac1543d57"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2784",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sully Balloo’s death weighed on Magni alongside the losses of other dwarves fighting for the Alliance.",["title"]="King Magni Bronzebeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"686:description:1-38","686:description:40-137","686:description:139-256","686:description:261-349","686:description:354-443","686:description:448-472","686:description:474-510","686:objective:1-70"},["minimumStage"]=2,["questID"]=686,["sourceHash"]="649ec407f53157887d3dc2e45cf012e4a90d4a27967dfe3437c3e89ac1543d57"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2784",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He commissioned Marblesten to build a memorial, offering Mrs. Balloo a lasting tribute where he could not restore her husband.",["title"]="King Magni Bronzebeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"689:description:1-86","689:description:89-151","689:description:156-196","689:description:201-266","689:description:268-362","689:description:364-437","689:objective:1-70"},["minimumStage"]=2,["questID"]=689,["sourceHash"]="ce883697c253c8a06d5767ebba77672dabe8855c2748a06b37cc7a8bedf7428d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2790",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marblesten undertook the king’s memorial to Sully Balloo, seeking fine Alterac granite for an enduring monument.",["title"]="Grand Mason Marblesten"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"689:description:1-86","689:description:89-151","689:description:156-196","689:description:201-266","689:description:268-362","689:description:364-437","689:objective:1-70"},["minimumStage"]=2,["questID"]=689,["sourceHash"]="ce883697c253c8a06d5767ebba77672dabe8855c2748a06b37cc7a8bedf7428d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2790",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the stone gathering to Darrow Hill in Hillsbrad while lamenting the cost of war.",["title"]="Grand Mason Marblesten"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"690:description:1-14","690:description:16-106","690:description:111-283","690:description:288-379","690:description:381-458","690:description:460-478","690:objective:1-54"},["minimumStage"]=2,["questID"]=690,["sourceHash"]="8d876e04c5520008776457a3899eea30e1356e502d7cf10a6ea5300c459bf02d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2708",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Trelane had been Malin’s teacher before the siege forced the elder archmage out of Stromgarde.",["title"]="Archmage Malin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"690:description:1-14","690:description:16-106","690:description:111-283","690:description:288-379","690:description:381-458","690:description:460-478","690:objective:1-54"},["minimumStage"]=2,["questID"]=690,["sourceHash"]="8d876e04c5520008776457a3899eea30e1356e502d7cf10a6ea5300c459bf02d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2708",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Malin sought help for his agents recovering possessions left behind after Trelane failed to hold the Tower of Arathor.",["title"]="Archmage Malin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"698:description:1-216","698:description:221-331","698:description:333-364","698:description:369-491","698:objective:1-66"},["minimumStage"]=2,["questID"]=698,["sourceHash"]="a049c4ce1e13264c0c90db3df491fa353c5a5c2e0184eb0f9e8d9767c84ccccf"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5591",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dar assembled supplies for the coastal outpost east of Stonard.",["title"]="Dar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"698:description:1-216","698:description:221-331","698:description:333-364","698:description:369-491","698:objective:1-66"},["minimumStage"]=2,["questID"]=698,["sourceHash"]="a049c4ce1e13264c0c90db3df491fa353c5a5c2e0184eb0f9e8d9767c84ccccf"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5591",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted to ease Tok’Kar’s burden of guard duty and cooking by sending the soldiers mature sawtooth meat.",["title"]="Dar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"699:description:1-149","699:description:151-242","699:description:247-320","699:description:322-453","699:objective:1-66"},["minimumStage"]=2,["questID"]=699,["sourceHash"]="6fd78bb5ed0180820376f4853051b25b01a2d1d18d2dbf51a206374ff8fb906f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5592",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tok’Kar’s coastal post watched the murlocs, guarding Stonard or warning it if a force proved too large.",["title"]="Tok'Kar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"699:description:1-149","699:description:151-242","699:description:247-320","699:description:322-453","699:objective:1-66"},["minimumStage"]=2,["questID"]=699,["sourceHash"]="6fd78bb5ed0180820376f4853051b25b01a2d1d18d2dbf51a206374ff8fb906f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5592",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His people prepared sawtooth claws as weapons and offered one in thanks for meat and company at their lonely station.",["title"]="Tok'Kar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"705:description:1-81","705:description:84-127","705:description:130-161","705:description:166-199","705:description:202-236","705:description:239-311","705:description:314-361","705:description:366-404","705:description:407-467","705:description:472-507","705:objective:1-50"},["minimumStage"]=2,["questID"]=705,["sourceHash"]="e752b743577e6bb07649a956d1c48b6547773df81568c07deb9b8e71155119df"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2817",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rigglefuzz used flash bombs to frighten away the Badlands’ predators and scavengers.",["title"]="Rigglefuzz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"705:description:1-81","705:description:84-127","705:description:130-161","705:description:166-199","705:description:202-236","705:description:239-311","705:description:314-361","705:description:366-404","705:description:407-467","705:description:472-507","705:objective:1-50"},["minimumStage"]=2,["questID"]=705,["sourceHash"]="e752b743577e6bb07649a956d1c48b6547773df81568c07deb9b8e71155119df"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2817",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Running short of crushed blue pearl powder, he sought pearls from the Vile Reef’s clams to replenish the bombs.",["title"]="Rigglefuzz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"706:description:1-114","706:description:116-200","706:description:205-354","706:description:356-411","706:description:413-494","706:objective:1-49"},["minimumStage"]=2,["questID"]=706,["sourceHash"]="202b1dc1b5b73bf3e0541fe62dc4c5a0cd00270864a73cb9a31b6dfcb7523883"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2860",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sigrun learned fiery weapon enchantment as Feranor Steeltoe’s apprentice.",["title"]="Sigrun Ironhew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"706:description:1-114","706:description:116-200","706:description:205-354","706:description:356-411","706:description:413-494","706:objective:1-49"},["minimumStage"]=2,["questID"]=706,["sourceHash"]="202b1dc1b5b73bf3e0541fe62dc4c5a0cd00270864a73cb9a31b6dfcb7523883"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2860",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The technique required blood from a rare, still-beating black drake whelp’s heart, which he sought from Lethlor Ravine while awaiting Ironforge’s word.",["title"]="Sigrun Ironhew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"715:description:1-94","715:description:96-209","715:description:214-321","715:description:326-423","715:description:425-496","715:objective:1-95"},["minimumStage"]=2,["questID"]=715,["sourceHash"]="de664236feabfe4a63f879f2a43fd77ce3698252abf98c88c019da9b77130357"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2920",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lucien developed potions while learning from Lotwil’s Badlands research.",["title"]="Lucien Tosselwrench"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"715:description:1-94","715:description:96-209","715:description:214-321","715:description:326-423","715:description:425-496","715:objective:1-95"},["minimumStage"]=2,["questID"]=715,["sourceHash"]="de664236feabfe4a63f879f2a43fd77ce3698252abf98c88c019da9b77130357"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2920",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anticipating trouble from Lotwil’s experiment, he sought healing and invisibility potions in exchange for his own developing recipe.",["title"]="Lucien Tosselwrench"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"717:description:1-105","717:description:107-260","717:description:265-372","717:description:374-446","717:description:457-493","717:objective:1-107","717:objective:112-187","717:objective:192-292"},["minimumStage"]=2,["questID"]=717,["sourceHash"]="1d403236a428e8f3d95dc1d9bad3b05ba52c671166adad959edafb332dd800e6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2888",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Garek feared Blacklash and Hematus would not remain securely imprisoned after black dragons settled in Lethlor and ogres stole the Sign of the Earth.",["title"]="Garek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"717:description:1-105","717:description:107-260","717:description:265-372","717:description:374-446","717:description:457-493","717:objective:1-107","717:objective:112-187","717:objective:192-292"},["minimumStage"]=2,["questID"]=717,["sourceHash"]="1d403236a428e8f3d95dc1d9bad3b05ba52c671166adad959edafb332dd800e6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2888",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Three runestones sustained the prison; the Sign could retrieve them and let a hunter deliberately break the seal for a final confrontation.",["title"]="Garek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"729:description:1-118","729:description:120-194","729:description:199-229","729:description:237-269","729:description:274-318","729:description:320-385","729:description:387-419","729:description:421-453","729:description:458-511","729:objective:1-47"},["minimumStage"]=2,["questID"]=729,["sourceHash"]="7ecfde41549bee21251229f58ef877c8c0227fd728f4fdad992724f8bbe941c9"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2913",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Greywhisker assigned Hollee to the renowned Remtravel, whose discoveries had been celebrated at her Ironforge academy.",["title"]="Archaeologist Hollee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"729:description:1-118","729:description:120-194","729:description:199-229","729:description:237-269","729:description:274-318","729:description:320-385","729:description:387-419","729:description:421-453","729:description:458-511","729:objective:1-47"},["minimumStage"]=2,["questID"]=729,["sourceHash"]="7ecfde41549bee21251229f58ef877c8c0227fd728f4fdad992724f8bbe941c9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2913",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Golems overwhelmed their newly uncovered site, but Remtravel seemed oblivious. Hollee escaped to Auberdine to seek help for him.",["title"]="Archaeologist Hollee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"629:description:1-118","629:description:121-232","629:description:237-341","629:description:344-494","629:objective:1-61"},["minimumStage"]=2,["questID"]=629,["sourceHash"]="2e165d64a12e0b296a3537176212d9f119ca3911e244f6e41cc8624b5ffa0dcc"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-104",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kin’weelay remembered an old troll city sinking beneath the Savage Coast after a great upheaval of the earth.",["title"]="The Vile Reef"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"629:description:1-118","629:description:121-232","629:description:237-341","629:description:344-494","629:objective:1-61"},["minimumStage"]=2,["questID"]=629,["sourceHash"]="2e165d64a12e0b296a3537176212d9f119ca3911e244f6e41cc8624b5ffa0dcc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-104",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A tablet among the submerged ruins preserved Gri’lek’s sacred tale; Kin’weelay sought a fragment for the Darkspear’s home in Orgrimmar.",["title"]="The Vile Reef"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"705:description:1-81","705:description:84-127","705:description:130-161","705:description:166-199","705:description:202-236","705:description:239-311","705:description:314-361","705:description:366-404","705:description:407-467","705:description:472-507","705:objective:1-50"},["minimumStage"]=2,["questID"]=705,["sourceHash"]="e752b743577e6bb07649a956d1c48b6547773df81568c07deb9b8e71155119df"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-104",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Its clams supplied the blue pearls Rigglefuzz needed for the flash bombs protecting him from Badlands wildlife.",["title"]="The Vile Reef"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"600:description:1-136","600:description:139-163","600:description:168-236","600:description:239-374","600:description:379-461","600:description:466-471","600:description:479-511","600:objective:1-63"},["minimumStage"]=2,["questID"]=600,["sourceHash"]="87f821a4791ba01f24c2dbea04fa5c04a05332aec2ac3c2f263103b7a3ae111b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-310",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Basilisks kept Venture Company miners out of the mine itself, though they still extracted Singing Crystals from the surrounding hills.",["title"]="Crystalvein Mine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"681:description:1-56","681:description:59-183","681:description:188-232","681:description:237-363","681:description:368-425","681:description:428-510","681:objective:1-57","681:objective:62-102"},["minimumStage"]=2,["questID"]=681,["sourceHash"]="4388382be54d139a78a57d94dbb39d4bcae735669bb4f0b24e35748bd7e475da"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-313",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Syndicate control of the manor threatened supply trains from Southshore to Stromgarde’s dwindling defenders.",["title"]="Northfold Manor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"657:description:1-39","657:description:44-63","657:description:65-148","657:description:150-242","657:description:247-348","657:description:350-504","657:objective:1-18"},["minimumStage"]=2,["questID"]=657,["sourceHash"]="096103cfa4cf4176d2cfb34e3d0f02f568666af9748b0c2b7306b72b5d0b2360"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-314",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Quae’s recovered papers pointed toward Jorell’s deadly experiments at the farm and a plan to steal research not yet sent to Tarren Mill.",["title"]="Go'Shek Farm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"544:description:1-65","544:description:68-126","544:description:129-220","544:description:225-341","544:description:344-388","544:description:393-503","544:objective:1-93"},["minimumStage"]=2,["questID"]=544,["sourceHash"]="8828acb59e0e39cb4074505175a777b812830fd5882a107ba0a7689f34da2e33"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-278",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wordeen said Dalaran’s wizards quarantined four Forsaken fugitives here after their escape with stolen artifacts from the Undercity.",["title"]="Lordamere Internment Camp"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"455:description:1-56","455:description:59-100","455:description:103-237","455:description:242-325","455:description:328-372","455:description:377-456","455:description:461-486","455:description:489-500","455:objective:1-19","455:objective:24-70","455:objective:75-119"},["minimumStage"]=2,["questID"]=455,["sourceHash"]="524fc92094783dd80c19c622aad1bc8823e273df6cb37f75623f64b57af86ca8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-269",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Dragonmaw foothold threatened to cut Loch Modan off from Menethil Harbor, making the passage a critical supply route.",["title"]="Dun Algaz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"400:description:1-93","400:description:96-131","400:description:134-209","400:description:214-253","400:description:256-320","400:description:325-384","400:description:387-502","400:objective:1-48"},["minimumStage"]=2,["questID"]=400,["sourceHash"]="ce1f9910e687ce1d355645aa697b3dba0bf38af18e8f1d717c82caf75ce8272b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-189",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Beldin’s mechanic shop drew veteran siege-engine pilots northeast of Kharanos.",["title"]="Steelgrill's Depot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"310:description:1-58","310:description:61-122","310:description:125-171","310:description:176-220","310:description:223-343","310:description:346-403","310:description:408-484","310:objective:1-127"},["minimumStage"]=2,["questID"]=310,["sourceHash"]="306889ec3bd1e34e7af6fd93631edc0a2790320a1813217e2543fc7875263756"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2102",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marleth’s brewing rivalry reached the Kharanos cellar through a plan to replace Thunder Ale with her Barleybrew Scalder.",["title"]="Thunderbrew Distillery"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"470:description:1-82","470:description:84-105","470:description:110-158","470:description:160-194","470:description:196-243","470:description:248-312","470:description:317-384","470:description:386-438","470:description:440-457","470:objective:1-109"},["minimumStage"]=2,["questID"]=470,["sourceHash"]="cfe8dbd6b48d7215847de42327cb6f7206d7c5e93fbc391a98b8051962ced6ef"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-309",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sida’s weekly visit was interrupted by an ooze attack; her thrown bag vanished into one creature while she escaped.",["title"]="Ironbeard's Tomb"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"717:description:1-105","717:description:107-260","717:description:265-372","717:description:374-446","717:description:457-493","717:objective:1-107","717:objective:112-187","717:objective:192-292"},["minimumStage"]=2,["questID"]=717,["sourceHash"]="1d403236a428e8f3d95dc1d9bad3b05ba52c671166adad959edafb332dd800e6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-339",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Black dragons settling in the ravine and the theft of the Sign of the Earth undermined confidence in Blacklash and Hematus’s prison.",["title"]="Lethlor Ravine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"717:description:1-105","717:description:107-260","717:description:265-372","717:description:374-446","717:description:457-493","717:objective:1-107","717:objective:112-187","717:objective:192-292"},["minimumStage"]=2,["questID"]=717,["sourceHash"]="1d403236a428e8f3d95dc1d9bad3b05ba52c671166adad959edafb332dd800e6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-339",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Three runestones maintained the drakes’ seal and could be retrieved with the Sign to open it deliberately.",["title"]="Lethlor Ravine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"689:description:1-86","689:description:89-151","689:description:156-196","689:description:201-266","689:description:268-362","689:description:364-437","689:objective:1-70"},["minimumStage"]=2,["questID"]=689,["sourceHash"]="ce883697c253c8a06d5767ebba77672dabe8855c2748a06b37cc7a8bedf7428d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1056",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Its Alterac granite was the stone Marblesten selected for the king’s memorial to Sully Balloo.",["title"]="Darrow Hill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"690:description:1-14","690:description:16-106","690:description:111-283","690:description:288-379","690:description:381-458","690:description:460-478","690:objective:1-54"},["minimumStage"]=2,["questID"]=690,["sourceHash"]="8d876e04c5520008776457a3899eea30e1356e502d7cf10a6ea5300c459bf02d"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-325",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Trelane’s failed defense of the tower preceded his flight from besieged Stromgarde and the loss of belongings later sought by his former apprentice.",["title"]="The Tower of Arathor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"680:description:1-83","680:description:88-242","680:description:247-367","680:description:372-499","680:objective:1-72"},["minimumStage"]=2,["questID"]=680,["sourceHash"]="3cf4cf4497e59b2cb94b37b3c241492c1ec4e0b2f2dba54a8425fbce59a1a254"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-321",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Korin believed Or’Kalar’s attack concealed a personal trap for Drum Fel, stemming from the ogre’s earlier defeat.",["title"]="Hammerfall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"456:description:1-14","456:description:17-44","456:description:47-125","456:description:130-251","456:description:256-329","456:description:332-387","456:description:390-497","456:objective:1-88"},["minimumStage"]=2,["questID"]=456,["sourceHash"]="e3aeee2bdb83486a5040f96f823fdf7afc9c32a5e85151134d59a12ad6a30ef4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-188",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ilthalaine linked an overabundance of nightsabers and thistle boars to heavy spring rains and the forest’s limited food.",["title"]="Shadowglen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"459:description:1-55","459:description:58-122","459:description:125-210","459:description:215-287","459:description:290-384","459:description:391-507","459:objective:1-49"},["minimumStage"]=2,["questID"]=459,["sourceHash"]="a86e4c10edf18330954d833e5e759536635c3ba91cb55425c2b8a34a4563f57f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-188",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tarindrella suspected Fel Moss behind the local grell infestation and the Gnarlpine furbolgs’ disturbing change.",["title"]="Shadowglen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"699:description:1-149","699:description:151-242","699:description:247-320","699:description:322-453","699:objective:1-66"},["minimumStage"]=2,["questID"]=699,["sourceHash"]="6fd78bb5ed0180820376f4853051b25b01a2d1d18d2dbf51a206374ff8fb906f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="atlas-place-swamp-of-sorrows",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tok’Kar’s coastal watch guarded against murlocs and warned Stonard of threats too large for the outpost to stop.",["title"]="Swamp of Sorrows"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"681:description:1-56","681:description:59-183","681:description:188-232","681:description:237-363","681:description:368-425","681:description:428-510","681:objective:1-57","681:objective:62-102"},["minimumStage"]=2,["questID"]=681,["sourceHash"]="4388382be54d139a78a57d94dbb39d4bcae735669bb4f0b24e35748bd7e475da"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-324",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The militia, ogres and Syndicate divided the city, while the defenders’ shrinking numbers made support from Southshore increasingly important.",["title"]="Stromgarde Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"730:description:1-86","730:description:91-168","730:description:170-337","730:description:342-398","730:description:400-431","730:description:436-499","730:objective:1-70"},["minimumStage"]=2,["questID"]=730,["sourceHash"]="81c328d87f624ee59ece1de46fc85967ff7f4adc30c427ca79933bd3405dce85"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2912",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Greywhisker sought news of the archaeology crew he had sent to Darkshore after weeks without word.",["title"]="Chief Archaeologist Greywhisker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"730:description:1-86","730:description:91-168","730:description:170-337","730:description:342-398","730:description:400-431","730:description:436-499","730:objective:1-70"},["minimumStage"]=2,["questID"]=730,["sourceHash"]="81c328d87f624ee59ece1de46fc85967ff7f4adc30c427ca79933bd3405dce85"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2912",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He argued that discoveries in Khaz Modan revealed dangers reaching beyond any one kingdom, despite allies treating archaeology as a hobby.",["title"]="Chief Archaeologist Greywhisker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"731:description:1-18","731:description:20-55","731:description:57-71","731:description:76-104","731:description:106-137","731:description:139-167","731:description:169-193","731:description:195-282","731:description:287-353","731:description:355-368","731:description:370-426","731:description:431-451","731:objective:1-120"},["minimumStage"]=2,["questID"]=731,["sourceHash"]="f472a19b3b98092219d1659e3434dd69430e4546419dd02fb57f725f9442154b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2917",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Remtravel confused his visitor with Hollee and repeatedly called the fossil he sought a stone brush.",["title"]="Prospector Remtravel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"731:description:1-18","731:description:20-55","731:description:57-71","731:description:76-104","731:description:106-137","731:description:139-167","731:description:169-193","731:description:195-282","731:description:287-353","731:description:355-368","731:description:370-426","731:description:431-451","731:objective:1-120"},["minimumStage"]=2,["questID"]=731,["sourceHash"]="f472a19b3b98092219d1659e3434dd69430e4546419dd02fb57f725f9442154b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2917",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted a discovery and a written account to justify his work to the Explorers’ League in Darnassus.",["title"]="Prospector Remtravel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"736:description:1-25","736:description:28-71","736:description:74-140","736:description:145-169","736:description:174-204","736:description:207-250","736:description:255-322","736:description:327-356","736:description:359-445","736:objective:1-73"},["minimumStage"]=2,["questID"]=736,["sourceHash"]="3baa6c3ace54e6ebc8c8eda0b64db2354e4df1467098a649028a0c8b10c9b31e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2934",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bel’dugur offered Yagyin’s Digest in return for three items of power whose names he would write but not speak.",["title"]="Keeper Bel'dugur"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"736:description:1-25","736:description:28-71","736:description:74-140","736:description:145-169","736:description:174-204","736:description:207-250","736:description:255-322","736:description:327-356","736:description:359-445","736:objective:1-73"},["minimumStage"]=2,["questID"]=736,["sourceHash"]="3baa6c3ace54e6ebc8c8eda0b64db2354e4df1467098a649028a0c8b10c9b31e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2934",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He treated the exchange as a test of someone hoping to open a new chapter of their order.",["title"]="Keeper Bel'dugur"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"742:description:1-29","742:description:32-64","742:description:69-146","742:description:149-251","742:description:254-317","742:description:320-469","742:objective:1-63"},["minimumStage"]=2,["questID"]=742,["sourceHash"]="7e9249ad0e78b69bbab7dbd3894e9c957abd421d889eed0bac5116e5603b3c27"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10881",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Windstrider directed Horde adventurers toward Ashenvale’s outposts and Senani Thunderheart’s hunt at Splintertree.",["title"]="Bluff Runner Windstrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"743:description:1-49","743:description:51-81","743:description:86-209","743:description:214-309","743:description:311-368","743:description:373-463","743:objective:1-64"},["minimumStage"]=2,["questID"]=743,["sourceHash"]="64b07b4f203acc0cd59fa13b39f1a25ca83ced57662de5dbdc556d6c8987def5"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2985",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ruul was a warrior and teacher who prepared young tauren for the trials preceding wider travel.",["title"]="Ruul Eagletalon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"743:description:1-49","743:description:51-81","743:description:86-209","743:description:214-309","743:description:311-368","743:description:373-463","743:objective:1-64"},["minimumStage"]=2,["questID"]=743,["sourceHash"]="64b07b4f203acc0cd59fa13b39f1a25ca83ced57662de5dbdc556d6c8987def5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2985",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He proposed the Windfury harpies along Mulgore’s southeastern mountain edges as a test of strength against a local enemy.",["title"]="Ruul Eagletalon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"744:description:1-100","744:description:105-177","744:description:179-278","744:description:283-398","744:description:400-464","744:objective:1-100"},["minimumStage"]=2,["questID"]=744,["sourceHash"]="7e90a84cc8783d6598cc438e0128a50dd5aca8387ce5be1dfc79761f3a2eefe2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2987",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eyahn prepared the headdress her brother would wear before Chief Bloodhoof.",["title"]="Eyahn Eagletalon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"744:description:1-100","744:description:105-177","744:description:179-278","744:description:283-398","744:description:400-464","744:objective:1-100"},["minimumStage"]=2,["questID"]=744,["sourceHash"]="7e90a84cc8783d6598cc438e0128a50dd5aca8387ce5be1dfc79761f3a2eefe2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2987",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her design joined tanned leather straps with azure and bronze feathers gathered from harpies north of Thunder Bluff.",["title"]="Eyahn Eagletalon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"747:description:1-73","747:description:75-153","747:description:155-234","747:description:239-306","747:description:308-350","747:description:352-420","747:description:422-497","747:objective:1-112"},["minimumStage"]=2,["questID"]=747,["sourceHash"]="388363002d18677f5bc6e65eb6984093ca4cc55741ac1877de5173966887f601"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2980",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grull’s father was Chief Hawkwind, whose approval young hunters sought before being welcomed into Thunder Bluff.",["title"]="Grull Hawkwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"747:description:1-73","747:description:75-153","747:description:155-234","747:description:239-306","747:description:308-350","747:description:352-420","747:description:422-497","747:objective:1-112"},["minimumStage"]=2,["questID"]=747,["sourceHash"]="388363002d18677f5bc6e65eb6984093ca4cc55741ac1877de5173966887f601"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2980",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He linked a first plainstrider hunt to the village’s need for meat and feathers for clothing, making tribal service part of proving skill.",["title"]="Grull Hawkwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"748:description:1-63","748:description:66-86","748:description:91-218","748:description:223-291","748:description:294-333","748:description:335-410","748:description:413-438","748:description:443-484","748:objective:1-85"},["minimumStage"]=2,["questID"]=748,["sourceHash"]="f4dee6e1ee072c9419d5596d79eaa24cf824a7fc3e6bbe90a7f4979596a4fb43"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2948",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mull prepared cleansing totems for Mulgore’s sacred wells, beginning with Winterhoof.",["title"]="Mull Thunderhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"748:description:1-63","748:description:66-86","748:description:91-218","748:description:223-291","748:description:294-333","748:description:335-410","748:description:413-438","748:description:443-484","748:objective:1-85"},["minimumStage"]=2,["questID"]=748,["sourceHash"]="f4dee6e1ee072c9419d5596d79eaa24cf824a7fc3e6bbe90a7f4979596a4fb43"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2948",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He blamed goblins and their servants for poisoning the waters and called on the land’s animals to supply paws and talons for the rite.",["title"]="Mull Thunderhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"749:description:1-38","749:description:40-109","749:description:111-216","749:description:221-334","749:description:336-407","749:description:412-486","749:objective:1-94"},["minimumStage"]=2,["questID"]=749,["sourceHash"]="2472b9c3e3b2787c3545eb4df3521eacb0c6ed0ad7a67ce1b47d9a32695f3664"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2988",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Morin’s party attacked a guarded Venture Company caravan beside Stonebull Lake after losing two companions in an earlier clash.",["title"]="Morin Cloudstalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"749:description:1-38","749:description:40-109","749:description:111-216","749:description:221-334","749:description:336-407","749:description:412-486","749:objective:1-94"},["minimumStage"]=2,["questID"]=749,["sourceHash"]="2472b9c3e3b2787c3545eb4df3521eacb0c6ed0ad7a67ce1b47d9a32695f3664"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2988",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Salvagers returning to the burned wagons made him suspect useful supplies or papers had survived the torches.",["title"]="Morin Cloudstalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"782:description:1-189","782:description:191-263","782:description:268-401","782:description:403-473","782:description:475-507","782:objective:1-70"},["minimumStage"]=2,["questID"]=782,["sourceHash"]="fe3a435c5dbb9be5d3a7ee9961238c11389fb4b89f285d6540cefee5bb3b57a4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1068",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gorn recalled Deathwing’s old dealings with the Horde and regarded silencing Blacklash and Hematus as a step toward restoring its honor.",["title"]="Gorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"782:description:1-189","782:description:191-263","782:description:268-401","782:description:403-473","782:description:475-507","782:objective:1-70"},["minimumStage"]=2,["questID"]=782,["sourceHash"]="fe3a435c5dbb9be5d3a7ee9961238c11389fb4b89f285d6540cefee5bb3b57a4"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1068",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tho’grun’s hired ogres betrayed his party and took the Sign of the Earth, leaving the prison key in enemy hands at Camp Boff.",["title"]="Gorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"783:description:1-97","783:description:102-126","783:description:131-263","783:description:266-335","783:description:338-356","783:description:361-440","783:description:443-474","783:objective:1-27"},["minimumStage"]=2,["questID"]=783,["sourceHash"]="7c7503bf3c33af5489648bff87dbedadd78cd7eec0bb079476eacae23ec43369"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-823",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Willem recruited volunteers for Northshire and directed them to his superior, Marshal McBride, inside the abbey.",["title"]="Deputy Willem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"783:description:1-97","783:description:102-126","783:description:131-263","783:description:266-335","783:description:338-356","783:description:361-440","783:description:443-474","783:objective:1-27"},["minimumStage"]=2,["questID"]=783,["sourceHash"]="7c7503bf3c33af5489648bff87dbedadd78cd7eec0bb079476eacae23ec43369"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-823",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With many guards serving far away, he described the local force as hard pressed by threats close to home.",["title"]="Deputy Willem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"786:description:1-21","786:description:23-93","786:description:98-266","786:description:271-317","786:description:319-415","786:description:420-487","786:objective:1-113"},["minimumStage"]=2,["questID"]=786,["sourceHash"]="269d87615cb2ec5e08cd1cdeabeafcbe95721f4a152d6e5b7da957e6560218cf"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3140",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lar slipped into Kolkar Crag while its centaurs were raiding and discovered plans for a three-part assault on Durotar’s trolls and orcs.",["title"]="Lar Prowltusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"786:description:1-21","786:description:23-93","786:description:98-266","786:description:271-317","786:description:319-415","786:description:420-487","786:objective:1-113"},["minimumStage"]=2,["questID"]=786,["sourceHash"]="269d87615cb2ec5e08cd1cdeabeafcbe95721f4a152d6e5b7da957e6560218cf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3140",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the plans destroyed among the three leaders holding them before the invasion could begin.",["title"]="Lar Prowltusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"787:description:1-13","787:description:15-82","787:description:87-130","787:description:132-259","787:description:261-352","787:description:354-446","787:description:451-496","787:objective:1-28"},["minimumStage"]=2,["questID"]=787,["sourceHash"]="d3f41462075f17cd52f08d9210377b9ff000da316e9e4e8cbb1dbfb75385c4bb"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3144",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thrall charged Eitrigg with overseeing the training of new Horde recruits.",["title"]="Eitrigg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"787:description:1-13","787:description:15-82","787:description:87-130","787:description:132-259","787:description:261-352","787:description:354-446","787:description:451-496","787:objective:1-28"},["minimumStage"]=2,["questID"]=787,["sourceHash"]="d3f41462075f17cd52f08d9210377b9ff000da316e9e4e8cbb1dbfb75385c4bb"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3144",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eitrigg recalled leaving the old Horde over demonic influence, then returning after rescue and hearing Thrall’s vision of a people guided by shamans instead.",["title"]="Eitrigg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"789:description:1-91","789:description:93-150","789:description:152-214","789:description:219-305","789:description:307-406","789:description:411-466","789:objective:1-50"},["minimumStage"]=2,["questID"]=789,["sourceHash"]="b86b1168718e115cb3f31bb70b8027a5866bff01423897c7e776e071fa7c314c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="gornek",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gornek kept scorpid antidote for young recruits and explained that it was made from venom extracted from the creatures’ own stingers.",["title"]="Gornek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"789:description:1-91","789:description:93-150","789:description:152-214","789:description:219-305","789:description:307-406","789:description:411-466","789:objective:1-50"},["minimumStage"]=2,["questID"]=789,["sourceHash"]="b86b1168718e115cb3f31bb70b8027a5866bff01423897c7e776e071fa7c314c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="gornek",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He required tails as proof that recruits could face the scorpids whose poison had felled veterans as well as novices.",["title"]="Gornek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"791:description:1-38","791:description:40-78","791:description:83-127","791:description:129-208","791:description:213-301","791:description:306-358","791:description:360-466","791:objective:1-66"},["minimumStage"]=2,["questID"]=791,["sourceHash"]="ebd82153ba83395aad6386e127c8680b87661c57bf11d52962505c936e50cf71"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3147",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Too old for battle, Furl watched for invaders, sounded the signal horn and made useful goods for younger warriors.",["title"]="Furl Scornbrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"791:description:1-38","791:description:40-78","791:description:83-127","791:description:129-208","791:description:213-301","791:description:306-358","791:description:360-466","791:objective:1-66"},["minimumStage"]=2,["questID"]=791,["sourceHash"]="ebd82153ba83395aad6386e127c8680b87661c57bf11d52962505c936e50cf71"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3147",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered to fashion a bag from canvas taken from the humans and centaurs, turning a gathered material into practical help for a recruit.",["title"]="Furl Scornbrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"809:description:1-128","809:description:131-174","809:description:179-263","809:description:266-344","809:description:347-367","809:description:372-474","809:description:477-503","809:objective:1-36"},["minimumStage"]=2,["questID"]=809,["sourceHash"]="912fa453c13f3ff0cbac71e6ed3e8f206bb50d9ff66d060167c501a147ffd120"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3216",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Neeru publicly claimed to be tracking demonic corruption and identified the Burning Blade’s Demon Seed atop Dreadmist Peak as a threat to destroy.",["title"]="Neeru Fireblade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"809:description:1-128","809:description:131-174","809:description:179-263","809:description:266-344","809:description:347-367","809:description:372-474","809:description:477-503","809:objective:1-36"},["minimumStage"]=2,["questID"]=809,["sourceHash"]="912fa453c13f3ff0cbac71e6ed3e8f206bb50d9ff66d060167c501a147ffd120"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3216",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent the inquiry onward to his assistant Ak’Zeloth at Far Watch Post; the stated mission did not establish Neeru’s sincerity.",["title"]="Neeru Fireblade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"812:description:7-29","812:description:31-78","812:description:83-176","812:description:178-229","812:description:231-277","812:description:279-320","812:description:325-377","812:description:379-389","812:description:391-404","812:description:406-441","812:description:443-478","812:objective:1-58","812:objective:60-133"},["minimumStage"]=2,["questID"]=812,["sourceHash"]="25fe1a8278b9e08461117c4a528a9505e735d0e7ae60ec18d01d30636a86c7a6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3190",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A deep venomtail sting left Rhinag rapidly weakening and afraid he had little time to live.",["title"]="Rhinag"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"812:description:7-29","812:description:31-78","812:description:83-176","812:description:178-229","812:description:231-277","812:description:279-320","812:description:325-377","812:description:379-389","812:description:391-404","812:description:406-441","812:description:443-478","812:objective:1-58","812:objective:60-133"},["minimumStage"]=2,["questID"]=812,["sourceHash"]="25fe1a8278b9e08461117c4a528a9505e735d0e7ae60ec18d01d30636a86c7a6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3190",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought an antidote from Kor’ghan in Orgrimmar’s Cleft of Shadow before the venom overcame him.",["title"]="Rhinag"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"815:description:1-4","815:description:6-51","815:description:56-111","815:description:113-193","815:description:198-295","815:description:297-488","815:objective:1-52"},["minimumStage"]=2,["questID"]=815,["sourceHash"]="e74d32baa2044a1eeef7fa5e079af79532497cabb9979acfe0b9b5a496f456cc"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3191",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Torka prepared meals and needed taillasher eggs for the next morning’s breakfast.",["title"]="Cook Torka"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"815:description:1-4","815:description:6-51","815:description:56-111","815:description:113-193","815:description:198-295","815:description:297-488","815:objective:1-52"},["minimumStage"]=2,["questID"]=815,["sourceHash"]="e74d32baa2044a1eeef7fa5e079af79532497cabb9979acfe0b9b5a496f456cc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-3191",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recommended the Echo Isles’ nests but warned that the raptors fiercely defended their eggs and sometimes buried them too deep to gather safely.",["title"]="Cook Torka"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"816:description:1-28","816:description:30-93","816:description:95-168","816:description:170-186","816:description:191-264","816:description:266-324","816:description:326-355","816:description:360-421","816:description:423-509","816:objective:1-87"},["minimumStage"]=2,["questID"]=816,["sourceHash"]="36059bc06795d3ee508d6c8952c083ebe541938a021c6d8e242b46f13ff943f3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3193",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Misha’s son Kron left to hunt Southfury crocolisks after angrily dismissing her warnings.",["title"]="Misha Tor'kren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"816:description:1-28","816:description:30-93","816:description:95-168","816:description:170-186","816:description:191-264","816:description:266-324","816:description:326-355","816:description:360-421","816:description:423-509","816:objective:1-87"},["minimumStage"]=2,["questID"]=816,["sourceHash"]="36059bc06795d3ee508d6c8952c083ebe541938a021c6d8e242b46f13ff943f3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3193",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Days without his return left her seeking either the missing hunter or some sign of his fate along the river.",["title"]="Misha Tor'kren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"817:description:1-54","817:description:56-183","817:description:188-243","817:description:245-314","817:description:316-381","817:description:386-439","817:description:441-487","817:objective:1-62"},["minimumStage"]=2,["questID"]=817,["sourceHash"]="acd3602220689d3291ea5b429d6902d0b77b81b7d76b3ef57c65d48d3b2a1de5"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3194",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vel’rin prepared hides for his people’s blankets, armor and tents.",["title"]="Vel'rin Fang"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"817:description:1-54","817:description:56-183","817:description:188-243","817:description:245-314","817:description:316-381","817:description:386-439","817:description:441-487","817:objective:1-62"},["minimumStage"]=2,["questID"]=817,["sourceHash"]="acd3602220689d3291ea5b429d6902d0b77b81b7d76b3ef57c65d48d3b2a1de5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-3194",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He saw reason both to hunt Durotar’s tigers and let them thrive, requesting more furs when growing needs strained the settlement’s stock.",["title"]="Vel'rin Fang"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"818:description:1-57","818:description:59-147","818:description:149-239","818:description:244-258","818:description:260-284","818:description:286-313","818:description:318-337","818:description:339-363","818:description:368-422","818:description:424-478","818:description:480-505","818:objective:1-93"},["minimumStage"]=2,["questID"]=818,["sourceHash"]="8d2fbf0d1f1a6625f0293fd00928b0db21743f6f37f0da549d3cce12180072c2"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="npc-3304",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vornal’s failing eyesight made him increasingly dependent on alchemy to accomplish magic that once came easily.",["title"]="Master Vornal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"818:description:1-57","818:description:59-147","818:description:149-239","818:description:244-258","818:description:260-284","818:description:286-313","818:description:318-337","818:description:339-363","818:description:368-422","818:description:424-478","818:description:480-505","818:objective:1-93"},["minimumStage"]=2,["questID"]=818,["sourceHash"]="8d2fbf0d1f1a6625f0293fd00928b0db21743f6f37f0da549d3cce12180072c2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-3304",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought intact makrura eyes and crawler mucus while judging whether any young orc or troll might be worthy of apprenticeship.",["title"]="Master Vornal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"821:description:1-42","821:description:44-80","821:description:82-151","821:description:153-236","821:description:241-402","821:description:404-435","821:description:440-493","821:objective:1-110"},["minimumStage"]=2,["questID"]=821,["sourceHash"]="189eb7f9c65f4ca6bcb3f10a4825facad5c06b88c82e84bc3e141cd803085e43"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3292",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Chen taught Drohn’s mentor the stormstout recipe, and the mentor passed it to Drohn.",["title"]="Brewmaster Drohn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"821:description:1-42","821:description:44-80","821:description:82-151","821:description:153-236","821:description:241-402","821:description:404-435","821:description:440-493","821:objective:1-110"},["minimumStage"]=2,["questID"]=821,["sourceHash"]="189eb7f9c65f4ca6bcb3f10a4825facad5c06b88c82e84bc3e141cd803085e43"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3292",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The brew called for savannah lion tusks, plainstrider kidneys and a thunder lizard horn gathered across the Barrens.",["title"]="Brewmaster Drohn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"834:description:1-34","834:description:36-81","834:description:83-131","834:description:133-163","834:description:165-203","834:description:208-333","834:description:338-397","834:description:399-509","834:objective:1-70"},["minimumStage"]=2,["questID"]=834,["sourceHash"]="e5b5c788f2c2d86b416e43c86d648f4957a8bb3f4808d793283f220bd101ebc2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3293",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gazlowe sent Rezlak to support the orcs’ work in Durotar.",["title"]="Rezlak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"834:description:1-34","834:description:36-81","834:description:83-131","834:description:133-163","834:description:165-203","834:description:208-333","834:description:338-397","834:description:399-509","834:objective:1-70"},["minimumStage"]=2,["questID"]=834,["sourceHash"]="e5b5c788f2c2d86b416e43c86d648f4957a8bb3f4808d793283f220bd101ebc2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3293",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dustwind harpies seized his latest supply shipment in Razorwind Canyon, leaving his work stalled until the goods could be recovered.",["title"]="Rezlak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"836:description:1-53","836:description:58-151","836:description:154-234","836:description:237-330","836:description:333-403","836:description:408-477","836:description:480-507","836:objective:1-106"},["minimumStage"]=2,["questID"]=836,["sourceHash"]="5d472bc2c490072ea45b99f5706d2a179c352dd5cd1950e3370edcbb1bc9dc85"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7806",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="OOX-09/HL needed an escort to the shore beyond Overlook Cliff so Oglethorpe could restore its cloaking and prepare a safe takeoff.",["title"]="Homing Robot OOX-09/HL"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"843:description:1-33","843:description:38-91","843:description:93-181","843:description:183-280","843:description:285-341","843:description:343-378","843:description:383-505","843:objective:1-80","843:objective:85-128"},["minimumStage"]=2,["questID"]=843,["sourceHash"]="0aef90184dc89e6a5f2d6337f0bbae811acf6cda08a05ebb4b7c249f02110d2f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3341",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The lands torn by Bael Modan’s excavation had once sustained Gann’s tribe. He said attempts at diplomacy with the dwarves had failed.",["title"]="Gann Stonespire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"843:description:1-33","843:description:38-91","843:description:93-181","843:description:183-280","843:description:285-341","843:description:343-378","843:description:383-505","843:objective:1-80","843:objective:85-128"},["minimumStage"]=2,["questID"]=843,["sourceHash"]="0aef90184dc89e6a5f2d6337f0bbae811acf6cda08a05ebb4b7c249f02110d2f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3341",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the dig driven out by force and Khazgorm’s journal recovered from its leader.",["title"]="Gann Stonespire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"851:description:1-81","851:description:84-166","851:description:169-206","851:description:211-297","851:description:300-388","851:description:391-410","851:description:415-474","851:objective:1-64"},["minimumStage"]=2,["questID"]=851,["sourceHash"]="d58817d8dcb606a2d1c813dc883592350deac925877ad7bf5bc7220e9a5443d1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3389",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Regthar planned to draw the wandering Verog back to the Stagnant Oasis by provoking an alarm among the centaurs at his command tent.",["title"]="Regthar Deathgate"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"851:description:1-81","851:description:84-166","851:description:169-206","851:description:211-297","851:description:300-388","851:description:391-410","851:description:415-474","851:objective:1-64"},["minimumStage"]=2,["questID"]=851,["sourceHash"]="d58817d8dcb606a2d1c813dc883592350deac925877ad7bf5bc7220e9a5443d1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3389",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Verog’s head displayed beside Barak Kodobane’s as the next blow against the centaur leadership.",["title"]="Regthar Deathgate"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"853:description:1-56","853:description:59-111","853:description:114-211","853:description:216-290","853:description:293-375","853:description:380-388","853:description:391-500","853:objective:1-92"},["minimumStage"]=2,["questID"]=853,["sourceHash"]="1b9428f087c3502ca8e440e38229e49bd75ee7935785747760dcbf9580d37f5b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3390",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Helbrim sent a spore emulsion to his associate Zamah in Thunder Bluff’s Pools of Vision.",["title"]="Apothecary Helbrim"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"853:description:1-56","853:description:59-111","853:description:114-211","853:description:216-290","853:description:293-375","853:description:380-388","853:description:391-500","853:objective:1-92"},["minimumStage"]=2,["questID"]=853,["sourceHash"]="1b9428f087c3502ca8e440e38229e49bd75ee7935785747760dcbf9580d37f5b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3390",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The preparation had to be resealed and processed quickly before it lost its potency.",["title"]="Apothecary Helbrim"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"854:description:1-39","854:description:41-84","854:description:89-150","854:description:152-202","854:description:207-328","854:description:330-408","854:description:410-472","854:objective:1-50"},["minimumStage"]=2,["questID"]=854,["sourceHash"]="b786a70e1d5cbed78a534aa6d6f907df85401095783794f74d2a0f95ec685661"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kirge guided travelers from Mulgore toward the Crossroads and Thork, joining their service to the Horde’s shared needs.",["title"]="Kirge Sternhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"854:description:1-39","854:description:41-84","854:description:89-150","854:description:152-202","854:description:207-328","854:description:330-408","854:description:410-472","854:objective:1-50"},["minimumStage"]=2,["questID"]=854,["sourceHash"]="b786a70e1d5cbed78a534aa6d6f907df85401095783794f74d2a0f95ec685661"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described that next step through foresight and the Earthmother’s blessing rather than as a mere errand between settlements.",["title"]="Kirge Sternhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"857:description:1-19","857:description:21-37","857:description:39-57","857:description:59-69","857:description:74-111","857:description:113-132","857:description:134-218","857:description:223-247","857:description:249-259","857:description:264-318","857:description:320-349","857:description:351-375","857:description:377-385","857:description:390-433","857:description:435-470","857:description:475-493","857:description:495-505","857:objective:1-70"},["minimumStage"]=2,["questID"]=857,["sourceHash"]="ac0bfa1cda2c26c043e5b7d878d34588c14686e84e8d4b37c3f9dc7ea1c881b0"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3421",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Feegly blamed Twinbraid’s jealousy for taking the Tear of the Moons from him and driving him away from Bael Modan.",["title"]="Feegly the Exiled"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"857:description:1-19","857:description:21-37","857:description:39-57","857:description:59-69","857:description:74-111","857:description:113-132","857:description:134-218","857:description:223-247","857:description:249-259","857:description:264-318","857:description:320-349","857:description:351-375","857:description:377-385","857:description:390-433","857:description:435-470","857:description:475-493","857:description:495-505","857:objective:1-70"},["minimumStage"]=2,["questID"]=857,["sourceHash"]="ac0bfa1cda2c26c043e5b7d878d34588c14686e84e8d4b37c3f9dc7ea1c881b0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3421",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He demanded the relic back, rejecting the general’s warning that its power was cursed. His accusations were his own account of the quarrel.",["title"]="Feegly the Exiled"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"858:description:1-38","858:description:40-58","858:description:60-148","858:description:150-233","858:description:235-337","858:description:342-382","858:description:384-487","858:description:492-508","858:objective:1-49"},["minimumStage"]=2,["questID"]=858,["sourceHash"]="041d081225d11058e698e9a6d65b8c1a8ceee071126ed8dfd82d806a22026e66"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3439",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wizzlecrank entered the shredder without the key to its movement column, then concealed the problem from another operator by claiming a mechanical fault.",["title"]="Wizzlecrank's Shredder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"858:description:1-38","858:description:40-58","858:description:60-148","858:description:150-233","858:description:235-337","858:description:342-382","858:description:384-487","858:description:492-508","858:objective:1-49"},["minimumStage"]=2,["questID"]=858,["sourceHash"]="041d081225d11058e698e9a6d65b8c1a8ceee071126ed8dfd82d806a22026e66"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3439",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Escaping depended on a key held by the supervisor in the derrick’s upper control room.",["title"]="Wizzlecrank's Shredder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"860:description:1-78","860:description:81-120","860:description:123-186","860:description:191-218","860:description:221-264","860:description:269-296","860:description:299-394","860:description:397-486","860:objective:1-46"},["minimumStage"]=2,["questID"]=860,["sourceHash"]="a1b992a366ef02c28605836effb2589881c76b9a828027d355d362d3dbbff09c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3441",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Melor guided hunters onward from Mulgore to Sergra Darkthorn at the Crossroads.",["title"]="Melor Stonehoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"860:description:1-78","860:description:81-120","860:description:123-186","860:description:191-218","860:description:221-264","860:description:269-296","860:description:299-394","860:description:397-486","860:objective:1-46"},["minimumStage"]=2,["questID"]=860,["sourceHash"]="a1b992a366ef02c28605836effb2589881c76b9a828027d355d362d3dbbff09c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3441",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He regarded the Barrens’ fierce, strong-willed beasts as teachers whose pursuit would strengthen a hunter’s spirit.",["title"]="Melor Stonehoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"861:description:1-37","861:description:40-76","861:description:81-97","861:description:100-140","861:description:145-239","861:description:242-286","861:description:291-386","861:description:389-467","861:objective:1-67"},["minimumStage"]=2,["questID"]=861,["sourceHash"]="3831ac0af6caec2c3438643894602d3fd70ffd8dfa79f02067ac2a4f35660161"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3052",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Skorn remembered his own youthful desire to wander and hunt.",["title"]="Skorn Whitecloud"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"861:description:1-37","861:description:40-76","861:description:81-97","861:description:100-140","861:description:145-239","861:description:242-286","861:description:291-386","861:description:389-467","861:objective:1-67"},["minimumStage"]=2,["questID"]=861,["sourceHash"]="3831ac0af6caec2c3438643894602d3fd70ffd8dfa79f02067ac2a4f35660161"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3052",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent aspiring hunters to Melor with flatland prowler claws as proof of skill and resolve.",["title"]="Skorn Whitecloud"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"866:description:1-65","866:description:68-182","866:description:187-222","866:description:224-253","866:description:258-353","866:description:356-437","866:objective:1-50"},["minimumStage"]=2,["questID"]=866,["sourceHash"]="090eaa259e02e52e35b064cba5050bdc22bdc5cd1a25245252b37b04b55b100c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3446",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mebok wanted to compare Barrens root samples with herbs from elsewhere, seeking exploitable differences caused by the oasis water.",["title"]="Mebok Mizzyrix"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"866:description:1-65","866:description:68-182","866:description:187-222","866:description:224-253","866:description:258-353","866:description:356-437","866:objective:1-50"},["minimumStage"]=2,["questID"]=866,["sourceHash"]="090eaa259e02e52e35b064cba5050bdc22bdc5cd1a25245252b37b04b55b100c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3446",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He believed the local plants retained familiar properties while acquiring subtle changes from that water.",["title"]="Mebok Mizzyrix"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"867:description:1-73","867:description:75-144","867:description:149-216","867:description:218-345","867:description:350-478","867:description:480-509","867:objective:1-27","867:objective:32-83"},["minimumStage"]=2,["questID"]=867,["sourceHash"]="d2e5aef25236e12e33954c5eb13e4e164631100c95ebee7b4f33790c657a0b72"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3449",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Darsok had scouted Witchwing nests and worked out the harpies’ chain of command after repeated attacks on caravan supplies.",["title"]="Darsok Swiftdagger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"867:description:1-73","867:description:75-144","867:description:149-216","867:description:218-345","867:description:350-478","867:description:480-509","867:objective:1-27","867:objective:32-83"},["minimumStage"]=2,["questID"]=867,["sourceHash"]="d2e5aef25236e12e33954c5eb13e4e164631100c95ebee7b4f33790c657a0b72"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3449",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His plan began with lesser fighters and roguefeathers, intending to work upward through their leadership.",["title"]="Darsok Swiftdagger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"869:description:1-67","869:description:70-149","869:description:154-176","869:description:178-232","869:description:235-240","869:description:242-257","869:description:260-272","869:description:277-325","869:description:328-405","869:description:410-437","869:description:440-466","869:objective:1-50"},["minimumStage"]=2,["questID"]=869,["sourceHash"]="d615920b451deec3742a1ce49a944be1da6ac97a525842f6e95dbae4e2ea449d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3464",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Silver intended for the Crossroads guards’ payroll vanished from Gazrog’s tower, and a captured thief proved to be a raptor.",["title"]="Gazrog"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"869:description:1-67","869:description:70-149","869:description:154-176","869:description:178-232","869:description:235-240","869:description:242-257","869:description:260-272","869:description:277-325","869:description:328-405","869:description:410-437","869:description:440-466","869:objective:1-50"},["minimumStage"]=2,["questID"]=869,["sourceHash"]="d615920b451deec3742a1ce49a944be1da6ac97a525842f6e95dbae4e2ea449d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3464",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the stolen pay recovered and the raptors stopped, while admitting that he did not understand their interest in silver.",["title"]="Gazrog"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"871:description:1-38","871:description:40-92","871:description:97-197","871:description:199-325","871:description:330-368","871:description:370-455","871:description:457-485","871:objective:1-119"},["minimumStage"]=2,["questID"]=871,["sourceHash"]="eb0453c9c873eaa31154495b7c4c5e8fa055cea511c0bb5b9335722d24e420f2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3429",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Razormane attacks disrupted Thork’s supply lines from Durotar.",["title"]="Thork"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"871:description:1-38","871:description:40-92","871:description:97-197","871:description:199-325","871:description:330-368","871:description:370-455","871:description:457-485","871:objective:1-119"},["minimumStage"]=2,["questID"]=871,["sourceHash"]="eb0453c9c873eaa31154495b7c4c5e8fa055cea511c0bb5b9335722d24e420f2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3429",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="While scouts sought the raid leader, he called for attacks on the northeastern thorn dens to relieve the pressure.",["title"]="Thork"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"878:description:1-27","878:description:29-110","878:description:112-175","878:description:177-221","878:description:223-237","878:description:242-347","878:description:349-482","878:objective:1-149"},["minimumStage"]=2,["questID"]=878,["sourceHash"]="1f832f75205595b41422b8924547f9d4786c20ec5965f49fa9465c845bbf954f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3430",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mangletooth sought to weaken Bristleback spiritual leaders so that his Razormane tribe could defeat its rivals and rule the Barrens.",["title"]="Mangletooth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"878:description:1-27","878:description:29-110","878:description:112-175","878:description:177-221","878:description:223-237","878:description:242-347","878:description:349-482","878:objective:1-149"},["minimumStage"]=2,["questID"]=878,["sourceHash"]="1f832f75205595b41422b8924547f9d4786c20ec5965f49fa9465c845bbf954f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3430",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described both tribes as drawing strength from their bond with the earth and challenged Thork’s account of who caused the Horde’s troubles.",["title"]="Mangletooth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"882:description:1-71","882:description:74-114","882:description:117-156","882:description:159-200","882:description:205-301","882:description:306-320","882:description:323-417","882:description:420-472","882:description:477-499","882:objective:1-48"},["minimumStage"]=2,["questID"]=882,["sourceHash"]="5e771b9aa8e08e6549e3319ebd66a2171cb305ee27ab065ecee9ada8560bbb30"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3387",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jorn depicted Ishamuhale’s killing as a passion beyond hunger or sport, framing the raptor hunt as a lesson in its nature.",["title"]="Jorn Skyseer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"882:description:1-71","882:description:74-114","882:description:117-156","882:description:159-200","882:description:205-301","882:description:306-320","882:description:323-417","882:description:420-472","882:description:477-499","882:objective:1-48"},["minimumStage"]=2,["questID"]=882,["sourceHash"]="5e771b9aa8e08e6549e3319ebd66a2171cb305ee27ab065ecee9ada8560bbb30"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3387",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He proposed a zhevra carcass by the dead tree northwest of Ratchet to draw the elusive raptor within reach.",["title"]="Jorn Skyseer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"886:description:1-92","886:description:97-188","886:description:193-235","886:description:238-266","886:description:269-328","886:description:331-385","886:description:388-436","886:description:441-503","886:objective:1-45"},["minimumStage"]=2,["questID"]=886,["sourceHash"]="abc2a96af52b194c04af390558bb2614353021dd9c022babbb454f8d9fba6d98"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5769",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hamuul sought help for Tonga’s inquiry into the strange power the druids sensed leaking into the Barrens.",["title"]="Arch Druid Hamuul Runetotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"886:description:1-92","886:description:97-188","886:description:193-235","886:description:238-266","886:description:269-328","886:description:331-385","886:description:388-436","886:description:441-503","886:objective:1-45"},["minimumStage"]=2,["questID"]=886,["sourceHash"]="abc2a96af52b194c04af390558bb2614353021dd9c022babbb454f8d9fba6d98"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5769",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tonga had been sent to find its source and worked from the Crossroads, where Hamuul directed further assistance.",["title"]="Arch Druid Hamuul Runetotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"891:description:1-92","891:description:97-130","891:description:132-176","891:description:178-248","891:description:253-332","891:description:334-380","891:description:382-465","891:objective:1-148"},["minimumStage"]=2,["questID"]=891,["sourceHash"]="d8d6e96b6b803fc134a5259e9e9db30088996459b84fc26fd4be36bff5b26004"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3339",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brightsun blamed Northwatch’s gunners for the loss of another ship from his fleet.",["title"]="Captain Thalo'thas Brightsun"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"891:description:1-92","891:description:97-130","891:description:132-176","891:description:178-248","891:description:253-332","891:description:334-380","891:description:382-465","891:objective:1-148"},["minimumStage"]=2,["questID"]=891,["sourceHash"]="d8d6e96b6b803fc134a5259e9e9db30088996459b84fc26fd4be36bff5b26004"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3339",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He called for a strike on Captain Fairmount and her cannoneers, demanding soldiers’ medals as evidence.",["title"]="Captain Thalo'thas Brightsun"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"893:description:1-174","893:description:176-263","893:description:268-353","893:description:355-451","893:description:453-474","893:objective:1-139"},["minimumStage"]=2,["questID"]=893,["sourceHash"]="006eeb936ccb97a403dd3cf017f4c6c563def47dc5e472e316e9455b8f566116"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3433",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tatternack wanted examples of improved Razormane weapons to study the smithing behind them.",["title"]="Tatternack Steelforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"893:description:1-174","893:description:176-263","893:description:268-353","893:description:355-451","893:description:453-474","893:objective:1-139"},["minimumStage"]=2,["questID"]=893,["sourceHash"]="006eeb936ccb97a403dd3cf017f4c6c563def47dc5e472e316e9455b8f566116"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3433",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought a stalker’s dagger, seer’s wand and warfrenzy’s shield despite reports that the tribe had no skilled blacksmiths.",["title"]="Tatternack Steelforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"898:description:1-8","898:description:10-30","898:description:35-74","898:description:76-127","898:description:129-184","898:description:186-234","898:description:243-286","898:description:288-359","898:description:364-375","898:description:377-413","898:description:415-469","898:objective:1-71"},["minimumStage"]=2,["questID"]=898,["sourceHash"]="649453e4fc2fc65d4c490ade970527457cd3774085741c564ba0b8803b47f3c6"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3465",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gilthares described himself as a moonshine-transport deckhand and sole survivor when his ship was sunk and he was imprisoned at Northwatch.",["title"]="Gilthares Firebough"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"898:description:1-8","898:description:10-30","898:description:35-74","898:description:76-127","898:description:129-184","898:description:186-234","898:description:243-286","898:description:288-359","898:description:364-375","898:description:377-413","898:description:415-469","898:objective:1-71"},["minimumStage"]=2,["questID"]=898,["sourceHash"]="649453e4fc2fc65d4c490ade970527457cd3774085741c564ba0b8803b47f3c6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3465",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He rejected the accusation that he threatened the Alliance and sought an escape back to Ratchet.",["title"]="Gilthares Firebough"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"899:description:1-58","899:description:60-186","899:description:188-288","899:description:290-372","899:description:377-404","899:description:409-418","899:description:420-443","899:description:445-510","899:objective:1-65"},["minimumStage"]=2,["questID"]=899,["sourceHash"]="f137ccc7d1f516fe9a47743a8c594e2da4d08526c5ab53c11bbd99853c6e4347"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-3432",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mankrik’s uncertainty and hatred kept him searching the horizon and killing quilboar without satisfaction.",["title"]="Mankrik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"899:description:1-58","899:description:60-186","899:description:188-288","899:description:290-372","899:description:377-404","899:description:409-418","899:description:420-443","899:description:445-510","899:objective:1-65"},["minimumStage"]=2,["questID"]=899,["sourceHash"]="f137ccc7d1f516fe9a47743a8c594e2da4d08526c5ab53c11bbd99853c6e4347"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-3432",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He asked for more tusks as proof of further deaths, inviting others to join his revenge rather than treating the hunt as ordinary food gathering.",["title"]="Mankrik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"911:description:1-111","911:description:114-205","911:description:208-319","911:description:324-415","911:description:418-485","911:objective:1-107"},["minimumStage"]=2,["questID"]=911,["sourceHash"]="8c39ab0cd31633dec7c3c6084e5cd1d38a5923d35c84d10f3f896d2e3620d16d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14444",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The orphan dreamed of becoming a frontier pioneer and wanted to see Mor’shan Rampart, the gateway toward Ashenvale.",["title"]="Orcish Orphan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"914:description:1-77","914:description:80-226","914:description:231-303","914:description:306-335","914:description:338-418","914:description:432-490","914:objective:1-93"},["minimumStage"]=2,["questID"]=914,["sourceHash"]="ee035e44c082ec6a1f4106cc8f287c206cdeeb55327b720a0e177912a53965f0"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5770",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nara regarded the Druids of the Fang as a fallen healing order, now trying to remake the Barrens according to corrupted dreams.",["title"]="Nara Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"914:description:1-77","914:description:80-226","914:description:231-303","914:description:306-335","914:description:338-418","914:description:432-490","914:objective:1-93"},["minimumStage"]=2,["questID"]=914,["sourceHash"]="ee035e44c082ec6a1f4106cc8f287c206cdeeb55327b720a0e177912a53965f0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5770",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She sought the four leaders’ dream gems from the depths of the Wailing Caverns as a way to resist their influence.",["title"]="Nara Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"916:description:1-88","916:description:91-255","916:description:260-299","916:description:302-394","916:description:397-471","916:objective:1-65"},["minimumStage"]=2,["questID"]=916,["sourceHash"]="ead609376ee13e72ee8a8222742701e35af2d949766a15fd2f94390cd67d183d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2082",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gilshalan studied the webwood spiders in and around Shadowthread Cave.",["title"]="Gilshalan Windwalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"916:description:1-88","916:description:91-255","916:description:260-299","916:description:302-394","916:description:397-471","916:objective:1-65"},["minimumStage"]=2,["questID"]=916,["sourceHash"]="ead609376ee13e72ee8a8222742701e35af2d949766a15fd2f94390cd67d183d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2082",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought venom samples to test his belief that the World Tree had altered spiders related to a much smaller variety.",["title"]="Gilshalan Windwalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"921:description:1-55","921:description:57-191","921:description:196-260","921:description:262-384","921:description:389-421","921:description:423-495","921:objective:1-77"},["minimumStage"]=2,["questID"]=921,["sourceHash"]="e68518cc1fe6085c5aa2c05860a73dd8793e9c441801ff6df9c80417ede14838"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3514",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tenaron joined a young traveler’s moonwell gathering to lessons in the night elves’ recent history.",["title"]="Tenaron Stormgrip"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"921:description:1-55","921:description:57-191","921:description:196-260","921:description:262-384","921:description:389-421","921:description:423-495","921:objective:1-77"},["minimumStage"]=2,["questID"]=921,["sourceHash"]="e68518cc1fe6085c5aa2c05860a73dd8793e9c441801ff6df9c80417ede14838"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3514",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recalled Nordrassil’s power spent against Archimonde at Hyjal and the changed world that followed the Legion’s defeat.",["title"]="Tenaron Stormgrip"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"929:description:1-58","929:description:60-186","929:description:188-268","929:description:273-403","929:description:405-491","929:objective:1-72"},["minimumStage"]=2,["questID"]=929,["sourceHash"]="2decdd2f207e21b84d0f8afd3d471a4ecae426e70d7ae78278ddf6145f14be15"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3515",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Corithras gathered moonwell water from across Teldrassil to replenish the druids’ well in Darnassus.",["title"]="Corithras Moonrage"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"929:description:1-58","929:description:60-186","929:description:188-268","929:description:273-403","929:description:405-491","929:objective:1-72"},["minimumStage"]=2,["questID"]=929,["sourceHash"]="2decdd2f207e21b84d0f8afd3d471a4ecae426e70d7ae78278ddf6145f14be15"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3515",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Specially crafted phials carried the water, while each return gave him an occasion to continue Tenaron’s historical account.",["title"]="Corithras Moonrage"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"936:description:1-66","936:description:71-212","936:description:215-334","936:description:339-440","936:objective:1-56"},["minimumStage"]=2,["questID"]=936,["sourceHash"]="f76dbb103f08eb26de24af5524e0e6a4a76ba56587a89fc7d0ab26d2cd77a271"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-6929",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gryshka directed seasoned adventurers toward Hamuul’s research in Thunder Bluff, though she did not know its particulars.",["title"]="Innkeeper Gryshka"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"937:description:1-140","937:description:142-190","937:description:195-334","937:description:339-448","937:objective:1-95"},["minimumStage"]=2,["questID"]=937,["sourceHash"]="1a65afe9238ca9938501251a96656603dd080a0c766ddc9dd14cc6bd43fe93ab"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3519",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Arynia commanded a small Sentinel group protecting the Oracle Tree from harpies nesting around its glade.",["title"]="Sentinel Arynia Cloudsbreak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"937:description:1-140","937:description:142-190","937:description:195-334","937:description:339-448","937:objective:1-95"},["minimumStage"]=2,["questID"]=937,["sourceHash"]="1a65afe9238ca9938501251a96656603dd080a0c766ddc9dd14cc6bd43fe93ab"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-3519",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Harpies killed a runner carrying the tree’s report to Darnassus, sharpening the urgency of driving them back.",["title"]="Sentinel Arynia Cloudsbreak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"943:description:1-77","943:description:79-182","943:description:187-281","943:description:283-418","943:description:423-488","943:objective:1-107"},["minimumStage"]=2,["questID"]=943,["sourceHash"]="0531af0818bd0e5fc19b41482dc3c1421d10fc39a92c4cf16dc34252ce80380c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2911",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Flagongut discovered the Stone of Relu but lost it in a raptor attack while traveling to meet Whelgar.",["title"]="Archaeologist Flagongut"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"943:description:1-77","943:description:79-182","943:description:187-281","943:description:283-418","943:description:423-488","943:objective:1-107"},["minimumStage"]=2,["questID"]=943,["sourceHash"]="0531af0818bd0e5fc19b41482dc3c1421d10fc39a92c4cf16dc34252ce80380c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2911",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought the stone and Whelgar’s original fossil together, believing their combined power would explain the find.",["title"]="Archaeologist Flagongut"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"952:description:1-195","952:description:200-318","952:description:320-357","952:description:359-441","952:objective:1-95"},["minimumStage"]=2,["questID"]=952,["sourceHash"]="374fc977e3938c7992d81f819926d848d6583b9a3233f1392944e180ef92145d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3516",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fandral sent word to Onu in the Grove of the Ancients while awaiting news from Teldrassil’s Oracle Glade.",["title"]="Arch Druid Fandral Staghelm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"964:description:1-48","964:description:51-188","964:description:191-308","964:description:313-343","964:description:346-397","964:description:400-498","964:objective:1-86"},["minimumStage"]=2,["questID"]=964,["sourceHash"]="697ceeeaf09c934990978124537a152b6e158f7f2d5ae7dc346d601ffc40d427"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11057",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dithers explained a Skeleton Key made from skeletal remains, hardened in a mold with strong metal and completed with a portal-opener’s signet.",["title"]="Apothecary Dithers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"964:description:1-48","964:description:51-188","964:description:191-308","964:description:313-343","964:description:346-397","964:description:400-498","964:objective:1-86"},["minimumStage"]=2,["questID"]=964,["sourceHash"]="697ceeeaf09c934990978124537a152b6e158f7f2d5ae7dc346d601ffc40d427"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11057",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The work began with fragments from Andorhal’s skeletons, before the forging and signet could make the key function.",["title"]="Apothecary Dithers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"966:description:1-71","966:description:73-198","966:description:203-289","966:description:294-416","966:description:418-510","966:objective:1-80"},["minimumStage"]=2,["questID"]=966,["sourceHash"]="9f4012bafcf8365e87c1804fb171d3631c31ff7b88281e11700f5f1c4aa8e193"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3661",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Balthule collected the tower warlocks’ scraps of parchment to discover why they had gathered, delaying his report to Elissa rather than abandon the watch.",["title"]="Balthule Shadowstrike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"966:description:1-71","966:description:73-198","966:description:203-289","966:description:294-416","966:description:418-510","966:objective:1-80"},["minimumStage"]=2,["questID"]=966,["sourceHash"]="9f4012bafcf8365e87c1804fb171d3631c31ff7b88281e11700f5f1c4aa8e193"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3661",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned that the warlocks inside Althalaxx were stronger than those outside and sought enough documents to complete the puzzle.",["title"]="Balthule Shadowstrike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"977:description:1-94","977:description:96-114","977:description:116-125","977:description:130-235","977:description:237-287","977:description:289-364","977:description:369-450","977:objective:1-64"},["minimumStage"]=2,["questID"]=977,["sourceHash"]="c68b7801eb43a383a5056dd14e2b7d6b8bff71e5d09273fbdb7accf96f7b6f3f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10305",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Umi needed two flawless, large yeti horns after obtaining a covering for her machine’s moving parts.",["title"]="Umi Rumplesnicker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"977:description:1-94","977:description:96-114","977:description:116-125","977:description:130-235","977:description:237-287","977:description:289-364","977:description:369-450","977:objective:1-64"},["minimumStage"]=2,["questID"]=977,["sourceHash"]="c68b7801eb43a383a5056dd14e2b7d6b8bff71e5d09273fbdb7accf96f7b6f3f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10305",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She selected the ice thistle patriarchs and matriarchs in the southeastern cave as the source of the finest horns.",["title"]="Umi Rumplesnicker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"208:description:1-43","208:description:46-179","208:description:184-272","208:description:275-323","208:description:326-366","208:description:369-418","208:description:421-496","208:objective:1-90"},["minimumStage"]=2,["questID"]=208,["sourceHash"]="07b4e77ff16d26c42ebf5e2bdecaf0472cb03756c179432beca22c4d4489e4d5"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-731",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="King Bangalash was a white tiger, the hunting expedition’s most coveted quarry in Stranglethorn.",["title"]="King Bangalash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"208:description:1-43","208:description:46-179","208:description:184-272","208:description:275-323","208:description:326-366","208:description:369-418","208:description:421-496","208:objective:1-90"},["minimumStage"]=2,["questID"]=208,["sourceHash"]="07b4e77ff16d26c42ebf5e2bdecaf0472cb03756c179432beca22c4d4489e4d5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-731",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The final challenge placed him beyond the earlier hunts for Sin’Dall, Bhag’thera and Tethis in the expedition’s judgment.",["title"]="King Bangalash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"193:description:1-64","193:description:67-131","193:description:134-162","193:description:165-224","193:description:229-294","193:objective:1-6","193:objective:11-92"},["minimumStage"]=2,["questID"]=193,["sourceHash"]="6ab13131644d2002ed84a4351154223b265d2b41fd74695693127326f485edbf"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-728",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bhag’thera had repeatedly eluded the panther hunters working in the jungle.",["title"]="Bhag'thera"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"193:description:1-64","193:description:67-131","193:description:134-162","193:description:165-224","193:description:229-294","193:objective:1-6","193:objective:11-92"},["minimumStage"]=2,["questID"]=193,["sourceHash"]="6ab13131644d2002ed84a4351154223b265d2b41fd74695693127326f485edbf"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-728",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The expedition sought the great panther’s fang as proof of a hunter’s mastery.",["title"]="Bhag'thera"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"197:description:1-139","197:description:142-182","197:description:187-266","197:description:269-334","197:objective:1-89"},["minimumStage"]=2,["questID"]=197,["sourceHash"]="4016eaad99fb67f9cc905680b725f91ece982528e46462fdf290756a5c93c47d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-730",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The wily raptor Tethis had escaped the hunting instructor’s own attempts to kill him, making his talon a particularly prized proof.",["title"]="Tethis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"188:description:1-50","188:description:53-99","188:description:102-128","188:description:131-204","188:description:207-255","188:description:260-298","188:objective:1-91"},["minimumStage"]=2,["questID"]=188,["sourceHash"]="275b9140dc3b2fac155dc2bfdd2b7867fa7f9ba64197571eb3c10077eca2f093"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-729",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hunters had tracked the elusive tigress Sin’Dall for weeks without bringing her down.",["title"]="Sin'Dall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"348:description:1-29","348:description:34-93","348:description:98-190","348:description:195-251","348:description:256-305","348:description:310-337","348:objective:1-66","348:objective:68-108"},["minimumStage"]=2,["questID"]=348,["sourceHash"]="b7350e1269aa76d097e09fca669271a6392ca41b02fdc6082ce5544554e62fb3"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-1514",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The feverish petitioner described Mokk as an elusive white beast.",["title"]="Mokk the Savage"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"348:description:1-29","348:description:34-93","348:description:98-190","348:description:195-251","348:description:256-305","348:description:310-337","348:objective:1-66","348:objective:68-108"},["minimumStage"]=2,["questID"]=348,["sourceHash"]="b7350e1269aa76d097e09fca669271a6392ca41b02fdc6082ce5544554e62fb3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1514",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="That account claimed his heart could cure Stranglethorn Fever and that only Unbagwa could summon him; these were the sick petitioner’s claims.",["title"]="Mokk the Savage"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5056:description:1-93","5056:description:95-150","5056:description:152-253","5056:description:258-342","5056:description:344-391","5056:description:393-463","5056:description:468-505","5056:objective:1-75"},["minimumStage"]=2,["questID"]=5056,["sourceHash"]="621cf1b02ef3ef91000b1bc0c00d162a9811022630034156e62ecce1e27d4d9a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shy-Rotam led the frostsabers gathered around Frostsaber Rock in northern Winterspring.",["title"]="Shy-Rotam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5056:description:1-93","5056:description:95-150","5056:description:152-253","5056:description:258-342","5056:description:344-391","5056:description:393-463","5056:description:468-505","5056:objective:1-75"},["minimumStage"]=2,["questID"]=5056,["sourceHash"]="621cf1b02ef3ef91000b1bc0c00d162a9811022630034156e62ecce1e27d4d9a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The hunt used sacred meat from her own kin placed on her stone to draw the matriarch out in anger.",["title"]="Shy-Rotam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5054:description:1-93","5054:description:95-163","5054:description:168-194","5054:description:196-251","5054:description:253-303","5054:description:308-409","5054:description:411-429","5054:objective:1-70"},["minimumStage"]=2,["questID"]=5054,["sourceHash"]="3302739ad1d755d023348847a82852ad8bd54a3f9a5841f6671b7aed84355aaa"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-10806",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ursius stalked the snowy slopes northwest of Everlook.",["title"]="Ursius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5054:description:1-93","5054:description:95-163","5054:description:168-194","5054:description:196-251","5054:description:253-303","5054:description:308-409","5054:description:411-429","5054:objective:1-70"},["minimumStage"]=2,["questID"]=5054,["sourceHash"]="3302739ad1d755d023348847a82852ad8bd54a3f9a5841f6671b7aed84355aaa"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10806",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The hunter’s warning described the shardtooth as agile and clever, capable of turning those pursuing him into prey.",["title"]="Ursius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5055:description:1-96","5055:description:98-170","5055:description:172-239","5055:description:244-296","5055:description:298-333","5055:objective:1-72"},["minimumStage"]=2,["questID"]=5055,["sourceHash"]="cde34d8b7dbf0463b44839f9463d82dd5645233af219dd62346b3b849cbb7caa"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-10807",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brumeran’s swift, graceful flight carried her silently over southern Winterspring’s snow.",["title"]="Brumeran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5055:description:1-96","5055:description:98-170","5055:description:172-239","5055:description:244-296","5055:description:298-333","5055:objective:1-72"},["minimumStage"]=2,["questID"]=5055,["sourceHash"]="cde34d8b7dbf0463b44839f9463d82dd5645233af219dd62346b3b849cbb7caa"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10807",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The hunting account warned that the chillwind chimaera’s grace concealed a lethal danger to those crossing her path.",["title"]="Brumeran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2941:description:1-128","2941:description:130-204","2941:description:206-258","2941:description:260-313","2941:description:318-366","2941:description:368-430","2941:description:432-469","2941:objective:1-48"},["minimumStage"]=2,["questID"]=2941,["sourceHash"]="3442d36f1299bd901d4ee95bf2fb8d9c9324895fbf8e85ba4afc5b35b9a5ac58"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-7977",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gammerita was a giant snapjaw on the Hinterlands coast.",["title"]="Gammerita"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2941:description:1-128","2941:description:130-204","2941:description:206-258","2941:description:260-313","2941:description:318-366","2941:description:368-430","2941:description:432-469","2941:objective:1-48"},["minimumStage"]=2,["questID"]=2941,["sourceHash"]="3442d36f1299bd901d4ee95bf2fb8d9c9324895fbf8e85ba4afc5b35b9a5ac58"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7977",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A researcher unable to travel sought a picture of her through Curgle’s snapshot invention, making observation rather than a kill the purpose of the visit.",["title"]="Gammerita"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"882:description:1-71","882:description:74-114","882:description:117-156","882:description:159-200","882:description:205-301","882:description:306-320","882:description:323-417","882:description:420-472","882:description:477-499","882:objective:1-48"},["minimumStage"]=2,["questID"]=882,["sourceHash"]="5e771b9aa8e08e6549e3319ebd66a2171cb305ee27ab065ecee9ada8560bbb30"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3257",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jorn called the raptor Ishamuhale Speartooth and portrayed his hunting as an appetite for killing rather than food alone.",["title"]="Ishamuhale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"882:description:1-71","882:description:74-114","882:description:117-156","882:description:159-200","882:description:205-301","882:description:306-320","882:description:323-417","882:description:420-472","882:description:477-499","882:objective:1-48"},["minimumStage"]=2,["questID"]=882,["sourceHash"]="5e771b9aa8e08e6549e3319ebd66a2171cb305ee27ab065ecee9ada8560bbb30"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-3257",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A zhevra carcass at the dead tree northwest of Ratchet was the proposed lure for the sunscale raptor.",["title"]="Ishamuhale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"881:description:1-76","881:description:79-157","881:description:160-220","881:description:225-266","881:description:271-349","881:description:352-421","881:description:431-469","881:description:472-503","881:objective:1-61"},["minimumStage"]=2,["questID"]=881,["sourceHash"]="1f8a1c1efef038d6719ca3228f123e00095c76b403490d93cbd62f0829117262"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3475",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Echeyakee meant Whitemist in the tauren tongue; accounts likened his stealth to a thin white mist moving over the earth.",["title"]="Echeyakee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"881:description:1-76","881:description:79-157","881:description:160-220","881:description:225-266","881:description:271-349","881:description:352-421","881:description:431-469","881:description:472-503","881:objective:1-61"},["minimumStage"]=2,["questID"]=881,["sourceHash"]="1f8a1c1efef038d6719ca3228f123e00095c76b403490d93cbd62f0829117262"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3475",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tauren accounts called the great cat both mercy and death for his swift kills; a horn at his lair among giant kodo bones would call him forth.",["title"]="Echeyakee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"766:description:1-82","766:description:84-156","766:description:161-281","766:description:283-329","766:description:331-476","766:description:481-510","766:objective:1-128"},["minimumStage"]=2,["questID"]=766,["sourceHash"]="8b1bd0e7ce521c71846b12932d7f7b11ad99b8cf028dd259263ab06c4daf87ff"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-3068",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Mulgore tale described Mazzranache with red eyes, razor-sharp talons and a venomous bite.",["title"]="Mazzranache"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"766:description:1-82","766:description:84-156","766:description:161-281","766:description:283-329","766:description:331-476","766:description:481-510","766:objective:1-128"},["minimumStage"]=2,["questID"]=766,["sourceHash"]="8b1bd0e7ce521c71846b12932d7f7b11ad99b8cf028dd259263ab06c4daf87ff"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3068",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The bitten traveler compared the strider to his grandfather’s stories and sought animal parts to clean the infected wound.",["title"]="Mazzranache"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"770:description:1-118","770:description:123-197","770:objective:1-37"},["minimumStage"]=2,["questID"]=770,["sourceHash"]="12a38064f253564936e9ef5fc06dd8e5a517444ad50cc868ff28f7bebf63b69e"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-3056",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ghost Howl’s ragged hide bore a terrible, lasting wound.",["title"]="Ghost Howl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"770:description:1-118","770:description:123-197","770:objective:1-37"},["minimumStage"]=2,["questID"]=770,["sourceHash"]="12a38064f253564936e9ef5fc06dd8e5a517444ad50cc868ff28f7bebf63b69e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3056",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The cloak’s account attributed that scar to the wolf’s battles against the Burning Legion.",["title"]="Ghost Howl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"776:description:1-84","776:description:89-212","776:description:217-235","776:description:237-297","776:description:299-391","776:objective:1-79"},["minimumStage"]=2,["questID"]=776,["sourceHash"]="1c9c3b8ad541c813622c11792c29a08dbc138431b99d0f626c5ad132f4613455"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3058",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The great kodo’s horn was sought as a test of continued tracking skill and service after the Earthmother’s rites.",["title"]="Arra'chea"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"883:description:1-70","883:objective:1-54"},["minimumStage"]=2,["questID"]=883,["sourceHash"]="ef016b8a395a2adeda4454dc5dd76d53bbcc78502d7d75c42de2d9d6f8f7d76b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3474",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lakota’mani’s hoof was regarded as a symbol of the great kodo’s strength.",["title"]="Lakota'mani"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"884:description:1-56","884:objective:1-51"},["minimumStage"]=2,["questID"]=884,["sourceHash"]="92982a07df7cc638ada2beec557a901a9847b9256f3aa7eda68a7de6a04cb3cc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3473",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sparks flew from Owatanka’s tailspike when it was touched.",["title"]="Owatanka"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"885:description:1-52","885:objective:1-61"},["minimumStage"]=2,["questID"]=885,["sourceHash"]="31196f8f3048f8da1ffd1e32367005897329de0f49df5d6a4b0f98dd12dbc875"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3472",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Washte Pawne’s feather was painful to the touch; the account did not explain the cause.",["title"]="Washte Pawne"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"23:description:1-88","23:description:91-186","23:description:191-349","23:objective:1-77"},["minimumStage"]=2,["questID"]=23,["sourceHash"]="c9eee9db19ac6a8194c8ed14b6b1fba14d36131ff6adfaecc3b697f259a7699f"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-12678",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A small quarter-crescent emblem marked Ursangous’s paw.",["title"]="Ursangous"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"23:description:1-88","23:description:91-186","23:description:191-349","23:objective:1-77"},["minimumStage"]=2,["questID"]=23,["sourceHash"]="c9eee9db19ac6a8194c8ed14b6b1fba14d36131ff6adfaecc3b697f259a7699f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12678",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The hunt treated the emblem’s significance as a mystery rather than identifying a patron or allegiance for the bear.",["title"]="Ursangous"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"982:description:1-101","982:description:104-212","982:description:215-283","982:description:288-394","982:description:397-502","982:objective:1-100","982:objective:103-190"},["minimumStage"]=2,["questID"]=982,["sourceHash"]="7aab55bfcb887d5bf6a5b6239927aea6f301b0ce9328f73efd2f239946b5c56e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6301",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gorbold recalled murloc attacks sinking the Silver Dawning and Mist Veil as they approached Auberdine, with neither captain surviving.",["title"]="Gorbold Steelhand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"982:description:1-101","982:description:104-212","982:description:215-283","982:description:288-394","982:description:397-502","982:objective:1-100","982:objective:103-190"},["minimumStage"]=2,["questID"]=982,["sourceHash"]="7aab55bfcb887d5bf6a5b6239927aea6f301b0ce9328f73efd2f239946b5c56e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6301",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted their locked logs and effects recovered for the surviving crews still living nearby.",["title"]="Gorbold Steelhand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"983:description:1-4","983:description:6-51","983:description:53-84","983:description:89-154","983:description:156-206","983:description:211-288","983:description:290-380","983:description:382-419","983:description:421-461","983:description:463-496","983:description:498-511","983:objective:1-53"},["minimumStage"]=2,["questID"]=983,["sourceHash"]="b040ea8bcaa26bb9c184e3faf495df2b61c4e36dd2784e0c1219144300a5b211"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3666",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wizbang invented the buzzboxes to let people speak across long distances.",["title"]="Wizbang Cranktoggle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"983:description:1-4","983:description:6-51","983:description:53-84","983:description:89-154","983:description:156-206","983:description:211-288","983:description:290-380","983:description:382-419","983:description:421-461","983:description:463-496","983:description:498-511","983:objective:1-53"},["minimumStage"]=2,["questID"]=983,["sourceHash"]="b040ea8bcaa26bb9c184e3faf495df2b61c4e36dd2784e0c1219144300a5b211"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3666",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The machines needed frequent repairs, so he placed them near creatures supplying suitable parts; the faulty box south of Auberdine required crawler legs.",["title"]="Wizbang Cranktoggle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1007:description:1-35","1007:description:40-190","1007:description:193-256","1007:description:261-299","1007:description:301-330","1007:description:335-440","1007:description:443-505","1007:objective:1-72"},["minimumStage"]=2,["questID"]=1007,["sourceHash"]="f1cb0bc84bac5365f39ba5f208fa08385334ac7d3678290b9f4ba4570a8d1806"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3846",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Naga attacked Talen’s small vessel over Zoram’s drowned ruins. He fled to shore with limited supplies and made a meager camp.",["title"]="Talen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1007:description:1-35","1007:description:40-190","1007:description:193-256","1007:description:261-299","1007:description:301-330","1007:description:335-440","1007:description:443-505","1007:objective:1-72"},["minimumStage"]=2,["questID"]=1007,["sourceHash"]="f1cb0bc84bac5365f39ba5f208fa08385334ac7d3678290b9f4ba4570a8d1806"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3846",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His prized ancient statuette was lost during the escape, though it had been the reason for risking the coast in the first place.",["title"]="Talen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1008:description:1-75","1008:description:80-194","1008:description:197-241","1008:description:244-270","1008:description:275-338","1008:description:341-427","1008:description:432-474","1008:objective:1-61"},["minimumStage"]=2,["questID"]=1008,["sourceHash"]="477aa646970849b31a416fb3a266897502ea42b23a1b828fe5c548fd20bb6a45"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3845",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shindrell remembered Zoram as a doomed city submerged in the Sundering and nearly forgotten by the night elves.",["title"]="Shindrell Swiftfire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1008:description:1-75","1008:description:80-194","1008:description:197-241","1008:description:244-270","1008:description:275-338","1008:description:341-427","1008:description:432-474","1008:objective:1-61"},["minimumStage"]=2,["questID"]=1008,["sourceHash"]="477aa646970849b31a416fb3a266897502ea42b23a1b828fe5c548fd20bb6a45"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3845",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The naga’s return to its strand alarmed her, even though she did not know their purpose.",["title"]="Shindrell Swiftfire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1010:description:1-81","1010:description:84-164","1010:description:169-260","1010:description:263-326","1010:description:329-370","1010:description:375-461","1010:objective:1-57"},["minimumStage"]=2,["questID"]=1010,["sourceHash"]="46c7f301dfa8140a2ca9bf01067888b782974fdf1cdf4f05f52ba9def8d12883"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3847",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Orendil sought Bathran’s Hair to treat a child whose illness he suspected reached beyond the physical.",["title"]="Orendil Broadleaf"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1010:description:1-81","1010:description:84-164","1010:description:169-260","1010:description:263-326","1010:description:329-370","1010:description:375-461","1010:objective:1-57"},["minimumStage"]=2,["questID"]=1010,["sourceHash"]="46c7f301dfa8140a2ca9bf01067888b782974fdf1cdf4f05f52ba9def8d12883"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3847",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He knew the plant for healing ailments of the spirit and directed the search toward the ruins north of Maestra’s Post.",["title"]="Orendil Broadleaf"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1016:description:1-76","1016:description:78-191","1016:description:196-252","1016:description:254-376","1016:description:378-436","1016:description:438-499","1016:objective:1-71","1016:objective:73-164"},["minimumStage"]=2,["questID"]=1016,["sourceHash"]="a65a8fdb31b05c2e1f2b0a4c8395781032aae4eecb982eabfa84901333fdce80"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3885",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Velene used a divining scroll focused through intact elemental bracers to identify the beings’ creator.",["title"]="Sentinel Velene Starstrike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1016:description:1-76","1016:description:78-191","1016:description:196-252","1016:description:254-376","1016:description:378-436","1016:description:438-499","1016:objective:1-71","1016:objective:73-164"},["minimumStage"]=2,["questID"]=1016,["sourceHash"]="a65a8fdb31b05c2e1f2b0a4c8395781032aae4eecb982eabfa84901333fdce80"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3885",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted the divination’s results before deciding how the investigation should proceed.",["title"]="Sentinel Velene Starstrike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1022:description:1-143","1022:description:145-214","1022:description:219-333","1022:description:335-405","1022:description:407-502","1022:objective:1-118"},["minimumStage"]=2,["questID"]=1022,["sourceHash"]="4fe69627c8f14167520b33490bfb87409d6131fc422eb44d1b15ac13bf105937"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3880",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Melyria’s efforts helped keep demons from Ashenvale, but the ruined shrine near Felwood had fallen to mysterious wolf-men.",["title"]="Sentinel Melyria Frostshadow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1022:description:1-143","1022:description:145-214","1022:description:219-333","1022:description:335-405","1022:description:407-502","1022:objective:1-118"},["minimumStage"]=2,["questID"]=1022,["sourceHash"]="4fe69627c8f14167520b33490bfb87409d6131fc422eb44d1b15ac13bf105937"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3880",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She sought the Tome of Mel’Thandris at the shrine to explain the creatures now haunting the Howling Vale.",["title"]="Sentinel Melyria Frostshadow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1026:description:1-32","1026:description:37-134","1026:description:136-186","1026:description:191-300","1026:description:305-376","1026:description:378-461","1026:description:463-502","1026:objective:1-95"},["minimumStage"]=2,["questID"]=1026,["sourceHash"]="8e0391d25a66747e7d6635f53b7e2581cfc1a792d50753f3ddbd66c7a7ab0fd2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3916",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shael’dryn remembered Dartol’s rod and the once-familiar treants, now corrupted near the Felwood border.",["title"]="Shael'dryn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1026:description:1-32","1026:description:37-134","1026:description:136-186","1026:description:191-300","1026:description:305-376","1026:description:378-461","1026:description:463-502","1026:objective:1-95"},["minimumStage"]=2,["questID"]=1026,["sourceHash"]="8e0391d25a66747e7d6635f53b7e2581cfc1a792d50753f3ddbd66c7a7ab0fd2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3916",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The next rod fragment lay in a chest whose wooden key was carried by one of those treants.",["title"]="Shael'dryn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1038:description:1-41","1038:description:43-121","1038:description:123-219","1038:description:221-311","1038:description:316-443","1038:description:445-502","1038:objective:1-119"},["minimumStage"]=2,["questID"]=1038,["sourceHash"]="17d1e5b45f1d06b1944c1a607131a3a6b29cb67a1adee68e28568f4c6a73dbf8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-8026",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thyn’tel trusted Velinde’s record of service and said the Sentinels expected her return rather than assuming desertion.",["title"]="Thyn'tel Bladeweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1038:description:1-41","1038:description:43-121","1038:description:123-219","1038:description:221-311","1038:description:316-443","1038:description:445-502","1038:objective:1-119"},["minimumStage"]=2,["questID"]=1038,["sourceHash"]="17d1e5b45f1d06b1944c1a607131a3a6b29cb67a1adee68e28568f4c6a73dbf8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8026",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Velinde’s belongings and duty journal remained locked in a chest in the Sentinels’ bunkhouse, available through Thyn’tel’s key.",["title"]="Thyn'tel Bladeweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1041:description:1-80","1041:description:85-151","1041:description:153-290","1041:description:295-353","1041:description:355-397","1041:description:399-426","1041:description:431-503","1041:objective:1-37"},["minimumStage"]=2,["questID"]=1041,["sourceHash"]="c41f436fb1f317d3596d95d1e65f87acc12f4e8ef63957f81a0c45574e0037d0"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3945",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Velinde traveled partway north with Ruzzgot’s caravan before leaving it for Darkshire.",["title"]="Caravaneer Ruzzgot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1041:description:1-80","1041:description:85-151","1041:description:153-290","1041:description:295-353","1041:description:355-397","1041:description:399-426","1041:description:431-503","1041:objective:1-37"},["minimumStage"]=2,["questID"]=1041,["sourceHash"]="c41f436fb1f317d3596d95d1e65f87acc12f4e8ef63957f81a0c45574e0037d0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3945",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recalled the unusual night elf passenger and recommended Darkshire’s clerk as the next source of information.",["title"]="Caravaneer Ruzzgot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1042:description:1-74","1042:description:76-203","1042:description:208-278","1042:description:280-349","1042:description:351-383","1042:description:385-435","1042:description:437-488","1042:objective:1-41"},["minimumStage"]=2,["questID"]=1042,["sourceHash"]="e7f186dcb8514eb9bf11381bdcf3d0eee31e8072432117cc7c998229d6386a29"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-267",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Daltry kept Darkshire’s records and had no lodging entry for Velinde Starsong.",["title"]="Clerk Daltry"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1042:description:1-74","1042:description:76-203","1042:description:208-278","1042:description:280-349","1042:description:351-383","1042:description:385-435","1042:description:437-488","1042:objective:1-41"},["minimumStage"]=2,["questID"]=1042,["sourceHash"]="e7f186dcb8514eb9bf11381bdcf3d0eee31e8072432117cc7c998229d6386a29"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-267",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He knew Calor worked with the Carevins, a household of demon and undead hunters led by Jonathan.",["title"]="Clerk Daltry"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1042:description:1-74","1042:description:76-203","1042:description:208-278","1042:description:280-349","1042:description:351-383","1042:description:385-435","1042:description:437-488","1042:objective:1-41"},["minimumStage"]=2,["questID"]=1042,["sourceHash"]="e7f186dcb8514eb9bf11381bdcf3d0eee31e8072432117cc7c998229d6386a29"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-661",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jonathan headed the Carevin household, whose hunters opposed demons, undead and other monsters in Duskwood.",["title"]="Jonathan Carevin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1043:description:1-24","1043:description:26-202","1043:description:207-271","1043:description:273-361","1043:description:366-463","1043:description:465-511","1043:objective:1-83"},["minimumStage"]=2,["questID"]=1043,["sourceHash"]="754cdaf2e426eadfc20ae6e47840d28ac79dbf94072b38f332d33ca1311ff769"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-661",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He welcomed help against the worgen-infested southern mine and asked that anything significant found there be shared with him.",["title"]="Jonathan Carevin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1045:description:1-82","1045:description:84-117","1045:description:119-157","1045:description:162-234","1045:description:236-292","1045:description:297-328","1045:description:330-353","1045:description:355-396","1045:description:398-497","1045:objective:1-82"},["minimumStage"]=2,["questID"]=1045,["sourceHash"]="9de7025283bc4846e90bdc9c1370417d57222ac77dd3293285ddb19d185c48ea"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3897",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krolg blamed elven arrogance for much of the corruption yet insisted that his own people remained responsible for their choices.",["title"]="Krolg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1045:description:1-82","1045:description:84-117","1045:description:119-157","1045:description:162-234","1045:description:236-292","1045:description:297-328","1045:description:330-353","1045:description:355-396","1045:description:398-497","1045:objective:1-82"},["minimumStage"]=2,["questID"]=1045,["sourceHash"]="9de7025283bc4846e90bdc9c1370417d57222ac77dd3293285ddb19d185c48ea"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3897",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He opposed Ran Bloodtooth’s hunger for power and sought to protect even the elves’ children by confronting evil within his own kin.",["title"]="Krolg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1049:description:1-66","1049:description:68-155","1049:description:160-232","1049:description:234-256","1049:description:258-329","1049:description:334-434","1049:description:436-510","1049:objective:1-124"},["minimumStage"]=2,["questID"]=1049,["sourceHash"]="16e205117ab6bfc68b53a92f042c79b806476a2d759673af2adda327858023e6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3978",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Truthseeker questioned whether the Horde had allied with the Forsaken too quickly and wondered who influenced the Elder Council.",["title"]="Sage Truthseeker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1049:description:1-66","1049:description:68-155","1049:description:160-232","1049:description:234-256","1049:description:258-329","1049:description:334-434","1049:description:436-510","1049:objective:1-124"},["minimumStage"]=2,["questID"]=1049,["sourceHash"]="16e205117ab6bfc68b53a92f042c79b806476a2d759673af2adda327858023e6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3978",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought the Scarlet Monastery’s Compendium of the Fallen, judging its research potentially useful despite the zealots’ madness.",["title"]="Sage Truthseeker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1050:description:1-25","1050:description:27-95","1050:description:100-200","1050:description:205-314","1050:description:316-419","1050:description:424-497","1050:objective:1-104"},["minimumStage"]=2,["questID"]=1050,["sourceHash"]="d3f78f7ef80dc178781cfc97c641c8fe30e2ecfcddb7442957728ae281e24d1f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3979",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mae sought Mythology of the Titans from the old monastery library, hoping knowledge of the past could better prepare Ironforge for the future.",["title"]="Librarian Mae Paledust"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1053:description:1-64","1053:description:66-136","1053:description:141-248","1053:description:250-327","1053:description:329-402","1053:description:408-468","1053:description:470-511","1053:objective:1-169"},["minimumStage"]=2,["questID"]=1053,["sourceHash"]="993e1204bfe5f91c4e937c1cc9d97326687b9712fd6dc81c8777a86b6fc3453f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3980",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Raleigh had served the Scarlet Crusade with pride before witnessing its torture of innocent people.",["title"]="Raleigh the Devout"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1053:description:1-64","1053:description:66-136","1053:description:141-248","1053:description:250-327","1053:description:329-402","1053:description:408-468","1053:description:470-511","1053:objective:1-169"},["minimumStage"]=2,["questID"]=1053,["sourceHash"]="993e1204bfe5f91c4e937c1cc9d97326687b9712fd6dc81c8777a86b6fc3453f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3980",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He rejected its belief that anyone outside the Scarlet tabard carried the plague and called for its leaders’ defeat in the Light’s name.",["title"]="Raleigh the Devout"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1056:description:1-63","1056:description:68-153","1056:description:155-251","1056:description:253-375","1056:description:380-408","1056:description:410-430","1056:description:435-463","1056:objective:1-45"},["minimumStage"]=2,["questID"]=1056,["sourceHash"]="cc407b6f78f514198a917636f7feb866c5f3064580f276afb3dca7989ee0f798"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3996",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Faldreas guided travelers to Keeper Albagorm at Stonetalon Peak.",["title"]="Faldreas Goeth'Shael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1056:description:1-63","1056:description:68-153","1056:description:155-251","1056:description:253-375","1056:description:380-408","1056:description:410-430","1056:description:435-463","1056:objective:1-45"},["minimumStage"]=2,["questID"]=1056,["sourceHash"]="cc407b6f78f514198a917636f7feb866c5f3064580f276afb3dca7989ee0f798"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3996",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His directions passed through Talondeep Path into Windshear Crag, then beyond Cragpool Lake toward the steep ascent.",["title"]="Faldreas Goeth'Shael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1058:description:1-16","1058:description:21-62","1058:description:64-121","1058:description:123-156","1058:description:158-180","1058:description:182-194","1058:description:199-238","1058:description:240-298","1058:description:300-378","1058:description:380-438","1058:description:443-504","1058:objective:1-131"},["minimumStage"]=2,["questID"]=1058,["sourceHash"]="00208a292c981783160c8c0638f7c134da98bbc3cc3443d91b8ba2bcf5c69b59"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3995",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jin’Zil planned his mocking version of forest magic for three elves, requiring sap, feline whiskers, courser eyes and a fey dragon scale.",["title"]="Witch Doctor Jin'Zil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1061:description:1-120","1061:description:123-188","1061:description:190-200","1061:description:205-280","1061:description:283-362","1061:description:367-393","1061:description:396-457","1061:description:460-497","1061:objective:1-58"},["minimumStage"]=2,["questID"]=1061,["sourceHash"]="28f0a56ae391b67f332b7f399cb81c568a30d4184780bef52cb365840cebdcdf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4047",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zor answered the Stonetalon spirits’ distress by seeking help for Seereth’s investigation of goblin deforestation.",["title"]="Zor Lonetree"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1061:description:1-120","1061:description:123-188","1061:description:190-200","1061:description:205-280","1061:description:283-362","1061:description:367-393","1061:description:396-457","1061:description:460-497","1061:objective:1-58"},["minimumStage"]=2,["questID"]=1061,["sourceHash"]="28f0a56ae391b67f332b7f399cb81c568a30d4184780bef52cb365840cebdcdf"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4047",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described Seereth as a promising Horde shaman sent to the mountains, camped near Greatwood Vale.",["title"]="Zor Lonetree"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1062:description:1-125","1062:description:128-189","1062:description:192-224","1062:description:229-298","1062:description:301-420","1062:description:423-471","1062:description:476-484","1062:objective:1-19","1062:objective:21-107"},["minimumStage"]=2,["questID"]=1062,["sourceHash"]="1faa271a72cbef5ee863e99435762437e2c3f3f6f127e48779978e05ca2f71cc"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4049",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Seereth saw the Venture Company’s logging and burning as an exploitation that left Stonetalon’s spirits nearly blind with pain.",["title"]="Seereth Stonebreak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1062:description:1-125","1062:description:128-189","1062:description:192-224","1062:description:229-298","1062:description:301-420","1062:description:423-471","1062:description:476-484","1062:objective:1-19","1062:objective:21-107"},["minimumStage"]=2,["questID"]=1062,["sourceHash"]="1faa271a72cbef5ee863e99435762437e2c3f3f6f127e48779978e05ca2f71cc"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4049",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She called for force against the goblins and their servants at Windshear Crag after their advance beyond Greatwood Vale.",["title"]="Seereth Stonebreak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1064:description:1-85","1064:description:88-162","1064:description:167-230","1064:description:233-258","1064:description:261-353","1064:description:358-385","1064:description:388-436","1064:description:439-501","1064:objective:1-68"},["minimumStage"]=2,["questID"]=1064,["sourceHash"]="8911865c385b1511b9287748f46c036ea2fdfb4da70f5e0b6b566761b008a99f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4046",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magatha hoped Forsaken knowledge of disease could help Stonetalon and strengthen trust between the allied peoples.",["title"]="Magatha Grimtotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1064:description:1-85","1064:description:88-162","1064:description:167-230","1064:description:233-258","1064:description:261-353","1064:description:358-385","1064:description:388-436","1064:description:439-501","1064:objective:1-68"},["minimumStage"]=2,["questID"]=1064,["sourceHash"]="8911865c385b1511b9287748f46c036ea2fdfb4da70f5e0b6b566761b008a99f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4046",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She recommended Zamah as both a scholar and Forsaken emissary working beneath Thunder Bluff’s Spirit Rise.",["title"]="Magatha Grimtotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1010:description:1-81","1010:description:84-164","1010:description:169-260","1010:description:263-326","1010:description:329-370","1010:description:375-461","1010:objective:1-57"},["minimumStage"]=2,["questID"]=1010,["sourceHash"]="46c7f301dfa8140a2ca9bf01067888b782974fdf1cdf4f05f52ba9def8d12883"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-411",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Orendil sought the plant Bathran’s Hair among these old ruins, relying on its reputation for treating ailments of the spirit.",["title"]="Bathran's Haunt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1022:description:1-143","1022:description:145-214","1022:description:219-333","1022:description:335-405","1022:description:407-502","1022:objective:1-118"},["minimumStage"]=2,["questID"]=1022,["sourceHash"]="4fe69627c8f14167520b33490bfb87409d6131fc422eb44d1b15ac13bf105937"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-419",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wolf-men occupied the ruined shrine of Mel’Thandris near the Felwood border; their chilling calls gave the vale its newer name.",["title"]="The Howling Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1022:description:1-143","1022:description:145-214","1022:description:219-333","1022:description:335-405","1022:description:407-502","1022:objective:1-118"},["minimumStage"]=2,["questID"]=1022,["sourceHash"]="4fe69627c8f14167520b33490bfb87409d6131fc422eb44d1b15ac13bf105937"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-419",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The shrine’s surviving tome offered Melyria a possible explanation for the creatures’ arrival.",["title"]="The Howling Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1008:description:1-75","1008:description:80-194","1008:description:197-241","1008:description:244-270","1008:description:275-338","1008:description:341-427","1008:description:432-474","1008:objective:1-61"},["minimumStage"]=2,["questID"]=1008,["sourceHash"]="477aa646970849b31a416fb3a266897502ea42b23a1b828fe5c548fd20bb6a45"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-414",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The drowned city of Zoram lay along this coast, lost in the Sundering and nearly forgotten by the night elves.",["title"]="The Zoram Strand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1007:description:1-35","1007:description:40-190","1007:description:193-256","1007:description:261-299","1007:description:301-330","1007:description:335-440","1007:description:443-505","1007:objective:1-72"},["minimumStage"]=2,["questID"]=1007,["sourceHash"]="f1cb0bc84bac5365f39ba5f208fa08385334ac7d3678290b9f4ba4570a8d1806"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-414",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Naga surged from the water to attack Talen’s vessel above the ruins, driving him ashore and separating him from his statuette.",["title"]="The Zoram Strand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"916:description:1-88","916:description:91-255","916:description:260-299","916:description:302-394","916:description:397-471","916:objective:1-65"},["minimumStage"]=2,["questID"]=916,["sourceHash"]="ead609376ee13e72ee8a8222742701e35af2d949766a15fd2f94390cd67d183d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="shadowthread-cave",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gilshalan studied the cave’s webwood spiders to test whether the World Tree had altered relatives of a smaller spider variety.",["title"]="Shadowthread Cave"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1056:description:1-63","1056:description:68-153","1056:description:155-251","1056:description:253-375","1056:description:380-408","1056:description:410-430","1056:description:435-463","1056:objective:1-45"},["minimumStage"]=2,["questID"]=1056,["sourceHash"]="cc407b6f78f514198a917636f7feb866c5f3064580f276afb3dca7989ee0f798"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-1276",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The tunnel south of Ashenvale’s Mystral Lake opened into Windshear Crag in the Stonetalon Mountains.",["title"]="The Talondeep Path"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1061:description:1-120","1061:description:123-188","1061:description:190-200","1061:description:205-280","1061:description:283-362","1061:description:367-393","1061:description:396-457","1061:description:460-497","1061:objective:1-58"},["minimumStage"]=2,["questID"]=1061,["sourceHash"]="28f0a56ae391b67f332b7f399cb81c568a30d4184780bef52cb365840cebdcdf"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-469",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Seereth camped near the vale while reporting Stonetalon’s deforestation to Zor in Orgrimmar.",["title"]="Greatwood Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1062:description:1-125","1062:description:128-189","1062:description:192-224","1062:description:229-298","1062:description:301-420","1062:description:423-471","1062:description:476-484","1062:objective:1-19","1062:objective:21-107"},["minimumStage"]=2,["questID"]=1062,["sourceHash"]="1faa271a72cbef5ee863e99435762437e2c3f3f6f127e48779978e05ca2f71cc"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-461",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Venture Company crews cut and burned the forest here, drawing the Horde shamans’ demand that the exploitation stop.",["title"]="Windshear Crag"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1056:description:1-63","1056:description:68-153","1056:description:155-251","1056:description:253-375","1056:description:380-408","1056:description:410-430","1056:description:435-463","1056:objective:1-45"},["minimumStage"]=2,["questID"]=1056,["sourceHash"]="cc407b6f78f514198a917636f7feb866c5f3064580f276afb3dca7989ee0f798"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-463",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Faldreas’s route from Windshear passed southwest by the lake before turning north to the steep climb toward Stonetalon Peak.",["title"]="Cragpool Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1056:description:1-63","1056:description:68-153","1056:description:155-251","1056:description:253-375","1056:description:380-408","1056:description:410-430","1056:description:435-463","1056:objective:1-45"},["minimumStage"]=2,["questID"]=1056,["sourceHash"]="cc407b6f78f514198a917636f7feb866c5f3064580f276afb3dca7989ee0f798"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-467",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keeper Albagorm awaited travelers directed through the mountains by Faldreas.",["title"]="Stonetalon Peak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"834:description:1-34","834:description:36-81","834:description:83-131","834:description:133-163","834:description:165-203","834:description:208-333","834:description:338-397","834:description:399-509","834:objective:1-70"},["minimumStage"]=2,["questID"]=834,["sourceHash"]="e5b5c788f2c2d86b416e43c86d648f4957a8bb3f4808d793283f220bd101ebc2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-410",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dustwind harpies carried off Rezlak’s supplies into the canyon, interrupting the work Gazlowe had sent him to support.",["title"]="Razorwind Canyon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"786:description:1-21","786:description:23-93","786:description:98-266","786:description:271-317","786:description:319-415","786:description:420-487","786:objective:1-113"},["minimumStage"]=2,["questID"]=786,["sourceHash"]="269d87615cb2ec5e08cd1cdeabeafcbe95721f4a152d6e5b7da957e6560218cf"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-366",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lar’s infiltration uncovered three sets of plans for attacks on Durotar’s orcs and trolls, each held by a Kolkar leader.",["title"]="Kolkar Crag"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"809:description:1-128","809:description:131-174","809:description:179-263","809:description:266-344","809:description:347-367","809:description:372-474","809:description:477-503","809:objective:1-36"},["minimumStage"]=2,["questID"]=809,["sourceHash"]="912fa453c13f3ff0cbac71e6ed3e8f206bb50d9ff66d060167c501a147ffd120"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-384",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Neeru placed the Burning Blade’s Demon Seed on the peak in his public account of the cult’s power.",["title"]="Dreadmist Peak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"747:description:1-73","747:description:75-153","747:description:155-234","747:description:239-306","747:description:308-350","747:description:352-420","747:description:422-497","747:objective:1-112"},["minimumStage"]=2,["questID"]=747,["sourceHash"]="388363002d18677f5bc6e65eb6984093ca4cc55741ac1877de5173966887f601"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-220",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Hawkwinds joined young hunters’ trials to the mesa village’s need for plainstrider meat and clothing feathers.",["title"]="Red Cloud Mesa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"891:description:1-92","891:description:97-130","891:description:132-176","891:description:178-248","891:description:253-332","891:description:334-380","891:description:382-465","891:objective:1-148"},["minimumStage"]=2,["questID"]=891,["sourceHash"]="d8d6e96b6b803fc134a5259e9e9db30088996459b84fc26fd4be36bff5b26004"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-391",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brightsun blamed Northwatch’s guns along the coast for losses to his fleet and sought retaliation against the hold’s gunners.",["title"]="The Merchant Coast"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"851:description:1-81","851:description:84-166","851:description:169-206","851:description:211-297","851:description:300-388","851:description:391-410","851:description:415-474","851:objective:1-64"},["minimumStage"]=2,["questID"]=851,["sourceHash"]="d58817d8dcb606a2d1c813dc883592350deac925877ad7bf5bc7220e9a5443d1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-388",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Verog’s command tent stood at the oasis; Regthar proposed provoking an alarm there to draw the wandering centaur back.",["title"]="The Stagnant Oasis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"749:description:1-38","749:description:40-109","749:description:111-216","749:description:221-334","749:description:336-407","749:description:412-486","749:objective:1-94"},["minimumStage"]=2,["questID"]=749,["sourceHash"]="2472b9c3e3b2787c3545eb4df3521eacb0c6ed0ad7a67ce1b47d9a32695f3664"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-223",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Morin’s fighters burned a guarded Venture Company caravan on the northern shore, then found salvagers returning to what they had left behind.",["title"]="Stonebull Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5056:description:1-93","5056:description:95-150","5056:description:152-253","5056:description:258-342","5056:description:344-391","5056:description:393-463","5056:description:468-505","5056:objective:1-75"},["minimumStage"]=2,["questID"]=5056,["sourceHash"]="621cf1b02ef3ef91000b1bc0c00d162a9811022630034156e62ecce1e27d4d9a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-2241",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The great cats of northern Winterspring gathered around the rock under Shy-Rotam’s leadership.",["title"]="Frostsaber Rock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1070:description:1-10","1070:description:15-68","1070:description:70-111","1070:description:113-151","1070:description:153-189","1070:description:194-349","1070:description:351-430","1070:description:432-458","1070:description:463-503","1070:objective:1-98"},["minimumStage"]=2,["questID"]=1070,["sourceHash"]="4788cca92e7f43d87fac6eb27b53e4ab44cc36b6b6189272567b69768a5a8cf7"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4079",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thenysil worried for Kaela Shadowspear, sent by Wolfrunner to investigate Stonetalon with an Alliance gnome mage.",["title"]="Sentinel Thenysil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1070:description:1-10","1070:description:15-68","1070:description:70-111","1070:description:113-151","1070:description:153-189","1070:description:194-349","1070:description:351-430","1070:description:432-458","1070:description:463-503","1070:objective:1-98"},["minimumStage"]=2,["questID"]=1070,["sourceHash"]="4788cca92e7f43d87fac6eb27b53e4ab44cc36b6b6189272567b69768a5a8cf7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4079",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The lack of a reply deepened her concern over the Venture Company’s damage and prompted her to seek someone who could find her friend.",["title"]="Sentinel Thenysil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1071:description:1-122","1071:description:124-136","1071:description:138-237","1071:description:242-317","1071:description:319-372","1071:description:377-414","1071:description:416-507","1071:objective:1-19","1071:objective:21-47","1071:objective:49-105"},["minimumStage"]=2,["questID"]=1071,["sourceHash"]="d8b545412954d98dd374b43f94c7955e8a0e7b01976066270b691678faa78f6f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4077",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gaxim belonged to the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences.",["title"]="Gaxim Rustfizzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1071:description:1-122","1071:description:124-136","1071:description:138-237","1071:description:242-317","1071:description:319-372","1071:description:377-414","1071:description:416-507","1071:objective:1-19","1071:objective:21-47","1071:objective:49-105"},["minimumStage"]=2,["questID"]=1071,["sourceHash"]="d8b545412954d98dd374b43f94c7955e8a0e7b01976066270b691678faa78f6f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4077",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted to show the night elves that magic, mixtures and machinery could protect their forests, but needed the Windshear goblins held back long enough to build his inventions.",["title"]="Gaxim Rustfizzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1073:description:1-9","1073:description:11-81","1073:description:86-125","1073:description:127-205","1073:description:210-247","1073:description:252-350","1073:description:355-478","1073:objective:1-92"},["minimumStage"]=2,["questID"]=1073,["sourceHash"]="3030acc2ad45ce24c4c5ba6da2f0d7b6064417e558dc72ef5b913d264ec44c0b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4081",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lomac offered to make Nitromirglyceronium from the proper potions, treating the request as proof of an alchemist’s skill and an opportunity for a spectacular explosion.",["title"]="Lomac Gearstrip"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1076:description:1-22","1076:description:24-43","1076:description:45-89","1076:description:94-155","1076:description:157-202","1076:description:207-315","1076:description:317-447","1076:description:452-480","1076:objective:1-54"},["minimumStage"]=2,["questID"]=1076,["sourceHash"]="a6022f4621cffa6d188abcb9cf3b458a0faa13d16b5d3d86b5546745fe8614af"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4078",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Collin needed dust devil debris for a scroll carrying the messaging spell sought for Gaxim’s project.",["title"]="Collin Mauren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1076:description:1-22","1076:description:24-43","1076:description:45-89","1076:description:94-155","1076:description:157-202","1076:description:207-315","1076:description:317-447","1076:description:452-480","1076:objective:1-54"},["minimumStage"]=2,["questID"]=1076,["sourceHash"]="a6022f4621cffa6d188abcb9cf3b458a0faa13d16b5d3d86b5546745fe8614af"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4078",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He gathered the other components while directing the dangerous reagent search toward Westfall.",["title"]="Collin Mauren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1087:description:1-63","1087:description:65-225","1087:description:227-248","1087:description:253-386","1087:description:391-463","1087:description:465-509","1087:objective:1-117"},["minimumStage"]=2,["questID"]=1087,["sourceHash"]="84847d6d24083b9acddd807f684fa6bbf2082b563f8487584d2efefa2bbb796c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4198",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Braelyn hated Stonetalon’s druids, accusing Cenarius’s followers of stifling the flow of magic through the forests.",["title"]="Braelyn Firehand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1087:description:1-63","1087:description:65-225","1087:description:227-248","1087:description:253-386","1087:description:391-463","1087:description:465-509","1087:objective:1-117"},["minimumStage"]=2,["questID"]=1087,["sourceHash"]="84847d6d24083b9acddd807f684fa6bbf2082b563f8487584d2efefa2bbb796c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4198",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted to return to Jaedenar but said her master would not permit it until her assigned work was finished.",["title"]="Braelyn Firehand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1090:description:1-72","1090:description:74-113","1090:description:115-180","1090:description:182-237","1090:description:239-312","1090:description:317-417","1090:description:419-510","1090:objective:1-63"},["minimumStage"]=2,["questID"]=1090,["sourceHash"]="067b19b7a37599a174f9bef8b0fdcd69a60754cd66dbb77f12febfca6c736d68"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4276",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Piznik had held a senior position until Gerenzo dismissed Ziz Fizziks and sent him into the mines.",["title"]="Piznik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1090:description:1-72","1090:description:74-113","1090:description:115-180","1090:description:182-237","1090:description:239-312","1090:description:317-417","1090:description:419-510","1090:objective:1-63"},["minimumStage"]=2,["questID"]=1090,["sourceHash"]="067b19b7a37599a174f9bef8b0fdcd69a60754cd66dbb77f12febfca6c736d68"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4276",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Remaining as Ziz’s informant, he offered a sample of the gold-green ore Gerenzo ordered mined if someone would guard him from patrols.",["title"]="Piznik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1097:description:1-109","1097:description:112-174","1097:description:179-208","1097:description:211-274","1097:description:277-359","1097:description:364-481","1097:objective:1-26"},["minimumStage"]=2,["questID"]=1097,["sourceHash"]="8b6ccdcfedb363b0e87cf4d027f9b76b7a4331e3d3c1e04ef61d6fd4215a675a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-514",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Argus sought help for Grimand Elmore’s northern delivery, treating assistance to the dwarven smith as part of maintaining ties between the allied peoples.",["title"]="Smith Argus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1102:description:1-70","1102:description:75-157","1102:description:159-211","1102:description:213-236","1102:description:238-277","1102:description:282-386","1102:description:391-445","1102:objective:1-61"},["minimumStage"]=2,["questID"]=1102,["sourceHash"]="d95d95b30772d3fd880f394b0a51b4f68bf96a89a7f9e07242f05a67f46c6b80"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4451",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Auld’s people had lived on sacred southern Barrens land for decades before enemies drove them away.",["title"]="Auld Stonespire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1102:description:1-70","1102:description:75-157","1102:description:159-211","1102:description:213-236","1102:description:238-277","1102:description:282-386","1102:description:391-445","1102:objective:1-61"},["minimumStage"]=2,["questID"]=1102,["sourceHash"]="d95d95b30772d3fd880f394b0a51b4f68bf96a89a7f9e07242f05a67f46c6b80"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4451",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Though grateful for Cairne’s unification in Thunder Bluff, he could not forgive the displacement and sought Charlga Razorflank’s heart for peace at the end of his life.",["title"]="Auld Stonespire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1103:description:1-28","1103:description:30-111","1103:description:116-248","1103:description:253-263","1103:description:265-269","1103:description:271-325","1103:description:327-410","1103:description:415-510","1103:objective:1-116"},["minimumStage"]=2,["questID"]=1103,["sourceHash"]="e6f96543e89782d78c5138ef9810fdaf2f64ab80c724fa5ffbd86fa223c5afe0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7007",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tiev helped other shamanic initiates reach the pure water spirit if their cleansing rite went wrong.",["title"]="Tiev Mordune"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1103:description:1-28","1103:description:30-111","1103:description:116-248","1103:description:253-263","1103:description:265-269","1103:description:271-325","1103:description:327-410","1103:description:415-510","1103:objective:1-116"},["minimumStage"]=2,["questID"]=1103,["sourceHash"]="e6f96543e89782d78c5138ef9810fdaf2f64ab80c724fa5ffbd86fa223c5afe0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7007",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He had defeated the corrupt manifestation himself and could delay his own offering while another brought Islen’s water sapta as proof of readiness.",["title"]="Tiev Mordune"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1105:description:1-55","1105:description:58-86","1105:description:89-108","1105:description:110-202","1105:description:207-261","1105:description:266-318","1105:description:321-378","1105:description:381-422","1105:description:427-454","1105:description:457-485","1105:objective:1-78"},["minimumStage"]=2,["questID"]=1105,["sourceHash"]="d2a98dfedce7d66fd96bcf2f15c484104ec4b5c5765a2fdabf8fec7c45ac88d1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4453",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wizzle feared his brother’s new fuel could eat through their rocket car’s chassis and wanted hard tortoise shells for safer tanks.",["title"]="Wizzle Brassbolts"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1105:description:1-55","1105:description:58-86","1105:description:89-108","1105:description:110-202","1105:description:207-261","1105:description:266-318","1105:description:321-378","1105:description:381-422","1105:description:427-454","1105:description:457-485","1105:objective:1-78"},["minimumStage"]=2,["questID"]=1105,["sourceHash"]="d2a98dfedce7d66fd96bcf2f15c484104ec4b5c5765a2fdabf8fec7c45ac88d1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4453",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He admired his brother’s brilliance even while preparing against the dangerous strength of the invention.",["title"]="Wizzle Brassbolts"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1110:description:1-107","1110:description:110-244","1110:description:249-306","1110:description:309-377","1110:description:382-408","1110:description:411-448","1110:objective:1-70"},["minimumStage"]=2,["questID"]=1110,["sourceHash"]="a797d1a087b422932713f10f2a05fd8201016b03a080bc20259a15a1f964cdac"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4452",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kravel bought scattered rocket-car wreckage from the Shimmering Flats to supply the gnomish and goblin racers’ modifications.",["title"]="Kravel Koalbeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1124:description:1-84","1124:description:87-181","1124:description:184-255","1124:description:257-275","1124:description:280-418","1124:description:421-485","1124:objective:1-100"},["minimumStage"]=2,["questID"]=1124,["sourceHash"]="090ed09ffffd1d6a1518c23bfbdb3543a904d5e4ffbacefd9b62a4974255805e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11801",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rabine feared that something was stirring the ancient evil sealed in Silithus and sent trusted help to Layo at Valor’s Rest.",["title"]="Rabine Saturna"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1124:description:1-84","1124:description:87-181","1124:description:184-255","1124:description:257-275","1124:description:280-418","1124:description:421-485","1124:objective:1-100"},["minimumStage"]=2,["questID"]=1124,["sourceHash"]="090ed09ffffd1d6a1518c23bfbdb3543a904d5e4ffbacefd9b62a4974255805e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11801",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He connected the wasteland’s present danger with an old war between night elves and an alien power.",["title"]="Rabine Saturna"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1125:description:1-69","1125:description:72-111","1125:description:116-206","1125:description:209-277","1125:description:280-346","1125:description:351-429","1125:description:432-505","1125:objective:1-162"},["minimumStage"]=2,["questID"]=1125,["sourceHash"]="73112336ef3cf93b9869ee32bc4d75903db48624e597e77b5f7c4f445ebe21ed"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-13220",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Layo’s investigation began at Southwind’s silithid-overrun ruins, where the spirits of druids and Sentinels still wandered.",["title"]="Layo Starstrike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1125:description:1-69","1125:description:72-111","1125:description:116-206","1125:description:209-277","1125:description:280-346","1125:description:351-429","1125:description:432-505","1125:objective:1-162"},["minimumStage"]=2,["questID"]=1125,["sourceHash"]="73112336ef3cf93b9869ee32bc4d75903db48624e597e77b5f7c4f445ebe21ed"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13220",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought the release of those tortured souls while exploring the former night elf base.",["title"]="Layo Starstrike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1132:description:1-28","1132:description:31-123","1132:description:128-200","1132:description:205-285","1132:description:288-397","1132:description:400-452","1132:description:457-500","1132:objective:1-72"},["minimumStage"]=2,["questID"]=1132,["sourceHash"]="8c5978689b84f015cdd12bfe1a093db83d72c9157e351dbefbf8d0516a742073"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4455",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Flint encouraged travelers to take ship for Theramore, where his partner Fiora Longears could introduce them to Kalimdor.",["title"]="Red Jack Flint"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1132:description:1-28","1132:description:31-123","1132:description:128-200","1132:description:205-285","1132:description:288-397","1132:description:400-452","1132:description:457-500","1132:objective:1-72"},["minimumStage"]=2,["questID"]=1132,["sourceHash"]="8c5978689b84f015cdd12bfe1a093db83d72c9157e351dbefbf8d0516a742073"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4455",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His longing for wind and waves colored his pitch for the distant land’s opportunities.",["title"]="Red Jack Flint"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1149:description:1-64","1149:description:66-75","1149:description:77-130","1149:description:135-194","1149:description:196-251","1149:description:253-299","1149:description:301-357","1149:description:362-405","1149:description:407-468","1149:description:473-501","1149:objective:1-69"},["minimumStage"]=2,["questID"]=1149,["sourceHash"]="818cb97212ae76deb2858b9c6fd8d6ff21ed9306c951cd493cabd70c6d4f1fb2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2986",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dorn tested a traveler’s faith, body and mind through trials rooted in the traditions used to judge inner strength.",["title"]="Dorn Plainstalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1149:description:1-64","1149:description:66-75","1149:description:77-130","1149:description:135-194","1149:description:196-251","1149:description:253-299","1149:description:301-357","1149:description:362-405","1149:description:407-468","1149:description:473-501","1149:objective:1-69"},["minimumStage"]=2,["questID"]=1149,["sourceHash"]="818cb97212ae76deb2858b9c6fd8d6ff21ed9306c951cd493cabd70c6d4f1fb2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2986",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned that failure carried mortal danger, rather than presenting the trials as harmless ceremonial games.",["title"]="Dorn Plainstalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1154:description:1-71","1154:description:73-82","1154:description:84-136","1154:description:138-206","1154:description:211-311","1154:description:316-345","1154:description:347-372","1154:description:374-486","1154:objective:1-124"},["minimumStage"]=2,["questID"]=1154,["sourceHash"]="4c5993a64378efe38d601ead507a0a61690f66348c137328ba1717497b4c847a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4489",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Braug set tests of learning after Dorn’s physical challenges, requiring a named book to be studied before answering his questions.",["title"]="Braug Dimspirit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1154:description:1-71","1154:description:73-82","1154:description:84-136","1154:description:138-206","1154:description:211-311","1154:description:316-345","1154:description:347-372","1154:description:374-486","1154:objective:1-124"},["minimumStage"]=2,["questID"]=1154,["sourceHash"]="4c5993a64378efe38d601ead507a0a61690f66348c137328ba1717497b4c847a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4489",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Legacy of the Aspects lay deep in Dor’Danil among dead druids and their killers, making scholarship depend on retrieving knowledge from danger.",["title"]="Braug Dimspirit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1160:description:1-116","1160:description:118-163","1160:description:165-261","1160:description:266-317","1160:description:319-394","1160:description:396-472","1160:description:477-491","1160:objective:1-90"},["minimumStage"]=2,["questID"]=1160,["sourceHash"]="4d3e826a4ae35424dc16af109affa3cf1330622ad201a428a10beb11992d8483"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4488",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Parqual valued understanding above strength and sought the Monastery’s Beginnings of the Undead Threat for that reason.",["title"]="Parqual Fintallas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1160:description:1-116","1160:description:118-163","1160:description:165-261","1160:description:266-317","1160:description:319-394","1160:description:396-472","1160:description:477-491","1160:objective:1-90"},["minimumStage"]=2,["questID"]=1160,["sourceHash"]="4d3e826a4ae35424dc16af109affa3cf1330622ad201a428a10beb11992d8483"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4488",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted to examine the text once used to teach the now-corrupt paladins how to fight his kind.",["title"]="Parqual Fintallas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1164:description:1-11","1164:description:13-22","1164:description:24-92","1164:description:94-109","1164:description:114-152","1164:description:154-211","1164:description:213-325","1164:description:330-379","1164:description:381-412","1164:description:417-433","1164:description:435-499","1164:objective:1-80"},["minimumStage"]=2,["questID"]=1164,["sourceHash"]="820a809548ca9d9866cdf5afb0f956735b5afb6d57b56afc41a2e7856a25c427"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4486",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The plague took Genavie’s family, and war left her estate looted and burned.",["title"]="Genavie Callow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1164:description:1-11","1164:description:13-22","1164:description:24-92","1164:description:94-109","1164:description:114-152","1164:description:154-211","1164:description:213-325","1164:description:330-379","1164:description:381-412","1164:description:417-433","1164:description:435-499","1164:objective:1-80"},["minimumStage"]=2,["questID"]=1164,["sourceHash"]="820a809548ca9d9866cdf5afb0f956735b5afb6d57b56afc41a2e7856a25c427"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4486",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She accused Kenata and her children of stealing her last precious belongings, but now demanded revenge against them rather than the objects’ return.",["title"]="Genavie Callow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1168:description:1-39","1168:description:41-86","1168:description:91-119","1168:description:121-138","1168:description:140-165","1168:description:167-184","1168:description:189-206","1168:description:208-233","1168:description:235-272","1168:description:277-305","1168:description:307-330","1168:description:332-351","1168:description:356-397","1168:description:399-414","1168:description:416-434","1168:objective:1-116"},["minimumStage"]=2,["questID"]=1168,["sourceHash"]="63fc9939978aa2dea925054e3b4be6209ffc0395fb2130d0097fd43c61c1914a"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4502",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Black dragons killed Tharg’s wife and drove his people from the Stonemaul ruins.",["title"]="Tharg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1168:description:1-39","1168:description:41-86","1168:description:91-119","1168:description:121-138","1168:description:140-165","1168:description:167-184","1168:description:189-206","1168:description:208-233","1168:description:235-272","1168:description:277-305","1168:description:307-330","1168:description:332-351","1168:description:356-397","1168:description:399-414","1168:description:416-434","1168:objective:1-116"},["minimumStage"]=2,["questID"]=1168,["sourceHash"]="63fc9939978aa2dea925054e3b4be6209ffc0395fb2130d0097fd43c61c1914a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4502",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He resented Mok’Morokk’s retreat and concern for personal power, wanting the ogres to fight and regain their southern home.",["title"]="Tharg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1179:description:1-39","1179:description:42-134","1179:description:137-194","1179:description:199-321","1179:description:324-368","1179:description:371-400","1179:description:405-475","1179:description:478-499","1179:description:504-511","1179:objective:1-78"},["minimumStage"]=2,["questID"]=1179,["sourceHash"]="ecd36ba1563d92cbc6466ca037c363865b222bba57d8f3c2cc64adeea84c44c6"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2092",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Longbeard’s friends, the Brassbolts brothers, sought siege-engine helmets after their fast rocket car repeatedly concussed its pilots.",["title"]="Pilot Longbeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1179:description:1-39","1179:description:42-134","1179:description:137-194","1179:description:199-321","1179:description:324-368","1179:description:371-400","1179:description:405-475","1179:description:478-499","1179:description:504-511","1179:objective:1-78"},["minimumStage"]=2,["questID"]=1179,["sourceHash"]="ecd36ba1563d92cbc6466ca037c363865b222bba57d8f3c2cc64adeea84c44c6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2092",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His own duties prevented the journey to the Shimmering Flats, leaving the delivery to another traveler.",["title"]="Pilot Longbeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1187:description:1-111","1187:description:113-127","1187:description:132-308","1187:description:313-462","1187:description:464-483","1187:objective:1-68"},["minimumStage"]=2,["questID"]=1187,["sourceHash"]="461adf99c89cdbced3d9cb45715511999a751dfba1e61d5c926e5e9693c2442a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4706",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Razzeric made Pozzik’s racers more reckless by loosening controls, stripping frame parts and adding power.",["title"]="Razzeric"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1187:description:1-111","1187:description:113-127","1187:description:132-308","1187:description:313-462","1187:description:464-483","1187:objective:1-68"},["minimumStage"]=2,["questID"]=1187,["sourceHash"]="461adf99c89cdbced3d9cb45715511999a751dfba1e61d5c926e5e9693c2442a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4706",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted a seaforium booster recovered from the Dustwallow zeppelin wreck after its shipment from Shreev failed to arrive.",["title"]="Razzeric"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1195:description:1-109","1195:description:114-214","1195:description:219-370","1195:description:372-490","1195:objective:1-66"},["minimumStage"]=2,["questID"]=1195,["sourceHash"]="78ed8423acff3f1b4a13ca435cc91b7ca7ffc1ac6555d46733db0dac927b5550"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4721",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zangen sought a Galak relic but first required moonwell water carried in a dryad’s phial.",["title"]="Zangen Stonehoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1195:description:1-109","1195:description:114-214","1195:description:219-370","1195:description:372-490","1195:objective:1-66"},["minimumStage"]=2,["questID"]=1195,["sourceHash"]="78ed8423acff3f1b4a13ca435cc91b7ca7ffc1ac6555d46733db0dac927b5550"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4721",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His instructions joined Raynewood’s dryads with the moonwell beside the Falfarren River as preparations for the centaur stronghold.",["title"]="Zangen Stonehoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1197:description:1-106","1197:description:108-184","1197:description:189-265","1197:description:267-338","1197:description:343-473","1197:objective:1-66"},["minimumStage"]=2,["questID"]=1197,["sourceHash"]="125b9cae3c52fda7b9852f556fa0f66bc5dd2c740f3315f54491deaa96bca7f4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4722",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rau explained that moonwell water could briefly quench the flame protecting the centaur relic, leaving only a short chance to retrieve it.",["title"]="Rau Cliffrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1197:description:1-106","1197:description:108-184","1197:description:189-265","1197:description:267-338","1197:description:343-473","1197:objective:1-66"},["minimumStage"]=2,["questID"]=1197,["sourceHash"]="125b9cae3c52fda7b9852f556fa0f66bc5dd2c740f3315f54491deaa96bca7f4"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-4722",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the attempt toward heavily guarded Splithoof Hold inside Splithoof Crag.",["title"]="Rau Cliffrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1198:description:1-135","1198:description:140-258","1198:description:263-351","1198:description:353-400","1198:description:405-458","1198:description:463-499","1198:objective:1-52"},["minimumStage"]=2,["questID"]=1198,["sourceHash"]="90e3053f1b01884a9e92f6fe86e2c879608b987a80d982ad3aef23e4f6f64de6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4786",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shaedlass gathered information for the Argent Dawn to learn where and when assistance was needed.",["title"]="Dawnwatcher Shaedlass"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1198:description:1-135","1198:description:140-258","1198:description:263-351","1198:description:353-400","1198:description:405-458","1198:description:463-499","1198:objective:1-52"},["minimumStage"]=2,["questID"]=1198,["sourceHash"]="90e3053f1b01884a9e92f6fe86e2c879608b987a80d982ad3aef23e4f6f64de6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4786",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thaelrid had failed to return from scouting the rumored naga and Twilight’s Hammer alliance at Blackfathom, while the other scouts were occupied.",["title"]="Dawnwatcher Shaedlass"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1199:description:1-192","1199:description:197-323","1199:description:328-401","1199:description:406-463","1199:description:465-505","1199:objective:1-64"},["minimumStage"]=2,["questID"]=1199,["sourceHash"]="63e74c5f3d6990f191ef152bdc1c7d83da37ea41292af81e13a2f255c5e16304"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4784",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Manados sought to disrupt the Twilight’s Hammer’s gathering at Blackfathom before its unknown plan could advance.",["title"]="Argent Guard Manados"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1199:description:1-192","1199:description:197-323","1199:description:328-401","1199:description:406-463","1199:description:465-505","1199:objective:1-64"},["minimumStage"]=2,["questID"]=1199,["sourceHash"]="63e74c5f3d6990f191ef152bdc1c7d83da37ea41292af81e13a2f255c5e16304"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4784",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He understood the cult’s purpose as restoring the Old Gods and suspected a local alliance with the naga.",["title"]="Argent Guard Manados"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1200:description:1-21","1200:description:23-42","1200:description:47-93","1200:description:95-221","1200:description:226-279","1200:description:284-364","1200:description:366-435","1200:description:440-506","1200:objective:1-75"},["minimumStage"]=2,["questID"]=1200,["sourceHash"]="4ed07e95391181d46c42d82a0399b689b501eb65291a600ec6369446d3aaaf22"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4787",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thaelrid described Blackfathom as a former temple of Elune whose sacred moonwell was corrupted from beneath the earth.",["title"]="Argent Guard Thaelrid"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1200:description:1-21","1200:description:23-42","1200:description:47-93","1200:description:95-221","1200:description:226-279","1200:description:284-364","1200:description:366-435","1200:description:440-506","1200:objective:1-75"},["minimumStage"]=2,["questID"]=1200,["sourceHash"]="4ed07e95391181d46c42d82a0399b689b501eb65291a600ec6369446d3aaaf22"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4787",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Weakened and unable to act alone, he sought help against Kelris and the cultists sacrificing innocents to Aku’Mai.",["title"]="Argent Guard Thaelrid"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1204:description:1-97","1204:description:99-166","1204:description:171-209","1204:description:212-256","1204:description:259-319","1204:description:324-357","1204:description:360-413","1204:description:418-505","1204:objective:1-60"},["minimumStage"]=2,["questID"]=1204,["sourceHash"]="f0df4f97eb3f52d6d927c4e073c3b60cd3bf9ef7ae96d4faa30e2b387ebe8b4a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4794",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Morgan developed a dish of mudrock soup and bugs, seeking unusual ingredients rather than ordinary turtle meat.",["title"]="Morgan Stern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1204:description:1-97","1204:description:99-166","1204:description:171-209","1204:description:212-256","1204:description:259-319","1204:description:324-357","1204:description:360-413","1204:description:418-505","1204:objective:1-60"},["minimumStage"]=2,["questID"]=1204,["sourceHash"]="f0df4f97eb3f52d6d927c4e073c3b60cd3bf9ef7ae96d4faa30e2b387ebe8b4a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4794",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted forked mudrock tongues for their reputed distinctive flavor, but doubted he would survive gathering them in Dustwallow himself.",["title"]="Morgan Stern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1241:description:1-72","1241:description:74-101","1241:description:106-174","1241:description:176-273","1241:description:278-386","1241:description:391-452","1241:description:454-511","1241:objective:1-30"},["minimumStage"]=2,["questID"]=1241,["sourceHash"]="10e4fb4c4a0ef00fb787d9d46c8156015fb8c7247dbc6eeae003e66cad94866b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4960",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="DeLavey quietly enlisted his own contacts to investigate a diplomat’s disappearance before the affair became public.",["title"]="Bishop DeLavey"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1241:description:1-72","1241:description:74-101","1241:description:106-174","1241:description:176-273","1241:description:278-386","1241:description:391-452","1241:description:454-511","1241:objective:1-30"},["minimumStage"]=2,["questID"]=1241,["sourceHash"]="10e4fb4c4a0ef00fb787d9d46c8156015fb8c7247dbc6eeae003e66cad94866b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4960",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jorgen in the Valley of Heroes was an old friend whom he trusted with a note and the next step of the inquiry.",["title"]="Bishop DeLavey"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1244:description:1-16","1244:description:18-111","1244:description:116-190","1244:description:192-288","1244:description:290-342","1244:description:347-414","1244:description:419-494","1244:objective:1-67"},["minimumStage"]=2,["questID"]=1244,["sourceHash"]="2b3e763f1ce2fffec429ef90641488f5818b5a7f1f9a9069267596ebdd7f8c69"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-840",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Backus regarded the Defias as a standing threat even when their members kept to themselves.",["title"]="Watcher Backus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1244:description:1-16","1244:description:18-111","1244:description:116-190","1244:description:192-288","1244:description:290-342","1244:description:347-414","1244:description:419-494","1244:objective:1-67"},["minimumStage"]=2,["questID"]=1244,["sourceHash"]="2b3e763f1ce2fffec429ef90641488f5818b5a7f1f9a9069267596ebdd7f8c69"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-840",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="An unusual gathering of Defias agents at Addle’s Stead had appeared in his reports several weeks before the missing-diplomat inquiry.",["title"]="Watcher Backus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1249:description:1-29","1249:description:31-84","1249:description:86-113","1249:description:115-143","1249:description:148-166","1249:description:168-236","1249:description:241-316","1249:description:318-398","1249:description:400-485","1249:objective:1-77"},["minimumStage"]=2,["questID"]=1249,["sourceHash"]="34166f0d9c7340d87888a22f9b4e1983ad7566754411984ef21b5be40924731d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4963",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mikhail welcomed someone sent by Elling with particular warmth and offered his assistance.",["title"]="Mikhail"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1249:description:1-29","1249:description:31-84","1249:description:86-113","1249:description:115-143","1249:description:148-166","1249:description:168-236","1249:description:241-316","1249:description:318-398","1249:description:400-485","1249:objective:1-77"},["minimumStage"]=2,["questID"]=1249,["sourceHash"]="34166f0d9c7340d87888a22f9b4e1983ad7566754411984ef21b5be40924731d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4963",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="During the inquiry he noticed a man near the exit listening closely, and warned that the suspect might flee.",["title"]="Mikhail"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1250:description:1-60","1250:description:62-80","1250:description:82-134","1250:description:136-243","1250:description:245-291","1250:description:293-321","1250:description:323-366","1250:description:371-456","1250:description:458-483","1250:description:485-502","1250:description:504-511","1250:objective:1-33"},["minimumStage"]=2,["questID"]=1250,["sourceHash"]="f2184947b043f2d2eff0237fedafae6961946d7fc1e4a382cbeadabf1c458396"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4962",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Slim admitted arranging for a man named Hendel to board the king’s ship in harbor as part of a Defias operation.",["title"]="Tapoke \"Slim\" Jahn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1250:description:1-60","1250:description:62-80","1250:description:82-134","1250:description:136-243","1250:description:245-291","1250:description:293-321","1250:description:323-366","1250:description:371-456","1250:description:458-483","1250:description:485-502","1250:description:504-511","1250:objective:1-33"},["minimumStage"]=2,["questID"]=1250,["sourceHash"]="f2184947b043f2d2eff0237fedafae6961946d7fc1e4a382cbeadabf1c458396"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4962",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He said the missing traveler was Stormwind’s king, bound for a secret meeting with Jaina, and that the Defias had an unidentified partner.",["title"]="Tapoke \"Slim\" Jahn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1265:description:1-7","1265:description:9-28","1265:description:30-71","1265:description:76-103","1265:description:105-140","1265:description:142-217","1265:description:219-324","1265:description:326-414","1265:description:419-489","1265:description:491-502","1265:objective:1-51"},["minimumStage"]=2,["questID"]=1265,["sourceHash"]="67b7c513447f8a7363beef2ff64e7b5606fa6b362833406f23a0b02f433bbd6a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4964",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Samaul commanded soldiers protecting Theramore’s lands and regarded avoiding a disturbance as part of that duty.",["title"]="Commander Samaul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1265:description:1-7","1265:description:9-28","1265:description:30-71","1265:description:76-103","1265:description:105-140","1265:description:142-217","1265:description:219-324","1265:description:326-414","1265:description:419-489","1265:description:491-502","1265:objective:1-51"},["minimumStage"]=2,["questID"]=1265,["sourceHash"]="67b7c513447f8a7363beef2ff64e7b5606fa6b362833406f23a0b02f433bbd6a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4964",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recognized Hendel as one of his soldiers and understood that an inquiry sent by Elling was likely serious.",["title"]="Commander Samaul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1266:description:1-38","1266:description:40-128","1266:description:130-249","1266:description:254-332","1266:description:337-412","1266:description:414-492","1266:objective:1-40"},["minimumStage"]=2,["questID"]=1266,["sourceHash"]="c05b16ef5e646d7834a12ab71f82b89acfd46a3bb40a1f36081c6b3177850a4a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4967",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tervosh knew the disposition of Theramore’s guards and infiltrators, including those watching the Horde settlement of Brackenwall.",["title"]="Archmage Tervosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1266:description:1-38","1266:description:40-128","1266:description:130-249","1266:description:254-332","1266:description:337-412","1266:description:414-492","1266:objective:1-40"},["minimumStage"]=2,["questID"]=1266,["sourceHash"]="c05b16ef5e646d7834a12ab71f82b89acfd46a3bb40a1f36081c6b3177850a4a"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-4967",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed visitors to Lady Proudmoore’s tower when they needed to find him again.",["title"]="Archmage Tervosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1270:description:1-54","1270:description:59-141","1270:description:146-243","1270:description:245-328","1270:description:333-391","1270:description:394-468","1270:objective:1-66"},["minimumStage"]=2,["questID"]=1270,["sourceHash"]="0a643583e2d66bf600540e461f16df7f1c5cbc230efd490399066caf3f376714"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4880",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ignatz accepted good money from Mebok Mizzyrix to gather bogbean leaves, without much interest in the potion they would serve.",["title"]="\"Stinky\" Ignatz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1270:description:1-54","1270:description:59-141","1270:description:146-243","1270:description:245-328","1270:description:333-391","1270:description:394-468","1270:objective:1-66"},["minimumStage"]=2,["questID"]=1270,["sourceHash"]="0a643583e2d66bf600540e461f16df7f1c5cbc230efd490399066caf3f376714"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4880",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His knowledge of the swamp did not prevent its creatures from surrounding him before he found the plant.",["title"]="\"Stinky\" Ignatz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1275:description:1-44","1275:description:46-129","1275:description:134-193","1275:description:195-263","1275:description:268-382","1275:description:384-466","1275:description:471-494","1275:objective:1-63"},["minimumStage"]=2,["questID"]=1275,["sourceHash"]="794a794346538bbb3ff5a9005dfb271a74dafc3730c8e02db21be15b1bf17db9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8997",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gershala sought satyr and naga brain stems from Blackfathom to study the consequences of demonic corruption.",["title"]="Gershala Nightwhisper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1275:description:1-44","1275:description:46-129","1275:description:134-193","1275:description:195-263","1275:description:268-382","1275:description:384-466","1275:description:471-494","1275:objective:1-63"},["minimumStage"]=2,["questID"]=1275,["sourceHash"]="794a794346538bbb3ff5a9005dfb271a74dafc3730c8e02db21be15b1bf17db9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-8997",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She feared that blood elves’ use of demonic magic might transform them as earlier corruption had transformed other peoples; this was her warning, not an established future.",["title"]="Gershala Nightwhisper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1286:description:1-177","1286:description:182-348","1286:description:353-398","1286:description:400-446","1286:description:451-464","1286:description:466-496","1286:objective:1-85"},["minimumStage"]=2,["questID"]=1286,["sourceHash"]="fc39aa52dfd48b72cab6f14556f41e8bd7fd489840b433a045d6718d862fc435"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vimes described maintaining Dustwallow’s defensive watchtowers as a difficult effort sustained by Theramore’s resolve.",["title"]="Captain Garran Vimes"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1286:description:1-177","1286:description:182-348","1286:description:353-398","1286:description:400-446","1286:description:451-464","1286:description:466-496","1286:objective:1-85"},["minimumStage"]=2,["questID"]=1286,["sourceHash"]="fc39aa52dfd48b72cab6f14556f41e8bd7fd489840b433a045d6718d862fc435"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Reports placed deserters under Balos Jacken at the abandoned tower of Lost Point, prompting him to seek information from their lieutenant.",["title"]="Captain Garran Vimes"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1301:description:1-108","1301:description:110-133","1301:description:135-204","1301:description:209-232","1301:description:234-343","1301:description:348-438","1301:objective:1-43"},["minimumStage"]=2,["questID"]=1301,["sourceHash"]="0aa6a3e918ceaad7fb691c7649d758c6fa177a67093e80756fbbc9cb3a65b63a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5081",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Connor worked at Stormwind’s Blue Recluse after training under the chef and innkeeper James Hyal.",["title"]="Connor Rivers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1301:description:1-108","1301:description:110-133","1301:description:135-204","1301:description:209-232","1301:description:234-343","1301:description:348-438","1301:objective:1-43"},["minimumStage"]=2,["questID"]=1301,["sourceHash"]="0aa6a3e918ceaad7fb691c7649d758c6fa177a67093e80756fbbc9cb3a65b63a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5081",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He credited Hyal with his success and hoped a traveler could carry his greetings after a long silence.",["title"]="Connor Rivers"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1302:description:1-58","1302:description:60-174","1302:description:176-225","1302:description:227-248","1302:description:253-387","1302:description:389-459","1302:description:461-479","1302:description:481-508","1302:objective:1-57"},["minimumStage"]=2,["questID"]=1302,["sourceHash"]="f03b8762670c9d42ca1085bdf5375776cc84315f2902f513ada413a2e155632c"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5082",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vincent’s brother James had crossed the sea with Lady Proudmoore; Vincent remembered him as an excellent cook.",["title"]="Vincent Hyal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1302:description:1-58","1302:description:60-174","1302:description:176-225","1302:description:227-248","1302:description:253-387","1302:description:389-459","1302:description:461-479","1302:description:481-508","1302:objective:1-57"},["minimumStage"]=2,["questID"]=1302,["sourceHash"]="f03b8762670c9d42ca1085bdf5375776cc84315f2902f513ada413a2e155632c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5082",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His latest information placed James establishing an inn in Kalimdor, with Theramore’s clerk as a possible source of directions.",["title"]="Vincent Hyal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1360:description:1-85","1360:description:87-131","1360:description:134-188","1360:description:191-240","1360:description:243-322","1360:description:327-400","1360:description:403-468","1360:description:471-504","1360:objective:1-126"},["minimumStage"]=2,["questID"]=1360,["sourceHash"]="9679cbb06dde5c221ec054189baf31ae51863b3331f0281a0b9c54ba1b66f883"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6294",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krom worked as a digger at Uldaman until troggs overran the excavation and forced him to flee without his belongings.",["title"]="Krom Stoutarm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1360:description:1-85","1360:description:87-131","1360:description:134-188","1360:description:191-240","1360:description:243-322","1360:description:327-400","1360:description:403-468","1360:description:471-504","1360:objective:1-126"},["minimumStage"]=2,["questID"]=1360,["sourceHash"]="9679cbb06dde5c221ec054189baf31ae51863b3331f0281a0b9c54ba1b66f883"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6294",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His most treasured possession remained in a chest bearing his name at the end of the North Common Hall.",["title"]="Krom Stoutarm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1363:description:1-189","1363:description:191-291","1363:description:296-314","1363:description:316-371","1363:description:373-457","1363:description:459-504","1363:objective:1-39"},["minimumStage"]=2,["questID"]=1363,["sourceHash"]="7928147dc1c474ca4d0264d92845a5c5c26921c15794aea290b9e2205a994ec2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-338",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mazen cared for the library’s magical tomes and scrolls at Stormwind’s Academy of Arcane Arts and Sciences.",["title"]="Mazen Mac'Nadir"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1363:description:1-189","1363:description:191-291","1363:description:296-314","1363:description:316-371","1363:description:373-457","1363:description:459-504","1363:objective:1-39"},["minimumStage"]=2,["questID"]=1363,["sourceHash"]="7928147dc1c474ca4d0264d92845a5c5c26921c15794aea290b9e2205a994ec2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-338",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He valued Dellis’s ability inside the library but distrusted his judgment beyond Stormwind’s gates after a recent mistake.",["title"]="Mazen Mac'Nadir"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1364:description:1-115","1364:description:120-168","1364:description:170-197","1364:description:202-320","1364:description:322-362","1364:description:364-399","1364:description:401-436","1364:description:441-503","1364:objective:1-110"},["minimumStage"]=2,["questID"]=1364,["sourceHash"]="793d17d312e44aa645678c0e0033ae05d7c4bb6df1784009d922867df715df4e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5386",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dellis lost an important essay while carrying Mazen’s work to Watcher Mahar Ba at Nethergarde.",["title"]="Acolyte Dellis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1364:description:1-115","1364:description:120-168","1364:description:170-197","1364:description:202-320","1364:description:322-362","1364:description:364-399","1364:description:401-436","1364:description:441-503","1364:objective:1-110"},["minimumStage"]=2,["questID"]=1364,["sourceHash"]="793d17d312e44aa645678c0e0033ae05d7c4bb6df1784009d922867df715df4e"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5386",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Unfamiliar with the Blasted Lands journey, he took a wrong turn in the Swamp of Sorrows and fled from threatening plantlike creatures.",["title"]="Acolyte Dellis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1365:description:1-48","1365:description:51-124","1365:description:127-206","1365:description:209-269","1365:description:274-314","1365:description:319-364","1365:description:367-412","1365:description:417-456","1365:description:459-490","1365:objective:1-58"},["minimumStage"]=2,["questID"]=1365,["sourceHash"]="972a58414043949ba63f186869c854cfbba6caa830ae35540f2e74d83c7e62e4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5395",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Felgur wanted to weaken Desolace’s centaur clans before their rivalries could give way to a united attack.",["title"]="Felgur Twocuts"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1365:description:1-48","1365:description:51-124","1365:description:127-206","1365:description:209-269","1365:description:274-314","1365:description:319-364","1365:description:367-412","1365:description:417-456","1365:description:459-490","1365:objective:1-58"},["minimumStage"]=2,["questID"]=1365,["sourceHash"]="972a58414043949ba63f186869c854cfbba6caa830ae35540f2e74d83c7e62e4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5395",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He began with the Kolkar and their leader, Khan Dez’hepah, judging their internal warfare a temporary advantage.",["title"]="Felgur Twocuts"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1372:description:1-81","1372:description:86-159","1372:description:161-211","1372:description:213-223","1372:description:225-299","1372:description:304-315","1372:description:317-323","1372:description:325-342","1372:description:344-412","1372:description:417-454","1372:description:456-493","1372:objective:1-48"},["minimumStage"]=2,["questID"]=1372,["sourceHash"]="1d6085f51cc1d81b46f95e76ad879acfb533cb30fbf90003402cbe6bdc7f03fd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zraedus scouted with an expedition sent by Varimathras to survey the southern lands.",["title"]="Deathstalker Zraedus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1372:description:1-81","1372:description:86-159","1372:description:161-211","1372:description:213-223","1372:description:225-299","1372:description:304-315","1372:description:317-323","1372:description:325-342","1372:description:344-412","1372:description:417-454","1372:description:456-493","1372:objective:1-48"},["minimumStage"]=2,["questID"]=1372,["sourceHash"]="1d6085f51cc1d81b46f95e76ad879acfb533cb30fbf90003402cbe6bdc7f03fd"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He saw a human spying on Beggar’s Haunt before orcs captured the infiltrator and took him to Stonard, then arranged Faustin’s help with a supposed truth serum.",["title"]="Deathstalker Zraedus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1383:description:1-36","1383:description:38-117","1383:description:122-198","1383:description:200-274","1383:description:276-344","1383:description:349-425","1383:description:427-484","1383:description:489-504","1383:objective:1-110"},["minimumStage"]=2,["questID"]=1383,["sourceHash"]="0fecf4725a0802a60f04c94818564d91c71e0370dee02e7961541a2aa0cc1d51"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5414",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Faustin’s proposed serum combined shadow panther hearts, the Mire Lord’s enchanted fungus and a rare tumor from Desolace’s deepstriders.",["title"]="Apothecary Faustin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1383:description:1-36","1383:description:38-117","1383:description:122-198","1383:description:200-274","1383:description:276-344","1383:description:349-425","1383:description:427-484","1383:description:489-504","1383:objective:1-110"},["minimumStage"]=2,["questID"]=1383,["sourceHash"]="0fecf4725a0802a60f04c94818564d91c71e0370dee02e7961541a2aa0cc1d51"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5414",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He worked with Zraedus on the concoction intended for the human prisoner in Stonard.",["title"]="Apothecary Faustin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1395:description:1-80","1395:description:83-164","1395:description:169-219","1395:description:224-280","1395:description:283-422","1395:description:427-442","1395:description:445-507","1395:objective:1-88"},["minimumStage"]=2,["questID"]=1395,["sourceHash"]="cf5c6ab99af950a1deaaba09e671b0338631cec1e05cb4a3145c697b923b5836"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5464",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sorigal needed powerstones carried to Quartermaster Lungertz before their short-lived power faded; the next caravan would be too late.",["title"]="Watchmaster Sorigal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1395:description:1-80","1395:description:83-164","1395:description:169-219","1395:description:224-280","1395:description:283-422","1395:description:427-442","1395:description:445-507","1395:objective:1-88"},["minimumStage"]=2,["questID"]=1395,["sourceHash"]="cf5c6ab99af950a1deaaba09e671b0338631cec1e05cb4a3145c697b923b5836"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5464",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the urgent shipment through Deadwind Pass and the Swamp of Sorrows to Nethergarde, warning of the dangerous journey.",["title"]="Watchmaster Sorigal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1419:description:1-45","1419:description:48-70","1419:description:72-126","1419:description:129-146","1419:description:151-181","1419:description:184-261","1419:description:264-301","1419:description:306-327","1419:description:330-367","1419:description:370-447","1419:objective:1-55"},["minimumStage"]=2,["questID"]=1419,["sourceHash"]="9496479fa94028e39fef45f67b01859875ba39399ef0ca4de1a63375bf04d366"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5394",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Neeka sought crag coyote jawbones after the bold scavengers began stealing Kargath’s food supplies.",["title"]="Neeka Bloodscar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1419:description:1-45","1419:description:48-70","1419:description:72-126","1419:description:129-146","1419:description:151-181","1419:description:184-261","1419:description:264-301","1419:description:306-327","1419:description:330-367","1419:description:370-447","1419:objective:1-55"},["minimumStage"]=2,["questID"]=1419,["sourceHash"]="9496479fa94028e39fef45f67b01859875ba39399ef0ca4de1a63375bf04d366"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5394",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She treated hunting the Badlands’ tough coyotes as a test of whether a traveler truly knew its heat and dusty plains.",["title"]="Neeka Bloodscar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1426:description:1-76","1426:description:78-133","1426:description:135-231","1426:description:233-330","1426:description:335-361","1426:description:363-384","1426:description:386-442","1426:objective:1-113"},["minimumStage"]=2,["questID"]=1426,["sourceHash"]="c67a1041f78c22d7230c0165702ea3a29205e57a640cfa46cb5e647446828392"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5593",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Katar despised the sea and its creatures, taking satisfaction in seeing the fish-men slain in the Horde’s service.",["title"]="Katar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1431:description:1-101","1431:description:106-189","1431:description:191-274","1431:description:276-367","1431:description:372-470","1431:description:472-490","1431:objective:1-30"},["minimumStage"]=2,["questID"]=1431,["sourceHash"]="d260ae8c10b72ddec0470d545db99b56c894f83bffdb6ce66913bc1eb9d27ba6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5639",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Craven praised Thrall’s prudence and diplomacy, arguing that the warchief’s experience with humans had taught him much despite the strain of war.",["title"]="Craven Drok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1431:description:1-101","1431:description:106-189","1431:description:191-274","1431:description:276-367","1431:description:372-470","1431:description:472-490","1431:objective:1-30"},["minimumStage"]=2,["questID"]=1431,["sourceHash"]="d260ae8c10b72ddec0470d545db99b56c894f83bffdb6ce66913bc1eb9d27ba6"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5639",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed those interested in that account to Keldran’s hovel near Orgrimmar’s western exit.",["title"]="Craven Drok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1437:description:1-20","1437:description:22-131","1437:description:133-234","1437:description:236-331","1437:description:336-416","1437:description:421-478","1437:objective:1-62"},["minimumStage"]=2,["questID"]=1437,["sourceHash"]="4a3b3645e274e4b0eeacd04b1d974ec2383d52ac36e8c3b7467429f76cb5c776"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5642",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vahlarriel searched for Tyranis and Dalinda, missing children of the Darnassian merchant House Malem.",["title"]="Vahlarriel Demonslayer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1437:description:1-20","1437:description:22-131","1437:description:133-234","1437:description:236-331","1437:description:336-416","1437:description:421-478","1437:objective:1-62"},["minimumStage"]=2,["questID"]=1437,["sourceHash"]="4a3b3645e274e4b0eeacd04b1d974ec2383d52ac36e8c3b7467429f76cb5c776"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5642",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Their father feared the worst; the last report placed the pair traveling through Stonetalon, and Vahlarriel hoped their wagon would supply a lead.",["title"]="Vahlarriel Demonslayer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1439:description:1-76","1439:description:78-118","1439:description:120-220","1439:description:225-259","1439:description:261-329","1439:description:331-347","1439:description:352-421","1439:description:423-477","1439:objective:1-31"},["minimumStage"]=2,["questID"]=1439,["sourceHash"]="9c33622fc19fab33cb57d82dcb7b1bf0b79bf8698985ce14b9bc2353af335c50"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5644",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dalinda said orcs killed her family’s guards and servants before taking her and Tyranis captive.",["title"]="Dalinda Malem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1439:description:1-76","1439:description:78-118","1439:description:120-220","1439:description:225-259","1439:description:261-329","1439:description:331-347","1439:description:352-421","1439:description:423-477","1439:objective:1-31"},["minimumStage"]=2,["questID"]=1439,["sourceHash"]="9c33622fc19fab33cb57d82dcb7b1bf0b79bf8698985ce14b9bc2353af335c50"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5644",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She would not leave without learning her brother’s fate, recalling that he had tried to impress their captors with his arcane knowledge.",["title"]="Dalinda Malem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1444:description:1-75","1444:description:77-124","1444:description:129-213","1444:description:215-235","1444:description:240-321","1444:description:326-372","1444:description:374-489","1444:objective:1-31"},["minimumStage"]=2,["questID"]=1444,["sourceHash"]="17638bbac2e831c04e302af61bb64ab14f6726bbf4898d9a6cffcd71266d76fd"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5598",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jammal’an expelled the exile from Atal’Hakkar after he questioned the high priest’s prophecy.",["title"]="Atal'ai Exile"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1444:description:1-75","1444:description:77-124","1444:description:129-213","1444:description:215-235","1444:description:240-321","1444:description:326-372","1444:description:374-489","1444:objective:1-31"},["minimumStage"]=2,["questID"]=1444,["sourceHash"]="17638bbac2e831c04e302af61bb64ab14f6726bbf4898d9a6cffcd71266d76fd"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5598",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Once a supporter of Jammal’an, he came to fear that the summoning ritual would destroy the Atal’ai and imperil the wider world.",["title"]="Atal'ai Exile"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1448:description:1-65","1448:description:70-133","1448:description:135-155","1448:description:160-200","1448:description:202-290","1448:description:292-344","1448:description:349-442","1448:description:447-468","1448:description:470-511","1448:objective:1-81"},["minimumStage"]=2,["questID"]=1448,["sourceHash"]="40922fbe9a436426d03608c892862f95940b17bd65cb3c87af2399c62212f43b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5384",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Explorers’ League sent Brohann to find Atal’Hakkar on what he regarded as his final expedition.",["title"]="Brohann Caskbelly"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1448:description:1-65","1448:description:70-133","1448:description:135-155","1448:description:160-200","1448:description:202-290","1448:description:292-344","1448:description:349-442","1448:description:447-468","1448:description:470-511","1448:objective:1-81"},["minimumStage"]=2,["questID"]=1448,["sourceHash"]="40922fbe9a436426d03608c892862f95940b17bd65cb3c87af2399c62212f43b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5384",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Age and frailty limited him to searching the Swamp of Sorrows from gryphonback, and the temple eluded him.",["title"]="Brohann Caskbelly"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1450:description:1-84","1450:description:89-114","1450:description:116-186","1450:description:188-233","1450:description:244-330","1450:description:332-421","1450:description:426-443","1450:objective:1-64"},["minimumStage"]=2,["questID"]=1450,["sourceHash"]="aeacf0acfd008dd974eb2aab9fc7a4c0fea6d2fc5bcb01bf667d1b7f6e81f4e2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5635",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Falstad sharply corrected a visitor who mistook him for Gryphon Master Talonaxe, insisting flight assignments were the gryphon master’s business.",["title"]="Falstad Wildhammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1452:description:1-7","1452:description:12-46","1452:description:48-85","1452:description:90-190","1452:description:192-224","1452:description:226-232","1452:description:237-251","1452:description:253-334","1452:description:339-382","1452:description:384-399","1452:description:401-447","1452:description:452-484","1452:description:486-508","1452:objective:1-116"},["minimumStage"]=2,["questID"]=1452,["sourceHash"]="92f3b222d909d6e417e4672f445d1746bc8f7f99c49418052b37f1c73a8a2d7e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5634",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rhapsody accompanied Brohann on an unpleasant expedition into the swamp.",["title"]="Rhapsody Shindigger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1452:description:1-7","1452:description:12-46","1452:description:48-85","1452:description:90-190","1452:description:192-224","1452:description:226-232","1452:description:237-251","1452:description:253-334","1452:description:339-382","1452:description:384-399","1452:description:401-447","1452:description:452-484","1452:description:486-508","1452:objective:1-116"},["minimumStage"]=2,["questID"]=1452,["sourceHash"]="92f3b222d909d6e417e4672f445d1746bc8f7f99c49418052b37f1c73a8a2d7e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5634",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered his account in exchange for a strong cocktail made with roc gizzards and groddoc and ironfur livers.",["title"]="Rhapsody Shindigger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1453:description:1-40","1453:description:42-104","1453:description:106-223","1453:description:228-340","1453:description:342-399","1453:description:401-440","1453:objective:1-35"},["minimumStage"]=2,["questID"]=1453,["sourceHash"]="1640bf2ed9f9ad6dda55e8f21f46091de2e2604b837a9919062fddb77a13e75a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5637",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Roetten referred adventurers seeking work in Desolace to Kreldig Ungor at Nijel’s Point.",["title"]="Roetten Stonehammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1453:description:1-40","1453:description:42-104","1453:description:106-223","1453:description:228-340","1453:description:342-399","1453:description:401-440","1453:objective:1-35"},["minimumStage"]=2,["questID"]=1453,["sourceHash"]="1640bf2ed9f9ad6dda55e8f21f46091de2e2604b837a9919062fddb77a13e75a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5637",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described the northern mountain camp as a small, easily missed refuge reached from the Stonetalon approach.",["title"]="Roetten Stonehammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1468:description:1-48","1468:description:51-120","1468:description:125-142","1468:description:145-254","1468:description:257-341","1468:description:344-381","1468:description:386-438","1468:description:441-490","1468:objective:1-101"},["minimumStage"]=2,["questID"]=1468,["sourceHash"]="432ea70e03be4b7866df4c46c33d4c7c11af1328d97e38bc25944be0f34a28b3"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14450",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nightingale arranged temporary care for orphaned children during Children’s Week.",["title"]="Orphan Matron Nightingale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1468:description:1-48","1468:description:51-120","1468:description:125-142","1468:description:145-254","1468:description:257-341","1468:description:344-381","1468:description:386-438","1468:description:441-490","1468:objective:1-101"},["minimumStage"]=2,["questID"]=1468,["sourceHash"]="432ea70e03be4b7866df4c46c33d4c7c11af1328d97e38bc25944be0f34a28b3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14450",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She entrusted willing guardians with a whistle to meet and accompany their ward during the festival.",["title"]="Orphan Matron Nightingale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1470:description:1-17","1470:description:19-112","1470:description:114-149","1470:description:154-172","1470:description:177-210","1470:description:212-243","1470:description:245-352","1470:description:357-503","1470:objective:1-41"},["minimumStage"]=2,["questID"]=1470,["sourceHash"]="70936e0cab0eae77bc8a2b4270066f923b978963baf84d2b830b88b56e85616a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5667",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Venya taught that knowledge allowed warlocks to control chaotic magic and bend beings of the void to their will.",["title"]="Venya Marthand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1470:description:1-17","1470:description:19-112","1470:description:114-149","1470:description:154-172","1470:description:177-210","1470:description:212-243","1470:description:245-352","1470:description:357-503","1470:objective:1-41"},["minimumStage"]=2,["questID"]=1470,["sourceHash"]="70936e0cab0eae77bc8a2b4270066f923b978963baf84d2b830b88b56e85616a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5667",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Before teaching a young warlock to bind a servant, she required skulls from the rattlecage skeletons near the abandoned smithy.",["title"]="Venya Marthand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1472:description:1-71","1472:description:73-121","1472:description:126-180","1472:description:185-224","1472:description:226-345","1472:description:347-393","1472:description:398-456","1472:description:458-489","1472:objective:1-54"},["minimumStage"]=2,["questID"]=1472,["sourceHash"]="55a810b012418aa9177662f4fa7ca4c08f3da71330ad773304d0d69325c42f4e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5675",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Carendin taught that a succubus could be lured into the world with the hearts of loving, virtuous men and then dominated by the summoner.",["title"]="Carendin Halgar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1472:description:1-71","1472:description:73-121","1472:description:126-180","1472:description:185-224","1472:description:226-345","1472:description:347-393","1472:description:398-456","1472:description:458-489","1472:objective:1-54"},["minimumStage"]=2,["questID"]=1472,["sourceHash"]="55a810b012418aa9177662f4fa7ca4c08f3da71330ad773304d0d69325c42f4e"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5675",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His assistant Godrick Farsan researched suitable victims for the summoning.",["title"]="Carendin Halgar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1476:description:1-26","1476:description:28-49","1476:description:54-156","1476:description:161-308","1476:description:313-431","1476:description:436-468","1476:description:470-508","1476:objective:1-103"},["minimumStage"]=2,["questID"]=1476,["sourceHash"]="dce5cf92695fffde9f6b4fc4f3b7b247542c0bc95dcebf53e7a83e62922ad963"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5693",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Godrick searched overheard stories for honorable men whose hearts could serve Carendin’s ritual.",["title"]="Godrick Farsan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1476:description:1-26","1476:description:28-49","1476:description:54-156","1476:description:161-308","1476:description:313-431","1476:description:436-468","1476:description:470-508","1476:objective:1-103"},["minimumStage"]=2,["questID"]=1476,["sourceHash"]="dce5cf92695fffde9f6b4fc4f3b7b247542c0bc95dcebf53e7a83e62922ad963"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5693",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He selected Dalin Forgewright for caring for Lordaeron refugees at the Greymane Wall, and Comar Villard for remaining faithful to his missing wife.",["title"]="Godrick Farsan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1486:description:1-130","1486:description:135-196","1486:description:198-298","1486:description:300-377","1486:description:382-470","1486:objective:1-53"},["minimumStage"]=2,["questID"]=1486,["sourceHash"]="c15c0cc165e4ad66be250671dbfc349b2ffe4375a8c043bdbd81ed514e61519d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5767",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nalpak connected the appearance of deviate beasts in the Wailing Caverns with Naralex’s deepening nightmare.",["title"]="Nalpak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1486:description:1-130","1486:description:135-196","1486:description:198-298","1486:description:300-377","1486:description:382-470","1486:objective:1-53"},["minimumStage"]=2,["questID"]=1486,["sourceHash"]="c15c0cc165e4ad66be250671dbfc349b2ffe4375a8c043bdbd81ed514e61519d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5767",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Despite considering the creatures evil, he believed their unusual hides could serve leatherworkers.",["title"]="Nalpak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1487:description:1-25","1487:description:30-153","1487:description:155-188","1487:description:193-283","1487:description:288-403","1487:description:408-462","1487:objective:1-129"},["minimumStage"]=2,["questID"]=1487,["sourceHash"]="19e6f163ea5b922cc75394ee24400a61e42711e561acefc2b86f31979934d1c5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5768",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ebru remembered Naralex’s purpose as restoring the Barrens’ former lush forest through the Emerald Dream, before his dream became a nightmare.",["title"]="Ebru"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1487:description:1-25","1487:description:30-153","1487:description:155-188","1487:description:193-283","1487:description:288-403","1487:description:408-462","1487:objective:1-129"},["minimumStage"]=2,["questID"]=1487,["sourceHash"]="19e6f163ea5b922cc75394ee24400a61e42711e561acefc2b86f31979934d1c5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5768",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="While other disciples tried to awaken Naralex, she concentrated on destroying the corrupted creatures inhabiting the caverns.",["title"]="Ebru"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1498:description:1-49","1498:description:51-61","1498:description:64-132","1498:description:135-205","1498:description:210-292","1498:description:295-310","1498:description:313-346","1498:description:349-422","1498:description:427-461","1498:objective:1-64"},["minimumStage"]=2,["questID"]=1498,["sourceHash"]="d2b1dda553be7368f5876dd3a255a7a396f20fa698ec45832b9642c5f10caab2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5810",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Uzzek taught that warriors were the Horde’s shield and had a duty to protect weaker companions.",["title"]="Uzzek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1498:description:1-49","1498:description:51-61","1498:description:64-132","1498:description:135-205","1498:description:210-292","1498:description:295-310","1498:description:313-346","1498:description:349-422","1498:description:427-461","1498:objective:1-64"},["minimumStage"]=2,["questID"]=1498,["sourceHash"]="d2b1dda553be7368f5876dd3a255a7a396f20fa698ec45832b9642c5f10caab2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5810",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He tested prospective pupils against Thunder Ridge’s lightning hides and thunder lizards before offering instruction.",["title"]="Uzzek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1503:description:1-56","1503:description:59-126","1503:description:129-252","1503:description:255-266","1503:description:271-337","1503:description:340-404","1503:description:409-497","1503:objective:1-65"},["minimumStage"]=2,["questID"]=1503,["sourceHash"]="6dd343e92fb7e24d674dfdf336e77a1c96ebfc772d97ca9a1f5ef44597962fcf"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-5878",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thun’grim’s eyesight was poor enough for raiding Razormanes to exploit it with distracting snorts.",["title"]="Thun'grim Firegaze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1503:description:1-56","1503:description:59-126","1503:description:129-252","1503:description:255-266","1503:description:271-337","1503:description:340-404","1503:description:409-497","1503:objective:1-65"},["minimumStage"]=2,["questID"]=1503,["sourceHash"]="6dd343e92fb7e24d674dfdf336e77a1c96ebfc772d97ca9a1f5ef44597962fcf"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5878",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Quilboar stole an iron chest of forged steel from his camp while others distracted him; he offered a weapon for its recovery.",["title"]="Thun'grim Firegaze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1509:description:1-62","1509:description:64-105","1509:description:110-162","1509:description:164-180","1509:description:182-258","1509:description:263-353","1509:description:358-426","1509:description:428-486","1509:objective:1-36"},["minimumStage"]=2,["questID"]=1509,["sourceHash"]="b1ac31f1d8f9704070af6587f2816960aebababd7ae9d13d913412b4ba89c99f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5910",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zankaja’s mate Dogran proudly accepted a promotion to duty at the Crossroads, working with Gazrog.",["title"]="Zankaja"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1509:description:1-62","1509:description:64-105","1509:description:110-162","1509:description:164-180","1509:description:182-258","1509:description:263-353","1509:description:358-426","1509:description:428-486","1509:objective:1-36"},["minimumStage"]=2,["questID"]=1509,["sourceHash"]="b1ac31f1d8f9704070af6587f2816960aebababd7ae9d13d913412b4ba89c99f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5910",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She concealed her sadness at his departure, then feared for him when he was a week overdue without sending word.",["title"]="Zankaja"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1511:description:1-85","1511:description:90-105","1511:description:107-155","1511:description:157-228","1511:description:230-272","1511:description:277-337","1511:description:339-415","1511:objective:1-58"},["minimumStage"]=2,["questID"]=1511,["sourceHash"]="7d3347f7ae40adf49cf49dd36964bd9aef7ab1d00b1f2af8f0090418945ee5ba"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4197",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ken’zigla prepared a draught to restore enough strength for wounded Dogran to move, warning that the whole dose at once could make him bleed dangerously.",["title"]="Ken'zigla"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1511:description:1-85","1511:description:90-105","1511:description:107-155","1511:description:157-228","1511:description:230-272","1511:description:277-337","1511:description:339-415","1511:objective:1-58"},["minimumStage"]=2,["questID"]=1511,["sourceHash"]="7d3347f7ae40adf49cf49dd36964bd9aef7ab1d00b1f2af8f0090418945ee5ba"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4197",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent the medicine through Logmar at Camp Taurajo, who was expected to know where Dogran could be found.",["title"]="Ken'zigla"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1523:description:1-48","1523:description:50-143","1523:description:145-199","1523:description:201-210","1523:description:212-296","1523:description:301-336","1523:description:338-466","1523:objective:1-32"},["minimumStage"]=2,["questID"]=1523,["sourceHash"]="bbf06166377f3dcc40a8b0e139ccc5a43d98d1fb1bb2ece5068cfeba34ee93ae"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3032",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Beram guided shamans from patience in their studies toward understanding fire, destruction and chaos.",["title"]="Beram Skychaser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1523:description:1-48","1523:description:50-143","1523:description:145-199","1523:description:201-210","1523:description:212-296","1523:description:301-336","1523:description:338-466","1523:objective:1-32"},["minimumStage"]=2,["questID"]=1523,["sourceHash"]="bbf06166377f3dcc40a8b0e139ccc5a43d98d1fb1bb2ece5068cfeba34ee93ae"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-3032",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He referred those ready for the next trial to Kranal Fiss north of the Crossroads.",["title"]="Beram Skychaser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1524:description:1-89","1524:description:94-213","1524:description:215-343","1524:description:348-410","1524:description:412-510","1524:objective:1-63"},["minimumStage"]=2,["questID"]=1524,["sourceHash"]="5401786b258286cc3e038d99f5b90490430d1a77d25bbd34ae4eadf9818c8257"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5907",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kranal distinguished the power to wield fire from the readiness to master it, requiring a pilgrimage to a high holy shrine.",["title"]="Kranal Fiss"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1524:description:1-89","1524:description:94-213","1524:description:215-343","1524:description:348-410","1524:description:412-510","1524:objective:1-63"},["minimumStage"]=2,["questID"]=1524,["sourceHash"]="5401786b258286cc3e038d99f5b90490430d1a77d25bbd34ae4eadf9818c8257"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5907",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He entrusted the trial’s torch to Telf Joolam’s care at the Shrine of the Dormant Flame, expecting it returned alight.",["title"]="Kranal Fiss"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1525:description:1-56","1525:description:58-103","1525:description:108-169","1525:description:174-235","1525:description:237-334","1525:description:339-440","1525:description:442-511","1525:objective:1-63"},["minimumStage"]=2,["questID"]=1525,["sourceHash"]="b3a357e7d6c98f816d820c81ba982b9855db9c048fe195a2a01f31c964122d80"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5900",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Telf prepared fire sapta to bind a shaman to the flame as a step toward the Eternal Flame and fire totem.",["title"]="Telf Joolam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1525:description:1-56","1525:description:58-103","1525:description:108-169","1525:description:174-235","1525:description:237-334","1525:description:339-440","1525:description:442-511","1525:objective:1-63"},["minimumStage"]=2,["questID"]=1525,["sourceHash"]="b3a357e7d6c98f816d820c81ba982b9855db9c048fe195a2a01f31c964122d80"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5900",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His preparation required fire tar from Razormane spellcasters and a reagent pouch from the Burning Blade.",["title"]="Telf Joolam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1528:description:1-27","1528:description:29-121","1528:description:126-166","1528:description:168-252","1528:description:254-329","1528:description:331-355","1528:description:360-435","1528:objective:1-36"},["minimumStage"]=2,["questID"]=1528,["sourceHash"]="05beac15296e7c7084f192a3592f7004fd1bdc5ababbd3e245fac28e8beae4f2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5892",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Searn recognized mastery of fire as preparation for learning the ways of water.",["title"]="Searn Firewarder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1528:description:1-27","1528:description:29-121","1528:description:126-166","1528:description:168-252","1528:description:254-329","1528:description:331-355","1528:description:360-435","1528:objective:1-36"},["minimumStage"]=2,["questID"]=1528,["sourceHash"]="05beac15296e7c7084f192a3592f7004fd1bdc5ababbd3e245fac28e8beae4f2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5892",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed pupils to Islen on the Barrens coast beyond Ratchet, identifying her place by a great shark.",["title"]="Searn Firewarder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1532:description:1-117","1532:description:119-192","1532:description:197-340","1532:description:345-410","1532:description:412-476","1532:description:478-501","1532:objective:1-41"},["minimumStage"]=2,["questID"]=1532,["sourceHash"]="5a6275dd201c8b909ec951b269a1040747fab2a1a4855b38e702f7d3ced488e2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5906",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xanis regarded air as a difficult element to control but expressed confidence in a promising pupil’s ability to master it.",["title"]="Xanis Flameweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1532:description:1-117","1532:description:119-192","1532:description:197-340","1532:description:345-410","1532:description:412-476","1532:description:478-501","1532:objective:1-41"},["minimumStage"]=2,["questID"]=1532,["sourceHash"]="5a6275dd201c8b909ec951b269a1040747fab2a1a4855b38e702f7d3ced488e2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5906",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent those ready to study air to Prate Cloudseer in eastern Thousand Needles.",["title"]="Xanis Flameweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1534:description:1-86","1534:description:88-125","1534:description:130-173","1534:description:175-309","1534:description:311-367","1534:description:372-413","1534:description:415-489","1534:objective:1-103"},["minimumStage"]=2,["questID"]=1534,["sourceHash"]="0634b25eabf224211c2b7242a132a89192d1a705783cac9b864c99a4cf978745"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5899",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brine required water from the fountain at the Ruins of Stardust as the final component before returning a pupil to Islen.",["title"]="Brine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1534:description:1-86","1534:description:88-125","1534:description:130-173","1534:description:175-309","1534:description:311-367","1534:description:372-413","1534:description:415-489","1534:objective:1-103"},["minimumStage"]=2,["questID"]=1534,["sourceHash"]="0634b25eabf224211c2b7242a132a89192d1a705783cac9b864c99a4cf978745"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-5899",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her directions placed the sacred ruins beyond Lake Mystral beside the mountains dividing Ashenvale from Stonetalon.",["title"]="Brine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1578:description:1-81","1578:description:84-182","1578:description:187-274","1578:description:277-387","1578:description:390-432","1578:description:437-485","1578:objective:1-99"},["minimumStage"]=2,["questID"]=1578,["sourceHash"]="d9609fe40ace69096129e619e115fb243de3f008b1d8d0e0ff1eede30de42911"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6031",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tormus sought a steady supply of new weapons and armor for Loch Modan’s mountaineers fighting troggs.",["title"]="Tormus Deepforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1578:description:1-81","1578:description:84-182","1578:description:187-274","1578:description:277-387","1578:description:390-432","1578:description:437-485","1578:objective:1-99"},["minimumStage"]=2,["questID"]=1578,["sourceHash"]="d9609fe40ace69096129e619e115fb243de3f008b1d8d0e0ff1eede30de42911"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6031",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His colleague Thorvald worked from the southern guard tower to keep the mountaineers equipped.",["title"]="Tormus Deepforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1598:description:1-10","1598:description:12-21","1598:description:26-140","1598:description:145-213","1598:description:218-301","1598:description:303-316","1598:description:318-353","1598:description:358-438","1598:description:440-507","1598:objective:1-54"},["minimumStage"]=2,["questID"]=1598,["sourceHash"]="a07d203956747c9ebb21a8a732d9708ba20bbbe0eada41a3b894dc69f44e66bc"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-459",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Drusilla coveted the Powers of the Void, one of the books stolen by an Abbey novice who joined the Defias.",["title"]="Drusilla La Salle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1598:description:1-10","1598:description:12-21","1598:description:26-140","1598:description:145-213","1598:description:218-301","1598:description:303-316","1598:description:318-353","1598:description:358-438","1598:description:440-507","1598:objective:1-54"},["minimumStage"]=2,["questID"]=1598,["sourceHash"]="a07d203956747c9ebb21a8a732d9708ba20bbbe0eada41a3b894dc69f44e66bc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-459",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She used recovery of the stolen book as a test of a novice warlock’s ability to survive the calling.",["title"]="Drusilla La Salle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1599:description:1-61","1599:description:63-180","1599:description:185-225","1599:description:230-300","1599:description:302-411","1599:description:416-503","1599:objective:1-51"},["minimumStage"]=2,["questID"]=1599,["sourceHash"]="0e2cacda7f416ce81f00413adb62ad52477d186971f12f4aa9c6c9043019cfb2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-460",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alamar interrupted his research to teach a new warlock the basic summoning of an imp.",["title"]="Alamar Grimm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1599:description:1-61","1599:description:63-180","1599:description:185-225","1599:description:230-300","1599:description:302-411","1599:description:416-503","1599:objective:1-51"},["minimumStage"]=2,["questID"]=1599,["sourceHash"]="0e2cacda7f416ce81f00413adb62ad52477d186971f12f4aa9c6c9043019cfb2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-460",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Before teaching, he tested both magical and physical ability by requiring feather charms from Frostmane novices.",["title"]="Alamar Grimm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1644:description:1-100","1644:description:105-236","1644:description:238-320","1644:description:325-336","1644:description:338-362","1644:description:364-402","1644:description:407-511","1644:objective:1-54"},["minimumStage"]=2,["questID"]=1644,["sourceHash"]="d5a8680672f84d778cfda34d4e69d7290aeff3bfaa9b9a5b759b7aff17be652b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6174",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stephanie cared for orphaned children, many bereaved by Scourge attacks, and sewed their clothes from materials John collected.",["title"]="Stephanie Turner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1644:description:1-100","1644:description:105-236","1644:description:238-320","1644:description:325-336","1644:description:338-362","1644:description:364-402","1644:description:407-511","1644:objective:1-54"},["minimumStage"]=2,["questID"]=1644,["sourceHash"]="d5a8680672f84d778cfda34d4e69d7290aeff3bfaa9b9a5b759b7aff17be652b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6174",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keeping the children fed and sheltered left her little time to make the shirts and trousers they needed.",["title"]="Stephanie Turner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1647:description:1-80","1647:description:82-121","1647:description:123-153","1647:description:155-189","1647:description:191-268","1647:description:273-320","1647:description:322-409","1647:description:411-459","1647:description:461-502","1647:objective:1-51"},["minimumStage"]=2,["questID"]=1647,["sourceHash"]="bd7cef9a94907e34b706de975fb3338c112d7acc96eafd9e6876efb275e3ee85"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6179",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tiza taught that paladinhood required practical kindness toward someone whose own purpose was noble, not merely another trial of arms.",["title"]="Tiza Battleforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1647:description:1-80","1647:description:82-121","1647:description:123-153","1647:description:155-189","1647:description:191-268","1647:description:273-320","1647:description:322-409","1647:description:411-459","1647:description:461-502","1647:objective:1-51"},["minimumStage"]=2,["questID"]=1647,["sourceHash"]="bd7cef9a94907e34b706de975fb3338c112d7acc96eafd9e6876efb275e3ee85"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-6179",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She remained in Ironforge’s temple to guide other paladins while a pupil sought someone in need.",["title"]="Tiza Battleforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1648:description:1-140","1648:description:142-311","1648:description:316-374","1648:description:379-485","1648:objective:1-49"},["minimumStage"]=2,["questID"]=1648,["sourceHash"]="e5f9fb911e3b09e581621d07d47b8f77c04575a7a46b9bfff460776a63414390"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6175",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="John traveled to Ironforge roughly monthly to collect supplies and seek help for the Stormwind orphanage he ran with Stephanie.",["title"]="John Turner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1648:description:1-140","1648:description:142-311","1648:description:316-374","1648:description:379-485","1648:objective:1-49"},["minimumStage"]=2,["questID"]=1648,["sourceHash"]="e5f9fb911e3b09e581621d07d47b8f77c04575a7a46b9bfff460776a63414390"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6175",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A slow, unproductive visit left him unable to send home the linen his wife needed for the children’s clothing.",["title"]="John Turner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1650:description:1-5","1650:description:7-94","1650:description:109-184","1650:description:186-222","1650:description:224-318","1650:description:320-377","1650:description:382-497","1650:description:499-507","1650:objective:1-33"},["minimumStage"]=2,["questID"]=1650,["sourceHash"]="5bd4b1a8a4a19a8c216e0d3008103916558b718c2c6b9759f259b11e87d59ea3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6171",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Duthorian sent a paladin to protect Daphne Stilwell at her isolated Longshore house while her husband visited Ironforge.",["title"]="Duthorian Rall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1650:description:1-5","1650:description:7-94","1650:description:109-184","1650:description:186-222","1650:description:224-318","1650:description:320-377","1650:description:382-497","1650:description:499-507","1650:objective:1-33"},["minimumStage"]=2,["questID"]=1650,["sourceHash"]="5bd4b1a8a4a19a8c216e0d3008103916558b718c2c6b9759f259b11e87d59ea3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6171",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He praised Jordan’s smithing and feared that the Defias presence around the Stilwells’ home left Daphne vulnerable.",["title"]="Duthorian Rall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1654:description:1-66","1654:description:68-206","1654:description:211-364","1654:description:366-479","1654:description:481-500","1654:objective:1-182"},["minimumStage"]=2,["questID"]=1654,["sourceHash"]="7a4eb5cd4ee7ed8d15984a8ea9ad8ae952eb0b18cd73fadbc5f7a3522ce08d6c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6181",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jordan offered to forge a weapon as a symbol of paladinhood and the Light.",["title"]="Jordan Stilwell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1654:description:1-66","1654:description:68-206","1654:description:211-364","1654:description:366-479","1654:description:481-500","1654:objective:1-182"},["minimumStage"]=2,["questID"]=1654,["sourceHash"]="7a4eb5cd4ee7ed8d15984a8ea9ad8ae952eb0b18cd73fadbc5f7a3522ce08d6c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6181",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His reward required a capable traveler to gather the materials he had already researched and listed.",["title"]="Jordan Stilwell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1655:description:1-35","1655:description:37-71","1655:description:76-87","1655:description:89-108","1655:description:110-123","1655:description:125-160","1655:description:162-178","1655:description:180-223","1655:description:225-284","1655:description:286-393","1655:description:398-469","1655:description:471-501","1655:objective:1-62"},["minimumStage"]=2,["questID"]=1655,["sourceHash"]="a8b791239b6c6a4a9ffe8c6a0e77cec3a1e44749a1b7d487720d4fee0e2a45a2"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6241",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mo’grosh ogres ambushed the Wetlands caravan carrying Bailor’s ore shipment for Jordan; the surviving guard later died before a healer could save him.",["title"]="Bailor Stonehand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1655:description:1-35","1655:description:37-71","1655:description:76-87","1655:description:89-108","1655:description:110-123","1655:description:125-160","1655:description:162-178","1655:description:180-223","1655:description:225-284","1655:description:286-393","1655:description:398-469","1655:description:471-501","1655:objective:1-62"},["minimumStage"]=2,["questID"]=1655,["sourceHash"]="a8b791239b6c6a4a9ffe8c6a0e77cec3a1e44749a1b7d487720d4fee0e2a45a2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6241",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bailor called Jordan an old friend and placed the stolen shipment among the ogres northeast across the Loch.",["title"]="Bailor Stonehand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1286:description:1-177","1286:description:182-348","1286:description:353-398","1286:description:400-446","1286:description:451-464","1286:description:466-496","1286:objective:1-85"},["minimumStage"]=2,["questID"]=1286,["sourceHash"]="fc39aa52dfd48b72cab6f14556f41e8bd7fd489840b433a045d6718d862fc435"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-506",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theramore’s abandoned watchtower became a refuge for deserters whose local lieutenant was Balos Jacken.",["title"]="Lost Point"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1286:description:1-177","1286:description:182-348","1286:description:353-398","1286:description:400-446","1286:description:451-464","1286:description:466-496","1286:objective:1-85"},["minimumStage"]=2,["questID"]=1286,["sourceHash"]="fc39aa52dfd48b72cab6f14556f41e8bd7fd489840b433a045d6718d862fc435"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-506",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vimes placed the deserted tower southeast of the inn in Dustwallow.",["title"]="Lost Point"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1302:description:1-58","1302:description:60-174","1302:description:176-225","1302:description:227-248","1302:description:253-387","1302:description:389-459","1302:description:461-479","1302:description:481-508","1302:objective:1-57"},["minimumStage"]=2,["questID"]=1302,["sourceHash"]="f03b8762670c9d42ca1085bdf5375776cc84315f2902f513ada413a2e155632c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-514",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theramore’s clerk worked on the keep’s upper floor and could help travelers find people who had settled in the city.",["title"]="Foothold Citadel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1419:description:1-45","1419:description:48-70","1419:description:72-126","1419:description:129-146","1419:description:151-181","1419:description:184-261","1419:description:264-301","1419:description:306-327","1419:description:330-367","1419:description:370-447","1419:objective:1-55"},["minimumStage"]=2,["questID"]=1419,["sourceHash"]="9496479fa94028e39fef45f67b01859875ba39399ef0ca4de1a63375bf04d366"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-340",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Crag coyotes grew bold enough to creep into the outpost and steal from its food supplies.",["title"]="Kargath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1453:description:1-40","1453:description:42-104","1453:description:106-223","1453:description:228-340","1453:description:342-399","1453:description:401-440","1453:objective:1-35"},["minimumStage"]=2,["questID"]=1453,["sourceHash"]="1640bf2ed9f9ad6dda55e8f21f46091de2e2604b837a9919062fddb77a13e75a"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-608",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A small camp sheltered among northern Desolace’s mountains, easy for a traveler to overlook.",["title"]="Nijel's Point"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1453:description:1-40","1453:description:42-104","1453:description:106-223","1453:description:228-340","1453:description:342-399","1453:description:401-440","1453:objective:1-35"},["minimumStage"]=2,["questID"]=1453,["sourceHash"]="1640bf2ed9f9ad6dda55e8f21f46091de2e2604b837a9919062fddb77a13e75a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-608",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kreldig Ungor received travelers sent by Roetten to help with the Reclaimers’ work in Desolace.",["title"]="Nijel's Point"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1524:description:1-89","1524:description:94-213","1524:description:215-343","1524:description:348-410","1524:description:412-510","1524:objective:1-63"},["minimumStage"]=2,["questID"]=1524,["sourceHash"]="5401786b258286cc3e038d99f5b90490430d1a77d25bbd34ae4eadf9818c8257"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-640",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A hidden trail along Durotar’s Southfury approach led up to the high peak bearing this holy shrine.",["title"]="Shrine of the Dormant Flame"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1524:description:1-89","1524:description:94-213","1524:description:215-343","1524:description:348-410","1524:description:412-510","1524:objective:1-63"},["minimumStage"]=2,["questID"]=1524,["sourceHash"]="5401786b258286cc3e038d99f5b90490430d1a77d25bbd34ae4eadf9818c8257"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-640",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Telf Joolam watched the shrine, where a shaman’s trial torch was to be kindled at the brazier.",["title"]="Shrine of the Dormant Flame"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1534:description:1-86","1534:description:88-125","1534:description:130-173","1534:description:175-309","1534:description:311-367","1534:description:372-413","1534:description:415-489","1534:objective:1-103"},["minimumStage"]=2,["questID"]=1534,["sourceHash"]="0634b25eabf224211c2b7242a132a89192d1a705783cac9b864c99a4cf978745"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A fountain stood in the center of the lake at this sacred ruin.",["title"]="The Ruins of Stardust"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1534:description:1-86","1534:description:88-125","1534:description:130-173","1534:description:175-309","1534:description:311-367","1534:description:372-413","1534:description:415-489","1534:objective:1-103"},["minimumStage"]=2,["questID"]=1534,["sourceHash"]="0634b25eabf224211c2b7242a132a89192d1a705783cac9b864c99a4cf978745"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brine required the fountain’s water for a shaman’s preparation before returning to Islen.",["title"]="The Ruins of Stardust"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1498:description:1-49","1498:description:51-61","1498:description:64-132","1498:description:135-205","1498:description:210-292","1498:description:295-310","1498:description:313-346","1498:description:349-422","1498:description:427-461","1498:objective:1-64"},["minimumStage"]=2,["questID"]=1498,["sourceHash"]="d2b1dda553be7368f5876dd3a255a7a396f20fa698ec45832b9642c5f10caab2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-369",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lightning hides and thunder lizards supplied a dangerous proving ground for warriors sent by Uzzek.",["title"]="Thunder Ridge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1650:description:1-5","1650:description:7-94","1650:description:109-184","1650:description:186-222","1650:description:224-318","1650:description:320-377","1650:description:382-497","1650:description:499-507","1650:objective:1-33"},["minimumStage"]=2,["questID"]=1650,["sourceHash"]="5bd4b1a8a4a19a8c216e0d3008103916558b718c2c6b9759f259b11e87d59ea3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-2",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="At the far end of the shore, the Stilwells’ small house overlooked the ocean, isolated amid reports of Defias control.",["title"]="Longshore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1266:description:1-38","1266:description:40-128","1266:description:130-249","1266:description:254-332","1266:description:337-412","1266:description:414-492","1266:objective:1-40"},["minimumStage"]=2,["questID"]=1266,["sourceHash"]="c05b16ef5e646d7834a12ab71f82b89acfd46a3bb40a1f36081c6b3177850a4a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-496",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theramore’s infiltrators kept watch on the Horde base as part of their effort to identify threats to the border.",["title"]="Brackenwall Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1395:description:1-80","1395:description:83-164","1395:description:169-219","1395:description:224-280","1395:description:283-422","1395:description:427-442","1395:description:445-507","1395:objective:1-88"},["minimumStage"]=2,["questID"]=1395,["sourceHash"]="cf5c6ab99af950a1deaaba09e671b0338631cec1e05cb4a3145c697b923b5836"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1438",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Quartermaster Lungertz received urgent powerstone supplies whose fading strength made waiting for the caravan impractical.",["title"]="Nethergarde Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1656:description:1-42","1656:description:44-201","1656:description:206-285","1656:description:287-317","1656:description:322-394","1656:description:396-433","1656:objective:1-65"},["minimumStage"]=2,["questID"]=1656,["sourceHash"]="99363f136ccf40162ca2105bf812da5633628afc3d11fce65b4ce3f97c712167"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6775",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Antur was struggling to complete his Rite of Strength while also carrying out his father’s request to deliver furs to Bloodhoof’s inn.",["title"]="Antur Fallow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1656:description:1-42","1656:description:44-201","1656:description:206-285","1656:description:287-317","1656:description:322-394","1656:description:396-433","1656:objective:1-65"},["minimumStage"]=2,["questID"]=1656,["sourceHash"]="99363f136ccf40162ca2105bf812da5633628afc3d11fce65b4ce3f97c712167"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6775",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He remembered the inn as a pleasant resting place and sought another traveler’s help with the delivery.",["title"]="Antur Fallow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1657:description:1-34","1657:description:36-82","1657:description:87-134","1657:description:137-250","1657:description:253-379","1657:description:384-417","1657:description:419-463","1657:objective:1-150"},["minimumStage"]=2,["questID"]=1657,["sourceHash"]="c1bbcfebc21034aae3fa02d52b83fa610eacaf1ee7169028682d20bf642d1b9c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15197",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yanka treated Hallow’s End raids on Southshore as a tribute to the Forsaken’s liberation.",["title"]="Darkcaller Yanka"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1657:description:1-34","1657:description:36-82","1657:description:87-134","1657:description:137-250","1657:description:253-379","1657:description:384-417","1657:description:419-463","1657:objective:1-150"},["minimumStage"]=2,["questID"]=1657,["sourceHash"]="c1bbcfebc21034aae3fa02d52b83fa610eacaf1ee7169028682d20bf642d1b9c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15197",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She supplied specially made stink bombs to foul the town’s center and warned that the Alliance would resist.",["title"]="Darkcaller Yanka"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1658:description:1-91","1658:description:94-151","1658:description:154-210","1658:description:213-346","1658:description:351-415","1658:description:418-495","1658:objective:1-59","1658:objective:62-122"},["minimumStage"]=2,["questID"]=1658,["sourceHash"]="64c68ada1ccfc615bb350c29e62f7c02d620ef93e1da3951ebc6ac8dc8a5c683"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15199",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hartman wanted scouts to assess the size of the Wickerman Festival and the trouble the Forsaken might cause during Hallow’s End.",["title"]="Sergeant Hartman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1658:description:1-91","1658:description:94-151","1658:description:154-210","1658:description:213-346","1658:description:351-415","1658:description:418-495","1658:objective:1-59","1658:objective:62-122"},["minimumStage"]=2,["questID"]=1658,["sourceHash"]="64c68ada1ccfc615bb350c29e62f7c02d620ef93e1da3951ebc6ac8dc8a5c683"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15199",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned that the festival’s Tirisfal guards would make the reconnaissance dangerous.",["title"]="Sergeant Hartman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1683:description:1-54","1683:description:59-161","1683:description:164-230","1683:description:235-278","1683:description:281-360","1683:description:365-457","1683:objective:1-50"},["minimumStage"]=2,["questID"]=1683,["sourceHash"]="c92d3cc4f83f7a887da43d25ca6968101b4e593d28c6e3c26530eeee97ab3ca3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4088",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Elanaria required proof of resolve against Vorlus Vilehoof, a satyr defiling a remote moonwell, before offering advanced warrior instruction.",["title"]="Elanaria"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1683:description:1-54","1683:description:59-161","1683:description:164-230","1683:description:235-278","1683:description:281-360","1683:description:365-457","1683:objective:1-50"},["minimumStage"]=2,["questID"]=1683,["sourceHash"]="c92d3cc4f83f7a887da43d25ca6968101b4e593d28c6e3c26530eeee97ab3ca3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4088",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She knew the well southeast of Ban’ethil lay at the end of a well-hidden path.",["title"]="Elanaria"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1685:description:1-31","1685:description:33-147","1685:description:152-227","1685:description:229-280","1685:description:282-337","1685:description:342-404","1685:description:406-471","1685:description:473-507","1685:objective:1-64"},["minimumStage"]=2,["questID"]=1685,["sourceHash"]="038f707f15041462ce8b1f2c6c46e5a0780618664585f1e1c09d0913530b0e52"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6121",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Remen carried Gakin’s summons for further warlock training after spending the day trying to find the pupil.",["title"]="Remen Marcot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1685:description:1-31","1685:description:33-147","1685:description:152-227","1685:description:229-280","1685:description:282-337","1685:description:342-404","1685:description:406-471","1685:description:473-507","1685:objective:1-64"},["minimumStage"]=2,["questID"]=1685,["sourceHash"]="038f707f15041462ce8b1f2c6c46e5a0780618664585f1e1c09d0913530b0e52"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6121",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He urged discretion about Gakin’s training place in the Slaughtered Lamb’s basement.",["title"]="Remen Marcot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1688:description:1-37","1688:description:39-140","1688:description:142-194","1688:description:196-238","1688:description:243-310","1688:description:312-401","1688:description:406-438","1688:description:440-488","1688:description:490-511","1688:objective:1-63"},["minimumStage"]=2,["questID"]=1688,["sourceHash"]="57d2bfb86b832a274290927ccf0189a21445e912c9460fc230317153dfd2e0c3"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6122",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Surena Caledon had been Gakin’s talented pupil before leaving with the Defias member Erlan Drudgemoor.",["title"]="Gakin the Darkbinder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1688:description:1-37","1688:description:39-140","1688:description:142-194","1688:description:196-238","1688:description:243-310","1688:description:312-401","1688:description:406-438","1688:description:440-488","1688:description:490-511","1688:objective:1-63"},["minimumStage"]=2,["questID"]=1688,["sourceHash"]="57d2bfb86b832a274290927ccf0189a21445e912c9460fc230317153dfd2e0c3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6122",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Angered by her departure, he demanded the return of a bloodstone choker he had given her, disregarding her safety.",["title"]="Gakin the Darkbinder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1699:description:1-41","1699:description:44-144","1699:description:147-151","1699:description:154-187","1699:description:192-225","1699:description:230-281","1699:description:286-378","1699:description:383-401","1699:description:404-463","1699:description:466-507","1699:objective:1-104","1699:objective:109-149"},["minimumStage"]=2,["questID"]=1699,["sourceHash"]="e7dc60aca73c6bfa02605b04b5fbba5d5705587d078518bca6f4887426ad8962"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6166",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yorus tested warriors with a run into Rethban Caverns after a drink of his family’s Barleybrew Scalder, with gnolls and a time limit complicating the trial.",["title"]="Yorus Barleybrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1707:description:1-96","1707:description:99-105","1707:description:110-239","1707:description:242-305","1707:description:308-402","1707:description:405-466","1707:objective:1-76"},["minimumStage"]=2,["questID"]=1707,["sourceHash"]="628ae04a11e9f269ddb2ed1683e727c75a6385e521e1d58d56e89ac0f0c2d6f9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7408",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Luglunket operated a spigot for Gadgetzan’s water enterprise and exchanged care packages for recovered Wastewander water pouches.",["title"]="Spigot Operator Luglunket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1707:description:1-96","1707:description:99-105","1707:description:110-239","1707:description:242-305","1707:description:308-402","1707:description:405-466","1707:objective:1-76"},["minimumStage"]=2,["questID"]=1707,["sourceHash"]="628ae04a11e9f269ddb2ed1683e727c75a6385e521e1d58d56e89ac0f0c2d6f9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7408",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He maintained that the desert nomads had stolen the water from Gadgetzan and presented recovery as helping the town sustain itself.",["title"]="Spigot Operator Luglunket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1708:description:1-72","1708:description:75-165","1708:description:170-228","1708:description:231-315","1708:description:320-389","1708:description:392-405","1708:description:408-461","1708:objective:1-70"},["minimumStage"]=2,["questID"]=1708,["sourceHash"]="2b01a078bd837c849c3734203c11f0752118553cfdc30c6437f98a6b1c4ec746"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6169",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Klockmort eagerly sought searing coral to try Furen Longbeard’s newly discovered techniques on a piece of armor.",["title"]="Klockmort Spannerspan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1708:description:1-72","1708:description:75-165","1708:description:170-228","1708:description:231-315","1708:description:320-389","1708:description:392-405","1708:description:408-461","1708:objective:1-70"},["minimumStage"]=2,["questID"]=1708,["sourceHash"]="2b01a078bd837c849c3734203c11f0752118553cfdc30c6437f98a6b1c4ec746"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6169",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered the finished armor to the traveler whose earlier assistance had helped Furen share the discovery.",["title"]="Klockmort Spannerspan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1710:description:1-73","1710:description:76-193","1710:description:198-214","1710:description:217-301","1710:description:306-408","1710:description:411-502","1710:objective:1-52"},["minimumStage"]=2,["questID"]=1710,["sourceHash"]="dc19984e68ec8f8f52cfa1d52c37ebc7345d05a1442199abb18186e3bad6fa4f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6142",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mathiel wanted Highperch wyvern eggshells to test Furen Longbeard’s techniques on new armor he was researching.",["title"]="Mathiel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1710:description:1-73","1710:description:76-193","1710:description:198-214","1710:description:217-301","1710:description:306-408","1710:description:411-502","1710:objective:1-52"},["minimumStage"]=2,["questID"]=1710,["sourceHash"]="dc19984e68ec8f8f52cfa1d52c37ebc7345d05a1442199abb18186e3bad6fa4f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6142",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He called Furen a colleague and offered an extra piece of armor in exchange for gathering the materials.",["title"]="Mathiel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1712:description:1-37","1712:description:40-101","1712:description:104-163","1712:description:168-197","1712:description:202-216","1712:description:219-303","1712:description:306-366","1712:description:371-462","1712:description:467-508","1712:objective:1-79"},["minimumStage"]=2,["questID"]=1712,["sourceHash"]="640b2babf23093f8197dc15e903877f7007452ace1e334598260ea9b9e1bf7b3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6176",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bath’rah had watched for ages in hope of seeing Cyclonian fall, but still sought a champion able to defeat the wind lord.",["title"]="Bath'rah the Windwatcher"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1712:description:1-37","1712:description:40-101","1712:description:104-163","1712:description:168-197","1712:description:202-216","1712:description:219-303","1712:description:306-366","1712:description:371-462","1712:description:467-508","1712:objective:1-79"},["minimumStage"]=2,["questID"]=1712,["sourceHash"]="640b2babf23093f8197dc15e903877f7007452ace1e334598260ea9b9e1bf7b3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6176",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered to summon Cyclonian and bind the power of its whirlwind heart into a weapon if a warrior could obtain it.",["title"]="Bath'rah the Windwatcher"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1715:description:1-5","1715:description:7-299","1715:description:304-398","1715:description:403-482","1715:objective:1-64"},["minimumStage"]=2,["questID"]=1715,["sourceHash"]="4a18e25163a87af6a8f5f2ad81eef4c6ede15ccf080e0772551c978aea80a38d"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6120",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lago recalled warlock instruction in Khaz Modan once operating under Gnomeregan’s masters, before their forced relocation to Ironforge.",["title"]="Lago Blackwrench"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1715:description:1-5","1715:description:7-299","1715:description:304-398","1715:description:403-482","1715:objective:1-64"},["minimumStage"]=2,["questID"]=1715,["sourceHash"]="4a18e25163a87af6a8f5f2ad81eef4c6ede15ccf080e0772551c978aea80a38d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6120",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magni’s close watch on the displaced warlocks forced Lago to send novices to Gakin in Stormwind, a restriction he bitterly resented.",["title"]="Lago Blackwrench"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1719:description:1-66","1719:description:69-212","1719:description:217-290","1719:description:293-374","1719:description:379-431","1719:description:434-486","1719:objective:1-60"},["minimumStage"]=2,["questID"]=1719,["sourceHash"]="e7d9cea738063d05003ad56273a4d75382f9a28eaa8b53e52e7b5b34b5680732"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6236",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Klannoc admitted rising warriors to his instruction only after the Affray, Fray Island’s test of successive challengers and Big Will.",["title"]="Klannoc Macleod"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1719:description:1-66","1719:description:69-212","1719:description:217-290","1719:description:293-374","1719:description:379-431","1719:description:434-486","1719:objective:1-60"},["minimumStage"]=2,["questID"]=1719,["sourceHash"]="e7d9cea738063d05003ad56273a4d75382f9a28eaa8b53e52e7b5b34b5680732"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6236",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Twiggy Flathead organized the opponents after a contestant stepped onto the grate.",["title"]="Klannoc Macleod"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1738:description:1-101","1738:description:103-135","1738:description:140-202","1738:description:204-307","1738:description:312-353","1738:description:355-450","1738:objective:1-109"},["minimumStage"]=2,["questID"]=1738,["sourceHash"]="51053311c74160a843988d96e45aa0a40e95459126c9a330a398c0033126eaf2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6244",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Takar said his sight through time revealed a tree grown where two lovers died together during the War of the Ancients.",["title"]="Takar the Seer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1738:description:1-101","1738:description:103-135","1738:description:140-202","1738:description:204-307","1738:description:312-353","1738:description:355-450","1738:objective:1-109"},["minimumStage"]=2,["questID"]=1738,["sourceHash"]="51053311c74160a843988d96e45aa0a40e95459126c9a330a398c0033126eaf2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6244",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He identified that heartswood in Ordil’Aran as a symbol of undying love powerful enough to tempt a succubus.",["title"]="Takar the Seer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1740:description:1-130","1740:description:135-181","1740:description:183-258","1740:description:263-407","1740:description:409-478","1740:description:480-509","1740:objective:1-104"},["minimumStage"]=2,["questID"]=1740,["sourceHash"]="b83e9d0b75d48e4ac13b96cc0e07ba6d7a8be35deee167139b84f6d134fd7024"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6247",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Doan explained that demons fallen from favor could have their spirits imprisoned in orbs whose fragments retained power.",["title"]="Doan Karhan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1740:description:1-130","1740:description:135-181","1740:description:183-258","1740:description:263-407","1740:description:409-478","1740:description:480-509","1740:objective:1-104"},["minimumStage"]=2,["questID"]=1740,["sourceHash"]="b83e9d0b75d48e4ac13b96cc0e07ba6d7a8be35deee167139b84f6d134fd7024"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6247",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered to reform Soran’ruk’s broken orb from pieces held by Twilight’s Hammer acolytes in Blackfathom and a wizard in Shadowfang.",["title"]="Doan Karhan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1758:description:1-97","1758:description:102-167","1758:description:169-253","1758:description:255-330","1758:description:335-379","1758:description:381-499","1758:objective:1-38"},["minimumStage"]=2,["questID"]=1758,["sourceHash"]="2c43dc7637c7fe53853ae84cd22f32fbc5f8fa1bffdf5b8de14d9d36d31b0155"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6251",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Strahad and three acolytes assisted with the elaborate magic circles needed to summon a felhunter for a warlock’s challenge.",["title"]="Strahad Farsan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1758:description:1-97","1758:description:102-167","1758:description:169-253","1758:description:255-330","1758:description:335-379","1758:description:381-499","1758:objective:1-38"},["minimumStage"]=2,["questID"]=1758,["sourceHash"]="2c43dc7637c7fe53853ae84cd22f32fbc5f8fa1bffdf5b8de14d9d36d31b0155"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6251",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought the lost Tome of the Cabal, an account by the first warlocks to summon a felhunter unaided, and recommended consulting Krom Stoutarm.",["title"]="Strahad Farsan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1783:description:1-94","1783:description:96-231","1783:description:236-361","1783:description:363-412","1783:description:417-467","1783:description:472-487","1783:objective:1-63"},["minimumStage"]=2,["questID"]=1783,["sourceHash"]="d3129effbef6e23b3fb718084599a199b9dcb46f6956f59c31d9132c8203be05"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6178",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Muiredon and Narm spied on Dark Iron dwarves south of Helm’s Bed Lake, then were overwhelmed after attacking.",["title"]="Muiredon Battleforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1783:description:1-94","1783:description:96-231","1783:description:236-361","1783:description:363-412","1783:description:417-467","1783:description:472-487","1783:objective:1-63"},["minimumStage"]=2,["questID"]=1783,["sourceHash"]="d3129effbef6e23b3fb718084599a199b9dcb46f6956f59c31d9132c8203be05"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6178",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Narm sent him to get support; Muiredon refused to rest while his companion still needed help.",["title"]="Muiredon Battleforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1784:description:1-109","1784:description:111-204","1784:description:209-315","1784:description:317-443","1784:description:448-505","1784:objective:1-120"},["minimumStage"]=2,["questID"]=1784,["sourceHash"]="3783e67b8994e1c6919dbf547c259c1445229c9307b7b2fa036e29f73caf412c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6177",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Narm sought the Dark Iron captain’s orders as proof for councilors who doubted their presence in Dun Morogh.",["title"]="Narm Faulk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1784:description:1-109","1784:description:111-204","1784:description:209-315","1784:description:317-443","1784:description:448-505","1784:objective:1-120"},["minimumStage"]=2,["questID"]=1784,["sourceHash"]="3783e67b8994e1c6919dbf547c259c1445229c9307b7b2fa036e29f73caf412c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6177",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He had fallen fighting the spies after his reconnaissance with Muiredon and needed another person to recover the documents.",["title"]="Narm Faulk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1786:description:1-109","1786:description:111-211","1786:description:216-298","1786:description:300-363","1786:description:368-412","1786:description:414-450","1786:description:455-483","1786:description:485-504","1786:objective:1-60"},["minimumStage"]=2,["questID"]=1786,["sourceHash"]="bdd71605a237202a925ec19cc3216e07238edbf6e2cf4db53411d8e9695497fd"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6173",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gazin and Henze attacked Defias mages at Heroes’ Vigil while seeking evidence of their infiltration, but reinforcements overwhelmed them.",["title"]="Gazin Tenorm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1786:description:1-109","1786:description:111-211","1786:description:216-298","1786:description:300-363","1786:description:368-412","1786:description:414-450","1786:description:455-483","1786:description:485-504","1786:objective:1-60"},["minimumStage"]=2,["questID"]=1786,["sourceHash"]="bdd71605a237202a925ec19cc3216e07238edbf6e2cf4db53411d8e9695497fd"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6173",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Henze held their attackers back so Gazin could escape, leaving Gazin desperate to find help for his companion.",["title"]="Gazin Tenorm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1787:description:1-62","1787:description:64-136","1787:description:138-286","1787:description:291-331","1787:description:333-421","1787:description:426-509","1787:objective:1-106"},["minimumStage"]=2,["questID"]=1787,["sourceHash"]="6bda9f2be36ac364d04b299d8cb9bb02d8149e72238780437e8454cf4a9f25a2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6172",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Henze wanted the Defias papers carried to Gazin as evidence of infiltration and a possible clue to their plans.",["title"]="Henze Faulk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1787:description:1-62","1787:description:64-136","1787:description:138-286","1787:description:291-331","1787:description:333-421","1787:description:426-509","1787:objective:1-106"},["minimumStage"]=2,["questID"]=1787,["sourceHash"]="6bda9f2be36ac364d04b299d8cb9bb02d8149e72238780437e8454cf4a9f25a2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6172",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Too badly hurt to fight, he depended on another person to recover the papers and tell Gazin he was alive.",["title"]="Henze Faulk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1683:description:1-54","1683:description:59-161","1683:description:164-230","1683:description:235-278","1683:description:281-360","1683:description:365-457","1683:objective:1-50"},["minimumStage"]=2,["questID"]=1683,["sourceHash"]="c92d3cc4f83f7a887da43d25ca6968101b4e593d28c6e3c26530eeee97ab3ca3"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6128",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vorlus had occupied a remote moonwell southeast of Ban’ethil, splashing in and defiling its sacred water.",["title"]="Vorlus Vilehoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1683:description:1-54","1683:description:59-161","1683:description:164-230","1683:description:235-278","1683:description:281-360","1683:description:365-457","1683:objective:1-50"},["minimumStage"]=2,["questID"]=1683,["sourceHash"]="c92d3cc4f83f7a887da43d25ca6968101b4e593d28c6e3c26530eeee97ab3ca3"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-6128",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The satyr bore the horn Elanaria requested as proof that the moonwell’s defiler had been stopped.",["title"]="Vorlus Vilehoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1688:description:1-37","1688:description:39-140","1688:description:142-194","1688:description:196-238","1688:description:243-310","1688:description:312-401","1688:description:406-438","1688:description:440-488","1688:description:490-511","1688:objective:1-63"},["minimumStage"]=2,["questID"]=1688,["sourceHash"]="57d2bfb86b832a274290927ccf0189a21445e912c9460fc230317153dfd2e0c3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-881",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Surena studied warlock magic under Gakin before leaving with Erlan Drudgemoor of the Defias.",["title"]="Surena Caledon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1688:description:1-37","1688:description:39-140","1688:description:142-194","1688:description:196-238","1688:description:243-310","1688:description:312-401","1688:description:406-438","1688:description:440-488","1688:description:490-511","1688:objective:1-63"},["minimumStage"]=2,["questID"]=1688,["sourceHash"]="57d2bfb86b832a274290927ccf0189a21445e912c9460fc230317153dfd2e0c3"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-881",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gakin placed his former pupil at the Brackwell Pumpkin Patch when he sought his bloodstone choker’s return.",["title"]="Surena Caledon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1712:description:1-37","1712:description:40-101","1712:description:104-163","1712:description:168-197","1712:description:202-216","1712:description:219-303","1712:description:306-366","1712:description:371-462","1712:description:467-508","1712:objective:1-79"},["minimumStage"]=2,["questID"]=1712,["sourceHash"]="640b2babf23093f8197dc15e903877f7007452ace1e334598260ea9b9e1bf7b3"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6239",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cyclonian was the wind lord Bath’rah sought a champion to defeat.",["title"]="Cyclonian"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1712:description:1-37","1712:description:40-101","1712:description:104-163","1712:description:168-197","1712:description:202-216","1712:description:219-303","1712:description:306-366","1712:description:371-462","1712:description:467-508","1712:objective:1-79"},["minimumStage"]=2,["questID"]=1712,["sourceHash"]="640b2babf23093f8197dc15e903877f7007452ace1e334598260ea9b9e1bf7b3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6239",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bath’rah believed Cyclonian’s whirlwind heart could infuse a weapon with its power after a successful summoning and confrontation.",["title"]="Cyclonian"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1383:description:1-36","1383:description:38-117","1383:description:122-198","1383:description:200-274","1383:description:276-344","1383:description:349-425","1383:description:427-484","1383:description:489-504","1383:objective:1-110"},["minimumStage"]=2,["questID"]=1383,["sourceHash"]="0fecf4725a0802a60f04c94818564d91c71e0370dee02e7961541a2aa0cc1d51"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1081",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Mire Lord’s enchanted fungus was one of the unusual ingredients Faustin sought for his purported truth serum.",["title"]="Mire Lord"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1476:description:1-26","1476:description:28-49","1476:description:54-156","1476:description:161-308","1476:description:313-431","1476:description:436-468","1476:description:470-508","1476:objective:1-103"},["minimumStage"]=2,["questID"]=1476,["sourceHash"]="dce5cf92695fffde9f6b4fc4f3b7b247542c0bc95dcebf53e7a83e62922ad963"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5682",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dalin devoted himself to caring for Lordaeron’s refugees who had been refused entry at the Greymane Wall.",["title"]="Dalin Forgewright"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1476:description:1-26","1476:description:28-49","1476:description:54-156","1476:description:161-308","1476:description:313-431","1476:description:436-468","1476:description:470-508","1476:objective:1-103"},["minimumStage"]=2,["questID"]=1476,["sourceHash"]="dce5cf92695fffde9f6b4fc4f3b7b247542c0bc95dcebf53e7a83e62922ad963"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5682",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Godrick selected him as an honorable victim whose heart might draw a succubus into the world.",["title"]="Dalin Forgewright"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1476:description:1-26","1476:description:28-49","1476:description:54-156","1476:description:161-308","1476:description:313-431","1476:description:436-468","1476:description:470-508","1476:objective:1-103"},["minimumStage"]=2,["questID"]=1476,["sourceHash"]="dce5cf92695fffde9f6b4fc4f3b7b247542c0bc95dcebf53e7a83e62922ad963"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5683",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Comar wandered the Wetlands looking for a sign of his wife, remaining faithful to his lost love.",["title"]="Comar Villard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1476:description:1-26","1476:description:28-49","1476:description:54-156","1476:description:161-308","1476:description:313-431","1476:description:436-468","1476:description:470-508","1476:objective:1-103"},["minimumStage"]=2,["questID"]=1476,["sourceHash"]="dce5cf92695fffde9f6b4fc4f3b7b247542c0bc95dcebf53e7a83e62922ad963"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5683",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His devotion made him a target of Godrick’s search for a loving man’s heart to use in a summoning.",["title"]="Comar Villard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1021:description:1-55","1021:description:57-123","1021:description:125-184","1021:description:189-214","1021:description:216-296","1021:description:298-324","1021:description:326-377","1021:objective:1-22"},["minimumStage"]=2,["questID"]=1021,["sourceHash"]="60d315288b851af1178c735d05cc2f75583a5e25c57c390fffe4d23d5fc872c1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3920",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anilia led Illiyana’s sisters to Xavian to recover the Branch of Cenarius from the satyrs.",["title"]="Anilia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1021:description:1-55","1021:description:57-123","1021:description:125-184","1021:description:189-214","1021:description:216-296","1021:description:298-324","1021:description:326-377","1021:objective:1-22","1021:completion:1-73"},["minimumStage"]=4,["questID"]=1021,["sourceHash"]="60d315288b851af1178c735d05cc2f75583a5e25c57c390fffe4d23d5fc872c1"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-3920",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A gaping wound in her side left Anilia close to death when the search reached her.",["title"]="Anilia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1031:description:1-60","1031:description:62-179","1031:description:181-199","1031:description:201-315","1031:objective:1-76"},["minimumStage"]=2,["questID"]=1031,["sourceHash"]="bd776a9bb44d01b7c7ddae4cc22ac3f741e37def10742f08e3f0b433266cce1a"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3920",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her final words named Geltharis as the one who had taken the branch, directing its recovery before she died.",["title"]="Anilia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1031:description:1-60","1031:description:62-179","1031:description:181-199","1031:description:201-315","1031:objective:1-76"},["minimumStage"]=2,["questID"]=1031,["sourceHash"]="bd776a9bb44d01b7c7ddae4cc22ac3f741e37def10742f08e3f0b433266cce1a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4619",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anilia’s dying account identified Geltharis as the holder of the Branch of Cenarius, beyond the northern arch.",["title"]="Geltharis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1032:description:1-38","1032:description:40-92","1032:description:94-109","1032:description:111-114","1032:description:119-166","1032:description:168-216","1032:description:218-302","1032:objective:1-48"},["minimumStage"]=2,["questID"]=1032,["sourceHash"]="0ca99b510ea30eb13b8f04df33bb7987943daa330efd01086a6b3b0f5cec9f2c"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3901",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Illiyana mourned Anilia, recalling the days they had spent playing together in the forest.",["title"]="Illiyana"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1032:description:1-38","1032:description:40-92","1032:description:94-109","1032:description:111-114","1032:description:119-166","1032:description:168-216","1032:description:218-302","1032:objective:1-48"},["minimumStage"]=2,["questID"]=1032,["sourceHash"]="0ca99b510ea30eb13b8f04df33bb7987943daa330efd01086a6b3b0f5cec9f2c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3901",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After the loss she asked for the horns of the satyrs responsible, seeking some comfort through retribution.",["title"]="Illiyana"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1035:description:1-54","1035:description:57-129","1035:description:132-179","1035:description:184-250","1035:description:252-280","1035:description:285-375","1035:description:378-428","1035:description:433-478","1035:objective:1-97"},["minimumStage"]=2,["questID"]=1035,["sourceHash"]="7eaa00de9e7c479a1d5f40838426695ea1973ce1ef2a53bc3bfc2fb241110b53"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3931",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The oracle led the Shadethickets who displaced the moonstone gatherers at Fallen Sky Lake.",["title"]="Shadethicket Oracle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1035:description:1-54","1035:description:57-129","1035:description:132-179","1035:description:184-250","1035:description:252-280","1035:description:285-375","1035:description:378-428","1035:description:433-478","1035:objective:1-97"},["minimumStage"]=2,["questID"]=1035,["sourceHash"]="7eaa00de9e7c479a1d5f40838426695ea1973ce1ef2a53bc3bfc2fb241110b53"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3931",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="It hoarded the fallen moonstones, one of which Pelturas sought to restore his weakened daughter.",["title"]="Shadethicket Oracle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1033:description:1-109","1033:description:112-147","1033:description:150-234","1033:description:239-341","1033:description:344-394","1033:description:396-470","1033:objective:1-44"},["minimumStage"]=2,["questID"]=1033,["sourceHash"]="a8aa3e76b0a64cf96dbe02f974fc86df0abe4df87fc83ccd3d851dde361e2264"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3892",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Relara was Pelturas Whitemoon’s child, whose persistent illness drove him to seek several remedies from Orendil’s advice.",["title"]="Relara Whitemoon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1034:description:1-57","1034:description:60-128","1034:description:131-137","1034:description:139-167","1034:description:172-239","1034:description:242-278","1034:description:281-330","1034:description:335-377","1034:description:380-408","1034:objective:1-54"},["minimumStage"]=2,["questID"]=1034,["sourceHash"]="c9d08473703e74c078480d5427069a1d683152dd4473e278cec11059c38d105a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3892",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Elune’s Tear eased her nightmares, yet a continuing fever led her father to seek stardust for a poultice.",["title"]="Relara Whitemoon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1033:description:1-109","1033:description:112-147","1033:description:150-234","1033:description:239-341","1033:description:344-394","1033:description:396-470","1033:objective:1-44"},["minimumStage"]=2,["questID"]=1033,["sourceHash"]="a8aa3e76b0a64cf96dbe02f974fc86df0abe4df87fc83ccd3d851dde361e2264"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3894",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pelturas sought stronger medicine for Relara after Orendil’s first cure only slowed her disease.",["title"]="Pelturas Whitemoon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1035:description:1-54","1035:description:57-129","1035:description:132-179","1035:description:184-250","1035:description:252-280","1035:description:285-375","1035:description:378-428","1035:description:433-478","1035:objective:1-97","1035:completion:1-35","1035:completion:37-110","1035:completion:115-179","1035:completion:181-198","1035:completion:200-248"},["minimumStage"]=4,["questID"]=1035,["sourceHash"]="7eaa00de9e7c479a1d5f40838426695ea1973ce1ef2a53bc3bfc2fb241110b53"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3894",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grateful for the moonstone intended to restore his daughter’s strength, he offered a possession he valued second only to Relara herself.",["title"]="Pelturas Whitemoon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1057:description:1-80","1057:description:85-145","1057:description:147-208","1057:description:210-264","1057:description:269-360","1057:description:362-460","1057:description:465-499","1057:objective:1-147"},["minimumStage"]=2,["questID"]=1057,["sourceHash"]="5a0f2b26705a03f82bc6bb3de0a8e5c4012a6754dec8f46b2beb587743ab8635"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3994",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Albagorm blamed industrialists for burning sacred hills and saw Bloodfury harpies blocking the Charred Vale’s regrowth.",["title"]="Keeper Albagorm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1059:description:1-34","1059:description:36-92","1059:description:97-159","1059:description:161-298","1059:description:303-430","1059:description:435-456","1059:description:458-478","1059:objective:1-76"},["minimumStage"]=2,["questID"]=1059,["sourceHash"]="6ae7ef206544461590f51844fc2206ad4ac6e7402f4681389e81730905b3cf5d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3994",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He urgently sought Falfindel’s ability to call great forest spirits before the harpies could regroup.",["title"]="Keeper Albagorm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1059:description:1-34","1059:description:36-92","1059:description:97-159","1059:description:161-298","1059:description:303-430","1059:description:435-456","1059:description:458-478","1059:objective:1-76"},["minimumStage"]=2,["questID"]=1059,["sourceHash"]="6ae7ef206544461590f51844fc2206ad4ac6e7402f4681389e81730905b3cf5d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4048",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Falfindel was a druid reputed capable of calling great forest spirits to help reclaim damaged land.",["title"]="Falfindel Waywarder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1059:description:1-34","1059:description:36-92","1059:description:97-159","1059:description:161-298","1059:description:303-430","1059:description:435-456","1059:description:458-478","1059:objective:1-76"},["minimumStage"]=2,["questID"]=1059,["sourceHash"]="6ae7ef206544461590f51844fc2206ad4ac6e7402f4681389e81730905b3cf5d"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-4048",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He could be found at the forest’s edge where western Thousand Needles met Feralas.",["title"]="Falfindel Waywarder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1396:description:1-77","1396:description:80-138","1396:description:143-173","1396:description:176-251","1396:description:254-300","1396:objective:1-127"},["minimumStage"]=2,["questID"]=1396,["sourceHash"]="8ac63506adec5feafe7525c1d97e7b79445d0268b38590096eea2207e91c3163"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5476",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Biggs said he alone survived an attack that wrecked his caravan before it reached the eastern coast.",["title"]="Watcher Biggs"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1421:description:1-180","1421:description:185-307","1421:description:310-351","1421:description:354-383","1421:objective:1-104"},["minimumStage"]=2,["questID"]=1421,["sourceHash"]="0100491f9d896ab15f0630b8ab130a10e746ddf692860ef03a1506a857eb77b9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5476",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought the stolen reagent chest to preserve supplies vital to Nethergarde’s wizards rather than abandon the caravan’s purpose.",["title"]="Watcher Biggs"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1391:description:1-55","1391:description:57-176","1391:description:181-245","1391:description:247-297","1391:description:299-386","1391:description:391-440","1391:description:442-486","1391:objective:1-54","1391:completion:1-15","1391:completion:17-25","1391:completion:27-75","1391:completion:77-143"},["minimumStage"]=4,["questID"]=1391,["sourceHash"]="dab9118f8103fa446fab2813c9ea7a4b01f16accf67e49e84af967099f1589cd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5416",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The prisoner in Stonard accepted Zraedus’s doctored ale after days without a drink, promising to describe what he had learned afterward.",["title"]="Infiltrator Marksen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1421:description:1-180","1421:description:185-307","1421:description:310-351","1421:description:354-383","1421:objective:1-104"},["minimumStage"]=2,["questID"]=1421,["sourceHash"]="0100491f9d896ab15f0630b8ab130a10e746ddf692860ef03a1506a857eb77b9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-76",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Biggs saw one of his stolen wagons dragged toward this Lost One settlement, carrying reagents needed by Nethergarde’s wizards.",["title"]="Fallow Sanctuary"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1440:description:1-25","1440:description:27-175","1440:description:177-278","1440:objective:1-101","1440:completion:1-14","1440:completion:16-123","1440:completion:125-191","1440:completion:193-211","1440:completion:216-342","1440:completion:344-416"},["minimumStage"]=4,["questID"]=1440,["sourceHash"]="50db17da3148b2dd9e27eced4f8e85f2cbf7767626764365c84815f780d996aa"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-599",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dalinda’s escape from the fortress ended with her safe arrival at Nijel’s Point, although her brother did not return with her.",["title"]="Thunder Axe Fortress"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1197:description:1-106","1197:description:108-184","1197:description:189-265","1197:description:267-338","1197:description:343-473","1197:objective:1-66"},["minimumStage"]=2,["questID"]=1197,["sourceHash"]="125b9cae3c52fda7b9852f556fa0f66bc5dd2c740f3315f54491deaa96bca7f4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1557",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Galak heavily guarded a relic within an enduring flame that moonwell water could quench only briefly.",["title"]="Splithoof Hold"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1033:description:1-109","1033:description:112-147","1033:description:150-234","1033:description:239-341","1033:description:344-394","1033:description:396-470","1033:objective:1-44"},["minimumStage"]=2,["questID"]=1033,["sourceHash"]="a8aa3e76b0a64cf96dbe02f974fc86df0abe4df87fc83ccd3d851dde361e2264"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="iris-lake",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The stone called Elune’s Tear was found only on the lake’s island; Orendil recommended it against corruption.",["title"]="Iris Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1021:description:1-55","1021:description:57-123","1021:description:125-184","1021:description:189-214","1021:description:216-296","1021:description:298-324","1021:description:326-377","1021:objective:1-22"},["minimumStage"]=2,["questID"]=1021,["sourceHash"]="60d315288b851af1178c735d05cc2f75583a5e25c57c390fffe4d23d5fc872c1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16006",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A ruined night elf temple became the focus of the dryads’ search for their stolen Branch of Cenarius.",["title"]="Xavian"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1057:description:1-80","1057:description:85-145","1057:description:147-208","1057:description:210-264","1057:description:269-360","1057:description:362-460","1057:description:465-499","1057:objective:1-147"},["minimumStage"]=2,["questID"]=1057,["sourceHash"]="5a0f2b26705a03f82bc6bb3de0a8e5c4012a6754dec8f46b2beb587743ab8635"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-465",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Albagorm attributed the burning to mechanized industrialists, while Bloodfury harpies prevented those seeking to begin regrowth from entering.",["title"]="The Charred Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1688:description:1-37","1688:description:39-140","1688:description:142-194","1688:description:196-238","1688:description:243-310","1688:description:312-401","1688:description:406-438","1688:description:440-488","1688:description:490-511","1688:objective:1-63"},["minimumStage"]=2,["questID"]=1688,["sourceHash"]="57d2bfb86b832a274290927ccf0189a21445e912c9460fc230317153dfd2e0c3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16156",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gakin traced his former pupil Surena and her Defias companion Erlan to the pumpkin patch while seeking a gifted bloodstone choker.",["title"]="Brackwell Pumpkin Patch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1719:description:1-66","1719:description:69-212","1719:description:217-290","1719:description:293-374","1719:description:379-431","1719:description:434-486","1719:objective:1-60"},["minimumStage"]=2,["questID"]=1719,["sourceHash"]="e7d9cea738063d05003ad56273a4d75382f9a28eaa8b53e52e7b5b34b5680732"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="fray-island",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Affray tested rising warriors here, with Twiggy sending successive challengers before calling out Big Will.",["title"]="Fray Island"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1786:description:1-109","1786:description:111-211","1786:description:216-298","1786:description:300-363","1786:description:368-412","1786:description:414-450","1786:description:455-483","1786:description:485-504","1786:objective:1-60"},["minimumStage"]=2,["questID"]=1786,["sourceHash"]="bdd71605a237202a925ec19cc3216e07238edbf6e2cf4db53411d8e9695497fd"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16516",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gazin and Henze found Defias mages studying documents on the island, but their attempt to seize evidence was overwhelmed by more attackers.",["title"]="Heroes' Vigil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1803:description:5-59","1803:description:61-123","1803:description:125-189","1803:description:191-246","1803:description:248-283","1803:description:288-391","1803:description:396-508","1803:objective:1-83"},["minimumStage"]=2,["questID"]=1803,["sourceHash"]="74197549a28159689bb8ec645ea61d3a5b0fab1cc6e53547798efc81d03a9442"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6293",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jorah traced the Tome of the Cabal to Lordaeron, where vandals removed almost half its pages.",["title"]="Jorah Annison"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1803:description:5-59","1803:description:61-123","1803:description:125-189","1803:description:191-246","1803:description:248-283","1803:description:288-391","1803:description:396-508","1803:objective:1-83"},["minimumStage"]=2,["questID"]=1803,["sourceHash"]="74197549a28159689bb8ec645ea61d3a5b0fab1cc6e53547798efc81d03a9442"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6293",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He distinguished a rumored missing half among Thousand Needles’ centaurs from the surviving text lost during shipment west of Southshore.",["title"]="Jorah Annison"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1842:description:1-74","1842:description:77-134","1842:description:139-211","1842:description:214-263","1842:description:266-366","1842:description:371-400","1842:description:403-448","1842:objective:1-72"},["minimumStage"]=2,["questID"]=1842,["sourceHash"]="f0d6a50929e072f05e001b37c30d4d75c3bfc3ac6271beb272765a10658b1137"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6408",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ula’elek crafted magically empowered gauntlets from material gathered by the warrior who would wear them.",["title"]="Ula'elek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1842:description:1-74","1842:description:77-134","1842:description:139-211","1842:description:214-263","1842:description:266-366","1842:description:371-400","1842:description:403-448","1842:objective:1-72"},["minimumStage"]=2,["questID"]=1842,["sourceHash"]="f0d6a50929e072f05e001b37c30d4d75c3bfc3ac6271beb272765a10658b1137"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6408",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He said satyrs fed on Ashenvale’s purity and that swollen, uncloven hooves held the magic they had drained from the forest.",["title"]="Ula'elek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1844:description:1-68","1844:description:73-164","1844:description:167-287","1844:description:292-326","1844:description:331-392","1844:description:395-427","1844:description:430-502","1844:objective:1-58"},["minimumStage"]=2,["questID"]=1844,["sourceHash"]="257dfbecaba47a54c18fc3e8c285cac05a5ef097a94097160a9eb01b2de9d3ef"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6410",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Orm required a chimaera matriarch’s galvanized horn before making a warrior’s helm.",["title"]="Orm Stonehoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1844:description:1-68","1844:description:73-164","1844:description:167-287","1844:description:292-326","1844:description:331-392","1844:description:395-427","1844:description:430-502","1844:objective:1-58"},["minimumStage"]=2,["questID"]=1844,["sourceHash"]="257dfbecaba47a54c18fc3e8c285cac05a5ef097a94097160a9eb01b2de9d3ef"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6410",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described the Charred Vale’s surviving creatures as maddened by pain and despair, framing the matriarch’s death as release from suffering.",["title"]="Orm Stonehoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1858:description:1-85","1858:description:87-176","1858:description:181-283","1858:description:285-306","1858:description:308-339","1858:description:341-394","1858:description:396-444","1858:objective:1-123"},["minimumStage"]=2,["questID"]=1858,["sourceHash"]="0e8375f90d1fd30e6c3032a0d60860d57a621531117902cbfc4f7ed3daa973a3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6446",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Therzok sought the contents of Tazan’s locked satchel and reasoned that the absent key had been entrusted to an assistant.",["title"]="Therzok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1858:description:1-85","1858:description:87-176","1858:description:181-283","1858:description:285-306","1858:description:308-339","1858:description:341-394","1858:description:396-444","1858:objective:1-123"},["minimumStage"]=2,["questID"]=1858,["sourceHash"]="0e8375f90d1fd30e6c3032a0d60860d57a621531117902cbfc4f7ed3daa973a3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6446",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She identified Gamon as Tazan’s drunken assistant and suggested quietly taking the key from him in the tavern.",["title"]="Therzok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1861:description:1-108","1861:description:111-204","1861:description:209-245","1861:description:248-292","1861:description:297-318","1861:description:321-443","1861:description:446-504","1861:objective:1-57"},["minimumStage"]=2,["questID"]=1861,["sourceHash"]="3b69f5f181ba327e2d0787e572fa53b79f45807c02fc878197071e13f80c4188"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5497",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jennea sought water from Mirror Lake’s waterfall to test for magical contamination.",["title"]="Jennea Cannon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1861:description:1-108","1861:description:111-204","1861:description:209-245","1861:description:248-292","1861:description:297-318","1861:description:321-443","1861:description:446-504","1861:objective:1-57"},["minimumStage"]=2,["questID"]=1861,["sourceHash"]="3b69f5f181ba327e2d0787e572fa53b79f45807c02fc878197071e13f80c4188"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5497",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She linked the investigation to great magical struggles that had torn once-stable currents from their channels, leaving the effects uncertain.",["title"]="Jennea Cannon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1880:description:1-69","1880:description:72-118","1880:description:121-159","1880:description:162-177","1880:description:179-196","1880:description:201-298","1880:description:301-314","1880:description:317-459","1880:description:464-498","1880:objective:1-38"},["minimumStage"]=2,["questID"]=1880,["sourceHash"]="a9c3c871592c80c07259d305fc6caae4efae1682f63f4b5c4001c56028d9b50f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5144",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bink left her knowledge-storing gizmonitor in a chest outside Gnomeregan when its inhabitants fled.",["title"]="Bink"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1880:description:1-69","1880:description:72-118","1880:description:121-159","1880:description:162-177","1880:description:179-196","1880:description:201-298","1880:description:301-314","1880:description:317-459","1880:description:464-498","1880:objective:1-38"},["minimumStage"]=2,["questID"]=1880,["sourceHash"]="a9c3c871592c80c07259d305fc6caae4efae1682f63f4b5c4001c56028d9b50f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5144",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Leper gnomes now occupied the huts around the lost device, and she wanted the accumulated magical knowledge recovered.",["title"]="Bink"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1882:description:1-46","1882:description:49-150","1882:description:153-301","1882:description:306-368","1882:description:371-417","1882:description:420-458","1882:description:461-484","1882:objective:1-84"},["minimumStage"]=2,["questID"]=1882,["sourceHash"]="c693143fd1f551db318c9233be53c0e6cf37b401cdaa2a6a73bb8f1550f3520d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anastasia collected Balnir’s snapdragons to measure how far the Plaguelands’ corruption had spread into Tirisfal.",["title"]="Anastasia Hartwell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1882:description:1-46","1882:description:49-150","1882:description:153-301","1882:description:306-368","1882:description:371-417","1882:description:420-458","1882:description:461-484","1882:objective:1-84"},["minimumStage"]=2,["questID"]=1882,["sourceHash"]="c693143fd1f551db318c9233be53c0e6cf37b401cdaa2a6a73bb8f1550f3520d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Despite finding a certain charm in its destructive force, she considered the plague unruly and something Forsaken mages should curtail.",["title"]="Anastasia Hartwell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1886:description:1-104","1886:description:109-167","1886:description:172-213","1886:description:215-323","1886:description:325-382","1886:description:387-460","1886:description:462-495","1886:objective:1-89"},["minimumStage"]=2,["questID"]=1886,["sourceHash"]="efdc225b5c9229a83ecb971c81c1304b8a1bfebb145ab331393b1da940443ca1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6467",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mennet tested recruits to Varimathras’s elite Deathstalkers with dangerous work whose purpose he deliberately concealed.",["title"]="Mennet Carkad"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1886:description:1-104","1886:description:109-167","1886:description:172-213","1886:description:215-323","1886:description:325-382","1886:description:387-460","1886:description:462-495","1886:objective:1-89"},["minimumStage"]=2,["questID"]=1886,["sourceHash"]="efdc225b5c9229a83ecb971c81c1304b8a1bfebb145ab331393b1da940443ca1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6467",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He required the personal effects of Astor Hadren, a messenger between Silverpine and the Undercity, leaving the method to the recruit.",["title"]="Mennet Carkad"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1938:description:1-76","1938:description:79-150","1938:description:153-175","1938:description:180-313","1938:description:318-375","1938:description:378-454","1938:objective:1-76"},["minimumStage"]=2,["questID"]=1938,["sourceHash"]="27816cf939ca3e1f34838cd6ed44e85e0986d663fd7df929dd913b43cf67308b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5694",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Andromath recalled three mages studying together until one embraced forbidden arts and was banished despite their warnings.",["title"]="High Sorcerer Andromath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1938:description:1-76","1938:description:79-150","1938:description:153-175","1938:description:180-313","1938:description:318-375","1938:description:378-454","1938:objective:1-76"},["minimumStage"]=2,["questID"]=1938,["sourceHash"]="27816cf939ca3e1f34838cd6ed44e85e0986d663fd7df929dd913b43cf67308b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5694",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The exile took Ur’s treatise to Ilgalar, and Andromath sought its return to Stormwind’s mages.",["title"]="High Sorcerer Andromath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1944:description:1-138","1944:description:141-202","1944:description:207-263","1944:description:268-300","1944:description:303-374","1944:description:377-502","1944:objective:1-52"},["minimumStage"]=2,["questID"]=1944,["sourceHash"]="bed7593958aae217caeb074902eddf2262f57bdc8486ad874d25423605ae5020"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5885",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Deino wanted water from the bottom of Xavian’s highest waterfall to investigate the ancient city’s reputed magical power.",["title"]="Deino"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1944:description:1-138","1944:description:141-202","1944:description:207-263","1944:description:268-300","1944:description:303-374","1944:description:377-502","1944:objective:1-52"},["minimumStage"]=2,["questID"]=1944,["sourceHash"]="bed7593958aae217caeb074902eddf2262f57bdc8486ad874d25423605ae5020"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5885",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Satyrs held the ruins, making a mage’s interest in their affairs dangerous.",["title"]="Deino"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1950:description:1-60","1950:description:65-118","1950:description:121-197","1950:description:200-281","1950:description:286-330","1950:description:333-401","1950:description:404-493","1950:objective:1-59"},["minimumStage"]=2,["questID"]=1950,["sourceHash"]="3c58cf4688a5137aff4a4c8e263f2d2df90a5e7636daebc428896602ef68f660"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6548",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tirth kept the sought-after tome in a magically locked strongbox but had forgotten the phrase needed to open it.",["title"]="Magus Tirth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1950:description:1-60","1950:description:65-118","1950:description:121-197","1950:description:200-281","1950:description:286-330","1950:description:333-401","1950:description:404-493","1950:objective:1-59"},["minimumStage"]=2,["questID"]=1950,["sourceHash"]="3c58cf4688a5137aff4a4c8e263f2d2df90a5e7636daebc428896602ef68f660"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6548",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His missing apprentice normally helped him remember the phrase; Tirth directed the search toward people at the race track.",["title"]="Magus Tirth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2040:description:1-66","2040:description:68-119","2040:description:124-177","2040:description:179-236","2040:description:238-438","2040:objective:1-103"},["minimumStage"]=2,["questID"]=2040,["sourceHash"]="be5f487ac4c9178365979b3c5fee99cffb0cb5342bbd2e0ff088c4b07dbba686"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6579",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shoni sought an intact goblin shredder power supply from the Deadmines to drive gnomish excavation machines.",["title"]="Shoni the Shilent"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2040:description:1-66","2040:description:68-119","2040:description:124-177","2040:description:179-236","2040:description:238-438","2040:objective:1-103"},["minimumStage"]=2,["questID"]=2040,["sourceHash"]="be5f487ac4c9178365979b3c5fee99cffb0cb5342bbd2e0ff088c4b07dbba686"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6579",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The planned machinery could pierce Gnomeregan’s rocky underground borders and open an assault route into the trogg-held city.",["title"]="Shoni the Shilent"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2098:description:1-46","2098:description:48-87","2098:description:89-158","2098:description:163-219","2098:description:224-340","2098:description:342-476","2098:objective:1-68"},["minimumStage"]=2,["questID"]=2098,["sourceHash"]="bb764de9b818b6d80e30501da2f5d55c8a4e70d336efe380e72aa3e4d8a28f96"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6667",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Threshadons sank Gelkak’s ship off Darkshore, and the key needed to operate his first mate broke when he washed ashore.",["title"]="Gelkak Gyromast"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2098:description:1-46","2098:description:48-87","2098:description:89-158","2098:description:163-219","2098:description:224-340","2098:description:342-476","2098:objective:1-68"},["minimumStage"]=2,["questID"]=2098,["sourceHash"]="bb764de9b818b6d80e30501da2f5d55c8a4e70d336efe380e72aa3e4d8a28f96"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6667",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the scattered key pieces recovered from creatures he had seen rummaging through the wreck.",["title"]="Gelkak Gyromast"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2160:description:1-4","2160:description:6-39","2160:description:41-144","2160:description:149-196","2160:description:198-278","2160:description:283-351","2160:description:353-448","2160:objective:1-68"},["minimumStage"]=2,["questID"]=2160,["sourceHash"]="d53ed52c5c7589f98e81d885bd0274e5ee546bda58d7df2e463d5e6839d56fd5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6782",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hands needed a package delivered to Tannok at Kharanos’s inn but could not cross the dangerous pass without a Mountaineer escort.",["title"]="Hands Springsprocket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2160:description:1-4","2160:description:6-39","2160:description:41-144","2160:description:149-196","2160:description:198-278","2160:description:283-351","2160:description:353-448","2160:objective:1-68"},["minimumStage"]=2,["questID"]=2160,["sourceHash"]="d53ed52c5c7589f98e81d885bd0274e5ee546bda58d7df2e463d5e6839d56fd5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6782",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With the next escort days away, he asked a passing adventurer to take the supplies instead.",["title"]="Hands Springsprocket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2161:description:1-10","2161:description:13-28","2161:description:33-59","2161:description:62-127","2161:description:130-228","2161:description:231-259","2161:description:262-351","2161:description:356-378","2161:description:381-415","2161:description:418-434","2161:description:439-487","2161:description:490-499","2161:objective:1-53"},["minimumStage"]=2,["questID"]=2161,["sourceHash"]="0675b9c67a9882ec17d8aac5265afbcfffea70d453a4f3ff367bc4b807fee176"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6786",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ukor braved Durotar’s beasts to carry food to the Valley of Trials, only to discover it was not needed there.",["title"]="Ukor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2161:description:1-10","2161:description:13-28","2161:description:33-59","2161:description:62-127","2161:description:130-228","2161:description:231-259","2161:description:262-351","2161:description:356-378","2161:description:381-415","2161:description:418-434","2161:description:439-487","2161:description:490-499","2161:objective:1-53"},["minimumStage"]=2,["questID"]=2161,["sourceHash"]="0675b9c67a9882ec17d8aac5265afbcfffea70d453a4f3ff367bc4b807fee176"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6786",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fearful of another journey past scorpids and spiders, he sought help returning the load to Innkeeper Grosk in Razor Hill.",["title"]="Ukor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2178:description:1-34","2178:description:36-81","2178:description:83-92","2178:description:97-151","2178:description:156-240","2178:description:245-442","2178:objective:1-64"},["minimumStage"]=2,["questID"]=2178,["sourceHash"]="1fe10e5f6eeeff3e431ba642b42637f74291f51a7871e6740cb90b280e8240e1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3702",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alanndarian prepared a secret strider stew recipe and offered to teach it to someone who could obtain the meat.",["title"]="Alanndarian Nightsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2199:description:1-49","2199:description:52-80","2199:description:82-148","2199:description:151-210","2199:description:213-297","2199:description:302-412","2199:description:417-498","2199:objective:1-58"},["minimumStage"]=2,["questID"]=2199,["sourceHash"]="f4aba0c4e4fa3ab3509f8cbf5b9c10b170e28655b5cdf3eea0f2842e3ef197e9"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6826",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Talvash remembered former renown as an Ironforge jeweler and blamed a competitor’s deceit for the ruined reputation that left him penniless.",["title"]="Talvash del Kissel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2199:description:1-49","2199:description:52-80","2199:description:82-148","2199:description:151-210","2199:description:213-297","2199:description:302-412","2199:description:417-498","2199:objective:1-58"},["minimumStage"]=2,["questID"]=2199,["sourceHash"]="f4aba0c4e4fa3ab3509f8cbf5b9c10b170e28655b5cdf3eea0f2842e3ef197e9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6826",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A rare new order required silver bars; he offered knowledge of the necklace in exchange for help filling it.",["title"]="Talvash del Kissel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2201:description:1-124","2201:description:127-278","2201:description:283-351","2201:description:354-480","2201:objective:1-73","2201:objective:76-179","2201:objective:184-212","2201:objective:215-275","2201:objective:278-369","2201:objective:374-434"},["minimumStage"]=2,["questID"]=2201,["sourceHash"]="960974c3148691be838e8177bed9d6beecf629030b2fc8e3ae246f3ea7a43762"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6912",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The dead paladin’s journal supplied clues to the necklace gems amid the Shadowforge dwarves and troggs contesting Uldaman.",["title"]="Remains of a Paladin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2202:description:1-73","2202:description:76-199","2202:description:202-278","2202:description:283-338","2202:description:341-402","2202:description:407-495","2202:objective:1-59"},["minimumStage"]=2,["questID"]=2202,["sourceHash"]="dd62b6eed8bf72fcd514afd22f223c197f5886ee0f282c5ac9a2a4ec77a80bfb"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6868",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jarkal wanted to study Uldaman’s newly discovered magenta fungus caps for possible alchemical uses.",["title"]="Jarkal Mossmeld"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2202:description:1-73","2202:description:76-199","2202:description:202-278","2202:description:283-338","2202:description:341-402","2202:description:407-495","2202:objective:1-59"},["minimumStage"]=2,["questID"]=2202,["sourceHash"]="dd62b6eed8bf72fcd514afd22f223c197f5886ee0f282c5ac9a2a4ec77a80bfb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6868",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned that disturbing a cluster could release poisonous spores and offered restorative elixirs for the collected caps.",["title"]="Jarkal Mossmeld"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2218:description:1-43","2218:description:45-96","2218:description:98-158","2218:description:163-199","2218:description:201-239","2218:description:244-339","2218:description:341-412","2218:description:414-452","2218:objective:1-43"},["minimumStage"]=2,["questID"]=2218,["sourceHash"]="6408ecfec7190aaf19059bf3c91d5313dfb5155171ce061ae1c8caa5a924a860"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1234",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hogral directed people seeking purpose toward Ironforge’s thieves’ guild in the Forlorn Cavern.",["title"]="Hogral Bakkan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2218:description:1-43","2218:description:45-96","2218:description:98-158","2218:description:163-199","2218:description:201-239","2218:description:244-339","2218:description:341-412","2218:description:414-452","2218:objective:1-43"},["minimumStage"]=2,["questID"]=2218,["sourceHash"]="6408ecfec7190aaf19059bf3c91d5313dfb5155171ce061ae1c8caa5a924a860"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1234",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recommended Hulfdan Blackbeard as the contact who could set a willing newcomer to work.",["title"]="Hogral Bakkan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2238:description:1-61","2238:description:63-121","2238:description:126-158","2238:description:160-178","2238:description:180-197","2238:description:202-340","2238:description:345-428","2238:description:430-484","2238:description:486-496","2238:objective:1-34"},["minimumStage"]=2,["questID"]=2238,["sourceHash"]="7f85ccb4ebf99e8ac62050b3cc04baba8c449b128c47f10c209a814157f70b8a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5165",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hulfdan’s Hidden Circle coveted the riches carried from the king’s quarry and wanted a share taken without the king knowing.",["title"]="Hulfdan Blackbeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2238:description:1-61","2238:description:63-121","2238:description:126-158","2238:description:160-178","2238:description:180-197","2238:description:202-340","2238:description:345-428","2238:description:430-484","2238:description:486-496","2238:objective:1-34"},["minimumStage"]=2,["questID"]=2238,["sourceHash"]="7f85ccb4ebf99e8ac62050b3cc04baba8c449b128c47f10c209a814157f70b8a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5165",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He relied on Onin MacHammar, hidden among the leper gnomes near Gnomeregan, for a report before planning the theft.",["title"]="Hulfdan Blackbeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2239:description:1-11","2239:description:13-92","2239:description:97-371","2239:description:376-402","2239:description:404-456","2239:objective:1-48"},["minimumStage"]=2,["questID"]=2239,["sourceHash"]="b342ce6f5e5e6a85cc0492d62a15c7bf989d02ccf1cc6403f123ad070489859d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6886",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Onin watched the armored steam tank carrying ore and gems between Ironforge, Gol’Bolar Quarry and Kharanos.",["title"]="Onin MacHammar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2239:description:1-11","2239:description:13-92","2239:description:97-371","2239:description:376-402","2239:description:404-456","2239:objective:1-48"},["minimumStage"]=2,["questID"]=2239,["sourceHash"]="b342ce6f5e5e6a85cc0492d62a15c7bf989d02ccf1cc6403f123ad070489859d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6886",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His eastern contacts helped trace the tank’s circuit, including its puzzling long detour past Gnomeregan before returning to Ironforge.",["title"]="Onin MacHammar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2342:description:1-65","2342:description:68-173","2342:description:178-323","2342:description:326-418","2342:description:423-470","2342:description:473-502","2342:objective:1-136"},["minimumStage"]=2,["questID"]=2342,["sourceHash"]="fd67dcd5c83240ae981799537b8c54ad1e69d91d2d804fabdbc7c0b90f76ce6b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5651",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Patrick’s family had worked as diggers in Uldaman and left their treasured weapon locked in the South Common Hall.",["title"]="Patrick Garrett"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2342:description:1-65","2342:description:68-173","2342:description:178-323","2342:description:326-418","2342:description:423-470","2342:description:473-502","2342:objective:1-136"},["minimumStage"]=2,["questID"]=2342,["sourceHash"]="fd67dcd5c83240ae981799537b8c54ad1e69d91d2d804fabdbc7c0b90f76ce6b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5651",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Resenting his paid work sweeping bat pens, he offered his savings to recover the family weapon and restore what he considered his birthright.",["title"]="Patrick Garrett"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2359:description:1-47","2359:description:49-138","2359:description:143-156","2359:description:158-187","2359:description:189-233","2359:description:238-327","2359:description:329-378","2359:description:383-452","2359:description:454-488","2359:objective:1-103","2359:objective:105-173","2359:objective:175-229"},["minimumStage"]=2,["questID"]=2359,["sourceHash"]="f4046b3c77d0020577c8cd3f0a9221849c038e09259ed0100feb7fdd3ddfd3d0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7024",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kearnen spent weeks watching Klaven’s tower and tracking the arrival of a major shipment from Duskwood.",["title"]="Agent Kearnen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2359:description:1-47","2359:description:49-138","2359:description:143-156","2359:description:158-187","2359:description:189-233","2359:description:238-327","2359:description:329-378","2359:description:383-452","2359:description:454-488","2359:objective:1-103","2359:objective:105-173","2359:objective:175-229"},["minimumStage"]=2,["questID"]=2359,["sourceHash"]="f4046b3c77d0020577c8cd3f0a9221849c038e09259ed0100feb7fdd3ddfd3d0"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7024",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She could identify the new guards as inhuman but did not know precisely what they were; she suspected they protected the shipment’s chest.",["title"]="Agent Kearnen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2398:description:1-46","2398:description:49-101","2398:description:103-134","2398:description:137-218","2398:description:223-323","2398:description:328-426","2398:description:429-485","2398:objective:1-23"},["minimumStage"]=2,["questID"]=2398,["sourceHash"]="845d82bc3f98aec212eb410f6e37f1113ee9c6a096c515479b4cd5ed00de67ee"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1356",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stormpike’s friend Baelog led dwarves deep into Uldaman shortly before the troggs overran the excavation.",["title"]="Prospector Stormpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2398:description:1-46","2398:description:49-101","2398:description:103-134","2398:description:137-218","2398:description:223-323","2398:description:328-426","2398:description:429-485","2398:objective:1-23"},["minimumStage"]=2,["questID"]=2398,["sourceHash"]="845d82bc3f98aec212eb410f6e37f1113ee9c6a096c515479b4cd5ed00de67ee"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1356",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The sudden assault left him fearing that his companions were trapped alive behind enemy lines, and he sought a search rather than assume their deaths.",["title"]="Prospector Stormpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2439:description:1-34","2439:description:37-183","2439:description:186-250","2439:description:255-330","2439:description:333-399","2439:description:404-496","2439:objective:1-73"},["minimumStage"]=2,["questID"]=2439,["sourceHash"]="e39f33bbf2ae2d64fadad5e4879d26b6dcbddbb589c5280026fc95375c39346b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5387",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magellas regarded the Platinum Discs as a remarkable possible link between dwarven origins and the ancient Creators, conditional on the records proving true.",["title"]="High Explorer Magellas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2439:description:1-34","2439:description:37-183","2439:description:186-250","2439:description:255-330","2439:description:333-399","2439:description:404-496","2439:objective:1-73"},["minimumStage"]=2,["questID"]=2439,["sourceHash"]="e39f33bbf2ae2d64fadad5e4879d26b6dcbddbb589c5280026fc95375c39346b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5387",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the League to devote substantial research to the find and arranged a reward through Dinita at the vault.",["title"]="High Explorer Magellas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2458:description:1-22","2458:description:24-54","2458:description:59-131","2458:description:133-190","2458:description:195-240","2458:description:242-281","2458:description:283-327","2458:description:329-387","2458:description:392-504","2458:objective:1-25","2458:objective:27-127","2458:objective:132-222","2458:objective:224-311","2458:objective:316-439"},["minimumStage"]=2,["questID"]=2458,["sourceHash"]="7e9501224671c082c85e0f19b1d172332be349b3a5e4650d79036741def10c56"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3401",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shenthul’s organization spent a year establishing an agent deep inside the Venture Company.",["title"]="Shenthul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2458:description:1-22","2458:description:24-54","2458:description:59-131","2458:description:133-190","2458:description:195-240","2458:description:242-281","2458:description:283-327","2458:description:329-387","2458:description:392-504","2458:objective:1-25","2458:objective:27-127","2458:objective:132-222","2458:objective:224-311","2458:objective:316-439"},["minimumStage"]=2,["questID"]=2458,["sourceHash"]="7e9501224671c082c85e0f19b1d172332be349b3a5e4650d79036741def10c56"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3401",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Reports of a large new operation prompted him to send a contact to Fizzule, identified through a flare and the Shattered Hand’s salute.",["title"]="Shenthul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2458:description:1-22","2458:description:24-54","2458:description:59-131","2458:description:133-190","2458:description:195-240","2458:description:242-281","2458:description:283-327","2458:description:329-387","2458:description:392-504","2458:objective:1-25","2458:objective:27-127","2458:objective:132-222","2458:objective:224-311","2458:objective:316-439"},["minimumStage"]=2,["questID"]=2458,["sourceHash"]="7e9501224671c082c85e0f19b1d172332be349b3a5e4650d79036741def10c56"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7233",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fizzule served as Shenthul’s undercover agent inside the Venture Company near the Sludge Fen.",["title"]="Taskmaster Fizzule"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2478:description:1-62","2478:description:64-143","2478:description:148-206","2478:description:208-276","2478:description:278-308","2478:description:313-436","2478:description:438-509","2478:objective:1-81","2478:objective:83-105","2478:objective:107-137","2478:objective:139-147","2478:objective:152-294","2478:objective:296-384"},["minimumStage"]=2,["questID"]=2478,["sourceHash"]="94536c93e5ec7c09ae1758abfd22c5f982cb0d614be54df13758a5961dafe458"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7233",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His operation targeted a cache of Zanzil’s mixture in Gallywix’s lockbox, with Foreman Silixiz holding the tower key.",["title"]="Taskmaster Fizzule"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2606:description:1-6","2606:description:8-34","2606:description:36-59","2606:description:64-81","2606:description:83-146","2606:description:148-163","2606:description:168-189","2606:description:191-200","2606:description:202-264","2606:description:266-348","2606:description:353-435","2606:description:437-466","2606:objective:1-65"},["minimumStage"]=2,["questID"]=2606,["sourceHash"]="5c3785f318e4a85f3cf13df96a88208b707ae997e05c4d9fbcfb235a57499f94"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7564",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marin turned to his friend Sprinkle, a skilled chef, to make an unpleasant experimental drink palatable.",["title"]="Marin Noggenfogger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2606:description:1-6","2606:description:8-34","2606:description:36-59","2606:description:64-81","2606:description:83-146","2606:description:148-163","2606:description:168-189","2606:description:191-200","2606:description:202-264","2606:description:266-348","2606:description:353-435","2606:description:437-466","2606:objective:1-65"},["minimumStage"]=2,["questID"]=2606,["sourceHash"]="5c3785f318e4a85f3cf13df96a88208b707ae997e05c4d9fbcfb235a57499f94"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7564",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He was initially ready to abandon the foul-tasting dew, then decided it needed both improved flavor and a stronger kick.",["title"]="Marin Noggenfogger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2609:description:1-19","2609:description:21-42","2609:description:47-84","2609:description:89-252","2609:description:254-351","2609:description:356-423","2609:description:425-435","2609:description:437-493","2609:objective:1-135","2609:objective:137-189"},["minimumStage"]=2,["questID"]=2609,["sourceHash"]="9f7743d01935aca239d1fc556bed210123b4c82c0f74539c716677976270710c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7207",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Doc prescribed an unusual cure combining wildflowers, a vial, a bronze tube and chartreuse thread for the condition he called the itis.",["title"]="Doc Mixilpixil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2609:description:1-19","2609:description:21-42","2609:description:47-84","2609:description:89-252","2609:description:254-351","2609:description:356-423","2609:description:425-435","2609:description:437-493","2609:objective:1-135","2609:objective:137-189"},["minimumStage"]=2,["questID"]=2609,["sourceHash"]="9f7743d01935aca239d1fc556bed210123b4c82c0f74539c716677976270710c"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7207",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ol’ Emma left the needed thread for him at the Finest Thread, and he relayed Dr. Montgomery’s blunt advice about washing.",["title"]="Doc Mixilpixil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2641:description:1-55","2641:description:57-72","2641:description:74-180","2641:description:182-207","2641:description:209-212","2641:description:214-229","2641:description:234-253","2641:description:255-295","2641:description:297-433","2641:description:438-502","2641:objective:1-80"},["minimumStage"]=2,["questID"]=2641,["sourceHash"]="45144a80f90029fb2590096a0b095fe15ca43875ba6ffd01bcfc94c7580a4e06"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-7583",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="As a child Sprinkle learned to rescue her sister’s unpalatable cooking with a mushroom she came to call her secret ingredient.",["title"]="Sprinkle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2641:description:1-55","2641:description:57-72","2641:description:74-180","2641:description:182-207","2641:description:209-212","2641:description:214-229","2641:description:234-253","2641:description:255-295","2641:description:297-433","2641:description:438-502","2641:objective:1-80"},["minimumStage"]=2,["questID"]=2641,["sourceHash"]="45144a80f90029fb2590096a0b095fe15ca43875ba6ffd01bcfc94c7580a4e06"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7583",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Violet Tragan grew underwater in a Hinterlands lake and was her proposed remedy for Marin’s bitter brew.",["title"]="Sprinkle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2743:description:1-52","2743:description:57-132","2743:description:134-196","2743:description:201-215","2743:description:220-326","2743:description:328-396","2743:description:401-466","2743:description:468-507","2743:objective:1-58"},["minimumStage"]=2,["questID"]=2743,["sourceHash"]="d1fa4075cc5575b6a0c865519f8a966c86f3d32cb3c668bff81480e5ffb79abc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7729",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kirith’s freed spirit explained that Razelikh’s three underlings each wore part of the amulet needed to summon their demon lord.",["title"]="Spirit of Kirith"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2743:description:1-52","2743:description:57-132","2743:description:134-196","2743:description:201-215","2743:description:220-326","2743:description:328-396","2743:description:401-466","2743:description:468-507","2743:objective:1-58"},["minimumStage"]=2,["questID"]=2743,["sourceHash"]="d1fa4075cc5575b6a0c865519f8a966c86f3d32cb3c668bff81480e5ffb79abc"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7729",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With little time remaining, he sent that knowledge back to Trebor so the effort could proceed against Razelikh’s protection.",["title"]="Spirit of Kirith"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2751:description:1-54","2751:description:56-103","2751:description:105-209","2751:description:214-266","2751:description:268-314","2751:description:319-353","2751:description:355-459","2751:description:461-503","2751:objective:1-108"},["minimumStage"]=2,["questID"]=2751,["sourceHash"]="1199014f20567b1e87855ef5939f03acc74682b79c0112afe439f68bacd5e2f8"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-7790",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Orokk inherited a smithing hammer carried through twenty generations of Omosh.",["title"]="Orokk Omosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2751:description:1-54","2751:description:56-103","2751:description:105-209","2751:description:214-266","2751:description:268-314","2751:description:319-353","2751:description:355-459","2751:description:461-503","2751:objective:1-108"},["minimumStage"]=2,["questID"]=2751,["sourceHash"]="1199014f20567b1e87855ef5939f03acc74682b79c0112afe439f68bacd5e2f8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7790",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Without kin or the possibility of children, he sought a capable outsider to preserve the family’s secret recipes rather than let the craft end with him.",["title"]="Orokk Omosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2756:description:1-126","2756:description:128-156","2756:description:158-202","2756:description:204-252","2756:description:257-309","2756:description:314-330","2756:description:332-373","2756:description:375-461","2756:objective:1-89"},["minimumStage"]=2,["questID"]=2756,["sourceHash"]="2ae5c816841492e34071b3317b49373e356a0c148811813793b3b285f506dcaf"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-7792",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aturk recalled using powdered enemy bones as smithing filament in older days of fighting.",["title"]="Aturk the Anvil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2756:description:1-126","2756:description:128-156","2756:description:158-202","2756:description:204-252","2756:description:257-309","2756:description:314-330","2756:description:332-373","2756:description:375-461","2756:objective:1-89"},["minimumStage"]=2,["questID"]=2756,["sourceHash"]="2ae5c816841492e34071b3317b49373e356a0c148811813793b3b285f506dcaf"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7792",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thrall’s call for peace restrained the old clan hostilities he remembered, although he still offered to teach martial craft through armor-making.",["title"]="Aturk the Anvil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2758:description:1-125","2758:description:127-310","2758:description:315-368","2758:description:370-451","2758:objective:1-63"},["minimumStage"]=2,["questID"]=2758,["sourceHash"]="4d34830cd1977b7d07172eca891f2d25bb3bbe2666a11047d6f8189c1022ebaa"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7798",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Galvan trained Hank as an armorsmith before leaving for Booty Bay.",["title"]="Hank the Hammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2758:description:1-125","2758:description:127-310","2758:description:315-368","2758:description:370-451","2758:objective:1-63"},["minimumStage"]=2,["questID"]=2758,["sourceHash"]="4d34830cd1977b7d07172eca891f2d25bb3bbe2666a11047d6f8189c1022ebaa"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7798",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hank kept a promise to his mentor by teaching determined smiths willing to advance their craft.",["title"]="Hank the Hammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2762:description:1-69","2762:description:71-182","2762:description:184-215","2762:description:217-220","2762:description:222-301","2762:description:306-364","2762:description:366-487","2762:objective:1-89"},["minimumStage"]=2,["questID"]=2762,["sourceHash"]="5ab707c4ab743858fe5e2ef8edb94670990d9b35521c74b60fb7cc8b6f2243d1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7802",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Galvan acknowledged truesilver’s strength but mischievously rejected its name, calling mithril the nobler metal.",["title"]="Galvan the Ancient"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2762:description:1-69","2762:description:71-182","2762:description:184-215","2762:description:217-220","2762:description:222-301","2762:description:306-364","2762:description:366-487","2762:objective:1-89"},["minimumStage"]=2,["questID"]=2762,["sourceHash"]="5ab707c4ab743858fe5e2ef8edb94670990d9b35521c74b60fb7cc8b6f2243d1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7802",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His lessons paired that teasing philosophy with the secret of ornate mithril gloves.",["title"]="Galvan the Ancient"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2772:description:1-149","2772:description:151-158","2772:description:160-299","2772:description:304-411","2772:description:413-435","2772:description:437-496","2772:objective:1-82"},["minimumStage"]=2,["questID"]=2772,["sourceHash"]="1f4f840f20694fcc5f8e141b53a475bf0761a6bf76e2834f9e4c0e1e62b44a24"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-7804",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Trenton credited ornate mithril boots with letting him recover from a Venture Company contestant’s dirty trick and win a blacksmithing championship.",["title"]="Trenton Lighthammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2772:description:1-149","2772:description:151-158","2772:description:160-299","2772:description:304-411","2772:description:413-435","2772:description:437-496","2772:objective:1-82"},["minimumStage"]=2,["questID"]=2772,["sourceHash"]="1f4f840f20694fcc5f8e141b53a475bf0761a6bf76e2834f9e4c0e1e62b44a24"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7804",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A shredder’s entry into the next competition made him seek the method for ornate mithril trousers in exchange for teaching his boots.",["title"]="Trenton Lighthammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2783:description:1-29","2783:description:34-152","2783:description:157-282","2783:description:284-296","2783:description:301-372","2783:description:374-417","2783:objective:1-89"},["minimumStage"]=2,["questID"]=2783,["sourceHash"]="ce2109f9499b28b44a40f55dbd090ced037efa6231b313346737ff95e73cef2b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7826",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ardalan urged an end to fighting the Horde over scorched ground while the Burning Legion’s true strength grew unchecked.",["title"]="Ambassador Ardalan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2783:description:1-29","2783:description:34-152","2783:description:157-282","2783:description:284-296","2783:description:301-372","2783:description:374-417","2783:objective:1-89"},["minimumStage"]=2,["questID"]=2783,["sourceHash"]="ce2109f9499b28b44a40f55dbd090ced037efa6231b313346737ff95e73cef2b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7826",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed listeners to the fallen Horde hero, believing an enemy’s testimony could reveal the Blasted Lands’ greater danger.",["title"]="Ambassador Ardalan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2822:description:1-90","2822:description:93-201","2822:description:206-288","2822:description:291-363","2822:description:366-434","2822:description:437-481","2822:objective:1-66"},["minimumStage"]=2,["questID"]=2822,["sourceHash"]="ac85eccc2b7726bd5026a458d266fbaa8d78d0fa8d34efd3028549f4b4d7774b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7854",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jangdor prized uncompromising quality in leatherwork and sought thick yeti hides from Feralas as superior material.",["title"]="Jangdor Swiftstrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2822:description:1-90","2822:description:93-201","2822:description:206-288","2822:description:291-363","2822:description:366-434","2822:description:437-481","2822:objective:1-66"},["minimumStage"]=2,["questID"]=2822,["sourceHash"]="ac85eccc2b7726bd5026a458d266fbaa8d78d0fa8d34efd3028549f4b4d7774b"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-7854",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed hide-gatherers west toward the yetis of Feral Scar Vale.",["title"]="Jangdor Swiftstrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2841:description:1-73","2841:description:75-103","2841:description:105-188","2841:description:190-215","2841:description:220-297","2841:description:299-388","2841:description:393-447","2841:description:449-506","2841:objective:1-115"},["minimumStage"]=2,["questID"]=2841,["sourceHash"]="1778273e2204934290a8300f90ace0293bed78fbfe6f8a7a4f2363d33467be67"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3412",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nogg wanted blueprints for a gnomish rig he considered better than the goblins’ shredder designs.",["title"]="Nogg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2841:description:1-73","2841:description:75-103","2841:description:105-188","2841:description:190-215","2841:description:220-297","2841:description:299-388","2841:description:393-447","2841:description:449-506","2841:objective:1-115"},["minimumStage"]=2,["questID"]=2841,["sourceHash"]="1778273e2204934290a8300f90ace0293bed78fbfe6f8a7a4f2363d33467be67"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3412",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The plans were locked in a safe near Thermaplugg, whose combination Nogg believed known only to the mekgineer.",["title"]="Nogg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2842:description:1-165","2842:description:170-216","2842:description:218-308","2842:description:310-357","2842:description:362-475","2842:objective:1-31"},["minimumStage"]=2,["questID"]=2842,["sourceHash"]="8a6ea55338a8350f710cb300e984b893920c2d47435ac0b33fbeddb31905ab05"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3413",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="News from Kernobee about a powerful new gnomish rig prompted Sovik and Scooty to build the Transpolyporter 6000.",["title"]="Sovik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2842:description:1-165","2842:description:170-216","2842:description:218-308","2842:description:310-357","2842:description:362-475","2842:objective:1-31"},["minimumStage"]=2,["questID"]=2842,["sourceHash"]="8a6ea55338a8350f710cb300e984b893920c2d47435ac0b33fbeddb31905ab05"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3413",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He promoted the device as an alternative to reaching Gnomeregan through Dun Morogh, sending passengers to Scooty in Booty Bay.",["title"]="Sovik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2843:description:1-133","2843:description:138-223","2843:description:225-232","2843:description:237-291","2843:description:293-375","2843:description:380-436","2843:objective:1-52"},["minimumStage"]=2,["questID"]=2843,["sourceHash"]="791b775f91e630487a502264a4a9a51278d4d3a1decaa2e1ecb41ad8c4c334f1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7853",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scooty calibrated transponders to passengers’ size and weight for the journey to Gnomeregan.",["title"]="Scooty"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2843:description:1-133","2843:description:138-223","2843:description:225-232","2843:description:237-291","2843:description:293-375","2843:description:380-436","2843:objective:1-52"},["minimumStage"]=2,["questID"]=2843,["sourceHash"]="791b775f91e630487a502264a4a9a51278d4d3a1decaa2e1ecb41ad8c4c334f1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7853",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He explained the return pad and admitted possible unusual side effects, while reassuring passengers that these should no longer be permanent.",["title"]="Scooty"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2865:description:1-45","2865:description:48-108","2865:description:111-125","2865:description:130-167","2865:description:169-215","2865:description:220-334","2865:description:337-344","2865:description:349-392","2865:description:395-446","2865:description:451-462","2865:description:465-509","2865:objective:1-57"},["minimumStage"]=2,["questID"]=2865,["sourceHash"]="48b3ad9e8e15201cca0dfda54281b7ec21b70b12f53df8c72678f0ed0edc20cb"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7876",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tran’rek wanted intact scarab shells, whose hardness made them useful building material.",["title"]="Tran'rek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2865:description:1-45","2865:description:48-108","2865:description:111-125","2865:description:130-167","2865:description:169-215","2865:description:220-334","2865:description:337-344","2865:description:349-392","2865:description:395-446","2865:description:451-462","2865:description:465-509","2865:objective:1-57"},["minimumStage"]=2,["questID"]=2865,["sourceHash"]="48b3ad9e8e15201cca0dfda54281b7ec21b70b12f53df8c72678f0ed0edc20cb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7876",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He knew overhunting had nearly eliminated Tanaris’s scarabs and disclosed the surviving colony in Zul’Farrak only after securing a promise of shells.",["title"]="Tran'rek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2866:description:1-88","2866:description:91-178","2866:description:183-262","2866:description:265-322","2866:description:325-412","2866:description:417-490","2866:description:492-505","2866:objective:1-77"},["minimumStage"]=2,["questID"]=2866,["sourceHash"]="3c2aedc9fa2784f2ba96983aec1539f11c521980b0bc9e968c32573b72c411c5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3936",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shandris’s earlier survey found little in ancient Solarsal, but the Hatecrest naga’s sudden occupation suggested a new threat or hidden purpose.",["title"]="Shandris Feathermoon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2866:description:1-88","2866:description:91-178","2866:description:183-262","2866:description:265-322","2866:description:325-412","2866:description:417-490","2866:description:492-505","2866:objective:1-77"},["minimumStage"]=2,["questID"]=2866,["sourceHash"]="3c2aedc9fa2784f2ba96983aec1539f11c521980b0bc9e968c32573b72c411c5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3936",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She requested a fresh investigation rather than assume the naga were merely preparing an attack.",["title"]="Shandris Feathermoon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2879:description:1-41","2879:description:43-185","2879:description:190-276","2879:description:278-388","2879:description:390-508","2879:objective:1-53"},["minimumStage"]=2,["questID"]=2879,["sourceHash"]="b4475e5fbbb1c9a4f6bf2acb293c64c1ea078b367ff7fc7f53f946fa7aa0e530"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7764",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Troyas recognized a possible key to the Equinex Monolith and explained how the four surviving flames might energize it.",["title"]="Troyas Moonbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2879:description:1-41","2879:description:43-185","2879:description:190-276","2879:description:278-388","2879:description:390-508","2879:objective:1-53"},["minimumStage"]=2,["questID"]=2879,["sourceHash"]="b4475e5fbbb1c9a4f6bf2acb293c64c1ea078b367ff7fc7f53f946fa7aa0e530"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7764",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the stave tested beside the monolith in Ravenwind, where it might unlock a sacred artifact if his identification proved correct.",["title"]="Troyas Moonbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2904:description:1-24","2904:description:26-39","2904:description:44-205","2904:description:210-232","2904:description:237-443","2904:description:448-463","2904:objective:1-81"},["minimumStage"]=2,["questID"]=2904,["sourceHash"]="8d174dca78348f80cb6c2e060a31921bca1d6feb8fee9b692fdcafc2818cc9f8"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-7850",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dark Iron dwarves captured Kernobee, beat him severely and left him among Gnomeregan’s troggs.",["title"]="Kernobee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2904:description:1-24","2904:description:26-39","2904:description:44-205","2904:description:210-232","2904:description:237-443","2904:description:448-463","2904:objective:1-81"},["minimumStage"]=2,["questID"]=2904,["sourceHash"]="8d174dca78348f80cb6c2e060a31921bca1d6feb8fee9b692fdcafc2818cc9f8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7850",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted to escape and warn Tinkerwiz in Ratchet about Dark Iron involvement in the new rig, with Scooty informed of his destination.",["title"]="Kernobee"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2922:description:1-96","2922:description:99-234","2922:description:237-258","2922:description:260-296","2922:description:299-330","2922:description:335-365","2922:description:368-507","2922:objective:1-65"},["minimumStage"]=2,["questID"]=2922,["sourceHash"]="c8a89eb94af4db8739b07b2ed842092a7287cc2e83873399d2a8d54e5bd40a05"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Overspark created Techbot to aid him and his associates with its devices and store of information.",["title"]="Tinkmaster Overspark"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2922:description:1-96","2922:description:99-234","2922:description:237-258","2922:description:260-296","2922:description:299-330","2922:description:335-365","2922:description:368-507","2922:objective:1-65"},["minimumStage"]=2,["questID"]=2922,["sourceHash"]="c8a89eb94af4db8739b07b2ed842092a7287cc2e83873399d2a8d54e5bd40a05"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He hoped the frenzied machine’s memory core would explain its reversed behavior and let him repair it rather than lose his creation entirely.",["title"]="Tinkmaster Overspark"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2926:description:1-164","2926:description:169-275","2926:description:277-304","2926:description:306-436","2926:description:438-494","2926:objective:1-116","2926:objective:118-179"},["minimumStage"]=2,["questID"]=2926,["sourceHash"]="0abd98d52add0a7cec943974f9830aa4653f75c22c53cb97f8ffd54319b181f0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1268",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ozzie and Razzle investigated a possible cure for Gnomeregan’s sickness using fallout gathered from irradiated troggs.",["title"]="Ozzie Togglevolt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2926:description:1-164","2926:description:169-275","2926:description:277-304","2926:description:306-436","2926:description:438-494","2926:objective:1-116","2926:objective:118-179"},["minimumStage"]=2,["questID"]=2926,["sourceHash"]="0abd98d52add0a7cec943974f9830aa4653f75c22c53cb97f8ffd54319b181f0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1268",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Their theory remained untested; Ozzie joked that the result might instead be a remarkably powerful rum.",["title"]="Ozzie Togglevolt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2927:description:1-42","2927:description:44-60","2927:description:62-135","2927:description:137-195","2927:description:200-235","2927:description:240-287","2927:description:292-321","2927:description:323-372","2927:description:374-411","2927:description:413-464","2927:objective:1-40"},["minimumStage"]=2,["questID"]=2927,["sourceHash"]="4c26d2a0d5365e5e27429f907691de4bb821661cd457b62bdcc4e2b1157a16d1"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-6569",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gnoarn was bald and blamed the loss of his once-prized gnomefro on Gnomeregan’s radiation leak.",["title"]="Gnoarn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2927:description:1-42","2927:description:44-60","2927:description:62-135","2927:description:137-195","2927:description:200-235","2927:description:240-287","2927:description:292-321","2927:description:323-372","2927:description:374-411","2927:description:413-464","2927:objective:1-40"},["minimumStage"]=2,["questID"]=2927,["sourceHash"]="4c26d2a0d5365e5e27429f907691de4bb821661cd457b62bdcc4e2b1157a16d1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6569",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted both the city and its afflicted people saved, directing help toward Ozzie and Razzle’s research.",["title"]="Gnoarn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2929:description:1-26","2929:description:28-100","2929:description:102-114","2929:description:116-121","2929:description:123-129","2929:description:131-172","2929:description:174-243","2929:description:245-267","2929:description:272-301","2929:description:303-357","2929:description:359-438","2929:description:440-469","2929:objective:1-53","2929:objective:55-114"},["minimumStage"]=2,["questID"]=2929,["sourceHash"]="25be94f2a0c5037f02dc52b2adb116292f6fa54bb1cae3818f14d4229bd1a786"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="mekkatorque",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mekkatorque had trusted Thermaplugg and regarded his seizure of the ruined city as a betrayal of the entire gnomish people.",["title"]="Gelbin Mekkatorque"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2929:description:1-26","2929:description:28-100","2929:description:102-114","2929:description:116-121","2929:description:123-129","2929:description:131-172","2929:description:174-243","2929:description:245-267","2929:description:272-301","2929:description:303-357","2929:description:359-438","2929:description:440-469","2929:objective:1-53","2929:objective:55-114"},["minimumStage"]=2,["questID"]=2929,["sourceHash"]="25be94f2a0c5037f02dc52b2adb116292f6fa54bb1cae3818f14d4229bd1a786"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="mekkatorque",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Displacement did not end his determination to retake Gnomeregan; he called for Thermaplugg’s destruction as part of that fight.",["title"]="Gelbin Mekkatorque"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2930:description:1-53","2930:description:56-78","2930:description:83-201","2930:description:204-275","2930:description:277-356","2930:description:359-426","2930:description:428-471","2930:description:476-494","2930:description:497-509","2930:objective:1-70"},["minimumStage"]=2,["questID"]=2930,["sourceHash"]="83bcb14d5ad55c9b1b73cb7c1257c7b0bffbb25df4bbbe448ace056d0ad3f22f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7950",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Castpipe sought vital data abandoned during Gnomeregan’s evacuation, preserved on a prismatic punch card deep inside the city.",["title"]="Master Mechanic Castpipe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2930:description:1-53","2930:description:56-78","2930:description:83-201","2930:description:204-275","2930:description:277-356","2930:description:359-426","2930:description:428-471","2930:description:476-494","2930:description:497-509","2930:objective:1-70"},["minimumStage"]=2,["questID"]=2930,["sourceHash"]="83bcb14d5ad55c9b1b73cb7c1257c7b0bffbb25df4bbbe448ace056d0ad3f22f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7950",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Recovering it required successive security clearance through the Matrix Punchograph terminals, while even the initial punch cards had been left behind.",["title"]="Master Mechanic Castpipe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2932:description:1-80","2932:description:82-107","2932:description:112-174","2932:description:177-262","2932:description:267-321","2932:description:324-435","2932:description:440-487","2932:objective:1-53","2932:objective:56-176"},["minimumStage"]=2,["questID"]=2932,["sourceHash"]="5d490ece2874daa5695e490b32a6eed33cfccdf95b4b15c8e901905052095a0c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2497",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nimboya sought to punish the Witherbark for what he described as betraying their former Horde allies.",["title"]="Nimboya"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2932:description:1-80","2932:description:82-107","2932:description:112-174","2932:description:177-262","2932:description:267-321","2932:description:324-435","2932:description:440-487","2932:objective:1-53","2932:objective:56-176"},["minimumStage"]=2,["questID"]=2932,["sourceHash"]="5d490ece2874daa5695e490b32a6eed33cfccdf95b4b15c8e901905052095a0c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2497",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted a skull-bearing pike raised in Hiri’watha or Zun’watha as a warning about the consequences of that betrayal.",["title"]="Nimboya"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2954:description:1-40","2954:description:43-169","2954:description:174-327","2954:description:330-434","2954:objective:1-117"},["minimumStage"]=2,["questID"]=2954,["sourceHash"]="4ba7316dae351f76d5287bf119cc6705f48f776a8d34cb5ca8022d849ff65c74"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7918",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Stone Watcher guarded access to the Uldum compound and required the Plates of Uldum integrated with the visitor’s disc set.",["title"]="Stone Watcher of Norgannon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2954:description:1-40","2954:description:43-169","2954:description:174-327","2954:description:330-434","2954:objective:1-117"},["minimumStage"]=2,["questID"]=2954,["sourceHash"]="4ba7316dae351f76d5287bf119cc6705f48f776a8d34cb5ca8022d849ff65c74"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7918",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Its appearance in response to the Platinum Discs confirmed that the desert investigation had reached a responsive guardian, not that entry had been granted.",["title"]="Stone Watcher of Norgannon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2970:description:1-81","2970:description:83-232","2970:description:237-298","2970:description:300-368","2970:description:370-464","2970:objective:1-127"},["minimumStage"]=2,["questID"]=2970,["sourceHash"]="ce26148b57fca2386b05732955dc5b51dd226810ac67d2697a33e856d31228dd"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7957",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jer’kai and Kindal planned to strike the Grimtotem together, relying on Kindal’s arrows and help from willing allies.",["title"]="Jer'kai Moonweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2970:description:1-81","2970:description:83-232","2970:description:237-298","2970:description:300-368","2970:description:370-464","2970:objective:1-127"},["minimumStage"]=2,["questID"]=2970,["sourceHash"]="ce26148b57fca2386b05732955dc5b51dd226810ac67d2697a33e856d31228dd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7957",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She pointed to further camps east of the first target, presenting a wider local assault rather than a single isolated skirmish.",["title"]="Jer'kai Moonweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2983:description:1-51","2983:description:53-152","2983:description:154-184","2983:description:186-247","2983:description:252-287","2983:description:289-429","2983:objective:1-32"},["minimumStage"]=2,["questID"]=2983,["sourceHash"]="8472f547013794861ae0c9ffe4da8fac51eea00335d874a80ffe53874d6dd70e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3173",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Swart directed shamans ready for the power of fire to Kranal Fiss, who would determine the next part of their training.",["title"]="Swart"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2984:description:1-48","2984:description:50-143","2984:description:145-199","2984:description:201-210","2984:description:212-296","2984:description:301-336","2984:description:338-466","2984:objective:1-32"},["minimumStage"]=2,["questID"]=2984,["sourceHash"]="768ff9b5ef6e2f222ac75a85dc3a33d440d27b732fb5ffb7fca85bbad5cf65fe"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3066",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Narm guided patient shaman pupils toward the study of fire’s destruction and chaos under Kranal Fiss.",["title"]="Narm Skychaser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2997:description:1-10","2997:description:12-197","2997:description:199-312","2997:description:317-367","2997:description:369-420","2997:description:422-441","2997:objective:1-39"},["minimumStage"]=2,["questID"]=2997,["sourceHash"]="5d882565361147a770d856391a7d73173f5898c624946aaeb96ec79115523bf5"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1232",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Azar recommended Tiza Battleforge as a respected guide for young paladins learning both the Light and their responsibilities.",["title"]="Azar Stronghammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2997:description:1-10","2997:description:12-197","2997:description:199-312","2997:description:317-367","2997:description:369-420","2997:description:422-441","2997:objective:1-39"},["minimumStage"]=2,["questID"]=2997,["sourceHash"]="5d882565361147a770d856391a7d73173f5898c624946aaeb96ec79115523bf5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1232",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed pupils to the Hall of Mysteries in Ironforge’s Mystic Ward when their work in Dun Morogh allowed the journey.",["title"]="Azar Stronghammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2998:description:1-29","2998:description:31-116","2998:description:118-193","2998:description:195-277","2998:description:282-354","2998:description:356-436","2998:objective:1-37"},["minimumStage"]=2,["questID"]=2998,["sourceHash"]="2a60b079e663cd1c64a16f7597a6bb0ba5be4a1001af88987a3009b4365b6d91"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-927",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wilhelm passed on Duthorian Rall’s praise for a pupil and his wish to put that paladin’s abilities to further tests.",["title"]="Brother Wilhelm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2998:description:1-29","2998:description:31-116","2998:description:118-193","2998:description:195-277","2998:description:282-354","2998:description:356-436","2998:objective:1-37"},["minimumStage"]=2,["questID"]=2998,["sourceHash"]="2a60b079e663cd1c64a16f7597a6bb0ba5be4a1001af88987a3009b4365b6d91"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-927",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He identified Stormwind’s Cathedral of Light as Rall’s usual place.",["title"]="Brother Wilhelm"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3341:description:1-73","3341:description:75-185","3341:description:190-261","3341:description:263-389","3341:description:394-472","3341:description:474-509","3341:objective:1-80"},["minimumStage"]=2,["questID"]=3341,["sourceHash"]="cee4459d04c8f701721c8fc9a3cf6ad3dc7513261769dd44518411d47aa53adc"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2308",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Andrew’s newer reports overturned an earlier assessment of Razorfen Downs as a minor threat: its quilboar had allied with the Scourge.",["title"]="Andrew Brownell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3341:description:1-73","3341:description:75-185","3341:description:190-261","3341:description:263-389","3341:description:394-472","3341:description:474-509","3341:objective:1-80"},["minimumStage"]=2,["questID"]=3341,["sourceHash"]="cee4459d04c8f701721c8fc9a3cf6ad3dc7513261769dd44518411d47aa53adc"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2308",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought Amnennar’s destruction to sever the lich’s reported telepathic link with Ner’zhul and control over the quilboar.",["title"]="Andrew Brownell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3361:description:1-78","3361:description:81-173","3361:description:178-265","3361:description:268-299","3361:description:302-353","3361:description:356-412","3361:description:417-495","3361:objective:1-94"},["minimumStage"]=2,["questID"]=3361,["sourceHash"]="494e0509a295e10915eeaf9b05bb2677778a6b77410f59977683ef2a4d51b727"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-8416",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Felix fled the irradiation of Gnomeregan and lost his tools and belongings during the escape.",["title"]="Felix Whindlebolt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3361:description:1-78","3361:description:81-173","3361:description:178-265","3361:description:268-299","3361:description:302-353","3361:description:356-412","3361:description:417-495","3361:objective:1-94"},["minimumStage"]=2,["questID"]=3361,["sourceHash"]="494e0509a295e10915eeaf9b05bb2677778a6b77410f59977683ef2a4d51b727"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-8416",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Trolls carried his chest, box and bucket of bolts to camps near Anvilmar; lacking an adventurer’s skills, he depended on someone else to recover them.",["title"]="Felix Whindlebolt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2866:description:1-88","2866:description:91-178","2866:description:183-262","2866:description:265-322","2866:description:325-412","2866:description:417-490","2866:description:492-505","2866:objective:1-77"},["minimumStage"]=2,["questID"]=2866,["sourceHash"]="3c2aedc9fa2784f2ba96983aec1539f11c521980b0bc9e968c32573b72c411c5"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-1117",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shandris’s first exploration found little of note in ruins that long predated the present settlements.",["title"]="Ruins of Solarsal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2866:description:1-88","2866:description:91-178","2866:description:183-262","2866:description:265-322","2866:description:325-412","2866:description:417-490","2866:description:492-505","2866:objective:1-77"},["minimumStage"]=2,["questID"]=2866,["sourceHash"]="3c2aedc9fa2784f2ba96983aec1539f11c521980b0bc9e968c32573b72c411c5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1117",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A sudden Hatecrest occupation raised concern about an attack or another hidden purpose, prompting a renewed investigation.",["title"]="Ruins of Solarsal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2879:description:1-41","2879:description:43-185","2879:description:190-276","2879:description:278-388","2879:description:390-508","2879:objective:1-53"},["minimumStage"]=2,["questID"]=2879,["sourceHash"]="b4475e5fbbb1c9a4f6bf2acb293c64c1ea078b367ff7fc7f53f946fa7aa0e530"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1114",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Four flames still burned here: Samha, Imbel, Byltan and Lahassa. Their essences could energize the stave needed at the Equinex Monolith.",["title"]="Ruins of Ravenwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2879:description:1-41","2879:description:43-185","2879:description:190-276","2879:description:278-388","2879:description:390-508","2879:objective:1-53"},["minimumStage"]=2,["questID"]=2879,["sourceHash"]="b4475e5fbbb1c9a4f6bf2acb293c64c1ea078b367ff7fc7f53f946fa7aa0e530"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-1114",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The ruins and their monolith lay on Feralas’s mainland west of the Dream Bough.",["title"]="Ruins of Ravenwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1861:description:1-108","1861:description:111-204","1861:description:209-245","1861:description:248-292","1861:description:297-318","1861:description:321-443","1861:description:446-504","1861:objective:1-57"},["minimumStage"]=2,["questID"]=1861,["sourceHash"]="3b69f5f181ba327e2d0787e572fa53b79f45807c02fc878197071e13f80c4188"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-16517",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A waterfall fed the lake southwest of Stormwind’s gates.",["title"]="Mirror Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1861:description:1-108","1861:description:111-204","1861:description:209-245","1861:description:248-292","1861:description:297-318","1861:description:321-443","1861:description:446-504","1861:objective:1-57"},["minimumStage"]=2,["questID"]=1861,["sourceHash"]="3b69f5f181ba327e2d0787e572fa53b79f45807c02fc878197071e13f80c4188"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16517",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jennea sought a water sample from the waterfall’s base to test for magical taint, without yet knowing whether it was present.",["title"]="Mirror Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2239:description:1-11","2239:description:13-92","2239:description:97-371","2239:description:376-402","2239:description:404-456","2239:objective:1-48"},["minimumStage"]=2,["questID"]=2239,["sourceHash"]="b342ce6f5e5e6a85cc0492d62a15c7bf989d02ccf1cc6403f123ad070489859d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-134",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The armored steam tank collected the quarry’s shipment before refueling at Kharanos on its circuit back to Ironforge.",["title"]="Gol'Bolar Quarry"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1882:description:1-46","1882:description:49-150","1882:description:153-301","1882:description:306-368","1882:description:371-417","1882:description:420-458","1882:description:461-484","1882:objective:1-84"},["minimumStage"]=2,["questID"]=1882,["sourceHash"]="c693143fd1f551db318c9233be53c0e6cf37b401cdaa2a6a73bb8f1550f3520d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="reviewed-balnir-farmstead",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Snapdragons in the farmstead’s garden offered Anastasia a sample with which to measure possible plague corruption in eastern Tirisfal.",["title"]="Balnir Farmstead"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1938:description:1-76","1938:description:79-150","1938:description:153-175","1938:description:180-313","1938:description:318-375","1938:description:378-454","1938:objective:1-76"},["minimumStage"]=2,["questID"]=1938,["sourceHash"]="27816cf939ca3e1f34838cd6ed44e85e0986d663fd7df929dd913b43cf67308b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-96",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A mage banished for refusing to abandon dark arts made the tower his domain and carried Ur’s treatise into its library.",["title"]="Tower of Ilgalar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1322:description:1-107","1322:description:112-140","1322:description:142-187","1322:description:189-275","1322:description:277-326","1322:objective:1-62"},["minimumStage"]=2,["questID"]=1322,["sourceHash"]="28990e5c758f9e70a1ffa3c0880cf8f73568a61693ba6f8d3b77c230ac3fa74c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-499",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Large darkmist spiders took over the old mine northwest of Brackenwall.",["title"]="Darkmist Cavern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1322:description:1-107","1322:description:112-140","1322:description:142-187","1322:description:189-275","1322:description:277-326","1322:objective:1-62"},["minimumStage"]=2,["questID"]=1322,["sourceHash"]="28990e5c758f9e70a1ffa3c0880cf8f73568a61693ba6f8d3b77c230ac3fa74c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-499",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Their acidic venom offered Do’gol a way to remove soot from a shield recovered at Shady Rest.",["title"]="Darkmist Cavern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1424:description:1-84","1424:description:89-173","1424:description:175-271","1424:description:276-350","1424:description:355-388","1424:description:390-451","1424:description:453-505","1424:objective:1-62"},["minimumStage"]=2,["questID"]=1424,["sourceHash"]="2dfa03ee5d160166a2a04eb203d2c8512ec580af644d206a8ec4a6dccdc504cf"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-74",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The sunken Atal’ai temple and its green dragon guards drew the warchief’s investigators, who sought artifacts around the pool to explain the disaster.",["title"]="Pool of Tears"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2932:description:1-80","2932:description:82-107","2932:description:112-174","2932:description:177-262","2932:description:267-321","2932:description:324-435","2932:description:440-487","2932:objective:1-53","2932:objective:56-176"},["minimumStage"]=2,["questID"]=2932,["sourceHash"]="5d490ece2874daa5695e490b32a6eed33cfccdf95b4b15c8e901905052095a0c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1885",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nimboya named this small Witherbark village as a possible site for a warning pike meant to punish the tribe’s alleged betrayal of the Horde.",["title"]="Hiri'watha"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2932:description:1-80","2932:description:82-107","2932:description:112-174","2932:description:177-262","2932:description:267-321","2932:description:324-435","2932:description:440-487","2932:objective:1-53","2932:objective:56-176"},["minimumStage"]=2,["questID"]=2932,["sourceHash"]="5d490ece2874daa5695e490b32a6eed33cfccdf95b4b15c8e901905052095a0c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-352",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="This Witherbark village was among the places where Nimboya wanted a skull-bearing warning raised against his former allies.",["title"]="Zun'watha"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2822:description:1-90","2822:description:93-201","2822:description:206-288","2822:description:291-363","2822:description:366-434","2822:description:437-481","2822:objective:1-66"},["minimumStage"]=2,["questID"]=2822,["sourceHash"]="ac85eccc2b7726bd5026a458d266fbaa8d78d0fa8d34efd3028549f4b4d7774b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1105",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Feralas’s yetis inhabited the vale, and Jangdor prized their thick hides as material for fine leatherwork.",["title"]="Feral Scar Vale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1195:description:1-109","1195:description:114-214","1195:description:219-370","1195:description:372-490","1195:objective:1-66"},["minimumStage"]=2,["questID"]=1195,["sourceHash"]="78ed8423acff3f1b4a13ca435cc91b7ca7ffc1ac6555d46733db0dac927b5550"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-426",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dryads near the retreat carried etched phials sought to collect moonwell water for a centaur-relic expedition.",["title"]="Raynewood Retreat"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1195:description:1-109","1195:description:114-214","1195:description:219-370","1195:description:372-490","1195:objective:1-66"},["minimumStage"]=2,["questID"]=1195,["sourceHash"]="78ed8423acff3f1b4a13ca435cc91b7ca7ffc1ac6555d46733db0dac927b5550"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-433",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A moonwell south of the road beside the river’s western bank supplied water intended to breach the Galak relic’s protection.",["title"]="Falfarren River"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3364:description:1-4","3364:description:7-160","3364:description:163-219","3364:description:224-237","3364:description:240-261","3364:description:264-370","3364:description:373-437","3364:description:442-494","3364:objective:1-97"},["minimumStage"]=2,["questID"]=3364,["sourceHash"]="ccea0f317bd77ea80779190de6f6d82a244023ef608ae274989b85a266b633bf"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12738",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nori was late carrying Durnan’s scalding mornbrew after making an earlier delivery to Grelin, with only minutes before the drink cooled.",["title"]="Nori Pridedrift"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3364:description:1-4","3364:description:7-160","3364:description:163-219","3364:description:224-237","3364:description:240-261","3364:description:264-370","3364:description:373-437","3364:description:442-494","3364:objective:1-97"},["minimumStage"]=2,["questID"]=3364,["sourceHash"]="ccea0f317bd77ea80779190de6f6d82a244023ef608ae274989b85a266b633bf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12738",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She sought a faster messenger to Anvilmar and insisted her mug be returned afterward.",["title"]="Nori Pridedrift"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3370:description:1-76","3370:description:78-176","3370:description:181-313","3370:description:319-387","3370:description:389-406","3370:description:408-425","3370:objective:1-64"},["minimumStage"]=2,["questID"]=3370,["sourceHash"]="e450c5f0c546e5046d77428190360dbc4a4e19beeb2ec7e362e4966d15a4d2c6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Falla recognized pure Emerald Dream essence in the shard but saw nightmares rather than a reassuring dream within it.",["title"]="Falla Sagewind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3370:description:1-76","3370:description:78-176","3370:description:181-313","3370:description:319-387","3370:description:389-406","3370:description:408-425","3370:objective:1-64"},["minimumStage"]=2,["questID"]=3370,["sourceHash"]="e450c5f0c546e5046d77428190360dbc4a4e19beeb2ec7e362e4966d15a4d2c6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Concerned by the vision, she urged its prompt delivery to Mathrengyl Bearwalker of the Cenarion Circle.",["title"]="Falla Sagewind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3371:description:1-63","3371:description:65-124","3371:description:126-233","3371:description:238-308","3371:description:310-400","3371:description:402-430","3371:objective:1-63"},["minimumStage"]=2,["questID"]=3371,["sourceHash"]="318c9faa39b48aa4f8e6868d9cab9a69df2c980b11521c0915a668932a866953"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-8256",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thorius mourned Dorius deeply and sought to honor his final wish by freeing his men from the Dark Iron dwarves.",["title"]="Curator Thorius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3371:description:1-63","3371:description:65-124","3371:description:126-233","3371:description:238-308","3371:description:310-400","3371:description:402-430","3371:objective:1-63"},["minimumStage"]=2,["questID"]=3371,["sourceHash"]="318c9faa39b48aa4f8e6868d9cab9a69df2c980b11521c0915a668932a866953"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8256",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the rescue toward the sweltering Slag Pits, where the captives were forced to work.",["title"]="Curator Thorius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3376:description:1-35","3376:description:38-99","3376:description:104-173","3376:description:176-327","3376:description:330-371","3376:description:376-445","3376:objective:1-85"},["minimumStage"]=2,["questID"]=3376,["sourceHash"]="4c40153301c99152d51a36d96a40f5d4bd40d10d71df6876fc755421a3fc626d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3209",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Windfeather described the tauren’s hard-won home as still threatened by Bristleback attacks from Brambleblade Ravine.",["title"]="Brave Windfeather"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3376:description:1-35","3376:description:38-99","3376:description:104-173","3376:description:176-327","3376:description:330-371","3376:description:376-445","3376:objective:1-85"},["minimumStage"]=2,["questID"]=3376,["sourceHash"]="4c40153301c99152d51a36d96a40f5d4bd40d10d71df6876fc755421a3fc626d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3209",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Where earlier efforts had failed, he sought Chief Sharptusk’s death to break the continuing local war.",["title"]="Brave Windfeather"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3379:description:1-73","3379:description:75-151","3379:description:156-327","3379:description:329-392","3379:description:394-406","3379:description:411-441","3379:description:446-488","3379:objective:1-69","3379:objective:71-156","3379:objective:158-222"},["minimumStage"]=2,["questID"]=3379,["sourceHash"]="c30dbe9007077e0e8ea451d1b6eab59d2ee831c6b1c150bbb5119c286831e9dd"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8439",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nilith opposed poachers slaughtering Searing Gorge spiders without regard for the lasting supply of shadow silk.",["title"]="Nilith Lokrav"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3379:description:1-73","3379:description:75-151","3379:description:156-327","3379:description:329-392","3379:description:394-406","3379:description:411-441","3379:description:446-488","3379:objective:1-69","3379:objective:71-156","3379:objective:158-222"},["minimumStage"]=2,["questID"]=3379,["sourceHash"]="c30dbe9007077e0e8ea451d1b6eab59d2ee831c6b1c150bbb5119c286831e9dd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8439",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her concern joined an artisan’s demand for valuable silk with the damage done by indiscriminate hunting.",["title"]="Nilith Lokrav"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3382:description:1-67","3382:description:69-136","3382:description:138-155","3382:description:160-267","3382:description:269-384","3382:description:389-450","3382:description:455-495","3382:objective:1-99","3382:objective:101-136"},["minimumStage"]=2,["questID"]=3382,["sourceHash"]="35a442c699c98b75f29328ecd1a55385cb2b217b152859c9e78d1ebebedbdd2d"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-8380",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vanessa’s crew had been looking for a safe anchorage when naga attacked shortly after sunset, then returned again.",["title"]="Captain Vanessa Beltis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3382:description:1-67","3382:description:69-136","3382:description:138-155","3382:description:160-267","3382:description:269-384","3382:description:389-450","3382:description:455-495","3382:objective:1-99","3382:objective:101-136"},["minimumStage"]=2,["questID"]=3382,["sourceHash"]="35a442c699c98b75f29328ecd1a55385cb2b217b152859c9e78d1ebebedbdd2d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-8380",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She did not know what the attackers sought and kept scouts at the valley’s entrance to warn of the next assault.",["title"]="Captain Vanessa Beltis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3461:description:1-115","3461:description:117-172","3461:description:174-221","3461:description:223-251","3461:description:253-268","3461:description:273-327","3461:description:332-368","3461:description:370-434","3461:objective:1-47"},["minimumStage"]=2,["questID"]=3461,["sourceHash"]="d96e83ddc85000a25b77b6f226d847ecb2cfc5c1cfe2f1a8e7ca5903a53ce75f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-8392",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xiggs assisted Tymor’s expedition but had received no payment to pass to the traveler, directing any reward claim back to Ironforge.",["title"]="Pilot Xiggs Fuselighter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3461:description:1-115","3461:description:117-172","3461:description:174-221","3461:description:223-251","3461:description:253-268","3461:description:273-327","3461:description:332-368","3461:description:370-434","3461:objective:1-47"},["minimumStage"]=2,["questID"]=3461,["sourceHash"]="d96e83ddc85000a25b77b6f226d847ecb2cfc5c1cfe2f1a8e7ca5903a53ce75f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8392",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He returned the drawing kit rather than keep it after the difficult fieldwork.",["title"]="Pilot Xiggs Fuselighter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3462:description:1-37","3462:description:39-109","3462:objective:1-27"},["minimumStage"]=2,["questID"]=3462,["sourceHash"]="dbae2a5bae885e51c4d9afabeed4abddcee4b53eb0a5ac76620bb0d10a296e73"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-8509",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kalaran named Maltrake as his envoy and instructor in the Torch of Retribution’s use.",["title"]="Squire Maltrake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3463:description:1-16","3463:description:18-194","3463:description:199-324","3463:description:329-415","3463:description:417-465","3463:objective:1-122"},["minimumStage"]=2,["questID"]=3463,["sourceHash"]="c0c1eeb82ec2e7702867041712be138e307f8b0affeff55980c2a13c3404518f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8509",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maltrake claimed the torch could leave Dark Iron watchtowers burning long enough to prevent guards from using them, despite being unable to destroy the towers themselves.",["title"]="Squire Maltrake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3504:description:1-26","3504:description:28-77","3504:description:82-117","3504:description:119-140","3504:description:142-173","3504:description:178-223","3504:description:225-239","3504:description:241-316","3504:description:318-366","3504:description:371-431","3504:description:433-489","3504:description:491-510","3504:objective:1-57"},["minimumStage"]=2,["questID"]=3504,["sourceHash"]="0584873acd089a96d8eabc24b9a296e00b4e7bc0e73df764411c59d26f047121"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-8576",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Belgrom sent his would-be avenger to Ag’tor at Valormok after accusing a blood elf partner of murdering the warriors he had supplied.",["title"]="Ag'tor Bloodfist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3505:description:1-18","3505:description:23-126","3505:description:128-203","3505:description:208-311","3505:description:313-389","3505:description:391-441","3505:description:443-501","3505:objective:1-97","3505:objective:99-212"},["minimumStage"]=2,["questID"]=3505,["sourceHash"]="62d660d11fb70970e575f2434e441384238ee77f33cc33edf3a80f31143fa2f0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8576",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ag’tor directed the retaliation first against workers, then toward scouting their leader’s guarded personal camp for a way to provoke her.",["title"]="Ag'tor Bloodfist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3512:description:1-85","3512:description:88-183","3512:description:186-275","3512:description:280-393","3512:description:396-440","3512:description:443-506","3512:objective:1-85"},["minimumStage"]=2,["questID"]=3512,["sourceHash"]="39b0383b757788165a203b28920713d6f9b80e26cd22afde81e12fc84f610516"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5353",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Itharius described Eranikus as caught between sleep and death within nightmares, with the recovered essence badly tainted.",["title"]="Itharius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3512:description:1-85","3512:description:88-183","3512:description:186-275","3512:description:280-393","3512:description:396-440","3512:description:443-506","3512:objective:1-85"},["minimumStage"]=2,["questID"]=3512,["sourceHash"]="39b0383b757788165a203b28920713d6f9b80e26cd22afde81e12fc84f610516"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5353",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He hoped a method of speaking through the gem could reach Eranikus and recommended the human medium Umbranse as a possible ally.",["title"]="Itharius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3514:description:1-98","3514:description:103-220","3514:description:222-269","3514:description:274-301","3514:description:303-359","3514:description:361-385","3514:description:387-503","3514:objective:1-59"},["minimumStage"]=2,["questID"]=3514,["sourceHash"]="2fd93465d2adfcbe0b806a643fe985a0fc7c7fd0ef5a6a6788ee9064acd2d53d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8582",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kadrak sought to stop Rynthariel’s outrunners and mark the Talon Den with a Horde banner as a warning against further messengers through Horde territory.",["title"]="Kadrak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3514:description:1-98","3514:description:103-220","3514:description:222-269","3514:description:274-301","3514:description:303-359","3514:description:361-385","3514:description:387-503","3514:objective:1-59"},["minimumStage"]=2,["questID"]=3514,["sourceHash"]="2fd93465d2adfcbe0b806a643fe985a0fc7c7fd0ef5a6a6788ee9064acd2d53d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8582",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He identified a recovered scroll with Rynthariel, the Talon Den’s dryad keymaster, and treated it as evidence of hostile activity.",["title"]="Kadrak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3521:description:1-90","3521:description:92-150","3521:description:155-183","3521:description:185-319","3521:description:321-389","3521:description:394-442","3521:description:444-510","3521:objective:1-107"},["minimumStage"]=2,["questID"]=3521,["sourceHash"]="ece3cb3cfe44f735fa181bd0e9da1012ba75e3083e02c9c38c217f308e1ee8a9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-8583",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dirania knew an antidote that might help Iverron after the Webwood spiders poisoned him.",["title"]="Dirania Silvershine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3521:description:1-90","3521:description:92-150","3521:description:155-183","3521:description:185-319","3521:description:321-389","3521:description:394-442","3521:description:444-510","3521:objective:1-107"},["minimumStage"]=2,["questID"]=3521,["sourceHash"]="ece3cb3cfe44f735fa181bd0e9da1012ba75e3083e02c9c38c217f308e1ee8a9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8583",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her preparation required hyacinth mushrooms, moonpetal lilies from watery pools and ichor from the same spiders responsible for the poisoning.",["title"]="Dirania Silvershine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3526:description:1-69","3526:description:72-140","3526:description:143-232","3526:description:237-257","3526:description:260-355","3526:description:359-497","3526:objective:1-131"},["minimumStage"]=2,["questID"]=3526,["sourceHash"]="d7fb1ec32b0c513f9743c46c16171d2f9f03fce35c61e55d24f97ad47e8766fe"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-4586",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Graham favored goblin engineering for its high explosives and extravagant equipment, presenting it as the brilliant engineer’s choice.",["title"]="Graham Van Talen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3526:description:1-69","3526:description:72-140","3526:description:143-232","3526:description:237-257","3526:description:260-355","3526:description:359-497","3526:objective:1-131"},["minimumStage"]=2,["questID"]=3526,["sourceHash"]="d7fb1ec32b0c513f9743c46c16171d2f9f03fce35c61e55d24f97ad47e8766fe"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-4586",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent interested experts to Nixx Sprocketspring in Gadgetzan with an introductory manual.",["title"]="Graham Van Talen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3629:description:1-69","3629:description:72-142","3629:description:145-241","3629:description:246-266","3629:description:269-363","3629:description:367-505","3629:objective:1-131"},["minimumStage"]=2,["questID"]=3629,["sourceHash"]="02b273058707a2a54ea77e785982fc9d33ee57777ac31cdd34951fdd725ec9c2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5174",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Springspindle distrusted goblin engineering’s enthusiasm for explosions, joking that its practitioners endangered themselves as readily as anything nearby.",["title"]="Springspindle Fizzlegear"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3630:description:1-78","3630:description:81-140","3630:description:143-225","3630:description:230-250","3630:description:253-359","3630:description:363-492","3630:objective:1-131"},["minimumStage"]=2,["questID"]=3630,["sourceHash"]="52fede70e051629575c60f2f352409397c6c332f377c3561a454c77568c23f13"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5518",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lilliam championed gnome engineering as the creation of useful devices that could improve everyday life.",["title"]="Lilliam Sparkspindle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3630:description:1-78","3630:description:81-140","3630:description:143-225","3630:description:230-250","3630:description:253-359","3630:description:363-492","3630:objective:1-131"},["minimumStage"]=2,["questID"]=3630,["sourceHash"]="52fede70e051629575c60f2f352409397c6c332f377c3561a454c77568c23f13"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5518",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She directed those pursuing that discipline to Tinkmaster Overspark in Ironforge.",["title"]="Lilliam Sparkspindle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3633:description:1-69","3633:description:72-140","3633:description:143-232","3633:description:237-257","3633:description:260-355","3633:description:359-497","3633:objective:1-131"},["minimumStage"]=2,["questID"]=3633,["sourceHash"]="7bbfb0289280e9f87f30d6397034b91cde6cddfc5e7242768426119c4efca66c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3494",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tinkerwiz promoted goblin engineering as mastery of the world through explosives and fantastic gear.",["title"]="Tinkerwiz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3633:description:1-69","3633:description:72-140","3633:description:143-232","3633:description:237-257","3633:description:260-355","3633:description:359-497","3633:objective:1-131"},["minimumStage"]=2,["questID"]=3633,["sourceHash"]="7bbfb0289280e9f87f30d6397034b91cde6cddfc5e7242768426119c4efca66c"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3494",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recommended Nixx Sprocketspring in Gadgetzan to experts seeking that discipline.",["title"]="Tinkerwiz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3636:description:1-89","3636:description:91-152","3636:description:157-224","3636:description:226-369","3636:description:371-427","3636:description:432-496","3636:objective:1-82"},["minimumStage"]=2,["questID"]=3636,["sourceHash"]="258c54d3cc5e550bb2f6e0a5e63df77dee4614caf0dea94234ff0bfe19c8337f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1284",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Benedictus warned that Razorfen Downs’ quilboar had made a pact with the Scourge and fallen under Amnennar’s rule.",["title"]="Archbishop Benedictus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3636:description:1-89","3636:description:91-152","3636:description:157-224","3636:description:226-369","3636:description:371-427","3636:description:432-496","3636:objective:1-82"},["minimumStage"]=2,["questID"]=3636,["sourceHash"]="258c54d3cc5e550bb2f6e0a5e63df77dee4614caf0dea94234ff0bfe19c8337f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1284",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He called for followers of the Light to end the union rather than treat the Downs as merely another quilboar settlement.",["title"]="Archbishop Benedictus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3638:description:1-86","3638:description:89-187","3638:description:192-260","3638:description:263-309","3638:description:312-358","3638:description:363-479","3638:description:482-510","3638:objective:1-142"},["minimumStage"]=2,["questID"]=3638,["sourceHash"]="b4436dddd977ac36ce24e2faf19fcf19c3606954ff0a71fab9b18303b619e90c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-8126",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nixx taught goblin engineering as a craft of profit, powerful bombs and formidable weapons.",["title"]="Nixx Sprocketspring"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3638:description:1-86","3638:description:89-187","3638:description:192-260","3638:description:263-309","3638:description:312-358","3638:description:363-479","3638:description:482-510","3638:objective:1-142"},["minimumStage"]=2,["questID"]=3638,["sourceHash"]="b4436dddd977ac36ce24e2faf19fcf19c3606954ff0a71fab9b18303b619e90c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8126",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He required an oath of lifelong secrecy over its schemata before admitting a new engineer.",["title"]="Nixx Sprocketspring"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3661:description:1-46","3661:description:48-171","3661:description:176-290","3661:description:295-412","3661:description:414-458","3661:description:460-504","3661:objective:1-91"},["minimumStage"]=2,["questID"]=3661,["sourceHash"]="aa04dcfc8412fc441077bdd9ca024a2e670669a0c9558d965522e427d5239711"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7916",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Erelas sought Hinterlands wildkin feathers to investigate the rumor that Elune had created the creatures.",["title"]="Erelas Ambersky"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3661:description:1-46","3661:description:48-171","3661:description:176-290","3661:description:295-412","3661:description:414-458","3661:description:460-504","3661:objective:1-91"},["minimumStage"]=2,["questID"]=3661,["sourceHash"]="aa04dcfc8412fc441077bdd9ca024a2e670669a0c9558d965522e427d5239711"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7916",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described wildkin as capable of great gentleness but fiercely protective of what they valued, and did not treat their rumored origin as settled fact.",["title"]="Erelas Ambersky"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3762:description:1-66","3762:description:71-212","3762:description:215-334","3762:description:339-440","3762:objective:1-56"},["minimumStage"]=2,["questID"]=3762,["sourceHash"]="71520e9e0397f63bd2cd30245701931ef0ea88939ae55e6e85ba3a341d176921"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6746",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pala recruited seasoned travelers for a Cenarion Circle research effort led by Hamuul Runetotem.",["title"]="Innkeeper Pala"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3762:description:1-66","3762:description:71-212","3762:description:215-334","3762:description:339-440","3762:objective:1-56"},["minimumStage"]=2,["questID"]=3762,["sourceHash"]="71520e9e0397f63bd2cd30245701931ef0ea88939ae55e6e85ba3a341d176921"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6746",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She did not know the project’s particulars and sent interested people directly to Hamuul on Thunder Bluff’s Elder Rise.",["title"]="Innkeeper Pala"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3786:description:1-78","3786:description:81-166","3786:description:169-250","3786:description:255-324","3786:description:327-444","3786:objective:1-130","3786:objective:135-193"},["minimumStage"]=2,["questID"]=3786,["sourceHash"]="b45f422b5bae51d638900388bb9994dbe0253c84aa31e356a440f3ea71ed4946"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9087",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bashana handled morrowgrain deliveries on Elder Rise so that Hamuul could concentrate on the Circle’s research and other duties.",["title"]="Bashana Runetotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3786:description:1-78","3786:description:81-166","3786:description:169-250","3786:description:255-324","3786:description:327-444","3786:objective:1-130","3786:objective:135-193"},["minimumStage"]=2,["questID"]=3786,["sourceHash"]="b45f422b5bae51d638900388bb9994dbe0253c84aa31e356a440f3ea71ed4946"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9087",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She supplied an Evergreen Pouch to grow Tharlendis seeds with Un’Goro soil as fertilizer.",["title"]="Bashana Runetotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3787:description:1-20","3787:description:25-146","3787:description:149-246","3787:description:249-301","3787:description:303-393","3787:description:398-478","3787:objective:1-55"},["minimumStage"]=2,["questID"]=3787,["sourceHash"]="db069073b4fa3b6c315eeb950773f8822f022b6025164f154e45e067ee369916"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5566",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tannysa quietly referred Cenarion Circle researchers to her druid colleague Quintis Jonespyre in Feathermoon.",["title"]="Tannysa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3787:description:1-20","3787:description:25-146","3787:description:149-246","3787:description:249-301","3787:description:303-393","3787:description:398-478","3787:objective:1-55"},["minimumStage"]=2,["questID"]=3787,["sourceHash"]="db069073b4fa3b6c315eeb950773f8822f022b6025164f154e45e067ee369916"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5566",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She asked that the discussion of morrowgrain be kept from the Arch Druid’s ears.",["title"]="Tannysa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3788:description:1-20","3788:description:25-146","3788:description:149-242","3788:description:245-297","3788:description:299-389","3788:description:394-474","3788:objective:1-55"},["minimumStage"]=2,["questID"]=3788,["sourceHash"]="8e411809942e3aaec5893952f09c6b5c1f4d0e5749da6f0c37e55af293f796fa"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7736",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shyria passed along Quintis Jonespyre’s request to speak privately with a traveler researching morrowgrain.",["title"]="Innkeeper Shyria"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3791:description:1-32","3791:description:35-217","3791:description:220-262","3791:description:265-379","3791:description:384-428","3791:description:431-495","3791:objective:1-68"},["minimumStage"]=2,["questID"]=3791,["sourceHash"]="5cec7c73070094a9814a4f47a4b9ceec6b4cd3ebc568e2fe84c8de4c9b6d890b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7879",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Quintis specialized in researching curses.",["title"]="Quintis Jonespyre"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3791:description:1-32","3791:description:35-217","3791:description:220-262","3791:description:265-379","3791:description:384-428","3791:description:431-495","3791:objective:1-68"},["minimumStage"]=2,["questID"]=3791,["sourceHash"]="5cec7c73070094a9814a4f47a4b9ceec6b4cd3ebc568e2fe84c8de4c9b6d890b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7879",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Reports of morrowgrain’s possible curse-like qualities made him question why the Arch Druid was using the Cenarion Circle’s name and resources to obtain such quantities.",["title"]="Quintis Jonespyre"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3801:description:1-14","3801:description:16-42","3801:description:44-130","3801:description:132-246","3801:description:251-350","3801:description:355-388","3801:description:390-482","3801:objective:1-92"},["minimumStage"]=2,["questID"]=3801,["sourceHash"]="a2e65b2147ec9a92788f1803d87ecd2582fbe34d8b06e3f11174fc9b1fb97212"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-8888",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Franclorn identified himself as the architect responsible for the stonewrought building method used in works across the world.",["title"]="Franclorn Forgewright"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3801:description:1-14","3801:description:16-42","3801:description:44-130","3801:description:132-246","3801:description:251-350","3801:description:355-388","3801:description:390-482","3801:objective:1-92"},["minimumStage"]=2,["questID"]=3801,["sourceHash"]="a2e65b2147ec9a92788f1803d87ecd2582fbe34d8b06e3f11174fc9b1fb97212"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8888",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered the key to his accursed city’s depths in exchange for assistance.",["title"]="Franclorn Forgewright"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3821:description:1-145","3821:description:150-281","3821:description:283-301","3821:description:303-317","3821:description:322-386","3821:description:388-436","3821:objective:1-82"},["minimumStage"]=2,["questID"]=3821,["sourceHash"]="92f3223a6174f263a7521a60d3468d8d82f55b4d1c3d18a1a1cbbe49fe680877"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9082",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thal’trak’s wife Sha’ni led a platoon investigating strange Firegut rituals in the Burning Steppes.",["title"]="Thal'trak Proudtusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3821:description:1-145","3821:description:150-281","3821:description:283-301","3821:description:303-317","3821:description:322-386","3821:description:388-436","3821:objective:1-82"},["minimumStage"]=2,["questID"]=3821,["sourceHash"]="92f3223a6174f263a7521a60d3468d8d82f55b4d1c3d18a1a1cbbe49fe680877"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9082",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Three weeks without news left him desperate, but his post prevented a search and Goretooth urged him to move on.",["title"]="Thal'trak Proudtusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3822:description:1-34","3822:description:36-62","3822:description:67-133","3822:description:138-193","3822:description:195-261","3822:description:263-347","3822:description:349-379","3822:description:384-411","3822:description:413-443","3822:description:448-490","3822:description:492-507","3822:objective:1-80","3822:objective:82-134"},["minimumStage"]=2,["questID"]=3822,["sourceHash"]="f8155b317bd55a178253e4a6c61a4a40a8cfcb83402b940285bd612e7f90416b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-9136",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krom’Grul’s ogres captured Sha’ni’s platoon and killed the others; she died after being held at an altar for a ritual.",["title"]="Sha'ni Proudtusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3822:description:1-34","3822:description:36-62","3822:description:67-133","3822:description:138-193","3822:description:195-261","3822:description:263-347","3822:description:349-379","3822:description:384-411","3822:description:413-443","3822:description:448-490","3822:description:492-507","3822:objective:1-80","3822:objective:82-134"},["minimumStage"]=2,["questID"]=3822,["sourceHash"]="f8155b317bd55a178253e4a6c61a4a40a8cfcb83402b940285bd612e7f90416b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9136",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her spirit wanted the stolen wedding nose-ring returned to Thal’trak with the hope that they would meet again in another life.",["title"]="Sha'ni Proudtusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3842:description:1-21","3842:description:23-38","3842:description:40-136","3842:description:138-165","3842:description:170-205","3842:description:207-276","3842:description:278-384","3842:description:389-462","3842:description:464-510","3842:objective:1-60"},["minimumStage"]=2,["questID"]=3842,["sourceHash"]="1f50676ddae6b06a1aca6e1b12468acc211500fb4dbf16a738294d1e2e9539e7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Quentin could work a protective spell to help a nearly hatched sprite darter egg remain healthy and undamaged.",["title"]="Quentin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3842:description:1-21","3842:description:23-38","3842:description:40-136","3842:description:138-165","3842:description:170-205","3842:description:207-276","3842:description:278-384","3842:description:389-462","3842:description:464-510","3842:objective:1-60"},["minimumStage"]=2,["questID"]=3842,["sourceHash"]="1f50676ddae6b06a1aca6e1b12468acc211500fb4dbf16a738294d1e2e9539e7"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He spoke highly of the two Moonweavers’ care for sprite darters and asked the egg’s new guardian to provide fortitude elixirs for the spell.",["title"]="Quentin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3881:description:1-68","3881:description:71-135","3881:description:138-306","3881:description:311-424","3881:description:427-501","3881:objective:1-89"},["minimumStage"]=2,["questID"]=3881,["sourceHash"]="b0096fb0ce1e70396d7639563f003f84e9017cc7ef2fac3a10d31cf58fe5e2de"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9270",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Williden led a non-aligned expedition in Un’Goro Crater.",["title"]="Williden Marshal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3881:description:1-68","3881:description:71-135","3881:description:138-306","3881:description:311-424","3881:description:427-501","3881:objective:1-89"},["minimumStage"]=2,["questID"]=3881,["sourceHash"]="b0096fb0ce1e70396d7639563f003f84e9017cc7ef2fac3a10d31cf58fe5e2de"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9270",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His troupe underestimated the crater’s dangers and abandoned vital supplies while fleeing camps in its southwest and northeast.",["title"]="Williden Marshal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3883:description:1-75","3883:description:78-177","3883:description:180-258","3883:description:263-310","3883:description:313-373","3883:description:376-450","3883:description:453-498","3883:objective:1-110","3883:objective:113-165","3883:objective:170-235"},["minimumStage"]=2,["questID"]=3883,["sourceHash"]="f179181582b1c78798337e255a7529b51b8c36e7fcbf782cfdefcbff80394437"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9271",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hol’anyee refused to abandon research after the expedition’s setbacks and sought to explain the Gorishi insects’ place in Un’Goro’s ecology.",["title"]="Hol'anyee Marshal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3883:description:1-75","3883:description:78-177","3883:description:180-258","3883:description:263-310","3883:description:313-373","3883:description:376-450","3883:description:453-498","3883:objective:1-110","3883:objective:113-165","3883:objective:170-235"},["minimumStage"]=2,["questID"]=3883,["sourceHash"]="f179181582b1c78798337e255a7529b51b8c36e7fcbf782cfdefcbff80394437"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9271",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She asked for a hive-wall sample beside the hanging larval spawns that marked their hatcheries, treating their apparently alien presence as a question to investigate.",["title"]="Hol'anyee Marshal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3902:description:1-10","3902:description:13-84","3902:description:89-197","3902:description:200-242","3902:description:245-366","3902:description:371-415","3902:description:418-467","3902:objective:1-106"},["minimumStage"]=2,["questID"]=3902,["sourceHash"]="adfe1efe63a3bccb1e1ab2e3cdf6ff29df15d667c33aa9c05fdd06afe60715a7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1740",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Saltain needed scavenged equipment for the next dead expected to rise in Deathknell.",["title"]="Deathguard Saltain"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3902:description:1-10","3902:description:13-84","3902:description:89-197","3902:description:200-242","3902:description:245-366","3902:description:371-415","3902:description:418-467","3902:objective:1-106"},["minimumStage"]=2,["questID"]=3902,["sourceHash"]="adfe1efe63a3bccb1e1ab2e3cdf6ff29df15d667c33aa9c05fdd06afe60715a7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1740",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent fresh recruits to search the boxed supplies so that newcomers would not begin their service without clothing or gear.",["title"]="Deathguard Saltain"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3904:description:1-91","3904:description:94-186","3904:description:188-220","3904:description:223-325","3904:description:330-354","3904:description:357-449","3904:description:454-476","3904:description:479-494","3904:objective:1-71"},["minimumStage"]=2,["questID"]=3904,["sourceHash"]="a1ce9b6827207a2d511676917dd8eec33fe1b580219d760e90f89707a025f9b4"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9296",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Defias occupied Northshire’s vineyards during Milly’s harvest, leaving the grape buckets behind enemy lines.",["title"]="Milly Osworth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3904:description:1-91","3904:description:94-186","3904:description:188-220","3904:description:223-325","3904:description:330-354","3904:description:357-449","3904:description:454-476","3904:description:479-494","3904:objective:1-71"},["minimumStage"]=2,["questID"]=3904,["sourceHash"]="a1ce9b6827207a2d511676917dd8eec33fe1b580219d760e90f89707a025f9b4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9296",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She feared both theft by the brigands and trampling by the guards sent to fight them, and sought recovery of the crop before either could ruin it.",["title"]="Milly Osworth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3908:description:1-44","3908:description:46-95","3908:description:97-137","3908:description:142-181","3908:description:183-209","3908:description:214-222","3908:description:224-291","3908:description:293-347","3908:description:352-425","3908:description:427-461","3908:description:463-506","3908:objective:1-54"},["minimumStage"]=2,["questID"]=3908,["sourceHash"]="3a9de31f6ab0807fd5972c260aa7a88262b2bab0fb36f2b8a9875e6d15bcf600"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-8737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Linken could not remember how he reached Un’Goro or why his sword needed strengthening.",["title"]="Linken"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3908:description:1-44","3908:description:46-95","3908:description:97-137","3908:description:142-181","3908:description:183-209","3908:description:214-222","3908:description:224-291","3908:description:293-347","3908:description:352-425","3908:description:427-461","3908:description:463-506","3908:objective:1-54"},["minimumStage"]=2,["questID"]=3908,["sourceHash"]="3a9de31f6ab0807fd5972c260aa7a88262b2bab0fb36f2b8a9875e6d15bcf600"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-8737",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The recovered belongings stirred incomplete memories, including Donova Snowden’s ability to temper the sword at Winterspring’s hot springs.",["title"]="Linken"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3924:description:1-81","3924:description:84-262","3924:description:265-298","3924:description:303-380","3924:description:383-482","3924:objective:1-61"},["minimumStage"]=2,["questID"]=3924,["sourceHash"]="db209163cb3dfc29c483b9d5a83cb86a787b65bf3a9ab4a18e46e407e2cec1d2"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-9317",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rilli had worked in the Venture Company, where rival Boss Copperplug kept the samophlange’s workings secret from all but trusted associates.",["title"]="Rilli Greasygob"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3924:description:1-81","3924:description:84-262","3924:description:265-298","3924:description:303-380","3924:description:383-482","3924:objective:1-61"},["minimumStage"]=2,["questID"]=3924,["sourceHash"]="db209163cb3dfc29c483b9d5a83cb86a787b65bf3a9ab4a18e46e407e2cec1d2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9317",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Repairing the device required the manual or its scattered pages from Copperplug at Boulder Lode Mine.",["title"]="Rilli Greasygob"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3982:description:1-45","3982:description:47-100","3982:description:102-169","3982:description:174-193","3982:description:198-264","3982:description:266-307","3982:description:309-371","3982:description:376-393","3982:description:398-402","3982:description:404-420","3982:description:422-435","3982:description:437-452","3982:objective:1-16"},["minimumStage"]=2,["questID"]=3982,["sourceHash"]="45ff6dacc7a990dfed455ed316db5d521eed92b570ae1459537d43164808ad75"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9020",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gor’shak claimed he deliberately accepted capture under Thrall’s orders to gather intelligence inside the Dark Iron city.",["title"]="Commander Gor'shak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3982:description:1-45","3982:description:47-100","3982:description:102-169","3982:description:174-193","3982:description:198-264","3982:description:266-307","3982:description:309-371","3982:description:376-393","3982:description:398-402","3982:description:404-420","3982:description:422-435","3982:description:437-452","3982:objective:1-16"},["minimumStage"]=2,["questID"]=3982,["sourceHash"]="45ff6dacc7a990dfed455ed316db5d521eed92b570ae1459537d43164808ad75"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9020",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He reported Moira Bronzebeard’s presence there and interrupted the disclosure when guards approached.",["title"]="Commander Gor'shak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4002:description:1-36","4002:description:41-100","4002:description:102-192","4002:description:197-278","4002:description:280-373","4002:description:375-411","4002:description:416-432","4002:objective:1-76"},["minimumStage"]=2,["questID"]=4002,["sourceHash"]="7360d448f0da71b9677de1a326c0f9200f6784047ae8223fe559e9152016ff44"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="thrall",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thrall saw helping the dwarves as an opportunity to improve relations in the Eastern Kingdoms and shape a less hopeless future for later generations of the Horde.",["title"]="Thrall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4004:description:1-30","4004:description:32-86","4004:description:91-130","4004:description:135-210","4004:description:212-294","4004:description:299-394","4004:description:399-414","4004:description:416-492","4004:objective:1-17"},["minimumStage"]=2,["questID"]=4004,["sourceHash"]="a6d3fb649717b4b1f61e206ccf50c85b518b12e59c38360a757857a38d526011"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-8929",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Moira called Thaurissan her husband and spoke of their unborn child after his death.",["title"]="Princess Moira Bronzebeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4004:description:1-30","4004:description:32-86","4004:description:91-130","4004:description:135-210","4004:description:212-294","4004:description:299-394","4004:description:399-414","4004:description:416-492","4004:objective:1-17"},["minimumStage"]=2,["questID"]=4004,["sourceHash"]="a6d3fb649717b4b1f61e206ccf50c85b518b12e59c38360a757857a38d526011"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8929",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She angrily declared that the child would inherit Ironforge and condemned the intervention that had left it without a father.",["title"]="Princess Moira Bronzebeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4061:description:1-90","4061:description:92-210","4061:description:212-244","4061:description:249-395","4061:description:397-499","4061:objective:1-108","4061:objective:113-219"},["minimumStage"]=2,["questID"]=4061,["sourceHash"]="e220327f3804bc922c0007859eb476e68548f28aff5f9ec6fe83daabd099032b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9079",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theodora investigated machines first encountered in the Searing Gorge, tracing imports toward the Burning Steppes and possibly Blackrock Depths.",["title"]="Hierophant Theodora Mulvadania"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4061:description:1-90","4061:description:92-210","4061:description:212-244","4061:description:249-395","4061:description:397-499","4061:objective:1-108","4061:objective:113-219"},["minimumStage"]=2,["questID"]=4061,["sourceHash"]="e220327f3804bc922c0007859eb476e68548f28aff5f9ec6fe83daabd099032b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9079",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Elemental shards from rock automatons and lesser constructs were to help her determine their true origin.",["title"]="Hierophant Theodora Mulvadania"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4101:description:1-74","4101:description:77-173","4101:description:176-244","4101:description:249-286","4101:description:289-359","4101:description:362-488","4101:objective:1-57"},["minimumStage"]=2,["questID"]=4101,["sourceHash"]="ad7770d3a0ee05d07ef76a2465766407fa005bafaf6074ff3b217eb8a026efce"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9528",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Arathandris knew methods for cleansing Felwood’s corrupted plants but entrusted them only to proven allies of the Cenarion Circle.",["title"]="Arathandris Silversky"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4101:description:1-74","4101:description:77-173","4101:description:176-244","4101:description:249-286","4101:description:289-359","4101:description:362-488","4101:objective:1-57"},["minimumStage"]=2,["questID"]=4101,["sourceHash"]="ad7770d3a0ee05d07ef76a2465766407fa005bafaf6074ff3b217eb8a026efce"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9528",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She sought blood amber from Warpwood elementals she judged beyond saving, hoping its study would help preserve other life.",["title"]="Arathandris Silversky"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4122:description:1-91","4122:description:93-203","4122:description:205-234","4122:description:239-322","4122:description:327-350","4122:description:352-429","4122:description:431-461","4122:objective:1-53","4122:objective:55-138","4122:objective:143-279","4122:objective:281-359"},["minimumStage"]=2,["questID"]=4122,["sourceHash"]="362344d0dc1b869950b00e37390eef4a8f4a4ceab7eac17d91b6316d8265f3b9"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-9080",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lexlort tracked Grark through the Searing Gorge and Blackrock Mountain into the Burning Steppes, accusing him of supplying operational intelligence to Blackrock orcs.",["title"]="Lexlort"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4122:description:1-91","4122:description:93-203","4122:description:205-234","4122:description:239-322","4122:description:327-350","4122:description:352-429","4122:description:431-461","4122:objective:1-53","4122:objective:55-138","4122:objective:143-279","4122:objective:281-359"},["minimumStage"]=2,["questID"]=4122,["sourceHash"]="362344d0dc1b869950b00e37390eef4a8f4a4ceab7eac17d91b6316d8265f3b9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9080",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Grark taken alive in shackles and brought back through the mountain.",["title"]="Lexlort"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4123:description:1-38","4123:description:41-110","4123:description:113-213","4123:description:218-243","4123:description:248-344","4123:description:347-465","4123:description:470-479","4123:objective:1-76"},["minimumStage"]=2,["questID"]=4123,["sourceHash"]="909995536d05b66fd8aa03b59524fc30b207b233ce82973b1f59a11fc6388b01"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9536",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maxwort had sought the fist-sized Heart of the Mountain for years, but the Dark Iron dwarves refused to sell it.",["title"]="Maxwort Uberglint"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4123:description:1-38","4123:description:41-110","4123:description:113-213","4123:description:218-243","4123:description:248-344","4123:description:347-465","4123:description:470-479","4123:objective:1-76"},["minimumStage"]=2,["questID"]=4123,["sourceHash"]="909995536d05b66fd8aa03b59524fc30b207b233ce82973b1f59a11fc6388b01"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9536",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He turned to force, explaining that opening the vault’s relic coffers would draw out Doomgrip and expose the secret safe.",["title"]="Maxwort Uberglint"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4141:description:1-22","4141:description:24-49","4141:description:54-113","4141:description:115-177","4141:description:179-244","4141:description:249-310","4141:description:312-415","4141:description:420-471","4141:description:473-508","4141:objective:1-44"},["minimumStage"]=2,["questID"]=4141,["sourceHash"]="205a7a6ca31c42ae695e2c615700e0caeb6a1afd5f335e8c9453d36b5b92d960"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9119",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Muigin blamed Larion for their predicament and resented his companion’s refusal to speak to him.",["title"]="Muigin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4141:description:1-22","4141:description:24-49","4141:description:54-113","4141:description:115-177","4141:description:179-244","4141:description:249-310","4141:description:312-415","4141:description:420-471","4141:description:473-508","4141:objective:1-44"},["minimumStage"]=2,["questID"]=4141,["sourceHash"]="205a7a6ca31c42ae695e2c615700e0caeb6a1afd5f335e8c9453d36b5b92d960"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9119",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He hoped to study and train the crater’s plant-creatures to obey commands, partly as a way of teasing Larion.",["title"]="Muigin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4143:description:1-78","4143:description:80-125","4143:description:130-209","4143:description:211-305","4143:description:310-380","4143:description:382-471","4143:description:473-486","4143:objective:1-75"},["minimumStage"]=2,["questID"]=4143,["sourceHash"]="ed716ceca80e29831c0299a7478477ab34861737a8d4855a14bafa28234b1935"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7775",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gregan had not seen plants like Muigin’s specimens and considered visiting Un’Goro to see them himself.",["title"]="Gregan Brewspewer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4143:description:1-78","4143:description:80-125","4143:description:130-209","4143:description:211-305","4143:description:310-380","4143:description:382-471","4143:description:473-486","4143:objective:1-75"},["minimumStage"]=2,["questID"]=4143,["sourceHash"]="ed716ceca80e29831c0299a7478477ab34861737a8d4855a14bafa28234b1935"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7775",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He identified Atal’ai haze from the Sunken Temple’s lurkers, worms and oozes as the substance Muigin needed to control the plants.",["title"]="Gregan Brewspewer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4145:description:1-22","4145:description:24-49","4145:description:54-141","4145:description:146-223","4145:description:225-331","4145:description:336-385","4145:description:387-438","4145:objective:1-129"},["minimumStage"]=2,["questID"]=4145,["sourceHash"]="f406fdf78f34bd3f5c0c26790c5132a575c43c8bb25c5550dad94578ed024b8a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9118",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Larion blamed Muigin’s supposed shortcut for their becoming lost, directly contradicting Muigin’s account of the dispute.",["title"]="Larion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4145:description:1-22","4145:description:24-49","4145:description:54-141","4145:description:146-223","4145:description:225-331","4145:description:336-385","4145:description:387-438","4145:objective:1-129"},["minimumStage"]=2,["questID"]=4145,["sourceHash"]="f406fdf78f34bd3f5c0c26790c5132a575c43c8bb25c5550dad94578ed024b8a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9118",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Annoyed by the plant-creatures Muigin kept sending at him, he wanted their supply reduced before further pests could reach him.",["title"]="Larion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4146:description:1-19","4146:description:21-138","4146:description:140-234","4146:description:239-328","4146:description:330-419","4146:description:421-499","4146:objective:1-88"},["minimumStage"]=2,["questID"]=4146,["sourceHash"]="614e8b0ee9501819021235e640d40bcf97b6b5ae17809d3565a559f0254564f0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-8496",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Liv developed a short-range bug-zapper prototype during Marvon’s absence and proposed adjusting it against Bloodpetals.",["title"]="Liv Rizzlefix"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4146:description:1-19","4146:description:21-138","4146:description:140-234","4146:description:239-328","4146:description:330-419","4146:description:421-499","4146:objective:1-88"},["minimumStage"]=2,["questID"]=4146,["sourceHash"]="614e8b0ee9501819021235e640d40bcf97b6b5ae17809d3565a559f0254564f0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8496",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The prototype required Atal’ai haze as fuel, making a temple expedition part of her answer to the plant pests.",["title"]="Liv Rizzlefix"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4161:description:1-205","4161:description:210-296","4161:description:298-384","4161:description:386-423","4161:description:428-509","4161:objective:1-51"},["minimumStage"]=2,["questID"]=4161,["sourceHash"]="f421cf27fd95b82e91182a269c0840dc25ae71f1191ca8af03afc23b1217d1ed"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6286",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zarrin taught that kaldorei meant children of the stars and that taking only what was needed, then giving back, sustained the night elves’ balance with nature.",["title"]="Zarrin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4161:description:1-205","4161:description:210-296","4161:description:298-384","4161:description:386-423","4161:description:428-509","4161:objective:1-51"},["minimumStage"]=2,["questID"]=4161,["sourceHash"]="f421cf27fd95b82e91182a269c0840dc25ae71f1191ca8af03afc23b1217d1ed"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6286",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He used a tightly limited gathering of spider legs to teach that restraint alongside a traditional recipe.",["title"]="Zarrin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4261:description:1-46","4261:description:48-74","4261:description:76-111","4261:description:116-171","4261:description:173-199","4261:description:204-290","4261:description:292-316","4261:description:318-410","4261:description:415-507","4261:objective:1-94"},["minimumStage"]=2,["questID"]=4261,["sourceHash"]="d0fc9c563464b4376af6d24040ef9794f8ff1ed15e381008d0f206023daeba46"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-9598",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Arei remembered Felwood before the Legion’s infernals and the Skull of Gul’dan’s corruption devastated the peaceful land.",["title"]="Arei"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4261:description:1-46","4261:description:48-74","4261:description:76-111","4261:description:116-171","4261:description:173-199","4261:description:204-290","4261:description:292-316","4261:description:318-410","4261:description:415-507","4261:objective:1-94"},["minimumStage"]=2,["questID"]=4261,["sourceHash"]="d0fc9c563464b4376af6d24040ef9794f8ff1ed15e381008d0f206023daeba46"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9598",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Even as a spirit he remained trapped in the land’s suffering, seeking an escort away so he could finally rest.",["title"]="Arei"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4262:description:1-141","4262:description:146-222","4262:description:227-319","4262:description:321-421","4262:description:426-472","4262:objective:1-50","4262:objective:55-113","4262:objective:115-146"},["minimumStage"]=2,["questID"]=4262,["sourceHash"]="b16b6e914218240f6a0b2e0864cfb30c8f7a4408157770e78853fbaa39e96f09"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9561",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jalinda’s mages returned burned from scouting Blackrock Mountain, while others did not survive.",["title"]="Jalinda Sprig"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4262:description:1-141","4262:description:146-222","4262:description:227-319","4262:description:321-421","4262:description:426-472","4262:objective:1-50","4262:objective:55-113","4262:objective:115-146"},["minimumStage"]=2,["questID"]=4262,["sourceHash"]="b16b6e914218240f6a0b2e0864cfb30c8f7a4408157770e78853fbaa39e96f09"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9561",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She sought Overmaster Pyron’s destruction so her expedition could pass the quarry entrance into Blackrock Depths.",["title"]="Jalinda Sprig"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4282:description:1-44","4282:description:49-83","4282:description:88-111","4282:description:113-244","4282:description:246-326","4282:description:331-361","4282:description:366-407","4282:description:409-452","4282:objective:1-42","4282:objective:47-153"},["minimumStage"]=2,["questID"]=4282,["sourceHash"]="0646bdd218397b8f280c22bdbe289f74dab7e6353bd9ae3914b97d9322dbbe11"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9023",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A discovered note revived Windsor’s hope that information he had lost could be recovered from Angerforge and Argelmach.",["title"]="Marshal Windsor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4282:description:1-44","4282:description:49-83","4282:description:88-111","4282:description:113-244","4282:description:246-326","4282:description:331-361","4282:description:366-407","4282:description:409-452","4282:objective:1-42","4282:objective:47-153"},["minimumStage"]=2,["questID"]=4282,["sourceHash"]="0646bdd218397b8f280c22bdbe289f74dab7e6353bd9ae3914b97d9322dbbe11"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9023",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He expected the two Dark Iron leaders to resist and asked for the records seized rather than rely on negotiation.",["title"]="Marshal Windsor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4293:description:1-74","4293:description:76-153","4293:description:155-307","4293:description:312-466","4293:objective:1-63","4293:objective:65-181","4293:objective:183-249"},["minimumStage"]=2,["questID"]=4293,["sourceHash"]="55c79b0251cc9446c4c76e3b71581fb2cd3729a221db42ce00dae35243904d6f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10136",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fuely sought Felwood slime samples as a control group for comparison with other specimens.",["title"]="Chemist Fuely"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4293:description:1-74","4293:description:76-153","4293:description:155-307","4293:description:312-466","4293:objective:1-63","4293:objective:65-181","4293:objective:183-249"},["minimumStage"]=2,["questID"]=4293,["sourceHash"]="55c79b0251cc9446c4c76e3b71581fb2cd3729a221db42ce00dae35243904d6f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10136",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He associated the slimes with fel-tainted pools and reports that they emerged during the forest’s destruction, treating the collected material as a basis for experiments.",["title"]="Chemist Fuely"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4297:description:1-75","4297:description:77-128","4297:description:130-219","4297:description:221-315","4297:description:317-376","4297:description:381-505","4297:objective:1-68"},["minimumStage"]=2,["questID"]=4297,["sourceHash"]="74c07e84eafed2889536c354ae4129746cbba6898822e3e898f631ba72fc03e9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9660",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Agnar cared for a nearly hatched sprite darter egg and prepared for the omnivorous hatchling’s first food.",["title"]="Agnar Beastamer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4297:description:1-75","4297:description:77-128","4297:description:130-219","4297:description:221-315","4297:description:317-376","4297:description:381-505","4297:objective:1-68"},["minimumStage"]=2,["questID"]=4297,["sourceHash"]="74c07e84eafed2889536c354ae4129746cbba6898822e3e898f631ba72fc03e9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9660",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recommended raw Silvermane stalker meat but admitted that his ideas about Elune’s purpose for sprite darters remained speculation.",["title"]="Agnar Beastamer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4300:description:1-81","4300:description:83-126","4300:description:131-183","4300:description:185-266","4300:description:268-283","4300:description:285-294","4300:description:296-338","4300:description:340-400","4300:description:402-456","4300:objective:1-55"},["minimumStage"]=2,["questID"]=4300,["sourceHash"]="cd5fd77266fffc6c7aeafef0a4048ce466a1505e162ca2834003e4d54d71c771"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8659",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jes’rimon sought uncommon white raptor claws from Un’Goro for clients of the Hand who wanted weapons fashioned from them.",["title"]="Jes'rimon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4300:description:1-81","4300:description:83-126","4300:description:131-183","4300:description:185-266","4300:description:268-283","4300:description:285-294","4300:description:296-338","4300:description:340-400","4300:description:402-456","4300:objective:1-55"},["minimumStage"]=2,["questID"]=4300,["sourceHash"]="cd5fd77266fffc6c7aeafef0a4048ce466a1505e162ca2834003e4d54d71c771"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8659",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He distinguished the rare pale claws from the usual black ones and offered payment for a substantial supply.",["title"]="Jes'rimon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4324:description:1-105","4324:description:108-113","4324:description:115-179","4324:description:184-273","4324:description:276-324","4324:description:329-348","4324:description:351-363","4324:description:366-398","4324:description:401-476","4324:objective:1-51"},["minimumStage"]=2,["questID"]=4324,["sourceHash"]="a40f5a109b6130da081f87ef1040fb05aa95d567e8ad7be3816e2b9fd4ea2889"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9706",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yorba’s sister Yuka had traced their younger brother Ribbly to the Burning Steppes and asked for hired assistance.",["title"]="Yorba Screwspigot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4324:description:1-105","4324:description:108-113","4324:description:115-179","4324:description:184-273","4324:description:276-324","4324:description:329-348","4324:description:351-363","4324:description:366-398","4324:description:401-476","4324:objective:1-51"},["minimumStage"]=2,["questID"]=4324,["sourceHash"]="a40f5a109b6130da081f87ef1040fb05aa95d567e8ad7be3816e2b9fd4ea2889"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9706",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He saw profit in Ribbly’s newly useful circumstances, sending willing hands to Yuka at Flame Crest.",["title"]="Yorba Screwspigot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4402:description:1-50","4402:description:55-78","4402:description:83-161","4402:description:163-228","4402:description:233-255","4402:description:257-380","4402:description:382-473","4402:objective:1-30","4402:objective:32-94"},["minimumStage"]=2,["questID"]=4402,["sourceHash"]="cde783173979456d38e2f98386e3581be72a384eab8716c4f6729d5b044c4547"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9796",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Galgar prepared cactus apple surprise, a sweet he praised for cooling travelers in the Valley of Trials’ heat.",["title"]="Galgar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4402:description:1-50","4402:description:55-78","4402:description:83-161","4402:description:163-228","4402:description:233-255","4402:description:257-380","4402:description:382-473","4402:objective:1-30","4402:objective:32-94"},["minimumStage"]=2,["questID"]=4402,["sourceHash"]="cde783173979456d38e2f98386e3581be72a384eab8716c4f6729d5b044c4547"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9796",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He exchanged portions of the dish for locally gathered cactus apples.",["title"]="Galgar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4486:description:1-72","4486:description:77-108","4486:description:110-196","4486:description:198-263","4486:description:265-299","4486:description:304-456","4486:description:458-475","4486:description:477-510","4486:objective:1-37"},["minimumStage"]=2,["questID"]=4486,["sourceHash"]="8836182c79aa5a757aeb5e795271b772abf151105c1e18175c50b993ab9aa472"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5149",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brandur admitted jealousy of another paladin’s accomplishments and said Tiza had made him promise to work on that weakness.",["title"]="Brandur Ironhammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4486:description:1-72","4486:description:77-108","4486:description:110-196","4486:description:198-263","4486:description:265-299","4486:description:304-456","4486:description:458-475","4486:description:477-510","4486:objective:1-37"},["minimumStage"]=2,["questID"]=4486,["sourceHash"]="8836182c79aa5a757aeb5e795271b772abf151105c1e18175c50b993ab9aa472"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5149",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He set the envy aside to relay Duthorian’s urgent request for a meeting in Stormwind.",["title"]="Brandur Ironhammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4487:description:1-22","4487:description:24-146","4487:description:148-157","4487:description:162-262","4487:description:264-295","4487:description:297-373","4487:description:375-381","4487:description:383-402","4487:description:407-467","4487:description:469-506","4487:objective:1-35"},["minimumStage"]=2,["questID"]=4487,["sourceHash"]="38f0134020c8e049bd270fdcd8b99986c009899785f98c38720560bdf4b141e1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5172",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Briarthorn regarded a warlock’s growing power as grounds for a further, darkly amused blessing.",["title"]="Briarthorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4487:description:1-22","4487:description:24-146","4487:description:148-157","4487:description:162-262","4487:description:264-295","4487:description:297-373","4487:description:375-381","4487:description:383-402","4487:description:407-467","4487:description:469-506","4487:objective:1-35"},["minimumStage"]=2,["questID"]=4487,["sourceHash"]="38f0134020c8e049bd270fdcd8b99986c009899785f98c38720560bdf4b141e1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5172",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the pupil to Strahad above Ratchet, joking that a demon sent to summon them had apparently been outpaced.",["title"]="Briarthorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3371:description:1-63","3371:description:65-124","3371:description:126-233","3371:description:238-308","3371:description:310-400","3371:description:402-430","3371:objective:1-63"},["minimumStage"]=2,["questID"]=3371,["sourceHash"]="318c9faa39b48aa4f8e6868d9cab9a69df2c980b11521c0915a668932a866953"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-1443",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A sweltering mine in the Searing Gorge housed the Dark Iron dwarves’ forced labor.",["title"]="The Slag Pit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3371:description:1-63","3371:description:65-124","3371:description:126-233","3371:description:238-308","3371:description:310-400","3371:description:402-430","3371:objective:1-63"},["minimumStage"]=2,["questID"]=3371,["sourceHash"]="318c9faa39b48aa4f8e6868d9cab9a69df2c980b11521c0915a668932a866953"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1443",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dorius’s men were among the slaves Thorius sought to free in fulfillment of his fallen friend’s last request.",["title"]="The Slag Pit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4101:description:1-74","4101:description:77-173","4101:description:176-244","4101:description:249-286","4101:description:289-359","4101:description:362-488","4101:objective:1-57"},["minimumStage"]=2,["questID"]=4101,["sourceHash"]="ad7770d3a0ee05d07ef76a2465766407fa005bafaf6074ff3b217eb8a026efce"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1768",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Warpwood elementals in the northern caverns were judged beyond cleansing, but their blood amber might help Arathandris save other corrupted plants.",["title"]="Irontree Cavern"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3924:description:1-81","3924:description:84-262","3924:description:265-298","3924:description:303-380","3924:description:383-482","3924:objective:1-61"},["minimumStage"]=2,["questID"]=3924,["sourceHash"]="db209163cb3dfc29c483b9d5a83cb86a787b65bf3a9ab4a18e46e407e2cec1d2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-381",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Boss Copperplug kept the samophlange manual here, distributing fragments of its secrets only to trusted Venture Company associates.",["title"]="Boulder Lode Mine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4324:description:1-105","4324:description:108-113","4324:description:115-179","4324:description:184-273","4324:description:276-324","4324:description:329-348","4324:description:351-363","4324:description:366-398","4324:description:401-476","4324:objective:1-51"},["minimumStage"]=2,["questID"]=4324,["sourceHash"]="a40f5a109b6130da081f87ef1040fb05aa95d567e8ad7be3816e2b9fd4ea2889"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-251",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The refuge occupied a cave northwest of Dreadmaul Rock.",["title"]="Flame Crest"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"4324:description:1-105","4324:description:108-113","4324:description:115-179","4324:description:184-273","4324:description:276-324","4324:description:329-348","4324:description:351-363","4324:description:366-398","4324:description:401-476","4324:objective:1-51"},["minimumStage"]=2,["questID"]=4324,["sourceHash"]="a40f5a109b6130da081f87ef1040fb05aa95d567e8ad7be3816e2b9fd4ea2889"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-251",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yuka Screwspigot stayed here while tracking Ribbly and seeking hired help through her brother Yorba.",["title"]="Flame Crest"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3786:description:1-78","3786:description:81-166","3786:description:169-250","3786:description:255-324","3786:description:327-444","3786:objective:1-130","3786:objective:135-193"},["minimumStage"]=2,["questID"]=3786,["sourceHash"]="b45f422b5bae51d638900388bb9994dbe0253c84aa31e356a440f3ea71ed4946"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1639",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bashana received morrowgrain grown with Tharlendis seeds and Un’Goro soil, protecting Hamuul’s time for the research itself.",["title"]="Elder Rise"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3904:description:1-91","3904:description:94-186","3904:description:188-220","3904:description:223-325","3904:description:330-354","3904:description:357-449","3904:description:454-476","3904:description:479-494","3904:objective:1-71"},["minimumStage"]=2,["questID"]=3904,["sourceHash"]="a1ce9b6827207a2d511676917dd8eec33fe1b580219d760e90f89707a025f9b4"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16520",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Defias occupied the vineyard while Milly was gathering grapes, leaving harvest buckets vulnerable to theft or trampling during the guards’ response.",["title"]="Northshire Vineyards"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3364:description:1-4","3364:description:7-160","3364:description:163-219","3364:description:224-237","3364:description:240-261","3364:description:264-370","3364:description:373-437","3364:description:442-494","3364:objective:1-97"},["minimumStage"]=2,["questID"]=3364,["sourceHash"]="ccea0f317bd77ea80779190de6f6d82a244023ef608ae274989b85a266b633bf"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-location-area-77",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The settlement was dug into the mountain, northeast of Nori’s delivery stop.",["title"]="Anvilmar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3376:description:1-35","3376:description:38-99","3376:description:104-173","3376:description:176-327","3376:description:330-371","3376:description:376-445","3376:objective:1-85"},["minimumStage"]=2,["questID"]=3376,["sourceHash"]="4c40153301c99152d51a36d96a40f5d4bd40d10d71df6876fc755421a3fc626d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="brambleblade-ravine",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Chief Sharptusk led a makeshift Bristleback village in the ravine, from which continued attacks burdened the nearby tauren.",["title"]="Brambleblade Ravine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3514:description:1-98","3514:description:103-220","3514:description:222-269","3514:description:274-301","3514:description:303-359","3514:description:361-385","3514:description:387-503","3514:objective:1-59"},["minimumStage"]=2,["questID"]=3514,["sourceHash"]="2fd93465d2adfcbe0b806a643fe985a0fc7c7fd0ef5a6a6788ee9064acd2d53d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-468",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rynthariel served as the den’s dryad keymaster, whose messengers drew Kadrak’s hostile attention.",["title"]="The Talon Den"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"3902:description:1-10","3902:description:13-84","3902:description:89-197","3902:description:200-242","3902:description:245-366","3902:description:371-415","3902:description:418-467","3902:objective:1-106"},["minimumStage"]=2,["questID"]=3902,["sourceHash"]="adfe1efe63a3bccb1e1ab2e3cdf6ff29df15d667c33aa9c05fdd06afe60715a7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-154",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Boxed equipment among the ruins was scavenged to clothe and supply recruits expected to rise from the grave.",["title"]="Deathknell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4488:description:1-55","4488:description:57-70","4488:description:75-136","4488:description:138-248","4488:description:250-321","4488:description:326-387","4488:description:389-457","4488:description:459-488","4488:objective:1-35"},["minimumStage"]=2,["questID"]=4488,["sourceHash"]="50224a88c6a5f5742a3f88d3cd3704ecededf2390be49d8f737beb315b784d34"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-461",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Demisette warned that growing power without knowledge or discipline could leave a warlock overwhelmed by corruption.",["title"]="Demisette Cloyce"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4488:description:1-55","4488:description:57-70","4488:description:75-136","4488:description:138-248","4488:description:250-321","4488:description:326-387","4488:description:389-457","4488:description:459-488","4488:objective:1-35"},["minimumStage"]=2,["questID"]=4488,["sourceHash"]="50224a88c6a5f5742a3f88d3cd3704ecededf2390be49d8f737beb315b784d34"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-461",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She passed on Strahad’s summons and urged a prompt journey to his tower above Ratchet.",["title"]="Demisette Cloyce"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4493:description:1-133","4493:description:136-233","4493:description:238-285","4493:description:288-363","4493:description:366-437","4493:description:440-509","4493:objective:1-43"},["minimumStage"]=2,["questID"]=4493,["sourceHash"]="f53d7f4ea7f30d800d66a033cffaea7329ca191a902f7604ad90a9c78c98b291"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7740",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gracina feared the silithid would consume everything outside their own ecology and judged the outbreaks already seen only an early stage.",["title"]="Gracina Spiritmight"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4493:description:1-133","4493:description:136-233","4493:description:238-285","4493:description:288-363","4493:description:366-437","4493:description:440-509","4493:objective:1-43"},["minimumStage"]=2,["questID"]=4493,["sourceHash"]="f53d7f4ea7f30d800d66a033cffaea7329ca191a902f7604ad90a9c78c98b291"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7740",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She suspected a deeper source in Un’Goro and sent her theory to Pestlezugg in Gadgetzan for investigation.",["title"]="Gracina Spiritmight"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4494:description:1-133","4494:description:136-233","4494:description:238-285","4494:description:288-363","4494:description:366-437","4494:description:440-509","4494:objective:1-43"},["minimumStage"]=2,["questID"]=4494,["sourceHash"]="47327ecd80c686805b921cd94ccd7cd98b6148e9dc1a5ea8fc2da2edcbff011d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7010",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zilzibin considered the silithid’s apparent drive to consume other life a grave danger to Azeroth.",["title"]="Zilzibin Drumlore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4494:description:1-133","4494:description:136-233","4494:description:238-285","4494:description:288-363","4494:description:366-437","4494:description:440-509","4494:objective:1-43"},["minimumStage"]=2,["questID"]=4494,["sourceHash"]="47327ecd80c686805b921cd94ccd7cd98b6148e9dc1a5ea8fc2da2edcbff011d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7010",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Pestlezugg to investigate his suspicion that their strength came from Un’Goro rather than treating that theory as proven.",["title"]="Zilzibin Drumlore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4503:description:1-28","4503:description:33-106","4503:description:108-199","4503:description:204-224","4503:description:226-358","4503:description:360-441","4503:description:443-470","4503:objective:1-99"},["minimumStage"]=2,["questID"]=4503,["sourceHash"]="1bd87a5105940bf168390ce5ecf154cc46cf59280d7a762c62ac785d4783aa91"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9998",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stranded and poor at navigation, Shizzle was too frightened of gryphons and wind riders to rely on them for the trip to Gadgetzan.",["title"]="Shizzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4503:description:1-28","4503:description:33-106","4503:description:108-199","4503:description:204-224","4503:description:226-358","4503:description:360-441","4503:description:443-470","4503:objective:1-99"},["minimumStage"]=2,["questID"]=4503,["sourceHash"]="1bd87a5105940bf168390ce5ecf154cc46cf59280d7a762c62ac785d4783aa91"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9998",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He built his own flying machine and hoped pterrordax and diemetradon scales would supply the last material needed for its wings.",["title"]="Shizzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4512:description:1-40","4512:description:42-84","4512:description:89-169","4512:description:171-267","4512:description:269-287","4512:description:289-312","4512:description:317-346","4512:description:348-419","4512:description:421-507","4512:objective:1-96"},["minimumStage"]=2,["questID"]=4512,["sourceHash"]="8fe5ac1520d21840a21c2cbcabe283df03293817d0589dc9444f88d2144b7811"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-9616",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Laris had helped recover a Menethil woman’s bag after oozes swallowed it, part of a lasting interest in slime.",["title"]="Laris Geardawdle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4512:description:1-40","4512:description:42-84","4512:description:89-169","4512:description:171-267","4512:description:269-287","4512:description:289-312","4512:description:317-346","4512:description:348-419","4512:description:421-507","4512:objective:1-96"},["minimumStage"]=2,["questID"]=4512,["sourceHash"]="8fe5ac1520d21840a21c2cbcabe283df03293817d0589dc9444f88d2144b7811"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9616",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Seeing Royal Apothecary Society members collecting samples sharpened his curiosity about ooze origins and prompted research with Felwood specimens.",["title"]="Laris Geardawdle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4621:description:1-25","4621:description:27-151","4621:description:154-246","4621:description:249-329","4621:description:334-444","4621:description:447-509","4621:objective:1-160"},["minimumStage"]=2,["questID"]=4621,["sourceHash"]="73b87ef0ecf88fd70db588b0d72595aa1480bdc96ca5f4622e6778e6e89f0e1a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2546",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Firallon wanted Seahorn and Revilgaz removed because Booty Bay’s fleet and law obstructed Bloodsail plunder.",["title"]="Fleet Master Firallon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4621:description:1-25","4621:description:27-151","4621:description:154-246","4621:description:249-329","4621:description:334-444","4621:description:447-509","4621:objective:1-160"},["minimumStage"]=2,["questID"]=4621,["sourceHash"]="73b87ef0ecf88fd70db588b0d72595aa1480bdc96ca5f4622e6778e6e89f0e1a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2546",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He made their deaths the condition for naming a willing pirate an honorary admiral, rather than granting that rank merely for meeting him.",["title"]="Fleet Master Firallon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4641:description:1-30","4641:description:32-73","4641:description:75-115","4641:description:120-125","4641:description:130-154","4641:description:159-177","4641:description:182-327","4641:description:329-338","4641:description:343-359","4641:description:364-444","4641:description:446-490","4641:objective:1-18","4641:objective:20-143"},["minimumStage"]=2,["questID"]=4641,["sourceHash"]="a41de2c247c47865634f8e0ff022115045ad8f1031550a3c5fe37354dc6b891d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10176",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kaltunk received young adventurers newly old enough to fight for the Horde and judged where their service should begin.",["title"]="Kaltunk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4641:description:1-30","4641:description:32-73","4641:description:75-115","4641:description:120-125","4641:description:130-154","4641:description:159-177","4641:description:182-327","4641:description:329-338","4641:description:343-359","4641:description:364-444","4641:description:446-490","4641:objective:1-18","4641:objective:20-143"},["minimumStage"]=2,["questID"]=4641,["sourceHash"]="a41de2c247c47865634f8e0ff022115045ad8f1031550a3c5fe37354dc6b891d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10176",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He tempered dreams of immediately strangling dragons or demons with a referral to Gornek for more suitable work.",["title"]="Kaltunk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4737:description:1-47","4737:description:49-188","4737:description:193-197","4737:description:199-213","4737:description:215-255","4737:description:257-266","4737:description:271-315","4737:description:317-412","4737:description:414-469","4737:description:471-504","4737:objective:1-42"},["minimumStage"]=2,["questID"]=4737,["sourceHash"]="28d47a81c0ce5a0d35a786f2ed465a18add2477fe83ed14fc2da75c5480c4e3a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3326",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zevrost expected a power-seeking warlock eventually to become enslaved by corruption and addiction.",["title"]="Zevrost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4737:description:1-47","4737:description:49-188","4737:description:193-197","4737:description:199-213","4737:description:215-255","4737:description:257-266","4737:description:271-315","4737:description:317-412","4737:description:414-469","4737:description:471-504","4737:objective:1-42"},["minimumStage"]=2,["questID"]=4737,["sourceHash"]="28d47a81c0ce5a0d35a786f2ed465a18add2477fe83ed14fc2da75c5480c4e3a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3326",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He acknowledged Menara’s different approach: creating tools to harness a pupil’s strength rather than sharing his pessimism.",["title"]="Zevrost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4739:description:5-13","4739:description:18-136","4739:description:138-155","4739:description:160-231","4739:description:233-292","4739:description:294-342","4739:description:347-396","4739:description:398-437","4739:objective:1-42"},["minimumStage"]=2,["questID"]=4739,["sourceHash"]="ca866620bbfa7c005900f3546dbc7bcb7da599b56dcdc013e09ec63819e9e587"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4563",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kaal recognized growing confidence in a warlock and recommended Menara’s further tutoring.",["title"]="Kaal Soulreaper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4739:description:5-13","4739:description:18-136","4739:description:138-155","4739:description:160-231","4739:description:233-292","4739:description:294-342","4739:description:347-396","4739:description:398-437","4739:objective:1-42"},["minimumStage"]=2,["questID"]=4739,["sourceHash"]="ca866620bbfa7c005900f3546dbc7bcb7da599b56dcdc013e09ec63819e9e587"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4563",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described her teaching and tests at Strahad’s tower, including gifts for those who succeeded.",["title"]="Kaal Soulreaper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4764:description:1-86","4764:description:89-170","4764:description:175-192","4764:description:195-250","4764:description:252-269","4764:description:272-334","4764:description:339-477","4764:description:482-510","4764:objective:1-69"},["minimumStage"]=2,["questID"]=4764,["sourceHash"]="999b37deffa1731cce5ec320f350918422fd98a89a381acdda6b39991b5e8b94"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9565",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mayara sought Doomrigger’s gem-encrusted clasp among the dwarven relics she believed might survive in Blackrock Spire’s ruined Hall of Fortune.",["title"]="Mayara Brightwing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4764:description:1-86","4764:description:89-170","4764:description:175-192","4764:description:195-250","4764:description:252-269","4764:description:272-334","4764:description:339-477","4764:description:482-510","4764:objective:1-69"},["minimumStage"]=2,["questID"]=4764,["sourceHash"]="999b37deffa1731cce5ec320f350918422fd98a89a381acdda6b39991b5e8b94"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9565",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She distinguished the hall’s earlier use for trophies and art from reports of its collapse and later, less wholesome purpose.",["title"]="Mayara Brightwing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4767:description:1-68","4767:description:70-144","4767:description:146-212","4767:description:214-241","4767:description:246-306","4767:description:308-400","4767:description:402-496","4767:objective:1-55"},["minimumStage"]=2,["questID"]=4767,["sourceHash"]="bfe09bb699685da4bacb62ac582e292690c4641968aa7585deb522489f1846f7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10377",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Elu gathered wyvern eggs for the growing ranks of master wind riders while hoping to become a rider himself.",["title"]="Elu"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4767:description:1-68","4767:description:70-144","4767:description:146-212","4767:description:214-241","4767:description:246-306","4767:description:308-400","4767:description:402-496","4767:objective:1-55"},["minimumStage"]=2,["questID"]=4767,["sourceHash"]="bfe09bb699685da4bacb62ac582e292690c4641968aa7585deb522489f1846f7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10377",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Training could not keep pace with demand, but Highperch’s wyverns fiercely protected the nests from which he sought eggs.",["title"]="Elu"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4770:description:1-19","4770:description:21-124","4770:description:126-194","4770:description:196-252","4770:description:257-294","4770:description:296-403","4770:description:408-446","4770:description:448-468","4770:objective:1-96"},["minimumStage"]=2,["questID"]=4770,["sourceHash"]="27190c3eaf955922a54752cbe4e1d735c18fb46b3816d9d75e591d84ad051427"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-10427",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pao’ka became lost in Highperch after studying wyverns too closely and being chased from a nest.",["title"]="Pao'ka Swiftmountain"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4770:description:1-19","4770:description:21-124","4770:description:126-194","4770:description:196-252","4770:description:257-294","4770:description:296-403","4770:description:408-446","4770:description:448-468","4770:objective:1-96"},["minimumStage"]=2,["questID"]=4770,["sourceHash"]="27190c3eaf955922a54752cbe4e1d735c18fb46b3816d9d75e591d84ad051427"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10427",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Days without friendly contact left him seeking an escort to Whitereach Post before Motega learned he had ventured out alone.",["title"]="Pao'ka Swiftmountain"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4811:description:1-60","4811:description:63-125","4811:description:128-239","4811:description:244-358","4811:description:361-430","4811:description:433-503","4811:objective:1-100","4811:objective:103-169"},["minimumStage"]=2,["questID"]=4811,["sourceHash"]="3c94ed3de3f118e8de0eef1771970258eec466af8f1e42e8eaae99ff60c599c6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2930",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Glynda wanted a reported red crystal found and examined because hostile moonkin seemed drawn to it.",["title"]="Sentinel Glynda Nal'Shea"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4811:description:1-60","4811:description:63-125","4811:description:128-239","4811:description:244-358","4811:description:361-430","4811:description:433-503","4811:objective:1-100","4811:objective:103-169"},["minimumStage"]=2,["questID"]=4811,["sourceHash"]="3c94ed3de3f118e8de0eef1771970258eec466af8f1e42e8eaae99ff60c599c6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2930",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She put Auberdine’s safety before reverence for the once-gentle creatures, while admitting that the crystal’s nature and even its existence were unconfirmed.",["title"]="Sentinel Glynda Nal'Shea"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4901:description:1-85","4901:description:87-210","4901:description:215-358","4901:description:360-425","4901:description:430-499","4901:objective:1-70","4901:objective:72-133"},["minimumStage"]=2,["questID"]=4901,["sourceHash"]="daa24aa274c4ae26b7fa64a13f645f6c5e41f11315fbadf812c07286037fb9be"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10300",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ranshalla copied incantations from Kel’Theril and believed they could open access to an altar of Elune above the ridge.",["title"]="Ranshalla"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4901:description:1-85","4901:description:87-210","4901:description:215-358","4901:description:360-425","4901:description:430-499","4901:objective:1-70","4901:objective:72-133"},["minimumStage"]=2,["questID"]=4901,["sourceHash"]="daa24aa274c4ae26b7fa64a13f645f6c5e41f11315fbadf812c07286037fb9be"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10300",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She needed help lighting five cave torches while she recited the spell, hoping the findings could then be reported to Erelas.",["title"]="Ranshalla"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4962:description:1-60","4962:description:65-137","4962:description:139-283","4962:description:288-372","4962:description:374-396","4962:description:401-479","4962:objective:1-74","4962:objective:76-191"},["minimumStage"]=2,["questID"]=4962,["sourceHash"]="bd87aaa3c6218af4ad42ab11342e7d3372706807bb7189ef9f27db23e25503f1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6254",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wytula supplied a ruby for capturing the soul of a weakened felhound as part of Menara’s work.",["title"]="Acolyte Wytula"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4962:description:1-60","4962:description:65-137","4962:description:139-283","4962:description:288-372","4962:description:374-396","4962:description:401-479","4962:objective:1-74","4962:objective:76-191"},["minimumStage"]=2,["questID"]=4962,["sourceHash"]="bd87aaa3c6218af4ad42ab11342e7d3372706807bb7189ef9f27db23e25503f1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6254",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She recommended Desolace’s felhounds and directed both the captured spirit and gem back to Menara.",["title"]="Acolyte Wytula"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4963:description:1-61","4963:description:66-141","4963:description:143-287","4963:description:292-376","4963:description:378-400","4963:description:405-486","4963:objective:1-76","4963:objective:78-195"},["minimumStage"]=2,["questID"]=4963,["sourceHash"]="773b9df92cc7afc5690cace39ab353bd7ada39cf905f35cf13bd72c3d69537a3"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6252",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magaz provided an emerald intended to draw an infernal’s soul near the creature’s death.",["title"]="Acolyte Magaz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4963:description:1-61","4963:description:66-141","4963:description:143-287","4963:description:292-376","4963:description:378-400","4963:description:405-486","4963:objective:1-76","4963:objective:78-195"},["minimumStage"]=2,["questID"]=4963,["sourceHash"]="773b9df92cc7afc5690cace39ab353bd7ada39cf905f35cf13bd72c3d69537a3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6252",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recommended infernals in Desolace and required the resulting spirit and gem taken to Menara.",["title"]="Acolyte Magaz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4984:description:1-140","4984:description:143-241","4984:description:244-298","4984:description:303-383","4984:description:386-435","4984:description:438-500","4984:objective:1-107"},["minimumStage"]=2,["questID"]=4984,["sourceHash"]="58bb9f191b6c7d78e6cc273953564035480416892eb2cb318abbc6e6d9600a4a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10739",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mulgris came to heal the plague’s harm to nature, even though he could do little alone against the Scourge.",["title"]="Mulgris Deepriver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4984:description:1-140","4984:description:143-241","4984:description:244-298","4984:description:303-383","4984:description:386-435","4984:description:438-500","4984:objective:1-107"},["minimumStage"]=2,["questID"]=4984,["sourceHash"]="58bb9f191b6c7d78e6cc273953564035480416892eb2cb318abbc6e6d9600a4a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10739",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Unable to finish his work, he sought mercy for nearby diseased wolves he believed beyond saving.",["title"]="Mulgris Deepriver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5021:description:1-33","5021:description:35-69","5021:description:74-157","5021:description:160-219","5021:description:222-319","5021:description:324-359","5021:description:362-395","5021:description:398-429","5021:description:432-464","5021:description:466-483","5021:objective:1-81","5021:objective:84-127","5021:objective:130-232"},["minimumStage"]=2,["questID"]=5021,["sourceHash"]="44071932fd6301bd4392a7cc99e263d0bb4bc97d45ef55da9bdd99f5d0869bd8"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-10778",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Janice’s apparition cowered in an upstairs corner, vaguely aware of visitors and uncertain of her surroundings.",["title"]="Janice Felstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5021:description:1-33","5021:description:35-69","5021:description:74-157","5021:description:160-219","5021:description:222-319","5021:description:324-359","5021:description:362-395","5021:description:398-429","5021:description:432-464","5021:description:466-483","5021:objective:1-81","5021:objective:84-127","5021:objective:130-232"},["minimumStage"]=2,["questID"]=5021,["sourceHash"]="44071932fd6301bd4392a7cc99e263d0bb4bc97d45ef55da9bdd99f5d0869bd8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10778",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her frightened thoughts remained fixed on a package left near her horse and a departure she feared had come too late.",["title"]="Janice Felstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5047:description:1-48","5047:description:50-114","5047:description:119-137","5047:description:142-185","5047:description:190-249","5047:description:254-366","5047:description:371-425","5047:description:427-458","5047:objective:1-40"},["minimumStage"]=2,["questID"]=5047,["sourceHash"]="5eae3889c7060dabe160b642159107032e39e308336822184a8c4dbb7d6266e1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10776",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Finkle carried a glowing piece of flesh taken from the beast’s innards and believed Malyfous could assess useful crafts from such remains.",["title"]="Finkle Einhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5047:description:1-48","5047:description:50-114","5047:description:119-137","5047:description:142-185","5047:description:190-249","5047:description:254-366","5047:description:371-425","5047:description:427-458","5047:objective:1-40"},["minimumStage"]=2,["questID"]=5047,["sourceHash"]="5eae3889c7060dabe160b642159107032e39e308336822184a8c4dbb7d6266e1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-10776",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent word to Malyfous in Everlook that he was safe and the suit had worked perfectly.",["title"]="Finkle Einhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5048:description:1-58","5048:description:60-151","5048:description:156-264","5048:description:267-344","5048:description:349-422","5048:description:425-481","5048:objective:1-67","5048:objective:70-145"},["minimumStage"]=2,["questID"]=5048,["sourceHash"]="c899534d31d377f5d766f48d8e7c2b7ec2530b52f4eff90c99c8df66428b832b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10782",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bathrilor consulted royal records to identify the intended recipient of a Felstone parcel.",["title"]="Royal Factor Bathrilor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5048:description:1-58","5048:description:60-151","5048:description:156-264","5048:description:267-344","5048:description:349-422","5048:description:425-481","5048:objective:1-67","5048:objective:70-145"},["minimumStage"]=2,["questID"]=5048,["sourceHash"]="c899534d31d377f5d766f48d8e7c2b7ec2530b52f4eff90c99c8df66428b832b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10782",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He judged Ol’ Emma a likely match for Emma Felstone but recommended asking her surname rather than treating the identification as certain.",["title"]="Royal Factor Bathrilor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5049:description:1-155","5049:description:160-230","5049:description:232-243","5049:description:246-303","5049:description:306-354","5049:description:357-498","5049:objective:1-81","5049:objective:84-157"},["minimumStage"]=2,["questID"]=5049,["sourceHash"]="e501298f0e73ea610189c723ab137a752fc2d5a701bc901609cc0adda6070326"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10781",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bauhaus used the available evidence to identify Jeremiah Payson as the parcel’s intended recipient.",["title"]="Royal Overseer Bauhaus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5049:description:1-155","5049:description:160-230","5049:description:232-243","5049:description:246-303","5049:description:306-354","5049:description:357-498","5049:objective:1-81","5049:objective:84-157"},["minimumStage"]=2,["questID"]=5049,["sourceHash"]="e501298f0e73ea610189c723ab137a752fc2d5a701bc901609cc0adda6070326"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10781",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He pointed toward the cockroach vendor beneath a walkway near the Undercity bank, seasoning the directions with sarcasm about the errand’s grandeur.",["title"]="Royal Overseer Bauhaus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5065:description:1-53","5065:description:56-166","5065:description:169-247","5065:description:250-253","5065:description:258-320","5065:description:325-370","5065:description:373-438","5065:description:440-471","5065:objective:1-78"},["minimumStage"]=2,["questID"]=5065,["sourceHash"]="324d16c5f42a50a7fae1bffa5ad9ed687a5918e50892e245eb2e97267f28342a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10460",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ironboot wanted all six Tablets of Mosh’aru investigated, warning that the first two alone concealed part of Hakkar’s legend.",["title"]="Prospector Ironboot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5065:description:1-53","5065:description:56-166","5065:description:169-247","5065:description:250-253","5065:description:258-320","5065:description:325-370","5065:description:373-438","5065:description:440-471","5065:objective:1-78"},["minimumStage"]=2,["questID"]=5065,["sourceHash"]="324d16c5f42a50a7fae1bffa5ad9ed687a5918e50892e245eb2e97267f28342a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10460",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His long study placed the third and fourth tablets with the Eastern Plaguelands’ Mossflayers, and he feared the secrets the remaining texts might hold.",["title"]="Prospector Ironboot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5124:description:1-22","5124:description:27-50","5124:description:55-106","5124:description:108-159","5124:description:164-186","5124:description:188-275","5124:description:277-366","5124:description:371-389","5124:description:394-506","5124:objective:1-89","5124:objective:91-149"},["minimumStage"]=2,["questID"]=5124,["sourceHash"]="4a2ffc8ad1db4f5e7cf67e9b2e8d54a1624031e91f9b7c6824f2490f29f4f9ad"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10637",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Malyfous wanted the unusual unfired gauntlets and enough component samples to determine how they could be reproduced.",["title"]="Malyfous Darkhammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5124:description:1-22","5124:description:27-50","5124:description:55-106","5124:description:108-159","5124:description:164-186","5124:description:188-275","5124:description:277-366","5124:description:371-389","5124:description:394-506","5124:objective:1-89","5124:objective:91-149"},["minimumStage"]=2,["questID"]=5124,["sourceHash"]="4a2ffc8ad1db4f5e7cf67e9b2e8d54a1624031e91f9b7c6824f2490f29f4f9ad"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10637",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered to supply ordinary thorium himself and teach the resulting recipe in exchange for the gauntlets and rarer materials.",["title"]="Malyfous Darkhammer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5141:description:1-68","5141:description:71-163","5141:description:168-316","5141:description:319-396","5141:description:399-499","5141:objective:1-111","5141:objective:116-197","5141:objective:202-373"},["minimumStage"]=2,["questID"]=5141,["sourceHash"]="173a87ea93ca986b0590b0603e172c039a0b46c39418dfce07a8ee824cf3e147"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7866",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Peter taught the crafting of dragonscale mail to leatherworkers able to demonstrate skilled scorpid work and acquire dragonkin scales.",["title"]="Peter Galen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5141:description:1-68","5141:description:71-163","5141:description:168-316","5141:description:319-396","5141:description:399-499","5141:objective:1-111","5141:objective:116-197","5141:objective:202-373"},["minimumStage"]=2,["questID"]=5141,["sourceHash"]="173a87ea93ca986b0590b0603e172c039a0b46c39418dfce07a8ee824cf3e147"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7866",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He presented the discipline as demanding but rewarding and required a deliberate commitment before instruction.",["title"]="Peter Galen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5143:description:1-206","5143:description:211-370","5143:description:373-443","5143:description:446-484","5143:objective:1-86","5143:objective:91-167","5143:objective:172-348"},["minimumStage"]=2,["questID"]=5143,["sourceHash"]="3f813b9db81d72dc717179fc7e82074a80cb9db6a8d3f4f14c27ed8e4a9ffbe3"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7870",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Caryssia offered tribal leatherworking mastery to artisans already accomplished in wild leather armor.",["title"]="Caryssia Moonhunter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5143:description:1-206","5143:description:211-370","5143:description:373-443","5143:description:446-484","5143:objective:1-86","5143:objective:91-167","5143:objective:172-348"},["minimumStage"]=2,["questID"]=5143,["sourceHash"]="3f813b9db81d72dc717179fc7e82074a80cb9db6a8d3f4f14c27ed8e4a9ffbe3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7870",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She framed the craft as an understanding of nature’s primal character, tested through the pupil’s finest work.",["title"]="Caryssia Moonhunter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5144:description:1-161","5144:description:166-322","5144:description:325-486","5144:objective:1-112","5144:objective:117-196","5144:objective:201-374"},["minimumStage"]=2,["questID"]=5144,["sourceHash"]="462c4a750d5e15fe54df25751fe0bca09f6a195e75d8304b6c09da807adc984b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7868",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sarah taught elemental leatherworking to those willing to study the powers within natural substances.",["title"]="Sarah Tanner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5144:description:1-161","5144:description:166-322","5144:description:325-486","5144:objective:1-112","5144:objective:117-196","5144:objective:201-374"},["minimumStage"]=2,["questID"]=5144,["sourceHash"]="462c4a750d5e15fe54df25751fe0bca09f6a195e75d8304b6c09da807adc984b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7868",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She required pure essences of fire, water, earth and wind as evidence of a prospective pupil’s attunement.",["title"]="Sarah Tanner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5145:description:1-68","5145:description:71-163","5145:description:168-316","5145:description:319-396","5145:description:399-499","5145:objective:1-122","5145:objective:127-208","5145:objective:213-384"},["minimumStage"]=2,["questID"]=5145,["sourceHash"]="5be377258a9f9d07d4ed86ceeed5f9e5b0e8381aff207fbb208347e3086219f0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7867",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thorkaf trained dragonscale leatherworkers through fine scorpid armor and the gathering of dragonkin scales.",["title"]="Thorkaf Dragoneye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5145:description:1-68","5145:description:71-163","5145:description:168-316","5145:description:319-396","5145:description:399-499","5145:objective:1-122","5145:objective:127-208","5145:objective:213-384"},["minimumStage"]=2,["questID"]=5145,["sourceHash"]="5be377258a9f9d07d4ed86ceeed5f9e5b0e8381aff207fbb208347e3086219f0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7867",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He required a focused choice of discipline before undertaking its demanding mail craft.",["title"]="Thorkaf Dragoneye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5146:description:1-161","5146:description:166-322","5146:description:325-486","5146:objective:1-123","5146:objective:128-207","5146:objective:212-385"},["minimumStage"]=2,["questID"]=5146,["sourceHash"]="f876de65e34dc07e437f40c2b5d6bbd8bffcc88c90866028a2da71ebd5f5d2af"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7869",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brumn offered elemental leatherworking instruction through the study of natural substances.",["title"]="Brumn Winterhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5146:description:1-161","5146:description:166-322","5146:description:325-486","5146:objective:1-123","5146:objective:128-207","5146:objective:212-385"},["minimumStage"]=2,["questID"]=5146,["sourceHash"]="f876de65e34dc07e437f40c2b5d6bbd8bffcc88c90866028a2da71ebd5f5d2af"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7869",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Proof of connection to the elements took the form of pure essences gathered from fire, water, earth and wind.",["title"]="Brumn Winterhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5148:description:1-206","5148:description:211-370","5148:description:373-443","5148:description:446-484","5148:objective:1-84","5148:objective:89-165","5148:objective:170-346"},["minimumStage"]=2,["questID"]=5148,["sourceHash"]="45da519576230fb79a7ee90dfade9eaa937947698b626d45fe3be12c3ad6de8c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7871",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Se’Jib guided accomplished wild-leather artisans toward tribal leatherworking.",["title"]="Se'Jib"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5148:description:1-206","5148:description:211-370","5148:description:373-443","5148:description:446-484","5148:objective:1-84","5148:objective:89-165","5148:objective:170-346"},["minimumStage"]=2,["questID"]=5148,["sourceHash"]="45da519576230fb79a7ee90dfade9eaa937947698b626d45fe3be12c3ad6de8c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7871",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He required the finest samples of a pupil’s armor and an understanding of primal nature before mastery could begin.",["title"]="Se'Jib"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5149:description:1-90","5149:description:93-139","5149:description:144-205","5149:description:208-309","5149:description:314-411","5149:description:416-444","5149:objective:1-19"},["minimumStage"]=2,["questID"]=5149,["sourceHash"]="82ce7b71b14eaa9115025c5cf32e3912ce40326fbe95291d989c33b3bfbef5b6"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-10926",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pamela waited in the family house because Aunt Marlene had told her to remain there while her father went to fight.",["title"]="Pamela Redpath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5149:description:1-90","5149:description:93-139","5149:description:144-205","5149:description:208-309","5149:description:314-411","5149:description:416-444","5149:objective:1-19"},["minimumStage"]=2,["questID"]=5149,["sourceHash"]="82ce7b71b14eaa9115025c5cf32e3912ce40326fbe95291d989c33b3bfbef5b6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10926",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The long wait and frightening whispers left her longing for her father and for the doll she had left in town.",["title"]="Pamela Redpath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5153:description:1-68","5153:description:71-131","5153:description:134-150","5153:description:155-189","5153:description:194-241","5153:description:244-353","5153:description:356-383","5153:description:385-425","5153:description:430-502","5153:objective:1-39"},["minimumStage"]=2,["questID"]=5153,["sourceHash"]="708297736a76eeb3d51627722a71258f90d1a4878b564b10a3fd17cda291c2f3"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-10927",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marlene said Joseph’s soul had been twisted by the Scourge and his body destroyed, while his wedding ring remained beneath his monument.",["title"]="Marlene Redpath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5153:description:1-68","5153:description:71-131","5153:description:134-150","5153:description:155-189","5153:description:194-241","5153:description:244-353","5153:description:356-383","5153:description:385-425","5153:description:430-502","5153:objective:1-39"},["minimumStage"]=2,["questID"]=5153,["sourceHash"]="708297736a76eeb3d51627722a71258f90d1a4878b564b10a3fd17cda291c2f3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10927",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She hoped Chromie’s strange powers might change his fate and reunite him with his daughter, without yet knowing whether that hope could succeed.",["title"]="Marlene Redpath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5156:description:1-212","5156:description:217-246","5156:description:248-307","5156:description:309-409","5156:description:411-441","5156:description:443-506","5156:objective:1-96","5156:objective:98-220"},["minimumStage"]=2,["questID"]=5156,["sourceHash"]="5f3793f529db52f5cd18b6acea23a3b46339b4a469be294a8890cd058eab4aa5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10921",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Taronn wanted to check whether Shatter Scar’s old infernal craters still held entropic elementals and foul water.",["title"]="Taronn Redfeather"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5156:description:1-212","5156:description:217-246","5156:description:248-307","5156:description:309-409","5156:description:411-441","5156:description:443-506","5156:objective:1-96","5156:objective:98-220"},["minimumStage"]=2,["questID"]=5156,["sourceHash"]="5f3793f529db52f5cd18b6acea23a3b46339b4a469be294a8890cd058eab4aa5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10921",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He connected the craters to infernals called down during the last great war and warned that the creatures remained dangerous.",["title"]="Taronn Redfeather"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5212:description:1-89","5212:description:94-139","5212:description:141-276","5212:description:278-320","5212:description:325-349","5212:description:351-443","5212:description:445-490","5212:objective:1-86","5212:objective:88-160"},["minimumStage"]=2,["questID"]=5212,["sourceHash"]="530420f207abee35879bdd379030bbc4123b6c60986e8fceb2c1774fbf52c80d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11035",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Betina had studied the plague for years and rejected the idea that scientific investigation belonged only to Forsaken apothecaries.",["title"]="Betina Bigglezink"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5212:description:1-89","5212:description:94-139","5212:description:141-276","5212:description:278-320","5212:description:325-349","5212:description:351-443","5212:description:445-490","5212:objective:1-86","5212:objective:88-160"},["minimumStage"]=2,["questID"]=5212,["sourceHash"]="530420f207abee35879bdd379030bbc4123b6c60986e8fceb2c1774fbf52c80d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11035",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Evidence that the plague was strengthening overturned earlier expectations of decline and led her to seek flesh from Stratholme’s newly infected.",["title"]="Betina Bigglezink"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5214:description:1-17","5214:description:19-40","5214:description:42-126","5214:description:128-247","5214:description:252-292","5214:description:294-339","5214:description:341-454","5214:description:459-478","5214:description:480-505","5214:objective:1-88","5214:objective:90-133"},["minimumStage"]=2,["questID"]=5214,["sourceHash"]="6d67e2183e116922c108e2f979bc9e61f88e315f9f5f908adde1323eeb949ec4"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11033",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Smokey left Fras Siabi’s shop during the sack of Stratholme, remembering its owner’s vow to burn the stock rather than surrender it.",["title"]="Smokey LaRue"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5214:description:1-17","5214:description:19-40","5214:description:42-126","5214:description:128-247","5214:description:252-292","5214:description:294-339","5214:description:341-454","5214:description:459-478","5214:description:480-505","5214:objective:1-88","5214:objective:90-133"},["minimumStage"]=2,["questID"]=5214,["sourceHash"]="6d67e2183e116922c108e2f979bc9e61f88e315f9f5f908adde1323eeb949ec4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11033",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He hoped some of the prized tobacco survived, while admitting that Fras’s fate was only his own assumption.",["title"]="Smokey LaRue"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5216:description:1-120","5216:description:123-212","5216:description:217-296","5216:description:299-360","5216:description:363-502","5216:objective:1-97","5216:objective:100-156","5216:objective:159-272"},["minimumStage"]=2,["questID"]=5216,["sourceHash"]="d1a39948ca912cf468b48edf87c3ed8158e449f7518c2904d6cbfc034c23e68b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11053",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="MacDonnell sought poison samples from the Scourge cauldrons to develop a counteragent.",["title"]="High Priestess MacDonnell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5216:description:1-120","5216:description:123-212","5216:description:217-296","5216:description:299-360","5216:description:363-502","5216:objective:1-97","5216:objective:100-156","5216:objective:159-272"},["minimumStage"]=2,["questID"]=5216,["sourceHash"]="d1a39948ca912cf468b48edf87c3ed8158e449f7518c2904d6cbfc034c23e68b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11053",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She judged Felstone Field the most accessible first target because its troops were less experienced, but warned against underestimating them.",["title"]="High Priestess MacDonnell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5229:description:1-117","5229:description:120-209","5229:description:214-314","5229:description:317-371","5229:description:374-500","5229:objective:1-97","5229:objective:100-156","5229:objective:159-272"},["minimumStage"]=2,["questID"]=5229,["sourceHash"]="af536fde7e791b69a4357dbe506dd3622d498cce4e4401c61560ad76a5127be3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11055",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vandis sought cauldron toxin samples to study a counteragent against the plague.",["title"]="Shadow Priestess Vandis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5229:description:1-117","5229:description:120-209","5229:description:214-314","5229:description:317-371","5229:description:374-500","5229:objective:1-97","5229:objective:100-156","5229:objective:159-272"},["minimumStage"]=2,["questID"]=5229,["sourceHash"]="af536fde7e791b69a4357dbe506dd3622d498cce4e4401c61560ad76a5127be3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11055",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She recommended beginning at Felstone Field, where less-experienced Scourge troops might make access easier without making it safe.",["title"]="Shadow Priestess Vandis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5243:description:1-37","5243:description:39-138","5243:description:140-219","5243:description:224-329","5243:description:334-408","5243:description:413-472","5243:description:474-498","5243:objective:1-35","5243:objective:37-118","5243:objective:120-212"},["minimumStage"]=2,["questID"]=5243,["sourceHash"]="c7043eaae40131edf2d50bebcf53d4ae5086c0e2df56956d39274c6750e03ae6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11036",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Leonid regarded his own undeath as both an illness requiring treatment and an advantage in the Argent Dawn’s war against the Scourge.",["title"]="Leonid Barthalomew the Revered"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5243:description:1-37","5243:description:39-138","5243:description:140-219","5243:description:224-329","5243:description:334-408","5243:description:413-472","5243:description:474-498","5243:objective:1-35","5243:objective:37-118","5243:objective:120-212"},["minimumStage"]=2,["questID"]=5243,["sourceHash"]="c7043eaae40131edf2d50bebcf53d4ae5086c0e2df56956d39274c6750e03ae6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11036",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He dismissed praise for his sacrifices and sought practical help recovering the Dawn’s stored holy water from Stratholme.",["title"]="Leonid Barthalomew the Revered"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5251:description:1-59","5251:description:61-98","5251:description:100-162","5251:description:164-227","5251:description:232-256","5251:description:261-397","5251:description:399-437","5251:description:439-487","5251:objective:1-71","5251:objective:73-118"},["minimumStage"]=2,["questID"]=5251,["sourceHash"]="38924bf7a10d176e0059c8dc8893b2c168d557bb00dea788babfe9a68ffa492c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11039",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nicholas condemned the Scarlet Crusade’s zealotry and the innocents killed in the name of the Light.",["title"]="Duke Nicholas Zverenhoff"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5251:description:1-59","5251:description:61-98","5251:description:100-162","5251:description:164-227","5251:description:232-256","5251:description:261-397","5251:description:399-437","5251:description:439-487","5251:objective:1-71","5251:objective:73-118"},["minimumStage"]=2,["questID"]=5251,["sourceHash"]="38924bf7a10d176e0059c8dc8893b2c168d557bb00dea788babfe9a68ffa492c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11039",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Galford and the Crusade’s valued archives destroyed to strike at its knowledge and power in Stratholme.",["title"]="Duke Nicholas Zverenhoff"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5281:description:1-63","5281:description:65-201","5281:description:206-265","5281:description:270-290","5281:description:295-382","5281:description:384-396","5281:description:398-472","5281:objective:1-10","5281:objective:12-65"},["minimumStage"]=2,["questID"]=5281,["sourceHash"]="b04dca61a97fc7308eee4e8214f44a0c9fa71ab0a118143ffd40709f3beb9124"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11038",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alen sought help for Stratholme’s restless dead, including those who chose the city’s flames over becoming Scourge.",["title"]="Caretaker Alen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5281:description:1-63","5281:description:65-201","5281:description:206-265","5281:description:270-290","5281:description:295-382","5281:description:384-396","5281:description:398-472","5281:objective:1-10","5281:objective:12-65"},["minimumStage"]=2,["questID"]=5281,["sourceHash"]="b04dca61a97fc7308eee4e8214f44a0c9fa71ab0a118143ffd40709f3beb9124"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11038",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He trusted his associate Egan’s unusual work with souls and directed aid toward his experiments near Stratholme.",["title"]="Caretaker Alen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5282:description:1-140","5282:description:142-166","5282:description:168-298","5282:description:303-338","5282:description:340-390","5282:description:395-448","5282:description:450-466","5282:objective:1-70","5282:objective:72-180","5282:objective:185-226"},["minimumStage"]=2,["questID"]=5282,["sourceHash"]="1058cd61857a30c1747395182004366f46cfc9062481c4d3efeeca549c628d38"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11140",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hatred of the Scourge sustained Egan, but he rejected the Scarlet Crusade’s refusal to show compassion to innocent undead.",["title"]="Egan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5282:description:1-140","5282:description:142-166","5282:description:168-298","5282:description:303-338","5282:description:340-390","5282:description:395-448","5282:description:450-466","5282:objective:1-70","5282:objective:72-180","5282:objective:185-226"},["minimumStage"]=2,["questID"]=5282,["sourceHash"]="1058cd61857a30c1747395182004366f46cfc9062481c4d3efeeca549c628d38"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11140",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His blaster was intended to unchain Stratholme’s tortured ghosts and free their souls.",["title"]="Egan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5284:description:1-109","5284:description:111-219","5284:description:224-279","5284:description:284-493","5284:description:495-506","5284:objective:1-176"},["minimumStage"]=2,["questID"]=5284,["sourceHash"]="76e12db1752eaa20efa1d553939c65b7b7f92098024dc334739bab31bfee0798"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11146",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ironus praised weaponsmithing’s profit while frankly acknowledging the exhausting workload, aching back and ash-filled lungs it could bring.",["title"]="Ironus Coldsteel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5284:description:1-109","5284:description:111-219","5284:description:224-279","5284:description:284-493","5284:description:495-506","5284:objective:1-176"},["minimumStage"]=2,["questID"]=5284,["sourceHash"]="76e12db1752eaa20efa1d553939c65b7b7f92098024dc334739bab31bfee0798"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11146",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He tested prospective weaponsmiths through work that demonstrated their ability to supply high-quality arms to adventurers.",["title"]="Ironus Coldsteel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5321:description:1-110","5321:description:112-178","5321:description:183-188","5321:description:193-226","5321:description:228-306","5321:description:308-378","5321:description:383-459","5321:description:461-493","5321:objective:1-80"},["minimumStage"]=2,["questID"]=5321,["sourceHash"]="b8e6baee3c232cdd6589d86f87a960d7171b5c044eae19f0427045e6c3951bfc"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11218",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Since waking from the Emerald Dream, Kerlonian remained so sleepy that a roadside nap interrupted his journey to Maestra’s Post.",["title"]="Kerlonian Evershade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5321:description:1-110","5321:description:112-178","5321:description:183-188","5321:description:193-226","5321:description:228-306","5321:description:308-378","5321:description:383-459","5321:description:461-493","5321:objective:1-80"},["minimumStage"]=2,["questID"]=5321,["sourceHash"]="b8e6baee3c232cdd6589d86f87a960d7171b5c044eae19f0427045e6c3951bfc"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11218",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought Liladris Moonriver and entrusted an escort with his horn in case he fell asleep again.",["title"]="Kerlonian Evershade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5341:description:1-53","5341:description:55-128","5341:description:130-162","5341:description:167-269","5341:description:274-348","5341:description:350-446","5341:objective:1-64","5341:objective:66-194","5341:objective:196-251"},["minimumStage"]=2,["questID"]=5341,["sourceHash"]="7bb40fbb59e1f419467084ce83c1e5a74ef17ef04755102ed0cb2c553cb3cbb3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alexi and Weldon were the two remaining heirs competing for the Barov fortune’s deeds in Scholomance.",["title"]="Alexi Barov"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5341:description:1-53","5341:description:55-128","5341:description:130-162","5341:description:167-269","5341:description:274-348","5341:description:350-446","5341:objective:1-64","5341:objective:66-194","5341:objective:196-251"},["minimumStage"]=2,["questID"]=5341,["sourceHash"]="7bb40fbb59e1f419467084ce83c1e5a74ef17ef04755102ed0cb2c553cb3cbb3"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alexi bitterly accused his still-human brother of cowardice for fleeing the war and sought the deeds before Weldon could claim the inheritance.",["title"]="Alexi Barov"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5344:description:1-60","5344:description:62-82","5344:description:84-178","5344:description:183-201","5344:description:203-265","5344:description:270-339","5344:description:341-357","5344:description:359-387","5344:description:389-446","5344:objective:1-70","5344:objective:72-112","5344:objective:117-180"},["minimumStage"]=2,["questID"]=5344,["sourceHash"]="ff1813a053700d4443cf393a34ca5ed9ccc6c3d40c422582ef1a10f55ba898b8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11023",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Weldon wanted Alexi killed after recovering the deeds, fearing rival mercenaries might otherwise come for his own head.",["title"]="Weldon Barov"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5344:description:1-60","5344:description:62-82","5344:description:84-178","5344:description:183-201","5344:description:203-265","5344:description:270-339","5344:description:341-357","5344:description:359-387","5344:description:389-446","5344:objective:1-70","5344:objective:72-112","5344:objective:117-180"},["minimumStage"]=2,["questID"]=5344,["sourceHash"]="ff1813a053700d4443cf393a34ca5ed9ccc6c3d40c422582ef1a10f55ba898b8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11023",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He invoked noble upbringing while hiring another person to carry out the killing he would not undertake himself.",["title"]="Weldon Barov"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5384:description:1-15","5384:description:20-59","5384:description:64-86","5384:description:88-140","5384:description:145-196","5384:description:198-258","5384:description:263-290","5384:description:292-317","5384:description:319-356","5384:description:358-440","5384:description:445-507","5384:objective:1-54","5384:objective:56-118","5384:objective:120-162","5384:objective:167-203","5384:objective:205-248"},["minimumStage"]=2,["questID"]=5384,["sourceHash"]="0b083341a85d96b6e8f966efab9997347f87a4e0fcd74590a1a655b85a58bfc4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11216",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eva sought vengeance for Kirtonos’s innocent victims by turning the blood used to appease him into the lure for his destruction.",["title"]="Eva Sarkhoff"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5384:description:1-15","5384:description:20-59","5384:description:64-86","5384:description:88-140","5384:description:145-196","5384:description:198-258","5384:description:263-290","5384:description:292-317","5384:description:319-356","5384:description:358-440","5384:description:445-507","5384:objective:1-54","5384:objective:56-118","5384:objective:120-162","5384:objective:167-203","5384:objective:205-248"},["minimumStage"]=2,["questID"]=5384,["sourceHash"]="0b083341a85d96b6e8f966efab9997347f87a4e0fcd74590a1a655b85a58bfc4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11216",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She directed the Blood of Innocents to Scholomance’s porch brazier, trusting that Krastinov’s master could not resist it.",["title"]="Eva Sarkhoff"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5386:description:1-73","5386:description:75-139","5386:description:141-233","5386:description:235-240","5386:description:245-292","5386:description:294-381","5386:description:383-445","5386:objective:1-93"},["minimumStage"]=2,["questID"]=5386,["sourceHash"]="c1ad6818c17f0536ea3825224cb38dc0f291776a5967d0c23b28dfa549b6e238"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11259",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Centaur troubles kept Nataka from visiting Shadowprey for the Bloodbelly fish he particularly enjoyed.",["title"]="Nataka Longhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5386:description:1-73","5386:description:75-139","5386:description:141-233","5386:description:235-240","5386:description:245-292","5386:description:294-381","5386:description:383-445","5386:objective:1-93"},["minimumStage"]=2,["questID"]=5386,["sourceHash"]="c1ad6818c17f0536ea3825224cb38dc0f291776a5967d0c23b28dfa549b6e238"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11259",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He praised the village’s troll fishers and sent a traveler to Jinar’Zillen for the catch.",["title"]="Nataka Longhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5504:description:1-55","5504:description:58-90","5504:description:93-220","5504:description:225-362","5504:description:365-499","5504:objective:1-94"},["minimumStage"]=2,["questID"]=5504,["sourceHash"]="5e51a723c953dcfeaee36a1a436582c732f2256ee0b468f33575f5cd0e74bb60"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10856",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hasana administered access to the Argent Dawn’s prized magic-resistance mantles in exchange for valor tokens demonstrating continued service.",["title"]="Argent Quartermaster Hasana"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5507:description:1-55","5507:description:58-90","5507:description:93-220","5507:description:225-362","5507:description:365-499","5507:objective:1-101"},["minimumStage"]=2,["questID"]=5507,["sourceHash"]="525831a6cf95c29a2016ff769d333dd786fbc27d1b50ec989cb400b9a2f138b7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10857",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lightspark offered qualified Argent Dawn allies access to magical resistance mantles, asking valor tokens as a sign of dedication.",["title"]="Argent Quartermaster Lightspark"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5513:description:1-55","5513:description:58-90","5513:description:93-220","5513:description:225-362","5513:description:365-499","5513:objective:1-106"},["minimumStage"]=2,["questID"]=5513,["sourceHash"]="1550e5407e8b624b42efec2e38f52f34d16b2c667bf7320768f9d8abb814fa2a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11536",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Miranda handled the Dawn’s valued resistance mantles, whose shoulder application protected against different kinds of magic.",["title"]="Quartermaster Miranda Breechlock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5518:description:1-148","5518:description:151-195","5518:description:198-240","5518:description:245-257","5518:description:260-373","5518:description:376-424","5518:description:427-470","5518:description:473-497","5518:objective:1-98","5518:objective:101-160"},["minimumStage"]=2,["questID"]=5518,["sourceHash"]="060b8f2cac227c95b0d34550850ba8df9b632a0ce29e18204ffa2d793de80ced"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14338",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="During captivity Knot worked out a short-lived ogre disguise that might fool the Gordok long enough to pass Kromcrush without killing him.",["title"]="Knot Thimblejack"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5518:description:1-148","5518:description:151-195","5518:description:198-240","5518:description:245-257","5518:description:260-373","5518:description:376-424","5518:description:427-470","5518:description:473-497","5518:objective:1-98","5518:objective:101-160"},["minimumStage"]=2,["questID"]=5518,["sourceHash"]="060b8f2cac227c95b0d34550850ba8df9b632a0ce29e18204ffa2d793de80ced"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14338",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He needed materials to stabilize the suit, warning that even his best version would hold together for only a brief interval.",["title"]="Knot Thimblejack"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5541:description:1-54","5541:description:57-173","5541:description:178-183","5541:description:185-241","5541:description:244-326","5541:description:328-370","5541:description:375-426","5541:description:429-482","5541:objective:1-59"},["minimumStage"]=2,["questID"]=5541,["sourceHash"]="238360dbddbda193eac40ad5db0635589c747167416f9633b8435c5a0253f196"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1694",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Loslor sought a lost ammunition crate for Rumbleshot’s shop, where riflemen and mortar teams practiced and consumed a steady supply.",["title"]="Loslor Rudge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5541:description:1-54","5541:description:57-173","5541:description:178-183","5541:description:185-241","5541:description:244-326","5541:description:328-370","5541:description:375-426","5541:description:429-482","5541:objective:1-59"},["minimumStage"]=2,["questID"]=5541,["sourceHash"]="238360dbddbda193eac40ad5db0635589c747167416f9633b8435c5a0253f196"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-1694",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wendigo chased his courier from a camp near the Grizzled Den, leaving the shipment behind.",["title"]="Loslor Rudge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5545:description:1-36","5545:description:38-115","5545:description:117-233","5545:description:238-351","5545:description:353-432","5545:objective:1-63"},["minimumStage"]=2,["questID"]=5545,["sourceHash"]="cf6f7b96165dd1c428fd62ece39276aae4e588175642d0df308b4e68065935a7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10616",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wolves and bears drove Raelen’s workers away after they had cut and bundled the lumber, threatening an approaching deadline.",["title"]="Supervisor Raelen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5545:description:1-36","5545:description:38-115","5545:description:117-233","5545:description:238-351","5545:description:353-432","5545:objective:1-63"},["minimumStage"]=2,["questID"]=5545,["sourceHash"]="cf6f7b96165dd1c428fd62ece39276aae4e588175642d0df308b4e68065935a7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10616",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He had already asked Rainer to clear the beasts but still needed the abandoned wood carried back to fill his order.",["title"]="Supervisor Raelen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5561:description:1-76","5561:description:79-149","5561:description:152-310","5561:description:315-453","5561:description:456-503","5561:objective:1-101"},["minimumStage"]=2,["questID"]=5561,["sourceHash"]="fd0ffb26e35564d8eb02e749a49fa71dacdda957ca89f86c57b9c777286abd32"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11596",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Smeed developed a kombobulator that rejuvenated and controlled old kodos, then entered a partnership with caravan owner Cork and Rigger.",["title"]="Smeed Scrabblescrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5561:description:1-76","5561:description:79-149","5561:description:152-310","5561:description:315-453","5561:description:456-503","5561:objective:1-101"},["minimumStage"]=2,["questID"]=5561,["sourceHash"]="fd0ffb26e35564d8eb02e749a49fa71dacdda957ca89f86c57b9c777286abd32"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11596",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted aged beasts brought in for the caravan’s use and took pride in rivaling Bibbly’s supposed monopoly on Desolace profits.",["title"]="Smeed Scrabblescrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5601:description:1-147","5601:description:150-184","5601:description:187-247","5601:description:252-370","5601:description:373-415","5601:description:418-473","5601:description:478-501","5601:objective:1-35"},["minimumStage"]=2,["questID"]=5601,["sourceHash"]="9b5e243e11ad720c60904cb4b069b446064f39ea4f84961f6a4db7073d77a686"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11629",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jessica escaped Lordaeron before the Scourge devastated her homeland and feared the rest of her family died at Darrowshire.",["title"]="Jessica Redpath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5601:description:1-147","5601:description:150-184","5601:description:187-247","5601:description:252-370","5601:description:373-415","5601:description:418-473","5601:description:478-501","5601:objective:1-35"},["minimumStage"]=2,["questID"]=5601,["sourceHash"]="9b5e243e11ad720c60904cb4b069b446064f39ea4f84961f6a4db7073d77a686"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11629",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She especially longed for her younger sister Pamela and asked for a search rather than accept the family’s deaths without news.",["title"]="Jessica Redpath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5621:description:1-21","5621:description:23-142","5621:description:144-198","5621:description:200-217","5621:description:222-300","5621:description:302-370","5621:description:372-426","5621:objective:1-67","5621:objective:69-163"},["minimumStage"]=2,["questID"]=5621,["sourceHash"]="f6f2b00030915ece21f595bd25d627ddae533ae860c59e45abe41538b454ceb2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3600",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Laurna trained Elune’s priestly students and sent one to tend an injured Sentinel because she was needed by the others.",["title"]="Laurna Morninglight"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5621:description:1-21","5621:description:23-142","5621:description:144-198","5621:description:200-217","5621:description:222-300","5621:description:302-370","5621:description:372-426","5621:objective:1-67","5621:objective:69-163"},["minimumStage"]=2,["questID"]=5621,["sourceHash"]="f6f2b00030915ece21f595bd25d627ddae533ae860c59e45abe41538b454ceb2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3600",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted Shaya’s wounds healed and her body fortified against further danger during patrol.",["title"]="Laurna Morninglight"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5624:description:1-85","5624:description:87-242","5624:description:247-284","5624:description:286-368","5624:description:370-389","5624:description:391-443","5624:description:445-511","5624:objective:1-66","5624:objective:68-161"},["minimumStage"]=2,["questID"]=5624,["sourceHash"]="8e464fe0696a2f7d014c5f798b504752845771706bfc19f85b6201afdb659d08"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-377",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Josetta tested young priests before their first church-approved robes, treating service as proof of readiness.",["title"]="Priestess Josetta"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5624:description:1-85","5624:description:87-242","5624:description:247-284","5624:description:286-368","5624:description:370-389","5624:description:391-443","5624:description:445-511","5624:objective:1-66","5624:objective:68-161"},["minimumStage"]=2,["questID"]=5624,["sourceHash"]="8e464fe0696a2f7d014c5f798b504752845771706bfc19f85b6201afdb659d08"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-377",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="News of the injured guard Roberts replaced her usual challenge with a real need for healing and protection.",["title"]="Priestess Josetta"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5625:description:1-139","5625:description:141-199","5625:description:201-320","5625:description:325-411","5625:description:413-429","5625:objective:1-69","5625:objective:71-157"},["minimumStage"]=2,["questID"]=5625,["sourceHash"]="43900f8217e8090f87f49c0bca9e9528084400ef2c7ff5a0fd7deb1c34ca22d8"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-1226",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maxan judged a priest’s readiness for church robes through practical aid to an injured mountaineer rather than a separate formal test.",["title"]="Maxan Anvol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5625:description:1-139","5625:description:141-199","5625:description:201-320","5625:description:325-411","5625:description:413-429","5625:objective:1-69","5625:objective:71-157"},["minimumStage"]=2,["questID"]=5625,["sourceHash"]="43900f8217e8090f87f49c0bca9e9528084400ef2c7ff5a0fd7deb1c34ca22d8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1226",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A Kharanos citizen’s report sent his pupil to heal and fortify Dolf south of town.",["title"]="Maxan Anvol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5644:description:1-32","5644:description:34-128","5644:description:130-210","5644:description:215-322","5644:description:324-336","5644:description:338-362","5644:description:367-410","5644:description:412-455","5644:objective:1-38"},["minimumStage"]=2,["questID"]=5644,["sourceHash"]="8fd5ad476f4ae641c57e4ec4673ad19e7b992a25f93c3692bc9ae3f3a5f027e2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5994",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zayus sent advanced pupils back to Aelthalyste for lessons he said only she could teach.",["title"]="Zayus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5644:description:1-32","5644:description:34-128","5644:description:130-210","5644:description:215-322","5644:description:324-336","5644:description:338-362","5644:description:367-410","5644:description:412-455","5644:objective:1-38"},["minimumStage"]=2,["questID"]=5644,["sourceHash"]="8fd5ad476f4ae641c57e4ec4673ad19e7b992a25f93c3692bc9ae3f3a5f027e2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5994",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He remembered his own early discovery of divine power while deliberately leaving the next lesson a surprise.",["title"]="Zayus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5647:description:1-32","5647:description:34-65","5647:description:67-237","5647:description:239-284","5647:description:289-327","5647:description:329-409","5647:description:411-439","5647:description:441-469","5647:objective:1-40"},["minimumStage"]=2,["questID"]=5647,["sourceHash"]="83709f45aa8d748d806f462c9bd5f1f4d8e77df35d9aa91be3645cd3d08ab5dd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4092",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lariia praised her allies’ growing confidence and search for their origins, taking pride in their progress.",["title"]="Lariia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5647:description:1-32","5647:description:34-65","5647:description:67-237","5647:description:239-284","5647:description:289-327","5647:description:329-409","5647:description:411-439","5647:description:441-469","5647:objective:1-40"},["minimumStage"]=2,["questID"]=5647,["sourceHash"]="83709f45aa8d748d806f462c9bd5f1f4d8e77df35d9aa91be3645cd3d08ab5dd"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4092",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She relayed Ironforge’s summons to High Priest Rohan and wished the traveler Elune’s guidance.",["title"]="Lariia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5648:description:1-37","5648:description:39-147","5648:description:149-227","5648:description:229-318","5648:description:323-412","5648:objective:1-65","5648:objective:67-151"},["minimumStage"]=2,["questID"]=5648,["sourceHash"]="de3347a986b3e8f229826c5b2ee5901e4e763ba66ca89f958c8285979795f2cd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3706",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tai’jin tested priestly readiness by sending aid to Kor’ja, a grunt hurt fighting Proudmoore’s remaining troops near Razor Hill.",["title"]="Tai'jin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5648:description:1-37","5648:description:39-147","5648:description:149-227","5648:description:229-318","5648:description:323-412","5648:objective:1-65","5648:objective:67-151"},["minimumStage"]=2,["questID"]=5648,["sourceHash"]="de3347a986b3e8f229826c5b2ee5901e4e763ba66ca89f958c8285979795f2cd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3706",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her lesson joined healing with the ancestors’ blessing so the wounded guard would be stronger against later danger.",["title"]="Tai'jin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5649:description:1-9","5649:description:11-69","5649:description:71-128","5649:description:130-155","5649:description:157-272","5649:description:277-342","5649:description:344-380","5649:description:382-417","5649:description:419-446","5649:objective:1-28"},["minimumStage"]=2,["questID"]=5649,["sourceHash"]="c527d8a8ca5925eb2318ae363de493e420b46d40fa9d787d8a7c01f806467683"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-3707",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ken’jai valued the Horde’s loyalty and teaching about honor while believing troll traditions could still be practiced quietly when orcs disapproved.",["title"]="Ken'jai"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5649:description:1-9","5649:description:11-69","5649:description:71-128","5649:description:130-155","5649:description:157-272","5649:description:277-342","5649:description:344-380","5649:description:382-417","5649:description:419-446","5649:objective:1-28"},["minimumStage"]=2,["questID"]=5649,["sourceHash"]="c527d8a8ca5925eb2318ae363de493e420b46d40fa9d787d8a7c01f806467683"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-3707",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent students to Tai’jin to learn the tribe’s history and spiritual ways.",["title"]="Ken'jai"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5650:description:1-77","5650:description:79-148","5650:description:150-162","5650:description:164-226","5650:description:228-263","5650:description:268-329","5650:description:331-395","5650:description:397-461","5650:description:463-510","5650:objective:1-67","5650:objective:69-158"},["minimumStage"]=2,["questID"]=5650,["sourceHash"]="7c9f8099a7ce0423443ca2afec7516384e84f22a6128b7a9eb585c1b3ff76db2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2129",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Beryl taught that mastery of darkness also required understanding healing and the Light.",["title"]="Dark Cleric Beryl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5650:description:1-77","5650:description:79-148","5650:description:150-162","5650:description:164-226","5650:description:228-263","5650:description:268-329","5650:description:331-395","5650:description:397-461","5650:description:463-510","5650:objective:1-67","5650:objective:69-158"},["minimumStage"]=2,["questID"]=5650,["sourceHash"]="7c9f8099a7ce0423443ca2afec7516384e84f22a6128b7a9eb585c1b3ff76db2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2129",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She made healing and fortifying Deathguard Kel, wounded after defending against gnolls, a test of that balance.",["title"]="Dark Cleric Beryl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5651:description:1-122","5651:description:124-238","5651:description:240-282","5651:description:284-303","5651:description:305-402","5651:description:404-428","5651:description:433-500","5651:objective:1-46"},["minimumStage"]=2,["questID"]=5651,["sourceHash"]="fc24988279d7e72e46b81aeab7fd65a31caf86f8cb52d760ff4eaca6700d3724"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-2123",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Duesten taught discretion in using both light and darkness while remembering that corruption and abandonment had shaped the Forsaken.",["title"]="Dark Cleric Duesten"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5651:description:1-122","5651:description:124-238","5651:description:240-282","5651:description:284-303","5651:description:305-402","5651:description:404-428","5651:description:433-500","5651:objective:1-46"},["minimumStage"]=2,["questID"]=5651,["sourceHash"]="fc24988279d7e72e46b81aeab7fd65a31caf86f8cb52d760ff4eaca6700d3724"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-2123",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed further instruction to Beryl in Brill.",["title"]="Dark Cleric Duesten"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5676:description:1-53","5676:description:55-114","5676:description:116-207","5676:description:212-337","5676:description:342-416","5676:description:418-465","5676:objective:1-45"},["minimumStage"]=2,["questID"]=5676,["sourceHash"]="68414dbb400e7870ef197fb08e31cca2e650c96b0b06079fb06d712a8e42a73e"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-5489",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Joshua distrusted arcane magic even when described as divinely inspired, but would not betray the alliance between his people and the pupil’s.",["title"]="Brother Joshua"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5676:description:1-53","5676:description:55-114","5676:description:116-207","5676:description:212-337","5676:description:342-416","5676:description:418-465","5676:objective:1-45"},["minimumStage"]=2,["questID"]=5676,["sourceHash"]="68414dbb400e7870ef197fb08e31cca2e650c96b0b06079fb06d712a8e42a73e"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-5489",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He set those reservations aside to send a summoned student back to Laurena at Stormwind’s cathedral.",["title"]="Brother Joshua"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5713:description:1-114","5713:description:116-181","5713:description:183-247","5713:description:252-313","5713:description:315-355","5713:description:360-503","5713:objective:1-80"},["minimumStage"]=2,["questID"]=5713,["sourceHash"]="c614923b4bf5c38e55966786f736ea2cd0deefc6a1457ce08765c6b23278f445"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11711",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marosh’s furbolg trackers poisoned Aynasha while she carried an important message toward Auberdine.",["title"]="Sentinel Aynasha"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5713:description:1-114","5713:description:116-181","5713:description:183-247","5713:description:252-313","5713:description:315-355","5713:description:360-503","5713:objective:1-80"},["minimumStage"]=2,["questID"]=5713,["sourceHash"]="c614923b4bf5c38e55966786f736ea2cd0deefc6a1457ce08765c6b23278f445"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11711",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Barely able to stand, she could prepare an antidote but needed protection long enough to use it, offering what help her bow could provide.",["title"]="Sentinel Aynasha"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5722:description:1-76","5722:description:78-227","5722:description:229-349","5722:description:354-448","5722:description:453-508","5722:objective:1-90"},["minimumStage"]=2,["questID"]=5722,["sourceHash"]="35b9ef28b43ac2b884ef28e14f08fca22cc5a579313f3389cba484750594e5e2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11833",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rahauro relayed Magatha’s interest in Maur Grimtotem’s discovery inside Ragefire Chasm.",["title"]="Rahauro"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5722:description:1-76","5722:description:78-227","5722:description:229-349","5722:description:354-448","5722:description:453-508","5722:objective:1-90"},["minimumStage"]=2,["questID"]=5722,["sourceHash"]="35b9ef28b43ac2b884ef28e14f08fca22cc5a579313f3389cba484750594e5e2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11833",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Maur’s body and any evidence of the find located after the servant failed to return from speaking with the troggs.",["title"]="Rahauro"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5763:description:1-36","5763:description:39-92","5763:description:95-174","5763:description:177-226","5763:description:231-333","5763:description:336-352","5763:description:357-395","5763:description:398-424","5763:description:427-494","5763:objective:1-60"},["minimumStage"]=2,["questID"]=5763,["sourceHash"]="88afd1b0466e39787969d625231e3fc115aa6d85545e4dfd021f4775cc14ea27"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11877",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Roon hunted beside Hemet in Desolace, admiring the dwarf’s uncanny rifle skills despite the enmity between their peoples.",["title"]="Roon Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5763:description:1-36","5763:description:39-92","5763:description:95-174","5763:description:177-226","5763:description:231-333","5763:description:336-352","5763:description:357-395","5763:description:398-424","5763:description:427-494","5763:objective:1-60"},["minimumStage"]=2,["questID"]=5763,["sourceHash"]="88afd1b0466e39787969d625231e3fc115aa6d85545e4dfd021f4775cc14ea27"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11877",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent a kodo horn to Stranglethorn as a personal gift and invitation to renew their shared hunts.",["title"]="Roon Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5821:description:1-85","5821:description:87-167","5821:description:169-206","5821:description:211-306","5821:description:311-469","5821:description:471-503","5821:objective:1-60","5821:objective:62-117"},["minimumStage"]=2,["questID"]=5821,["sourceHash"]="9af61378206edafe3f39ecc65188d1707111b47069bc36c352558b6b394e751d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11625",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cork treated centaur war drums as a reason to halt the caravan rather than risk lives for business.",["title"]="Cork Gizelton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5821:description:1-85","5821:description:87-167","5821:description:169-206","5821:description:211-306","5821:description:311-469","5821:description:471-503","5821:objective:1-60","5821:objective:62-117"},["minimumStage"]=2,["questID"]=5821,["sourceHash"]="9af61378206edafe3f39ecc65188d1707111b47069bc36c352558b6b394e751d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11625",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He traveled with Rigger and arranged escort payment through their partner Smeed.",["title"]="Cork Gizelton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5848:description:1-15","5848:description:17-93","5848:description:98-184","5848:description:186-241","5848:description:246-369","5848:description:371-448","5848:description:453-485","5848:objective:1-62","5848:objective:64-215","5848:objective:220-258"},["minimumStage"]=2,["questID"]=5848,["sourceHash"]="fdf2906a551283f98f1c0c9c11fd8adc2f8c45137eb56bb57faa5ef665ce2a4e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11936",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Renfray hid her masterwork after Tirion’s trial, covering it beneath an image of the twin moons in the old barracks.",["title"]="Artist Renfray"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5848:description:1-15","5848:description:17-93","5848:description:98-184","5848:description:186-241","5848:description:246-369","5848:description:371-448","5848:description:453-485","5848:objective:1-62","5848:objective:64-215","5848:objective:220-258"},["minimumStage"]=2,["questID"]=5848,["sourceHash"]="fdf2906a551283f98f1c0c9c11fd8adc2f8c45137eb56bb57faa5ef665ce2a4e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11936",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted the original work uncovered inside what had become Stratholme’s Scarlet Bastion.",["title"]="Artist Renfray"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5881:description:1-47","5881:description:49-109","5881:description:114-237","5881:description:239-381","5881:description:383-452","5881:objective:1-92"},["minimumStage"]=2,["questID"]=5881,["sourceHash"]="2029a965f0a15df78d07d23b7185f74a5621b7b5ea7a25496cf12a8ae4531924"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11860",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maggran arranged reserve relief for Horde troops so they could return to their families.",["title"]="Maggran Earthbinder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5881:description:1-47","5881:description:49-109","5881:description:114-237","5881:description:239-381","5881:description:383-452","5881:objective:1-92"},["minimumStage"]=2,["questID"]=5881,["sourceHash"]="2029a965f0a15df78d07d23b7185f74a5621b7b5ea7a25496cf12a8ae4531924"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11860",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His letter told Grish at the Great Lift that the family visit requested long before could finally begin.",["title"]="Maggran Earthbinder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5893:description:1-220","5893:description:223-308","5893:description:313-347","5893:description:350-402","5893:description:405-488","5893:objective:1-72"},["minimumStage"]=2,["questID"]=5893,["sourceHash"]="87da022e77b12902ba2a386d1ae3e546ae3461fca6ab8e573dff11ca4b0ad1d9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12097",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The quartermaster could not always spare defenders for Coldtooth Mine as fighting with the Stormpikes intensified.",["title"]="Frostwolf Quartermaster"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5893:description:1-220","5893:description:223-308","5893:description:313-347","5893:description:350-402","5893:description:405-488","5893:objective:1-72"},["minimumStage"]=2,["questID"]=5893,["sourceHash"]="87da022e77b12902ba2a386d1ae3e546ae3461fca6ab8e573dff11ca4b0ad1d9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12097",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Supplies remained necessary even when Alliance forces or underground creatures controlled the mine, prompting risky retrievals.",["title"]="Frostwolf Quartermaster"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5901:description:1-105","5901:description:107-239","5901:description:241-261","5901:description:266-331","5901:description:333-404","5901:description:406-436","5901:objective:1-71","5901:objective:73-177"},["minimumStage"]=2,["questID"]=5901,["sourceHash"]="1a1c9dfaf0c421abbb39c250425c9455738741a7c13e0368a03b91c9d0f26006"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11615",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mickey sought to cripple the Scarlet Crusade’s building and defense efforts by depriving it of lumber.",["title"]="Mickey Levine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5901:description:1-105","5901:description:107-239","5901:description:241-261","5901:description:266-331","5901:description:333-404","5901:description:406-436","5901:objective:1-71","5901:objective:73-177"},["minimumStage"]=2,["questID"]=5901,["sourceHash"]="1a1c9dfaf0c421abbb39c250425c9455738741a7c13e0368a03b91c9d0f26006"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11615",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His proposed attack used Plaguewood termites carried to the mill rather than another direct assault.",["title"]="Mickey Levine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5903:description:1-91","5903:description:93-163","5903:description:168-283","5903:description:288-401","5903:description:403-503","5903:objective:1-71","5903:objective:73-186"},["minimumStage"]=2,["questID"]=5903,["sourceHash"]="2d25a4803146dd750ade01d72050e0c6730aa37b14fd07bf1085a5d8d66e2018"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11616",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nathaniel’s repeated attempts to drive the Crusade out by force had failed.",["title"]="Nathaniel Dumah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5903:description:1-91","5903:description:93-163","5903:description:168-283","5903:description:288-401","5903:description:403-503","5903:objective:1-71","5903:objective:73-186"},["minimumStage"]=2,["questID"]=5903,["sourceHash"]="2d25a4803146dd750ade01d72050e0c6730aa37b14fd07bf1085a5d8d66e2018"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11616",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He turned to infestation, seeking especially destructive termites that had survived both plague and Scourge in Plaguewood.",["title"]="Nathaniel Dumah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5923:description:1-20","5923:description:25-129","5923:description:132-241","5923:description:244-377","5923:description:382-480","5923:objective:1-68"},["minimumStage"]=2,["questID"]=5923,["sourceHash"]="93e4484ac3e97ad75ba8d203307b9403989caade446e957c72a75238875ccd83"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4218",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Denatharion relayed Mathrengyl Bearwalker’s personal summons, praising the Arch Druid’s assistant as an especially wise guide.",["title"]="Denatharion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5924:description:1-20","5924:description:25-129","5924:description:132-241","5924:description:244-377","5924:description:382-480","5924:objective:1-68"},["minimumStage"]=2,["questID"]=5924,["sourceHash"]="5e437d0596ec599dde33f839091ebfb0553637a231f76c865ad3a8eefc8a8afe"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5505",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theridran passed on the invitation to train personally with Mathrengyl in the Cenarion Enclave.",["title"]="Theridran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5925:description:1-20","5925:description:25-129","5925:description:132-241","5925:description:244-377","5925:description:382-480","5925:objective:1-68"},["minimumStage"]=2,["questID"]=5925,["sourceHash"]="796f39cf8cc9fd4e0c754c6c2e167e96435430c7b199a7f2fa68a7b3dfe4ab54"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3602",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kal relayed Mathrengyl’s invitation to personal druid training in the Cenarion Enclave.",["title"]="Kal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5928:description:1-20","5928:description:25-123","5928:description:126-235","5928:description:238-352","5928:description:357-445","5928:objective:1-62"},["minimumStage"]=2,["questID"]=5928,["sourceHash"]="f2fa352cfb4c6e60af6a105df68b62f166487000ae9e884f5f86e68cb41c4124"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3064",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gennia recommended Turak, one of the Arch Druid’s assistants, as a wise and patient teacher on Elder Rise.",["title"]="Gennia Runetotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5943:description:1-27","5943:description:29-70","5943:description:72-179","5943:description:184-212","5943:description:214-289","5943:description:291-346","5943:description:348-457","5943:objective:1-51","5943:objective:53-108"},["minimumStage"]=2,["questID"]=5943,["sourceHash"]="6455b4e11d5f9668b161f877c6df10335a861ad0e0da9f3f4e217f79435114bb"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11626",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rigger and Cork founded their caravan in pursuit of profit before discovering how dangerous its route could be.",["title"]="Rigger Gizelton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5943:description:1-27","5943:description:29-70","5943:description:72-179","5943:description:184-212","5943:description:214-289","5943:description:291-346","5943:description:348-457","5943:objective:1-51","5943:objective:53-108"},["minimumStage"]=2,["questID"]=5943,["sourceHash"]="6455b4e11d5f9668b161f877c6df10335a861ad0e0da9f3f4e217f79435114bb"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11626",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Demons at Mannoroc usually ignored the caravan, but frightened kodos led Rigger to seek paid protection for that crossing.",["title"]="Rigger Gizelton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5944:description:1-56","5944:description:58-132","5944:description:134-243","5944:description:248-271","5944:description:273-309","5944:description:311-371","5944:description:373-414","5944:description:416-460","5944:description:465-492","5944:description:497-511","5944:objective:1-41"},["minimumStage"]=2,["questID"]=5944,["sourceHash"]="e103e67caaf6a3b7ccdf3498990073c50032a82d8296667bb6cf841a2364922f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1842",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Taelan felt he had been the Grand Crusader’s puppet and no longer wished to accept what the Scarlet Crusade had become.",["title"]="Highlord Taelan Fordring"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5944:description:1-56","5944:description:58-132","5944:description:134-243","5944:description:248-271","5944:description:273-309","5944:description:311-371","5944:description:373-414","5944:description:416-460","5944:description:465-492","5944:description:497-511","5944:objective:1-41"},["minimumStage"]=2,["questID"]=5944,["sourceHash"]="e103e67caaf6a3b7ccdf3498990073c50032a82d8296667bb6cf841a2364922f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1842",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dreams of fighting beside his father sustained him, and he longed to turn that imagined reunion into a real one.",["title"]="Highlord Taelan Fordring"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5961:description:1-64","5961:description:66-122","5961:description:124-172","5961:description:177-252","5961:description:254-310","5961:description:315-354","5961:description:356-489","5961:objective:1-60","5961:objective:62-119"},["minimumStage"]=2,["questID"]=5961,["sourceHash"]="31886a1abb978ba70fa7b2167134f27cc58fa941091fc356bb5da65e3c3ad82f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-10181",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sylvanas praised Nathanos as one of her earliest and most dedicated champions, directing proven recruits to the Blightcaller at Marris Stead.",["title"]="Lady Sylvanas Windrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6004:description:1-88","6004:description:90-174","6004:description:176-288","6004:description:293-344","6004:description:346-417","6004:description:419-492","6004:objective:1-140"},["minimumStage"]=2,["questID"]=6004,["sourceHash"]="76cb7e9f03df32a30c09fce9ccc5d42db93aa19c4aaf81fa27481ba5ad48db4e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11610",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kirsta scouted Hearthglen’s defenses and conducted attacks under orders from Alliance interests she did not consider it her place to question.",["title"]="Kirsta Deepshadow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6004:description:1-88","6004:description:90-174","6004:description:176-288","6004:description:293-344","6004:description:346-417","6004:description:419-492","6004:objective:1-140"},["minimumStage"]=2,["questID"]=6004,["sourceHash"]="76cb7e9f03df32a30c09fce9ccc5d42db93aa19c4aaf81fa27481ba5ad48db4e"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11610",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Injuries and exhaustion forced her to rest before completing the mission, leading her to hire help against the nearby camp.",["title"]="Kirsta Deepshadow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6028:description:1-96","6028:description:99-194","6028:description:197-359","6028:description:364-488","6028:objective:1-95"},["minimumStage"]=2,["questID"]=6028,["sourceHash"]="7de5a8cb3f80f5bb3a807b2f19891f5a8f5d799dd2b0b6cbf4f9cfa56e64abb7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10431",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gregor represented Argent Dawn interests to Everlook’s local government.",["title"]="Gregor Greystone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6028:description:1-96","6028:description:99-194","6028:description:197-359","6028:description:364-488","6028:objective:1-95"},["minimumStage"]=2,["questID"]=6028,["sourceHash"]="7de5a8cb3f80f5bb3a807b2f19891f5a8f5d799dd2b0b6cbf4f9cfa56e64abb7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10431",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought a reliable courier for his progress report to Argent Officer Pureheart and offered the delivery as an introduction to further service.",["title"]="Gregor Greystone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6061:description:1-100","6061:description:102-214","6061:description:219-314","6061:description:316-375","6061:description:377-433","6061:description:435-503","6061:objective:1-49","6061:objective:51-137"},["minimumStage"]=2,["questID"]=6061,["sourceHash"]="55dab6d51df7c5d8dd5384a684273f2241df38f89fed3ea596eba32fbb06f404"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-3065",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yaw taught that besting powerful beasts brought hunters closer to the Earthmother through their spirits, while taming expressed unity with surrounding nature.",["title"]="Yaw Sharpmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6061:description:1-100","6061:description:102-214","6061:description:219-314","6061:description:316-375","6061:description:377-433","6061:description:435-503","6061:objective:1-49","6061:objective:51-137"},["minimumStage"]=2,["questID"]=6061,["sourceHash"]="55dab6d51df7c5d8dd5384a684273f2241df38f89fed3ea596eba32fbb06f404"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3065",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He began practical taming lessons with an adult plainstrider before allowing a pupil to choose a lasting companion.",["title"]="Yaw Sharpmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6062:description:1-64","6062:description:66-172","6062:description:177-287","6062:description:292-378","6062:description:380-423","6062:description:425-501","6062:objective:1-47","6062:objective:49-121"},["minimumStage"]=2,["questID"]=6062,["sourceHash"]="5370725553887c15ec3cb6dd9bd2f319593261c448236e99a92ba489df82cb8f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3171",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thotar emphasized determined control of a creature’s natural strength as a hunter’s skill.",["title"]="Thotar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6062:description:1-64","6062:description:66-172","6062:description:177-287","6062:description:292-378","6062:description:380-423","6062:description:425-501","6062:objective:1-47","6062:objective:49-121"},["minimumStage"]=2,["questID"]=6062,["sourceHash"]="5370725553887c15ec3cb6dd9bd2f319593261c448236e99a92ba489df82cb8f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3171",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He used a dire mottled boar near Razor Hill as the first practical test of taming and fighting beside a beast.",["title"]="Thotar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6063:description:1-83","6063:description:85-242","6063:description:247-364","6063:description:369-411","6063:description:413-463","6063:description:465-510","6063:objective:1-44","6063:objective:46-117"},["minimumStage"]=2,["questID"]=6063,["sourceHash"]="709ee7b1ecb2b197ee5356b5d657855d5f106a7d9eb300f33e2a09b4c539b45d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3601",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dazalar taught that nature was stronger than the hunter and deserved respect rather than submission to personal desire.",["title"]="Dazalar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6063:description:1-83","6063:description:85-242","6063:description:247-364","6063:description:369-411","6063:description:413-463","6063:description:465-510","6063:objective:1-44","6063:objective:46-117"},["minimumStage"]=2,["questID"]=6063,["sourceHash"]="709ee7b1ecb2b197ee5356b5d657855d5f106a7d9eb300f33e2a09b4c539b45d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3601",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He tested that understanding through taming and working beside a webwood lurker.",["title"]="Dazalar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6064:description:1-22","6064:description:24-87","6064:description:92-115","6064:description:117-254","6064:description:256-332","6064:description:337-433","6064:description:435-497","6064:objective:1-45","6064:objective:47-125"},["minimumStage"]=2,["questID"]=6064,["sourceHash"]="f6a6cf16526f95fdf0aa7515d7ef36070484d83c0f674f3acc2f69d6c1cad7d1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-1231",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grif valued good hunting equipment but considered trying different creatures the best way to discover a suitable companion.",["title"]="Grif Wildheart"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6064:description:1-22","6064:description:24-87","6064:description:92-115","6064:description:117-254","6064:description:256-332","6064:description:337-433","6064:description:435-497","6064:objective:1-45","6064:objective:47-125"},["minimumStage"]=2,["questID"]=6064,["sourceHash"]="f6a6cf16526f95fdf0aa7515d7ef36070484d83c0f674f3acc2f69d6c1cad7d1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-1231",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He began the hands-on lesson with a large crag boar and a taming rod.",["title"]="Grif Wildheart"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6143:description:1-39","6143:description:41-139","6143:description:141-246","6143:description:251-311","6143:description:316-399","6143:description:401-475","6143:objective:1-136"},["minimumStage"]=2,["questID"]=6143,["sourceHash"]="132cd49328fd3a129343296f97a72ad581cb78e821c08460480db7bde757dd78"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-12340",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Naga attacked Drulzegar’s fishing crew near Ranazjar Isle, leaving him the sole survivor.",["title"]="Drulzegar Skraghook"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6143:description:1-39","6143:description:41-139","6143:description:141-246","6143:description:251-311","6143:description:316-399","6143:description:401-475","6143:objective:1-136"},["minimumStage"]=2,["questID"]=6143,["sourceHash"]="132cd49328fd3a129343296f97a72ad581cb78e821c08460480db7bde757dd78"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12340",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Survivor’s guilt and grief replaced his old fishing life with a desire for vengeance against the attackers.",["title"]="Drulzegar Skraghook"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6162:description:1-124","6162:description:129-324","6162:description:329-362","6162:description:364-403","6162:description:405-445","6162:description:447-472","6162:objective:1-81"},["minimumStage"]=2,["questID"]=6162,["sourceHash"]="348cbfef3c3060664a5fc4e0f2361ef81d5f71905df939c190140a158c5184ff"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9620",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dreka’Sur’s husband fought corruption in Felwood for their clan and last wrote of joining a druid against Overlord Ror.",["title"]="Dreka'Sur"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6162:description:1-124","6162:description:129-324","6162:description:329-362","6162:description:364-403","6162:description:405-445","6162:description:447-472","6162:objective:1-81"},["minimumStage"]=2,["questID"]=6162,["sourceHash"]="348cbfef3c3060664a5fc4e0f2361ef81d5f71905df939c190140a158c5184ff"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9620",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Neither companion was heard from again; she blamed Ror for leaving her a widow and wanted his clawed hand as vengeance.",["title"]="Dreka'Sur"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6181:description:1-119","6181:description:122-146","6181:description:149-208","6181:description:213-276","6181:description:279-305","6181:description:310-374","6181:description:377-457","6181:objective:1-45"},["minimumStage"]=2,["questID"]=6181,["sourceHash"]="cff7cd07705023766536a44d02da731761c26b2bb05f81ceba5944c0c9eb5de7"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-491",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lewis relied on armor dealer Osric Strang as a personal supply contact despite receiving little direct aid from Stormwind.",["title"]="Quartermaster Lewis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6181:description:1-119","6181:description:122-146","6181:description:149-208","6181:description:213-276","6181:description:279-305","6181:description:310-374","6181:description:377-457","6181:objective:1-45"},["minimumStage"]=2,["questID"]=6181,["sourceHash"]="cff7cd07705023766536a44d02da731761c26b2bb05f81ceba5944c0c9eb5de7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-491",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dwindling armor stocks prompted an urgent message to Osric’s Old Town shop, sent by gryphon through Thor.",["title"]="Quartermaster Lewis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6182:description:1-65","6182:description:67-139","6182:description:144-241","6182:description:243-353","6182:description:358-445","6182:description:447-468","6182:description:470-509","6182:objective:1-46","6182:objective:48-74"},["minimumStage"]=2,["questID"]=6182,["sourceHash"]="9934e58eeae84aa6c7fec6a331721b5e9f06c12ab4bc8ba96987707c00737f9f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1748",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bolvar recalled Nathanos as the first and last human ranger lord and Sylvanas’s pupil, presumed dead in Lordaeron’s defense without a recovered body.",["title"]="Highlord Bolvar Fordragon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6182:description:1-65","6182:description:67-139","6182:description:144-241","6182:description:243-353","6182:description:358-445","6182:description:447-468","6182:description:470-509","6182:objective:1-46","6182:objective:48-74"},["minimumStage"]=2,["questID"]=6182,["sourceHash"]="9934e58eeae84aa6c7fec6a331721b5e9f06c12ab4bc8ba96987707c00737f9f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1748",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="New information from Shaw’s investigation prompted him to send a trusted operative to the Old Town barracks.",["title"]="Highlord Bolvar Fordragon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6185:description:1-55","6185:description:57-74","6185:description:76-165","6185:description:170-232","6185:description:234-318","6185:description:320-329","6185:description:334-355","6185:description:360-395","6185:description:400-435","6185:description:440-487","6185:objective:1-93","6185:objective:95-176"},["minimumStage"]=2,["questID"]=6185,["sourceHash"]="f8491759b511e60f474682ea559ab91214206847e599fd79427c6783e4dba070"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12425",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Flint sought clues about the Blightcaller and the fate of missing SI:7 operatives in the Eastern Plaguelands.",["title"]="Flint Shadowmore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6185:description:1-55","6185:description:57-74","6185:description:76-165","6185:description:170-232","6185:description:234-318","6185:description:320-329","6185:description:334-355","6185:description:360-395","6185:description:400-435","6185:description:440-487","6185:objective:1-93","6185:objective:95-176"},["minimumStage"]=2,["questID"]=6185,["sourceHash"]="f8491759b511e60f474682ea559ab91214206847e599fd79427c6783e4dba070"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12425",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He feared the agents were dead and used their insignia as the means to identify any remains found.",["title"]="Flint Shadowmore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6285:description:1-39","6285:description:42-117","6285:description:122-294","6285:description:299-403","6285:description:406-470","6285:objective:1-128"},["minimumStage"]=2,["questID"]=6285,["sourceHash"]="a6747a40321f3aae93d2c38d7ff5a656ce1a891253ad150818afbfd0a46f5c9d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-352",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dungar arranged gryphon travel between Stormwind and known outlying masters, including Thor in Westfall.",["title"]="Dungar Longdrink"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6285:description:1-39","6285:description:42-117","6285:description:122-294","6285:description:299-403","6285:description:406-470","6285:objective:1-128"},["minimumStage"]=2,["questID"]=6285,["sourceHash"]="a6747a40321f3aae93d2c38d7ff5a656ce1a891253ad150818afbfd0a46f5c9d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-352",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He taught that his gryphons knew their capital route but needed the traveler’s prior contact with a remote master before taking them there.",["title"]="Dungar Longdrink"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6321:description:1-73","6321:description:76-187","6321:description:192-301","6321:description:306-406","6321:description:409-507","6321:objective:1-36"},["minimumStage"]=2,["questID"]=6321,["sourceHash"]="51a5a8cab93e7f1fe79f0297a14642dc88107f4cc718aa69f4a8e2ef52c3671b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6389",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Podrig inventoried the Sepulcher’s equipment under Hadrec’s orders to keep Deathguards prepared for danger in the woods.",["title"]="Deathguard Podrig"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6321:description:1-73","6321:description:76-187","6321:description:192-301","6321:description:306-406","6321:description:409-507","6321:objective:1-36"},["minimumStage"]=2,["questID"]=6321,["sourceHash"]="51a5a8cab93e7f1fe79f0297a14642dc88107f4cc718aa69f4a8e2ef52c3671b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6389",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Most stores were adequate, but weapons lost in the field required a requisition to Gordon Wendham in the Undercity.",["title"]="Deathguard Podrig"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6341:description:1-101","6341:description:104-169","6341:description:174-278","6341:description:281-347","6341:description:352-455","6341:objective:1-39"},["minimumStage"]=2,["questID"]=6341,["sourceHash"]="29257e1de4f6eac76669f5a70c21963205f35fcbd771de1aeda0391e8470e3c8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10118",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nessa wanted to compare Rut’theran’s unusually abundant, large fish with those found on the mainland.",["title"]="Nessa Shadowsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6341:description:1-101","6341:description:104-169","6341:description:174-278","6341:description:281-347","6341:description:352-455","6341:objective:1-39"},["minimumStage"]=2,["questID"]=6341,["sourceHash"]="29257e1de4f6eac76669f5a70c21963205f35fcbd771de1aeda0391e8470e3c8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-10118",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She prepared bones and scales for her colleague Laird, an Auberdine fish vendor, using Vesprystus to arrange transport.",["title"]="Nessa Shadowsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6342:description:1-90","6342:description:93-201","6342:description:206-287","6342:description:290-359","6342:description:364-390","6342:description:393-491","6342:objective:1-109"},["minimumStage"]=2,["questID"]=6342,["sourceHash"]="a68cda34ffd372e73d68349985a7384d0688d2c834b18fc2b85bf024ba17aaf0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3838",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vesprystus oversaw hippogryph travel from Rut’theran and recommended meeting the master in each new settlement to establish further routes.",["title"]="Vesprystus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6342:description:1-90","6342:description:93-201","6342:description:206-287","6342:description:290-359","6342:description:364-390","6342:description:393-491","6342:objective:1-109"},["minimumStage"]=2,["questID"]=6342,["sourceHash"]="a68cda34ffd372e73d68349985a7384d0688d2c834b18fc2b85bf024ba17aaf0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3838",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described ferry and hippogryph as reliable alternatives for crossing to Auberdine while helping forward Nessa’s research collection.",["title"]="Vesprystus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6:description:1-173","6:description:176-224","6:description:229-244","6:description:247-294","6:description:297-332","6:objective:1-77"},["minimumStage"]=2,["questID"]=6,["sourceHash"]="6bc064d32b725f2b95e6cd1dd9f23fb8e21c2496d12e8b9a8f17da29fe37ce28"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-103",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Garrick was the cutthroat Willem blamed for weeks of attacks on Northshire’s farmers and merchants.",["title"]="Garrick Padfoot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6:description:1-173","6:description:176-224","6:description:229-244","6:description:247-294","6:description:297-332","6:objective:1-77"},["minimumStage"]=2,["questID"]=6,["sourceHash"]="6bc064d32b725f2b95e6cd1dd9f23fb8e21c2496d12e8b9a8f17da29fe37ce28"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-103",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His gang gathered around a shack near the vineyards east of the Abbey, making a lone approach dangerous.",["title"]="Garrick Padfoot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"34:description:1-47","34:description:50-86","34:description:89-167","34:description:172-235","34:description:238-244","34:description:247-283","34:description:286-309","34:description:312-359","34:description:362-488","34:objective:1-57","34:objective:60-87"},["minimumStage"]=2,["questID"]=34,["sourceHash"]="f1bc27b7bb41d85bd59f74a36e66baba7d6973f7d984df99a745439153bcbce8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-345",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Martie blamed the boar Bellygrub for trampling her garden and ruining the daffodils until the next planting season.",["title"]="Bellygrub"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"34:description:1-47","34:description:50-86","34:description:89-167","34:description:172-235","34:description:238-244","34:description:247-283","34:description:286-309","34:description:312-359","34:description:362-488","34:objective:1-57","34:objective:60-87"},["minimumStage"]=2,["questID"]=34,["sourceHash"]="f1bc27b7bb41d85bd59f74a36e66baba7d6973f7d984df99a745439153bcbce8"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-345",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="It foraged southwest of Lakeshire and sometimes wandered into her garden.",["title"]="Bellygrub"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"200:description:1-66","200:description:69-112","200:description:117-172","200:description:175-270","200:description:273-362","200:description:367-470","200:description:473-509","200:objective:1-28"},["minimumStage"]=2,["questID"]=200,["sourceHash"]="9d6ace0a44c51e98d5efaf6a4f130d433ee953ed8c61f08c1694d972b98f826e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-815",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bookie managed Kurzen’s logistics and knew the compound’s day-to-day operations.",["title"]="Bookie Herod"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"200:description:1-66","200:description:69-112","200:description:117-172","200:description:175-270","200:description:273-362","200:description:367-470","200:description:473-509","200:objective:1-28"},["minimumStage"]=2,["questID"]=200,["sourceHash"]="9d6ace0a44c51e98d5efaf6a4f130d433ee953ed8c61f08c1694d972b98f826e"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-815",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He served as Thorsen’s contact inside the camp before Doren’s inquiry turned toward how the infiltrator’s secret had been exposed.",["title"]="Bookie Herod"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"206:description:1-67","206:description:70-208","206:description:211-301","206:description:306-418","206:description:423-500","206:objective:1-57"},["minimumStage"]=2,["questID"]=206,["sourceHash"]="91481e176e5c99c064c9d82f78615f344f21d19438e86206d85538a3dcb1dc77"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-818",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mai’Zoth was an ogre mage living in a mound in Stranglethorn’s eastern mountains.",["title"]="Mai'Zoth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"206:description:1-67","206:description:70-208","206:description:211-301","206:description:306-418","206:description:423-500","206:objective:1-57"},["minimumStage"]=2,["questID"]=206,["sourceHash"]="91481e176e5c99c064c9d82f78615f344f21d19438e86206d85538a3dcb1dc77"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-818",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nimetz attributed Kurzen’s corruption to Mai’Zoth’s rumored mind-control magic and the artifact called the Mind’s Eye.",["title"]="Mai'Zoth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"207:description:1-93","207:description:96-135","207:description:138-189","207:description:194-260","207:description:263-306","207:description:309-374","207:description:379-507","207:objective:1-66"},["minimumStage"]=2,["questID"]=207,["sourceHash"]="3de1044629ae83c72d0d49840b7b365ec3397cbd828e9dd7eac55a2a3e36129e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-813",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nimetz remembered Kurzen as once great and noble, making the colonel’s depravity a mystery rather than an assumed lifelong cruelty.",["title"]="Colonel Kurzen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"207:description:1-93","207:description:96-135","207:description:138-189","207:description:194-260","207:description:263-306","207:description:309-374","207:description:379-507","207:objective:1-66"},["minimumStage"]=2,["questID"]=207,["sourceHash"]="3de1044629ae83c72d0d49840b7b365ec3397cbd828e9dd7eac55a2a3e36129e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-813",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The initial inquiry tested a theory of troll influence through inscriptions from the Stranglethorn ruins; it had not yet established the cause.",["title"]="Colonel Kurzen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"211:description:1-85","211:description:90-173","211:description:176-328","211:description:331-410","211:description:415-482","211:objective:1-99"},["minimumStage"]=2,["questID"]=211,["sourceHash"]="3b308f2f09727008a9faf4b355685bc2ac3d12d30285480cf91de755f1d00af1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1852",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Araj was the lich holding dominion over ruined Andorhal.",["title"]="Araj the Summoner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"211:description:1-85","211:description:90-173","211:description:176-328","211:description:331-410","211:description:415-482","211:objective:1-99"},["minimumStage"]=2,["questID"]=211,["sourceHash"]="3b308f2f09727008a9faf4b355685bc2ac3d12d30285480cf91de755f1d00af1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1852",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Numerous Scourge defended the city center around him, reinforced by a formidable personal guard and the protection of his phylactery.",["title"]="Araj the Summoner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"212:description:1-69","212:description:72-92","212:description:94-188","212:description:193-326","212:description:331-453","212:description:456-468","212:objective:1-106"},["minimumStage"]=2,["questID"]=212,["sourceHash"]="8bf9c49c5fdc78fe186ceff6fa000d8efbc497c6293ff4dc8254420c96c7805f"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-690",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cold Eye basilisks roamed the beach dunes of northwestern Stranglethorn.",["title"]="Cold Eye Basilisk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"212:description:1-69","212:description:72-92","212:description:94-188","212:description:193-326","212:description:331-453","212:description:456-468","212:objective:1-106"},["minimumStage"]=2,["questID"]=212,["sourceHash"]="8bf9c49c5fdc78fe186ceff6fa000d8efbc497c6293ff4dc8254420c96c7805f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-690",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Their haunches supplied a delicacy that had to be delivered freshly killed because the meat was difficult to preserve.",["title"]="Cold Eye Basilisk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"256:description:1-40","256:description:45-233","256:description:238-336","256:description:341-425","256:objective:1-70"},["minimumStage"]=2,["questID"]=256,["sourceHash"]="46845441f61507acc433b28729accdaa7055be50930b86da3439f06f6887b04c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1210",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thelsamar’s magistrate presumed Chok’sul coordinated ogre attacks on the town, dam and excavation, and issued a bounty on that basis.",["title"]="Chok'sul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"256:description:1-40","256:description:45-233","256:description:238-336","256:description:341-425","256:objective:1-70"},["minimumStage"]=2,["questID"]=256,["sourceHash"]="46845441f61507acc433b28729accdaa7055be50930b86da3439f06f6887b04c"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1210",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The wanted notice placed him at the northeastern Loch Modan ogre camp.",["title"]="Chok'sul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"271:description:1-73","271:description:75-121","271:description:126-241","271:description:243-290","271:description:292-357","271:description:362-429","271:description:434-511","271:objective:1-87"},["minimumStage"]=2,["questID"]=271,["sourceHash"]="c58369da9e18e0e5a6d4640c941bea5b9929ceec41cf162274f46ae3d173f21c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1225",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vyrin said the large bear had eluded Farstrider Lodge’s hunters and left Daryl with a scar when he tried his own luck.",["title"]="Ol' Sooty"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"271:description:1-73","271:description:75-121","271:description:126-241","271:description:243-290","271:description:292-357","271:description:362-429","271:description:434-511","271:objective:1-87"},["minimumStage"]=2,["questID"]=271,["sourceHash"]="c58369da9e18e0e5a6d4640c941bea5b9929ceec41cf162274f46ae3d173f21c"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1225",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ol’ Sooty’s lair lay in the hills above Thelsamar.",["title"]="Ol' Sooty"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"279:description:1-91","279:description:94-158","279:description:163-331","279:description:334-395","279:description:400-444","279:description:447-492","279:objective:1-25","279:objective:30-60","279:objective:65-118"},["minimumStage"]=2,["questID"]=279,["sourceHash"]="37ce3b4ced8a78466e3bdf0b724f638f3f6e7ee7e0c5be280f371c7a0dba7018"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1259",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gobbler raided merchants with Bluegill murlocs and retreated to their coastal hovels afterward.",["title"]="Gobbler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"279:description:1-91","279:description:94-158","279:description:163-331","279:description:334-395","279:description:400-444","279:description:447-492","279:objective:1-25","279:objective:30-60","279:objective:65-118"},["minimumStage"]=2,["questID"]=279,["sourceHash"]="37ce3b4ced8a78466e3bdf0b724f638f3f6e7ee7e0c5be280f371c7a0dba7018"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1259",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He prowled the river inlet north of Menethil, amid murloc villages threatening the fishers and trade.",["title"]="Gobbler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"290:description:1-111","290:description:114-241","290:description:246-282","290:description:285-329","290:description:332-397","290:description:402-488","290:objective:1-53","290:objective:58-109"},["minimumStage"]=2,["questID"]=290,["sourceHash"]="8bb517c63dd76436136e2a6b1de236a218b0ce397d52ca27f5dff6e2603ee808"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1160",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Halyndor had commanded the Intrepid and kept control of its strongbox.",["title"]="Captain Halyndor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"290:description:1-111","290:description:114-241","290:description:246-282","290:description:285-329","290:description:332-397","290:description:402-488","290:objective:1-53","290:objective:58-109"},["minimumStage"]=2,["questID"]=290,["sourceHash"]="8bb517c63dd76436136e2a6b1de236a218b0ce397d52ca27f5dff6e2603ee808"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1160",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fitzsimmons believed the captain still walked the doomed ship and held the key to the cursed cargo whose cleansing might free its crew.",["title"]="Captain Halyndor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"296:description:1-96","296:description:99-130","296:description:133-215","296:description:220-255","296:description:258-304","296:description:307-382","296:description:385-433","296:objective:1-143"},["minimumStage"]=2,["questID"]=296,["sourceHash"]="d86e79932dea5ffbdc6ccd115131703ed661c7f72737517c4d4ba93cec0d0910"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-1353",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sarltooth was larger and more menacing than the other beasts occupying the excavation.",["title"]="Sarltooth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"296:description:1-96","296:description:99-130","296:description:133-215","296:description:220-255","296:description:258-304","296:description:307-382","296:description:385-433","296:objective:1-143"},["minimumStage"]=2,["questID"]=296,["sourceHash"]="d86e79932dea5ffbdc6ccd115131703ed661c7f72737517c4d4ba93cec0d0910"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1353",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ormer suspected it led the others into the dig, treating that suspicion as the reason for a final hunt.",["title"]="Sarltooth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"304:description:1-51","304:description:53-133","304:description:136-183","304:description:186-298","304:description:300-418","304:description:423-488","304:description:490-511","304:objective:1-83"},["minimumStage"]=2,["questID"]=304,["sourceHash"]="6331ad2e11c65eb84d1d1e311382d73afd33414fbe340bf5e57082ea04f9a4e1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1364",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Roggo’s intelligence identified Balgaras as the warlock leading Dark Iron forces in the Wetlands.",["title"]="Balgaras the Foul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"304:description:1-51","304:description:53-133","304:description:136-183","304:description:186-298","304:description:300-418","304:description:423-488","304:description:490-511","304:objective:1-83"},["minimumStage"]=2,["questID"]=304,["sourceHash"]="6331ad2e11c65eb84d1d1e311382d73afd33414fbe340bf5e57082ea04f9a4e1"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1364",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Longbraid placed his camp on Direforge Hill and accused him of hiding while soldiers carried out his orders.",["title"]="Balgaras the Foul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"312:description:1-80","312:description:83-126","312:description:129-218","312:description:221-274","312:description:277-321","312:description:326-362","312:description:365-398","312:description:401-481","312:objective:1-90"},["minimumStage"]=2,["questID"]=312,["sourceHash"]="9d7163773302fedd50413b151714cfba4e9a4a9f947cb1be1443a5de391fc767"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1271",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Old Icebeard carried off MacGrann’s locked store of salted winter meat while its owner hunted deer.",["title"]="Old Icebeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"312:description:1-80","312:description:83-126","312:description:129-218","312:description:221-274","312:description:277-321","312:description:326-362","312:description:365-398","312:description:401-481","312:objective:1-90"},["minimumStage"]=2,["questID"]=312,["sourceHash"]="9d7163773302fedd50413b151714cfba4e9a4a9f947cb1be1443a5de391fc767"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1271",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The thorium locker remained protected from being smashed, but its theft threatened MacGrann with starvation unless it could be recovered from the cave.",["title"]="Old Icebeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"369:description:1-153","369:description:156-268","369:description:273-352","369:description:355-442","369:description:445-509","369:objective:1-113"},["minimumStage"]=2,["questID"]=369,["sourceHash"]="1afb471e5cba60be8cb9d011af0a99fe663993e303ec054c420e9d64993e1c50"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1555",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Johaan’s old texts described plague surviving in Night Web spider venom; he sought a vicious specimen’s venom to test its contagious component in his new mixture.",["title"]="Vicious Night Web Spider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"370:description:1-121","370:description:124-255","370:description:260-334","370:objective:1-105"},["minimumStage"]=2,["questID"]=370,["sourceHash"]="81bf4e2b810d47f749e57f27a00de3ba7f748c45d4810c1bf4eb0c7368fee04e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1662",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Perrine commanded a Scarlet brigade assigned to the ruined tower southwest of Brill, according to Arren’s strategic documents.",["title"]="Captain Perrine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"371:description:1-62","371:description:65-253","371:description:258-297","371:description:299-354","371:objective:1-90"},["minimumStage"]=2,["questID"]=371,["sourceHash"]="52db2e170f5c95ef5884bef10f4df1f917576353dbd5e4f7db1a7b3fee4738ff"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1664",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vachon led Scarlet raids from a ruined tower near Balnir Farmstead in southeastern Tirisfal.",["title"]="Captain Vachon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6162:description:1-124","6162:description:129-324","6162:description:329-362","6162:description:364-403","6162:description:405-445","6162:description:447-472","6162:objective:1-81"},["minimumStage"]=2,["questID"]=6162,["sourceHash"]="348cbfef3c3060664a5fc4e0f2361ef81d5f71905df939c190140a158c5184ff"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-9464",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dreka’Sur described Ror as a great, corrupted furbolg.",["title"]="Overlord Ror"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6162:description:1-124","6162:description:129-324","6162:description:329-362","6162:description:364-403","6162:description:405-445","6162:description:447-472","6162:objective:1-81"},["minimumStage"]=2,["questID"]=6162,["sourceHash"]="348cbfef3c3060664a5fc4e0f2361ef81d5f71905df939c190140a158c5184ff"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9464",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her husband and a druid vanished after setting out against him, leaving her to blame Ror for their loss and seek vengeance.",["title"]="Overlord Ror"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3924:description:1-81","3924:description:84-262","3924:description:265-298","3924:description:303-380","3924:description:383-482","3924:objective:1-61"},["minimumStage"]=2,["questID"]=3924,["sourceHash"]="db209163cb3dfc29c483b9d5a83cb86a787b65bf3a9ab4a18e46e407e2cec1d2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-9336",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Copperplug guarded the samophlange’s technical secrets inside the Venture Company, sharing only fragments with trusted associates.",["title"]="Boss Copperplug"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3924:description:1-81","3924:description:84-262","3924:description:265-298","3924:description:303-380","3924:description:383-482","3924:objective:1-61"},["minimumStage"]=2,["questID"]=3924,["sourceHash"]="db209163cb3dfc29c483b9d5a83cb86a787b65bf3a9ab4a18e46e407e2cec1d2"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-9336",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rilli placed his rival at Boulder Lode Mine in the northeastern Barrens, with the manual needed for repairs.",["title"]="Boss Copperplug"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6343:description:1-32","6343:description:35-140","6343:description:143-257","6343:description:262-297","6343:description:300-409","6343:description:412-500","6343:objective:1-43"},["minimumStage"]=2,["questID"]=6343,["sourceHash"]="a5704a45c5a69a8eb006ec8d33e746145740c749764271de162428140e13fce0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4200",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Laird compared the mainland fish with Nessa’s Teldrassil specimens and wanted his observations sent back.",["title"]="Laird"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6343:description:1-32","6343:description:35-140","6343:description:143-257","6343:description:262-297","6343:description:300-409","6343:description:412-500","6343:objective:1-43"},["minimumStage"]=2,["questID"]=6343,["sourceHash"]="a5704a45c5a69a8eb006ec8d33e746145740c749764271de162428140e13fce0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4200",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He suspected the World Tree influenced nearby wildlife but acknowledged that the cause of the differences remained a guess.",["title"]="Laird"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6381:description:1-88","6381:description:90-127","6381:description:129-222","6381:description:224-299","6381:description:304-380","6381:description:382-410","6381:objective:1-122"},["minimumStage"]=2,["questID"]=6381,["sourceHash"]="c125f6a167653ad6e317ca685b9b4b5eb45a1ea721ca2e52c5de4e9145090a2b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11864",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tammra sought to help the Charred Vale’s cycle of life resume by planting enchanted Gaea seeds in surviving fertile soil.",["title"]="Tammra Windfield"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6381:description:1-88","6381:description:90-127","6381:description:129-222","6381:description:224-299","6381:description:304-380","6381:description:382-410","6381:objective:1-122"},["minimumStage"]=2,["questID"]=6381,["sourceHash"]="c125f6a167653ad6e317ca685b9b4b5eb45a1ea721ca2e52c5de4e9145090a2b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11864",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Harpies and angry fire elementals still threatened the planting grounds amid the burned land.",["title"]="Tammra Windfield"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6387:description:1-76","6387:description:79-149","6387:description:154-247","6387:description:250-296","6387:description:299-324","6387:description:329-483","6387:objective:1-54"},["minimumStage"]=2,["questID"]=6387,["sourceHash"]="236fb5710bde1f088f580b6722d654266ed54b4643197a79bc221dd18e00fe62"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1681",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brock taught mining to young dwarves and rewarded high-scoring students with honorary picks.",["title"]="Brock Stoneseeker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6387:description:1-76","6387:description:79-149","6387:description:154-247","6387:description:250-296","6387:description:299-324","6387:description:329-483","6387:objective:1-54"},["minimumStage"]=2,["questID"]=6387,["sourceHash"]="236fb5710bde1f088f580b6722d654266ed54b4643197a79bc221dd18e00fe62"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1681",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He relied on Golnir Bouldertoe in Ironforge to prepare the earned tools from his list.",["title"]="Brock Stoneseeker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6392:description:1-58","6392:description:60-96","6392:description:99-238","6392:description:243-337","6392:description:340-409","6392:description:414-451","6392:objective:1-130"},["minimumStage"]=2,["questID"]=6392,["sourceHash"]="c5880189cdee42cf0f337413ca05c7b53f7815164898dbd421dcf1d19d75a9a7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1573",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gryth operated gryphon travel from Ironforge, including the route back to Thorgrum in Thelsamar.",["title"]="Gryth Thurden"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6392:description:1-58","6392:description:60-96","6392:description:99-238","6392:description:243-337","6392:description:340-409","6392:description:414-451","6392:objective:1-130"},["minimumStage"]=2,["questID"]=6392,["sourceHash"]="c5880189cdee42cf0f337413ca05c7b53f7815164898dbd421dcf1d19d75a9a7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1573",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He emphasized making contact with remote flight masters before relying on a later return journey.",["title"]="Gryth Thurden"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6394:description:1-28","6394:description:31-66","6394:description:71-171","6394:description:174-258","6394:description:261-328","6394:description:333-371","6394:description:374-476","6394:description:478-501","6394:objective:1-44"},["minimumStage"]=2,["questID"]=6394,["sourceHash"]="d5e581c9dbd639e242ace888eb080f467f5284f332bdcd09d13215fb9b6057ef"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11378",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thazz’ril left his favorite pick in a northern cave while surveying minerals, then found vicious creatures occupying it when he returned.",["title"]="Foreman Thazz'ril"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6394:description:1-28","6394:description:31-66","6394:description:71-171","6394:description:174-258","6394:description:261-328","6394:description:333-371","6394:description:374-476","6394:description:478-501","6394:objective:1-44"},["minimumStage"]=2,["questID"]=6394,["sourceHash"]="d5e581c9dbd639e242ace888eb080f467f5284f332bdcd09d13215fb9b6057ef"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11378",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The pick’s enchantment made it visible in darkness; it lay in a chamber with waterfalls inside the Burning Blade Coven.",["title"]="Foreman Thazz'ril"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6403:description:1-40","6403:description:42-77","6403:description:79-115","6403:description:120-246","6403:description:251-312","6403:description:314-372","6403:description:374-393","6403:description:395-419","6403:description:424-471","6403:description:476-489","6403:objective:1-42","6403:objective:44-65"},["minimumStage"]=2,["questID"]=6403,["sourceHash"]="0ff48e143baa674d7be92ba7df943c8803a3c7fee2bbe7dc935d8a077f45d9b4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12580",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Windsor intended to break Lady Prestor’s hold over Stormwind by exposing her as Onyxia.",["title"]="Reginald Windsor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6403:description:1-40","6403:description:42-77","6403:description:79-115","6403:description:120-246","6403:description:251-312","6403:description:314-372","6403:description:374-393","6403:description:395-419","6403:description:424-471","6403:description:476-489","6403:objective:1-42","6403:objective:44-65"},["minimumStage"]=2,["questID"]=6403,["sourceHash"]="0ff48e143baa674d7be92ba7df943c8803a3c7fee2bbe7dc935d8a077f45d9b4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12580",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He identified her as Deathwing’s brood and Nefarian’s twin, warning that even the Highlord had been made a puppet of her deception.",["title"]="Reginald Windsor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6461:description:1-118","6461:description:123-174","6461:description:176-269","6461:description:274-365","6461:description:367-472","6461:objective:1-92"},["minimumStage"]=2,["questID"]=6461,["sourceHash"]="64ff189eedee6eed4af1742d7f8e3960413c2d7a9e7266af1d8a1259e6c632d4"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12816",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xen’Zilla’s hunters at Malaka’jin lost their catches to spiders raiding the camps after dark.",["title"]="Xen'Zilla"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6461:description:1-118","6461:description:123-174","6461:description:176-269","6461:description:274-365","6461:description:367-472","6461:objective:1-92"},["minimumStage"]=2,["questID"]=6461,["sourceHash"]="64ff189eedee6eed4af1742d7f8e3960413c2d7a9e7266af1d8a1259e6c632d4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12816",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought help protecting the game on which the settlement had prospered, rather than hunting the spiders without a practical need.",["title"]="Xen'Zilla"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6504:description:1-131","6504:description:133-249","6504:description:251-315","6504:description:320-378","6504:description:380-433","6504:description:435-460","6504:objective:1-111","6504:objective:113-170"},["minimumStage"]=2,["questID"]=6504,["sourceHash"]="f6f26f2ffd1454afe4d0c612b58f7747b7ef8eaccd35e50a3e3282b6a02f77ab"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12718",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gurda lost the shredder manual to a gust of wind while bringing the machine from Ratchet to the Warsong Lumber Camp.",["title"]="Gurda Ragescar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6504:description:1-131","6504:description:133-249","6504:description:251-315","6504:description:320-378","6504:description:380-433","6504:description:435-460","6504:objective:1-111","6504:objective:113-170"},["minimumStage"]=2,["questID"]=6504,["sourceHash"]="f6f26f2ffd1454afe4d0c612b58f7747b7ef8eaccd35e50a3e3282b6a02f77ab"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12718",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Unable to operate the shredder from its cover alone, she needed the scattered pages before reporting for duty.",["title"]="Gurda Ragescar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6544:description:1-4","6544:description:12-21","6544:description:26-97","6544:description:100-141","6544:description:144-217","6544:description:220-247","6544:description:252-301","6544:description:304-404","6544:description:409-424","6544:description:427-442","6544:objective:1-126"},["minimumStage"]=2,["questID"]=6544,["sourceHash"]="4fe3c0bcaa5208a0e8b05a1182643d818417da38f8832331b6f2a123b1bc3c22"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12858",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Torek led raiders preparing to assault Silverwing Outpost and its leader Duriel Moonfire.",["title"]="Torek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6544:description:1-4","6544:description:12-21","6544:description:26-97","6544:description:100-141","6544:description:144-217","6544:description:220-247","6544:description:252-301","6544:description:304-404","6544:description:409-424","6544:description:427-442","6544:objective:1-126"},["minimumStage"]=2,["questID"]=6544,["sourceHash"]="4fe3c0bcaa5208a0e8b05a1182643d818417da38f8832331b6f2a123b1bc3c22"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-12858",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the result reported to his superior Ertog at Splintertree, while scouts warned of the outpost’s strong Sentinel and warrior defense.",["title"]="Torek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6563:description:1-109","6563:description:111-175","6563:description:177-255","6563:description:257-368","6563:description:373-393","6563:description:395-472","6563:objective:1-61"},["minimumStage"]=2,["questID"]=6563,["sourceHash"]="fad301e79d90e4c2609289fc15e09918fb5db22e621b508afffb1841282872e0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12736",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Je’neu wanted Blackfathom’s sapphire crystals collected before naga harvesters could exploit their elemental power.",["title"]="Je'neu Sancrea"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6563:description:1-109","6563:description:111-175","6563:description:177-255","6563:description:257-368","6563:description:373-393","6563:description:395-472","6563:objective:1-61"},["minimumStage"]=2,["questID"]=6563,["sourceHash"]="fad301e79d90e4c2609289fc15e09918fb5db22e621b508afffb1841282872e0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12736",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He judged the crystals potentially powerful arcane components but had not yet established the naga’s purpose.",["title"]="Je'neu Sancrea"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6568:description:1-22","6568:description:24-96","6568:description:101-193","6568:description:198-229","6568:description:231-328","6568:description:330-415","6568:description:420-444","6568:objective:1-70"},["minimumStage"]=2,["questID"]=6568,["sourceHash"]="b0611f8632ea9470c265686ea402d70659a6e805fc0801e6b5925ac374935be5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10182",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rexxar recommended illusion and disguise rather than direct force to deceive the Black Dragonflight.",["title"]="Rexxar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6568:description:1-22","6568:description:24-96","6568:description:101-193","6568:description:198-229","6568:description:231-328","6568:description:330-415","6568:description:420-444","6568:objective:1-70"},["minimumStage"]=2,["questID"]=6568,["sourceHash"]="b0611f8632ea9470c265686ea402d70659a6e805fc0801e6b5925ac374935be5"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-10182",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He trusted Myranda, a former Lordaeron master illusionist who had helped before, while warning that she would judge the cause herself.",["title"]="Rexxar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6569:description:1-55","6569:description:60-189","6569:description:191-278","6569:description:283-415","6569:description:420-482","6569:objective:1-64","6569:objective:66-117"},["minimumStage"]=2,["questID"]=6569,["sourceHash"]="7c86c4600e351dc7ec6e3b1d7dbb78436e47791c88f322cd45e76a4daa7e2bac"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11872",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Myranda could create a disguise resembling one of the Black Flight.",["title"]="Myranda the Hag"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6569:description:1-55","6569:description:60-189","6569:description:191-278","6569:description:283-415","6569:description:420-482","6569:objective:1-64","6569:objective:66-117"},["minimumStage"]=2,["questID"]=6569,["sourceHash"]="7c86c4600e351dc7ec6e3b1d7dbb78436e47791c88f322cd45e76a4daa7e2bac"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11872",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She considered the illusion straightforward but required difficult-to-obtain eyes from Blackrock Spire’s black dragonspawn for the divination.",["title"]="Myranda the Hag"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6571:description:1-65","6571:description:70-127","6571:description:129-210","6571:description:215-266","6571:description:268-462","6571:description:467-482","6571:objective:1-143"},["minimumStage"]=2,["questID"]=6571,["sourceHash"]="dddf07eb03b28eca14e704a4326a4598c8d9fa6889875931c7ca4fbdb5c26944"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11820",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Locke faced shortages of saw blades, axes, oil and rope at the Warsong camp, with theft interrupting the latter shipments.",["title"]="Locke Okarr"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6571:description:1-65","6571:description:70-127","6571:description:129-210","6571:description:215-266","6571:description:268-462","6571:description:467-482","6571:objective:1-143"},["minimumStage"]=2,["questID"]=6571,["sourceHash"]="dddf07eb03b28eca14e704a4326a4598c8d9fa6889875931c7ca4fbdb5c26944"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11820",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He traced rope to Thistlefur and Foulweald furbolgs, and stolen oil to satyr rituals at Night Run, Satyrnaar and Xavian.",["title"]="Locke Okarr"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6603:description:1-32","6603:description:37-112","6603:description:114-147","6603:description:149-213","6603:description:215-278","6603:description:283-372","6603:description:377-406","6603:description:411-426","6603:description:428-491","6603:objective:1-57"},["minimumStage"]=2,["questID"]=6603,["sourceHash"]="3ed2736dc4b3d0451cdb30579ad8ace1d64e80354c70d389376e12b07309d3ec"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11754",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Meggi valued wilderness travel for developing judgment, reflexes and a cool head, taking pride in her time in the hills.",["title"]="Meggi Peppinrocker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6603:description:1-32","6603:description:37-112","6603:description:114-147","6603:description:149-213","6603:description:215-278","6603:description:283-372","6603:description:377-406","6603:description:411-426","6603:description:428-491","6603:objective:1-57"},["minimumStage"]=2,["questID"]=6603,["sourceHash"]="3ed2736dc4b3d0451cdb30579ad8ace1d64e80354c70d389376e12b07309d3ec"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11754",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She referred concerns about Winterspring to Donova at the hot springs rather than supplying an explanation herself.",["title"]="Meggi Peppinrocker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6622:description:1-17","6622:description:19-99","6622:description:101-186","6622:description:191-208","6622:description:210-256","6622:description:258-300","6622:description:302-338","6622:description:340-383","6622:description:385-438","6622:description:443-475","6622:description:480-497","6622:objective:1-63","6622:objective:65-131","6622:objective:136-164","6622:objective:166-244","6622:objective:246-381"},["minimumStage"]=2,["questID"]=6622,["sourceHash"]="919e76b360728d9a8236cd3aab26401ee093b456a0e52ce298d1096a3dc18b32"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12920",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gregory examined candidates for Horde Trauma through the treatment of a stream of wounded patients.",["title"]="Doctor Gregory Victor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6622:description:1-17","6622:description:19-99","6622:description:101-186","6622:description:191-208","6622:description:210-256","6622:description:258-300","6622:description:302-338","6622:description:340-383","6622:description:385-438","6622:description:443-475","6622:description:480-497","6622:objective:1-63","6622:objective:65-131","6622:objective:136-164","6622:objective:166-244","6622:objective:246-381"},["minimumStage"]=2,["questID"]=6622,["sourceHash"]="919e76b360728d9a8236cd3aab26401ee093b456a0e52ce298d1096a3dc18b32"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12920",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His lesson prioritized the critically hurt, then the badly injured, then those with lesser wounds.",["title"]="Doctor Gregory Victor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6624:description:1-17","6624:description:19-99","6624:description:101-189","6624:description:194-211","6624:description:213-259","6624:description:261-303","6624:description:305-341","6624:description:343-386","6624:description:388-441","6624:description:446-463","6624:objective:1-63","6624:objective:65-131","6624:objective:136-164","6624:objective:166-244","6624:objective:246-381"},["minimumStage"]=2,["questID"]=6624,["sourceHash"]="61af57e23e0ad660297538bc24c418b6531711ca72b0b096a0589d9cfd8b0fe8"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12939",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gustaf tested would-be Alliance Trauma practitioners in triage rather than simple speed alone.",["title"]="Doctor Gustaf VanHowzen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6624:description:1-17","6624:description:19-99","6624:description:101-189","6624:description:194-211","6624:description:213-259","6624:description:261-303","6624:description:305-341","6624:description:343-386","6624:description:388-441","6624:description:446-463","6624:objective:1-63","6624:objective:65-131","6624:objective:136-164","6624:objective:166-244","6624:objective:246-381"},["minimumStage"]=2,["questID"]=6624,["sourceHash"]="61af57e23e0ad660297538bc24c418b6531711ca72b0b096a0589d9cfd8b0fe8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12939",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He instructed pupils to treat critical injuries before severe ones and leave the least urgent cases until last.",["title"]="Doctor Gustaf VanHowzen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6626:description:1-36","6626:description:38-47","6626:description:49-70","6626:description:72-136","6626:description:138-186","6626:description:191-273","6626:description:275-343","6626:description:348-399","6626:description:401-416","6626:description:418-445","6626:objective:1-150"},["minimumStage"]=2,["questID"]=6626,["sourceHash"]="f5c0ffb3d1476a2beba358885e2fd165a79e5c6ece25ec4ad6ae4ac4c276789e"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12866",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Myriam suspected a diplomat granting undeath to followers might be Scourge, distinguishing that behavior from what she had observed of the Forsaken.",["title"]="Myriam Moonsinger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6626:description:1-36","6626:description:38-47","6626:description:49-70","6626:description:72-136","6626:description:138-186","6626:description:191-273","6626:description:275-343","6626:description:348-399","6626:description:401-416","6626:description:418-445","6626:objective:1-150"},["minimumStage"]=2,["questID"]=6626,["sourceHash"]="f5c0ffb3d1476a2beba358885e2fd165a79e5c6ece25ec4ad6ae4ac4c276789e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12866",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lacking the strength to confront the growing ranks alone, she sought help against those gathering for more power.",["title"]="Myriam Moonsinger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6641:description:1-20","6641:description:22-62","6641:description:67-166","6641:description:171-189","6641:description:191-259","6641:description:264-374","6641:description:376-436","6641:description:441-498","6641:objective:1-47","6641:objective:49-132","6641:objective:137-255"},["minimumStage"]=2,["questID"]=6641,["sourceHash"]="1706d99d86499f77ac57fb53ac0b16ac27fb87e999d9debcc5facd34957c8bff"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-12717",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Muglash blamed the sea hydra Vorsha for repeated, unprovoked devastation of Zoram’gar.",["title"]="Muglash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6641:description:1-20","6641:description:22-62","6641:description:67-166","6641:description:171-189","6641:description:191-259","6641:description:264-374","6641:description:376-436","6641:description:441-498","6641:objective:1-47","6641:objective:49-132","6641:objective:137-255"},["minimumStage"]=2,["questID"]=6641,["sourceHash"]="1706d99d86499f77ac57fb53ac0b16ac27fb87e999d9debcc5facd34957c8bff"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12717",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He planned to extinguish the naga’s honoring brazier offshore, believing that would draw the hydra out for a confrontation.",["title"]="Muglash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6845:description:1-56","6845:description:58-102","6845:description:105-213","6845:description:218-300","6845:description:303-366","6845:description:369-409","6845:description:411-457","6845:description:462-485","6845:objective:1-66"},["minimumStage"]=2,["questID"]=6845,["sourceHash"]="8ab77607217a358ed02adbe554ddabba8d6b997dfe31b73e6167248827388fed"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11939",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Umber offered to examine a suspected book and share its contents once he could identify them.",["title"]="Umber"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6845:description:1-56","6845:description:58-102","6845:description:105-213","6845:description:218-300","6845:description:303-366","6845:description:369-409","6845:description:411-457","6845:description:462-485","6845:objective:1-66"},["minimumStage"]=2,["questID"]=6845,["sourceHash"]="8ab77607217a358ed02adbe554ddabba8d6b997dfe31b73e6167248827388fed"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11939",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His teasing advice called Rabine the little camp’s den mother and warned visitors not to keep him waiting.",["title"]="Umber"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"86784:description:1-279","86784:objective:1-69"},["minimumStage"]=2,["questID"]=86784,["sourceHash"]="809b6f77a32e5e1d8f119b7f5e8376f76c1ec50fde387d2c9956cf6086f1f483"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1742",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/86784",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bartholomew knew Eleanor Shackleton as an experienced wilderness traveler and recommended her as a source of practical survival advice.",["title"]="Deathguard Bartholomew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"86784:description:1-279","86784:objective:1-69"},["minimumStage"]=2,["questID"]=86784,["sourceHash"]="809b6f77a32e5e1d8f119b7f5e8376f76c1ec50fde387d2c9956cf6086f1f483"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1742",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/86784",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He remembered her warning to gather far more firewood than seemed necessary and suggested bringing dry branches as an introduction.",["title"]="Deathguard Bartholomew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"86784:description:1-279","86784:objective:1-69"},["minimumStage"]=2,["questID"]=86784,["sourceHash"]="809b6f77a32e5e1d8f119b7f5e8376f76c1ec50fde387d2c9956cf6086f1f483"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-265812",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/86784",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eleanor traveled the wilds and took pride in surviving weather and monsters through practical preparation.",["title"]="Eleanor Shackleton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"86784:description:1-279","86784:objective:1-69"},["minimumStage"]=2,["questID"]=86784,["sourceHash"]="809b6f77a32e5e1d8f119b7f5e8376f76c1ec50fde387d2c9956cf6086f1f483"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-265812",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/86784",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="At her western Tirisfal camp, keeping ample firewood was one of the lessons she passed to less-experienced travelers.",["title"]="Eleanor Shackleton"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"90902:description:1-195","90902:objective:1-63"},["minimumStage"]=2,["questID"]=90902,["sourceHash"]="c951c39f81a4a73be1ef6262e795b63c4c32d95bcd29f55ed662b2666d829e39"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-244808",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/90902",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aramis guided newly risen paladins as they relearned how to call on the Light.",["title"]="Aramis Hammerhand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"90902:description:1-195","90902:objective:1-63"},["minimumStage"]=2,["questID"]=90902,["sourceHash"]="c951c39f81a4a73be1ef6262e795b63c4c32d95bcd29f55ed662b2666d829e39"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-244808",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/90902",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned that healing through the Light could be painful after death and taught persistence through practice rather than promise an effortless cure.",["title"]="Aramis Hammerhand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91209:description:1-202","91209:objective:1-67"},["minimumStage"]=2,["questID"]=91209,["sourceHash"]="b939cb8b64d1d4f18a23d8a87712bea8124880a49e4c6e8e831d26d2904e21df"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-246152",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91209",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shari continued the training of paladins arriving in Brill from Deathknell.",["title"]="Shari Stilwell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91209:description:1-202","91209:objective:1-67","91209:completion:1-106"},["minimumStage"]=4,["questID"]=91209,["sourceHash"]="b939cb8b64d1d4f18a23d8a87712bea8124880a49e4c6e8e831d26d2904e21df"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-246152",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91209",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She encouraged service to Brill’s people as a way to grow stronger in the Light before the next stage of a paladin’s journey.",["title"]="Shari Stilwell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91282:description:1-227","91282:objective:1-61"},["minimumStage"]=2,["questID"]=91282,["sourceHash"]="8c3e360bdceec11c0bdce30870409a48a00db32e2b277119245a2b2230c2c718"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-246349",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91282",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Breton received new arrivals at the paladins’ monastery of Bandarion Keep.",["title"]="Breton Samuels"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91282:description:1-227","91282:objective:1-61","91282:completion:1-46"},["minimumStage"]=4,["questID"]=91282,["sourceHash"]="8c3e360bdceec11c0bdce30870409a48a00db32e2b277119245a2b2230c2c718"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-246349",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91282",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He welcomed recruits into Tyr’s Watch, the new community formed around shared faith in Tirisfal.",["title"]="Breton Samuels"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91294:description:1-268","91294:objective:1-66"},["minimumStage"]=2,["questID"]=91294,["sourceHash"]="0630c919d46210f712ccbdaaf94dec618adcecdfd98211b8a2f948737a82d4c9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-246378",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91294",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Danitha led the growing stronghold at Bandarion Keep.",["title"]="Danitha Morr"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91294:description:1-268","91294:objective:1-66","91294:completion:1-113"},["minimumStage"]=4,["questID"]=91294,["sourceHash"]="0630c919d46210f712ccbdaaf94dec618adcecdfd98211b8a2f948737a82d4c9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-246378",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91294",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She sought fellowship among those still loyal to the Light and willing help with the work needed to establish their home.",["title"]="Danitha Morr"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91316:description:1-212","91316:objective:1-71"},["minimumStage"]=2,["questID"]=91316,["sourceHash"]="5614ce931b65a2e78930fb0c188e85835c10774421851ca82f00daaec807d77d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-246393",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91316",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jorin faced a shortage of building materials because supplying the distant fortress from the Undercity was difficult.",["title"]="Jorin Croge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91316:description:1-212","91316:objective:1-71"},["minimumStage"]=2,["questID"]=91316,["sourceHash"]="5614ce931b65a2e78930fb0c188e85835c10774421851ca82f00daaec807d77d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-246393",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91316",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought salvage from Shadowvale’s old root cellar to help repair the keep rather than wait on unreliable logistics.",["title"]="Jorin Croge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91858:description:1-241","91858:objective:1-61"},["minimumStage"]=2,["questID"]=91858,["sourceHash"]="d942070c29472e96120c9254390773f26818112b8379230e85cd6253a763244e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-248840",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91858",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Trevan served as the paladins’ contact at the Sepulcher during the search for missing Earthen Ring travelers.",["title"]="Trevan Rol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91859:description:1-214","91859:objective:1-50"},["minimumStage"]=2,["questID"]=91859,["sourceHash"]="e5fda2df523107e8a0ca2c86ad9687c3a2482c5fd9a8291f8092995b33c0833e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-248840",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91859",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He reported seeing a tauren with someone he believed was a cloaked high elf, while admitting he could not explain the unusual partnership.",["title"]="Trevan Rol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91859:description:1-214","91859:objective:1-50","91859:completion:1-96"},["minimumStage"]=4,["questID"]=91859,["sourceHash"]="e5fda2df523107e8a0ca2c86ad9687c3a2482c5fd9a8291f8092995b33c0833e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-259611",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91859",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Baldren openly expressed dislike for paladins but acknowledged that their arrival during the travelers’ disappearance was timely.",["title"]="Deathguard Baldren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91861:description:1-157","91861:objective:1-70","91861:completion:1-90"},["minimumStage"]=4,["questID"]=91861,["sourceHash"]="624b234597dcc67673936062ea22ffbd46a2e47466d95f06f8759c65b0e91fb4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-248755",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91861",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lumina was found captive inside Fenris Keep and urgently asked a Forsaken visitor to help free her.",["title"]="Lumina Windsinger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91920:description:1-188","91920:objective:1-66"},["minimumStage"]=2,["questID"]=91920,["sourceHash"]="68598697fdeda6adcc123a3ccc22e70120c4d987533b3e029474a898e9aae4c2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-1951",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91920",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Quinn said Renferrel’s potion had made no noticeable difference and feared either dying again or offending the apothecary.",["title"]="Quinn Yorick"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"91920:description:1-188","91920:objective:1-66"},["minimumStage"]=2,["questID"]=91920,["sourceHash"]="68598697fdeda6adcc123a3ccc22e70120c4d987533b3e029474a898e9aae4c2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1951",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91920",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He proposed murloc eyes as an alternative ingredient, hoping experimentation might succeed where the heart-based formula had not.",["title"]="Quinn Yorick"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92401:description:1-239","92401:objective:1-79"},["minimumStage"]=2,["questID"]=92401,["sourceHash"]="411211e25cb4c260482a647f46bc0a32c90126a6ebab23d80e9991966e7a9637"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-250686",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92401",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tabitha’s husband Edward visited the Lordaeron graveyard each week, still grieving the son they lost when Arthas razed the city.",["title"]="Tabitha Heartweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92401:description:1-239","92401:objective:1-79"},["minimumStage"]=2,["questID"]=92401,["sourceHash"]="411211e25cb4c260482a647f46bc0a32c90126a6ebab23d80e9991966e7a9637"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-250686",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92401",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She feared the overrun ruins and pleaded for news when Edward failed to return for days, but could not safely search herself.",["title"]="Tabitha Heartweaver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92421:description:1-220","92421:objective:1-75"},["minimumStage"]=2,["questID"]=92421,["sourceHash"]="9149b74021e961763bff43b18748b6b92b7c417e4e80ebff08f84438105af524"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-266484",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92421",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Morbin understood a Forsaken paladin’s duty as serving the Dark Lady while tending the needs of their people.",["title"]="Morbin Lightbane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92421:description:1-220","92421:objective:1-75"},["minimumStage"]=2,["questID"]=92421,["sourceHash"]="9149b74021e961763bff43b18748b6b92b7c417e4e80ebff08f84438105af524"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-266484",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92421",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought intact replacement limbs for decaying bodies, hoping to continue Captain Bandarion’s work of healing their kin while opposing the Scourge above the Undercity.",["title"]="Morbin Lightbane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92514:description:1-234","92514:objective:1-83"},["minimumStage"]=2,["questID"]=92514,["sourceHash"]="2ceb4e3cede6aa1649356c8a5aea2847a4fa4c4b68cbd907f77fab2697946bca"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-251523",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92514",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aonda said she recognized spirit-touched visitors by a faint sensation of static, associating it with the Windshapers.",["title"]="Constable Aonda"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92514:description:1-234","92514:objective:1-83","92514:completion:1-215"},["minimumStage"]=4,["questID"]=92514,["sourceHash"]="2ceb4e3cede6aa1649356c8a5aea2847a4fa4c4b68cbd907f77fab2697946bca"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-251523",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92514",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted Shen’dar’s defenders to put larger dangers before the tension between the High Order and Windshapers, keeping both groups civil within the village.",["title"]="Constable Aonda"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92515:description:1-200","92515:objective:1-71"},["minimumStage"]=2,["questID"]=92515,["sourceHash"]="0f58440c724410717f95f0b321a2bfa67a4b22544ecd81e10bf92132a329bae8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-251993",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92515",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Indari wanted prideclaw numbers reduced before the increasingly bold animals took a villager’s child or pet.",["title"]="Indari Sunseam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92515:description:1-200","92515:objective:1-71"},["minimumStage"]=2,["questID"]=92515,["sourceHash"]="0f58440c724410717f95f0b321a2bfa67a4b22544ecd81e10bf92132a329bae8"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-251993",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92515",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She could turn their pelts into useful goods, joining the protective hunt with the village’s material needs.",["title"]="Indari Sunseam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92516:description:1-205","92516:objective:1-83"},["minimumStage"]=2,["questID"]=92516,["sourceHash"]="152e3d40f9163128bfcd675c50f87c05aa9393148a59cc016b6eb5cb97afdbd7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-251906",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92516",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Teeri reported a new hippogryph nesting ground southeast of Shen’dar, whose flock was endangering travelers on the road.",["title"]="Teeri Wellwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92528:description:1-247","92528:objective:1-90"},["minimumStage"]=2,["questID"]=92528,["sourceHash"]="1a3b98043ea3af2b7dd5f273d3f190905f0ca96c08788133d3d706a85f9630de"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-257065",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92528",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jasaan received recruits among Al’Akir’s faithful at Falaath Village.",["title"]="Missionary Jasaan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92528:description:1-247","92528:objective:1-90"},["minimumStage"]=2,["questID"]=92528,["sourceHash"]="1a3b98043ea3af2b7dd5f273d3f190905f0ca96c08788133d3d706a85f9630de"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-257065",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92528",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He ordinarily sent newcomers to Skypriest Aanders for assessment, but barred an unpolished recruit from disturbing the priest’s important guest.",["title"]="Missionary Jasaan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92529:description:1-266","92529:objective:1-57"},["minimumStage"]=2,["questID"]=92529,["sourceHash"]="633db4e37bdcb21f12a329db3696d75d99c1583928c6d30deadfa04e76c45624"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-251904",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92529",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sania blamed her people’s lost bond with the winds on pride and complacency, teaching contrition as the way to regain the spirits’ favor.",["title"]="Sania Silverstream"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92529:description:1-266","92529:objective:1-57"},["minimumStage"]=2,["questID"]=92529,["sourceHash"]="633db4e37bdcb21f12a329db3696d75d99c1583928c6d30deadfa04e76c45624"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-251904",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92529",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She marked prospective Al’Akir worshipers so Jasaan and the faithful at Falaath would recognize them as recruits.",["title"]="Sania Silverstream"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92551:description:1-245","92551:objective:1-64"},["minimumStage"]=2,["questID"]=92551,["sourceHash"]="ef9dfb838dc8627d74e00ac7f202ce3ce957769e2dcf7b788bcd7afb04652a08"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-252172",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92551",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Danarii blamed months of missing caravan goods on Al’Aketh raids, rejecting the cult’s attempts to shift responsibility to bandits.",["title"]="Danarii Bellowveil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92551:description:1-245","92551:objective:1-64","92551:completion:1-177"},["minimumStage"]=4,["questID"]=92551,["sourceHash"]="ef9dfb838dc8627d74e00ac7f202ce3ce957769e2dcf7b788bcd7afb04652a08"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-252172",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92551",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Recovered food and windstones were to be redistributed with the constable’s help to Shen’dar’s people in greatest need.",["title"]="Danarii Bellowveil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92553:description:1-225","92553:objective:1-83"},["minimumStage"]=2,["questID"]=92553,["sourceHash"]="6997ceaae9f39a7f0b68362e3c7bb920878ff44a7855197c296da257494a94b7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-251905",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92553",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zerril provisioned Shen’dar with food and offered cooking lessons in exchange for fresh ingredients.",["title"]="Zerril Softbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92553:description:1-225","92553:objective:1-83"},["minimumStage"]=2,["questID"]=92553,["sourceHash"]="6997ceaae9f39a7f0b68362e3c7bb920878ff44a7855197c296da257494a94b7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-251905",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92553",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Growing danger left the villagers little time to hunt or forage, forcing him to seek outside help restocking eggs and strider meat.",["title"]="Zerril Softbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92595:description:1-195","92595:objective:1-83"},["minimumStage"]=2,["questID"]=92595,["sourceHash"]="47865ded0bab06eb5d9767e72362a3f2a8c98b200ffcfb39c98997d65e7b5ec6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-251902",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92595",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Illaya recognized skysight as a gift that could occur even in those who had not trained as shamans.",["title"]="Illaya Amberwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92595:description:1-195","92595:objective:1-83","92595:completion:1-266"},["minimumStage"]=4,["questID"]=92595,["sourceHash"]="47865ded0bab06eb5d9767e72362a3f2a8c98b200ffcfb39c98997d65e7b5ec6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-251902",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92595",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted every gifted soul’s help restoring dialogue with the winds so the Shen’dorei could survive threats within Zephras and uncertainty about their safety in Skywall.",["title"]="Illaya Amberwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92679:description:1-205","92679:objective:1-78"},["minimumStage"]=2,["questID"]=92679,["sourceHash"]="8fc290fa14444e412a94a626a549e255432027480928847a0c1028b6b761661b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-252448",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92679",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alvarion reached Valanaar in severe pain while seeking fighters to help save his farm.",["title"]="Alvarion Windfield"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92679:description:1-205","92679:objective:1-78"},["minimumStage"]=2,["questID"]=92679,["sourceHash"]="8fc290fa14444e412a94a626a549e255432027480928847a0c1028b6b761661b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-252448",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92679",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent potential helpers to his wife Aamelia at their orchard west of the city in the lowlands.",["title"]="Alvarion Windfield"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92679:description:1-205","92679:objective:1-78","92679:completion:1-213"},["minimumStage"]=4,["questID"]=92679,["sourceHash"]="8fc290fa14444e412a94a626a549e255432027480928847a0c1028b6b761661b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-252800",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92679",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aamelia was relieved her husband would be safe in Valanaar but feared his request had sent an outsider into mortal danger for nothing.",["title"]="Aamelia Windfield"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92679:description:1-205","92679:objective:1-78","92679:completion:1-213"},["minimumStage"]=4,["questID"]=92679,["sourceHash"]="8fc290fa14444e412a94a626a549e255432027480928847a0c1028b6b761661b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-252800",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92679",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She urged the would-be helper to leave rather than pretend the farm’s struggle was worth a stranger’s life.",["title"]="Aamelia Windfield"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92698:description:1-201","92698:objective:1-73"},["minimumStage"]=2,["questID"]=92698,["sourceHash"]="9c4d7025af84a3736cc152b989edf94603f838ae84037f481d0cada24dad9e3f"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="npc-250929",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92698",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The giant construct’s armor plates covered a voice repeating fragmented errors and questions about its own function.",["title"]="Malfunctioning Cyclone Construct"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92698:description:1-201","92698:objective:1-73","92698:completion:1-251"},["minimumStage"]=4,["questID"]=92698,["sourceHash"]="9c4d7025af84a3736cc152b989edf94603f838ae84037f481d0cada24dad9e3f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="npc-250929",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92698",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aamelia remembered it wandering the fields for decades, dating that aimlessness to the departure of the wind elementals.",["title"]="Malfunctioning Cyclone Construct"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92698:description:1-201","92698:objective:1-73","92698:completion:1-251"},["minimumStage"]=4,["questID"]=92698,["sourceHash"]="9c4d7025af84a3736cc152b989edf94603f838ae84037f481d0cada24dad9e3f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-250929",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92698",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Its former work hauling crops or tending livestock remained Alvarion’s guess. The firmer lead was the Windshapers’ old responsibility for maintaining such constructs.",["title"]="Malfunctioning Cyclone Construct"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92706:description:1-186","92706:objective:1-54"},["minimumStage"]=2,["questID"]=92706,["sourceHash"]="1bcc48b41c9f842cc0940b051f626ff7fc82f7b74d7fc7aa626db8648d1255d1"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-209797",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92706",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bruuz was a giant shark named by the frightened dockworkers.",["title"]="Bruuz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92706:description:1-186","92706:objective:1-54"},["minimumStage"]=2,["questID"]=92706,["sourceHash"]="1bcc48b41c9f842cc0940b051f626ff7fc82f7b74d7fc7aa626db8648d1255d1"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-209797",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92706",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="It circled Ratchet’s shipping dock and attacked sailors and small boats, leading Gazlowe to offer a bounty for its fin.",["title"]="Bruuz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93165:description:1-197","93165:objective:1-57"},["minimumStage"]=2,["questID"]=93165,["sourceHash"]="575bb52ecf51516cc957f76234bf17702fbe0a3359398ec8e7c48d9bb11fcf11"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-254151",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93165",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vayn sought vengeance for the tragedy the Al’Aketh brought upon the Nightclaw enclave.",["title"]="Vayn Moongaze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93165:description:1-197","93165:objective:1-57"},["minimumStage"]=2,["questID"]=93165,["sourceHash"]="575bb52ecf51516cc957f76234bf17702fbe0a3359398ec8e7c48d9bb11fcf11"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-254151",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93165",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered payment for cultist ears and promised access to the Nightclaw’s secrets only after a helper earned deeper trust.",["title"]="Vayn Moongaze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93317:description:1-218","93317:objective:1-63"},["minimumStage"]=2,["questID"]=93317,["sourceHash"]="8b5272da953e9d72cf70640ab9d9d17438817394200759d884ef64a18967f019"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-257006",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93317",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nyalah needed Windsong crawler meat before the brief annual harvest window closed, but cult activity had prevented her from reaching the lake.",["title"]="Nyalah Brightfire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93317:description:1-218","93317:objective:1-63"},["minimumStage"]=2,["questID"]=93317,["sourceHash"]="8b5272da953e9d72cf70640ab9d9d17438817394200759d884ef64a18967f019"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-257006",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93317",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She warned that the crabs were more aggressive than they appeared and could be found along the lake’s shores and river waters.",["title"]="Nyalah Brightfire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93317:description:1-218","93317:objective:1-63"},["minimumStage"]=2,["questID"]=93317,["sourceHash"]="8b5272da953e9d72cf70640ab9d9d17438817394200759d884ef64a18967f019"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-254588",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93317",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Windsong crawlers were crabs whose meat supplied a valued seasonal food.",["title"]="Windsong Crawler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93317:description:1-218","93317:objective:1-63"},["minimumStage"]=2,["questID"]=93317,["sourceHash"]="8b5272da953e9d72cf70640ab9d9d17438817394200759d884ef64a18967f019"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-254588",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93317",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nyalah described them as native to Windsong Lake, occurring along its shore and in rivers.",["title"]="Windsong Crawler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93317:description:1-218","93317:objective:1-63"},["minimumStage"]=2,["questID"]=93317,["sourceHash"]="8b5272da953e9d72cf70640ab9d9d17438817394200759d884ef64a18967f019"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-254588",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93317",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Their harvest was limited to a few weeks of the year in Nyalah’s account, making travel delayed by cult activity a threat to the season’s supply.",["title"]="Windsong Crawler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92515:description:1-200","92515:objective:1-71"},["minimumStage"]=2,["questID"]=92515,["sourceHash"]="0f58440c724410717f95f0b321a2bfa67a4b22544ecd81e10bf92132a329bae8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-251245",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92515",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Indari reported prideclaws pressing closer to Shen’dar’s borders and feared they would soon take a pet or child.",["title"]="Prideclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92515:description:1-200","92515:objective:1-71"},["minimumStage"]=2,["questID"]=92515,["sourceHash"]="0f58440c724410717f95f0b321a2bfa67a4b22544ecd81e10bf92132a329bae8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-251245",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92515",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Their pelts could be made into useful village goods, giving a protective hunt a second practical purpose.",["title"]="Prideclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92516:description:1-205","92516:objective:1-83"},["minimumStage"]=2,["questID"]=92516,["sourceHash"]="152e3d40f9163128bfcd675c50f87c05aa9393148a59cc016b6eb5cb97afdbd7"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-251261",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92516",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A hippogryph matriarch was among the flock nesting southeast of Shen’dar and troubling traffic on the road.",["title"]="Hippogryph Matriarch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93926:description:1-197","93926:objective:1-89"},["minimumStage"]=2,["questID"]=93926,["sourceHash"]="79cda27e20b99f1fdbc582f661a1fffb244cf38a38b213e9392c473d53a49f6f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-252155",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93926",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vaaniel commanded the peacekeepers at the western watchtower.",["title"]="Peacekeeper Vaaniel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"93926:description:1-197","93926:objective:1-89","93926:completion:1-174"},["minimumStage"]=4,["questID"]=93926,["sourceHash"]="79cda27e20b99f1fdbc582f661a1fffb244cf38a38b213e9392c473d53a49f6f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="npc-252155",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93926",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The withdrawal message reached a recently killed peacekeeper whose burned skin pointed to the cult’s storm-wielding attackers, rather than a surviving commander able to retreat.",["title"]="Peacekeeper Vaaniel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93951:description:1-217","93951:objective:1-73"},["minimumStage"]=2,["questID"]=93951,["sourceHash"]="88eb242423d2c6c58f1ebc4ad43fcdcfb61600c3158349bbef7c5295e5d81032"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-251991",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93951",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Taleen gathered the vibrant, silky down shed around hippogryph nests for the feather adornments many Skyborne wore in their hair.",["title"]="Taleen Shimmerthread"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"93951:description:1-217","93951:objective:1-73","93951:completion:1-141"},["minimumStage"]=4,["questID"]=93951,["sourceHash"]="88eb242423d2c6c58f1ebc4ad43fcdcfb61600c3158349bbef7c5295e5d81032"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-251991",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93951",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She considered small joys worth preserving even in dangerous times, valuing an ornament by the happiness it brought its wearer.",["title"]="Taleen Shimmerthread"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94006:description:1-262","94006:objective:1-49"},["minimumStage"]=2,["questID"]=94006,["sourceHash"]="793f66b0ea6a25d0aa8474786222dce997f7a531994cc250d8e948db3381dc75"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-252359",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94006",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lotheluum guided advancing druids toward Zephras’s great spirits for further instruction.",["title"]="Lotheluum Starbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94006:description:1-262","94006:objective:1-49"},["minimumStage"]=2,["questID"]=94006,["sourceHash"]="793f66b0ea6a25d0aa8474786222dce997f7a531994cc250d8e948db3381dc75"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-252359",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94006",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned that Urs’endris’s domain was withering and falling into the sky, sharing the danger faced by other parts of the island.",["title"]="Lotheluum Starbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94006:description:1-262","94006:objective:1-49"},["minimumStage"]=2,["questID"]=94006,["sourceHash"]="793f66b0ea6a25d0aa8474786222dce997f7a531994cc250d8e948db3381dc75"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-255853",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94006",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Urs’endris was a wise spirit credited with teaching druids the ursera shape for generations.",["title"]="Urs'endris"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94006:description:1-262","94006:objective:1-49"},["minimumStage"]=2,["questID"]=94006,["sourceHash"]="793f66b0ea6a25d0aa8474786222dce997f7a531994cc250d8e948db3381dc75"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="npc-255853",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94006",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The spirit could be found near the falls northeast of Valanaar, beneath the Shrine of Akir’s shadow.",["title"]="Urs'endris"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94427:description:1-190","94427:objective:1-60","94427:completion:1-99"},["minimumStage"]=4,["questID"]=94427,["sourceHash"]="5abbdda6171afac990672ec346cf64859133d55d28ba509772aaaefc9f04e4f3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-257648",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94427",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tanis feared a visiting paladin would punish their panhandling and pleaded to be left unharmed.",["title"]="Tanis Alderwood"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94436:description:1-171","94436:objective:1-68","94436:completion:1-95"},["minimumStage"]=4,["questID"]=94436,["sourceHash"]="c8beb092836ab9b86e8c910d4ef50f8ed0bd54970fc7f368b3f0af2ac57e1a9b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-257655",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94436",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Billmuth overcame reluctance to ask paladins for help because the priests had turned him away and his friend might have no other chance.",["title"]="Deathguard Billmuth"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94438:description:1-252","94438:objective:1-72","94438:completion:1-136"},["minimumStage"]=4,["questID"]=94438,["sourceHash"]="9140f448f8c2ceaf690d6b6ba87ac040537d82087b60807693d1e220ff7f884e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="npc-257663",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94438",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Falgan returned through the Symbol of Life and recalled the talisman from Lordaeron before the war.",["title"]="Deathguard Falgan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94438:description:1-252","94438:objective:1-72","94438:completion:1-136"},["minimumStage"]=4,["questID"]=94438,["sourceHash"]="9140f448f8c2ceaf690d6b6ba87ac040537d82087b60807693d1e220ff7f884e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-257663",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94438",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He and Billmuth had uncovered Scarlet plans for an attack, leaving further danger to address after his rescue.",["title"]="Deathguard Falgan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94484:description:1-252","94484:objective:1-74"},["minimumStage"]=2,["questID"]=94484,["sourceHash"]="1251adecd3205c9ed758e11ab257f3618fa4129578893b590ab74a0037339b91"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-257944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94484",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Elegael belonged to a druid conclave in a cave in northeastern Shadowgale Forest.",["title"]="Elegael Thornpaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94484:description:1-252","94484:objective:1-74","94484:completion:1-198"},["minimumStage"]=4,["questID"]=94484,["sourceHash"]="1251adecd3205c9ed758e11ab257f3618fa4129578893b590ab74a0037339b91"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-257944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94484",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The conclave’s message had failed to reach Lotheluum, leaving Elegael horrified to learn that no larger relief force was coming.",["title"]="Elegael Thornpaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94896:description:1-211","94896:objective:1-78"},["minimumStage"]=2,["questID"]=94896,["sourceHash"]="eae96429816b73bf3a5c81af51ce912f6d875684d4ff28076520cbb4abc926ba"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="npc-259012",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94896",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ealaane’s community fled Ban’aethal in the middle of the night when their home suddenly began falling into the sky.",["title"]="Ealaane Nimbuswalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94896:description:1-211","94896:objective:1-78","94896:completion:1-126"},["minimumStage"]=4,["questID"]=94896,["sourceHash"]="eae96429816b73bf3a5c81af51ce912f6d875684d4ff28076520cbb4abc926ba"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-259012",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94896",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Salvaged belongings were to be returned to the displaced owners as a first foothold for starting over.",["title"]="Ealaane Nimbuswalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95042:description:1-175","95042:objective:1-63"},["minimumStage"]=2,["questID"]=95042,["sourceHash"]="6990c857f2531f7af90d781fded65c6a6f64f88624bdec11be76d0d5403d097d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-259649",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95042",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ulric knew Kor Gems were used to empower paladin weapons and directed the search toward the naga in Blackfathom.",["title"]="Ulric Frostveil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"95042:description:1-175","95042:objective:1-63","95042:completion:1-190"},["minimumStage"]=4,["questID"]=95042,["sourceHash"]="6990c857f2531f7af90d781fded65c6a6f64f88624bdec11be76d0d5403d097d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-259649",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95042",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Though he considered their corruption simple to cleanse, he coveted the naga-infused magic for his own studies and offered to buy the gem instead.",["title"]="Ulric Frostveil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95111:description:1-196","95111:objective:1-75"},["minimumStage"]=2,["questID"]=95111,["sourceHash"]="5b5cbbd820646c3cacb35a36ee8dc7833f38c67d565a4ad806c8d76f11ac1b13"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3539",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95111",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ott made apparently ordinary blades in Tarren Mill whose quality surprised the Undercity smiths who later serviced one.",["title"]="Ott"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"95111:description:1-196","95111:objective:1-75","95111:completion:1-181"},["minimumStage"]=4,["questID"]=95111,["sourceHash"]="5b5cbbd820646c3cacb35a36ee8dc7833f38c67d565a4ad806c8d76f11ac1b13"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-3539",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95111",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described his own work as humble and functional, seeking neither praise nor glory, and was surprised to be offered a custom commission.",["title"]="Ott"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"95213:description:1-202","95213:objective:1-76","95213:completion:1-101"},["minimumStage"]=4,["questID"]=95213,["sourceHash"]="de4a06c040bc03b6d5c0d3704c523443e812587729537d9f957eedcf78da9fb6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-1256",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95213",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="An empty blasting-powder keg recovered from trogg hands visibly alarmed Thesten, who immediately demanded to know where it was found.",["title"]="Quarrymaster Thesten"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95216:description:1-183","95216:objective:1-73"},["minimumStage"]=2,["questID"]=95216,["sourceHash"]="96a4b1058b39c8fe3378bc00b9267b68256d59ec4c70f4c2be70f89e88ce7f17"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-11835",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95216",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theodore studied unusually virulent specimens in the Undercity’s Apothecarium.",["title"]="Theodore Griffs"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95216:description:1-183","95216:objective:1-73"},["minimumStage"]=2,["questID"]=95216,["sourceHash"]="96a4b1058b39c8fe3378bc00b9267b68256d59ec4c70f4c2be70f89e88ce7f17"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-11835",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95216",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted to validate reports that a venomous arthropod above the city could eat through undead flesh, treating the prospect with scientific excitement rather than caution.",["title"]="Theodore Griffs"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95314:description:1-187","95314:objective:1-82"},["minimumStage"]=2,["questID"]=95314,["sourceHash"]="477de7f18b673aaad5960f7d0f942b27c8f44f6ca580187d0285c19fd784923c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="npc-2132",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95314",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Carolai remembered Shadowvale’s Whispering Elixir as a banned but sought-after distillation of herbs unique to Tyr’s Fall.",["title"]="Carolai Anise"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95314:description:1-187","95314:objective:1-82"},["minimumStage"]=2,["questID"]=95314,["sourceHash"]="477de7f18b673aaad5960f7d0f942b27c8f44f6ca580187d0285c19fd784923c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-2132",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95314",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Requests from buyers led her to pay for bottles recovered from the village’s ruins despite its reputation for unsettling secrecy.",["title"]="Carolai Anise"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96101:description:1-207","96101:objective:1-76"},["minimumStage"]=2,["questID"]=96101,["sourceHash"]="2be0e59202ad10fb50f2594b2b947eb29e5f2b19e9c91d5ed85a9cc30fac34e7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-263664",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96101",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Raan taught aspiring adventurers how to thrive outdoors, beginning with rest beside a campfire.",["title"]="Raan Wildwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"96101:description:1-207","96101:objective:1-76","96101:completion:1-123"},["minimumStage"]=4,["questID"]=96101,["sourceHash"]="2be0e59202ad10fb50f2594b2b947eb29e5f2b19e9c91d5ed85a9cc30fac34e7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-263664",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96101",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He connected further camping knowledge with tradeskill teachers who could provide a fixture suited to a chosen profession.",["title"]="Raan Wildwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96390:description:1-173","96390:objective:1-45"},["minimumStage"]=2,["questID"]=96390,["sourceHash"]="3caddb431254f653f19f1342acc7dc5a8989a0483d66d925f344e591fe8559e5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-264936",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96390",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Farsen wanted Dark Iron infiltrators stopped at Ironband’s Compound before their still-unknown purpose could develop.",["title"]="Earthseer Farsen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"96390:description:1-173","96390:objective:1-45","96390:completion:1-144"},["minimumStage"]=4,["questID"]=96390,["sourceHash"]="3caddb431254f653f19f1342acc7dc5a8989a0483d66d925f344e591fe8559e5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-264936",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96390",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He regarded their kinship with the dwarves as no reason to tolerate further incursions into Dun Morogh.",["title"]="Earthseer Farsen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96403:description:1-204","96403:objective:1-75"},["minimumStage"]=2,["questID"]=96403,["sourceHash"]="445fe01c13cfefae696bca6c5f6973532240c623c8080f4441d9e6ab643764ba"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-265003",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96403",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thom claimed to have been patrolling the vaults when Dark Irons emerged in mole machines, repeatedly correcting references to valuable loot into talk of cultural heirlooms.",["title"]="Thom Filch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96403:description:1-204","96403:objective:1-75"},["minimumStage"]=2,["questID"]=96403,["sourceHash"]="445fe01c13cfefae696bca6c5f6973532240c623c8080f4441d9e6ab643764ba"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-265003",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96403",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He promised to catalog recovered relics and return them to places of honor; that was an assurance, not an independently established outcome.",["title"]="Thom Filch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96408:description:1-179","96408:objective:1-66"},["minimumStage"]=2,["questID"]=96408,["sourceHash"]="a75668f7265cefdd08e9f2ef9c68c0b2bb6a48c39da3632013a455c5156f1885"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1376",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96408",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Beldin sought an investigation of a newly noticed campfire high above Gol’Bolar Quarry, allowing for the possibility that its occupants were friendly.",["title"]="Beldin Steelgrill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91282:description:1-227","91282:objective:1-61"},["minimumStage"]=2,["questID"]=91282,["sourceHash"]="8c3e360bdceec11c0bdce30870409a48a00db32e2b277119245a2b2230c2c718"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="bandarion-keep",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91282",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The monastery at Northface Rock offered Tirisfal’s newly risen paladins a community built around shared faith.",["title"]="Bandarion Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91316:description:1-212","91316:objective:1-71"},["minimumStage"]=2,["questID"]=91316,["sourceHash"]="5614ce931b65a2e78930fb0c188e85835c10774421851ca82f00daaec807d77d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="bandarion-keep",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91316",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Its distance from the Undercity made supplies difficult to obtain, leaving restoration work short of building materials.",["title"]="Bandarion Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"95314:description:1-187","95314:objective:1-82"},["minimumStage"]=2,["questID"]=95314,["sourceHash"]="477de7f18b673aaad5960f7d0f942b27c8f44f6ca580187d0285c19fd784923c"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="shadowvale",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95314",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Before the Scourge invasion, the secluded village was known for Whispering Elixir, sought by apothecaries, mystics and poisoners despite its ban in the city.",["title"]="Shadowvale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"91316:description:1-212","91316:objective:1-71"},["minimumStage"]=2,["questID"]=91316,["sourceHash"]="5614ce931b65a2e78930fb0c188e85835c10774421851ca82f00daaec807d77d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="shadowvale",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/91316",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A ruined building’s old root cellar held salvage Jorin hoped could supply repairs at Bandarion.",["title"]="Shadowvale"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"95314:description:1-187","95314:objective:1-82"},["minimumStage"]=2,["questID"]=95314,["sourceHash"]="477de7f18b673aaad5960f7d0f942b27c8f44f6ca580187d0285c19fd784923c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="whispering-forest",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95314",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shadowvale’s isolated community deep in the forest had been secretive and unwelcoming to visitors in Carolai’s recollection.",["title"]="Whispering Forest"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"95314:description:1-187","95314:objective:1-82","95314:completion:1-164"},["minimumStage"]=4,["questID"]=95314,["sourceHash"]="477de7f18b673aaad5960f7d0f942b27c8f44f6ca580187d0285c19fd784923c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="whispering-forest",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95314",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rumors linked the forest’s alleged curse with its distilled elixir, but Carolai dismissed the warning rather than establish whether the belief was true.",["title"]="Whispering Forest"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92514:description:1-234","92514:objective:1-83","92514:completion:1-215"},["minimumStage"]=4,["questID"]=92514,["sourceHash"]="2ceb4e3cede6aa1649356c8a5aea2847a4fa4c4b68cbd907f77fab2697946bca"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="shendar-village",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92514",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The High Order and Windshapers maintained civil relations here despite their tensions, recognizing dangers larger than their disagreements.",["title"]="Shen'dar Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92551:description:1-245","92551:objective:1-64"},["minimumStage"]=2,["questID"]=92551,["sourceHash"]="ef9dfb838dc8627d74e00ac7f202ce3ce957769e2dcf7b788bcd7afb04652a08"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="shendar-village",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92551",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Repeated caravan raids disrupted shipments of food and windstones, which Danarii blamed on the Al’Aketh despite their denials.",["title"]="Shen'dar Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92529:description:1-266","92529:objective:1-57"},["minimumStage"]=2,["questID"]=92529,["sourceHash"]="633db4e37bdcb21f12a329db3696d75d99c1583928c6d30deadfa04e76c45624"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="falaath-village",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92529",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jasaan welcomed those bearing Sania’s mark as recruits among Al’Akir’s faithful.",["title"]="Falaath Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92528:description:1-247","92528:objective:1-90","92528:completion:1-209"},["minimumStage"]=4,["questID"]=92528,["sourceHash"]="1a3b98043ea3af2b7dd5f273d3f190905f0ca96c08788133d3d706a85f9630de"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="falaath-village",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92528",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The investigation placed Lorthuna herself among the cultists and revealed plans against Shen’dar and the western watchtower.",["title"]="Falaath Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92679:description:1-205","92679:objective:1-78"},["minimumStage"]=2,["questID"]=92679,["sourceHash"]="8fc290fa14444e412a94a626a549e255432027480928847a0c1028b6b761661b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="windfield-orchard",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92679",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alvarion sought fighters in Valanaar while Aamelia remained at the threatened orchard west of the city.",["title"]="Windfield Orchard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92698:description:1-201","92698:objective:1-73","92698:completion:1-251"},["minimumStage"]=4,["questID"]=92698,["sourceHash"]="9c4d7025af84a3736cc152b989edf94603f838ae84037f481d0cada24dad9e3f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="windfield-orchard",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92698",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aamelia recalled an aimless cyclone construct roaming the fields for decades after the wind elementals left; its earlier agricultural duties remained conjecture.",["title"]="Windfield Orchard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"93317:description:1-218","93317:objective:1-63"},["minimumStage"]=2,["questID"]=93317,["sourceHash"]="8b5272da953e9d72cf70640ab9d9d17438817394200759d884ef64a18967f019"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16625",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93317",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The local crawler harvest lasted only a few weeks each year in Nyalah’s account, making cult-blocked travel a threat to a prized seasonal food.",["title"]="Windsong Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"92516:description:1-205","92516:objective:1-83"},["minimumStage"]=2,["questID"]=92516,["sourceHash"]="152e3d40f9163128bfcd675c50f87c05aa9393148a59cc016b6eb5cb97afdbd7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16623",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92516",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="New hippogryph nesting grounds southeast of Shen’dar troubled road travelers, while the villagers were already pressed by other dangers.",["title"]="Shen'dar Highlands"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94484:description:1-252","94484:objective:1-74"},["minimumStage"]=2,["questID"]=94484,["sourceHash"]="1251adecd3205c9ed758e11ab257f3618fa4129578893b590ab74a0037339b91"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="shadowgale-forest",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94484",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A druid conclave occupied a northeastern cave, but missing correspondence left Lotheluum unsure whether the community remained safe.",["title"]="Shadowgale Forest"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94896:description:1-211","94896:objective:1-78"},["minimumStage"]=2,["questID"]=94896,["sourceHash"]="eae96429816b73bf3a5c81af51ce912f6d875684d4ff28076520cbb4abc926ba"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-16833",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94896",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The villagers evacuated suddenly in the middle of the night when their home began falling into the sky.",["title"]="Ruins of Ban'aethal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94896:description:1-211","94896:objective:1-78"},["minimumStage"]=2,["questID"]=94896,["sourceHash"]="eae96429816b73bf3a5c81af51ce912f6d875684d4ff28076520cbb4abc926ba"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16833",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94896",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Abandoned possessions remained among the ruins, valuable to refugees who could no longer safely return for them.",["title"]="Ruins of Ban'aethal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"94006:description:1-262","94006:objective:1-49"},["minimumStage"]=2,["questID"]=94006,["sourceHash"]="793f66b0ea6a25d0aa8474786222dce997f7a531994cc250d8e948db3381dc75"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-16629",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94006",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The waterfall northeast of Valanaar lay in the shrine’s shadow, near the threatened domain of Urs’endris.",["title"]="Shrine of Akir"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96604:description:1-155","96604:objective:1-67"},["minimumStage"]=2,["questID"]=96604,["sourceHash"]="c8f56e66617bc1a682aa3e07f4c7a1e6f2a8da1e25360054e764a2dd9f86b63e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-265809",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96604",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brakk taught new adventurers the outdoor skills needed to survive beyond settled roads, beginning with rest around a campfire.",["title"]="Brakk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96605:description:1-175","96605:objective:1-76"},["minimumStage"]=2,["questID"]=96605,["sourceHash"]="8dacba607661cca6ef471c5de24561b4a7c4e581d6571fd729152c502c02ac26"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-265810",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96605",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kaga offered practical wilderness instruction to restless travelers seeking fortune and glory.",["title"]="Kaga Wildhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96658:description:1-146","96658:objective:1-62"},["minimumStage"]=2,["questID"]=96658,["sourceHash"]="112179247ec2ea87c334bcddcafbe10d27ea6a1a344f5b329fc3beeaaf102eb6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-265944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96658",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="William taught cooking and the basic firecraft that formed the foundation of an adventurer’s camp.",["title"]="William Pickman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"96658:description:1-146","96658:objective:1-62","96658:completion:1-155"},["minimumStage"]=4,["questID"]=96658,["sourceHash"]="112179247ec2ea87c334bcddcafbe10d27ea6a1a344f5b329fc3beeaaf102eb6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-265944",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96658",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He connected stronger cooking skills and other trades with the further furnishings a camper could learn to make.",["title"]="William Pickman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96822:description:1-180","96822:objective:1-76"},["minimumStage"]=2,["questID"]=96822,["sourceHash"]="bef72e5cd3353fa655455a2c31e84d173c78b3772c657800037b2db1fbfc7715"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-266940",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96822",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Turroc wanted the weapons of warriors lost at Tiragarde recovered for a place of honor when human reinforcements prevented bringing home their bodies.",["title"]="Turroc"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"96822:description:1-180","96822:objective:1-76","96822:completion:1-166"},["minimumStage"]=4,["questID"]=96822,["sourceHash"]="bef72e5cd3353fa655455a2c31e84d173c78b3772c657800037b2db1fbfc7715"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-266940",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96822",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He accepted the recovered arms as a way to ensure the fallen Horde warriors would be remembered.",["title"]="Turroc"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96875:description:1-204","96875:objective:1-84"},["minimumStage"]=2,["questID"]=96875,["sourceHash"]="29943c883bc9d18477d5ca5c3792bd2474b93b53d3cd428c1ee9315833543da8"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-5811",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96875",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kamari supplied hides to the peons expanding Orgrimmar’s buildings.",["title"]="Kamari"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96875:description:1-204","96875:objective:1-84"},["minimumStage"]=2,["questID"]=96875,["sourceHash"]="29943c883bc9d18477d5ca5c3792bd2474b93b53d3cd428c1ee9315833543da8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-5811",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96875",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thunder Ridge’s lizard hides were too thick for ordinary armor but suited the lining of walls and roofs.",["title"]="Kamari"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96895:description:1-206","96895:objective:1-72"},["minimumStage"]=2,["questID"]=96895,["sourceHash"]="b2bc937c2a745cad049a1b0b5f7a73dab875558bcdc1118f65089f8d9dcc3a1a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-1738",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96895",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Terrence grew uneasy when Argent Dawn emissaries passed through Tirisfal unsupervised, even though both were Forsaken.",["title"]="Deathguard Terrence"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96895:description:1-206","96895:objective:1-72"},["minimumStage"]=2,["questID"]=96895,["sourceHash"]="b2bc937c2a745cad049a1b0b5f7a73dab875558bcdc1118f65089f8d9dcc3a1a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-1738",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96895",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He suspected the nearby Scourge cultists would draw the emissaries’ attention and directed a traveler toward the one headed southeast.",["title"]="Deathguard Terrence"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96899:description:1-190","96899:objective:1-60"},["minimumStage"]=2,["questID"]=96899,["sourceHash"]="84f15e2629f15d0b61293f6cec889ad58af187c0c56d45a6d36484386d5f949e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-267009",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96899",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hadric traveled with his Argent Dawn commander to meet Bandarion’s paladins before the Cult of the Damned diverted them.",["title"]="Hadric Harlson"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"96898:description:1-213","96898:objective:1-60"},["minimumStage"]=2,["questID"]=96898,["sourceHash"]="92ca3e7936276f99661ccbd0cf092febbfe923b0e510baf1a2e6515fcc1b0d97"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-267009",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96898",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought the necrotic focusing-crystal fragments scattered during Naxxramas’s assault, suspecting the cultists wanted to recover their power.",["title"]="Hadric Harlson"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"96899:description:1-190","96899:objective:1-60","96899:completion:1-214"},["minimumStage"]=4,["questID"]=96899,["sourceHash"]="84f15e2629f15d0b61293f6cec889ad58af187c0c56d45a6d36484386d5f949e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="npc-267008",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96899",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Leonid remembered using Bandarion’s fortress to prepare Argent Dawn battles before the order withdrew toward the Plaguelands.",["title"]="Leonid Barthalomew the Revered"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"96899:description:1-190","96899:objective:1-60","96899:completion:1-214"},["minimumStage"]=4,["questID"]=96899,["sourceHash"]="84f15e2629f15d0b61293f6cec889ad58af187c0c56d45a6d36484386d5f949e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-267008",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/96899",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He welcomed Danitha’s stewardship after the keep’s decline and recognized its new name as honoring a mutual friend.",["title"]="Leonid Barthalomew the Revered"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97003:description:1-227","97003:objective:1-66"},["minimumStage"]=2,["questID"]=97003,["sourceHash"]="9b83b65248091ee1584554824f1fbc4eccab47ea36d9fabbffbcac4408551c23"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="npc-267310",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97003",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gur’ak said he had fought creatures like the rumored Ravener before, which made him take the Razormanes’ stories seriously.",["title"]="Gur'ak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"97003:description:1-227","97003:objective:1-66","97003:completion:1-118"},["minimumStage"]=4,["questID"]=97003,["sourceHash"]="9b83b65248091ee1584554824f1fbc4eccab47ea36d9fabbffbcac4408551c23"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-267310",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97003",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted proof to bring back to Orgrimmar but promised to give the successful hunter the glory.",["title"]="Gur'ak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97003:description:1-227","97003:objective:1-66"},["minimumStage"]=2,["questID"]=97003,["sourceHash"]="9b83b65248091ee1584554824f1fbc4eccab47ea36d9fabbffbcac4408551c23"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-267307",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97003",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stories reported by Gur’ak described Chol’aruk as many times a normal quilboar’s size, with an insatiable thirst for blood; these were claims, not a recorded measurement.",["title"]="Chol'aruk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97003:description:1-227","97003:objective:1-66"},["minimumStage"]=2,["questID"]=97003,["sourceHash"]="9b83b65248091ee1584554824f1fbc4eccab47ea36d9fabbffbcac4408551c23"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-267307",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97003",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Razormane tales placed the Ravener’s lair deep in a cave at Thorn Hill.",["title"]="Chol'aruk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97223:description:1-209","97223:objective:1-66"},["minimumStage"]=2,["questID"]=97223,["sourceHash"]="2df4d86d4e4ed59f30108a47e902bf8328f16c249bcb22cbf1f8265cf7ee39d1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-7953",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97223",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xar’ti personally trained raptors gathered from across Kalimdor and prized the Bloodtalon line among the finest.",["title"]="Xar'Ti"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"97223:description:1-209","97223:objective:1-66","97223:completion:1-140"},["minimumStage"]=4,["questID"]=97223,["sourceHash"]="2df4d86d4e4ed59f30108a47e902bf8328f16c249bcb22cbf1f8265cf7ee39d1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-7953",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97223",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Although the matriarch had become too dangerous to leave near the village, Xar’ti wanted her eggs preserved and raised as allies.",["title"]="Xar'Ti"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97223:description:1-209","97223:objective:1-66"},["minimumStage"]=2,["questID"]=97223,["sourceHash"]="2df4d86d4e4ed59f30108a47e902bf8328f16c249bcb22cbf1f8265cf7ee39d1"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-268530",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97223",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xar’ti blamed the unusually savage matriarch for killing villagers and considered her continued presence too dangerous.",["title"]="Bloodtalon Matriarch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97223:description:1-209","97223:objective:1-66"},["minimumStage"]=2,["questID"]=97223,["sourceHash"]="2df4d86d4e4ed59f30108a47e902bf8328f16c249bcb22cbf1f8265cf7ee39d1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-268530",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97223",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her eggs offered a chance to preserve a valued raptor bloodline through training rather than abandon it as an enemy.",["title"]="Bloodtalon Matriarch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97250:description:1-229","97250:objective:1-84"},["minimumStage"]=2,["questID"]=97250,["sourceHash"]="64b50197b960f48a6c21c0ae6509dfe34b7f29f1518acc4dc49e5a4d4d4bbabf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-5911",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97250",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Logmar opposed human soldiers crossing the Barrens border and toppling tauren pathfinders’ landmarks after a tavern fire.",["title"]="Grunt Logmar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"97250:description:1-229","97250:objective:1-84","97250:completion:1-189"},["minimumStage"]=4,["questID"]=97250,["sourceHash"]="64b50197b960f48a6c21c0ae6509dfe34b7f29f1518acc4dc49e5a4d4d4bbabf"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-5911",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97250",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He still doubted the Horde caused the burning because civilians depended on that route for trade, leaving the cause for further investigation.",["title"]="Grunt Logmar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97279:description:1-200","97279:objective:1-66"},["minimumStage"]=2,["questID"]=97279,["sourceHash"]="91d6f696c073d3a1777e7f9ef0710c039e6604d331ef6e8006da2e89bcdcfc4b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3159",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97279",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kzan made the Valley of Trials’ training weapons, which were running short as recruits arrived.",["title"]="Kzan Thornslash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"97279:description:1-200","97279:objective:1-66","97279:completion:1-118"},["minimumStage"]=4,["questID"]=97279,["sourceHash"]="91d6f696c073d3a1777e7f9ef0710c039e6604d331ef6e8006da2e89bcdcfc4b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-3159",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97279",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He repaired weapons abandoned by failed recruits so that the next arrivals could use them.",["title"]="Kzan Thornslash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97289:description:1-249","97289:objective:1-63"},["minimumStage"]=2,["questID"]=97289,["sourceHash"]="21a925a59fc15b886d6efd2bbf27892462672287390739c8a963c19cee674373"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-271613",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97289",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The unfinished host was prepared to receive the severed head identified as Grand Marshal Othmar’s, though attachment was deliberately delayed.",["title"]="Unfinished Abomination"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"97289:description:1-249","97289:objective:1-63","97289:completion:1-146"},["minimumStage"]=4,["questID"]=97289,["sourceHash"]="21a925a59fc15b886d6efd2bbf27892462672287390739c8a963c19cee674373"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-271613",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97289",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Beside the recovered head the body stirred and panicked through a memory of death, producing only a broken beginning to speech.",["title"]="Unfinished Abomination"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97558:description:1-209","97558:objective:1-106"},["minimumStage"]=2,["questID"]=97558,["sourceHash"]="8770a2c912cac20182b4b6f485d000a20f15b04ebc12c11d24a31295dafc7aef"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3549",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97558",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shelene gathered different kinds of hides for replacing damaged Forsaken skin.",["title"]="Shelene Rhobart"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97558:description:1-209","97558:objective:1-106"},["minimumStage"]=2,["questID"]=97558,["sourceHash"]="8770a2c912cac20182b4b6f485d000a20f15b04ebc12c11d24a31295dafc7aef"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-3549",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97558",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She explained that the thickness of bat membranes, darkhound hides and murloc skin made each useful for different parts of an injured body.",["title"]="Shelene Rhobart"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97891:description:1-241","97891:objective:1-77"},["minimumStage"]=2,["questID"]=97891,["sourceHash"]="69c6c2241167b250bd755afdb3bd5bcf315bea25778a7c59928c7f7c832126b6"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="npc-7683",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97891",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alessandro complained that running made his knees rattle and pop out of place.",["title"]="Alessandro Luca"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97891:description:1-241","97891:objective:1-77"},["minimumStage"]=2,["questID"]=97891,["sourceHash"]="69c6c2241167b250bd755afdb3bd5bcf315bea25778a7c59928c7f7c832126b6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-7683",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97891",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="An unstable potion’s short life required a faster courier to carry it across the slime canal to Martin Felben.",["title"]="Alessandro Luca"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97891:description:1-241","97891:objective:1-77"},["minimumStage"]=2,["questID"]=97891,["sourceHash"]="69c6c2241167b250bd755afdb3bd5bcf315bea25778a7c59928c7f7c832126b6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-11044",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97891",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Martin was to receive Alessandro’s unstable potion at the Apothecarium before its brief useful life expired.",["title"]="Doctor Martin Felben"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97908:description:1-181","97908:objective:1-60"},["minimumStage"]=2,["questID"]=97908,["sourceHash"]="c84d3497c36ec1ba550d28d4e29ef41acbe90ea73917eee056433e0e7d34f6dd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-7088",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97908",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thuwd taught how harvested hides could become a comfortable camp chair for rest between dangers.",["title"]="Thuwd"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"97908:description:1-181","97908:objective:1-60","97908:completion:1-161"},["minimumStage"]=4,["questID"]=97908,["sourceHash"]="c84d3497c36ec1ba550d28d4e29ef41acbe90ea73917eee056433e0e7d34f6dd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-7088",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97908",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed campers outside town and reminded them that even a furnished camp needed its fire.",["title"]="Thuwd"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97959:description:1-166","97959:objective:1-57"},["minimumStage"]=2,["questID"]=97959,["sourceHash"]="880f5dfea340767037b0caf375c46055db7df16693712cfbb3873d2d2dac5b68"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-4598",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97959",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brom taught miners to make a lodestone for a camp, drawing warriors to share the benefit of gathering around it.",["title"]="Brom Killian"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"97970:description:1-210","97970:objective:1-64"},["minimumStage"]=2,["questID"]=97970,["sourceHash"]="18975630ecd8ff8d935e77bcbe44f903060a3e683cb3a6faaa458617743e04b9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-257022",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/97970",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Messana guided skilled miners in Shen’dar toward making a lodestone for their wilderness camps.",["title"]="Messana Crestwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98093:description:1-200","98093:objective:1-79"},["minimumStage"]=2,["questID"]=98093,["sourceHash"]="b246248ccd0cbd0cb4a5efbe9b74f04a44759be80133390b42b26b7098044312"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-14242",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98093",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sulhasa climbed a tree after hyenas circled and Stormhide lizards blocked her way home from a walk along the Gold Road.",["title"]="Sulhasa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98093:description:1-200","98093:objective:1-79"},["minimumStage"]=2,["questID"]=98093,["sourceHash"]="b246248ccd0cbd0cb4a5efbe9b74f04a44759be80133390b42b26b7098044312"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-14242",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98093",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted a safe path back to Camp Taurajo rather than remain stranded above the dangerous fields.",["title"]="Sulhasa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98248:description:1-209","98248:objective:1-73"},["minimumStage"]=2,["questID"]=98248,["sourceHash"]="f0ead3e936d7b865dff3ada546195d2f3960d11342540620024dd195f38ab80f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-256386",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98248",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dokimi received returns and delivery inquiries at Durotar Supply and Logistics’ trade outpost west of the Crossroads.",["title"]="Dokimi"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"98248:description:1-209","98248:objective:1-73","98248:completion:1-169"},["minimumStage"]=4,["questID"]=98248,["sourceHash"]="f0ead3e936d7b865dff3ada546195d2f3960d11342540620024dd195f38ab80f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-256386",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98248",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She enrolled helpers as associates without more paperwork and offered Merchant’s Favor for dealing with compromised shipments found on their travels.",["title"]="Dokimi"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98319:description:1-189","98319:objective:1-53"},["minimumStage"]=2,["questID"]=98319,["sourceHash"]="94231d91a0c151bb3d9dfc69a2226fb6b05d00335b4f9e42d93ede07458ba1f7"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-271546",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98319",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gretchen’s partner Cornelius charged into the wendigo-filled Grizzled Den before she could secure the report they needed.",["title"]="Mountaineer Gretchen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98319:description:1-189","98319:objective:1-53"},["minimumStage"]=2,["questID"]=98319,["sourceHash"]="94231d91a0c151bb3d9dfc69a2226fb6b05d00335b4f9e42d93ede07458ba1f7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-271546",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98319",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She described the growing wendigo problem as a second burden alongside the trolls and needed someone to locate her rash companion.",["title"]="Mountaineer Gretchen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98326:description:1-194","98326:objective:1-63"},["minimumStage"]=2,["questID"]=98326,["sourceHash"]="87d50963ffe3aa7c95e31c3f90fb4199dc043a954ca5329f0081061ba9d9f825"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-8508",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98326",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gretta’s husband Paxton spent days fishing on the frozen lake to obtain the sack stolen by Frosthowl.",["title"]="Gretta Ganter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98326:description:1-194","98326:objective:1-63"},["minimumStage"]=2,["questID"]=98326,["sourceHash"]="87d50963ffe3aa7c95e31c3f90fb4199dc043a954ca5329f0081061ba9d9f825"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-8508",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98326",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted the haul recovered rather than force him to begin the difficult work again.",["title"]="Gretta Ganter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98326:description:1-194","98326:objective:1-63"},["minimumStage"]=2,["questID"]=98326,["sourceHash"]="87d50963ffe3aa7c95e31c3f90fb4199dc043a954ca5329f0081061ba9d9f825"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-271587",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98326",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gretta blamed the loud wendigo for attacking her and carrying away the family’s hard-won fish.",["title"]="Frosthowl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98326:description:1-194","98326:objective:1-63"},["minimumStage"]=2,["questID"]=98326,["sourceHash"]="87d50963ffe3aa7c95e31c3f90fb4199dc043a954ca5329f0081061ba9d9f825"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-271587",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98326",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She placed Frosthowl deep in the Grizzled Den southeast of Brewnall.",["title"]="Frosthowl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98407:description:1-195","98407:objective:1-67"},["minimumStage"]=2,["questID"]=98407,["sourceHash"]="2b25e1347ee8a847a7fbb7f90c8b964948cf97368592d52d5e5668e4acbf2344"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1070",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98407",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Feldon wanted the bold gnolls camping close to Lakeshire deterred before they pressed still nearer to the people.",["title"]="Deputy Feldon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98407:description:1-195","98407:objective:1-67"},["minimumStage"]=2,["questID"]=98407,["sourceHash"]="2b25e1347ee8a847a7fbb7f90c8b964948cf97368592d52d5e5668e4acbf2344"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-1070",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98407",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He believed the disorganized packs respected strength and sought thrashers’ spiked collars as trophies to reinforce that warning.",["title"]="Deputy Feldon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98512:description:1-201","98512:objective:1-65"},["minimumStage"]=2,["questID"]=98512,["sourceHash"]="7c80e96327d80df59445ea92b75bfd6f2fe92af695eed4462f4392cbeef697cb"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-273017",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98512",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fendaal patrolled the border and watched Al’Aketh gathering around a northern hillside house.",["title"]="Fendaal Windstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98512:description:1-201","98512:objective:1-65"},["minimumStage"]=2,["questID"]=98512,["sourceHash"]="7c80e96327d80df59445ea92b75bfd6f2fe92af695eed4462f4392cbeef697cb"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-273017",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98512",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He could not establish what they intended, but offered cover to someone willing to confront the group while he watched for danger.",["title"]="Fendaal Windstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98545:description:1-207","98545:objective:1-64"},["minimumStage"]=2,["questID"]=98545,["sourceHash"]="3bf643cd64be3b643ef86f59543c9703345bb53f2758cab8641ab764c9ce16aa"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-272526",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98545",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Glix was an old friend of Leonid’s and received a discreet letter in the Undercity’s Trade Quarter.",["title"]="Glix Xizzix"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"98545:description:1-207","98545:objective:1-64","98545:completion:1-223"},["minimumStage"]=4,["questID"]=98545,["sourceHash"]="3bf643cd64be3b643ef86f59543c9703345bb53f2758cab8641ab764c9ce16aa"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-272526",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98545",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Annoyed at an unpromised tip, he offered lost-and-found belongings left after customers’ haircuts and answered the errand with gallows humor.",["title"]="Glix Xizzix"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98601:description:1-243","98601:objective:1-64"},["minimumStage"]=2,["questID"]=98601,["sourceHash"]="2e17a1848c0e976d83749b41a1ab7e70addecf781ccbc711ca6dbdf32ae5cd08"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="reviewed-shadow-priest-sarvis",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98601",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sarvis felt uneasy around paladins and asked that a Light-scented consecrated scroll be read away from him.",["title"]="Shadow Priest Sarvis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99079:description:1-217","99079:objective:1-64"},["minimumStage"]=2,["questID"]=99079,["sourceHash"]="6bdd200ead7e2c1e38b190fd5a4a631de9182f9a204f1827fb82c81eb36e6fce"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3222",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99079",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wildrunner guarded Bloodhoof’s safety while checking on overdue Longwalkers whose duty lay with the High Chieftain.",["title"]="Brave Wildrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99079:description:1-217","99079:objective:1-64"},["minimumStage"]=2,["questID"]=99079,["sourceHash"]="6bdd200ead7e2c1e38b190fd5a4a631de9182f9a204f1827fb82c81eb36e6fce"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-3222",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99079",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Malah had not returned from the eastern border, prompting him to send someone else to confirm her safety while he remained at the village.",["title"]="Brave Wildrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99079:description:1-217","99079:objective:1-64"},["minimumStage"]=2,["questID"]=99079,["sourceHash"]="6bdd200ead7e2c1e38b190fd5a4a631de9182f9a204f1827fb82c81eb36e6fce"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-275789",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99079",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Malah was one of the Longwalkers, trusted tauren scouts whose loyalty lay with the High Chieftain.",["title"]="Malah Longwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99079:description:1-217","99079:objective:1-64"},["minimumStage"]=2,["questID"]=99079,["sourceHash"]="6bdd200ead7e2c1e38b190fd5a4a631de9182f9a204f1827fb82c81eb36e6fce"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="npc-275789",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99079",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her headband and feathered staff marked her as a Longwalker.",["title"]="Malah Longwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"99079:description:1-217","99079:objective:1-64","99079:completion:1-97"},["minimumStage"]=4,["questID"]=99079,["sourceHash"]="6bdd200ead7e2c1e38b190fd5a4a631de9182f9a204f1827fb82c81eb36e6fce"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="npc-275789",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99079",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She was found dead with arrows in her back and scattered on the ground around her.",["title"]="Malah Longwind"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99082:description:1-217","99082:objective:1-57"},["minimumStage"]=2,["questID"]=99082,["sourceHash"]="59d231ac0aa90ac87ed0e6206542c4e37333b14acedecb99c2f1714d6297dded"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="cairne",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99082",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Baine credited his father Cairne with leading the charge alongside Thrall to reclaim the plains from the centaur.",["title"]="Cairne Bloodhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"99082:description:1-217","99082:objective:1-57","99082:completion:1-178"},["minimumStage"]=4,["questID"]=99082,["sourceHash"]="59d231ac0aa90ac87ed0e6206542c4e37333b14acedecb99c2f1714d6297dded"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="cairne",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99082",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="News of Galak returning to Mulgore drew his anger and praise for those defending the tauren’s home and ancestors.",["title"]="Cairne Bloodhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99123:description:1-137","99123:objective:1-63"},["minimumStage"]=2,["questID"]=99123,["sourceHash"]="c6834777f67aa6516af6d2362159033285d2a8401282548bc5cae2451a21b08f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-275811",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99123",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pal’juh scouted Kolkar Crag alone, ran out of magic at the wrong moment and became trapped in hiding.",["title"]="Pal'juh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"99123:description:1-137","99123:objective:1-63","99123:completion:1-182"},["minimumStage"]=4,["questID"]=99123,["sourceHash"]="c6834777f67aa6516af6d2362159033285d2a8401282548bc5cae2451a21b08f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-275811",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99123",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vornal considered her promising but too impulsive, hoping her escape would teach greater caution about venturing out alone.",["title"]="Pal'juh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99142:description:1-193","99142:objective:1-47"},["minimumStage"]=2,["questID"]=99142,["sourceHash"]="0748098441a159e693a4dda7495f6d64dcbaffad43ea26560f69afe547a13e31"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-10665",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99142",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Holland altered doom weed through alchemy and replanted it at Balnir to cultivate his intended creation, tomb weed.",["title"]="Junior Apothecary Holland"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99142:description:1-193","99142:objective:1-47"},["minimumStage"]=2,["questID"]=99142,["sourceHash"]="0748098441a159e693a4dda7495f6d64dcbaffad43ea26560f69afe547a13e31"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-10665",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99142",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scourge gathering near the crop intrigued him; he regarded the plant’s development as a path to personal glory and destructive future use.",["title"]="Junior Apothecary Holland"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99144:description:1-203","99144:objective:1-87"},["minimumStage"]=2,["questID"]=99144,["sourceHash"]="3992b05cfe295d5995232c51a9a56131d2f3b96c6a72689fffa09020a4567165"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="npc-275954",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99144",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bareth was captured while carrying a message from Bandarion to Shari in Brill.",["title"]="Bareth Dawnstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99144:description:1-203","99144:objective:1-87"},["minimumStage"]=2,["questID"]=99144,["sourceHash"]="3992b05cfe295d5995232c51a9a56131d2f3b96c6a72689fffa09020a4567165"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-275954",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99144",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His captors’ hateful use of the Light violated the ideals he sought to protect, yet he still hoped a visitor would trust his intentions and help him escape.",["title"]="Bareth Dawnstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99152:description:1-219","99152:objective:1-62"},["minimumStage"]=2,["questID"]=99152,["sourceHash"]="5fc5b34bf62afbfe7798af6e834b6b1c49e57dcd6be90b17fa692968aa48ccff"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-246389",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99152",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hilda wanted trainees ready before the undead beneath Shadowvale could become an uprising against Bandarion.",["title"]="Hilda the Breaker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99152:description:1-219","99152:objective:1-62"},["minimumStage"]=2,["questID"]=99152,["sourceHash"]="5fc5b34bf62afbfe7798af6e834b6b1c49e57dcd6be90b17fa692968aa48ccff"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-246389",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99152",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bones still glowing with reanimation magic could help her study the hidden threat that had escaped notice.",["title"]="Hilda the Breaker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99153:description:1-243","99153:objective:1-62"},["minimumStage"]=2,["questID"]=99153,["sourceHash"]="ad3028a3922a9f9e471d912a77abb0f70ea2bee1506ff840b1f8b5341ea71e5a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-259190",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99153",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ephram sought a focusing-crystal fragment taken by an escaped cultist and believed hidden beneath Shadowvale.",["title"]="Ephram Barbaro"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99153:description:1-243","99153:objective:1-62"},["minimumStage"]=2,["questID"]=99153,["sourceHash"]="ad3028a3922a9f9e471d912a77abb0f70ea2bee1506ff840b1f8b5341ea71e5a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-259190",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99153",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He suspected the shard was either raising the dead or strengthening them, without yet knowing which.",["title"]="Ephram Barbaro"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99158:description:1-201","99158:objective:1-54"},["minimumStage"]=2,["questID"]=99158,["sourceHash"]="bd254bc8aedef5770444fd8702f6356eb493cd6eb40e7086de1f64402683add2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-1253",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99158",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gavin was an Argent Dawn priest who preferred healing and helping travelers to taking up weapons.",["title"]="Father Gavin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"99158:description:1-201","99158:objective:1-54","99158:completion:1-162"},["minimumStage"]=4,["questID"]=99158,["sourceHash"]="bd254bc8aedef5770444fd8702f6356eb493cd6eb40e7086de1f64402683add2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-1253",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99158",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His repaired mountain building served as a rest stop, mostly self-sufficient but still dependent on certain supplies such as holy candles from Ironforge.",["title"]="Father Gavin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99159:description:1-151","99159:objective:1-54"},["minimumStage"]=2,["questID"]=99159,["sourceHash"]="3736965d03fc77b383647b53a941e94f07a9bbadedc8902b03666851a9921d6c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-1253",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99159",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He kept his hearth open to any soul needing warmth and sought extra firewood while other duties occupied him.",["title"]="Father Gavin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99160:description:1-218","99160:objective:1-51"},["minimumStage"]=2,["questID"]=99160,["sourceHash"]="9d1fa14b04eae83454a300aa937f53450c2488191c1620e1f29cbc5422500a48"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="npc-1253",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99160",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A recent shelf collapse angered the nearby ice spirits, threatening already hazardous mountain roads beyond his ability to placate them.",["title"]="Father Gavin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"99162:description:1-200","99162:objective:1-60","99162:completion:1-163"},["minimumStage"]=4,["questID"]=99162,["sourceHash"]="522fd4c9679e9aa39266caf330b5f03c88470d80881c9b91c85fc44f25b965f3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-1253",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99162",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After slides he sought missing mountaineers, using the names carved into their rifles to return the dead’s belongings to Ironforge and their families.",["title"]="Father Gavin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99161:description:1-211","99161:objective:1-51"},["minimumStage"]=2,["questID"]=99161,["sourceHash"]="9dcc7b2c97ca2b54f9c2189266bdff930528e9a0741c5ebc695fe123152b195b"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-276009",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99161",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Avala was larger than the ice elementals that followed the mountain rockslide.",["title"]="Avala"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"99161:description:1-211","99161:objective:1-51"},["minimumStage"]=2,["questID"]=99161,["sourceHash"]="9dcc7b2c97ca2b54f9c2189266bdff930528e9a0741c5ebc695fe123152b195b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-276009",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/99161",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gavin named the first spirit to appear Avala and suspected it caused further weather changes and small slides.",["title"]="Avala"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92514:description:1-234","92514:objective:1-83"},["minimumStage"]=2,["questID"]=92514,["sourceHash"]="2ceb4e3cede6aa1649356c8a5aea2847a4fa4c4b68cbd907f77fab2697946bca"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-254089",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92514",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Coriella Calmbreeze kept Shen’dar Village’s inn, offering lodging and supplies to travelers directed there by the constable.",["title"]="Coriella Calmbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92683:description:1-227","92683:objective:1-88"},["minimumStage"]=2,["questID"]=92683,["sourceHash"]="e397a09f83b8cf17818da0fdb85ef258de798dfcd28efaff6943a4900c899040"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-251622",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92683",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Giant flutterflies gathered in the outer fields near Shen’dar’s orchard, where their wings shed useful dust.",["title"]="Flutterfly"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92683:description:1-227","92683:objective:1-88"},["minimumStage"]=2,["questID"]=92683,["sourceHash"]="e397a09f83b8cf17818da0fdb85ef258de798dfcd28efaff6943a4900c899040"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-251622",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92683",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A swatter could startle a flutterfly into fleeing and shaking loose wing dust, though some insects retaliated instead.",["title"]="Flutterfly"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92683:description:1-227","92683:objective:1-88"},["minimumStage"]=2,["questID"]=92683,["sourceHash"]="e397a09f83b8cf17818da0fdb85ef258de798dfcd28efaff6943a4900c899040"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-251622",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/92683",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The village gathered flutterfly dust for household uses despite the mess involved in collecting it.",["title"]="Flutterfly"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93318:description:1-214","93318:objective:1-65"},["minimumStage"]=2,["questID"]=93318,["sourceHash"]="8ed95c011af087ab670e3c7c673bcdd56fae74791b7a14bfa2593e5ddc09f472"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-254589",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93318",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vulgara was a winged vuldren, described in the Peacekeepers’ wanted notice as a highly dangerous terror of the highlands.",["title"]="Vulgara the Insatiable"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93318:description:1-214","93318:objective:1-65"},["minimumStage"]=2,["questID"]=93318,["sourceHash"]="8ed95c011af087ab670e3c7c673bcdd56fae74791b7a14bfa2593e5ddc09f472"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-254589",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93318",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The notice placed Vulgara’s last sighting on a hilltop rise southwest of Shen’dar Village.",["title"]="Vulgara the Insatiable"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"93318:description:1-214","93318:objective:1-65"},["minimumStage"]=2,["questID"]=93318,["sourceHash"]="8ed95c011af087ab670e3c7c673bcdd56fae74791b7a14bfa2593e5ddc09f472"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-254589",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/93318",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Constable Aonda placed a bounty on the beast, with Danarii Bellowveil appointed to receive its head as proof.",["title"]="Vulgara the Insatiable"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94489:description:1-185","94489:objective:1-62"},["minimumStage"]=2,["questID"]=94489,["sourceHash"]="79aeb0e8e8b235f77fa869f9ffcb5e75575a61c54b1884fee4581496e776a2e2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-258130",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94489",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jorel Windsinger’s mate asked that the healing poultices be brought to him among the injured druids north of the clearing.",["title"]="Jorel Windsinger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94489:description:1-185","94489:objective:1-62"},["minimumStage"]=2,["questID"]=94489,["sourceHash"]="79aeb0e8e8b235f77fa869f9ffcb5e75575a61c54b1884fee4581496e776a2e2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-258130",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94489",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He had been in dire condition when his mate left, among the few Shen’dorei druids whose survival made every prepared poultice precious.",["title"]="Jorel Windsinger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94638:description:1-224","94638:objective:1-66"},["minimumStage"]=2,["questID"]=94638,["sourceHash"]="a9add3f46476272a931d9c7f67409d7fcffbb1c42c15cc4dbee65f304adf3c55"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-258443",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94638",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ur’endra had lost herself to madness and begun attacking her own kin as the absence of the winds unsettled nearby creatures.",["title"]="Ur'endra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94638:description:1-224","94638:objective:1-66"},["minimumStage"]=2,["questID"]=94638,["sourceHash"]="a9add3f46476272a931d9c7f67409d7fcffbb1c42c15cc4dbee65f304adf3c55"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-258443",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94638",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her mate placed her roaming grounds in the northwestern Shen’dar Highlands.",["title"]="Ur'endra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94638:description:1-224","94638:objective:1-66"},["minimumStage"]=2,["questID"]=94638,["sourceHash"]="a9add3f46476272a931d9c7f67409d7fcffbb1c42c15cc4dbee65f304adf3c55"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-258443",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94638",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her mate mourned the need to end her suffering, setting that difficult confrontation as a test for a druid seeking a stronger shape.",["title"]="Ur'endra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94913:description:1-188","94913:objective:1-74"},["minimumStage"]=2,["questID"]=94913,["sourceHash"]="01104855b57b3f64972385119184e7fa59dc100db5b2e3637f6d9a52c0ad82b6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11832",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94913",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keeper Remulos guarded Moonglade and watched over the druids who hibernated within its sacred lands.",["title"]="Keeper Remulos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"94913:description:1-188","94913:objective:1-74"},["minimumStage"]=2,["questID"]=94913,["sourceHash"]="01104855b57b3f64972385119184e7fa59dc100db5b2e3637f6d9a52c0ad82b6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11832",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/94913",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Druids were welcomed to Moonglade for knowledge and solace; newcomers seeking instruction were directed to Dendrite Starblaze in Nighthaven.",["title"]="Keeper Remulos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95036:description:1-198","95036:objective:1-67"},["minimumStage"]=2,["questID"]=95036,["sourceHash"]="18105d060e78471aad3007fc0e5155cfe1e86ef2529d22972c53e44cedd495c2"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-259897",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95036",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Old Fire-Eye was described as the largest and fiercest of the worgen threatening Silverpine’s people.",["title"]="Old Fire-Eye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95036:description:1-198","95036:objective:1-67"},["minimumStage"]=2,["questID"]=95036,["sourceHash"]="18105d060e78471aad3007fc0e5155cfe1e86ef2529d22972c53e44cedd495c2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-259897",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95036",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Those he attacked believed unknown magic kept him from staying dead, making an ordinary weapon inadequate to end the threat.",["title"]="Old Fire-Eye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95036:description:1-198","95036:objective:1-67"},["minimumStage"]=2,["questID"]=95036,["sourceHash"]="18105d060e78471aad3007fc0e5155cfe1e86ef2529d22972c53e44cedd495c2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-259897",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95036",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Trevan offered instructions for forging a special weapon to confront him; the request did not explain the source of his apparent return from death.",["title"]="Old Fire-Eye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95803:description:1-218","95803:objective:1-65"},["minimumStage"]=2,["questID"]=95803,["sourceHash"]="e7d2ae0036f7021fa8f928a3f93d61d9bbc44f5e6f1a011d4885fe43ff4b6295"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-259431",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95803",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rudolph Gelhardt was the tarnished commander whose severed head his former allies ordered delivered to Sylvanas.",["title"]="Rudolph Gelhardt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"95803:description:1-218","95803:objective:1-65"},["minimumStage"]=2,["questID"]=95803,["sourceHash"]="e7d2ae0036f7021fa8f928a3f93d61d9bbc44f5e6f1a011d4885fe43ff4b6295"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-259431",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/95803",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The delivery was intended to demonstrate that the order disciplined its own members and remained devoted to the Forsaken despite the Dark Lady’s mistrust.",["title"]="Rudolph Gelhardt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98093:description:1-200","98093:objective:1-79"},["minimumStage"]=2,["questID"]=98093,["sourceHash"]="b246248ccd0cbd0cb4a5efbe9b74f04a44759be80133390b42b26b7098044312"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-3238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98093",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stormhides were lizards encountered in the fields along the Gold Road near Camp Taurajo.",["title"]="Stormhide"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"98093:description:1-200","98093:objective:1-79"},["minimumStage"]=2,["questID"]=98093,["sourceHash"]="b246248ccd0cbd0cb4a5efbe9b74f04a44759be80133390b42b26b7098044312"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/98093",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="They blocked Sulhasa’s escape while hyenas circled, leaving her stranded in a tree until the way home could be cleared.",["title"]="Stormhide"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6961:description:1-36","6961:description:39-81","6961:description:84-184","6961:description:187-237","6961:description:242-318","6961:description:321-361","6961:description:364-442","6961:objective:1-98"},["minimumStage"]=2,["questID"]=6961,["sourceHash"]="f95823d900b483e1d1525458afb9bdfb02a0d828852d0f907c1bb690bcb0752c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kaymard Copperpinch promoted Smokywood Pastures’ Winter Veil treats and encouraged visitors to greet Greatfather Winter.",["title"]="Kaymard Copperpinch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6961:description:1-36","6961:description:39-81","6961:description:84-184","6961:description:187-237","6961:description:242-318","6961:description:321-361","6961:description:364-442","6961:objective:1-98"},["minimumStage"]=2,["questID"]=6961,["sourceHash"]="f95823d900b483e1d1525458afb9bdfb02a0d828852d0f907c1bb690bcb0752c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13418",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He tied seasonal generosity to the company’s wares, urging customers to buy treats for people who had been kind during the year.",["title"]="Kaymard Copperpinch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6962:description:1-71","6962:description:76-214","6962:description:217-308","6962:description:311-380","6962:objective:1-85"},["minimumStage"]=2,["questID"]=6962,["sourceHash"]="b19a402b36ed360f33a63e17abf812a2128774128fbccad011dc012229793b6a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13445",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After a long day greeting visitors, Great-father Winter asked for gingerbread cookies and ice-cold milk as a treat for himself.",["title"]="Great-father Winter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6964:description:1-26","6964:description:28-38","6964:description:43-123","6964:description:126-287","6964:description:292-391","6964:description:394-483","6964:objective:1-100"},["minimumStage"]=2,["questID"]=6964,["sourceHash"]="a406472eca81af8a90577249c3d2ae6f598c49a144d0f2e4016602b1bb9898b7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9550",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Furmund objected to merchants reducing the Feast of Winter Veil to presents and treats, directing curious travelers to Sagorne Creststrider for its history.",["title"]="Furmund"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6964:description:1-26","6964:description:28-38","6964:description:43-123","6964:description:126-287","6964:description:292-391","6964:description:394-483","6964:objective:1-100"},["minimumStage"]=2,["questID"]=6964,["sourceHash"]="a406472eca81af8a90577249c3d2ae6f598c49a144d0f2e4016602b1bb9898b7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9550",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He understood Winter Veil as a season of renewal, when the land slept beneath the snow brought by Greatfather Winter.",["title"]="Furmund"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6983:description:1-103","6983:description:106-127","6983:description:130-186","6983:description:191-240","6983:description:243-337","6983:description:340-462","6983:objective:1-72","6983:objective:75-207"},["minimumStage"]=2,["questID"]=6983,["sourceHash"]="6df132ea956047de0663d64dbb2a34f0f4481b5557ac089062344174a51b9111"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-13636",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Strange Snowman spoke through a shivering stammer and blamed the Abominable Greench for transforming him into his snowy condition.",["title"]="Strange Snowman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6983:description:1-103","6983:description:106-127","6983:description:130-186","6983:description:191-240","6983:description:243-337","6983:description:340-462","6983:objective:1-72","6983:objective:75-207"},["minimumStage"]=2,["questID"]=6983,["sourceHash"]="6df132ea956047de0663d64dbb2a34f0f4481b5557ac089062344174a51b9111"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-13636",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He reported that the Greench had also stolen Smokywood Pastures’ treats and warned that confronting the creature would require help.",["title"]="Strange Snowman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6983:description:1-103","6983:description:106-127","6983:description:130-186","6983:description:191-240","6983:description:243-337","6983:description:340-462","6983:objective:1-72","6983:objective:75-207"},["minimumStage"]=2,["questID"]=6983,["sourceHash"]="6df132ea956047de0663d64dbb2a34f0f4481b5557ac089062344174a51b9111"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13636",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the stolen shipment returned to Orgrimmar together with a plea that someone undo his freezing.",["title"]="Strange Snowman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6982:description:1-52","6982:description:55-154","6982:description:157-162","6982:description:164-241","6982:description:246-303","6982:description:306-416","6982:description:421-434","6982:description:437-494","6982:objective:1-72"},["minimumStage"]=2,["questID"]=6982,["sourceHash"]="22c4884636821683ea23f5b4afb3a4af8d066b274e71724b100e7e17d2ad23e1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-12096",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Stormpike quartermaster sought captured Horde supplies to keep Alliance troops equipped during the fighting in Alterac Valley.",["title"]="Stormpike Quartermaster"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"6982:description:1-52","6982:description:55-154","6982:description:157-162","6982:description:164-241","6982:description:246-303","6982:description:306-416","6982:description:421-434","6982:description:437-494","6982:objective:1-72"},["minimumStage"]=2,["questID"]=6982,["sourceHash"]="22c4884636821683ea23f5b4afb3a4af8d066b274e71724b100e7e17d2ad23e1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12096",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Despite disparaging Horde food and equipment, the quartermaster considered Coldtooth’s stores valuable enough to seize from deep within enemy territory.",["title"]="Stormpike Quartermaster"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7001:description:1-57","7001:description:59-88","7001:description:93-199","7001:description:204-282","7001:description:284-338","7001:description:340-409","7001:description:414-509","7001:objective:1-37","7001:objective:39-115","7001:objective:117-194","7001:objective:196-265"},["minimumStage"]=2,["questID"]=7001,["sourceHash"]="1ff3411d796f800a1fc1588bf69958c644853cc0dc57c593f533ac0355112aa0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13616",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Frostwolf stable master organized the capture and stabling of the valley’s wolves to restore the Wolf Riders to the front.",["title"]="Frostwolf Stable Master"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7001:description:1-57","7001:description:59-88","7001:description:93-199","7001:description:204-282","7001:description:284-338","7001:description:340-409","7001:description:414-509","7001:objective:1-37","7001:objective:39-115","7001:objective:117-194","7001:objective:196-265"},["minimumStage"]=2,["questID"]=7001,["sourceHash"]="1ff3411d796f800a1fc1588bf69958c644853cc0dc57c593f533ac0355112aa0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13616",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Handlers were given a muzzle to tame nearby frostwolves and bring them back until the stable held enough mounts for renewed patrols.",["title"]="Frostwolf Stable Master"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7002:description:1-144","7002:description:146-190","7002:description:195-247","7002:description:249-309","7002:description:314-357","7002:description:359-435","7002:description:437-482","7002:objective:1-4"},["minimumStage"]=2,["questID"]=7002,["sourceHash"]="5f210d6d8b3baf22a31d74a2345daf21c898494b19fe8ad217953934e87d634e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13441",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Frostwolf Wolf Rider Commander sought ram hides to make riding harnesses while others gathered wolves for the stables.",["title"]="Frostwolf Wolf Rider Commander"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7002:description:1-144","7002:description:146-190","7002:description:195-247","7002:description:249-309","7002:description:314-357","7002:description:359-435","7002:description:437-482","7002:objective:1-4"},["minimumStage"]=2,["questID"]=7002,["sourceHash"]="5f210d6d8b3baf22a31d74a2345daf21c898494b19fe8ad217953934e87d634e"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-13441",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The hides came from the same regional rams used by the Stormpike cavalry, turning the gathering effort against the enemy’s mounts.",["title"]="Frostwolf Wolf Rider Commander"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7003:description:1-70","7003:description:73-126","7003:description:131-262","7003:description:265-390","7003:description:393-483","7003:objective:1-98","7003:objective:101-244"},["minimumStage"]=2,["questID"]=7003,["sourceHash"]="df029f69905acd263427acbec32cf68175c26fb00325ce505f7e3b26a42af7d0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14637",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zorbin Fandazzle considered Feralas’s giants bad for business and wanted others to test his shrinking ray while he avoided the danger.",["title"]="Zorbin Fandazzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7003:description:1-70","7003:description:73-126","7003:description:131-262","7003:description:265-390","7003:description:393-483","7003:objective:1-98","7003:objective:101-244"},["minimumStage"]=2,["questID"]=7003,["sourceHash"]="df029f69905acd263427acbec32cf68175c26fb00325ce505f7e3b26a42af7d0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14637",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He claimed goblin improvements over gnomish designs and requested the miniaturization residue left by the trials.",["title"]="Zorbin Fandazzle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7021:description:1-36","7021:description:39-111","7021:description:114-214","7021:description:217-267","7021:description:272-348","7021:description:351-391","7021:description:394-472","7021:objective:1-98"},["minimumStage"]=2,["questID"]=7021,["sourceHash"]="56a7b5acb4f612c328eadb8f7a4783ee84b44f145e3c0b7ed2bf5490ff8a54ea"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13431",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Whulwert Copperpinch advertised Smokywood Pastures’ seasonal treats and directed Winter Veil visitors toward Greatfather Winter in Orgrimmar.",["title"]="Whulwert Copperpinch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7022:description:1-36","7022:description:39-81","7022:description:84-184","7022:description:187-237","7022:description:242-318","7022:description:321-361","7022:description:364-442","7022:objective:1-98"},["minimumStage"]=2,["questID"]=7022,["sourceHash"]="77acb70c3d092abbda7bf6b2373d01acd66d0dc22c30503e25c191ce500be29c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13429",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nardstrum Copperpinch encouraged Winter Veil gift-giving while selling Smokywood Pastures’ selection of festive treats.",["title"]="Nardstrum Copperpinch"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7025:description:1-70","7025:description:75-212","7025:description:215-306","7025:description:309-377","7025:objective:1-84"},["minimumStage"]=2,["questID"]=7025,["sourceHash"]="e4cf481cb1f99d4b61106cc6ac9a04ba01c3841074a55b9787504155dc1cc35b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13444",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Greatfather Winter asked a visitor for gingerbread cookies and cold milk after spending the day receiving holiday callers.",["title"]="Greatfather Winter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7026:description:1-57","7026:description:59-125","7026:description:130-262","7026:description:264-293","7026:description:298-400","7026:description:402-472","7026:objective:1-4"},["minimumStage"]=2,["questID"]=7026,["sourceHash"]="3ceb4e1ff969090a27235a3de6daa4d0b3935ed060b96b2f63980f0d02a85fa9"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13577",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Stormpike Ram Rider Commander oversaw the demand for harness leather needed to send the brigade’s cavalry into battle.",["title"]="Stormpike Ram Rider Commander"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7026:description:1-57","7026:description:59-125","7026:description:130-262","7026:description:264-293","7026:description:298-400","7026:description:402-472","7026:objective:1-4"},["minimumStage"]=2,["questID"]=7026,["sourceHash"]="3ceb4e1ff969090a27235a3de6daa4d0b3935ed060b96b2f63980f0d02a85fa9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13577",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The commander wanted frostwolf hides taken from the enemy’s territory, sparing local rams because the brigade needed them as mounts.",["title"]="Stormpike Ram Rider Commander"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7027:description:1-29","7027:description:31-36","7027:description:38-104","7027:description:109-134","7027:description:136-196","7027:description:198-283","7027:description:285-365","7027:description:370-435","7027:description:437-479","7027:objective:1-40","7027:objective:42-129","7027:objective:131-200","7027:objective:202-261"},["minimumStage"]=2,["questID"]=7027,["sourceHash"]="96cd90622fb9b5eae6ef772b3ace10bb9a5a3e8c2f74cc347562802d777e8746"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13617",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Stormpike stable master rebuilt the brigade’s cavalry by gathering Alterac rams from the valley into its empty stables.",["title"]="Stormpike Stable Master"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7027:description:1-29","7027:description:31-36","7027:description:38-104","7027:description:109-134","7027:description:136-196","7027:description:198-283","7027:description:285-365","7027:description:370-435","7027:description:437-479","7027:objective:1-40","7027:objective:42-129","7027:objective:131-200","7027:objective:202-261"},["minimumStage"]=2,["questID"]=7027,["sourceHash"]="96cd90622fb9b5eae6ef772b3ace10bb9a5a3e8c2f74cc347562802d777e8746"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13617",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A training collar was used to capture each ram, with the rider commander to be notified once enough mounts had been gathered.",["title"]="Stormpike Stable Master"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7028:description:1-72","7028:description:74-114","7028:description:116-166","7028:description:168-224","7028:description:229-333","7028:description:335-405","7028:description:410-454","7028:description:456-466","7028:description:468-509","7028:objective:1-61"},["minimumStage"]=2,["questID"]=7028,["sourceHash"]="c977107365418c7549f4da3439399b7bf8dee68064adc178f726523b5a67a562"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13656",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Willow coveted the theradric crystal carvings hidden in Terramok’s ancient caverns and offered payment for their recovery.",["title"]="Willow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7028:description:1-72","7028:description:74-114","7028:description:116-166","7028:description:168-224","7028:description:229-333","7028:description:335-405","7028:description:410-454","7028:description:456-466","7028:description:468-509","7028:objective:1-61"},["minimumStage"]=2,["questID"]=7028,["sourceHash"]="c977107365418c7549f4da3439399b7bf8dee68064adc178f726523b5a67a562"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13656",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She spoke of studying relics of the old gods behind Maraudon’s great doors, hinting that their powers had rested too long.",["title"]="Willow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7029:description:1-116","7029:description:121-139","7029:description:141-286","7029:description:291-377","7029:description:379-474","7029:description:476-503","7029:objective:1-69","7029:objective:74-172","7029:objective:177-276"},["minimumStage"]=2,["questID"]=7029,["sourceHash"]="fd0fc5679cb3b2da467b4c04a7171b80d30eb0853b3ff2ecec62c150df766e59"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11823",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vark Battlescar prepared a coated vial that could turn water from Maraudon’s orange crystal pool into a cleansing agent.",["title"]="Vark Battlescar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7029:description:1-116","7029:description:121-139","7029:description:141-286","7029:description:291-377","7029:description:379-474","7029:description:476-503","7029:objective:1-69","7029:objective:74-172","7029:objective:177-276"},["minimumStage"]=2,["questID"]=7029,["sourceHash"]="fd0fc5679cb3b2da467b4c04a7171b80d30eb0853b3ff2ecec62c150df766e59"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11823",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought to purge the Vylestem vines of Vyletongue’s toxins, warning that cleansing them would not remove the satyr’s control.",["title"]="Vark Battlescar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7041:description:1-116","7041:description:121-139","7041:description:141-288","7041:description:293-379","7041:description:381-476","7041:description:478-505","7041:objective:1-69","7041:objective:74-172","7041:objective:177-265"},["minimumStage"]=2,["questID"]=7041,["sourceHash"]="f186f4da7e7e33fe04b32fc5b97081dd621cd344e93f4b6210b5cdc6028e6ea7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11715",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Talendria provided the means to prepare a healing liquid from Maraudon’s corrupted orange pool.",["title"]="Talendria"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7041:description:1-116","7041:description:121-139","7041:description:141-288","7041:description:293-379","7041:description:381-476","7041:description:478-505","7041:objective:1-69","7041:objective:74-172","7041:objective:177-265"},["minimumStage"]=2,["questID"]=7041,["sourceHash"]="f186f4da7e7e33fe04b32fc5b97081dd621cd344e93f4b6210b5cdc6028e6ea7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11715",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her treatment targeted the stunted Vylestem vines, but she warned that Vyletongue could still turn the purified plants against their healer.",["title"]="Talendria"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7042:description:1-9","7042:description:11-155","7042:description:160-339","7042:description:342-452","7042:description:457-498","7042:objective:1-111"},["minimumStage"]=2,["questID"]=7042,["sourceHash"]="79c4bb3ff70b7dc3b43430bb109493ab46082d1eef716273325dcf572566f1b0"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13433",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wulmort Jinglepocket sought both a missing Smokywood Pastures treat shipment and the agent sent into Alterac to find it.",["title"]="Wulmort Jinglepocket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7042:description:1-9","7042:description:11-155","7042:description:160-339","7042:description:342-452","7042:description:457-498","7042:objective:1-111"},["minimumStage"]=2,["questID"]=7042,["sourceHash"]="79c4bb3ff70b7dc3b43430bb109493ab46082d1eef716273325dcf572566f1b0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13433",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With the seasonal stock and investigator both overdue, he asked adventurers to search where the shipment had last been reported.",["title"]="Wulmort Jinglepocket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7046:description:1-44","7046:description:46-118","7046:description:120-174","7046:description:176-211","7046:description:216-312","7046:description:314-433","7046:description:438-498","7046:objective:1-70","7046:objective:75-117"},["minimumStage"]=2,["questID"]=7046,["sourceHash"]="398fc671f216542e2f012c6c2740a1a1bc2a16e5295a494075c2ed70d5cefd32"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-13716",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Celebras’s scepter had once let him travel swiftly through Maraudon while he hoped to bring peace to his uncle’s spirit.",["title"]="Celebras the Redeemed"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7046:description:1-44","7046:description:46-118","7046:description:120-174","7046:description:176-211","7046:description:216-312","7046:description:314-433","7046:description:438-498","7046:objective:1-70","7046:objective:75-117"},["minimumStage"]=2,["questID"]=7046,["sourceHash"]="398fc671f216542e2f012c6c2740a1a1bc2a16e5295a494075c2ed70d5cefd32"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13716",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Restoring the scepter required a helper to follow his instructions as he channeled the energy joining its rod and diamond.",["title"]="Celebras the Redeemed"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7061:description:1-93","7061:description:96-267","7061:description:272-340","7061:description:343-451","7061:objective:1-88","7061:objective:91-175"},["minimumStage"]=2,["questID"]=7061,["sourceHash"]="a27768bcd61f6be8b531a13fe584c8aead6a0271377296cab7429c78db8359bd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13417",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sagorne Creststrider studied legends and offered a collected account of the Feast of Winter Veil to people seeking its history.",["title"]="Sagorne Creststrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7061:description:1-93","7061:description:96-267","7061:description:272-340","7061:description:343-451","7061:objective:1-88","7061:objective:91-175"},["minimumStage"]=2,["questID"]=7061,["sourceHash"]="a27768bcd61f6be8b531a13fe584c8aead6a0271377296cab7429c78db8359bd"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-13417",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the book brought to Cairne Bloodhoof, knowing the chieftain would welcome others’ interest in the lore of their people.",["title"]="Sagorne Creststrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7062:description:1-26","7062:description:28-38","7062:description:43-123","7062:description:126-287","7062:description:292-412","7062:description:415-504","7062:objective:1-97"},["minimumStage"]=2,["questID"]=7062,["sourceHash"]="0facd42f2ac6f55269adf4af07e20e50ac6e80176be54c861c5f197b840e7046"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1365",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Goli Krumn opposed the merchants’ emphasis on gifts and treats, asking travelers to learn the Feast’s older meaning instead.",["title"]="Goli Krumn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7062:description:1-26","7062:description:28-38","7062:description:43-123","7062:description:126-287","7062:description:292-412","7062:description:415-504","7062:objective:1-97"},["minimumStage"]=2,["questID"]=7062,["sourceHash"]="0facd42f2ac6f55269adf4af07e20e50ac6e80176be54c861c5f197b840e7046"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1365",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recommended Historian Karnik at the Explorers’ League as a guide to Winter Veil’s history.",["title"]="Goli Krumn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7064:description:1-124","7064:description:126-195","7064:description:197-283","7064:description:285-366","7064:description:368-498","7064:objective:1-83"},["minimumStage"]=2,["questID"]=7064,["sourceHash"]="a284fdfd6b298abdd6f70a674d2df96cf043581063f19b2617dbb208ef014bbb"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13699",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Selendra sought capable allies to confront Theradras so that Zaetar’s remains could be recovered before the return to Stonetalon.",["title"]="Selendra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7064:description:1-124","7064:description:126-195","7064:description:197-283","7064:description:285-366","7064:description:368-498","7064:objective:1-83"},["minimumStage"]=2,["questID"]=7064,["sourceHash"]="a284fdfd6b298abdd6f70a674d2df96cf043581063f19b2617dbb208ef014bbb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13699",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her account traced the centaur to Theradras and Cenarius’s son Zaetar, and blamed their children for killing their father.",["title"]="Selendra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7065:description:1-65","7065:description:67-148","7065:description:150-211","7065:description:213-237","7065:description:239-286","7065:description:288-375","7065:description:377-507","7065:objective:1-83"},["minimumStage"]=2,["questID"]=7065,["sourceHash"]="210f2dd2aa3167ca84b6bcc5cd9c28a5b9187584164fcbbea3aae0f60e0b7daf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13698",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keeper Marandis wanted Zaetar’s remains recovered from Maraudon and sought help against the earth princess who kept them.",["title"]="Keeper Marandis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7065:description:1-65","7065:description:67-148","7065:description:150-211","7065:description:213-237","7065:description:239-286","7065:description:288-375","7065:description:377-507","7065:objective:1-83"},["minimumStage"]=2,["questID"]=7065,["sourceHash"]="210f2dd2aa3167ca84b6bcc5cd9c28a5b9187584164fcbbea3aae0f60e0b7daf"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13698",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described Theradras as an elemental force connected to the Old Gods and recounted Zaetar’s death at the hands of their centaur children.",["title"]="Keeper Marandis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7066:description:1-74","7066:description:79-161","7066:description:163-180","7066:description:182-221","7066:description:223-259","7066:description:264-331","7066:description:333-344","7066:description:346-411","7066:description:413-464","7066:description:466-494","7066:objective:1-60"},["minimumStage"]=2,["questID"]=7066,["sourceHash"]="33f2416074b0802be423f2f7e9995812724047e9df78c7dfce89d6614432931b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-12238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zaetar’s spirit refused to abandon his centaur children despite their crimes, believing they still needed their father.",["title"]="Zaetar's Spirit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7066:description:1-74","7066:description:79-161","7066:description:163-180","7066:description:182-221","7066:description:223-259","7066:description:264-331","7066:description:333-344","7066:description:346-411","7066:description:413-464","7066:description:466-494","7066:objective:1-60"},["minimumStage"]=2,["questID"]=7066,["sourceHash"]="33f2416074b0802be423f2f7e9995812724047e9df78c7dfce89d6614432931b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-12238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He saw the life nourished by his remains as an expression of his father Cenarius’s teachings, a reason to stay rather than leave.",["title"]="Zaetar's Spirit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7066:description:1-74","7066:description:79-161","7066:description:163-180","7066:description:182-221","7066:description:223-259","7066:description:264-331","7066:description:333-344","7066:description:346-411","7066:description:413-464","7066:description:466-494","7066:objective:1-60"},["minimumStage"]=2,["questID"]=7066,["sourceHash"]="33f2416074b0802be423f2f7e9995812724047e9df78c7dfce89d6614432931b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-12238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He entrusted a seed from that growth to a messenger so his brother could know his spirit remained and he lived on.",["title"]="Zaetar's Spirit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7067:description:1-84","7067:description:86-152","7067:description:154-182","7067:description:187-326","7067:description:331-377","7067:description:379-433","7067:description:435-469","7067:objective:1-31","7067:objective:33-142"},["minimumStage"]=2,["questID"]=7067,["sourceHash"]="ad97a8ceee6cdc2c13815fd3ef420e2058e24c3ed23acbe0a952e714c547e5da"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-13717",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Centaur Pariah had been exiled as a heretic but remained committed to the beliefs that drove his search.",["title"]="Centaur Pariah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7067:description:1-84","7067:description:86-152","7067:description:154-182","7067:description:187-326","7067:description:331-377","7067:description:379-433","7067:description:435-469","7067:objective:1-31","7067:objective:33-142"},["minimumStage"]=2,["questID"]=7067,["sourceHash"]="ad97a8ceee6cdc2c13815fd3ef420e2058e24c3ed23acbe0a952e714c547e5da"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-13717",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He required an outsider belonging to no centaur tribe to enter Maraudon, where his people admitted only the most devout.",["title"]="Centaur Pariah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7067:description:1-84","7067:description:86-152","7067:description:154-182","7067:description:187-326","7067:description:331-377","7067:description:379-433","7067:description:435-469","7067:objective:1-31","7067:objective:33-142"},["minimumStage"]=2,["questID"]=7067,["sourceHash"]="ad97a8ceee6cdc2c13815fd3ef420e2058e24c3ed23acbe0a952e714c547e5da"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13717",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rather than reveal his purpose at once, he offered a parchment of instructions to anyone willing to consider his cause.",["title"]="Centaur Pariah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7028:description:1-72","7028:description:74-114","7028:description:116-166","7028:description:168-224","7028:description:229-333","7028:description:335-405","7028:description:410-454","7028:description:456-466","7028:description:468-509","7028:objective:1-61"},["minimumStage"]=2,["questID"]=7028,["sourceHash"]="c977107365418c7549f4da3439399b7bf8dee68064adc178f726523b5a67a562"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="atlas-instance-maraudon",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Willow placed Terramok’s crystal caverns deep within Maraudon, where ancient carvings lay behind great doors.",["title"]="Maraudon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7029:description:1-116","7029:description:121-139","7029:description:141-286","7029:description:291-377","7029:description:379-474","7029:description:476-503","7029:objective:1-69","7029:objective:74-172","7029:objective:177-276"},["minimumStage"]=2,["questID"]=7029,["sourceHash"]="fd0fc5679cb3b2da467b4c04a7171b80d30eb0853b3ff2ecec62c150df766e59"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="atlas-instance-maraudon",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vyletongue’s corruption stunted the caverns’ plants; Vylestem vines could be purged with treated pool water without escaping his control.",["title"]="Maraudon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"7067:description:1-84","7067:description:86-152","7067:description:154-182","7067:description:187-326","7067:description:331-377","7067:description:379-433","7067:description:435-469","7067:objective:1-31","7067:objective:33-142"},["minimumStage"]=2,["questID"]=7067,["sourceHash"]="ad97a8ceee6cdc2c13815fd3ef420e2058e24c3ed23acbe0a952e714c547e5da"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="atlas-instance-maraudon",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The centaur guarded Maraudon as a holy tomb and admitted only their devout, leaving an exiled pariah to seek an outsider’s aid.",["title"]="Maraudon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"372:description:1-97","372:description:100-212","372:description:217-277","372:description:280-346","372:objective:1-102"},["minimumStage"]=2,["questID"]=372,["sourceHash"]="bb18eecfadd4df05cd262dcba4dcabc87129f287613a68e687ca99949ac1fdf7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1665",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Captain Melrache commanded Scarlet Crusaders raiding from a ruined tower in northern Tirisfal.",["title"]="Captain Melrache"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"372:description:1-97","372:description:100-212","372:description:217-277","372:description:280-346","372:objective:1-102"},["minimumStage"]=2,["questID"]=372,["sourceHash"]="bb18eecfadd4df05cd262dcba4dcabc87129f287613a68e687ca99949ac1fdf7"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1665",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Forsaken intelligence placed his command beyond Faol’s Rest, with two bodyguards protecting him.",["title"]="Captain Melrache"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"373:description:1-86","373:description:88-183","373:description:188-232","373:objective:1-72"},["minimumStage"]=2,["questID"]=373,["sourceHash"]="149aaeed8ef8951d80d85525bb8fa3e9e9fdd66913d07c7f2ad7c9cae399c118"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="vancleef",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A recently written, sealed letter on VanCleef’s person was addressed to Baros Alexston, Stormwind’s city architect in Cathedral Square.",["title"]="Edwin VanCleef"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"375:description:1-18","375:description:21-86","375:description:89-128","375:description:131-195","375:description:198-285","375:description:290-323","375:description:326-418","375:description:421-475","375:objective:1-76"},["minimumStage"]=2,["questID"]=375,["sourceHash"]="876fc0e94c9de0e286b6471028f25fb0095a1b6c0d3b272edc9d65cd7b067955"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1512",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Duskbat pelts could be sewn with coarse thread into a blanket, the remedy sought by a Forsaken seamstress struggling against the chill of undeath.",["title"]="Duskbat"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"378:description:1-47","378:description:50-110","378:description:115-203","378:description:206-318","378:description:321-378","378:description:383-453","378:description:456-475","378:description:478-491","378:description:494-511","378:objective:1-69"},["minimumStage"]=2,["questID"]=378,["sourceHash"]="6830ddc9c492b48a196788fc266a6cd73903ec21eb5acb02c7b7b5ddece02f41"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-1666",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Roggo’s intelligence implicated Kam Deepfury in planning the attack on the Thandol Span that cost Longbraid members of his family.",["title"]="Kam Deepfury"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"378:description:1-47","378:description:50-110","378:description:115-203","378:description:206-318","378:description:321-378","378:description:383-453","378:description:456-475","378:description:478-491","378:description:494-511","378:objective:1-69"},["minimumStage"]=2,["questID"]=378,["sourceHash"]="6830ddc9c492b48a196788fc266a6cd73903ec21eb5acb02c7b7b5ddece02f41"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1666",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Deepfury was held in the Stormwind Stockade for political reasons while Longbraid’s ally sought vengeance against him.",["title"]="Kam Deepfury"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"389:description:1-53","389:description:55-110","389:description:115-163","389:description:165-206","389:description:208-344","389:description:346-395","389:description:400-468","389:description:470-510","389:objective:1-44"},["minimumStage"]=2,["questID"]=389,["sourceHash"]="73bfdf066e57bcaf71594b5e6813863f134f8a247111db521b64bf8430e1e0f1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1716",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alexston identified Bazil Thredd as VanCleef’s lieutenant and a possible source of knowledge about his plans.",["title"]="Bazil Thredd"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"389:description:1-53","389:description:55-110","389:description:115-163","389:description:165-206","389:description:208-344","389:description:346-395","389:description:400-468","389:description:470-510","389:objective:1-44"},["minimumStage"]=2,["questID"]=389,["sourceHash"]="73bfdf066e57bcaf71594b5e6813863f134f8a247111db521b64bf8430e1e0f1"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1716",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thredd was imprisoned in the Stormwind Stockade when Alexston directed an investigator to question him.",["title"]="Bazil Thredd"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"407:description:1-25","407:description:28-47","407:description:50-212","407:description:217-292","407:description:295-369","407:description:374-477","407:description:480-509","407:objective:1-113"},["minimumStage"]=2,["questID"]=407,["sourceHash"]="2bd367a4ca11788e71f31e8aa515139ce42cfecc8ea701df946f0bcda05557d1"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1537",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A captured Scarlet Zealot was held in the Gallows’ End Tavern cellar, where a Forsaken apothecary sent a pumpkin laced with an experimental formula.",["title"]="Scarlet Zealot"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"409:description:1-121","409:description:124-200","409:description:205-277","409:description:280-334","409:description:339-386","409:description:389-433","409:description:436-499","409:objective:1-29","409:objective:34-68","409:objective:73-104"},["minimumStage"]=2,["questID"]=409,["sourceHash"]="90ec6819e62c17a47cf4895c3414c90306510d6ea81551a90b61c6e613b13c14"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1946",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lillith Nefara was a powerful Scourge agent whose destruction was set as proof that an undead stranger opposed the Lich King.",["title"]="Lillith Nefara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"409:description:1-121","409:description:124-200","409:description:205-277","409:description:280-334","409:description:339-386","409:description:389-433","409:description:436-499","409:objective:1-29","409:objective:34-68","409:objective:73-104"},["minimumStage"]=2,["questID"]=409,["sourceHash"]="90ec6819e62c17a47cf4895c3414c90306510d6ea81551a90b61c6e613b13c14"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1946",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A Candle of Beckoning lit upon the old bloody altar off the island’s southern coast could awaken her.",["title"]="Lillith Nefara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"414:description:1-81","414:description:84-121","414:description:124-212","414:description:217-322","414:description:325-365","414:description:370-444","414:objective:1-54"},["minimumStage"]=2,["questID"]=414,["sourceHash"]="8ce741c5be37a91a404b04bcbd1f7ee7cd143e569aca3700f1fd8a8d52eeb739"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1340",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mountaineer Kadrell usually patrolled the road through Thelsamar in Loch Modan.",["title"]="Mountaineer Kadrell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"414:description:1-81","414:description:84-121","414:description:124-212","414:description:217-322","414:description:325-365","414:description:370-444","414:objective:1-54"},["minimumStage"]=2,["questID"]=414,["sourceHash"]="8ce741c5be37a91a404b04bcbd1f7ee7cd143e569aca3700f1fd8a8d52eeb739"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1340",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A fellow mountaineer sent him a cask of his brother’s Shimmer Stout, eager to learn whether Kadrell shared his taste for it.",["title"]="Mountaineer Kadrell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"436:description:1-79","436:description:82-171","436:description:176-285","436:description:290-347","436:description:350-421","436:description:426-511","436:objective:1-28"},["minimumStage"]=2,["questID"]=436,["sourceHash"]="238c47d8343b779c2017db16644c08be3f427587628e6e6ab2fb43a00e51dcd2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1344",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Prospector Ironband led an excavation of ancient ruins east of Loch Modan’s lake, with Magmar Fellhew managing the site’s details.",["title"]="Prospector Ironband"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"436:description:1-79","436:description:82-171","436:description:176-285","436:description:290-347","436:description:350-421","436:description:426-511","436:objective:1-28"},["minimumStage"]=2,["questID"]=436,["sourceHash"]="238c47d8343b779c2017db16644c08be3f427587628e6e6ab2fb43a00e51dcd2"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-1344",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ironband’s colleague described him as a stout dwarf, honest and focused on results.",["title"]="Prospector Ironband"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"436:description:1-79","436:description:82-171","436:description:176-285","436:description:290-347","436:description:350-421","436:description:426-511","436:objective:1-28"},["minimumStage"]=2,["questID"]=436,["sourceHash"]="238c47d8343b779c2017db16644c08be3f427587628e6e6ab2fb43a00e51dcd2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1344",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A slowdown despite repeated supply deliveries led that colleague to suspect outside interference with his dig.",["title"]="Prospector Ironband"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"437:description:1-119","437:description:122-261","437:description:266-293","437:description:298-345","437:description:348-433","437:description:438-467","437:description:470-497","437:objective:1-40","437:objective:45-77","437:objective:82-153"},["minimumStage"]=2,["questID"]=437,["sourceHash"]="75dc52c2dd51c80c5284aa0fdd3252d58096e277d579cad537dda936679b31c6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1983",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nightlash was the banshee reinforcing the Rot Hide position at Silverpine’s old farm known as the Dead Fields.",["title"]="Nightlash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"437:description:1-119","437:description:122-261","437:description:266-293","437:description:298-345","437:description:348-433","437:description:438-467","437:description:470-497","437:objective:1-40","437:objective:45-77","437:objective:82-153"},["minimumStage"]=2,["questID"]=437,["sourceHash"]="75dc52c2dd51c80c5284aa0fdd3252d58096e277d579cad537dda936679b31c6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1983",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her magic repeatedly routed the small forces sent against the farm, prompting a targeted effort to draw her out and destroy her.",["title"]="Nightlash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"437:description:1-119","437:description:122-261","437:description:266-293","437:description:298-345","437:description:348-433","437:description:438-467","437:description:470-497","437:objective:1-40","437:objective:45-77","437:objective:82-153"},["minimumStage"]=2,["questID"]=437,["sourceHash"]="75dc52c2dd51c80c5284aa0fdd3252d58096e277d579cad537dda936679b31c6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1983",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her essence was expected to turn to dust, which the attackers’ commander requested as proof.",["title"]="Nightlash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"455:description:1-56","455:description:59-100","455:description:103-237","455:description:242-325","455:description:328-372","455:description:377-456","455:description:461-486","455:description:489-500","455:objective:1-19","455:objective:24-70","455:objective:75-119"},["minimumStage"]=2,["questID"]=455,["sourceHash"]="524fc92094783dd80c19c622aad1bc8823e273df6cb37f75623f64b57af86ca8"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2086",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Valstag Ironjaw received reports in Menethil Harbor from fighters breaking through the Dragonmaw-held Dun Algaz route.",["title"]="Valstag Ironjaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"473:description:6-76","473:description:79-166","473:description:169-207","473:objective:1-29","473:completion:5-81","473:completion:83-103","473:completion:108-133"},["minimumStage"]=4,["questID"]=473,["sourceHash"]="34bdac1645ada41117350efa2ca4d0aa78771f05d9e85b2a4a12fcef01c7c2c8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2086",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He briefed Captain Stoutfist on that fighting, connecting the threatened pass to Menethil’s wider campaign against the clan.",["title"]="Valstag Ironjaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"464:description:1-124","464:description:127-217","464:description:220-310","464:description:315-388","464:description:393-430","464:description:433-479","464:objective:1-51","464:completion:1-16","464:completion:18-124","464:completion:129-231","464:completion:233-344","464:completion:349-437"},["minimumStage"]=4,["questID"]=464,["sourceHash"]="e527556b5812e30bd542f142940276b7a1dea804db0869960114a4d969dff5b8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2091",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nek’rosh was the son of Nekros, the Dragonmaw leader killed after the clan lost magical control of the red dragons.",["title"]="Chieftain Nek'rosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"464:description:1-124","464:description:127-217","464:description:220-310","464:description:315-388","464:description:393-430","464:description:433-479","464:objective:1-51","464:completion:1-16","464:completion:18-124","464:completion:129-231","464:completion:233-344","464:completion:349-437"},["minimumStage"]=4,["questID"]=464,["sourceHash"]="e527556b5812e30bd542f142940276b7a1dea804db0869960114a4d969dff5b8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2091",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stoutfist reported that Nek’rosh had sworn revenge against the dragons that slew his father.",["title"]="Chieftain Nek'rosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"465:description:1-74","465:description:79-141","465:description:144-225","465:description:230-266","465:description:269-304","465:description:309-331","465:description:334-396","465:description:401-451","465:description:454-508","465:objective:1-32"},["minimumStage"]=2,["questID"]=465,["sourceHash"]="4bb00cf6a37997d979e4f46d767449168327fdb033e7559498d3d5247bb3ce59"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2091",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nek’rosh built catapults to besiege Menethil while fighting in Dun Algaz cut the harbor off from reinforcements.",["title"]="Chieftain Nek'rosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"488:description:1-22","488:description:25-119","488:description:124-218","488:description:221-284","488:description:289-337","488:description:341-350","488:description:353-446","488:description:451-488","488:objective:1-121"},["minimumStage"]=2,["questID"]=488,["sourceHash"]="26b585f13e96c6f28f20630140abb27a37aa4d1f204ce30da8c87278c7757f5d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1986",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Webwood spider silk was among the forest reagents Zenn sought for secretive business, alongside owl feathers and nightsaber fangs.",["title"]="Webwood Spider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"488:description:1-22","488:description:25-119","488:description:124-218","488:description:221-284","488:description:289-337","488:description:341-350","488:description:353-446","488:description:451-488","488:objective:1-121"},["minimumStage"]=2,["questID"]=488,["sourceHash"]="26b585f13e96c6f28f20630140abb27a37aa4d1f204ce30da8c87278c7757f5d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1995",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Strigid owl feathers were gathered as forest reagents for Zenn’s concealed work.",["title"]="Strigid Owl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"488:description:1-22","488:description:25-119","488:description:124-218","488:description:221-284","488:description:289-337","488:description:341-350","488:description:353-446","488:description:451-488","488:objective:1-121"},["minimumStage"]=2,["questID"]=488,["sourceHash"]="26b585f13e96c6f28f20630140abb27a37aa4d1f204ce30da8c87278c7757f5d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2042",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nightsaber fangs were among the animal reagents requested by Zenn, who urged that the arrangement remain secret.",["title"]="Nightsaber"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"492:description:1-102","492:description:105-232","492:description:237-327","492:description:330-413","492:objective:1-57"},["minimumStage"]=2,["questID"]=492,["sourceHash"]="391e78ddf5bfbb24954b9096aba1b1209a2f7ca969970f34a4b29abe79ddd6d0"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2211",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Deathguard held the captured dwarven mountaineer in the Gallows’ End Tavern cellar, where he was intended to test a Forsaken apothecary’s special drink.",["title"]="Captured Mountaineer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"495:description:1-98","495:description:100-172","495:description:174-228","495:description:233-297","495:description:299-392","495:description:397-506","495:objective:1-61"},["minimumStage"]=2,["questID"]=495,["sourceHash"]="aa0427d172b67081b5f6d905b4c80e8a511c6c9eb4847ce55e1351b317f6813d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2278",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Melisara was the lieutenant at Tarren Mill assigned to the consequences of Mug’Thol’s defiance.",["title"]="Melisara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"495:description:1-98","495:description:100-172","495:description:174-228","495:description:233-297","495:description:299-392","495:description:397-506","495:objective:1-61"},["minimumStage"]=2,["questID"]=495,["sourceHash"]="aa0427d172b67081b5f6d905b4c80e8a511c6c9eb4847ce55e1351b317f6813d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2278",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mug’Thol had put on the Crown of Will instead of returning it to Sylvanas, breaking the possession that had bound him to her service.",["title"]="Melisara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"496:description:1-40","496:description:43-96","496:description:101-153","496:description:156-287","496:description:292-436","496:description:439-502","496:objective:1-82"},["minimumStage"]=2,["questID"]=496,["sourceHash"]="fddfe9214c0df5071e0611d3b8d50b3b4f17cc21f0636947afc173854fe7db94"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-2351",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gray bears ranged outside Tarren Mill, where their tongues were sought for an apothecary’s studies of killing agents.",["title"]="Gray Bear"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"498:description:1-134","498:description:139-244","498:description:246-313","498:description:315-370","498:description:375-428","498:description:430-498","498:objective:1-78"},["minimumStage"]=2,["questID"]=498,["sourceHash"]="2811d557acd056545ecc6d3cfc8ede8fe612b64533fe4b83c18fe1df8e2d9f24"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tog’thar was among the warriors taken captive when a mission to retrieve an object and investigate the Syndicate was overwhelmed at Durnholde.",["title"]="Tog'thar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"498:description:1-134","498:description:139-244","498:description:246-313","498:description:315-370","498:description:375-428","498:description:430-498","498:objective:1-78"},["minimumStage"]=2,["questID"]=498,["sourceHash"]="2811d557acd056545ecc6d3cfc8ede8fe612b64533fe4b83c18fe1df8e2d9f24"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-2238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He and Drull remained imprisoned at Durnholde southeast of Tarren Mill, across the river, after one comrade escaped.",["title"]="Tog'thar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"501:description:11-83","501:description:86-136","501:description:139-246","501:description:251-331","501:description:334-352","501:description:355-460","501:description:463-507","501:objective:1-73"},["minimumStage"]=2,["questID"]=501,["sourceHash"]="4c0d26d21ef12839eee306eb579fcf169e60e9a9a4e34927726d48758cfa5954"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2406",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A Tarren Mill apothecary sought mountain lion blood for an experimental death-brew, linking the animals to the Forsaken’s plague research.",["title"]="Mountain Lion"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7068:description:1-51","7068:description:53-79","7068:description:81-196","7068:description:201-285","7068:description:287-367","7068:description:372-433","7068:objective:1-89"},["minimumStage"]=2,["questID"]=7068,["sourceHash"]="1dec91053904e75ec1414a9c6b02e3df550d73c49e563f2b940b24129b500c34"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7311",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Uthel’nay sought the purple shadowshard crystals carried by Maraudon’s rock creatures, offering crafted payment for their recovery.",["title"]="Uthel'nay"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7068:description:1-51","7068:description:53-79","7068:description:81-196","7068:description:201-285","7068:description:287-367","7068:description:372-433","7068:objective:1-89"},["minimumStage"]=2,["questID"]=7068,["sourceHash"]="1dec91053904e75ec1414a9c6b02e3df550d73c49e563f2b940b24129b500c34"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7311",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recognized the strong magic within the centaur holy place and warned that entering it would be dangerous enough to warrant companions.",["title"]="Uthel'nay"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7081:description:1-56","7081:description:59-130","7081:description:133-170","7081:description:175-215","7081:description:218-296","7081:description:299-341","7081:description:346-449","7081:objective:1-87"},["minimumStage"]=2,["questID"]=7081,["sourceHash"]="ced3c46fa03648f3f89cf525456434089e72f253aa6bf1d12d4f4720f96da944"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13777",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sergeant Durgen Stormpike instructed Alliance recruits to assault enemy-held graveyards in Alterac Valley.",["title"]="Sergeant Durgen Stormpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7081:description:1-56","7081:description:59-130","7081:description:133-170","7081:description:175-215","7081:description:218-296","7081:description:299-341","7081:description:346-449","7081:objective:1-87"},["minimumStage"]=2,["questID"]=7081,["sourceHash"]="ced3c46fa03648f3f89cf525456434089e72f253aa6bf1d12d4f4720f96da944"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13777",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He distinguished tearing down an enemy banner from holding the position long enough for relieving troops to secure it.",["title"]="Sergeant Durgen Stormpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7082:description:1-53","7082:description:56-130","7082:description:133-187","7082:description:192-239","7082:description:242-323","7082:description:328-380","7082:description:382-484","7082:objective:1-87"},["minimumStage"]=2,["questID"]=7082,["sourceHash"]="238f7a381b221f4902799ce66413c5f99b1692cad617e896d81d1e7d1388d7a3"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13776",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Corporal Teeka Bloodsnarl directed Horde assaults against Alliance-held graveyards along Alterac’s shifting battle lines.",["title"]="Corporal Teeka Bloodsnarl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7082:description:1-53","7082:description:56-130","7082:description:133-187","7082:description:192-239","7082:description:242-323","7082:description:328-380","7082:description:382-484","7082:objective:1-87"},["minimumStage"]=2,["questID"]=7082,["sourceHash"]="238f7a381b221f4902799ce66413c5f99b1692cad617e896d81d1e7d1388d7a3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-13776",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She stressed that taking down the opposing banner began the attack, while holding the ground allowed Horde troops to arrive and claim it.",["title"]="Corporal Teeka Bloodsnarl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7241:description:1-49","7241:description:51-148","7241:description:153-271","7241:description:276-335","7241:description:340-419","7241:description:421-470","7241:description:472-507","7241:objective:1-60","7241:objective:62-190","7241:objective:192-278"},["minimumStage"]=2,["questID"]=7241,["sourceHash"]="a825160cea5a875a259e57987e9d1dfa5dffec30aa1a155613c975a5fb705448"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-13842",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ambassador Rokhstrom recruited fighters to defend the Frostwolf clan against the Stormpike Guard.",["title"]="Frostwolf Ambassador Rokhstrom"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7241:description:1-49","7241:description:51-148","7241:description:153-271","7241:description:276-335","7241:description:340-419","7241:description:421-470","7241:description:472-507","7241:objective:1-60","7241:objective:62-190","7241:objective:192-278"},["minimumStage"]=2,["questID"]=7241,["sourceHash"]="a825160cea5a875a259e57987e9d1dfa5dffec30aa1a155613c975a5fb705448"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-13842",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed those taking up the cause to Warmaster Laggrond at Alterac Valley’s entrance north of Tarren Mill.",["title"]="Frostwolf Ambassador Rokhstrom"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7321:description:1-59","7321:description:61-113","7321:description:115-187","7321:description:189-199","7321:description:204-261","7321:description:264-391","7321:description:396-495","7321:objective:1-93"},["minimumStage"]=2,["questID"]=7321,["sourceHash"]="401ea472b3f743b0cc5fd7b6e7e77292da9cdca970680924a0ff7e4da200eb3b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2393",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Christoph Jeffcoat prided himself on a secret turtle bisque recipe, joking that its taste could bring people back from the dead.",["title"]="Christoph Jeffcoat"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7321:description:1-59","7321:description:61-113","7321:description:115-187","7321:description:189-199","7321:description:204-261","7321:description:264-391","7321:description:396-495","7321:objective:1-93"},["minimumStage"]=2,["questID"]=7321,["sourceHash"]="401ea472b3f743b0cc5fd7b6e7e77292da9cdca970680924a0ff7e4da200eb3b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2393",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Work kept him from his former snapjaw hunts at Lake Lordamere, so he offered instruction in exchange for turtle meat and soothing spices.",["title"]="Christoph Jeffcoat"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7441:description:1-54","7441:description:56-121","7441:description:123-244","7441:description:249-381","7441:description:386-429","7441:description:434-487","7441:objective:1-49","7441:objective:51-142","7441:objective:147-245"},["minimumStage"]=2,["questID"]=7441,["sourceHash"]="6e5de3042136a6e87e9c265e582a7e3bbc4e882c743237be394cfbb4ffbaf058"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-14355",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Azj’Tordin was robbed by Pusillin while escaping the fallen prince’s control, losing both his incantation book and the key to Eldre’Thalas.",["title"]="Azj'Tordin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7441:description:1-54","7441:description:56-121","7441:description:123-244","7441:description:249-381","7441:description:386-429","7441:description:434-487","7441:objective:1-49","7441:objective:51-142","7441:objective:147-245"},["minimumStage"]=2,["questID"]=7441,["sourceHash"]="6e5de3042136a6e87e9c265e582a7e3bbc4e882c743237be394cfbb4ffbaf058"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14355",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Having traded immortality for freedom, he no longer wanted the key but urgently sought the book from the imp in the Warpwood Quarter.",["title"]="Azj'Tordin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7461:description:1-22","7461:description:24-57","7461:description:62-94","7461:description:96-142","7461:description:144-213","7461:description:215-252","7461:description:254-313","7461:description:315-363","7461:objective:1-92","7461:objective:94-188","7461:objective:193-277","7461:objective:279-328","7461:objective:333-414"},["minimumStage"]=2,["questID"]=7461,["sourceHash"]="a053e1177887017ca1d0fc9cbe432b26a158fe07e25dba849ca4b87d2b3466ee"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14358",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Shen’dralar Ancient wanted Eldre’Thalas’s madness ended and its spirits laid to rest, declaring that the immortals’ age had passed.",["title"]="Shen'dralar Ancient"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7461:description:1-22","7461:description:24-57","7461:description:62-94","7461:description:96-142","7461:description:144-213","7461:description:215-252","7461:description:254-313","7461:description:315-363","7461:objective:1-92","7461:objective:94-188","7461:objective:193-277","7461:objective:279-328","7461:objective:333-414"},["minimumStage"]=2,["questID"]=7461,["sourceHash"]="a053e1177887017ca1d0fc9cbe432b26a158fe07e25dba849ca4b87d2b3466ee"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14358",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The ancient described breaking the pylon guardians’ protection, confronting Immol’thar and then striking the prince once his power was reduced.",["title"]="Shen'dralar Ancient"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7463:description:1-10","7463:description:12-25","7463:description:27-65","7463:description:67-93","7463:description:95-104","7463:description:109-191","7463:description:196-213","7463:description:218-253","7463:description:255-309","7463:description:311-342","7463:description:347-443","7463:description:445-499","7463:objective:1-85","7463:objective:87-159"},["minimumStage"]=2,["questID"]=7463,["sourceHash"]="ab2c84f6c5a689a94be72236a4b9622d5d7d2b461540c49cee555eeb4361a24e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14368",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lorekeeper Lydros claimed five centuries had passed since he last saw a traveling mage of the visitor’s kind.",["title"]="Lorekeeper Lydros"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7463:description:1-10","7463:description:12-25","7463:description:27-65","7463:description:67-93","7463:description:95-104","7463:description:109-191","7463:description:196-213","7463:description:218-253","7463:description:255-309","7463:description:311-342","7463:description:347-443","7463:description:445-499","7463:objective:1-85","7463:objective:87-159"},["minimumStage"]=2,["questID"]=7463,["sourceHash"]="ab2c84f6c5a689a94be72236a4b9622d5d7d2b461540c49cee555eeb4361a24e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14368",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Hydrospawn’s elemental essence brought from the Warpwood Quarter so its anomalous presence could be catalogued, offering a useful cantrip in return.",["title"]="Lorekeeper Lydros"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7481:description:1-143","7481:description:148-296","7481:description:301-403","7481:description:408-437","7481:description:439-504","7481:objective:1-38","7481:objective:40-128"},["minimumStage"]=2,["questID"]=7481,["sourceHash"]="43d6429d2c57b7bf8f530d6e412110e4bc28772c3cda8ae6e0d0f4fb21f7bebf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14373",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sage Korolusk sought the knowledge carried by the missing elven master Kariel Winthalus, whether the fugitive was still alive or not.",["title"]="Sage Korolusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7481:description:1-143","7481:description:148-296","7481:description:301-403","7481:description:408-437","7481:description:439-504","7481:objective:1-38","7481:objective:40-128"},["minimumStage"]=2,["questID"]=7481,["sourceHash"]="43d6429d2c57b7bf8f530d6e412110e4bc28772c3cda8ae6e0d0f4fb21f7bebf"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14373",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The search followed Kariel from ruined Quel’Thalas through the Burning Steppes and across the sea to Feralas, where Eldre’Thalas seemed a likely refuge.",["title"]="Sage Korolusk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7482:description:1-143","7482:description:148-296","7482:description:301-403","7482:description:408-437","7482:description:439-504","7482:objective:1-38","7482:objective:40-131"},["minimumStage"]=2,["questID"]=7482,["sourceHash"]="cb255168d7b56b33ce447ae39db5ebdb18ece37113c0800ff6a7a0c082b2d695"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14374",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scholar Runethorn sought Kariel Winthalus and the ancient elven artifacts he carried when fleeing his devastated homeland.",["title"]="Scholar Runethorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7482:description:1-143","7482:description:148-296","7482:description:301-403","7482:description:408-437","7482:description:439-504","7482:objective:1-38","7482:objective:40-131"},["minimumStage"]=2,["questID"]=7482,["sourceHash"]="cb255168d7b56b33ce447ae39db5ebdb18ece37113c0800ff6a7a0c082b2d695"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14374",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The trail led from Quel’Thalas through the Burning Steppes to Feralas, where the scholar suspected Kariel had entered Eldre’Thalas.",["title"]="Scholar Runethorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7645:description:1-123","7645:description:126-152","7645:description:155-182","7645:description:187-221","7645:description:223-243","7645:description:245-265","7645:description:268-363","7645:description:366-442","7645:description:447-494","7645:objective:1-157","7645:objective:160-221","7645:objective:226-295"},["minimumStage"]=2,["questID"]=7645,["sourceHash"]="bd1015fe25be5ad7152f4eb6862053bfc0de6a8f323363bd47cb66b4b0144eba"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2357",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Merideth Carlson wanted vindication after the Silver Hand dismissed her claim that she could prepare feed for spiritual horses.",["title"]="Merideth Carlson"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7645:description:1-123","7645:description:126-152","7645:description:155-182","7645:description:187-221","7645:description:223-243","7645:description:245-265","7645:description:268-363","7645:description:366-442","7645:description:447-494","7645:objective:1-157","7645:objective:160-221","7645:objective:226-295"},["minimumStage"]=2,["questID"]=7645,["sourceHash"]="bd1015fe25be5ad7152f4eb6862053bfc0de6a8f323363bd47cb66b4b0144eba"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2357",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her special blend required the Argent Dawn’s enriched manna biscuits, and she demanded gold as compensation for the scorn she had endured.",["title"]="Merideth Carlson"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7841:description:1-76","7841:description:78-129","7841:description:134-146","7841:description:151-247","7841:description:249-336","7841:description:341-363","7841:objective:1-165","7841:objective:167-207","7841:objective:212-318"},["minimumStage"]=2,["questID"]=7841,["sourceHash"]="90029f3b72c4d9ac9863592e796bd284d58807611958e5e0e4e424b3c73d4343"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-14738",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Otho Moji’ko opposed the Wildhammer’s alliance with the Highvale high elves and called for attacks on those elves as a warning to the dwarves.",["title"]="Otho Moji'ko"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7841:description:1-76","7841:description:78-129","7841:description:134-146","7841:description:151-247","7841:description:249-336","7841:description:341-363","7841:objective:1-165","7841:objective:167-207","7841:objective:212-318"},["minimumStage"]=2,["questID"]=7841,["sourceHash"]="90029f3b72c4d9ac9863592e796bd284d58807611958e5e0e4e424b3c73d4343"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14738",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He framed the violence as a message that the Hinterlands’ trolls would punish their enemies’ new alliances.",["title"]="Otho Moji'ko"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7844:description:1-61","7844:description:63-180","7844:description:185-273","7844:description:278-443","7844:description:448-498","7844:objective:1-127","7844:objective:129-169","7844:objective:174-324"},["minimumStage"]=2,["questID"]=7844,["sourceHash"]="889b8a692935d65a57a073aa5a5ff4f4d32c923b38a638495a6d18bb3bc4be82"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-14739",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mystic Yayo’jin condemned the Vilebranch for feeding on other trolls and humanoids, rejecting any kinship beyond sharing the region.",["title"]="Mystic Yayo'jin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7844:description:1-61","7844:description:63-180","7844:description:185-273","7844:description:278-443","7844:description:448-498","7844:objective:1-127","7844:objective:129-169","7844:objective:174-324"},["minimumStage"]=2,["questID"]=7844,["sourceHash"]="889b8a692935d65a57a073aa5a5ff4f4d32c923b38a638495a6d18bb3bc4be82"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14739",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With Zul’jin still absent, Yayo’jin appealed to others to confront the tribe rather than await the leader he believed would have destroyed it.",["title"]="Mystic Yayo'jin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7905:description:1-29","7905:description:32-112","7905:description:117-189","7905:description:192-261","7905:description:266-329","7905:description:332-346","7905:description:349-357","7905:objective:1-95"},["minimumStage"]=2,["questID"]=7905,["sourceHash"]="21232eff654d87946d251ad7eb1f72718f9ea05334cc15f6dddef30345220ba0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14842",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Melnan Darkstone promoted the Darkmoon Faire’s visit outside Goldshire and distributed vouchers for prize tickets.",["title"]="Melnan Darkstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7905:description:1-29","7905:description:32-112","7905:description:117-189","7905:description:192-261","7905:description:266-329","7905:description:332-346","7905:description:349-357","7905:objective:1-95"},["minimumStage"]=2,["questID"]=7905,["sourceHash"]="21232eff654d87946d251ad7eb1f72718f9ea05334cc15f6dddef30345220ba0"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-14842",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed visitors to Gelvas Grimgate inside the carnival to redeem their vouchers.",["title"]="Melnan Darkstone"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7926:description:1-29","7926:description:32-112","7926:description:117-189","7926:description:192-261","7926:description:266-328","7926:description:331-345","7926:description:348-356","7926:objective:1-95"},["minimumStage"]=2,["questID"]=7926,["sourceHash"]="113da8c7788201286f7913c6a4a4fded1260ccb96e79bd3a65dbc1b6d8ce1cd7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14843",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kruban Darkblade advertised the Darkmoon Faire’s visit outside Thunder Bluff in Mulgore.",["title"]="Kruban Darkblade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7926:description:1-29","7926:description:32-112","7926:description:117-189","7926:description:192-261","7926:description:266-328","7926:description:331-345","7926:description:348-356","7926:objective:1-95"},["minimumStage"]=2,["questID"]=7926,["sourceHash"]="113da8c7788201286f7913c6a4a4fded1260ccb96e79bd3a65dbc1b6d8ce1cd7"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-14843",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His voucher could be exchanged with Gelvas Grimgate for free prize tickets at the carnival.",["title"]="Kruban Darkblade"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8053:description:1-18","8053:description:21-55","8053:description:58-95","8053:description:98-133","8053:description:136-177","8053:description:180-225","8053:description:228-258","8053:description:261-310","8053:description:315-349","8053:description:352-367","8053:description:370-396","8053:description:399-431","8053:description:434-487","8053:objective:1-51","8053:objective:54-143","8053:objective:148-215"},["minimumStage"]=2,["questID"]=8053,["sourceHash"]="a5ed48a41cbdf88841262d3c86a2d2cc5d6ee950c47f6dfc7110535384f51303"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14902",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jin’rokh the Breaker offered the battle gear of Zandalar’s freethinkers to outsiders who brought Paragons of Power from Zul’Gurub.",["title"]="Jin'rokh the Breaker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8053:description:1-18","8053:description:21-55","8053:description:58-95","8053:description:98-133","8053:description:136-177","8053:description:180-225","8053:description:228-258","8053:description:261-310","8053:description:315-349","8053:description:352-367","8053:description:370-396","8053:description:399-431","8053:description:434-487","8053:objective:1-51","8053:objective:54-143","8053:objective:148-215"},["minimumStage"]=2,["questID"]=8053,["sourceHash"]="a5ed48a41cbdf88841262d3c86a2d2cc5d6ee950c47f6dfc7110535384f51303"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14902",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He respected freethinkers who endured oppression and would die for their beliefs, treating that resolve as worthy of acknowledgment even in a heathen.",["title"]="Jin'rokh the Breaker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8056:description:1-80","8056:description:83-199","8056:description:202-321","8056:description:326-420","8056:description:423-507","8056:objective:1-53","8056:objective:56-145","8056:objective:150-216"},["minimumStage"]=2,["questID"]=8056,["sourceHash"]="ce6dabf9cca7287812c059f9f903ecce5ce0cf269eae385618770cd11530797d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14904",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maywiki of Zuldazar judged offerings from Zul’Gurub in return for bracers prized by Zandalar’s augurs.",["title"]="Maywiki of Zuldazar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8056:description:1-80","8056:description:83-199","8056:description:202-321","8056:description:326-420","8056:description:423-507","8056:objective:1-53","8056:objective:56-145","8056:objective:150-216"},["minimumStage"]=2,["questID"]=8056,["sourceHash"]="ce6dabf9cca7287812c059f9f903ecce5ce0cf269eae385618770cd11530797d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14904",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maywiki distinguished the augurs’ revered divination through bones and leaves from a witch doctor’s practice of hexing.",["title"]="Maywiki of Zuldazar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8059:description:1-101","8059:description:104-181","8059:description:184-318","8059:description:321-361","8059:description:366-457","8059:description:460-500","8059:objective:1-57","8059:objective:60-149","8059:objective:154-224"},["minimumStage"]=2,["questID"]=8059,["sourceHash"]="8f01143b1bcc04f7c449e30c5b89296b21b903c69cd8c97ab4689b210c12e231"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14903",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Al’tabim the All-Seeing offered knowledge of the demoniacs’ power in exchange for Paragons of Power recovered from Zul’Gurub.",["title"]="Al'tabim the All-Seeing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8059:description:1-101","8059:description:104-181","8059:description:184-318","8059:description:321-361","8059:description:366-457","8059:description:460-500","8059:objective:1-57","8059:objective:60-149","8059:objective:154-224"},["minimumStage"]=2,["questID"]=8059,["sourceHash"]="8f01143b1bcc04f7c449e30c5b89296b21b903c69cd8c97ab4689b210c12e231"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14903",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described demoniacs admitting a demon through ritual, then mastering it from within rather than surrendering to possession.",["title"]="Al'tabim the All-Seeing"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8062:description:1-132","8062:description:135-251","8062:description:254-347","8062:description:352-421","8062:description:424-495","8062:objective:1-105","8062:objective:108-197","8062:objective:202-270"},["minimumStage"]=2,["questID"]=8062,["sourceHash"]="357f24c4be119177445485b40c69e2e638aa108e1ca7f6574128f70b75c44afe"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14905",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Falthir the Sightless tested hunters through offerings brought from Zul’Gurub, measuring them against Zandalar’s finest predators.",["title"]="Falthir the Sightless"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8062:description:1-132","8062:description:135-251","8062:description:254-347","8062:description:352-421","8062:description:424-495","8062:objective:1-105","8062:objective:108-197","8062:objective:202-270"},["minimumStage"]=2,["questID"]=8062,["sourceHash"]="357f24c4be119177445485b40c69e2e638aa108e1ca7f6574128f70b75c44afe"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-14905",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He recalled that predators had fed the tribe during the dark years following the Gurubashi Empire’s fall.",["title"]="Falthir the Sightless"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8105:description:1-72","8105:description:75-197","8105:description:200-270","8105:description:275-375","8105:description:378-431","8105:description:436-492","8105:objective:1-118"},["minimumStage"]=2,["questID"]=8105,["sourceHash"]="d4d02a5095cdbf3b61511d7c059ff96d1970a9032438d5e64549ef323ee4686a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-14983",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Field Marshal Oslight directed Alliance attacks on Arathi Basin’s resource sites to supply the war effort.",["title"]="Field Marshal Oslight"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8105:description:1-72","8105:description:75-197","8105:description:200-270","8105:description:275-375","8105:description:378-431","8105:description:436-492","8105:objective:1-118"},["minimumStage"]=2,["questID"]=8105,["sourceHash"]="d4d02a5095cdbf3b61511d7c059ff96d1970a9032438d5e64549ef323ee4686a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14983",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He charged fighters with pulling down enemy banners at the farm, mine, lumber mill and smithy beyond their own base.",["title"]="Field Marshal Oslight"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8120:description:1-103","8120:description:106-211","8120:description:214-281","8120:description:286-374","8120:description:377-450","8120:description:464-508","8120:objective:1-118"},["minimumStage"]=2,["questID"]=8120,["sourceHash"]="928699ab4373de9f4045863586630a0e1e7a117c44b25a730fbd9d9bf644d2bb"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15021",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Deathmaster Dwire organized the Defilers’ assaults on Arathi Basin’s mine, lumber mill, smithy and stables.",["title"]="Deathmaster Dwire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8120:description:1-103","8120:description:106-211","8120:description:214-281","8120:description:286-374","8120:description:377-450","8120:description:464-508","8120:objective:1-118"},["minimumStage"]=2,["questID"]=8120,["sourceHash"]="928699ab4373de9f4045863586630a0e1e7a117c44b25a730fbd9d9bf644d2bb"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15021",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted to deny the League of Arathor the food and supplies it sought and prevent humans from reclaiming Arathi.",["title"]="Deathmaster Dwire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8121:description:1-87","8121:description:90-205","8121:description:210-263","8121:description:266-348","8121:description:351-436","8121:description:441-503","8121:objective:1-101"},["minimumStage"]=2,["questID"]=8121,["sourceHash"]="698c96eafcb17a087da7e52fa045f7ce082c11981ad8c6021360ace3da39be5a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15021",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His later challenge was to hold four strategic positions together, demonstrating how quickly the League’s gains could be lost.",["title"]="Deathmaster Dwire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8149:description:1-152","8149:description:155-259","8149:description:264-346","8149:description:349-394","8149:description:397-492","8149:objective:1-178"},["minimumStage"]=2,["questID"]=8149,["sourceHash"]="c9a44665fc525ad1d13008792e657061cdbcb513a9477f79d98ae9d323c6c428"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15011",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wagner Hammerstrike guided the Alliance’s Harvest Festival tribute to Uther Lightbringer.",["title"]="Wagner Hammerstrike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8149:description:1-152","8149:description:155-259","8149:description:264-346","8149:description:349-394","8149:description:397-492","8149:objective:1-178"},["minimumStage"]=2,["questID"]=8149,["sourceHash"]="c9a44665fc525ad1d13008792e657061cdbcb513a9477f79d98ae9d323c6c428"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15011",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent an offering to Uther’s statue at his Western Plaguelands tomb, commemorating sacrifice rather than a military victory.",["title"]="Wagner Hammerstrike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8150:description:1-152","8150:description:155-258","8150:description:263-359","8150:description:362-405","8150:description:408-502","8150:objective:1-115","8150:objective:118-195"},["minimumStage"]=2,["questID"]=8150,["sourceHash"]="30d0c073e5f1be68c35dc0fd060a9f8bce957291315ec2e41ddce57d9f4a6513"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15012",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Javnir Nashak organized a Harvest Festival tribute to Grom Hellscream as an example of strength and sacrifice.",["title"]="Javnir Nashak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8150:description:1-152","8150:description:155-258","8150:description:263-359","8150:description:362-405","8150:description:408-502","8150:objective:1-115","8150:objective:118-195"},["minimumStage"]=2,["questID"]=8150,["sourceHash"]="30d0c073e5f1be68c35dc0fd060a9f8bce957291315ec2e41ddce57d9f4a6513"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15012",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the offering to Grom’s monument in Ashenvale’s Demon Fall Canyon and remained only for the festival.",["title"]="Javnir Nashak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8195:description:1-62","8195:description:65-178","8195:description:183-224","8195:description:227-312","8195:description:315-401","8195:description:404-497"},["minimumStage"]=2,["questID"]=8195,["sourceHash"]="4e91a719b416a207d6a782bbcafa85443d5258cc02108feea596373b7ea0445b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15070",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vinchaxa exchanged sets of Zul’Gurub tribal coins for Zandalar Honor Tokens.",["title"]="Vinchaxa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8195:description:1-62","8195:description:65-178","8195:description:183-224","8195:description:227-312","8195:description:315-401","8195:description:404-497"},["minimumStage"]=2,["questID"]=8195,["sourceHash"]="4e91a719b416a207d6a782bbcafa85443d5258cc02108feea596373b7ea0445b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15070",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He described nine kinds of coin imbued with subtle mojo, some desired for battle gear and others exchangeable for Rin’wosho’s wares.",["title"]="Vinchaxa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8201:description:1-11","8201:description:14-78","8201:description:81-238","8201:description:241-259","8201:description:264-382","8201:description:387-424","8201:objective:1-96"},["minimumStage"]=2,["questID"]=8201,["sourceHash"]="25171bb12282ff9d666d745d5bef97cc5f4434ed05dff19fed359e4c50ab5cce"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-14910",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Exzhal sought to stop Hakkar from drawing the sacred gods’ energies through Zul’Gurub’s enthralled high priests.",["title"]="Exzhal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8201:description:1-11","8201:description:14-78","8201:description:81-238","8201:description:241-259","8201:description:264-382","8201:description:387-424","8201:objective:1-96"},["minimumStage"]=2,["questID"]=8201,["sourceHash"]="25171bb12282ff9d666d745d5bef97cc5f4434ed05dff19fed359e4c50ab5cce"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-14910",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He supplied a sacred cord for the priests’ heads, intending their defeat to interrupt the channeling that strengthened the Soulflayer.",["title"]="Exzhal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8275:description:1-34","8275:description:37-93","8275:description:96-195","8275:description:202-357","8275:description:362-392","8275:description:395-427","8275:description:429-502","8275:objective:1-58"},["minimumStage"]=2,["questID"]=8275,["sourceHash"]="2f52ddff2aff03cd003ff5aaddb964233e6cb2acc0aaf336b19aedd2eebf4b84"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15187",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Emissary Jademoon called Alliance adventurers to join the Cenarion Circle’s gathering forces in Silithus.",["title"]="Cenarion Emissary Jademoon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8275:description:1-34","8275:description:37-93","8275:description:96-195","8275:description:202-357","8275:description:362-392","8275:description:395-427","8275:description:429-502","8275:objective:1-58"},["minimumStage"]=2,["questID"]=8275,["sourceHash"]="2f52ddff2aff03cd003ff5aaddb964233e6cb2acc0aaf336b19aedd2eebf4b84"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15187",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jademoon warned that the silithid had prepared unchecked for expansion and directed volunteers to Windcaller Proudhorn at Cenarion Hold.",["title"]="Cenarion Emissary Jademoon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8276:description:1-34","8276:description:37-90","8276:description:93-234","8276:description:239-342","8276:description:345-380","8276:description:385-466","8276:description:469-501","8276:objective:1-58"},["minimumStage"]=2,["questID"]=8276,["sourceHash"]="e3e7d570b6df2525e3753f6f3a157f1b11944bfb8420dca27177bdc268c79fce"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15188",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Emissary Blackhoof rallied Horde combatants to reinforce the Circle’s campaign from Cenarion Hold.",["title"]="Cenarion Emissary Blackhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8276:description:1-34","8276:description:37-90","8276:description:93-234","8276:description:239-342","8276:description:345-380","8276:description:385-466","8276:description:469-501","8276:objective:1-58"},["minimumStage"]=2,["questID"]=8276,["sourceHash"]="e3e7d570b6df2525e3753f6f3a157f1b11944bfb8420dca27177bdc268c79fce"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15188",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tremors near silithid hives suggested large movements before an expansion, giving the appeal an urgency beyond the local desert.",["title"]="Cenarion Emissary Blackhoof"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8277:description:1-36","8277:description:39-120","8277:description:123-141","8277:description:144-221","8277:description:226-335","8277:description:340-435","8277:description:438-511","8277:objective:1-125","8277:objective:127-173"},["minimumStage"]=2,["questID"]=8277,["sourceHash"]="7dbc3f4442ee3fae210ea9d4acff5d42dd42acb84d5caf133be8fa6e5a40221c"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-15189",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Beetix’s cousin Noggle gathered rare herbs for Cenarion Hold’s alchemists until he returned poisoned from a journey.",["title"]="Beetix Ficklespragg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8277:description:1-36","8277:description:39-120","8277:description:123-141","8277:description:144-221","8277:description:226-335","8277:description:340-435","8277:description:438-511","8277:objective:1-125","8277:objective:127-173"},["minimumStage"]=2,["questID"]=8277,["sourceHash"]="7dbc3f4442ee3fae210ea9d4acff5d42dd42acb84d5caf133be8fa6e5a40221c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15189",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Having slowed the venom, Beetix needed likely poison samples from northern scorpids or skitterers to attempt a full antidote.",["title"]="Beetix Ficklespragg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8279:description:1-67","8279:description:70-122","8279:description:125-180","8279:description:185-297","8279:description:300-384","8279:description:387-502","8279:objective:1-78"},["minimumStage"]=2,["questID"]=8279,["sourceHash"]="48178d0e7e69beef60d5d679b3435325a57ceac37f5bb2c4336bf91deded50c4"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-15194",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hermit Ortell had left the Twilight’s Hammer and remained hunted by his former companions.",["title"]="Hermit Ortell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8279:description:1-67","8279:description:70-122","8279:description:125-180","8279:description:185-297","8279:description:300-384","8279:description:387-502","8279:objective:1-78"},["minimumStage"]=2,["questID"]=8279,["sourceHash"]="48178d0e7e69beef60d5d679b3435325a57ceac37f5bb2c4336bf91deded50c4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15194",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Deciphering their tablet required the Twilight Lexicon, whose three chapters the cult entrusted to separate keepers in its camps.",["title"]="Hermit Ortell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8280:description:1-59","8280:description:62-141","8280:description:144-199","8280:description:204-308","8280:description:311-403","8280:description:406-480","8280:objective:1-87"},["minimumStage"]=2,["questID"]=8280,["sourceHash"]="7b607b2613b6ff6094796cae19551b7ac214cf96c54ef7b8800ab98bc7fa850e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15191",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Windcaller Proudhorn defended the supply routes that sustained the Circle’s strategic foothold at Cenarion Hold.",["title"]="Windcaller Proudhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8280:description:1-59","8280:description:62-141","8280:description:144-199","8280:description:204-308","8280:description:311-403","8280:description:406-480","8280:objective:1-87"},["minimumStage"]=2,["questID"]=8280,["sourceHash"]="7b607b2613b6ff6094796cae19551b7ac214cf96c54ef7b8800ab98bc7fa850e"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-15191",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dredge strikers ravaged a morrowgrain shipment, making desert worms a more immediate danger to his caravans than the silithid.",["title"]="Windcaller Proudhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8282:description:1-11","8282:description:14-28","8282:description:30-103","8282:description:106-174","8282:description:179-242","8282:description:245-331","8282:description:334-426","8282:description:431-510","8282:objective:1-108"},["minimumStage"]=2,["questID"]=8282,["sourceHash"]="d73e31e0dbfc1a2108cb2674a976b296db3a7f2971fc627abb846cc033fdbfa5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-15190",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Noggle lost his reagent satchel while fleeing Deathclasp, then ran into a nest of stonelash flayers and was left too weak to retrieve it.",["title"]="Noggle Ficklespragg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8282:description:1-11","8282:description:14-28","8282:description:30-103","8282:description:106-174","8282:description:179-242","8282:description:245-331","8282:description:334-426","8282:description:431-510","8282:objective:1-108"},["minimumStage"]=2,["questID"]=8282,["sourceHash"]="d73e31e0dbfc1a2108cb2674a976b296db3a7f2971fc627abb846cc033fdbfa5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15190",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Without those rare reagents he and Beetix could not prepare the potions Cenarion Hold needed; his escape began behind Bronzebeard’s southern camp.",["title"]="Noggle Ficklespragg"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"2:description:1-122","2:description:125-242","2:objective:1-79"},["minimumStage"]=2,["questID"]=2,["sourceHash"]="1156a12b5bd46c6de5fe1db5a30c2b104380d9427de11b14f8ff799d0638bd15"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-431",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senani Thunderheart received trophies of the Ashenvale Hunt at Splintertree Post, including the identifying claw of Sharptalon.",["title"]="Splintertree Post"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"5:description:1-102","5:description:105-166","5:description:171-215","5:description:220-314","5:objective:1-22"},["minimumStage"]=2,["questID"]=5,["sourceHash"]="ca90b596bee2ad106d5f3667c132f6933759382a07760345e0fd61b86fd75eb9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16134",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jitters recommended the Dusky Crab Cakes made by Chef Grual at Darkshire’s Scarlet Raven Tavern when seeking relief from weeks of poor food.",["title"]="Darkshire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"173:description:1-44","173:description:46-104","173:description:106-163","173:description:168-206","173:description:211-232","173:description:234-304","173:description:306-365","173:description:370-488","173:objective:1-61"},["minimumStage"]=2,["questID"]=173,["sourceHash"]="5a1ea0ae215df1fc540b570c76dd87a71927a334ff5c32794f6913f57b441f1f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16134",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Master Carevin’s followers saw themselves as defenders of Darkshire against Duskwood’s evil, dissatisfied with the Watch’s response to the danger.",["title"]="Darkshire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"13:description:1-120","13:description:123-176","13:description:179-252","13:description:257-322","13:description:325-434","13:objective:1-113"},["minimumStage"]=2,["questID"]=13,["sourceHash"]="1fef918ba4b0dad5a4de6c2995e82cb31bf8ba8619304923676793fa9bd43794"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-219",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Defias pillagers plundered the farmstead along with Moonbrook and the Gold Coast Quarry, prompting the People’s Militia to intervene.",["title"]="Alexston Farmstead"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"15:description:1-80","15:description:83-157","15:description:162-192","15:description:195-224","15:description:227-283","15:objective:1-60"},["minimumStage"]=2,["questID"]=15,["sourceHash"]="1df8e6166fda022ef00b9cc823dc4a47d3f72f71d24024dc63e1760ab411f3d7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16514",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="McBride’s scouts found kobold workers camping near Echo Ridge, evidence that Northshire’s infestation was larger than he had believed.",["title"]="Echo Ridge Mine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"20:description:1-100","20:description:103-204","20:description:209-242","20:description:245-321","20:description:326-447","20:description:450-503","20:objective:1-56"},["minimumStage"]=2,["questID"]=20,["sourceHash"]="6e4ebe91765f1e6daa10ec8d6ce3f8c46a9323efe40a1ac1fada8d508a82b43b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-69",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Blackrock marauders operating from Stonewatch Keep kept Lakeshire’s citizens confined to town while further orcs gathered in southeastern Redridge.",["title"]="Lakeshire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"169:description:1-7","169:description:9-116","169:description:122-156","169:description:159-277","169:description:280-328","169:description:331-443","169:objective:1-86"},["minimumStage"]=2,["questID"]=169,["sourceHash"]="4823df1fc8847c050c5966922c08a371c07c75cb84f3b04810ba688f1ee5541a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-69",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magistrate Solomon received proof for the bounty on Gath’Ilzogg, named as the leader of the raids from the conquered keep.",["title"]="Lakeshire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"28:description:1-84","28:description:87-160","28:description:163-274","28:description:279-414","28:description:417-479","28:description:484-497","28:objective:1-103","28:objective:106-139","28:objective:144-227"},["minimumStage"]=2,["questID"]=28,["sourceHash"]="b8e721782ff375985b001d8480610991e9434119f86e3888a9df62b87a48b8bb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-656",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Druids searched the lake’s depths for rapidly decaying Shrine Baubles during a trial of mental and physical dexterity.",["title"]="Lake Elune'ara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"28:description:1-84","28:description:87-160","28:description:163-274","28:description:279-414","28:description:417-479","28:description:484-497","28:objective:1-103","28:objective:106-139","28:objective:144-227"},["minimumStage"]=2,["questID"]=28,["sourceHash"]="b8e721782ff375985b001d8480610991e9434119f86e3888a9df62b87a48b8bb"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-656",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The baubles had to reach the Shrine of Remulos promptly, where the trusted Moonglade warden Tajarri oversaw the next step.",["title"]="Lake Elune'ara"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"176:description:1-14","176:description:19-85","176:description:88-134","176:description:139-199","176:description:202-305","176:objective:1-70"},["minimumStage"]=2,["questID"]=176,["sourceHash"]="e3ed6754a117194bb78692507a4f61b5673fecc960b46031e81208eb4e3e14b8"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-16524",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marshal Dughan received bounty hunters’ proof against Hogger in Goldshire on behalf of the Stormwind Army.",["title"]="Goldshire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"52:description:1-9","52:description:12-180","52:description:185-216","52:objective:1-100"},["minimumStage"]=2,["questID"]=52,["sourceHash"]="d484633ff9f33e95cc5b17b90073e6a0ed0e480bbc889e0ffdc281b6f0f44a18"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16524",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Guards described wild animals growing more aggressive farther from Goldshire, with wolves and bears repeatedly striking Eastvale’s loggers.",["title"]="Goldshire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"127:description:1-49","127:description:52-104","127:description:109-161","127:description:164-237","127:objective:1-58"},["minimumStage"]=2,["questID"]=127,["sourceHash"]="a938ee35a83a2dd6efd4935085e98bbef276ebba9eea907e836dfad16f9bfe7f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-68",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lake Everstill was famous for its spotted sunfish, which supported a steady local demand; murlocs also carried the desired catch.",["title"]="Lake Everstill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"161:description:1-68","161:description:71-161","161:description:164-249","161:description:252-303","161:description:308-411","161:description:414-469","161:objective:1-128"},["minimumStage"]=2,["questID"]=161,["sourceHash"]="85ca4f58f8ae6a38af068123cebfcd0fe7af5f55ae0131cb2b0fda80a4ab7227"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-145",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A traveler passing through Algaz Gate could follow the Wetlands road toward Dun Modr and the regiment guarding the Thandol Span.",["title"]="Algaz Gate"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"173:description:1-44","173:description:46-104","173:description:106-163","173:description:168-206","173:description:211-232","173:description:234-304","173:description:306-365","173:description:370-488","173:objective:1-61"},["minimumStage"]=2,["questID"]=173,["sourceHash"]="5a1ea0ae215df1fc540b570c76dd87a71927a334ff5c32794f6913f57b441f1f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-16135",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nightbane Shadow Weaver worgen occupied Brightwood Grove, where Carevin’s followers sent recruits to prove their ability to confront Duskwood’s threats.",["title"]="Brightwood Grove"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"201:description:1-125","201:description:128-233","201:description:236-321","201:description:326-389","201:objective:1-70"},["minimumStage"]=2,["questID"]=201,["sourceHash"]="7b1e49aeb719de2058f4413db347580dbbd840a31c2fbaf38693cab349794f04"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-37",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Venture Company mined beside Lake Nazferiti, while reports placed Hemet Nesingwary’s hunting camp farther upriver.",["title"]="Lake Nazferiti"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"207:description:1-93","207:description:96-135","207:description:138-189","207:description:194-260","207:description:263-306","207:description:309-374","207:description:379-507","207:objective:1-66"},["minimumStage"]=2,["questID"]=207,["sourceHash"]="3de1044629ae83c72d0d49840b7b365ec3397cbd828e9dd7eac55a2a3e36129e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-123",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A tablet in the Bal’lal ruins held troll legends sought by an investigator looking for the cause of Kurzen’s corruption.",["title"]="Bal'lal Ruins"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"207:description:1-93","207:description:96-135","207:description:138-189","207:description:194-260","207:description:263-306","207:description:309-374","207:description:379-507","207:objective:1-66"},["minimumStage"]=2,["questID"]=207,["sourceHash"]="3de1044629ae83c72d0d49840b7b365ec3397cbd828e9dd7eac55a2a3e36129e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-102",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Two of the four Stranglethorn tablets sought in the inquiry into Kurzen lay in the ruins of Zul’Kunda.",["title"]="Ruins of Zul'Kunda"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"209:description:1-116","209:description:118-245","209:description:250-333","209:description:338-425","209:description:427-504","209:objective:1-56"},["minimumStage"]=2,["questID"]=209,["sourceHash"]="c86b8ed805c841bd598c815c5b9bff6d146c9ba8ce836f813ae6469e7d0d1d50"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-2317",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Island buyers imported tiger fangs from Stranglethorn, a trade one supplier secretly supplemented with forgeries made from Skullsplitter tusks.",["title"]="South Seas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"210:description:1-37","210:description:40-148","210:description:151-170","210:description:173-217","210:description:222-285","210:description:288-306","210:objective:1-46"},["minimumStage"]=2,["questID"]=210,["sourceHash"]="26504aa9771b68723781987106ec0440a4e85d60720e14ea2b9307f1dd234da6"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-35",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Krazek sold a mechanical cooking pot to Corporal Kaleb, who cooked for his camp and later sent the broken device back to Booty Bay for repairs.",["title"]="Booty Bay"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"270:description:1-141","270:description:144-189","270:description:194-272","270:description:275-339","270:description:344-418","270:description:421-478","270:objective:1-71"},["minimumStage"]=2,["questID"]=270,["sourceHash"]="13fe7c5b0da40654d202886d1dbef1799e8ce62369d65025dd9d22b1730bb23d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-150",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Glorin Steelbrow was the harbor contact recommended for locating Lightforge iron lost aboard the sunken Kul Tiras Third Fleet.",["title"]="Menethil Harbor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"282:description:1-130","282:description:132-146","282:description:148-188","282:description:193-198","282:description:200-249","282:description:254-315","282:description:317-357","282:description:362-460","282:objective:1-30"},["minimumStage"]=2,["questID"]=282,["sourceHash"]="b93127ef898967febaa7d478e95ff650913a0aa65f229ebef95335af4621f74c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-131",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The tunnel on the route from Anvilmar toward Kharanos was infested with troggs, with Mountaineer Thalos stationed nearby to warn travelers.",["title"]="Kharanos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"287:description:1-53","287:description:55-156","287:description:161-181","287:description:183-269","287:description:274-396","287:description:398-443","287:description:445-481","287:objective:1-90"},["minimumStage"]=2,["questID"]=287,["sourceHash"]="b96d77c23b7e11258b6dc86abd9af989e5b1ee09badf74a3a667dfb0b9fb2d6f"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-211",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Iceflow Lake lay at the end of the frozen river followed west from Kharanos’s northern road; Brewnall Village stood on its western bank.",["title"]="Iceflow Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"288:description:1-90","288:description:93-109","288:description:112-181","288:description:184-210","288:description:215-319","288:description:322-367","288:description:372-405","288:description:408-492","288:objective:1-44"},["minimumStage"]=2,["questID"]=288,["sourceHash"]="896815493d230e088a634aab4679d887b048e1036ce2ee5761d1993970a8628b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-21",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fitzsimmons recalled serving aboard the Wave Mistress in the Kul Tiras Third Fleet when orc-controlled red dragons burned and sank its ships off the Wetlands.",["title"]="Kul Tiras"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8284:description:1-68","8284:description:71-237","8284:description:242-365","8284:description:368-497","8284:objective:1-98"},["minimumStage"]=2,["questID"]=8284,["sourceHash"]="1ddb9cf3e115fd011cdae8fec32807599aad3312570f0c229c327146ae450136"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15183",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Larksbane sought the missing fragments of a clay tablet to understand the Twilight’s Hammer’s presence in Silithus.",["title"]="Geologist Larksbane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8284:description:1-68","8284:description:71-237","8284:description:242-365","8284:description:368-497","8284:objective:1-98"},["minimumStage"]=2,["questID"]=8284,["sourceHash"]="1ddb9cf3e115fd011cdae8fec32807599aad3312570f0c229c327146ae450136"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15183",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The cult’s former northwestern camp had become a field of elementals, with scattered wood and canvas marking what had stood there.",["title"]="Geologist Larksbane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8286:description:1-70","8286:description:72-182","8286:description:187-280","8286:description:285-307","8286:description:309-334","8286:description:336-385","8286:description:387-452","8286:description:454-496","8286:objective:1-81"},["minimumStage"]=2,["questID"]=8286,["sourceHash"]="0981d01e8b7707abf57b974b00f497e9709fc01a4b9aad6071850b22f62a7e79"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-15180",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Baristolth remembered lying maimed and near death before a single breath and the passage of time healed him, binding him to endure as a Watcher.",["title"]="Baristolth of the Shifting Sands"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8286:description:1-70","8286:description:72-182","8286:description:187-280","8286:description:285-307","8286:description:309-334","8286:description:336-385","8286:description:387-452","8286:description:454-496","8286:objective:1-81"},["minimumStage"]=2,["questID"]=8286,["sourceHash"]="0981d01e8b7707abf57b974b00f497e9709fc01a4b9aad6071850b22f62a7e79"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15180",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Believing another war was approaching, he required news of whether the master had returned to the Bronze’s resting place at the Caverns of Time.",["title"]="Baristolth of the Shifting Sands"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8307:description:1-67","8307:description:70-189","8307:description:192-253","8307:description:258-343","8307:description:346-423","8307:description:426-507","8307:objective:1-101"},["minimumStage"]=2,["questID"]=8307,["sourceHash"]="41f56d2b26a0f9252a6a97fb969b04ba8bab0ddd0beacad24b2bedd74fedfe5e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-15174",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Calandrath missed Auberdine’s birds and trees after moving to the arid desert, where food and useful herbs were scarce.",["title"]="Calandrath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8307:description:1-67","8307:description:70-189","8307:description:192-253","8307:description:258-343","8307:description:346-423","8307:description:426-507","8307:objective:1-101"},["minimumStage"]=2,["questID"]=8307,["sourceHash"]="41f56d2b26a0f9252a6a97fb969b04ba8bab0ddd0beacad24b2bedd74fedfe5e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15174",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted to learn how the western Twilight camp made bitter sandworm meat edible, hoping their method could broaden the Hold’s limited fare.",["title"]="Calandrath"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8310:description:1-129","8310:description:131-145","8310:description:147-161","8310:description:163-176","8310:description:178-251","8310:description:253-310","8310:objective:1-167","8310:objective:169-220"},["minimumStage"]=2,["questID"]=8310,["sourceHash"]="961aee7bf73e872b0604f62951d24219a8f587754c8d04233e48b276d71cadfc"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15171",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Frankal Stonebridge proposed an elixir to help decipher silithid and Qiraji glyphs, requesting brains from the hives’ different creatures.",["title"]="Frankal Stonebridge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8310:description:1-129","8310:description:131-145","8310:description:147-161","8310:description:163-176","8310:description:178-251","8310:description:253-310","8310:objective:1-167","8310:objective:169-220"},["minimumStage"]=2,["questID"]=8310,["sourceHash"]="961aee7bf73e872b0604f62951d24219a8f587754c8d04233e48b276d71cadfc"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-15171",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He hoped the experiment would make Rutgar’s work useful, treating the language problem as unfinished research rather than a solved translation.",["title"]="Frankal Stonebridge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8311:description:1-61","8311:description:64-137","8311:description:140-222","8311:description:227-351","8311:description:354-430","8311:description:433-488","8311:objective:1-109","8311:objective:112-184","8311:objective:189-316"},["minimumStage"]=2,["questID"]=8311,["sourceHash"]="b8273c85a7fe3d766b1eca6c39ed1c88ba6e59d449ed1ecc826d241ab707210d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-15310",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jesper was too sick to go trick-or-treating and sought someone to gather Hallow’s End sweets in his place.",["title"]="Jesper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8311:description:1-61","8311:description:64-137","8311:description:140-222","8311:description:227-351","8311:description:354-430","8311:description:433-488","8311:objective:1-109","8311:objective:112-184","8311:objective:189-316"},["minimumStage"]=2,["questID"]=8311,["sourceHash"]="b8273c85a7fe3d766b1eca6c39ed1c88ba6e59d449ed1ecc826d241ab707210d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15310",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered candy with funny or frightening transformations in exchange, directing the helper to city innkeepers and Talvash in Ironforge.",["title"]="Jesper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8312:description:1-61","8312:description:64-137","8312:description:140-222","8312:description:227-351","8312:description:354-432","8312:description:435-490","8312:objective:1-111","8312:objective:114-186","8312:objective:191-321"},["minimumStage"]=2,["questID"]=8312,["sourceHash"]="b2c04e03367ac8ef4a8da1b90bdd6cc49adebeb776dbc52410ac8dd8ff3a10cb"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-15309",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Illness kept Spoops from Hallow’s End trick-or-treating, leaving the child dependent on a volunteer’s help.",["title"]="Spoops"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8312:description:1-61","8312:description:64-137","8312:description:140-222","8312:description:227-351","8312:description:354-432","8312:description:435-490","8312:objective:1-111","8312:objective:114-186","8312:objective:191-321"},["minimumStage"]=2,["questID"]=8312,["sourceHash"]="b2c04e03367ac8ef4a8da1b90bdd6cc49adebeb776dbc52410ac8dd8ff3a10cb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15309",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Spoops directed the collection toward city innkeepers and Kali Remik in Sen’jin, offering transformation candy in return.",["title"]="Spoops"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8318:description:1-97","8318:description:100-142","8318:description:147-216","8318:description:219-283","8318:description:286-358","8318:objective:1-67"},["minimumStage"]=2,["questID"]=8318,["sourceHash"]="245f1d9720151caaec048179bd11f2a961a579b096760edb757873b485df5e16"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15306",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bor Wildmane gathered the encoded papers used by the Twilight’s Hammer to communicate between its separate groups.",["title"]="Bor Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8318:description:1-97","8318:description:100-142","8318:description:147-216","8318:description:219-283","8318:description:286-358","8318:objective:1-67"},["minimumStage"]=2,["questID"]=8318,["sourceHash"]="245f1d9720151caaec048179bd11f2a961a579b096760edb757873b485df5e16"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15306",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Even unable to read their writing, he reasoned that removing the texts from circulation would obstruct the cult’s coordination.",["title"]="Bor Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8361:description:1-97","8361:description:100-220","8361:description:223-293","8361:description:298-381","8361:description:384-458","8361:description:461-496","8361:objective:1-134"},["minimumStage"]=2,["questID"]=8361,["sourceHash"]="39fe56fe5ed830cfd0f1a271f9095b26a835ee19b7857368178c7fe8564966eb"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-15306",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He had seen cultists receiving orders from summoned elemental nobles, while remaining unsure whether those beings were their gods or intermediaries.",["title"]="Bor Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8320:description:1-118","8320:description:121-245","8320:description:250-342","8320:description:345-405","8320:description:408-474","8320:objective:1-73"},["minimumStage"]=2,["questID"]=8320,["sourceHash"]="ccfeeca7c034c1c24049c796f9801e5924a4696239228c54b9ff3de2d2d42ad0"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-15270",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Huum Wildmane opposed the geolords directing the Twilight’s Hammer’s rituals in its western Silithus camps.",["title"]="Huum Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8320:description:1-118","8320:description:121-245","8320:description:250-342","8320:description:345-405","8320:description:408-474","8320:objective:1-73"},["minimumStage"]=2,["questID"]=8320,["sourceHash"]="ccfeeca7c034c1c24049c796f9801e5924a4696239228c54b9ff3de2d2d42ad0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15270",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He suspected a connection between the rituals and the desert’s pulsing red crystals, but considered the cult’s immediate threat more urgent than the unanswered mystery.",["title"]="Huum Wildmane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8332:description:1-84","8332:description:87-229","8332:description:236-303","8332:description:306-413","8332:description:418-458","8332:objective:1-86"},["minimumStage"]=2,["questID"]=8332,["sourceHash"]="b255bd139661f3f59e7147704451c400439985bf26fbd697cce4cbd068ef7cc1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15282",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Aurel Goldleaf could fashion a replica medallion of station using a large brilliant shard and crests taken from Abyssal Templars.",["title"]="Aurel Goldleaf"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8332:description:1-84","8332:description:87-229","8332:description:236-303","8332:description:306-413","8332:description:418-458","8332:objective:1-86"},["minimumStage"]=2,["questID"]=8332,["sourceHash"]="b255bd139661f3f59e7147704451c400439985bf26fbd697cce4cbd068ef7cc1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15282",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The disguise was intended to make a wind-stone petitioner appear to be a middle-ranking cult leader and draw out a duke of the Abyssal Council.",["title"]="Aurel Goldleaf"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8353:description:1-47","8353:description:50-125","8353:description:130-189","8353:description:191-211","8353:description:214-240","8353:description:242-279","8353:description:281-340","8353:description:345-389","8353:description:392-415","8353:objective:1-91"},["minimumStage"]=2,["questID"]=8353,["sourceHash"]="26e7e9b035095a1b9cf3a35eedd014f8ec692132054b2eb84479e5ba57a66c0d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5111",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="For Hallow’s End, Firebrew offered an Ironforge Mint to helpers collecting sweets for a sick child, but first demanded a chicken’s cluck.",["title"]="Innkeeper Firebrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8354:description:1-47","8354:description:50-125","8354:description:130-189","8354:description:191-211","8354:description:214-240","8354:description:242-279","8354:description:281-340","8354:description:345-389","8354:description:392-415","8354:objective:1-89"},["minimumStage"]=2,["questID"]=8354,["sourceHash"]="6031e27394be2d7486277357904192600356195b6f0401ba34c0cf6a6d78c6d6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-6741",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Norman’s Hallow’s End treat was an Undercity Mint, exchanged only after the trick-or-treater performed a chicken’s cluck.",["title"]="Innkeeper Norman"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8356:description:1-12","8356:description:14-45","8356:description:48-191","8356:description:196-207","8356:description:209-246","8356:description:248-257","8356:description:259-277","8356:description:280-334","8356:description:339-409","8356:description:412-443","8356:objective:1-86"},["minimumStage"]=2,["questID"]=8356,["sourceHash"]="5f6ecb1d6a4daeedf58c2204de0f787f72294e3b6f69bf6c9a2d29fb3ea64853"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6740",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Allison insisted that even someone collecting candy for a sick child perform a trick, offering Stormwind Nougat for a show of flexed muscles.",["title"]="Innkeeper Allison"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8357:description:1-103","8357:description:106-159","8357:description:164-239","8357:description:242-277","8357:description:280-331","8357:objective:1-91"},["minimumStage"]=2,["questID"]=8357,["sourceHash"]="8457f2b1a42ecf3f119c41cace4ed8fbe8568aa5d774c0b6c379dd5db53d9476"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6735",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Saelienne kept Hallow’s End’s exchange of tricks for treats, requiring a dance before giving marzipan to the sick child’s helper.",["title"]="Innkeeper Saelienne"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8358:description:1-19","8358:description:22-30","8358:description:35-167","8358:description:170-230","8358:description:232-264","8358:description:267-298","8358:description:301-345","8358:description:350-367","8358:objective:1-83"},["minimumStage"]=2,["questID"]=8358,["sourceHash"]="6fbfb1e93236036acedc7a5c3c46182896e117fe567cd0989332796140b85cf2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11814",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kali Remik offered a Darkspear Gumdrop for a sick child, with a train noise as the playful price of the treat.",["title"]="Kali Remik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8371:description:1-76","8371:description:81-179","8371:description:182-297","8371:description:302-386","8371:description:388-411","8371:description:414-506","8371:objective:1-160"},["minimumStage"]=2,["questID"]=8371,["sourceHash"]="d01cf1b9688ca21eddff8692abd32bada1ab11b8b88a88f73ea5eea476d05c9c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15351",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Alliance brigadier general sought veterans who understood that resources won or lost on one battlefront could decide another.",["title"]="Alliance Brigadier General"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8371:description:1-76","8371:description:81-179","8371:description:182-297","8371:description:302-386","8371:description:388-411","8371:description:414-506","8371:objective:1-160"},["minimumStage"]=2,["questID"]=8371,["sourceHash"]="d01cf1b9688ca21eddff8692abd32bada1ab11b8b88a88f73ea5eea476d05c9c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15351",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The general framed service across the active battlegrounds as a coordinated war rather than a collection of isolated victories.",["title"]="Alliance Brigadier General"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8460:description:1-66","8460:description:68-170","8460:description:172-225","8460:description:230-268","8460:description:270-360","8460:description:362-449","8460:objective:1-116","8460:objective:119-197"},["minimumStage"]=2,["questID"]=8460,["sourceHash"]="4b7bcbbf6d7b0a20819c7ba6d7bc8bee5bc39a234227e42dbd7f44cfe6888af1"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11554",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grazle blamed indiscriminate attacks on furbolgs for the Timbermaw’s distrust of outsiders, who often failed to distinguish them from corrupted tribes.",["title"]="Grazle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8460:description:1-66","8460:description:68-170","8460:description:172-225","8460:description:230-268","8460:description:270-360","8460:description:362-449","8460:objective:1-116","8460:objective:119-197"},["minimumStage"]=2,["questID"]=8460,["sourceHash"]="4b7bcbbf6d7b0a20819c7ba6d7bc8bee5bc39a234227e42dbd7f44cfe6888af1"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11554",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered a chance to earn that trust through action against the Deadwood west of his position in Felwood.",["title"]="Grazle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8461:description:1-63","8461:description:66-156","8461:description:161-247","8461:description:250-323","8461:description:326-375","8461:description:380-426","8461:description:429-503","8461:objective:1-99","8461:objective:102-171"},["minimumStage"]=2,["questID"]=8461,["sourceHash"]="13f669c85ed11cb54fb5d2cbf9bc6a1f32eae95a617f7117f1bb4a9b413ffe91"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-15395",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nafien regarded the nearby Deadwood’s hostility as a consequence of fel corruption rather than their original nature.",["title"]="Nafien"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8461:description:1-63","8461:description:66-156","8461:description:161-247","8461:description:250-323","8461:description:326-375","8461:description:380-426","8461:description:429-503","8461:objective:1-99","8461:objective:102-171"},["minimumStage"]=2,["questID"]=8461,["sourceHash"]="13f669c85ed11cb54fb5d2cbf9bc6a1f32eae95a617f7117f1bb4a9b413ffe91"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15395",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He mourned fighting his own brethren but believed they could not be helped, asking that helpers spare him the distressing details.",["title"]="Nafien"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8464:description:1-45","8464:description:48-153","8464:description:158-232","8464:description:235-354","8464:description:359-430","8464:description:433-493","8464:objective:1-94","8464:objective:97-173"},["minimumStage"]=2,["questID"]=8464,["sourceHash"]="edd2cfc5755eed93e2b4725dfde1a8a84f3d27365e64f3f0fd39721f89654ab0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11556",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Salfa guarded the Timbermaw’s uneasy peace, explaining that outsiders they trusted could receive safe passage.",["title"]="Salfa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8464:description:1-45","8464:description:48-153","8464:description:158-232","8464:description:235-354","8464:description:359-430","8464:description:433-493","8464:objective:1-94","8464:objective:97-173"},["minimumStage"]=2,["questID"]=8464,["sourceHash"]="edd2cfc5755eed93e2b4725dfde1a8a84f3d27365e64f3f0fd39721f89654ab0"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11556",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The increasingly hostile Winterfall in their eastern village threatened that isolation, driven by what Salfa described as fear and rage.",["title"]="Salfa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8481:description:1-145","8481:description:150-238","8481:description:241-303","8481:description:306-358","8481:description:361-462","8481:description:464-499","8481:objective:1-111","8481:objective:114-204"},["minimumStage"]=2,["questID"]=8481,["sourceHash"]="a35930f6756c031fe4c0dc1f1ca7d1e0e21570ea24dc57b5d10c50895ff563ea"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11555",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gorn sought the demon he believed dominated the Winterfall, preparing a torch to draw it out at the high chief’s cave.",["title"]="Gorn One Eye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8481:description:1-145","8481:description:150-238","8481:description:241-303","8481:description:306-358","8481:description:361-462","8481:description:464-499","8481:objective:1-111","8481:objective:114-204"},["minimumStage"]=2,["questID"]=8481,["sourceHash"]="a35930f6756c031fe4c0dc1f1ca7d1e0e21570ea24dc57b5d10c50895ff563ea"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11555",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He regarded the demon’s fallen essence as the beginning of a long healing process for the tribe and Timbermaw Hold, rather than an instant cure.",["title"]="Gorn One Eye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8492:description:1-67","8492:description:69-195","8492:description:200-246","8492:description:248-288","8492:description:290-334","8492:objective:1-77"},["minimumStage"]=2,["questID"]=8492,["sourceHash"]="0770a9ce02674606a5c02c9b70012decb58475a019950fd072b17957693447b7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15383",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sergeant Stonebrow collected the Alliance’s copper contributions for the Ahn’Qiraj war effort.",["title"]="Sergeant Stonebrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8494:description:1-24","8494:description:26-77","8494:description:79-229","8494:description:231-250","8494:description:252-288","8494:description:290-320","8494:objective:1-72"},["minimumStage"]=2,["questID"]=8494,["sourceHash"]="813f006d927ce8d78c4b3a27acb75c65475ab8a16a62a71d1cb0d051ae26a0ef"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15431",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Corporal Carnes oversaw the Alliance’s demand for iron bars as its forces prepared for war in Ahn’Qiraj.",["title"]="Corporal Carnes"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8499:description:1-72","8499:description:74-227","8499:description:229-435","8499:description:437-472","8499:objective:1-74"},["minimumStage"]=2,["questID"]=8499,["sourceHash"]="0556f763cd9e9c1bccbd467b32f26c920a67a8845162edb4b19dfeac56114907"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15432",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dame Twinbraid directed the Alliance’s thorium collection for the Ahn’Qiraj campaign.",["title"]="Dame Twinbraid"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8499:description:1-72","8499:description:74-227","8499:description:229-435","8499:description:437-472","8499:objective:1-74"},["minimumStage"]=2,["questID"]=8499,["sourceHash"]="0556f763cd9e9c1bccbd467b32f26c920a67a8845162edb4b19dfeac56114907"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15432",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Foremost among the planned uses was a battalion of steam tanks to be airlifted into Silithus once construction was complete.",["title"]="Dame Twinbraid"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"344:description:1-21","344:description:24-44","344:description:47-127","344:description:130-201","344:description:204-216","344:description:221-236","344:description:239-267","344:description:270-323","344:description:326-433","344:description:438-461","344:description:464-502","344:objective:1-50"},["minimumStage"]=2,["questID"]=344,["sourceHash"]="6c8b08f2e132f156a8a10159a0c11e151dd10e7fa71da342ca74485054e69a4d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-24",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brother Paxton maintained the abbey’s library and copied works for its shelves.",["title"]="Northshire Abbey"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"344:description:1-21","344:description:24-44","344:description:47-127","344:description:130-201","344:description:204-216","344:description:221-236","344:description:239-267","344:description:270-323","344:description:326-433","344:description:438-461","344:description:464-502","344:objective:1-50"},["minimumStage"]=2,["questID"]=344,["sourceHash"]="6c8b08f2e132f156a8a10159a0c11e151dd10e7fa71da342ca74485054e69a4d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-24",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The library held Margulf Blaggon’s mining book, The Stresses of Iron, borrowed months earlier for Paxton to reproduce.",["title"]="Northshire Abbey"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"347:description:1-68","347:description:71-182","347:description:185-238","347:description:243-332","347:description:335-454","347:description:459-510","347:objective:1-87"},["minimumStage"]=2,["questID"]=347,["sourceHash"]="c2ffb56e8ca463d461b1216c3e32cf1b02ff78de4fdc22099fb9ca949b29e88b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-98",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The caverns yielded Bart Rethban’s namesake ore, whose dark, flat coloring supplied scribes with dye despite making weaker metal than iron.",["title"]="Rethban Caverns"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"347:description:1-68","347:description:71-182","347:description:185-238","347:description:243-332","347:description:335-454","347:description:459-510","347:objective:1-87"},["minimumStage"]=2,["questID"]=347,["sourceHash"]="c2ffb56e8ca463d461b1216c3e32cf1b02ff78de4fdc22099fb9ca949b29e88b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-98",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Redridge gnolls occupied the workings and their drudgers gathered the ore, while preparations against orc attacks kept the usual suppliers away.",["title"]="Rethban Caverns"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"357:description:1-74","357:description:77-216","357:description:221-272","357:description:275-359","357:description:364-430","357:description:433-486","357:objective:1-63"},["minimumStage"]=2,["questID"]=357,["sourceHash"]="2e7415c68edbdd92878cd5776d7c3577d0298ca7d5bd3928b2bb1792979ffe23"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-162",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A free-willed lich occupied an island in northern Brightwater Lake, attracting Forsaken interest in his identity and necromantic knowledge.",["title"]="Brightwater Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"357:description:1-74","357:description:77-216","357:description:221-272","357:description:275-359","357:description:364-430","357:description:433-486","357:objective:1-63"},["minimumStage"]=2,["questID"]=357,["sourceHash"]="2e7415c68edbdd92878cd5776d7c3577d0298ca7d5bd3928b2bb1792979ffe23"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-162",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The island’s guardian minions attacked approaching undead because their master believed other undead remained slaves of the Scourge.",["title"]="Brightwater Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"366:description:1-159","366:description:164-287","366:description:290-319","366:description:324-340","366:description:343-449","366:description:452-506","366:objective:1-70"},["minimumStage"]=2,["questID"]=366,["sourceHash"]="21b9adc98b126a046d74e2343a80c121899bbd03f17e0288a234563d8a5aaa2e"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-16558",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bethor, Gunther and Thule Ravenclaw had once studied together in Dalaran’s Kirin Tor before plague and undeath divided their later paths.",["title"]="Dalaran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"372:description:1-97","372:description:100-212","372:description:217-277","372:description:280-346","372:objective:1-102"},["minimumStage"]=2,["questID"]=372,["sourceHash"]="bb18eecfadd4df05cd262dcba4dcabc87129f287613a68e687ca99949ac1fdf7"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-173",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A ruined tower beyond Faol’s Rest served as Captain Melrache’s northern Tirisfal base for Scarlet raids.",["title"]="Faol's Rest"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"429:description:1-236","429:objective:1-76"},["minimumStage"]=2,["questID"]=429,["sourceHash"]="0dcf30803e23dbba8882744a91db7ee711d1461b16e450126471d33c6d208323"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://warcraftforever.games/quests/429",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Worgs ranged along the approach to Malden’s Orchard, where their discolored hearts were sought for an apothecary’s healing potion.",["title"]="Malden's Orchard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"464:description:1-124","464:description:127-217","464:description:220-310","464:description:315-388","464:description:393-430","464:description:433-479","464:objective:1-51"},["minimumStage"]=2,["questID"]=464,["sourceHash"]="e527556b5812e30bd542f142940276b7a1dea804db0869960114a4d969dff5b8"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-1037",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Surviving Dragonmaw fled Grim Batol after losing control of their red dragons at the Second War’s end, taking refuge in the mountains east of Whelgar’s excavation.",["title"]="Grim Batol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"486:description:1-54","486:description:56-110","486:description:115-176","486:description:178-276","486:description:279-316","486:description:321-449","486:description:452-506","486:objective:1-68"},["minimumStage"]=2,["questID"]=486,["sourceHash"]="1c681faecd7a5f629a2c2cc7d910cc2a98efcd62f4cefb1c5b36f2287ba011c2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-261",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ursal the Mauler held the southwestern settlement and was blamed for interfering with the awakening of the Druids of the Talon.",["title"]="Gnarlpine Hold"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"487:description:1-40","487:description:43-171","487:description:176-259","487:description:262-330","487:description:335-384","487:description:387-436","487:description:439-496","487:objective:1-88"},["minimumStage"]=2,["questID"]=487,["sourceHash"]="ce5e405d766bed0dad67a7911f415816dc6abb3aa0916f73a0432053a48352b5"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-186",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The road linking Dolanaar with Darnassus carried daily news, commerce and travelers.",["title"]="Dolanaar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"487:description:1-40","487:description:43-171","487:description:176-259","487:description:262-330","487:description:335-384","487:description:387-436","487:description:439-496","487:objective:1-88"},["minimumStage"]=2,["questID"]=487,["sourceHash"]="ce5e405d766bed0dad67a7911f415816dc6abb3aa0916f73a0432053a48352b5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-186",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Corrupted Gnarlpine ambushers attacked along that route, threatening the settlement’s connection to the city.",["title"]="Dolanaar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"527:description:1-43","527:description:48-88","527:description:91-178","527:description:183-269","527:description:272-353","527:description:358-369","527:description:372-419","527:description:422-501","527:objective:1-120"},["minimumStage"]=2,["questID"]=527,["sourceHash"]="c9478aaa113dfaf3191895a3d55a9164fa44eec36aa15dc290542a02d5801490"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-2372",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The northern farms supplied Hillsbrad’s food and infrastructure, with Farmer Ray and Farmer Getz named among the landowners.",["title"]="Hillsbrad Fields"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"527:description:1-43","527:description:48-88","527:description:91-178","527:description:183-269","527:description:272-353","527:description:358-369","527:description:372-419","527:description:422-501","527:objective:1-120"},["minimumStage"]=2,["questID"]=527,["sourceHash"]="c9478aaa113dfaf3191895a3d55a9164fa44eec36aa15dc290542a02d5801490"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2372",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Forsaken orders targeted the farms and their owners to weaken the town while the apothecaries worked on a new plague.",["title"]="Hillsbrad Fields"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"504:description:1-95","504:description:100-167","504:description:170-307","504:objective:1-76"},["minimumStage"]=2,["questID"]=504,["sourceHash"]="497506e88fad365cbd2fc0599df66956079844d431995760a1466d0a2bd204a6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-281",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Crushridge warmongers occupied the ruins, where Alliance commanders sought to deter the ogres from pressing into their territory.",["title"]="Ruins of Alterac"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"505:description:1-108","505:description:111-310","505:description:315-427","505:description:430-480","505:objective:1-104"},["minimumStage"]=2,["questID"]=505,["sourceHash"]="3f537b7573bf9ec5510700d6705c92fb560ca204ab110e90ff0b468372a43e14"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-2369",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Southshore’s new magistrate took office after his predecessor’s assassination; the investigation strongly suspected the Syndicate but had not found the killers.",["title"]="Southshore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"512:description:1-72","512:description:75-143","512:description:148-216","512:description:219-277","512:description:282-345","512:description:348-460","512:description:465-492","512:objective:1-63"},["minimumStage"]=2,["questID"]=512,["sourceHash"]="0420bb96479272bd6f93fe13e2253628188a85b831f9783b9e1b1d37c7b47903"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2369",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The magistrate feared the Syndicate’s former Alterac nobles intended the town’s ruin and sought their leaders among the agents in Strahnbrad.",["title"]="Southshore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"505:description:1-108","505:description:111-310","505:description:315-427","505:description:430-480","505:objective:1-104"},["minimumStage"]=2,["questID"]=505,["sourceHash"]="3f537b7573bf9ec5510700d6705c92fb560ca204ab110e90ff0b468372a43e14"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-1678",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A Syndicate camp at Sofera’s Naze formed part of the former Alterac nobles’ foothold near Horde-held Tarren Mill.",["title"]="Sofera's Naze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"507:description:1-79","507:description:81-156","507:description:158-244","507:objective:1-80"},["minimumStage"]=2,["questID"]=507,["sourceHash"]="60b7d1f63fff2a0de19e111f3748f38e4e0e878243d7ffab9cd56021e18c0107"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1338",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lord Aliden Perenolde’s manor stood on the lakeshore, the destination of a Forsaken mission to recover a pendant desired by the warchief.",["title"]="Lordamere Lake"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"509:description:1-39","509:description:41-119","509:description:122-164","509:description:169-319","509:description:324-433","509:description:435-503","509:objective:1-61"},["minimumStage"]=2,["questID"]=509,["sourceHash"]="853940e629ed6d4972616dadbb93f63947720d7ceedfb00d2a5086a1f9e4b6e9"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-2374",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nethander Stead lay south of Tarren Mill and east of both Southshore and the river.",["title"]="Nethander Stead"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"509:description:1-39","509:description:41-119","509:description:122-164","509:description:169-319","509:description:324-433","509:description:435-503","509:objective:1-61"},["minimumStage"]=2,["questID"]=509,["sourceHash"]="853940e629ed6d4972616dadbb93f63947720d7ceedfb00d2a5086a1f9e4b6e9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-2374",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mudsnout blossoms grew in its fields, where an apothecary sought them as ingredients for another experimental elixir.",["title"]="Nethander Stead"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"512:description:1-72","512:description:75-143","512:description:148-216","512:description:219-277","512:description:282-345","512:description:348-460","512:description:465-492","512:objective:1-63"},["minimumStage"]=2,["questID"]=512,["sourceHash"]="0420bb96479272bd6f93fe13e2253628188a85b831f9783b9e1b1d37c7b47903"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-280",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alliance investigators suspected the ruined town served as a Syndicate headquarters, with former Alterac nobles concealing themselves among its ordinary agents.",["title"]="Strahnbrad"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"517:description:1-46","517:description:49-137","517:description:140-196","517:description:201-223","517:description:226-295","517:description:298-338","517:description:341-402","517:objective:1-67"},["minimumStage"]=2,["questID"]=517,["sourceHash"]="bd325734c6b4cc6e0bee5d989538931266362255391bb95a8a2ff0029b09de43"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-2371",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dun Garok’s dwarven barracks kept kegs of Shindigger Stout, which a Forsaken apothecary wanted stolen for his next experiment.",["title"]="Dun Garok"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"530:description:1-53","530:description:56-115","530:description:118-191","530:description:196-303","530:objective:1-19","530:objective:24-75"},["minimumStage"]=2,["questID"]=530,["sourceHash"]="f6d8915a92bf7c6908933d54f3820497430ed2c09981b66e6e59fadc686ffa21"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-17065",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The kingdom of Gilneas lay beyond the Greymane Wall at the southern end of Silverpine, where Valdred was last reported trying to flee.",["title"]="Gilneas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"536:description:1-110","536:description:112-145","536:description:150-178","536:description:180-216","536:description:226-330","536:description:332-400","536:objective:1-98"},["minimumStage"]=2,["questID"]=536,["sourceHash"]="02b2af555f5ea0ab988e95d8533a08fd46e9c35f7c9f0c6b368153ee3c80b6de"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2378",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Murloc pockets along the Western Strand fell within Southshore’s security concerns, though its reluctant guard sought outside help to confront them.",["title"]="Western Strand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8503:description:1-79","8503:description:81-86","8503:description:88-97","8503:description:99-166","8503:description:168-207","8503:description:209-326","8503:objective:1-79"},["minimumStage"]=2,["questID"]=8503,["sourceHash"]="dfbeed778185df3c25dabd151489dac7679c3c76cd2eb0aa7cf40f4c527f4d59"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15434",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Private Draxlegauge collected stranglekelp for the Alliance’s war preparations, asking contributors to set aside their own uses for the herb.",["title"]="Private Draxlegauge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8505:description:1-59","8505:description:61-283","8505:description:288-381","8505:description:383-416","8505:objective:1-76"},["minimumStage"]=2,["questID"]=8505,["sourceHash"]="34a6f1ff761c848707ced388a29b560845836a702be01a43cdf4a405e65ac520"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15437",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Master Nightsong served as an authority on purple lotus, preserving the flowers gathered for the Alliance’s war effort.",["title"]="Master Nightsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8505:description:1-59","8505:description:61-283","8505:description:288-381","8505:description:383-416","8505:objective:1-76"},["minimumStage"]=2,["questID"]=8505,["sourceHash"]="34a6f1ff761c848707ced388a29b560845836a702be01a43cdf4a405e65ac520"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15437",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nightsong’s task was to ensure a sufficient supply for its many applications, without claiming to know which use the commanders intended.",["title"]="Master Nightsong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8507:description:1-14","8507:description:17-114","8507:description:121-191","8507:description:196-267","8507:description:270-323","8507:description:328-395","8507:description:398-490","8507:objective:1-61","8507:objective:64-224","8507:objective:229-330"},["minimumStage"]=2,["questID"]=8507,["sourceHash"]="2865675db963be318f70793bc02057d7fa11573cb3a4e35291ce6fe5d688cba1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15540",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Windcaller Kaldon assigned preliminary field duty before entrusting recruits with more involved war tasks.",["title"]="Windcaller Kaldon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8507:description:1-14","8507:description:17-114","8507:description:121-191","8507:description:196-267","8507:description:270-323","8507:description:328-395","8507:description:398-490","8507:objective:1-61","8507:objective:64-224","8507:objective:229-330"},["minimumStage"]=2,["questID"]=8507,["sourceHash"]="2865675db963be318f70793bc02057d7fa11573cb3a4e35291ce6fe5d688cba1"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-15540",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mutual animosity forced the Ironforge Brigade and Orgrimmar Legion to remain apart, so his Alliance recruits were warned away from the Horde’s force.",["title"]="Windcaller Kaldon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8509:description:1-41","8509:description:43-135","8509:description:137-185","8509:description:187-279","8509:description:281-307","8509:objective:1-84"},["minimumStage"]=2,["questID"]=8509,["sourceHash"]="60015513cf80c986d3bdc1a67d97324bc9cbe4de1e803edad0bfbb70e76a105d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15445",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sergeant Major Germaine collected Arthas’ Tears for the Ahn’Qiraj campaign under orders that did not explain the herb’s intended use.",["title"]="Sergeant Major Germaine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8511:description:1-58","8511:description:60-181","8511:description:183-285","8511:description:287-308","8511:description:313-418","8511:description:420-474","8511:objective:1-79"},["minimumStage"]=2,["questID"]=8511,["sourceHash"]="56026eb91b537c60b89819ca5e2fa92d753d641a3fc23d8525f2f004d3768957"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-15446",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bonnie’s Stoneflayer family had a long tradition of skinning, prompting the Alliance to enlist them in its light-leather collection.",["title"]="Bonnie Stoneflayer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8511:description:1-58","8511:description:60-181","8511:description:183-285","8511:description:287-308","8511:description:313-418","8511:description:420-474","8511:objective:1-79"},["minimumStage"]=2,["questID"]=8511,["sourceHash"]="56026eb91b537c60b89819ca5e2fa92d753d641a3fc23d8525f2f004d3768957"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15446",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bonnie supervised proper tanning while asking volunteers to supply the hides she could not leave her post to gather.",["title"]="Bonnie Stoneflayer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8515:description:1-34","8515:description:36-169","8515:description:171-242","8515:description:244-269","8515:description:271-295","8515:description:300-390","8515:description:392-407","8515:objective:1-78"},["minimumStage"]=2,["questID"]=8515,["sourceHash"]="6fc23bf0f8c5d88a8a536c6e72f1f21d538c9d92675e36ed6880a353ad4c7454"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15450",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marta Finespindle tracked the thick leather arriving for the Alliance’s Ahn’Qiraj preparations.",["title"]="Marta Finespindle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8515:description:1-34","8515:description:36-169","8515:description:171-242","8515:description:244-269","8515:description:271-295","8515:description:300-390","8515:description:392-407","8515:objective:1-78"},["minimumStage"]=2,["questID"]=8515,["sourceHash"]="6fc23bf0f8c5d88a8a536c6e72f1f21d538c9d92675e36ed6880a353ad4c7454"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15450",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She welcomed the large undertaking with enthusiasm, anticipating many uses once enough leather had been gathered.",["title"]="Marta Finespindle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8517:description:1-52","8517:description:54-227","8517:description:232-385","8517:description:387-475","8517:description:477-496","8517:objective:1-80"},["minimumStage"]=2,["questID"]=8517,["sourceHash"]="cd067f6ad6c063f4747de5c697cf5f662f5598f2b5789549f7ed1725caf4c1f7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15451",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sentinel Silversky led the collection of linen bandages before the Alliance committed its troops to Ahn’Qiraj.",["title"]="Sentinel Silversky"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8517:description:1-52","8517:description:54-227","8517:description:232-385","8517:description:387-475","8517:description:477-496","8517:objective:1-80"},["minimumStage"]=2,["questID"]=8517,["sourceHash"]="cd067f6ad6c063f4747de5c697cf5f662f5598f2b5789549f7ed1725caf4c1f7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15451",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Expecting a long and bloody conflict, Silversky regarded preparation and even the simplest bandages as work of real consequence.",["title"]="Sentinel Silversky"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8520:description:1-130","8520:description:132-164","8520:description:166-257","8520:description:262-298","8520:objective:1-77"},["minimumStage"]=2,["questID"]=8520,["sourceHash"]="19274a7aeb73dc14ded59c339fefbd560aef540c22b289e19415c2fb4a3c8e10"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15452",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nurse Stonefield was responsible for amassing silk bandages so the Alliance’s soldiers would have what they needed in the coming war.",["title"]="Nurse Stonefield"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8524:description:1-18","8524:description:20-152","8524:description:154-175","8524:description:177-201","8524:description:203-359","8524:description:361-393","8524:objective:1-85"},["minimumStage"]=2,["questID"]=8524,["sourceHash"]="6ed1a851e4c733afa22308ceae1690a79a9b0c17b05c445357462641bc875ab0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15455",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Slicky Gastronome gathered cooked rainbow fin albacore as food for the soldiers preparing to fight.",["title"]="Slicky Gastronome"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8524:description:1-18","8524:description:20-152","8524:description:154-175","8524:description:177-201","8524:description:203-359","8524:description:361-393","8524:objective:1-85"},["minimumStage"]=2,["questID"]=8524,["sourceHash"]="6ed1a851e4c733afa22308ceae1690a79a9b0c17b05c445357462641bc875ab0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15455",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He asked helpers to fish and cook the catch before delivery, treating sustenance as part of military preparation rather than an afterthought.",["title"]="Slicky Gastronome"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8526:description:1-23","8526:description:25-112","8526:description:114-227","8526:description:229-240","8526:description:242-271","8526:description:276-350","8526:description:352-412","8526:objective:1-76"},["minimumStage"]=2,["questID"]=8526,["sourceHash"]="235a5696b0ff8f86d2be1c289a6e7a5c1f0e87787ad35df5af0fe5cd0ddf04e5"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-15456",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sarah Sadwhistle’s father volunteered her to help with the Ahn’Qiraj supplies, hoping the work would be a learning experience.",["title"]="Sarah Sadwhistle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8526:description:1-23","8526:description:25-112","8526:description:114-227","8526:description:229-240","8526:description:242-271","8526:description:276-350","8526:description:352-412","8526:objective:1-76"},["minimumStage"]=2,["questID"]=8526,["sourceHash"]="235a5696b0ff8f86d2be1c289a6e7a5c1f0e87787ad35df5af0fe5cd0ddf04e5"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-15456",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She disliked the assignment to gather roast raptor because she did not even enjoy eating meat.",["title"]="Sarah Sadwhistle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8528:description:1-109","8528:description:111-253","8528:description:258-398","8528:description:400-458","8528:description:460-502","8528:objective:1-85"},["minimumStage"]=2,["questID"]=8528,["sourceHash"]="632f32cf95bf06d5299c52152e0103f90bcca58115f2b4bf6982ccb93d12bbd0"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15457",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Huntress Swiftriver stockpiled spotted yellowtail to sustain the troops once the Ahn’Qiraj fighting began.",["title"]="Huntress Swiftriver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8528:description:1-109","8528:description:111-253","8528:description:258-398","8528:description:400-458","8528:description:460-502","8528:objective:1-85"},["minimumStage"]=2,["questID"]=8528,["sourceHash"]="632f32cf95bf06d5299c52152e0103f90bcca58115f2b4bf6982ccb93d12bbd0"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15457",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She valued the fish for keeping well, fitting many dishes and lacking the strong smell of some saltwater catches.",["title"]="Huntress Swiftriver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8532:description:1-45","8532:description:47-127","8532:description:129-156","8532:description:158-311","8532:description:313-354","8532:objective:1-77"},["minimumStage"]=2,["questID"]=8532,["sourceHash"]="c6dfb34b377a19f226b11bba8ac72c1e3d31e9be70b026dc6e682411be532123"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15459",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Miner Cromwell collected finished copper bars for the Horde’s preparations.",["title"]="Miner Cromwell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8532:description:1-45","8532:description:47-127","8532:description:129-156","8532:description:158-311","8532:description:313-354","8532:objective:1-77"},["minimumStage"]=2,["questID"]=8532,["sourceHash"]="c6dfb34b377a19f226b11bba8ac72c1e3d31e9be70b026dc6e682411be532123"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15459",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He insisted on bars rather than raw ore because the organizers lacked enough time and workers to handle the smelting themselves.",["title"]="Miner Cromwell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8542:description:1-93","8542:description:95-179","8542:description:181-325","8542:description:327-365","8542:description:370-442","8542:description:444-491","8542:objective:1-70"},["minimumStage"]=2,["questID"]=8542,["sourceHash"]="028cdf80bb2f4682f04f88b5595039552ff7a8b0cf176e7ed5c1dd442516186b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15460",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grunt Maug was put in charge of gathering tin bars for the Horde’s Ahn’Qiraj effort.",["title"]="Grunt Maug"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8542:description:1-93","8542:description:95-179","8542:description:181-325","8542:description:327-365","8542:description:370-442","8542:description:444-491","8542:objective:1-70"},["minimumStage"]=2,["questID"]=8542,["sourceHash"]="028cdf80bb2f4682f04f88b5595039552ff7a8b0cf176e7ed5c1dd442516186b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15460",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Though he preferred sharpening weapons and shaping armor, he took pride in being entrusted with the warchief’s preparations.",["title"]="Grunt Maug"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8545:description:1-72","8545:description:74-122","8545:description:124-244","8545:description:246-272","8545:description:277-371","8545:description:373-411","8545:objective:1-87"},["minimumStage"]=2,["questID"]=8545,["sourceHash"]="5f5a1c4355cf760cb695874b1f50d0c0ad668f1422ac9ee267cea5c9f6ad78ff"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15469",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senior Sergeant T’kelah organized the Horde’s mithril collection, asking contributors to mine the ore and bring it already smelted into bars.",["title"]="Senior Sergeant T'kelah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8548:description:1-132","8548:description:137-169","8548:description:172-313","8548:objective:1-130","8548:objective:133-228"},["minimumStage"]=2,["questID"]=8548,["sourceHash"]="92433a8e66df16af30c897c3886c996806f0ee5a4d7783b0a2fbcf42472733ec"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15176",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vargus supplied battle gear reserved for the Cenarion Circle’s closest allies in exchange for badges earned through its assignments.",["title"]="Vargus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8548:description:1-132","8548:description:137-169","8548:description:172-313","8548:objective:1-130","8548:objective:133-228"},["minimumStage"]=2,["questID"]=8548,["sourceHash"]="92433a8e66df16af30c897c3886c996806f0ee5a4d7783b0a2fbcf42472733ec"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15176",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Combat, logistics and tactical service all contributed to those badges, joining different kinds of work in the Hold’s recognition of loyalty.",["title"]="Vargus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8549:description:1-60","8549:description:62-137","8549:description:139-194","8549:description:199-328","8549:description:330-374","8549:description:376-446","8549:description:448-470","8549:objective:1-84"},["minimumStage"]=2,["questID"]=8549,["sourceHash"]="3ea8d377982c2841471b6afedbca1dc8646a5f92e6e2e3d3891442e49871eae7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15477",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Herbalist Proudfeather saw the Ahn’Qiraj war as a trial that would define a generation and volunteered to gather peacebloom for the Horde’s potions.",["title"]="Herbalist Proudfeather"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8549:description:1-60","8549:description:62-137","8549:description:139-194","8549:description:199-328","8549:description:330-374","8549:description:376-446","8549:description:448-470","8549:objective:1-84"},["minimumStage"]=2,["questID"]=8549,["sourceHash"]="3ea8d377982c2841471b6afedbca1dc8646a5f92e6e2e3d3891442e49871eae7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15477",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Preparation itself, not merely the coming battle, was how Proudfeather believed their people would discover their mettle.",["title"]="Herbalist Proudfeather"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8551:description:1-68","8551:description:71-124","8551:description:129-136","8551:description:141-174","8551:description:177-252","8551:description:255-311","8551:description:314-349","8551:description:352-361","8551:description:366-411","8551:description:414-444","8551:description:447-500","8551:objective:1-54"},["minimumStage"]=2,["questID"]=8551,["sourceHash"]="17a3419d2ac961686ac706df42d030915f46c370345b82638c685b0eefc02259"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2500",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Captain Hecklebury Smotts had sailed a successful route to Ratchet before sea giants smashed his ship, killed his crew and sent him adrift toward Booty Bay.",["title"]="Captain Hecklebury Smotts"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8551:description:1-68","8551:description:71-124","8551:description:129-136","8551:description:141-174","8551:description:177-252","8551:description:255-311","8551:description:314-349","8551:description:352-361","8551:description:366-411","8551:description:414-444","8551:description:447-500","8551:objective:1-54"},["minimumStage"]=2,["questID"]=8551,["sourceHash"]="17a3419d2ac961686ac706df42d030915f46c370345b82638c685b0eefc02259"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2500",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought the captain’s chest taken by Gorlash, whose reported plan to use it as a snuffbox added insult to the loss of his command.",["title"]="Captain Hecklebury Smotts"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8554:description:1-27","8554:description:32-105","8554:description:108-155","8554:description:158-211","8554:description:214-294","8554:description:299-376","8554:description:379-442","8554:description:445-500","8554:objective:1-94","8554:objective:99-174"},["minimumStage"]=2,["questID"]=8554,["sourceHash"]="8a015b516d379c6e054d29bf7fe02de4d150a0f50f54f3ac72ed95012e5b3aeb"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2594",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sprogger’s kitchen was plundered when sea giants destroyed the ship, but Negolash sought his wine and food rather than the crew.",["title"]="Sprogger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8554:description:1-27","8554:description:32-105","8554:description:108-155","8554:description:158-211","8554:description:214-294","8554:description:299-376","8554:description:379-442","8554:description:445-500","8554:objective:1-94","8554:objective:99-174"},["minimumStage"]=2,["questID"]=8554,["sourceHash"]="8a015b516d379c6e054d29bf7fe02de4d150a0f50f54f3ac72ed95012e5b3aeb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2594",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His specialty was barbecued buzzard wings from a Badlands recipe; he proposed baiting the old coastal lifeboat with those wings and wine to draw Negolash out.",["title"]="Sprogger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8556:description:1-88","8556:description:91-227","8556:description:232-316","8556:description:321-392","8556:objective:1-123","8556:objective:126-209"},["minimumStage"]=2,["questID"]=8556,["sourceHash"]="4d4ad86e3a56e3ff678464e7f8024f4dd5aa8398ef083f108c84e4b8a0a483c7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15498",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Windcaller Yessendra proposed remaking Qiraji lieutenants’ rings by exchanging their corrupted gems for purer material from idols.",["title"]="Windcaller Yessendra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8556:description:1-88","8556:description:91-227","8556:description:232-316","8556:description:321-392","8556:objective:1-123","8556:objective:126-209"},["minimumStage"]=2,["questID"]=8556,["sourceHash"]="4d4ad86e3a56e3ff678464e7f8024f4dd5aa8398ef083f108c84e4b8a0a483c7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15498",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The plan rested on reports of the rings’ formidable powers and the superior quality of the idols’ gems, offering a way to turn the enemy’s craft toward allies.",["title"]="Windcaller Yessendra"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8557:description:1-65","8557:description:68-160","8557:description:165-229","8557:description:232-306","8557:description:311-346","8557:objective:1-110","8557:objective:113-196"},["minimumStage"]=2,["questID"]=8557,["sourceHash"]="19bd43f0a1f4e243462e68521aa3f5c93d93a6961829e52bc551101e493edd37"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15500",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keyl Swiftclaw offered to resize a Qiraji drape and fashion a clasp from idols and scarabs, making captured materials useful in the fight against their former owners.",["title"]="Keyl Swiftclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8558:description:1-184","8558:description:189-306","8558:description:309-420","8558:objective:1-113","8558:objective:116-199"},["minimumStage"]=2,["questID"]=8558,["sourceHash"]="a786a23b7d83a33f5e49a3c955cb5446dfde68c1a7fd0b2dfce86fbda0ee6db4"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15499",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Warden Haro offered to forge powerful weapons from the rare materials in Qiraji artifacts for those who proved allegiance to the Circle.",["title"]="Warden Haro"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8558:description:1-184","8558:description:189-306","8558:description:309-420","8558:objective:1-113","8558:objective:116-199"},["minimumStage"]=2,["questID"]=8558,["sourceHash"]="a786a23b7d83a33f5e49a3c955cb5446dfde68c1a7fd0b2dfce86fbda0ee6db4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15499",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ancient bones, deep-earth gems and pure metals stirred Haro’s urge to practice the craft with their broken and smelted remains.",["title"]="Warden Haro"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8559:description:1-35","8559:description:38-124","8559:description:129-246","8559:description:251-307","8559:objective:1-118","8559:objective:121-188"},["minimumStage"]=2,["questID"]=8559,["sourceHash"]="a2e5c0719193f594553201e4557d3492b3f3994e612779abb519891f77b419ee"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15503",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kandrostrasz offered to turn bindings of command and other Qiraji components into protective boots.",["title"]="Kandrostrasz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8559:description:1-35","8559:description:38-124","8559:description:129-246","8559:description:251-307","8559:objective:1-118","8559:objective:121-188"},["minimumStage"]=2,["questID"]=8559,["sourceHash"]="a2e5c0719193f594553201e4557d3492b3f3994e612779abb519891f77b419ee"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15503",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The promise reflected respect for ancient Qiraji magic, whose strongest artifacts could give even a dragon pause.",["title"]="Kandrostrasz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8561:description:1-20","8561:description:22-84","8561:description:87-174","8561:description:179-247","8561:description:250-278","8561:description:280-361","8561:description:366-403","8561:description:406-452","8561:objective:1-111","8561:objective:114-204"},["minimumStage"]=2,["questID"]=8561,["sourceHash"]="4c022429401e94978097ded34cd3c000d54641403e92615075a0eb0e944ff915"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-15502",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Andorgos’s brother Arygos was captive deeper within the Twin Emperors’ domain, beyond the reach of a direct rescue.",["title"]="Andorgos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8561:description:1-20","8561:description:22-84","8561:description:87-174","8561:description:179-247","8561:description:250-278","8561:description:280-361","8561:description:366-403","8561:description:406-452","8561:objective:1-111","8561:objective:114-204"},["minimumStage"]=2,["questID"]=8561,["sourceHash"]="4c022429401e94978097ded34cd3c000d54641403e92615075a0eb0e944ff915"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-15502",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The emperors’ mocking whispers strained Andorgos’s sanity, while visions of their crowns suggested a means of revenge through transmutation.",["title"]="Andorgos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8562:description:1-76","8562:description:79-189","8562:description:194-286","8562:description:289-366","8562:description:371-411","8562:description:414-463","8562:description:465-502","8562:objective:1-120","8562:objective:123-212"},["minimumStage"]=2,["questID"]=8562,["sourceHash"]="431cf45ab79312e8a884b836d8b9f16a63d6185e581aa9330bcfe4f9116875b9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15504",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vethsera feared the Old God stirring beneath Ahn’Qiraj would lash out at all living beings when the stars favored it.",["title"]="Vethsera"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8562:description:1-76","8562:description:79-189","8562:description:194-286","8562:description:289-366","8562:description:371-411","8562:description:414-463","8562:description:465-502","8562:objective:1-120","8562:objective:123-212"},["minimumStage"]=2,["questID"]=8562,["sourceHash"]="431cf45ab79312e8a884b836d8b9f16a63d6185e581aa9330bcfe4f9116875b9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15504",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vethsera offered extraordinary armor in exchange for a piece of the god’s husk, without claiming to know whether the danger would awaken in days or years.",["title"]="Vethsera"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8577:description:1-62","8577:description:64-154","8577:description:156-217","8577:description:222-440","8577:description:442-508","8577:objective:1-141"},["minimumStage"]=2,["questID"]=8577,["sourceHash"]="0df835ef5f1dff059807d7a20ff0a3529bf5c7dd3694aaa66b3e076acd1adeaf"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11811",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Narain Soothfancy accused his former best friend Stewvul of stealing the scrying goggles he needed for translation.",["title"]="Narain Soothfancy"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8577:description:1-62","8577:description:64-154","8577:description:156-217","8577:description:222-440","8577:description:442-508","8577:objective:1-141"},["minimumStage"]=2,["questID"]=8577,["sourceHash"]="0df835ef5f1dff059807d7a20ff0a3529bf5c7dd3694aaa66b3e076acd1adeaf"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11811",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His crystal-ball search gave uncertain and wildly separated possibilities for the thief’s whereabouts, leaving a personal grievance entangled with the scholarly task.",["title"]="Narain Soothfancy"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8580:description:1-8","8580:description:10-21","8580:description:23-116","8580:description:118-163","8580:description:165-229","8580:description:231-240","8580:description:242-256","8580:description:261-290","8580:description:292-371","8580:objective:1-80"},["minimumStage"]=2,["questID"]=8580,["sourceHash"]="891e6d8c079b751e5e5024d9ca77272a3b908932b70d915f0ccbeb50fc9659e2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15508",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Batrider Pele’keiki organized the Horde’s firebloom collection for Ahn’Qiraj.",["title"]="Batrider Pele'keiki"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8580:description:1-8","8580:description:10-21","8580:description:23-116","8580:description:118-163","8580:description:165-229","8580:description:231-240","8580:description:242-256","8580:description:261-290","8580:description:292-371","8580:objective:1-80"},["minimumStage"]=2,["questID"]=8580,["sourceHash"]="891e6d8c079b751e5e5024d9ca77272a3b908932b70d915f0ccbeb50fc9659e2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15508",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pele’keiki freely admitted not knowing its purpose; explosives and steam-tank fuel were guesses offered amid the appeal for help.",["title"]="Batrider Pele'keiki"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8582:description:1-126","8582:description:128-211","8582:description:213-280","8582:description:282-352","8582:description:357-381","8582:description:383-453","8582:description:455-506","8582:objective:1-80"},["minimumStage"]=2,["questID"]=8582,["sourceHash"]="24375710fbbf52e718215b2e5465c5ad5a4397f0e5a0b328d1200e9c3a562c06"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15512",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Apothecary Jezel gathered purple lotus for the Horde’s mass production of potions, elixirs and oils.",["title"]="Apothecary Jezel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8582:description:1-126","8582:description:128-211","8582:description:213-280","8582:description:282-352","8582:description:357-381","8582:description:383-453","8582:description:455-506","8582:objective:1-80"},["minimumStage"]=2,["questID"]=8582,["sourceHash"]="24375710fbbf52e718215b2e5465c5ad5a4397f0e5a0b328d1200e9c3a562c06"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15512",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alongside the known preparations, Jezel intended to experiment with further uses for the flower.",["title"]="Apothecary Jezel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8588:description:1-111","8588:description:113-189","8588:description:191-288","8588:description:293-341","8588:description:343-362","8588:description:364-409","8588:description:411-434","8588:objective:1-79"},["minimumStage"]=2,["questID"]=8588,["sourceHash"]="51a780960348dff65a2bdeabe7e0017cbb23fede9ea2052611d431b27e96ee71"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15515",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Skinner Jamani assembled heavy leather for the Horde’s wartime materials.",["title"]="Skinner Jamani"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8588:description:1-111","8588:description:113-189","8588:description:191-288","8588:description:293-341","8588:description:343-362","8588:description:364-409","8588:description:411-434","8588:objective:1-79"},["minimumStage"]=2,["questID"]=8588,["sourceHash"]="51a780960348dff65a2bdeabe7e0017cbb23fede9ea2052611d431b27e96ee71"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15515",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The planned uses ranged from reinforcement and armor to ordinary tarps, making hides part of both fighting equipment and camp supplies.",["title"]="Skinner Jamani"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8551:description:1-68","8551:description:71-124","8551:description:129-136","8551:description:141-174","8551:description:177-252","8551:description:255-311","8551:description:314-349","8551:description:352-361","8551:description:366-411","8551:description:414-444","8551:description:447-500","8551:objective:1-54"},["minimumStage"]=2,["questID"]=8551,["sourceHash"]="17a3419d2ac961686ac706df42d030915f46c370345b82638c685b0eefc02259"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1492",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Smotts reported that Gorlash wanted the stolen captain’s chest for a snuffbox, treating a seaman’s prized possession as a giant’s small convenience.",["title"]="Gorlash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8551:description:1-68","8551:description:71-124","8551:description:129-136","8551:description:141-174","8551:description:177-252","8551:description:255-311","8551:description:314-349","8551:description:352-361","8551:description:366-411","8551:description:414-444","8551:description:447-500","8551:objective:1-54"},["minimumStage"]=2,["questID"]=8551,["sourceHash"]="17a3419d2ac961686ac706df42d030915f46c370345b82638c685b0eefc02259"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1492",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Smotts had heard that Gorlash wandered the coast east of Booty Bay after the ship’s destruction.",["title"]="Gorlash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8554:description:1-27","8554:description:32-105","8554:description:108-155","8554:description:158-211","8554:description:214-294","8554:description:299-376","8554:description:379-442","8554:description:445-500","8554:objective:1-94","8554:objective:99-174"},["minimumStage"]=2,["questID"]=8554,["sourceHash"]="8a015b516d379c6e054d29bf7fe02de4d150a0f50f54f3ac72ed95012e5b3aeb"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1494",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sprogger recalled Negolash seeking wine and barbecued buzzard wings from the ship’s kitchen rather than attacking its crew for food.",["title"]="Negolash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8554:description:1-27","8554:description:32-105","8554:description:108-155","8554:description:158-211","8554:description:214-294","8554:description:299-376","8554:description:379-442","8554:description:445-500","8554:objective:1-94","8554:objective:99-174"},["minimumStage"]=2,["questID"]=8554,["sourceHash"]="8a015b516d379c6e054d29bf7fe02de4d150a0f50f54f3ac72ed95012e5b3aeb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1494",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The cook proposed using a heap of those wings and wine in the old lifeboat to lure the hungry giant back to shore.",["title"]="Negolash"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8590:description:1-56","8590:description:58-145","8590:description:147-186","8590:description:191-361","8590:description:363-447","8590:description:449-457","8590:objective:1-79"},["minimumStage"]=2,["questID"]=8590,["sourceHash"]="bcc74210e2383b0049168ff72e059baa26a55fb1775304eb3687111a617fe562"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15522",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sergeant Umala organized the Horde’s thick-leather contributions for Ahn’Qiraj, offering the nation’s gratitude for work on its war materials.",["title"]="Sergeant Umala"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8599:description:1-35","8599:description:37-177","8599:description:182-233","8599:description:238-253","8599:description:255-261","8599:description:263-280","8599:description:282-362","8599:description:364-390","8599:description:392-408","8599:description:410-424","8599:description:429-475","8599:description:477-511","8599:objective:1-60"},["minimumStage"]=2,["questID"]=8599,["sourceHash"]="2bf00fc5eac282a92adb002c766207e8bba2f61db7f91078946c646439aea9f2"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-15526",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Meridith rescued Narain Soothfancy from the wreckage of a crashed flying machine, a rare visitor whose memory stayed with her.",["title"]="Meridith the Mermaiden"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8599:description:1-35","8599:description:37-177","8599:description:182-233","8599:description:238-253","8599:description:255-261","8599:description:263-280","8599:description:282-362","8599:description:364-390","8599:description:392-408","8599:description:410-424","8599:description:429-475","8599:description:477-511","8599:objective:1-60"},["minimumStage"]=2,["questID"]=8599,["sourceHash"]="2bf00fc5eac282a92adb002c766207e8bba2f61db7f91078946c646439aea9f2"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15526",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Believing herself in love with the gnome, she wanted a messenger to carry him the feelings she could not leave unspoken.",["title"]="Meridith the Mermaiden"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8600:description:1-84","8600:description:86-200","8600:description:202-282","8600:description:288-326","8600:description:328-467","8600:description:469-507","8600:objective:1-81"},["minimumStage"]=2,["questID"]=8600,["sourceHash"]="e48b151307c25cf93866c0510cda14bfd29a168edc64bb0965e19cec72a681fb"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15525",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Doctor Serratus demanded rugged hides for the Horde’s Ahn’Qiraj preparations.",["title"]="Doctor Serratus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8600:description:1-84","8600:description:86-200","8600:description:202-282","8600:description:288-326","8600:description:328-467","8600:description:469-507","8600:objective:1-81"},["minimumStage"]=2,["questID"]=8600,["sourceHash"]="e48b151307c25cf93866c0510cda14bfd29a168edc64bb0965e19cec72a681fb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15525",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Serratus spoke of a knife’s fit in the hand and the pressure behind its cut, emphasizing control even while insisting upon a sharp edge.",["title"]="Doctor Serratus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8604:description:1-14","8604:description:16-126","8604:description:128-244","8604:description:246-273","8604:description:275-340","8604:description:345-392","8604:description:394-468","8604:objective:1-82"},["minimumStage"]=2,["questID"]=8604,["sourceHash"]="575752976c82199bdddcd8c7421f3e5ece61db29e4c1feecbdd681539b3b1563"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15528",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Healer Longrunner coordinated wool bandages for the Horde’s wartime first-aid kits.",["title"]="Healer Longrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8604:description:1-14","8604:description:16-126","8604:description:128-244","8604:description:246-273","8604:description:275-340","8604:description:345-392","8604:description:394-468","8604:objective:1-82"},["minimumStage"]=2,["questID"]=8604,["sourceHash"]="575752976c82199bdddcd8c7421f3e5ece61db29e4c1feecbdd681539b3b1563"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15528",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Firsthand experience had taught Longrunner that soldiers in the field could not depend on a healer always being present.",["title"]="Healer Longrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8607:description:1-111","8607:description:113-117","8607:description:119-225","8607:description:227-276","8607:description:278-368","8607:objective:1-81"},["minimumStage"]=2,["questID"]=8607,["sourceHash"]="fa895f62456b708a9e7902d9feb57e602f03c993b3b6450348c4c25cfde9153c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15529",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lady Callow oversaw the Horde’s mageweave-bandage collection, insisting that helpers obtain the supplies by whatever means they could.",["title"]="Lady Callow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8607:description:1-111","8607:description:113-117","8607:description:119-225","8607:description:227-276","8607:description:278-368","8607:objective:1-81"},["minimumStage"]=2,["questID"]=8607,["sourceHash"]="fa895f62456b708a9e7902d9feb57e602f03c993b3b6450348c4c25cfde9153c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15529",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She preferred fresh bandages but did not make freshness a condition of her promised personal reward.",["title"]="Lady Callow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8611:description:1-49","8611:description:51-88","8611:description:90-190","8611:description:195-272","8611:description:274-450","8611:description:452-468","8611:objective:1-85"},["minimumStage"]=2,["questID"]=8611,["sourceHash"]="06452cebb8f89a34f70c980ff82b1b860f81f73106be5f6a51fdcbca230a7115"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15533",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bloodguard Rawtar gathered and salted lean wolf steaks for the Horde’s Ahn’Qiraj provisions.",["title"]="Bloodguard Rawtar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8611:description:1-49","8611:description:51-88","8611:description:90-190","8611:description:195-272","8611:description:274-450","8611:description:452-468","8611:objective:1-85"},["minimumStage"]=2,["questID"]=8611,["sourceHash"]="06452cebb8f89a34f70c980ff82b1b860f81f73106be5f6a51fdcbca230a7115"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15533",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Preserving the deliveries kept Rawtar at the collection post, so helpers were asked to hunt the wolves and cook their meat before bringing it in.",["title"]="Bloodguard Rawtar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8613:description:1-50","8613:description:52-110","8613:description:112-208","8613:description:210-283","8613:description:285-318","8613:description:320-352","8613:description:354-381","8613:objective:1-86"},["minimumStage"]=2,["questID"]=8613,["sourceHash"]="2a41b4097dd78c12ed39523816b947135b2294a3bdf376d991b9707b37d862c6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15534",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fisherman Lin’do accepted responsibility for the Horde’s large spotted-yellowtail requirement and sought help to fulfill the request.",["title"]="Fisherman Lin'do"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8615:description:1-55","8615:description:57-181","8615:description:183-280","8615:description:285-317","8615:description:319-424","8615:description:426-459","8615:objective:1-79"},["minimumStage"]=2,["questID"]=8615,["sourceHash"]="67be33460a4bf42510b3c7a47f17a4350d0b89e2a5bb392dd7052dccf571effd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15535",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Chief Sharpclaw gathered baked salmon for the Ahn’Qiraj campaign, valuing a dish that sustained soldiers and kept well.",["title"]="Chief Sharpclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8615:description:1-55","8615:description:57-181","8615:description:183-280","8615:description:285-317","8615:description:319-424","8615:description:426-459","8615:objective:1-79"},["minimumStage"]=2,["questID"]=8615,["sourceHash"]="67be33460a4bf42510b3c7a47f17a4350d0b89e2a5bb392dd7052dccf571effd"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15535",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sharpclaw considered food as important as weapons, reasoning that a starving fighter could not lift an axe when the moment came.",["title"]="Chief Sharpclaw"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8730:description:1-20","8730:description:22-154","8730:description:156-197","8730:description:202-229","8730:description:240-276","8730:description:281-303","8730:description:305-340","8730:description:342-356","8730:objective:1-48","8730:objective:50-126","8730:objective:128-166"},["minimumStage"]=2,["questID"]=8730,["sourceHash"]="14ac9efce77eccb04bbb61af8a86c32b1eafc79fe55c82d4da3126b777839a6f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="atlas-figure-vaelastrasz",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vaelastrasz had been entrusted with the red scepter shard a thousand years earlier, only to lose it to Nefarius in his darkest hour.",["title"]="Vaelastrasz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8730:description:1-20","8730:description:22-154","8730:description:156-197","8730:description:202-229","8730:description:240-276","8730:description:281-303","8730:description:305-340","8730:description:342-356","8730:objective:1-48","8730:objective:50-126","8730:objective:128-166"},["minimumStage"]=2,["questID"]=8730,["sourceHash"]="14ac9efce77eccb04bbb61af8a86c32b1eafc79fe55c82d4da3126b777839a6f"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="atlas-figure-vaelastrasz",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Weakened and coughing, he warned that Nefarius intended to destroy the shard and urged the champion to act quickly.",["title"]="Vaelastrasz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8733:description:1-38","8733:description:40-124","8733:description:126-166","8733:description:168-238","8733:description:243-262","8733:description:264-322","8733:description:324-425","8733:description:430-447","8733:description:452-502","8733:objective:1-106"},["minimumStage"]=2,["questID"]=8733,["sourceHash"]="7ae18c91dbb95aa381abe7d95af6ff67e8bf9d00f5c2b2dcda718be72ea8b848"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15362",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Malfurion sought Eranikus’s redemption from the Old Gods’ taint and the recovery of the green scepter shard.",["title"]="Malfurion Stormrage"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8733:description:1-38","8733:description:40-124","8733:description:126-166","8733:description:168-238","8733:description:243-262","8733:description:264-322","8733:description:324-425","8733:description:430-447","8733:description:452-502","8733:objective:1-106"},["minimumStage"]=2,["questID"]=8733,["sourceHash"]="7ae18c91dbb95aa381abe7d95af6ff67e8bf9d00f5c2b2dcda718be72ea8b848"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15362",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His plan passed through an agent outside Darnassus who could inform Tyrande without alerting Staghelm.",["title"]="Malfurion Stormrage"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8742:description:1-75","8742:description:77-121","8742:description:126-150","8742:description:152-179","8742:description:181-211","8742:description:216-286","8742:description:288-394"},["minimumStage"]=2,["questID"]=8742,["sourceHash"]="58acdd3fff682b219d2026f76ad92ac6490a30b67683b3d14bcb6e314bd89fd6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15192",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anachronos offered the Scepter of the Shifting Sands to the prepared champion who would bring Kalimdor’s strength against C’Thun.",["title"]="Anachronos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8742:description:1-75","8742:description:77-121","8742:description:126-150","8742:description:152-179","8742:description:181-211","8742:description:216-286","8742:description:288-394"},["minimumStage"]=2,["questID"]=8742,["sourceHash"]="58acdd3fff682b219d2026f76ad92ac6490a30b67683b3d14bcb6e314bd89fd6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15192",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He understood the moment as the fulfillment of a thousand-year fate, placing his hope in the champion’s faith rather than the Old God’s prophecy.",["title"]="Anachronos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8789:description:1-45","8789:description:50-136","8789:description:138-208","8789:description:210-261","8789:description:266-339","8789:description:344-499","8789:objective:1-151"},["minimumStage"]=2,["questID"]=8789,["sourceHash"]="68f7d6f4948ea0d2b06af02227cf78dfdac849e6d5c44537c156149ab86b9f5f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-15380",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Arygos described a millennium spent watching the Qiraji, learning from their plots, internal treachery and treatment of servants whose usefulness had ended.",["title"]="Arygos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8789:description:1-45","8789:description:50-136","8789:description:138-208","8789:description:210-261","8789:description:266-339","8789:description:344-499","8789:objective:1-151"},["minimumStage"]=2,["questID"]=8789,["sourceHash"]="68f7d6f4948ea0d2b06af02227cf78dfdac849e6d5c44537c156149ab86b9f5f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15380",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought ceremonial armaments to combine with material drawn from the Old God’s volatility, turning knowledge of the enemy’s weaknesses into weapons against it.",["title"]="Arygos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8792:description:1-51","8792:description:53-166","8792:description:168-342","8792:description:347-406","8792:description:408-427","8792:description:429-474","8792:objective:1-60"},["minimumStage"]=2,["questID"]=8792,["sourceHash"]="d391a925c4cf8736e80510b444b3c7fad644e5106f52fd500929db53ff9f5e62"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15702",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senior Sergeant Taiga recruited volunteers for the Horde’s Ahn’Qiraj collections and directed them to Warlord Gorchuk.",["title"]="Senior Sergeant Taiga"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8793:description:1-51","8793:description:53-166","8793:description:168-342","8793:description:347-406","8793:description:408-427","8793:description:429-474","8793:objective:1-60"},["minimumStage"]=2,["questID"]=8793,["sourceHash"]="b0108c4cd29ff9e758334f1ebd196f099c01a1d25289b445d76423a8527a8f92"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15703",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senior Sergeant Grimsford urged travelers to help the Horde’s official war collectors, referring their offers to Warlord Gorchuk.",["title"]="Senior Sergeant Grimsford"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8794:description:1-51","8794:description:53-166","8794:description:168-342","8794:description:347-406","8794:description:408-427","8794:description:429-474","8794:objective:1-60"},["minimumStage"]=2,["questID"]=8794,["sourceHash"]="66e4ec57e7df5c7af37c5f5121a212156712e654fea555ade322e97c0e48063b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15704",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Senior Sergeant Kai’jin appealed for help with the Horde’s Ahn’Qiraj preparations and sent willing contributors to Warlord Gorchuk.",["title"]="Senior Sergeant Kai'jin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8795:description:1-51","8795:description:53-169","8795:description:171-345","8795:description:350-416","8795:description:418-437","8795:description:439-484","8795:objective:1-63"},["minimumStage"]=2,["questID"]=8795,["sourceHash"]="e4c11b7be1d4f5b1100bb3797558e5ca6fa9505c06c02c446f8baa7f93a8806e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15707",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Master Sergeant Fizzlebolt recruited support for the Alliance’s war collectors under Field Marshal Snowfall.",["title"]="Master Sergeant Fizzlebolt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8796:description:1-51","8796:description:53-169","8796:description:171-345","8796:description:350-416","8796:description:418-437","8796:description:439-484","8796:objective:1-63"},["minimumStage"]=2,["questID"]=8796,["sourceHash"]="6467e101a352fad61d650d158a1a1f2afab8ce7047e714075d46367323119675"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15708",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Master Sergeant Maclure directed volunteers toward Field Marshal Snowfall as the Alliance gathered materials for Ahn’Qiraj.",["title"]="Master Sergeant Maclure"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8797:description:1-51","8797:description:53-169","8797:description:171-345","8797:description:350-416","8797:description:418-437","8797:description:439-484","8797:objective:1-63"},["minimumStage"]=2,["questID"]=8797,["sourceHash"]="e971c9fe6fcfb92313558c6ced2c67f3917668205c190087351f041d51b8e9d6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15709",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Master Sergeant Moonshadow urged travelers to assist the Alliance’s collection effort and report to Snowfall.",["title"]="Master Sergeant Moonshadow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8827:description:1-136","8827:description:138-212","8827:description:217-255","8827:description:257-325","8827:objective:1-30","8827:objective:32-98"},["minimumStage"]=2,["questID"]=8827,["sourceHash"]="7100e60b3cb738276ccb3988b7133f6519d6722377695fa79a34dc34fc10a021"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15732",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Wonderform operator looked after the PX-238 Winter Wondervolt instead of joining the Winter Veil gift gathering.",["title"]="Wonderform Operator"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8827:description:1-136","8827:description:138-212","8827:description:217-255","8827:description:257-325","8827:objective:1-30","8827:objective:32-98"},["minimumStage"]=2,["questID"]=8827,["sourceHash"]="7100e60b3cb738276ccb3988b7133f6519d6722377695fa79a34dc34fc10a021"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15732",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The operator directed visitors toward the presents under Ironforge’s tree, crediting Greatfather Winter and Smokywood Pastures for the gifts.",["title"]="Wonderform Operator"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8846:description:1-55","8846:description:58-125","8846:description:127-172","8846:description:177-302","8846:description:305-480"},["minimumStage"]=2,["questID"]=8846,["sourceHash"]="9646c4677b2e4fc4ed356aa82b513735ae49c2e360d4b5fc4c83826d69a40099"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15701",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Field Marshal Snowfall issued additional war supplies in exchange for commendation signets.",["title"]="Field Marshal Snowfall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8846:description:1-55","8846:description:58-125","8846:description:127-172","8846:description:177-302","8846:description:305-480"},["minimumStage"]=2,["questID"]=8846,["sourceHash"]="9646c4677b2e4fc4ed356aa82b513735ae49c2e360d4b5fc4c83826d69a40099"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15701",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="That exchange offered potentially useful equipment rather than further recognition, letting contributors trade honors for practical help before battle.",["title"]="Field Marshal Snowfall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8857:description:1-148","8857:description:150-217","8857:description:219-265","8857:description:267-305","8857:objective:1-70"},["minimumStage"]=2,["questID"]=8857,["sourceHash"]="c2be9e3fb929a48420a07a09ff1c67d7bcc1e30fe972bb2fb6451587c61adaca"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15798",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Researcher Nestor prepared fresh husk samples from the fallen Colossus of Ashi for Oglethorpe in Booty Bay.",["title"]="Colossus Researcher Nestor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8857:description:1-148","8857:description:150-217","8857:description:219-265","8857:description:267-305","8857:objective:1-70"},["minimumStage"]=2,["questID"]=8857,["sourceHash"]="c2be9e3fb929a48420a07a09ff1c67d7bcc1e30fe972bb2fb6451587c61adaca"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15798",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted a swift courier carrying an already collected sample, since decay would spoil its value for the intended research.",["title"]="Colossus Researcher Nestor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8858:description:1-88","8858:description:90-159","8858:description:161-230","8858:description:235-293","8858:description:295-310","8858:description:315-362","8858:objective:1-71"},["minimumStage"]=2,["questID"]=8858,["sourceHash"]="27fdaa2bd99349d5b8664c50c325c6c2109bd376c182b677ef9690bbcebdcb35"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15799",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Researcher Eazel collected samples from the fallen Colossus of Regal for Oilfist at Thorium Point.",["title"]="Colossus Researcher Eazel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8858:description:1-88","8858:description:90-159","8858:description:161-230","8858:description:235-293","8858:description:295-310","8858:description:315-362","8858:objective:1-71"},["minimumStage"]=2,["questID"]=8858,["sourceHash"]="27fdaa2bd99349d5b8664c50c325c6c2109bd376c182b677ef9690bbcebdcb35"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-15799",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The creature’s size promised work into the early hours, while Oilfist’s generous payment made quick delivery of a fresh husk sample worthwhile.",["title"]="Colossus Researcher Eazel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8859:description:1-71","8859:description:73-98","8859:description:100-155","8859:description:157-247","8859:description:252-275","8859:description:277-292","8859:description:294-349","8859:objective:1-107"},["minimumStage"]=2,["questID"]=8859,["sourceHash"]="cd0ea7b66e176077be7beb493e8543aff3c682646b5b7c2ac9f985320a770d81"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15797",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Researcher Sophia arranged a fresh colossus husk sample for Lord Maxwell Tyrosus at Light’s Hope.",["title"]="Colossus Researcher Sophia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8859:description:1-71","8859:description:73-98","8859:description:100-155","8859:description:157-247","8859:description:252-275","8859:description:277-292","8859:description:294-349","8859:objective:1-107"},["minimumStage"]=2,["questID"]=8859,["sourceHash"]="cd0ea7b66e176077be7beb493e8543aff3c682646b5b7c2ac9f985320a770d81"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15797",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her servants had nearly died retrieving it, and Tyrosus hoped the creature’s secrets might help the war against the Scourge.",["title"]="Colossus Researcher Sophia"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8867:description:1-103","8867:description:108-190","8867:description:192-207","8867:description:212-282","8867:description:285-332","8867:objective:1-110"},["minimumStage"]=2,["questID"]=8867,["sourceHash"]="8150823e0a49cc1f9be9755c267f1ba47c6e9ab02f369d3e73d15d19cfd325c6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15895",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Lunar Festival Harbinger introduced the druids of Moonglade’s annual commemoration of an ancient triumph.",["title"]="Lunar Festival Harbinger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8867:description:1-103","8867:description:108-190","8867:description:192-207","8867:description:212-282","8867:description:285-332","8867:objective:1-110"},["minimumStage"]=2,["questID"]=8867,["sourceHash"]="8150823e0a49cc1f9be9755c267f1ba47c6e9ab02f369d3e73d15d19cfd325c6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15895",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Honoring the elders joined feasting and fireworks, with colorful rockets available for the nearby launchers.",["title"]="Lunar Festival Harbinger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8870:description:1-31","8870:description:34-137","8870:description:140-254","8870:description:257-296","8870:objective:1-69","8870:objective:72-142"},["minimumStage"]=2,["questID"]=8870,["sourceHash"]="cbe0bee9d3d14dfdd11008eb7c28d417a905358aa4c4bac83f700e1eca17e7f5"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15892",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Lunar Festival emissary carried the Cenarion Circle’s invitation to all peoples of Azeroth.",["title"]="Lunar Festival Emissary"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8870:description:1-31","8870:description:34-137","8870:description:140-254","8870:description:257-296","8870:objective:1-69","8870:objective:72-142"},["minimumStage"]=2,["questID"]=8870,["sourceHash"]="cbe0bee9d3d14dfdd11008eb7c28d417a905358aa4c4bac83f700e1eca17e7f5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-15892",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Visitors were directed to a harbinger standing within a blessed circle of moonlight to learn more about the celebration.",["title"]="Lunar Festival Emissary"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8873:description:1-31","8873:description:34-137","8873:description:140-254","8873:description:257-296","8873:objective:1-74","8873:objective:77-147"},["minimumStage"]=2,["questID"]=8873,["sourceHash"]="43cef3813c624933ddc55e0c67d0b12d15fefd351bc22afc737c45d2d5c164aa"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-15891",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Lunar Festival herald welcomed Azeroth’s peoples to the Circle’s yearly celebration and directed them to the city’s moonlit gathering place.",["title"]="Lunar Festival Herald"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8897:description:1-93","8897:description:95-173","8897:description:175-252","8897:description:257-287","8897:description:289-323","8897:description:325-343","8897:description:348-390","8897:description:392-461","8897:objective:1-96"},["minimumStage"]=2,["questID"]=8897,["sourceHash"]="81f42bde3cd3ad3eb69c6d44efafec79ac6309fe89d39e7dc4f871386d865161"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16005",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lieutenant Jocryn Heldric kept watch at the gate on a minor officer’s pay, with the possibility of being sent to the front.",["title"]="Lieutenant Jocryn Heldric"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8897:description:1-93","8897:description:95-173","8897:description:175-252","8897:description:257-287","8897:description:289-323","8897:description:325-343","8897:description:348-390","8897:description:392-461","8897:objective:1-96"},["minimumStage"]=2,["questID"]=8897,["sourceHash"]="81f42bde3cd3ad3eb69c6d44efafec79ac6309fe89d39e7dc4f871386d865161"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16005",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Limited time with Colara and fear of wealthier rivals led him to entrust a personal letter to someone who could reach his sweetheart.",["title"]="Lieutenant Jocryn Heldric"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8898:description:1-71","8898:description:73-96","8898:description:98-134","8898:description:136-202","8898:description:207-269","8898:description:274-319","8898:objective:1-72"},["minimumStage"]=2,["questID"]=8898,["sourceHash"]="d47104c0630f449c57af86c7973f331627dd4dd9f33681470cdb1930591ec8b6"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-16009",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tormek Stoneriver met the woman he loved while visiting Stormwind on the bank’s business.",["title"]="Tormek Stoneriver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8898:description:1-71","8898:description:73-96","8898:description:98-134","8898:description:136-202","8898:description:207-269","8898:description:274-319","8898:objective:1-72"},["minimumStage"]=2,["questID"]=8898,["sourceHash"]="d47104c0630f449c57af86c7973f331627dd4dd9f33681470cdb1930591ec8b6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16009",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After rewriting his message a dozen times, he wanted it carried directly rather than risk the crowded mail.",["title"]="Tormek Stoneriver"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"541:description:1-26","541:description:29-60","541:description:65-117","541:description:120-216","541:description:219-278","541:description:283-380","541:description:383-448","541:description:451-491","541:objective:1-132"},["minimumStage"]=2,["questID"]=541,["sourceHash"]="4f9229e5b1ca6bb9e16a3b5b1a613dda743aefb7f5e148c3d4a1771bf1318184"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2304",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Captain Ironhill led the dwarven force at Dun Garok, the barracks along Thoradin’s Wall in southeastern Hillsbrad.",["title"]="Captain Ironhill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"541:description:1-26","541:description:29-60","541:description:65-117","541:description:120-216","541:description:219-278","541:description:283-380","541:description:383-448","541:description:451-491","541:objective:1-132"},["minimumStage"]=2,["questID"]=541,["sourceHash"]="4f9229e5b1ca6bb9e16a3b5b1a613dda743aefb7f5e148c3d4a1771bf1318184"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2304",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Forsaken commanders marked him as the final target of their siege, intending to punish the dwarves for aiding Hillsbrad’s humans.",["title"]="Captain Ironhill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"543:description:1-129","543:description:132-235","543:description:240-429","543:description:434-476","543:objective:1-62"},["minimumStage"]=2,["questID"]=543,["sourceHash"]="b412cd89ed40eecd103cd7befcdbb7186fb854d26aa48ac8fc57d73745a30e69"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2417",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grel’borg the Miser was an ogre mage rumored to have found the lost emerald-set Perenolde tiara.",["title"]="Grel'borg the Miser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"543:description:1-129","543:description:132-235","543:description:240-429","543:description:434-476","543:objective:1-62"},["minimumStage"]=2,["questID"]=543,["sourceHash"]="b412cd89ed40eecd103cd7befcdbb7186fb854d26aa48ac8fc57d73745a30e69"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-2417",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Reports placed him wandering the ruins of Alterac in search of further treasure.",["title"]="Grel'borg the Miser"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"563:description:1-49","563:description:51-146","563:description:148-230","563:description:232-281","563:description:283-320","563:objective:1-61"},["minimumStage"]=2,["questID"]=563,["sourceHash"]="68be205c971e2f6f7e32d9d8ead630107e0f49cab2c22ca7dfb2bb435eb29ba2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2439",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Major Samuelson had become captain of Stormwind’s guard when a former pupil sought reassignment to the city.",["title"]="Major Samuelson"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"563:description:1-49","563:description:51-146","563:description:148-230","563:description:232-281","563:description:283-320","563:objective:1-61"},["minimumStage"]=2,["questID"]=563,["sourceHash"]="68be205c971e2f6f7e32d9d8ead630107e0f49cab2c22ca7dfb2bb435eb29ba2"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2439",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The dissatisfied guard hoped their old mentorship would help the report reach sympathetic hands without drawing his current commander’s attention.",["title"]="Major Samuelson"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"566:description:1-111","566:description:113-199","566:description:204-285","566:description:290-307","566:description:309-384","566:objective:1-81"},["minimumStage"]=2,["questID"]=566,["sourceHash"]="18e1ff76eaa8ae367c22877315f82270ae9b3d28d03f164dbd17afd17de3bf8b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2306",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Baron Vardus was identified by a Forsaken wanted notice as a high-ranking human member of the Syndicate.",["title"]="Baron Vardus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"566:description:1-111","566:description:113-199","566:description:204-285","566:description:290-307","566:description:309-384","566:objective:1-81"},["minimumStage"]=2,["questID"]=566,["sourceHash"]="18e1ff76eaa8ae367c22877315f82270ae9b3d28d03f164dbd17afd17de3bf8b"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-2306",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His last reported sighting was in the Uplands of the Alterac Mountains, north of Tarren Mill.",["title"]="Baron Vardus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"567:description:1-10","567:description:15-128","567:description:133-157","567:description:160-200","567:description:205-219","567:description:222-261","567:description:266-279","567:description:282-323","567:description:328-341","567:description:344-396","567:description:401-457","567:description:460-511","567:objective:1-137"},["minimumStage"]=2,["questID"]=567,["sourceHash"]="250edb4aceccb1ce6329c0ce8c9102eefe6627fb5532ef286a245d456aa6024d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2450",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="High Executor Darthalia’s bounty notice accused Miner Hackett of murdering Deathstalker Fry; the notice offered payment for his death.",["title"]="Miner Hackett"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"567:description:1-10","567:description:15-128","567:description:133-157","567:description:160-200","567:description:205-219","567:description:222-261","567:description:266-279","567:description:282-323","567:description:328-341","567:description:344-396","567:description:401-457","567:description:460-511","567:objective:1-137"},["minimumStage"]=2,["questID"]=567,["sourceHash"]="250edb4aceccb1ce6329c0ce8c9102eefe6627fb5532ef286a245d456aa6024d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2449",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Darthalia’s wanted notice accused Citizen Wilkes of murdering Apothecary Eli and placed a bounty on him.",["title"]="Citizen Wilkes"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"567:description:1-10","567:description:15-128","567:description:133-157","567:description:160-200","567:description:205-219","567:description:222-261","567:description:266-279","567:description:282-323","567:description:328-341","567:description:344-396","567:description:401-457","567:description:460-511","567:objective:1-137"},["minimumStage"]=2,["questID"]=567,["sourceHash"]="250edb4aceccb1ce6329c0ce8c9102eefe6627fb5532ef286a245d456aa6024d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2448",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Forsaken bounty against Clerk Horrace Whitesteed named the murder of Deathguard Toma as the accusation behind it.",["title"]="Clerk Horrace Whitesteed"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"567:description:1-10","567:description:15-128","567:description:133-157","567:description:160-200","567:description:205-219","567:description:222-261","567:description:266-279","567:description:282-323","567:description:328-341","567:description:344-396","567:description:401-457","567:description:460-511","567:objective:1-137"},["minimumStage"]=2,["questID"]=567,["sourceHash"]="250edb4aceccb1ce6329c0ce8c9102eefe6627fb5532ef286a245d456aa6024d"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2451",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Darthalia’s notice accused Farmer Kalaba of ambushing supplies from the Undercity and ordered a bounty for his death.",["title"]="Farmer Kalaba"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"570:description:1-81","570:description:84-124","570:description:127-164","570:description:167-220","570:description:225-291","570:description:294-319","570:description:322-354","570:description:359-486","570:objective:1-99"},["minimumStage"]=2,["questID"]=570,["sourceHash"]="ca96140b9ec6241de141c85df79f6495aef7feaadfb3726a7e8f3fcf887295fb"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-684",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shadowmaw panthers prowled Stranglethorn’s jungle, including the ground across the river from Mizjah Ruins.",["title"]="Shadowmaw Panther"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"570:description:1-81","570:description:84-124","570:description:127-164","570:description:167-220","570:description:225-291","570:description:294-319","570:description:322-354","570:description:359-486","570:objective:1-99"},["minimumStage"]=2,["questID"]=570,["sourceHash"]="ca96140b9ec6241de141c85df79f6495aef7feaadfb3726a7e8f3fcf887295fb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-684",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mok’thardin wanted their claws together with a flawless tigress fang as the first materials for a powerful enchantment.",["title"]="Shadowmaw Panther"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"571:description:1-58","571:description:63-154","571:description:157-193","571:description:198-260","571:description:263-312","571:description:317-342","571:description:345-447","571:objective:1-64"},["minimumStage"]=2,["questID"]=571,["sourceHash"]="9fcc05d1415f4d8036be78e48154510e6084d07ecb13635d2de8d360272e05ac"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1557",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Elder Mistvale gorillas foraged east of Booty Bay.",["title"]="Elder Mistvale Gorilla"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"571:description:1-58","571:description:63-154","571:description:157-193","571:description:198-260","571:description:263-312","571:description:317-342","571:description:345-447","571:objective:1-64"},["minimumStage"]=2,["questID"]=571,["sourceHash"]="9fcc05d1415f4d8036be78e48154510e6084d07ecb13635d2de8d360272e05ac"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1557",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The aged gorillas’ sinew could serve as a magical tether in Mok’thardin’s work, but he would accept only an undamaged specimen.",["title"]="Elder Mistvale Gorilla"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"572:description:1-119","572:description:122-260","572:description:265-324","572:description:327-394","572:description:397-490","572:objective:1-83"},["minimumStage"]=2,["questID"]=572,["sourceHash"]="a761171c3f3f37b6fe0bd61fd646e78a2cb93ad9d9ed522362a0f769f701ca7c"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-687",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jungle Stalker raptors wore feathers on their armbands, the adornments Mok’thardin sought for his ritual.",["title"]="Jungle Stalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"572:description:1-119","572:description:122-260","572:description:265-324","572:description:327-394","572:description:397-490","572:objective:1-83"},["minimumStage"]=2,["questID"]=572,["sourceHash"]="a761171c3f3f37b6fe0bd61fd646e78a2cb93ad9d9ed522362a0f769f701ca7c"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-687",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A tribe of the raptors lived directly south of Grom’gol, not far from Stranglethorn’s great arena.",["title"]="Jungle Stalker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"581:description:1-17","581:description:20-62","581:description:65-242","581:description:245-331","581:description:336-378","581:description:383-430","581:description:433-463","581:description:466-501","581:objective:1-62"},["minimumStage"]=2,["questID"]=581,["sourceHash"]="ce83dfcc0bb09827f504c714be4cd3583488eb8f6416bfbbf300b10f3bf824d8"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2530",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Yenniku, the Darkspear chief’s youngest son in Nimboya’s account, had been given to Zul’Gurub’s Gurubashi according to tribal custom.",["title"]="Yenniku"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"581:description:1-17","581:description:20-62","581:description:65-242","581:description:245-331","581:description:336-378","581:description:383-430","581:description:433-463","581:description:466-501","581:objective:1-62"},["minimumStage"]=2,["questID"]=581,["sourceHash"]="ce83dfcc0bb09827f504c714be4cd3583488eb8f6416bfbbf300b10f3bf824d8"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2530",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After the Darkspear left with Thrall, the tribe lost contact with him; Nimboya returned from Orgrimmar and suspected the Bloodscalp held him.",["title"]="Yenniku"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"582:description:1-32","582:description:37-108","582:description:111-214","582:description:219-335","582:description:349-447","582:objective:1-61"},["minimumStage"]=2,["questID"]=582,["sourceHash"]="fbfa183d1629aee19f41fa3d4d844f3d407b66b7560ca28cd0cdc7af5ca98fcb"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1061",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gan’zulah was the Bloodscalp chief whom Nimboya held responsible if the missing Yenniku had been killed.",["title"]="Gan'zulah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"584:description:1-70","584:description:73-108","584:description:113-206","584:description:209-327","584:description:332-421","584:description:426-456","584:description:459-506","584:objective:1-94"},["minimumStage"]=2,["questID"]=584,["sourceHash"]="e9d26228ac83c8551cd8871dbc2c024f86490287b9c409000ae2c9154982c0ad"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-1061",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The chief and his witchdoctor Nezzliok remained deep within Zul’Kunda during Nimboya’s search.",["title"]="Gan'zulah"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"584:description:1-70","584:description:73-108","584:description:113-206","584:description:209-327","584:description:332-421","584:description:426-456","584:description:459-506","584:objective:1-94"},["minimumStage"]=2,["questID"]=584,["sourceHash"]="e9d26228ac83c8551cd8871dbc2c024f86490287b9c409000ae2c9154982c0ad"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1062",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nezzliok the Dire was the Bloodscalp witchdoctor paired with Gan’zulah in Nimboya’s attempt to force answers about Yenniku.",["title"]="Nezzliok the Dire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"584:description:1-70","584:description:73-108","584:description:113-206","584:description:209-327","584:description:332-421","584:description:426-456","584:description:459-506","584:objective:1-94"},["minimumStage"]=2,["questID"]=584,["sourceHash"]="e9d26228ac83c8551cd8871dbc2c024f86490287b9c409000ae2c9154982c0ad"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1062",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nimboya proposed placing both enemies’ severed heads in a cauldron to make their dead lips reveal what they would not willingly tell the Darkspear.",["title"]="Nezzliok the Dire"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"586:description:1-31","586:description:36-45","586:description:48-73","586:description:78-150","586:description:152-159","586:description:164-227","586:description:230-340","586:description:343-346","586:description:349-388","586:description:393-464","586:objective:1-90","586:objective:95-180"},["minimumStage"]=2,["questID"]=586,["sourceHash"]="37e95fce3c13be9039740bf74fc1fa35bacdb33750da333f20b18d85024c7358"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1059",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ana’thek the Cruel was the Skullsplitter chief whom Gan’zulah’s severed head named as the greatest danger among the tribe’s eastern fighters.",["title"]="Ana'thek the Cruel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"586:description:1-31","586:description:36-45","586:description:48-73","586:description:78-150","586:description:152-159","586:description:164-227","586:description:230-340","586:description:343-346","586:description:349-388","586:description:393-464","586:objective:1-90","586:objective:95-180"},["minimumStage"]=2,["questID"]=586,["sourceHash"]="37e95fce3c13be9039740bf74fc1fa35bacdb33750da333f20b18d85024c7358"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1059",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gan’zulah demanded the chief’s shattered armor as proof, trying to turn his interrogator’s search into a lethal confrontation with his rival.",["title"]="Ana'thek the Cruel"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"588:description:1-18","588:description:23-114","588:description:119-152","588:description:157-207","588:description:210-299","588:description:304-336","588:description:341-410","588:description:413-430","588:objective:1-22"},["minimumStage"]=2,["questID"]=588,["sourceHash"]="6069b2a17e6038a0bb2aa00f4de0f36b712abd39bbfb2ab79cdd3866e25b3870"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2534",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nezzliok’s spirit identified Zanzil as the witchdoctor who had taken Yenniku and held the young troll’s body and soul under his control.",["title"]="Zanzil the Outcast"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"588:description:1-18","588:description:23-114","588:description:119-152","588:description:157-207","588:description:210-299","588:description:304-336","588:description:341-410","588:description:413-430","588:objective:1-22"},["minimumStage"]=2,["questID"]=588,["sourceHash"]="6069b2a17e6038a0bb2aa00f4de0f36b712abd39bbfb2ab79cdd3866e25b3870"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2534",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="That account made Yenniku’s recovery a matter of potent magic rather than simply finding a captive, leaving the Darkspear to seek a means of release.",["title"]="Zanzil the Outcast"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"609:description:1-61","609:description:66-148","609:description:153-251","609:description:254-329","609:description:332-388","609:description:393-467","609:description:470-492","609:objective:1-115"},["minimumStage"]=2,["questID"]=609,["sourceHash"]="bf2663932abf0b75b14ac2e7d0e813af536676088dd33c879837d85355677deb"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2535",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mackinley counted Maury “Club Foot” Wilkins among debtors who had been overdue for months, later hearing that the men were cursed and wandering jungle ruins.",["title"]="Maury \"Club Foot\" Wilkins"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"609:description:1-61","609:description:66-148","609:description:153-251","609:description:254-329","609:description:332-388","609:description:393-467","609:description:470-492","609:objective:1-115"},["minimumStage"]=2,["questID"]=609,["sourceHash"]="bf2663932abf0b75b14ac2e7d0e813af536676088dd33c879837d85355677deb"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2536",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jon-Jon the Crow was one of Mackinley’s missing debtors; stories of the men’s bewitchment did not soften the creditor’s demand for repayment.",["title"]="Jon-Jon the Crow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"609:description:1-61","609:description:66-148","609:description:153-251","609:description:254-329","609:description:332-388","609:description:393-467","609:description:470-492","609:objective:1-115"},["minimumStage"]=2,["questID"]=609,["sourceHash"]="bf2663932abf0b75b14ac2e7d0e813af536676088dd33c879837d85355677deb"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2537",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Chucky “Ten Thumbs” owed Mackinley money, part of a group the creditor first thought had fled town before hearing of a curse.",["title"]="Chucky \"Ten Thumbs\""},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"637:description:1-149","637:description:154-186","637:description:188-242","637:objective:1-45","637:completion:1-55","637:completion:57-72","637:completion:77-105"},["minimumStage"]=4,["questID"]=637,["sourceHash"]="a1e92517f7d045907b359ead31f88d21261617971c93dc52dd1cc716df57e06a"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2695",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sara Balloo received Sully’s painstakingly written letter with the news that her husband lay pinned beneath the cold water.",["title"]="Sara Balloo"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"683:description:1-45","683:description:50-138","683:description:140-261","683:description:266-359","683:description:362-383","683:objective:1-63"},["minimumStage"]=2,["questID"]=683,["sourceHash"]="a99f1146ef2abf8b289325ffb1ec9a4969fd266c808b376b67e5683ae2b54fe5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2695",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grief kept her from presenting her cause before King Magni in person, so she entrusted her prepared plea to a messenger.",["title"]="Sara Balloo"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"686:description:1-38","686:description:40-137","686:description:139-256","686:description:261-349","686:description:354-443","686:description:448-472","686:description:474-510","686:objective:1-70"},["minimumStage"]=2,["questID"]=686,["sourceHash"]="649ec407f53157887d3dc2e45cf012e4a90d4a27967dfe3437c3e89ac1543d57"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2695",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The king answered the loss of her husband by commissioning Grand Mason Marblesten to create a memorial to Sully.",["title"]="Sara Balloo"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"638:description:1-244","638:description:249-373","638:objective:1-66"},["minimumStage"]=2,["questID"]=638,["sourceHash"]="227243660435d4708d68bdcca9e784ac655c552e48e684ea539b0c60cd00f021"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10540",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vol’jin directed an effort to obtain Trol’kalar from ruined Stromgarde for the coming struggle against Zul’Gurub’s trolls.",["title"]="Vol'jin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"643:description:1-167","643:description:169-252","643:description:257-375","643:description:377-418","643:objective:1-67"},["minimumStage"]=2,["questID"]=643,["sourceHash"]="8f6cc00e6072bc4e63befb4b728d54bd2e53de4c0031ce0c74b29747767f1497"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2612",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lieutenant Valorcall led the surviving Stromgarde cavalry and carried one of the sigils entrusted by the human prince.",["title"]="Lieutenant Valorcall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"643:description:1-167","643:description:169-252","643:description:257-375","643:description:377-418","643:objective:1-67"},["minimumStage"]=2,["questID"]=643,["sourceHash"]="8f6cc00e6072bc4e63befb4b728d54bd2e53de4c0031ce0c74b29747767f1497"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2612",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The effort to obtain those sigils made his patrol a target even while Stromgarde’s grip on the surrounding highlands had weakened.",["title"]="Lieutenant Valorcall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"647:description:1-48","647:description:51-124","647:description:129-162","647:description:165-247","647:description:252-275","647:description:277-376","647:description:381-434","647:description:437-474","647:description:477-486","647:objective:1-62"},["minimumStage"]=2,["questID"]=647,["sourceHash"]="988a4090c5324d1591e042258c4cd494ffbe7373187050abc90d7989cb28edd0"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2705",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Brewmeister Bilger in Southshore was owed a batch of moonshine by MacKreel, who sought a courier after drinking through his watch and nearly missing the promised delivery.",["title"]="Brewmeister Bilger"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"657:description:1-39","657:description:44-63","657:description:65-148","657:description:150-242","657:description:247-348","657:description:350-504","657:objective:1-18"},["minimumStage"]=2,["questID"]=657,["sourceHash"]="096103cfa4cf4176d2cfb34e3d0f02f568666af9748b0c2b7306b72b5d0b2360"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2733",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Apothecary Jorell conducted deadly experiments at Go’Shek Farm and sent research onward to Tarren Mill.",["title"]="Apothecary Jorell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"657:description:1-39","657:description:44-63","657:description:65-148","657:description:150-242","657:description:247-348","657:description:350-504","657:objective:1-18"},["minimumStage"]=2,["questID"]=657,["sourceHash"]="096103cfa4cf4176d2cfb34e3d0f02f568666af9748b0c2b7306b72b5d0b2360"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2733",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The recovered folder drew Quae’s concern and a plan for Kinelory to steal the research that had not yet left the farm.",["title"]="Apothecary Jorell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"659:description:1-23","659:description:25-96","659:description:101-258","659:description:263-342","659:description:347-471","659:description:473-489","659:description:491-507","659:objective:1-69"},["minimumStage"]=2,["questID"]=659,["sourceHash"]="921e5e8efbd1fc39e23d8cf1836e91dd9b7aceee6a653790eb0621e496a9f824"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2713",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kinelory accompanied Quae to Go’Shek while their group investigated strange events suspected to involve the undead.",["title"]="Kinelory"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"657:description:1-39","657:description:44-63","657:description:65-148","657:description:150-242","657:description:247-348","657:description:350-504","657:objective:1-18"},["minimumStage"]=2,["questID"]=657,["sourceHash"]="096103cfa4cf4176d2cfb34e3d0f02f568666af9748b0c2b7306b72b5d0b2360"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2713",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="After orcs injured Quae, Kinelory needed another protector for her descent to Jorell’s farm to take the remaining research.",["title"]="Kinelory"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"659:description:1-23","659:description:25-96","659:description:101-258","659:description:263-342","659:description:347-471","659:description:473-489","659:description:491-507","659:objective:1-69"},["minimumStage"]=2,["questID"]=659,["sourceHash"]="921e5e8efbd1fc39e23d8cf1836e91dd9b7aceee6a653790eb0621e496a9f824"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2274",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stanley, the Hillsbrad dog, grew to an immense size and attacked anyone nearby before his owner put him down, according to the investigating adventurer’s account.",["title"]="Stanley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"659:description:1-23","659:description:25-96","659:description:101-258","659:description:263-342","659:description:347-471","659:description:473-489","659:description:491-507","659:objective:1-69"},["minimumStage"]=2,["questID"]=659,["sourceHash"]="921e5e8efbd1fc39e23d8cf1836e91dd9b7aceee6a653790eb0621e496a9f824"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2274",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The transformation prompted suspicion of undead involvement and sent investigators toward Go’Shek Farm, though that first report did not yet prove the cause.",["title"]="Stanley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"680:description:1-83","680:description:88-242","680:description:247-367","680:description:372-499","680:objective:1-72"},["minimumStage"]=2,["questID"]=680,["sourceHash"]="3cf4cf4497e59b2cb94b37b3c241492c1ec4e0b2f2dba54a8425fbce59a1a254"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2773",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The augur opposing Or’Kalar believed he still wanted revenge for a defeat inflicted by her husband years earlier.",["title"]="Or'Kalar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"680:description:1-83","680:description:88-242","680:description:247-367","680:description:372-499","680:objective:1-72"},["minimumStage"]=2,["questID"]=680,["sourceHash"]="3cf4cf4497e59b2cb94b37b3c241492c1ec4e0b2f2dba54a8425fbce59a1a254"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2773",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She described him as Mug’Thol’s agent in Stromgarde and feared a trap, hiding signs of his presence to keep her husband from rushing into danger.",["title"]="Or'Kalar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"642:description:1-19","642:description:22-129","642:description:132-204","642:description:209-223","642:description:226-337","642:description:340-432","642:description:437-458","642:objective:1-89"},["minimumStage"]=2,["questID"]=642,["sourceHash"]="3d21ef3f48d1bb6d96990bdedc8c1ef749ce27d149ba800f9461221e3fb7cb83"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2755",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Myzrael introduced herself as a princess of the earth, speaking to the surface through crystal shards above her underground confinement.",["title"]="Myzrael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"642:description:1-19","642:description:22-129","642:description:132-204","642:description:209-223","642:description:226-337","642:description:340-432","642:description:437-458","642:objective:1-89"},["minimumStage"]=2,["questID"]=642,["sourceHash"]="3d21ef3f48d1bb6d96990bdedc8c1ef749ce27d149ba800f9461221e3fb7cb83"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2755",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She said giants had imprisoned her beneath the Arathi Highlands and directed a would-be helper toward the Drywhisker kobolds’ shard cluster.",["title"]="Myzrael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"652:description:1-97","652:description:100-154","652:description:157-223","652:description:228-345","652:description:350-385","652:description:388-470","652:objective:1-21","652:objective:24-86"},["minimumStage"]=2,["questID"]=652,["sourceHash"]="bca383530c8119935ab7ad5a0c3a76fb29e748326f7060537bf67afdef124c48"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2755",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A final keystone held the remaining lock on her prison, with the Rod of Order carried by the stone watcher Fozruk serving as its key.",["title"]="Myzrael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8900:description:1-15","8900:description:17-60","8900:description:62-99","8900:description:104-152","8900:description:154-227","8900:description:232-307","8900:description:309-323","8900:description:325-363","8900:description:365-401","8900:objective:1-82"},["minimumStage"]=2,["questID"]=8900,["sourceHash"]="f3c6ab62eeea2a54d4bf458434ae4a5c44e792eb1bd8873cd5475461f5d5966b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-16007",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Orok Deathbane felt understood by Elenia in a way he had not expected, but companions’ laughter led him to stop speaking with her.",["title"]="Orok Deathbane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8900:description:1-15","8900:description:17-60","8900:description:62-99","8900:description:104-152","8900:description:154-227","8900:description:232-307","8900:description:309-323","8900:description:325-363","8900:description:365-401","8900:objective:1-82"},["minimumStage"]=2,["questID"]=8900,["sourceHash"]="f3c6ab62eeea2a54d4bf458434ae4a5c44e792eb1bd8873cd5475461f5d5966b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16007",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Missing that connection, he wanted his letter placed directly in her hands rather than left to chance.",["title"]="Orok Deathbane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8901:description:1-36","8901:description:38-125","8901:description:127-218","8901:description:223-282","8901:description:287-332","8901:description:334-368","8901:description:370-398","8901:objective:1-85"},["minimumStage"]=2,["questID"]=8901,["sourceHash"]="688da989e4d39ce584bf7794c03f4d8b3b23eade9237e4f1c34f9cff6a53678a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-16008",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Temma of the Wells fell in love with Elenia of the Undercity despite the rarity of looking beyond Temma’s own people, particularly toward a Forsaken.",["title"]="Temma of the Wells"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8901:description:1-36","8901:description:38-125","8901:description:127-218","8901:description:223-282","8901:description:287-332","8901:description:334-368","8901:description:370-398","8901:objective:1-85"},["minimumStage"]=2,["questID"]=8901,["sourceHash"]="688da989e4d39ce584bf7794c03f4d8b3b23eade9237e4f1c34f9cff6a53678a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16008",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The letter invited Elenia to Mulgore, with Temma hoping she would choose to come.",["title"]="Temma of the Wells"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8902:description:1-73","8902:description:75-171","8902:description:176-280","8902:description:285-315","8902:description:317-358","8902:description:360-397","8902:objective:1-85"},["minimumStage"]=2,["questID"]=8902,["sourceHash"]="fd015e1ed6f0d02d34d72ca628ea71dacff66cf6dd6ae83109ab3a97270d416f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-16003",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Before undeath changed their lives, Deathguard Tor had been betrothed to his childhood sweetheart Elenia.",["title"]="Deathguard Tor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8902:description:1-73","8902:description:75-171","8902:description:176-280","8902:description:285-315","8902:description:317-358","8902:description:360-397","8902:objective:1-85"},["minimumStage"]=2,["questID"]=8902,["sourceHash"]="fd015e1ed6f0d02d34d72ca628ea71dacff66cf6dd6ae83109ab3a97270d416f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16003",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Memories returned after years apart, but nervousness kept him from asking in person whether their love still had a place in their altered lives.",["title"]="Deathguard Tor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8905:description:1-13","8905:description:16-54","8905:description:59-176","8905:description:179-262","8905:description:267-375","8905:description:378-460","8905:description:463-505","8905:objective:1-127"},["minimumStage"]=2,["questID"]=8905,["sourceHash"]="93bbd7745895a292ce800a452587c46b146c723cd07a111f788519404f890acf"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16013",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Deliana offered superior armor in exchange for ordinary pieces, gold and assistance with her material requirements.",["title"]="Deliana"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8905:description:1-13","8905:description:16-54","8905:description:59-176","8905:description:179-262","8905:description:267-375","8905:description:378-460","8905:description:463-505","8905:objective:1-127"},["minimumStage"]=2,["questID"]=8905,["sourceHash"]="93bbd7745895a292ce800a452587c46b146c723cd07a111f788519404f890acf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16013",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her first request concerned the useful properties of blood from Winterspring’s bears and frostsabers.",["title"]="Deliana"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8913:description:1-9","8913:description:12-84","8913:description:87-155","8913:description:160-258","8913:description:263-363","8913:description:366-440","8913:objective:1-122"},["minimumStage"]=2,["questID"]=8913,["sourceHash"]="0986cfd740a485c21b13d6741ea1f78f558f7f2ebe3cd85fec57b2ab8fe64265"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16012",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mokvar offered an improved set of bracers in exchange for ordinary armor, payment and a favor.",["title"]="Mokvar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8913:description:1-9","8913:description:12-84","8913:description:87-155","8913:description:160-258","8913:description:263-363","8913:description:366-440","8913:objective:1-122"},["minimumStage"]=2,["questID"]=8913,["sourceHash"]="0986cfd740a485c21b13d6741ea1f78f558f7f2ebe3cd85fec57b2ab8fe64265"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16012",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He required a large sample of venom from Silithus’s spiders and scorpids before making the exchange.",["title"]="Mokvar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8921:description:1-42","8921:description:44-80","8921:description:83-131","8921:description:136-158","8921:description:161-170","8921:description:173-244","8921:description:247-306","8921:description:311-408","8921:description:410-503","8921:objective:1-151"},["minimumStage"]=2,["questID"]=8921,["sourceHash"]="36cba9a1ce54ccd6f65dafcc432ff3a1645d0d0e7d199637fb72b18d9998faf4"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16014",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mux Manascrambler developed an extra-dimensional ghost revealer, beginning with an ectoplasmic distiller to gather the substance of death.",["title"]="Mux Manascrambler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8921:description:1-42","8921:description:44-80","8921:description:83-131","8921:description:136-158","8921:description:161-170","8921:description:173-244","8921:description:247-306","8921:description:311-408","8921:description:410-503","8921:objective:1-151"},["minimumStage"]=2,["questID"]=8921,["sourceHash"]="36cba9a1ce54ccd6f65dafcc432ff3a1645d0d0e7d199637fb72b18d9998faf4"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-16014",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Short of funds and workers, Mux needed a helper to provide the converter, essences, oil and volcanic ash for its filter.",["title"]="Mux Manascrambler"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8946:description:1-83","8946:description:86-144","8946:description:149-194","8946:description:197-268","8946:description:273-285","8946:description:288-318","8946:objective:1-62"},["minimumStage"]=2,["questID"]=8946,["sourceHash"]="8364d22d722e9aa0a2315f56e5aa254c2a78278acbd63c3a89e862cac712afdf"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-16031",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ysida Harmon’s beloved died trying to rescue her, leaving her grateful for her own safety but unwilling for his spirit to linger.",["title"]="Ysida Harmon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8946:description:1-83","8946:description:86-144","8946:description:149-194","8946:description:197-268","8946:description:273-285","8946:description:288-318","8946:objective:1-62"},["minimumStage"]=2,["questID"]=8946,["sourceHash"]="8364d22d722e9aa0a2315f56e5aa254c2a78278acbd63c3a89e862cac712afdf"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16031",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She entrusted a locket as proof that she was well to someone who claimed the ability to speak with him.",["title"]="Ysida Harmon"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8984:description:1-59","8984:description:61-153","8984:description:158-212","8984:description:217-270","8984:description:272-353","8984:description:355-407","8984:objective:1-81"},["minimumStage"]=2,["questID"]=8984,["sourceHash"]="43bd0a3712e1cbf3d57eb4e86a2963b8aa4d03bdd8437baaedb77190b570ed91"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-16109",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mara Rennick bought the disputed goods from Apothecary Staffron Lerent, who worked in secluded Hillsbrad hills beyond Ravenholdt.",["title"]="Mara Rennick"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8984:description:1-59","8984:description:61-153","8984:description:158-212","8984:description:217-270","8984:description:272-353","8984:description:355-407","8984:objective:1-81"},["minimumStage"]=2,["questID"]=8984,["sourceHash"]="43bd0a3712e1cbf3d57eb4e86a2963b8aa4d03bdd8437baaedb77190b570ed91"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16109",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She was willing to identify her supplier if he undermined their efforts, while leaving the accusation of wrongdoing to the investigator.",["title"]="Mara Rennick"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8996:description:1-135","8996:description:137-264","8996:description:269-337","8996:description:339-381","8996:description:383-390","8996:objective:1-81"},["minimumStage"]=2,["questID"]=8996,["sourceHash"]="52e7950c144b54e5205be6e7f9cb71377726f64b166785c3356efc1e76c6f625"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16042",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Valthalak’s spirit acknowledged the restoration of its stolen portions and offered the thieves temporary safety, coupling respect for the helper’s courage with a threat that his patience might end.",["title"]="Lord Valthalak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9023:description:1-71","9023:description:76-260","9023:description:265-396","9023:description:398-491","9023:objective:1-103"},["minimumStage"]=2,["questID"]=9023,["sourceHash"]="7b89ad193dfa1e8e9c21c57c3301bbd238e97d2c4fc98999cfbc6f2b1c9aa422"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16091",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dirk Thunderwood ran Ravenholdt’s poison operations with his brother under the lord’s direction.",["title"]="Dirk Thunderwood"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9023:description:1-71","9023:description:76-260","9023:description:265-396","9023:description:398-491","9023:objective:1-103"},["minimumStage"]=2,["questID"]=9023,["sourceHash"]="7b89ad193dfa1e8e9c21c57c3301bbd238e97d2c4fc98999cfbc6f2b1c9aa422"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16091",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought venom sacs from Venoxis and Kurinnaxx as the basis of an unusually effective compound.",["title"]="Dirk Thunderwood"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9028:description:1-5","9028:description:7-14","9028:description:24-75","9028:description:80-157","9028:description:159-181","9028:description:186-250","9028:description:255-327","9028:description:329-351","9028:description:356-467","9028:description:469-499","9028:objective:1-83"},["minimumStage"]=2,["questID"]=9028,["sourceHash"]="c5fe4d7fd1e04ee50e06c2380810e3c89a4f66155b69f77245d1ef9e2ea92f6b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16106",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Evert Sorisam dealt in goods intended to ease courtship and denied that the business amounted to treason.",["title"]="Evert Sorisam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9028:description:1-5","9028:description:7-14","9028:description:24-75","9028:description:80-157","9028:description:159-181","9028:description:186-250","9028:description:255-327","9028:description:329-351","9028:description:356-467","9028:description:469-499","9028:objective:1-83"},["minimumStage"]=2,["questID"]=9028,["sourceHash"]="c5fe4d7fd1e04ee50e06c2380810e3c89a4f66155b69f77245d1ef9e2ea92f6b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-16106",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A goblin intermediary arranged his shipments from Staffron Lerent; Evert had never spoken to the apothecary himself.",["title"]="Evert Sorisam"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"8984:description:1-59","8984:description:61-153","8984:description:158-212","8984:description:217-270","8984:description:272-353","8984:description:355-407","8984:objective:1-81"},["minimumStage"]=2,["questID"]=8984,["sourceHash"]="43bd0a3712e1cbf3d57eb4e86a2963b8aa4d03bdd8437baaedb77190b570ed91"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16107",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Apothecary Staffron Lerent supplied the goods Mara Rennick identified during the inquiry into their source.",["title"]="Apothecary Staffron Lerent"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9028:description:1-5","9028:description:7-14","9028:description:24-75","9028:description:80-157","9028:description:159-181","9028:description:186-250","9028:description:255-327","9028:description:329-351","9028:description:356-467","9028:description:469-499","9028:objective:1-83"},["minimumStage"]=2,["questID"]=9028,["sourceHash"]="c5fe4d7fd1e04ee50e06c2380810e3c89a4f66155b69f77245d1ef9e2ea92f6b"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-16107",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His shipments also reached Evert Sorisam through a goblin intermediary, who placed the apothecary beyond Ravenholdt Manor in the Hillsbrad foothills.",["title"]="Apothecary Staffron Lerent"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9141:description:1-16","9141:description:18-22","9141:description:24-105","9141:description:107-125","9141:description:127-194","9141:description:199-290","9141:description:292-329","9141:description:334-422","9141:objective:1-107"},["minimumStage"]=2,["questID"]=9141,["sourceHash"]="6282ee933968a9c23cb81cdbebf8ddce42dd0eab39aecd891ac4ff0ca498b6d7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16212",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dispatch Commander Metz controlled sought-after work orders at the front, where crafters from across the world competed for jobs.",["title"]="Dispatch Commander Metz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9141:description:1-16","9141:description:18-22","9141:description:24-105","9141:description:107-125","9141:description:127-194","9141:description:199-290","9141:description:292-329","9141:description:334-422","9141:objective:1-107"},["minimumStage"]=2,["questID"]=9141,["sourceHash"]="6282ee933968a9c23cb81cdbebf8ddce42dd0eab39aecd891ac4ff0ca498b6d7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16212",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Metz required a valor token as proof of service before discussing an order, dismissing the idea that arrival alone deserved one.",["title"]="Dispatch Commander Metz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9165:description:1-69","9165:description:71-147","9165:description:152-181","9165:description:186-247","9165:description:249-348","9165:description:353-395","9165:description:397-504","9165:objective:1-117"},["minimumStage"]=2,["questID"]=9165,["sourceHash"]="582a08413fbeed4a9258e48305e2ed746ee2150d88f5fb8677eabe054ca4777d"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-16226",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Guard Didier credited adventurers with bringing his caravan through repeated Scourge attacks.",["title"]="Guard Didier"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9165:description:1-69","9165:description:71-147","9165:description:152-181","9165:description:186-247","9165:description:249-348","9165:description:353-395","9165:description:397-504","9165:objective:1-117"},["minimumStage"]=2,["questID"]=9165,["sourceHash"]="582a08413fbeed4a9258e48305e2ed746ee2150d88f5fb8677eabe054ca4777d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-16226",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The caravan then awaited Field Marshal Chambers, who would sign the writ for Metz at Light’s Hope; Didier warned that the officer was dangerous to cross.",["title"]="Guard Didier"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9260:description:1-80","9260:description:82-154","9260:description:161-281","9260:description:283-351","9260:description:353-487","9260:objective:1-133"},["minimumStage"]=2,["questID"]=9260,["sourceHash"]="35bcf6850f576c90da2aa34bc0ee59ef4729d010fb2646bfb89c615c7ad92c4f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-16478",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lieutenant Orrin called for defenders when the Scourge and a necropolis appeared at Stormwind’s doorstep.",["title"]="Lieutenant Orrin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"9260:description:1-80","9260:description:82-154","9260:description:161-281","9260:description:283-351","9260:description:353-487","9260:objective:1-133"},["minimumStage"]=2,["questID"]=9260,["sourceHash"]="35bcf6850f576c90da2aa34bc0ee59ef4729d010fb2646bfb89c615c7ad92c4f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-16478",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the glowing runic circles outside investigated, suspecting their shared energy linked them to the undead assault.",["title"]="Lieutenant Orrin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5:description:1-102","5:description:105-166","5:description:171-215","5:description:220-314","5:objective:1-22"},["minimumStage"]=2,["questID"]=5,["sourceHash"]="ca90b596bee2ad106d5f3667c132f6933759382a07760345e0fd61b86fd75eb9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-288",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jitters had spent weeks hiding in a ghost town and surviving on grubs and weeds, desperate enough to pay well for a proper meal.",["title"]="Jitters"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5:description:1-102","5:description:105-166","5:description:171-215","5:description:220-314","5:objective:1-22"},["minimumStage"]=2,["questID"]=5,["sourceHash"]="ca90b596bee2ad106d5f3667c132f6933759382a07760345e0fd61b86fd75eb9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-288",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He had heard of the crab cakes made by Grual in Darkshire and wanted a properly prepared feast brought to him.",["title"]="Jitters"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"7:description:1-40","7:description:43-97","7:description:100-145","7:description:148-218","7:objective:1-54"},["minimumStage"]=2,["questID"]=7,["sourceHash"]="730f34c2bae9f83a3f719c35da6df15614a973a1afc2a3e69a64fdf83351a924"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-197",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="McBride wanted the kobold clan driven from Northshire, beginning by reducing the vermin gathering in the northern woods.",["title"]="Marshal McBride"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"22:description:1-22","22:description:25-45","22:description:48-71","22:description:74-98","22:description:101-125","22:description:128-150","22:description:153-212","22:objective:1-67"},["minimumStage"]=2,["questID"]=22,["sourceHash"]="2df58ccc6dbcf5b0a6e92b0144b53e7c462964d90552120cf4c66a172a590c1b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-235",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Salma’s famous meat pie combined goretusk livers with onions, garlic, rosemary, dill and gravy beneath a prepared crust.",["title"]="Salma Saldean"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"33:description:1-33","33:description:36-72","33:description:75-155","33:description:160-272","33:objective:1-80"},["minimumStage"]=2,["questID"]=33,["sourceHash"]="004b915525b8f48a114b0eec43344ea955c5fc00a39fc96a842b6b73abe446ca"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-196",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Eagan disliked Northshire’s timber wolves but enjoyed their steaks, offering an exchange for tough wolf meat.",["title"]="Eagan Peltskinner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"35:description:1-138","35:description:141-230","35:description:235-254","35:objective:1-52"},["minimumStage"]=2,["questID"]=35,["sourceHash"]="ef045029a938d9921daaae837bfbcc0347c280d6ef5f166c235d7961e180bf2f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-240",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dughan depended on Guard Thomas’s week of observation at eastern Elwynn’s bridge to judge reports of murlocs.",["title"]="Marshal Dughan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"40:description:1-42","40:description:45-143","40:description:148-227","40:description:230-278","40:description:283-359","40:objective:1-69"},["minimumStage"]=2,["questID"]=40,["sourceHash"]="f5295cb5c6126d2c3e426d083a8f5418a5f87b812b8c100ddf3a920406210708"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-240",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gnolls and bandits already occupied the marshal’s attention, leaving Remy unable to convince him that the river creatures required more troops.",["title"]="Marshal Dughan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"36:description:1-59","36:description:62-144","36:description:147-215","36:description:223-252","36:description:255-303","36:description:306-361","36:description:364-418","36:objective:1-82"},["minimumStage"]=2,["questID"]=36,["sourceHash"]="f9abda536f0e38d90ff11e0ebb4a6b2b571df305cbdf9a4f754d0e5b43752d70"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Verna Furlbrow had not expected to leave her farm, but thieves overran the fields and made staying too dangerous.",["title"]="Verna Furlbrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"36:description:1-59","36:description:62-144","36:description:147-215","36:description:223-252","36:description:255-303","36:description:306-361","36:description:364-418","36:objective:1-82"},["minimumStage"]=2,["questID"]=36,["sourceHash"]="f9abda536f0e38d90ff11e0ebb4a6b2b571df305cbdf9a4f754d0e5b43752d70"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-238",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="While her husband repaired their wagon, she asked that her stew recipe be carried to Salma Saldean at the neighboring farm.",["title"]="Verna Furlbrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"35:description:1-138","35:description:141-230","35:description:235-254","35:objective:1-52"},["minimumStage"]=2,["questID"]=35,["sourceHash"]="ef045029a938d9921daaae837bfbcc0347c280d6ef5f166c235d7961e180bf2f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-261",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thomas had been stationed at eastern Elwynn’s bridge for a week, serving as Dughan’s source on the surrounding country.",["title"]="Guard Thomas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"37:description:1-116","37:description:119-180","37:description:185-235","37:description:237-253","37:objective:1-105"},["minimumStage"]=2,["questID"]=37,["sourceHash"]="d0a9dfc56711b6dc547993366dda1b26d0be847b54eab017f9cef74ccdfcd67c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-261",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He could not finish his report until he knew what had happened to Rolf and Malakai, sent upriver days earlier and still missing.",["title"]="Guard Thomas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"40:description:1-42","40:description:45-143","40:description:148-227","40:description:230-278","40:description:283-359","40:objective:1-69"},["minimumStage"]=2,["questID"]=40,["sourceHash"]="f5295cb5c6126d2c3e426d083a8f5418a5f87b812b8c100ddf3a920406210708"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-241",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Remy watched murlocs move upstream in eastern Elwynn, frightening fish and attacking travelers, yet struggled to persuade Dughan that the threat deserved troops.",["title"]="Remy \"Two Times\""},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"60:description:1-27","60:description:30-50","60:description:55-154","60:description:157-172","60:description:177-281","60:description:283-346","60:description:349-401","60:objective:1-53"},["minimumStage"]=2,["questID"]=60,["sourceHash"]="f263351cae6036d2acd50e0d1c530157468e538446f33535e77a9d2ed105ac13"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-253",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="William Pestle ran a Stormwind apothecary with his brother and traveled to gather wax from large candles.",["title"]="William Pestle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"60:description:1-27","60:description:30-50","60:description:55-154","60:description:157-172","60:description:177-281","60:description:283-346","60:description:349-401","60:objective:1-53"},["minimumStage"]=2,["questID"]=60,["sourceHash"]="f263351cae6036d2acd50e0d1c530157468e538446f33535e77a9d2ed105ac13"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-253",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Reports of kobolds in Elwynn’s Fargodeep and Jasperlode mines suggested a ready supply of the candles he needed.",["title"]="William Pestle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"72:description:1-60","72:description:63-108","72:description:111-144","72:description:149-201","72:description:204-265","72:description:268-290","72:description:293-377","72:description:380-409","72:objective:1-52"},["minimumStage"]=2,["questID"]=72,["sourceHash"]="63fa49a013e1eaed1144c50a38ae288366990ab87d7a6e66dea098b70f0608e9"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-297",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Folsom’s father had tended the estate before him and cleaned away the blood left by the massacre.",["title"]="Caretaker Folsom"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"72:description:1-60","72:description:63-108","72:description:111-144","72:description:149-201","72:description:204-265","72:description:268-290","72:description:293-377","72:description:380-409","72:objective:1-52"},["minimumStage"]=2,["questID"]=72,["sourceHash"]="63fa49a013e1eaed1144c50a38ae288366990ab87d7a6e66dea098b70f0608e9"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-297",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="With the Flintridge trust’s last funds exhausted, the family’s remaining possessions faced auction; Folsom blamed the pressure of taxes.",["title"]="Caretaker Folsom"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"83:description:1-127","83:description:132-206","83:description:211-268","83:objective:1-75"},["minimumStage"]=2,["questID"]=83,["sourceHash"]="325119ae782909cdf25c27dd05b5ab695c12d5c8347e0e62d95a67a95679529b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-278",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sara Timberlain fashioned fine goods from the red linen worn by Defias members in Elwynn.",["title"]="Sara Timberlain"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"83:description:1-127","83:description:132-206","83:description:211-268","83:objective:1-75"},["minimumStage"]=2,["questID"]=83,["sourceHash"]="325119ae782909cdf25c27dd05b5ab695c12d5c8347e0e62d95a67a95679529b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-278",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She distinguished their useful linen bandanas from the burlap masks worn by the Northshire gang.",["title"]="Sara Timberlain"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"85:description:1-69","85:description:72-147","85:description:153-218","85:objective:1-25"},["minimumStage"]=2,["questID"]=85,["sourceHash"]="069252413ee8eaa0d4766d1558ddcaaf4e7e38854f6f41748ce8c0e84a7fd31e"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-246",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The widowed Bernice Stonefield suspected Billy Maclure of taking her missing necklace and wanted it recovered.",["title"]="\"Auntie\" Bernice Stonefield"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"86:description:1-61","86:description:64-156","86:description:162-309","86:objective:1-82"},["minimumStage"]=2,["questID"]=86,["sourceHash"]="983d939713bd87453c856439f788ec6681577e59eeba21f3bc4601c9b4f6109a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-247",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Billy offered information about the necklace in exchange for a pie, specifically favoring Bernice’s pork-belly cooking.",["title"]="Billy Maclure"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"86:description:1-61","86:description:64-156","86:description:162-309","86:objective:1-82"},["minimumStage"]=2,["questID"]=86,["sourceHash"]="983d939713bd87453c856439f788ec6681577e59eeba21f3bc4601c9b4f6109a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-247",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He suggested supplying her with boar meat to secure the pie, turning the missing trinket into a bargain between neighboring farms.",["title"]="Billy Maclure"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"90:description:1-42","90:description:45-70","90:description:73-105","90:description:108-178","90:description:181-273","90:description:276-359","90:objective:1-95"},["minimumStage"]=2,["questID"]=90,["sourceHash"]="d54cc8c46f1e53d1c5b5190aa2031878ad4bb46fce8aa4acf90514650f868562"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-272",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grual prepared wolf kabobs, a house favorite, from lean flanks and seasoning herbs.",["title"]="Chef Grual"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"90:description:1-42","90:description:45-70","90:description:73-105","90:description:108-178","90:description:181-273","90:description:276-359","90:objective:1-95"},["minimumStage"]=2,["questID"]=90,["sourceHash"]="d54cc8c46f1e53d1c5b5190aa2031878ad4bb46fce8aa4acf90514650f868562"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-272",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Felicia Gump’s flower shop in Stormwind’s canal district supplied the herbs for his recipe.",["title"]="Chef Grual"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"653:description:1-17","653:description:22-26","653:description:29-38","653:description:41-93","653:description:96-170","653:description:175-256","653:description:261-285","653:description:288-323","653:description:326-386","653:description:391-417","653:description:420-471","653:description:474-504","653:objective:1-62"},["minimumStage"]=2,["questID"]=653,["sourceHash"]="e40e71b98515c10f11a9328a3a199ed58ca75077cb530b38e05854db1a408e2b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2755",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Once the binding loosened, Myzrael intended to hide and gather strength until she could confront the giants who had held her.",["title"]="Myzrael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"656:description:1-53","656:description:56-141","656:description:144-273","656:description:278-293","656:description:298-379","656:description:382-466","656:description:471-509","656:objective:1-55","656:objective:60-127"},["minimumStage"]=2,["questID"]=656,["sourceHash"]="290547ae18787557dd755acc67de4e0d88475744256d71b2e3f3a35e7fff8fbe"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2755",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theldurin warned that the freed princess must be stopped before her growing power let her challenge her former captors.",["title"]="Myzrael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"656:description:1-53","656:description:56-141","656:description:144-273","656:description:278-293","656:description:298-379","656:description:382-466","656:description:471-509","656:objective:1-55","656:objective:60-127","656:completion:1-95","656:completion:97-129","656:completion:134-221","656:completion:223-259","656:completion:261-323"},["minimumStage"]=4,["questID"]=656,["sourceHash"]="290547ae18787557dd755acc67de4e0d88475744256d71b2e3f3a35e7fff8fbe"}},["questSourceProofsMode"]="ALL"},["field"]="outcome",["id"]="catalog-unit-2755",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Binding the recovered eldritch shackles to her shards imprisoned her again; the voice beneath answered with a wail and roar, and the crystals radiated menace instead of reassurance.",["title"]="Myzrael"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"653:description:1-17","653:description:22-26","653:description:29-38","653:description:41-93","653:description:96-170","653:description:175-256","653:description:261-285","653:description:288-323","653:description:326-386","653:description:391-417","653:description:420-471","653:description:474-504","653:objective:1-62"},["minimumStage"]=2,["questID"]=653,["sourceHash"]="e40e71b98515c10f11a9328a3a199ed58ca75077cb530b38e05854db1a408e2b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2786",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gerrig Bonegrip received Myzrael’s allies at his shop in Ironforge’s Forlorn Cavern, declaring that they served a higher cause.",["title"]="Gerrig Bonegrip"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"687:description:1-73","687:description:76-122","687:description:125-183","687:description:186-268","687:description:273-327","687:description:330-369","687:objective:1-24"},["minimumStage"]=2,["questID"]=687,["sourceHash"]="cf62c1d5b7b992220a863525e4a70b8e4e1ae808bd54b74b074d10e8e0db9c4b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2786",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He identified the scroll’s former keeper Theldurin as an ex-member of the Twilight’s Hammer who had fled to the Badlands after rejecting its teachings.",["title"]="Gerrig Bonegrip"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"688:description:1-17","688:description:22-26","688:description:29-38","688:description:41-93","688:description:96-170","688:description:175-256","688:description:261-285","688:description:288-323","688:description:326-385","688:description:390-420","688:description:423-453","688:objective:1-31"},["minimumStage"]=2,["questID"]=688,["sourceHash"]="ccacd476e23076ed5e519fe811bb10ba899b07a17081214bed89684f6ca993b1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2787",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zaruk was Myzrael’s Hammerfall contact for bringing the earth princess back to the surface.",["title"]="Zaruk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"687:description:1-73","687:description:76-122","687:description:125-183","687:description:186-268","687:description:273-327","687:description:330-369","687:objective:1-24"},["minimumStage"]=2,["questID"]=687,["sourceHash"]="cf62c1d5b7b992220a863525e4a70b8e4e1ae808bd54b74b074d10e8e0db9c4b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2787",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The summons depended on recovering the scroll taken by Theldurin when he broke from their order, the Twilight’s Hammer.",["title"]="Zaruk"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"687:description:1-73","687:description:76-122","687:description:125-183","687:description:186-268","687:description:273-327","687:description:330-369","687:objective:1-24"},["minimumStage"]=2,["questID"]=687,["sourceHash"]="cf62c1d5b7b992220a863525e4a70b8e4e1ae808bd54b74b074d10e8e0db9c4b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2785",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Myzrael’s cult allies said Theldurin had once belonged to the Twilight’s Hammer before repudiating its teachings and fleeing with her scroll.",["title"]="Theldurin the Lost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"692:description:1-47","692:description:50-69","692:description:72-157","692:description:162-186","692:description:189-214","692:description:217-286","692:description:289-323","692:description:328-353","692:description:356-431","692:description:436-496","692:objective:1-114"},["minimumStage"]=2,["questID"]=692,["sourceHash"]="d3b3101d8a7a4fa2486ddf1e85a317eba9965c698990292786c532ba2f09b705"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2785",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He feared the scroll could unleash Myzrael upon the world but recognized that it might also be needed to confront her if her release had already begun.",["title"]="Theldurin the Lost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"692:description:1-47","692:description:50-69","692:description:72-157","692:description:162-186","692:description:189-214","692:description:217-286","692:description:289-323","692:description:328-353","692:description:356-431","692:description:436-496","692:objective:1-114","692:completion:1-19","692:completion:21-34","692:completion:36-102","692:completion:107-185"},["minimumStage"]=4,["questID"]=692,["sourceHash"]="d3b3101d8a7a4fa2486ddf1e85a317eba9965c698990292786c532ba2f09b705"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2785",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Theldurin received the fragments stolen and torn by enraged elementals, intending to join them again with his scrap-ratchet.",["title"]="Theldurin the Lost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92:description:1-68","92:description:70-98","92:description:100-175","92:description:177-200","92:description:202-272","92:description:277-390","92:objective:1-132"},["minimumStage"]=2,["questID"]=92,["sourceHash"]="ae69fc807b8cb65f94e69b74f9ec5f57717275022144d74bdd073a87a86c2df7"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-343",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Breanna fed a brigade of Stormwind troops during the recent orc uprising, emptying the supplies she needed for her usual cooking.",["title"]="Chef Breanna"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"92:description:1-68","92:description:70-98","92:description:100-175","92:description:177-200","92:description:202-272","92:description:277-390","92:objective:1-132"},["minimumStage"]=2,["questID"]=92,["sourceHash"]="ae69fc807b8cb65f94e69b74f9ec5f57717275022144d74bdd073a87a86c2df7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-343",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her goulash combined condor meat, great goretusk snouts and crisp spider meat, so replenishing the cupboard meant gathering from several kinds of Redridge wildlife.",["title"]="Chef Breanna"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"106:description:1-15","106:description:18-95","106:description:98-174","106:description:179-228","106:description:231-318","106:objective:1-51"},["minimumStage"]=2,["questID"]=106,["sourceHash"]="fb57860687693d6223cc69493caa74ad26abc32036c2d2cf15eed5b771f2f6f3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-251",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Maybell Maclure loved Tommy Joe Stonefield, but the hostility between their families prevented her from seeing him freely.",["title"]="Maybell Maclure"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"106:description:1-15","106:description:18-95","106:description:98-174","106:description:179-228","106:description:231-318","106:objective:1-51"},["minimumStage"]=2,["questID"]=106,["sourceHash"]="fb57860687693d6223cc69493caa74ad26abc32036c2d2cf15eed5b771f2f6f3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-251",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She entrusted him a letter through a traveler, directing the delivery toward the river west of the Stonefield farm.",["title"]="Maybell Maclure"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"127:description:1-49","127:description:52-104","127:description:109-161","127:description:164-237","127:objective:1-58"},["minimumStage"]=2,["questID"]=127,["sourceHash"]="a938ee35a83a2dd6efd4935085e98bbef276ebba9eea907e836dfad16f9bfe7f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-381",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dockmaster Baren bartered for Lake Everstill’s famous spotted sunfish to replenish a stock that steady demand had depleted.",["title"]="Dockmaster Baren"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"129:description:1-22","129:description:25-212","129:description:217-303","129:description:306-360","129:objective:1-37","129:objective:40-80"},["minimumStage"]=2,["questID"]=129,["sourceHash"]="83ffed488e627b37c6f6aa8d512a2128908afdc36d25c4f8690afcd804c1d41f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-379",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Darcy prepared lunch for Guard Parker but feared the dangers along his patrol, offering a meal to someone willing to deliver it.",["title"]="Darcy"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"129:description:1-22","129:description:25-212","129:description:217-303","129:description:306-360","129:objective:1-37","129:objective:40-80"},["minimumStage"]=2,["questID"]=129,["sourceHash"]="83ffed488e627b37c6f6aa8d512a2128908afdc36d25c4f8690afcd804c1d41f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-379",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Parker’s road led toward Duskwood, country Darcy considered too hazardous for an ordinary townsperson.",["title"]="Darcy"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"129:description:1-22","129:description:25-212","129:description:217-303","129:description:306-360","129:objective:1-37","129:objective:40-80"},["minimumStage"]=2,["questID"]=129,["sourceHash"]="83ffed488e627b37c6f6aa8d512a2128908afdc36d25c4f8690afcd804c1d41f"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-464",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Darcy described Parker as a big, strong Stormwind guard able to defend himself on patrol.",["title"]="Guard Parker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"130:description:1-67","130:description:70-151","130:description:156-261","130:objective:1-51"},["minimumStage"]=2,["questID"]=130,["sourceHash"]="801b86e17b95b0a0429985cf52bdb4336cae6fee04d2c06567f8364f6a718c40"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-464",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted flowers brought back to Darcy but asked that Martie the herbalist be told neither the sender nor the intended recipient.",["title"]="Guard Parker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"132:description:1-50","132:description:53-91","132:description:94-185","132:description:190-219","132:description:222-266","132:objective:1-51"},["minimumStage"]=2,["questID"]=132,["sourceHash"]="a4d6117477875fad140f6b8e0ff247e16ba77a801e21fa507d5f13ba22ef4951"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wiley the Black held information on Defias plans that he believed could cost him his life if disclosed.",["title"]="Wiley the Black"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"132:description:1-50","132:description:53-91","132:description:94-185","132:description:190-219","132:description:222-266","132:objective:1-51"},["minimumStage"]=2,["questID"]=132,["sourceHash"]="a4d6117477875fad140f6b8e0ff247e16ba77a801e21fa507d5f13ba22ef4951"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-266",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He had heard the gang was working with gnolls, kobolds and goblins, and entrusted the details to a note for Stoutmantle.",["title"]="Wiley the Black"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"153:description:1-40","153:description:43-102","153:description:105-220","153:description:225-290","153:objective:1-64"},["minimumStage"]=2,["questID"]=153,["sourceHash"]="e2c9dfd77bbd55ecf663de20373d7345516d68311da76a37c5b26d789b18080e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-878",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Scout Galiaan tracked the Defias’ shifting positions over a long period.",["title"]="Scout Galiaan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"153:description:1-40","153:description:43-102","153:description:105-220","153:description:225-290","153:objective:1-64"},["minimumStage"]=2,["questID"]=153,["sourceHash"]="e2c9dfd77bbd55ecf663de20373d7345516d68311da76a37c5b26d789b18080e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-878",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The red leather bandanas worn by many members gave the scout an identifying sign by which to follow the gang’s movement.",["title"]="Scout Galiaan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"155:description:1-57","155:description:60-83","155:description:86-115","155:description:121-145","155:description:148-205","155:description:208-242","155:description:245-278","155:description:281-328","155:description:333-402","155:objective:1-74","155:objective:77-202"},["minimumStage"]=2,["questID"]=155,["sourceHash"]="6a857e62b6f36f4f150eb902dd3217fd4bf0e287daf57a7e3ef5ccfde3ffa21a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-467",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Defias defector expected his former companions to kill him if they saw him guiding an outsider.",["title"]="The Defias Traitor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"155:description:1-57","155:description:60-83","155:description:86-115","155:description:121-145","155:description:148-205","155:description:208-242","155:description:245-278","155:description:281-328","155:description:333-402","155:objective:1-74","155:objective:77-202"},["minimumStage"]=2,["questID"]=155,["sourceHash"]="6a857e62b6f36f4f150eb902dd3217fd4bf0e287daf57a7e3ef5ccfde3ffa21a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-467",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered the route to their hideout in exchange for close protection, urging the escort to bring friends before setting out.",["title"]="The Defias Traitor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"174:description:1-104","174:description:107-194","174:description:199-251","174:description:254-306","174:objective:1-71"},["minimumStage"]=2,["questID"]=174,["sourceHash"]="202ca4c9bed82859626791e012ed660326457bcbd7e73bd0d35f1b28ae88ca2a"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-276",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Viktori Prism’Antras sought an explanation beyond magic for the forest’s strange transformation and wanted an instrument that could peer toward the stars.",["title"]="Viktori Prism'Antras"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"174:description:1-104","174:description:107-194","174:description:199-251","174:description:254-306","174:objective:1-71"},["minimumStage"]=2,["questID"]=174,["sourceHash"]="202ca4c9bed82859626791e012ed660326457bcbd7e73bd0d35f1b28ae88ca2a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-276",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His gnomish friend Cog supplied the design, beginning with a bronze tube to be made by a skilled engineer.",["title"]="Viktori Prism'Antras"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"183:description:1-39","183:description:44-135","183:description:137-165","183:description:167-211","183:description:213-324","183:description:329-413","183:objective:1-57"},["minimumStage"]=2,["questID"]=183,["sourceHash"]="52b1a6eaab73854bb76cda1fd6bd39697a160975a8e41ffe48b8763a43f8893d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-714",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Talin Keeneye enjoyed boar hunting, but Coldridge’s growing numbers of angry boars had made his daily pursuit dangerous.",["title"]="Talin Keeneye"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"210:description:1-37","210:description:40-148","210:description:151-170","210:description:173-217","210:description:222-285","210:description:288-306","210:objective:1-46"},["minimumStage"]=2,["questID"]=210,["sourceHash"]="26504aa9771b68723781987106ec0440a4e85d60720e14ea2b9307f1dd234da6"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-770",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Corporal Kaleb did most of the cooking for his camp, once easing the work with a mechanical pot bought from Krazek in Booty Bay.",["title"]="Corporal Kaleb"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"210:description:1-37","210:description:40-148","210:description:151-170","210:description:173-217","210:description:222-285","210:description:288-306","210:objective:1-46"},["minimumStage"]=2,["questID"]=210,["sourceHash"]="26504aa9771b68723781987106ec0440a4e85d60720e14ea2b9307f1dd234da6"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-770",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The time-saving pot broke, leaving Kaleb to seek a messenger who could take it back to its maker for repair.",["title"]="Corporal Kaleb"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"219:description:1-33","219:description:38-44","219:description:46-54","219:description:60-126","219:description:129-153","219:description:155-213","219:description:215-249","219:description:252-276","219:description:281-318","219:description:320-328","219:description:330-351","219:objective:1-57"},["minimumStage"]=2,["questID"]=219,["sourceHash"]="fc810b6cdaae526e0dd59d5bfdf655d5e267752ca86fb46c36e60f36c10090ed"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-349",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keeshan recalled orcs overrunning his regiment and killing most of its men before a head wound left him unconscious.",["title"]="Corporal Keeshan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"219:description:1-33","219:description:38-44","219:description:46-54","219:description:60-126","219:description:129-153","219:description:155-213","219:description:215-249","219:description:252-276","219:description:281-318","219:description:320-328","219:description:330-351","219:objective:1-57"},["minimumStage"]=2,["questID"]=219,["sourceHash"]="fc810b6cdaae526e0dd59d5bfdf655d5e267752ca86fb46c36e60f36c10090ed"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-349",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Badly hurt and held in a cave, he needed help to make the journey back to town rather than attempt escape alone.",["title"]="Corporal Keeshan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"227:description:1-72","227:description:77-165","227:description:167-176","227:description:178-194","227:objective:1-51"},["minimumStage"]=2,["questID"]=227,["sourceHash"]="f31c7b445225551cbfb2612859b6ceff48da25c9da3d000ddf66f0b86060c577"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-268",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sirra Von’Indi kept a leatherbound account of Morgan Ladimore and directed inquiries about the recent trouble to Althea.",["title"]="Sirra Von'Indi"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"229:description:1-38","229:description:43-62","229:description:67-180","229:description:182-217","229:description:219-234","229:description:236-266","229:description:268-313","229:objective:1-47"},["minimumStage"]=2,["questID"]=229,["sourceHash"]="7943ba146402eaf4fcea327fb6d1bcc337ca6b9ceb6add4159e6c2bfe12fd806"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-576",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sarah Ladimore survived the loss of her family and became a Watcher, although Morgan had believed them all dead.",["title"]="Watcher Ladimore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"231:description:1-40","231:description:42-49","231:description:51-144","231:description:149-256","231:description:261-266","231:description:268-281","231:objective:1-54"},["minimumStage"]=2,["questID"]=231,["sourceHash"]="5a0c561138a012847a1eff664be32c197aceb409bba984be30b99bdad9eb3ba9"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-576",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted her ring placed at her father’s grave as reassurance that she was safe and did not blame him for what had happened.",["title"]="Watcher Ladimore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"231:description:1-40","231:description:42-49","231:description:51-144","231:description:149-256","231:description:261-266","231:description:268-281","231:objective:1-54","231:completion:1-39","231:completion:44-54","231:completion:56-61","231:completion:63-92","231:completion:94-135","231:completion:144-166","231:completion:168-221","231:completion:223-348","231:completion:353-367"},["minimumStage"]=4,["questID"]=231,["sourceHash"]="5a0c561138a012847a1eff664be32c197aceb409bba984be30b99bdad9eb3ba9"}},["questSourceProofsMode"]="ALL"},["field"]="outcome",["id"]="catalog-unit-576",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The voice at Morgan’s grave recognized Sarah’s ring as a sign she lived, answering her gesture with relief from the burden that had held him.",["title"]="Watcher Ladimore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"309:description:1-16","309:description:21-66","309:description:68-202","309:description:207-251","309:objective:1-93"},["minimumStage"]=2,["questID"]=309,["sourceHash"]="1c2860301e99523b992389705070ac4654761a12c6d22150c2f7ea0d0c5335fc"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1379",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Miran carried a heavy load of blasting powder for Ironband’s expedition.",["title"]="Miran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"309:description:1-16","309:description:21-66","309:description:68-202","309:description:207-251","309:objective:1-93"},["minimumStage"]=2,["questID"]=309,["sourceHash"]="1c2860301e99523b992389705070ac4654761a12c6d22150c2f7ea0d0c5335fc"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1379",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dangerous roads and uncertainty about further Dark Iron interference made an escort a welcome safeguard for the delivery.",["title"]="Miran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"332:description:1-92","332:description:95-172","332:description:177-201","332:description:204-297","332:description:300-319","332:objective:1-94"},["minimumStage"]=2,["questID"]=332,["sourceHash"]="c8a8de27058dc1c48b17838f0754692fc355f87456df4e497cb3b312d084a408"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1432",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Renato Gallina advertised his family’s wine shop along the Trade District canals in Stormwind.",["title"]="Renato Gallina"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"332:description:1-92","332:description:95-172","332:description:177-201","332:description:204-297","332:description:300-319","332:objective:1-94"},["minimumStage"]=2,["questID"]=332,["sourceHash"]="c8a8de27058dc1c48b17838f0754692fc355f87456df4e497cb3b312d084a408"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1432",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His pamphlet directed new customers to his sister Suzetta for a complimentary bottle of the family’s pinot noir.",["title"]="Renato Gallina"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"333:description:1-42","333:description:45-102","333:description:105-157","333:description:162-190","333:description:193-259","333:description:262-299","333:description:304-405","333:objective:1-90"},["minimumStage"]=2,["questID"]=333,["sourceHash"]="dafc113202ecc35c7f0b783e0af828d2b3de8f8cb0b521ca3e56cc258616e1a5"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1427",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Harlan Bagley sold armor and sturdy clothing, with rising demand leaving his knitted stock short.",["title"]="Harlan Bagley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"333:description:1-42","333:description:45-102","333:description:105-157","333:description:162-190","333:description:193-259","333:description:262-299","333:description:304-405","333:objective:1-90"},["minimumStage"]=2,["questID"]=333,["sourceHash"]="dafc113202ecc35c7f0b783e0af828d2b3de8f8cb0b521ca3e56cc258616e1a5"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1427",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rema Schneider at the Canal Tailor and Fit Shop supplied the replacement clothing he needed.",["title"]="Harlan Bagley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"348:description:1-29","348:description:34-93","348:description:98-190","348:description:195-251","348:description:256-305","348:description:310-337","348:objective:1-66","348:objective:68-108"},["minimumStage"]=2,["questID"]=348,["sourceHash"]="b7350e1269aa76d097e09fca669271a6392ca41b02fdc6082ce5544554e62fb3"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2486",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fin Fizracket suffered a severe fever he called Stranglethorn Fever, struggling to explain what he believed would save him.",["title"]="Fin Fizracket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"348:description:1-29","348:description:34-93","348:description:98-190","348:description:195-251","348:description:256-305","348:description:310-337","348:objective:1-66","348:objective:68-108"},["minimumStage"]=2,["questID"]=348,["sourceHash"]="b7350e1269aa76d097e09fca669271a6392ca41b02fdc6082ce5544554e62fb3"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2486",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought Mokk the Savage’s heart as the supposed only cure and named Unbagwa as the witchdoctor able to summon the elusive white beast.",["title"]="Fin Fizracket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"420:description:1-123","420:description:125-186","420:description:191-201","420:description:203-267","420:description:272-407","420:objective:1-56"},["minimumStage"]=2,["questID"]=420,["sourceHash"]="fd09431d23c851a6dabe92794de646019bce802cacf89e86fe42427a65ab1d6c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1965",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mountaineer Thalos warned travelers that the tunnel toward Kharanos was infested with hostile troggs.",["title"]="Mountaineer Thalos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"420:description:1-123","420:description:125-186","420:description:191-201","420:description:203-267","420:description:272-407","420:objective:1-56"},["minimumStage"]=2,["questID"]=420,["sourceHash"]="fd09431d23c851a6dabe92794de646019bce802cacf89e86fe42427a65ab1d6c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1965",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He advised those bound for Senir to keep following the road after emerging from the passage.",["title"]="Mountaineer Thalos"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"435:description:1-92","435:description:95-151","435:description:156-217","435:description:220-275","435:description:280-296","435:description:299-404","435:objective:1-49"},["minimumStage"]=2,["questID"]=435,["sourceHash"]="7d345c5af1c12d06519f2c7792ecd8c15a2c251c40d3c4681b861d40d58e5078"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1978",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hungry wolves kept Erland from safely leaving the building to report to his Deathstalker teammate Rane Yorick.",["title"]="Deathstalker Erland"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"435:description:1-92","435:description:95-151","435:description:156-217","435:description:220-275","435:description:280-296","435:description:299-404","435:objective:1-49"},["minimumStage"]=2,["questID"]=435,["sourceHash"]="7d345c5af1c12d06519f2c7792ecd8c15a2c251c40d3c4681b861d40d58e5078"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-1978",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He asked for close escort and suggested companions, judging the number of wolves too great for an easy journey alone.",["title"]="Deathstalker Erland"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"454:description:1-78","454:description:80-88","454:description:90-187","454:description:192-264","454:description:266-332","454:objective:1-17"},["minimumStage"]=2,["questID"]=454,["sourceHash"]="29334d5a2639805be02a39ea098adfd6b0fc54de6905e8569227e576571f45a5"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2057",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Huldar and Miran divided a powder shipment between them, with Miran hauling barrels while Huldar watched the remainder.",["title"]="Huldar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"454:description:1-78","454:description:80-88","454:description:90-187","454:description:192-264","454:description:266-332","454:objective:1-17"},["minimumStage"]=2,["questID"]=454,["sourceHash"]="29334d5a2639805be02a39ea098adfd6b0fc54de6905e8569227e576571f45a5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2057",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Unwilling to let Miran carry the next load without protection, Huldar sought someone to accompany the trip.",["title"]="Huldar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"530:description:1-53","530:description:56-115","530:description:118-191","530:description:196-303","530:objective:1-19","530:objective:24-75"},["minimumStage"]=2,["questID"]=530,["sourceHash"]="f6d8915a92bf7c6908933d54f3820497430ed2c09981b66e6e59fadc686ffa21"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2050",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Raleigh Andrean named his former friend Valdred as his wife’s killer.",["title"]="Raleigh Andrean"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"530:description:1-53","530:description:56-115","530:description:118-191","530:description:196-303","530:objective:1-19","530:objective:24-75"},["minimumStage"]=2,["questID"]=530,["sourceHash"]="f6d8915a92bf7c6908933d54f3820497430ed2c09981b66e6e59fadc686ffa21"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2050",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Though he said he could no longer grieve, he still wanted vengeance and requested Valdred’s hands as proof.",["title"]="Raleigh Andrean"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"535:description:1-8","535:description:10-57","535:description:62-207","535:objective:1-63"},["minimumStage"]=2,["questID"]=535,["sourceHash"]="c15b504ed9ca7989298ddcbd815ac7978879b388dac2ca8600c096e7c43cd0b3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2333",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Injured and expecting an enemy to kill him, Valik offered the desired information in exchange for Southshore stout.",["title"]="Henchman Valik"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"536:description:1-110","536:description:112-145","536:description:150-178","536:description:180-216","536:description:226-330","536:description:332-400","536:objective:1-98"},["minimumStage"]=2,["questID"]=536,["sourceHash"]="02b2af555f5ea0ab988e95d8533a08fd46e9c35f7c9f0c6b368153ee3c80b6de"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-2228",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Farren Orinelle had been transferred from Stormwind’s city guard to Southshore, a posting he bitterly disliked.",["title"]="Lieutenant Farren Orinelle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"536:description:1-110","536:description:112-145","536:description:150-178","536:description:180-216","536:description:226-330","536:description:332-400","536:objective:1-98"},["minimumStage"]=2,["questID"]=536,["sourceHash"]="02b2af555f5ea0ab988e95d8533a08fd46e9c35f7c9f0c6b368153ee3c80b6de"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2228",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Redpath’s order to confront the Western Strand’s murlocs met little enthusiasm, leading the lieutenant to seek a substitute for the work.",["title"]="Lieutenant Farren Orinelle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"557:description:1-148","557:description:151-242","557:description:247-359","557:objective:1-68"},["minimumStage"]=2,["questID"]=557,["sourceHash"]="56c3f57dff3e6e7bbfaeeba9d509e48880a740751077466fd8b603da4d026bef"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2437",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bel’varil explained that bracers on Dalaran’s elementals bound them to a mage’s service, pairing them with the stone tokens already under study.",["title"]="Keeper Bel'varil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"557:description:1-148","557:description:151-242","557:description:247-359","557:objective:1-68"},["minimumStage"]=2,["questID"]=557,["sourceHash"]="56c3f57dff3e6e7bbfaeeba9d509e48880a740751077466fd8b603da4d026bef"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2437",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted examples gathered from the ruined city’s elementals before the Magus asked for them.",["title"]="Keeper Bel'varil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"599:description:1-18","599:description:21-94","599:description:97-131","599:description:134-188","599:description:193-222","599:description:225-285","599:description:288-331","599:objective:1-60"},["minimumStage"]=2,["questID"]=599,["sourceHash"]="92230b405d926e91e63fa5a9e0ff6975b3d23265ebebcaf0873e989c2f8b108e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2490",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="First Mate Crazz defended the Blackwater Raiders’ control of Booty Bay against the Bloodsail’s ambitions.",["title"]="First Mate Crazz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"599:description:1-18","599:description:21-94","599:description:97-131","599:description:134-188","599:description:193-222","599:description:225-285","599:description:288-331","599:objective:1-60"},["minimumStage"]=2,["questID"]=599,["sourceHash"]="92230b405d926e91e63fa5a9e0ff6975b3d23265ebebcaf0873e989c2f8b108e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2490",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="News of a planned attack alarmed him enough to send the report immediately to Fleet Master Seahorn.",["title"]="First Mate Crazz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"607:description:1-46","607:description:49-85","607:description:88-96","607:description:101-173","607:description:176-222","607:objective:1-46"},["minimumStage"]=2,["questID"]=607,["sourceHash"]="bd446ff6fd338e64c21f7de90d77c936edec8b2b900e4a1e75cd6db98feb88f4"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-2502",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="“Shaky” Phillipe owed Sea Wolf MacKinley money and insisted that drunken confusion, not an intention to avoid repayment, had delayed him.",["title"]="\"Shaky\" Phillipe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"607:description:1-46","607:description:49-85","607:description:88-96","607:description:101-173","607:description:176-222","607:objective:1-46"},["minimumStage"]=2,["questID"]=607,["sourceHash"]="bd446ff6fd338e64c21f7de90d77c936edec8b2b900e4a1e75cd6db98feb88f4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2502",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent a pouch back with an appeal that the creditor understand and refrain from rough treatment.",["title"]="\"Shaky\" Phillipe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"761:description:1-60","761:description:63-147","761:description:152-233","761:description:238-289","761:description:294-424","761:objective:1-69"},["minimumStage"]=2,["questID"]=761,["sourceHash"]="3af1e4fd9644e89ac0120d0ba846e86b75525bdd48db7d26b244097579c1c1f8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2947",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Harken regarded swoop quills as a hunter’s badge of cleverness and determination, since the cunning birds were difficult to spot and catch.",["title"]="Harken Windtotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"761:description:1-60","761:description:63-147","761:description:152-233","761:description:238-289","761:description:294-424","761:objective:1-69"},["minimumStage"]=2,["questID"]=761,["sourceHash"]="3af1e4fd9644e89ac0120d0ba846e86b75525bdd48db7d26b244097579c1c1f8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-2947",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His hunt challenged a willing helper to earn honor for the clan through skill on Mulgore’s plains.",["title"]="Harken Windtotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"761:description:1-60","761:description:63-147","761:description:152-233","761:description:238-289","761:description:294-424","761:objective:1-69"},["minimumStage"]=2,["questID"]=761,["sourceHash"]="3af1e4fd9644e89ac0120d0ba846e86b75525bdd48db7d26b244097579c1c1f8"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-2970",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Swoops ranged across Mulgore’s plains, where hunters needed sharp eyes and speed to find them.",["title"]="Swoop"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"761:description:1-60","761:description:63-147","761:description:152-233","761:description:238-289","761:description:294-424","761:objective:1-69"},["minimumStage"]=2,["questID"]=761,["sourceHash"]="3af1e4fd9644e89ac0120d0ba846e86b75525bdd48db7d26b244097579c1c1f8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2970",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Their quills carried ceremonial meaning as evidence of a hunter’s cleverness and determination in Harken’s trial.",["title"]="Swoop"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"768:description:1-21","768:description:24-121","768:description:124-156","768:description:161-264","768:description:269-351","768:objective:1-71"},["minimumStage"]=2,["questID"]=768,["sourceHash"]="8c26ed9e4261e9fb37835467e8ccaa6be04b1de109064ff7af997c6c5c7ac0b1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3050",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Veren Tallstrider fashioned beast hides into clothing and armor for Thunder Bluff’s people.",["title"]="Veren Tallstrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"768:description:1-21","768:description:24-121","768:description:124-156","768:description:161-264","768:description:269-351","768:objective:1-71"},["minimumStage"]=2,["questID"]=768,["sourceHash"]="8c26ed9e4261e9fb37835467e8ccaa6be04b1de109064ff7af997c6c5c7ac0b1"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3050",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered his craft in return for the hunter’s skins, joining service to the city with the honor of the plains hunt.",["title"]="Veren Tallstrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"775:description:1-46","775:description:48-121","775:description:126-242","775:objective:1-45"},["minimumStage"]=2,["questID"]=775,["sourceHash"]="dca6e9993c73d20217a2c1450e34df2654d3d2169735e0ca63839ca47e471ad7"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2994",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The ancestral spirit recognized completion of the Earthmother’s rites and directed the honored traveler to Cairne atop Thunder Bluff’s highest mesa.",["title"]="Ancestral Spirit"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"813:description:1-57","813:description:59-195","813:description:200-328","813:description:333-347","813:description:349-379","813:objective:1-55"},["minimumStage"]=2,["questID"]=813,["sourceHash"]="7b64baa1f5e8c9f2ad56fc0646ea427e0863852e60f0ad5c789daaec0f63f92e"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3189",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kor’ghan could prepare an antidote from the poison sacs of the venomtails near Orgrimmar’s entrance.",["title"]="Kor'ghan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"813:description:1-57","813:description:59-195","813:description:200-328","813:description:333-347","813:description:349-379","813:objective:1-55"},["minimumStage"]=2,["questID"]=813,["sourceHash"]="7b64baa1f5e8c9f2ad56fc0646ea427e0863852e60f0ad5c789daaec0f63f92e"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3189",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rhinag’s reckless hunt left him in urgent need; Kor’ghan set criticism aside to seek the ingredients that could save one of their own.",["title"]="Kor'ghan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"840:description:1-28","840:description:33-103","840:description:105-153","840:description:155-180","840:description:185-248","840:objective:1-69","840:objective:74-115","840:objective:120-189"},["minimumStage"]=2,["questID"]=840,["sourceHash"]="2c3d8c00d4f11155299b0224d5aa6328d057d765a672824d39871be2310e07ed"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3336",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Takrin Pathseeker sought strong recruits for the Barrens at the request of his friend Kargal.",["title"]="Takrin Pathseeker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"840:description:1-28","840:description:33-103","840:description:105-153","840:description:155-180","840:description:185-248","840:objective:1-69","840:objective:74-115","840:objective:120-189"},["minimumStage"]=2,["questID"]=840,["sourceHash"]="2c3d8c00d4f11155299b0224d5aa6328d057d765a672824d39871be2310e07ed"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3336",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent willing volunteers onward with a recruitment letter, framing the duty as service to the Horde.",["title"]="Takrin Pathseeker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"842:description:1-54","842:description:59-111","842:description:113-207","842:description:209-273","842:description:278-324","842:objective:1-56","842:objective:61-119","842:objective:125-193"},["minimumStage"]=2,["questID"]=842,["sourceHash"]="5846bb3fdf69a8852535730f1b978d8caaedf61b0f8e0aa99ec8a42921ea3d8b"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3337",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kargal Battlescar signed recruitment letters for Barrens duty and passed recruits toward Sergra Darkthorn at the Crossroads.",["title"]="Kargal Battlescar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"842:description:1-54","842:description:59-111","842:description:113-207","842:description:209-273","842:description:278-324","842:objective:1-56","842:objective:61-119","842:objective:125-193"},["minimumStage"]=2,["questID"]=842,["sourceHash"]="5846bb3fdf69a8852535730f1b978d8caaedf61b0f8e0aa99ec8a42921ea3d8b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3337",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He openly distrusted Sergra’s methods despite Thrall’s confidence in her, warning newcomers to form their own judgment.",["title"]="Kargal Battlescar"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"862:description:1-61","862:description:63-92","862:description:97-139","862:description:141-165","862:description:170-253","862:description:255-323","862:description:328-415","862:description:417-420","862:objective:1-48"},["minimumStage"]=2,["questID"]=862,["sourceHash"]="84febf3acd6ecb72c306cd929297b607420c86540f5f0845e764c5672cf87daa"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3443",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grub offered travelers a stew made from dig rats gathered around Bael Modan.",["title"]="Grub"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"862:description:1-61","862:description:63-92","862:description:97-139","862:description:141-165","862:description:170-253","862:description:255-323","862:description:328-415","862:description:417-420","862:objective:1-48"},["minimumStage"]=2,["questID"]=862,["sourceHash"]="84febf3acd6ecb72c306cd929297b607420c86540f5f0845e764c5672cf87daa"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3443",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hunger and a joke about every seasoned traveler’s time killing rats accompanied his request for the unlikely meal.",["title"]="Grub"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"873:description:1-44","873:description:47-90","873:description:93-167","873:description:172-193","873:description:196-220","873:description:223-267","873:description:272-343","873:description:348-421","873:objective:1-47"},["minimumStage"]=2,["questID"]=873,["sourceHash"]="d4f43c346e57958f4dd550602beb02ce8a02467ff63dfa445c0e097eae0cccf6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3388",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mahren Skyseer considered Isha Awak a worthy, honorable challenge, grateful for the great creature even while coastal humans feared it.",["title"]="Mahren Skyseer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"873:description:1-44","873:description:47-90","873:description:93-167","873:description:172-193","873:description:196-220","873:description:223-267","873:description:272-343","873:description:348-421","873:objective:1-47"},["minimumStage"]=2,["questID"]=873,["sourceHash"]="d4f43c346e57958f4dd550602beb02ce8a02467ff63dfa445c0e097eae0cccf6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3388",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He spoke of the creature’s heart as the dwelling place of its spirit and set the hunt as a meeting with strength and fate.",["title"]="Mahren Skyseer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"938:description:1-85","938:description:87-194","938:description:199-277","938:description:279-310","938:objective:1-81"},["minimumStage"]=2,["questID"]=938,["sourceHash"]="65a8ce0af67473cccf233ff7af617d376abd2fe0770a88b9ce1c20186b3b46bf"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-3568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mist was a gray-furred sabercat whose coat blended with the forest and whose bright blue eyes showed alert intelligence.",["title"]="Mist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"938:description:1-85","938:description:87-194","938:description:199-277","938:description:279-310","938:objective:1-81"},["minimumStage"]=2,["questID"]=938,["sourceHash"]="65a8ce0af67473cccf233ff7af617d376abd2fe0770a88b9ce1c20186b3b46bf"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The cat lay badly wounded, with deep cuts across her back and stomach.",["title"]="Mist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"938:description:1-85","938:description:87-194","938:description:199-277","938:description:279-310","938:objective:1-81"},["minimumStage"]=2,["questID"]=938,["sourceHash"]="65a8ce0af67473cccf233ff7af617d376abd2fe0770a88b9ce1c20186b3b46bf"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3568",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Despite the injuries, her lifted head and attentive gaze suggested that she wished to follow a potential helper.",["title"]="Mist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"945:description:1-5","945:description:10-92","945:description:95-120","945:description:125-152","945:description:155-219","945:description:222-279","945:objective:1-91"},["minimumStage"]=2,["questID"]=945,["sourceHash"]="4fa2e99763e993957e30829b749b9429e9d5ef050207b181fc07e764e37d4db7"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-3584",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cultists surrounded Therylune while she wandered near the Master’s Glaive, leaving her dependent on hiding until help arrived.",["title"]="Therylune"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"945:description:1-5","945:description:10-92","945:description:95-120","945:description:125-152","945:description:155-219","945:description:222-279","945:objective:1-91"},["minimumStage"]=2,["questID"]=945,["sourceHash"]="4fa2e99763e993957e30829b749b9429e9d5ef050207b181fc07e764e37d4db7"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3584",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wanted her sister Therysil at Ashenvale’s Shrine of Aessina informed that she was safe.",["title"]="Therylune"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"965:description:1-15","965:description:17-91","965:description:96-218","965:description:223-267","965:description:269-337","965:description:339-419","965:objective:1-68"},["minimumStage"]=2,["questID"]=965,["sourceHash"]="76b58f61c2e90e6eff409d165ab96c84319ca61459248d7157bd431879854711"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3657",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sentinel Elissa Starbreeze was charged with Auberdine’s protection and sent Balthule Shadowstrike to investigate the Tower of Althalaxx.",["title"]="Sentinel Elissa Starbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"965:description:1-15","965:description:17-91","965:description:96-218","965:description:223-267","965:description:269-337","965:description:339-419","965:objective:1-68"},["minimumStage"]=2,["questID"]=965,["sourceHash"]="76b58f61c2e90e6eff409d165ab96c84319ca61459248d7157bd431879854711"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3657",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His overdue return worried her, prompting a request that someone find out whether danger in the forest had stopped him.",["title"]="Sentinel Elissa Starbreeze"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"976:description:1-126","976:description:128-256","976:description:261-320","976:description:322-407","976:objective:1-101"},["minimumStage"]=2,["questID"]=976,["sourceHash"]="b09b9dc1945bebae45715428817aeb891cf95d14d2ae148ca9bc0e3049e62139"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4484",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Feero Ironhand was entrusted by Delgren with messages and supplies for Starbreeze in Auberdine.",["title"]="Feero Ironhand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"976:description:1-126","976:description:128-256","976:description:261-320","976:description:322-407","976:objective:1-101"},["minimumStage"]=2,["questID"]=976,["sourceHash"]="b09b9dc1945bebae45715428817aeb891cf95d14d2ae148ca9bc0e3049e62139"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4484",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He hesitated to travel without guards because enemies in the forest might seize both the goods and the information.",["title"]="Feero Ironhand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"990:description:1-88","990:description:90-181","990:description:186-306","990:objective:1-35"},["minimumStage"]=2,["questID"]=990,["sourceHash"]="2a3d5d086d83f57cd966c91eb71bc8f912298f98de7df2a876261710b147f272"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3694",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sentinel Selarin served Raene Wolfrunner and directed helpers south toward her in Astranaar.",["title"]="Sentinel Selarin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"990:description:1-88","990:description:90-181","990:description:186-306","990:objective:1-35"},["minimumStage"]=2,["questID"]=990,["sourceHash"]="2a3d5d086d83f57cd966c91eb71bc8f912298f98de7df2a876261710b147f272"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3694",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Selarin hoped their assistance could ease the corruption spreading through Ashenvale.",["title"]="Sentinel Selarin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"994:description:1-27","994:description:29-74","994:description:76-144","994:description:146-174","994:description:179-295","994:objective:1-78"},["minimumStage"]=2,["questID"]=994,["sourceHash"]="a9311caf839a3ca656ce55530704e0ad3666846a4b4bbd4a10bd15c6d90c960f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3692",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Volcor’s forceful escape plan was to fight down to the road where Grimclaw should be waiting, then part from the escort.",["title"]="Volcor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"994:description:1-27","994:description:29-74","994:description:76-144","994:description:146-174","994:description:179-295","994:objective:1-78"},["minimumStage"]=2,["questID"]=994,["sourceHash"]="a9311caf839a3ca656ce55530704e0ad3666846a4b4bbd4a10bd15c6d90c960f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3692",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted Terenthis in Auberdine to hear the escort’s account once the escape was over.",["title"]="Volcor"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1023:description:1-95","1023:description:100-152","1023:description:157-218","1023:description:220-256","1023:description:258-287","1023:objective:1-87"},["minimumStage"]=2,["questID"]=1023,["sourceHash"]="7f27fbb3b1d32b0ec56775fc8c2849f7a85b0d6bcdfe2cc1bcba82bf1f72fd4a"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-3891",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Teronis died while searching for the gem Raene needed, leaving an intact journal among his belongings.",["title"]="Teronis' Corpse"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1023:description:1-95","1023:description:100-152","1023:description:157-218","1023:description:220-256","1023:description:258-287","1023:objective:1-87"},["minimumStage"]=2,["questID"]=1023,["sourceHash"]="7f27fbb3b1d32b0ec56775fc8c2849f7a85b0d6bcdfe2cc1bcba82bf1f72fd4a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3891",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The search remained unfinished at his body, with nearby murlocs considered possible holders of the missing gem.",["title"]="Teronis' Corpse"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1036:description:7-30","1036:description:33-114","1036:description:117-221","1036:description:226-310","1036:description:313-402","1036:objective:1-93"},["minimumStage"]=2,["questID"]=1036,["sourceHash"]="350752ec2257563a6255f60e72d4d76be36f8aa2467e58ec57ebef127632eb6d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2545",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="“Pretty Boy” Duncan directed enemies of Booty Bay toward a special mission with the Bloodsail Buccaneers.",["title"]="\"Pretty Boy\" Duncan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1036:description:7-30","1036:description:33-114","1036:description:117-221","1036:description:226-310","1036:description:313-402","1036:objective:1-93"},["minimumStage"]=2,["questID"]=1036,["sourceHash"]="350752ec2257563a6255f60e72d4d76be36f8aa2467e58ec57ebef127632eb6d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-2545",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent recruits to Fleet Master Firallon below decks on the Crimson Veil, anchored alongside the other Bloodsail ships.",["title"]="\"Pretty Boy\" Duncan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1133:description:1-84","1133:description:86-101","1133:description:104-184","1133:description:187-241","1133:description:246-286","1133:description:289-317","1133:objective:1-44"},["minimumStage"]=2,["questID"]=1133,["sourceHash"]="b126961cc764a2dd0e875436b0b669741c24bce88086dea4e3e20f360124f2da"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4456",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fiora Longears directed newly arrived Alliance adventurers toward Astranaar and Shindrell Swiftfire.",["title"]="Fiora Longears"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1133:description:1-84","1133:description:86-101","1133:description:104-184","1133:description:187-241","1133:description:246-286","1133:description:289-317","1133:objective:1-44"},["minimumStage"]=2,["questID"]=1133,["sourceHash"]="b126961cc764a2dd0e875436b0b669741c24bce88086dea4e3e20f360124f2da"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4456",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The recommendation was her own: she cautioned that Shindrell did not actually know her.",["title"]="Fiora Longears"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1175:description:1-121","1175:description:123-307","1175:description:312-325","1175:description:327-420","1175:objective:1-125"},["minimumStage"]=2,["questID"]=1175,["sourceHash"]="7966096a447a4d8d4fe6f39b47cb46fdb0f00fd72ee5adf722b9fde450c34d97"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4629",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kronkrider hired Zherin to maintain the race track after the Red Thunder racer crashed into a basilisk.",["title"]="Trackmaster Zherin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1175:description:1-121","1175:description:123-307","1175:description:312-325","1175:description:327-420","1175:objective:1-125"},["minimumStage"]=2,["questID"]=1175,["sourceHash"]="7966096a447a4d8d4fe6f39b47cb46fdb0f00fd72ee5adf722b9fde450c34d97"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4629",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The animals growing large on the flats threatened to wander onto the course during races, so he sought help keeping basilisks away.",["title"]="Trackmaster Zherin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1181:description:1-51","1181:description:53-135","1181:description:137-199","1181:description:204-262","1181:objective:1-39"},["minimumStage"]=2,["questID"]=1181,["sourceHash"]="b546e840580e4ad46c6aea578c1cd833ba6c74c85914b3fb36b95f6921fbdfe5"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4631",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wharfmaster Lozgil referred questions about Revilgaz’s sponsorship business directly to the baron on the tavern’s top floor across the harbor.",["title"]="Wharfmaster Lozgil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1189:description:1-34","1189:description:36-85","1189:description:87-189","1189:description:194-233","1189:description:235-287","1189:objective:1-74"},["minimumStage"]=2,["questID"]=1189,["sourceHash"]="2d9685bb0930d61a186157e92fa0ed223c2191b0be677ffb5463cee58336e54f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4708",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shreev completed Razzeric’s requested work but warned that the slightest mistake setting it off could burn the driver on the track.",["title"]="Shreev"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1203:description:1-21","1203:description:24-69","1203:description:71-92","1203:description:95-112","1203:description:117-159","1203:description:162-185","1203:description:190-201","1203:description:204-287","1203:description:292-315","1203:description:318-355","1203:objective:1-57"},["minimumStage"]=2,["questID"]=1203,["sourceHash"]="e2bc5cd252b958290857983438932765b7f5cb747a0b87731b5a555d0c1d18a7"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4792",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jarl urgently wanted a moonsteel broadsword, which he called a swing blade, for cutting he would not explain.",["title"]="\"Swamp Eye\" Jarl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1203:description:1-21","1203:description:24-69","1203:description:71-92","1203:description:95-112","1203:description:117-159","1203:description:162-185","1203:description:190-201","1203:description:204-287","1203:description:292-315","1203:description:318-355","1203:objective:1-57"},["minimumStage"]=2,["questID"]=1203,["sourceHash"]="e2bc5cd252b958290857983438932765b7f5cb747a0b87731b5a555d0c1d18a7"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4792",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He suggested either buying it in town or asking a blacksmith for special work, warning that the intended material would not keep forever.",["title"]="\"Swamp Eye\" Jarl"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1220:description:1-54","1220:description:57-102","1220:description:105-165","1220:description:170-244","1220:objective:1-47"},["minimumStage"]=2,["questID"]=1220,["sourceHash"]="f4acb675ac3d7c41e3e022420533550f61f59e64b20f9fb978ecbc0f50aae95a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4947",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Theramore lieutenant directed an intercepted orc report to Captain Vimes, whose command of the language suited the inquiry.",["title"]="Theramore Lieutenant"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1220:description:1-54","1220:description:57-102","1220:description:105-165","1220:description:170-244","1220:objective:1-47"},["minimumStage"]=2,["questID"]=1220,["sourceHash"]="f4acb675ac3d7c41e3e022420533550f61f59e64b20f9fb978ecbc0f50aae95a"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-4947",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The report raised concern about Horde spies near Theramore and required the captain’s immediate attention.",["title"]="Theramore Lieutenant"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1242:description:1-36","1242:description:38-67","1242:description:69-111","1242:description:113-137","1242:description:142-245","1242:description:250-324","1242:description:326-335","1242:objective:1-64"},["minimumStage"]=2,["questID"]=1242,["sourceHash"]="04911e74bda3513fc40c9d8c9daddf7409f1b6bc6a7c107a6722b99ce85f7a93"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4959",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jorgen acted as a discreet intermediary, sending a sealed communication to Elling Trias at his Trade District cheese shop.",["title"]="Jorgen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1242:description:1-36","1242:description:38-67","1242:description:69-111","1242:description:113-137","1242:description:142-245","1242:description:250-324","1242:description:326-335","1242:objective:1-64"},["minimumStage"]=2,["questID"]=1242,["sourceHash"]="04911e74bda3513fc40c9d8c9daddf7409f1b6bc6a7c107a6722b99ce85f7a93"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4959",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He insisted that the messenger remain polite, wait for a response and say nothing unnecessary about the sensitive matter.",["title"]="Jorgen"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1247:description:1-10","1247:description:18-76","1247:description:78-111","1247:description:113-148","1247:description:150-187","1247:description:189-205","1247:description:210-287","1247:description:289-334","1247:objective:1-35"},["minimumStage"]=2,["questID"]=1247,["sourceHash"]="9c1ba78a65bae846fb6936eaf014c7666f171d0228965c5f12c7a904eb9fd45f"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4961",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dashel admitted that his part in the first plan had ended in failure and identified Slim of Menethil as the contact for the backup arrangement.",["title"]="Dashel Stonefist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1247:description:1-10","1247:description:18-76","1247:description:78-111","1247:description:113-148","1247:description:150-187","1247:description:189-205","1247:description:210-287","1247:description:289-334","1247:objective:1-35"},["minimumStage"]=2,["questID"]=1247,["sourceHash"]="9c1ba78a65bae846fb6936eaf014c7666f171d0228965c5f12c7a904eb9fd45f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4961",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He tried to distance himself from the later meeting at Addle’s Stead even while revealing that another attempt had been prepared.",["title"]="Dashel Stonefist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1274:description:1-27","1274:description:29-130","1274:description:135-264","1274:description:266-291","1274:description:293-326","1274:objective:1-38"},["minimumStage"]=2,["questID"]=1274,["sourceHash"]="97fa62279538a1ed9039443854fb7477c64205657a46c86c1b8489057473b2fe"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4982",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thomas quietly recruited adventurers for Bishop DeLavey’s delicate business at Stormwind Keep.",["title"]="Thomas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1274:description:1-27","1274:description:29-130","1274:description:135-264","1274:description:266-291","1274:description:293-326","1274:objective:1-38"},["minimumStage"]=2,["questID"]=1274,["sourceHash"]="97fa62279538a1ed9039443854fb7477c64205657a46c86c1b8489057473b2fe"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4982",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His appeal stressed discretion and importance before disclosing the subject of the bishop’s request.",["title"]="Thomas"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1276:description:1-19","1276:description:21-75","1276:description:77-122","1276:description:127-203","1276:description:205-219","1276:description:224-280","1276:description:285-381","1276:objective:1-58"},["minimumStage"]=2,["questID"]=1276,["sourceHash"]="6a831ef59203f801504a0410c2d861de121498c1cef338ad29db59138353997b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4926",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Earthen Ring once thanked Krog with armor made by Mosarn, leaving him able to recognize the Thunder Bluff smith’s name.",["title"]="Krog"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1276:description:1-19","1276:description:21-75","1276:description:77-122","1276:description:127-203","1276:description:205-219","1276:description:224-280","1276:description:285-381","1276:objective:1-58"},["minimumStage"]=2,["questID"]=1276,["sourceHash"]="6a831ef59203f801504a0410c2d861de121498c1cef338ad29db59138353997b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4926",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="That memory supplied a new lead for the shield inquiry after Reethe had yielded nothing useful.",["title"]="Krog"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1282:description:1-50","1282:description:52-78","1282:description:80-136","1282:description:141-183","1282:description:185-237","1282:description:239-344","1282:objective:1-69"},["minimumStage"]=2,["questID"]=1282,["sourceHash"]="8c1ff145f69156dde624346b8f506ec4ec7ffb77350fc305cf2b95eb7dbde579"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4921",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Guard Byron remembered Jim as the proprietor of a fine marsh inn and felt sorry for his changed condition, but preferred not to discuss it further.",["title"]="Guard Byron"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1282:description:1-50","1282:description:52-78","1282:description:80-136","1282:description:141-183","1282:description:185-237","1282:description:239-344","1282:objective:1-69"},["minimumStage"]=2,["questID"]=1282,["sourceHash"]="8c1ff145f69156dde624346b8f506ec4ec7ffb77350fc305cf2b95eb7dbde579"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-4921",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed persistent questions to Vimes at Foothold Citadel, east of Jaina’s tower.",["title"]="Guard Byron"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1285:description:1-9","1285:description:11-20","1285:description:22-36","1285:description:38-61","1285:description:66-170","1285:description:172-232","1285:description:234-269","1285:description:274-291","1285:objective:1-73"},["minimumStage"]=2,["questID"]=1285,["sourceHash"]="24f150feb75639215054899219fa2623fdee26822cd9de6846d7ee1d3cd64c44"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4948",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Adjutant Tesoran consulted Theramore’s service records to identify Lieutenant Paval Reethe.",["title"]="Adjutant Tesoran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1285:description:1-9","1285:description:11-20","1285:description:22-36","1285:description:38-61","1285:description:66-170","1285:description:172-232","1285:description:234-269","1285:description:274-291","1285:objective:1-73"},["minimumStage"]=2,["questID"]=1285,["sourceHash"]="24f150feb75639215054899219fa2623fdee26822cd9de6846d7ee1d3cd64c44"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4948",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The register recorded Reethe joining the Kul Tiras marines at sixteen, earning distinguished service and promotions, crossing the sea with Proudmoore’s recruits and later being listed missing.",["title"]="Adjutant Tesoran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1320:description:1-27","1320:description:29-132","1320:description:134-162","1320:description:167-198","1320:description:200-255","1320:objective:1-45"},["minimumStage"]=2,["questID"]=1320,["sourceHash"]="8839aac8dd7f0dfdd0b9a172d2c3e4af3f9437fe61779930901ddd4b3802b909"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4941",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Caz examined the shield’s burned-away leather strap and judged that it had fitted a large owner, perhaps a tauren.",["title"]="Caz Twosprocket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1320:description:1-27","1320:description:29-132","1320:description:134-162","1320:description:167-198","1320:description:200-255","1320:objective:1-45"},["minimumStage"]=2,["questID"]=1320,["sourceHash"]="8839aac8dd7f0dfdd0b9a172d2c3e4af3f9437fe61779930901ddd4b3802b909"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-4941",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered the identification tentatively and apologized to Vimes that the damaged object could tell him no more.",["title"]="Caz Twosprocket"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1036:description:7-30","1036:description:33-114","1036:description:117-221","1036:description:226-310","1036:description:313-402","1036:objective:1-93"},["minimumStage"]=2,["questID"]=1036,["sourceHash"]="350752ec2257563a6255f60e72d4d76be36f8aa2467e58ec57ebef127632eb6d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-1757",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Fleet Master Firallon received prospective Bloodsail recruits below decks aboard the Crimson Veil.",["title"]="The Crimson Veil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1036:description:7-30","1036:description:33-114","1036:description:117-221","1036:description:226-310","1036:description:313-402","1036:objective:1-93"},["minimumStage"]=2,["questID"]=1036,["sourceHash"]="350752ec2257563a6255f60e72d4d76be36f8aa2467e58ec57ebef127632eb6d"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-1757",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The ship lay at anchor off the Wild Coast beside the Riptide and the Damsel’s Luck.",["title"]="The Crimson Veil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1036:description:7-30","1036:description:33-114","1036:description:117-221","1036:description:226-310","1036:description:313-402","1036:objective:1-93"},["minimumStage"]=2,["questID"]=1036,["sourceHash"]="350752ec2257563a6255f60e72d4d76be36f8aa2467e58ec57ebef127632eb6d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1758",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Riptide lay with the Crimson Veil and the Damsel’s Luck off the Wild Coast, part of the ships Duncan named for a Bloodsail recruit.",["title"]="The Riptide"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"1036:description:7-30","1036:description:33-114","1036:description:117-221","1036:description:226-310","1036:description:313-402","1036:objective:1-93"},["minimumStage"]=2,["questID"]=1036,["sourceHash"]="350752ec2257563a6255f60e72d4d76be36f8aa2467e58ec57ebef127632eb6d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1759",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Damsel’s Luck was anchored beside the Crimson Veil and Riptide when Duncan directed recruits toward Firallon’s command.",["title"]="The Damsel's Luck"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1322:description:1-107","1322:description:112-140","1322:description:142-187","1322:description:189-275","1322:description:277-326","1322:objective:1-62"},["minimumStage"]=2,["questID"]=1322,["sourceHash"]="28990e5c758f9e70a1ffa3c0880cf8f73568a61693ba6f8d3b77c230ac3fa74c"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5087",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Do’gol found writing on the shield’s rim beneath burned residue and proposed revealing it with acid from Darkmist spiders’ venom.",["title"]="Do'gol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1322:description:1-107","1322:description:112-140","1322:description:142-187","1322:description:189-275","1322:description:277-326","1322:objective:1-62"},["minimumStage"]=2,["questID"]=1322,["sourceHash"]="28990e5c758f9e70a1ffa3c0880cf8f73568a61693ba6f8d3b77c230ac3fa74c"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5087",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The spiders’ occupation of the old Darkmist mine made its venom sacs the practical next step toward identifying the shield’s maker.",["title"]="Do'gol"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1387:description:1-36","1387:description:39-117","1387:description:120-127","1387:description:132-195","1387:description:198-242","1387:description:247-305","1387:description:308-332","1387:description:337-420","1387:objective:1-71"},["minimumStage"]=2,["questID"]=1387,["sourceHash"]="1f1741a5a89f20cf4684b4b5d96228f0f4defbd1625f189716adc05fbed475a4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5752",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Corporal Melkins regarded removing the centaur as necessary for peace and commissioned an Alliance bounty proven by their ears.",["title"]="Corporal Melkins"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1387:description:1-36","1387:description:39-117","1387:description:120-127","1387:description:132-195","1387:description:198-242","1387:description:247-305","1387:description:308-332","1387:description:337-420","1387:objective:1-71"},["minimumStage"]=2,["questID"]=1387,["sourceHash"]="1f1741a5a89f20cf4684b4b5d96228f0f4defbd1625f189716adc05fbed475a4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5752",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Although he recognized that the clans had different leaders and agendas, he condemned all of them as cruel; that sweeping judgment was his own.",["title"]="Corporal Melkins"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1393:description:1-12","1393:description:15-50","1393:description:55-110","1393:description:113-242","1393:description:247-295","1393:objective:1-94"},["minimumStage"]=2,["questID"]=1393,["sourceHash"]="9102c379e56c054a387b41609ed61390beb75a84ffec61f375635372743eeadc"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5391",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Galen Goodward feared that his captors would eat him and sought help escaping.",["title"]="Galen Goodward"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1393:description:1-12","1393:description:15-50","1393:description:55-110","1393:description:113-242","1393:description:247-295","1393:objective:1-94"},["minimumStage"]=2,["questID"]=1393,["sourceHash"]="9102c379e56c054a387b41609ed61390beb75a84ffec61f375635372743eeadc"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5391",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered treasure from his camp north of Stonard, promising to reveal the trick that opened its locked strongbox once free.",["title"]="Galen Goodward"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1418:description:1-160","1418:description:165-183","1418:description:186-274","1418:description:277-328","1418:objective:1-27"},["minimumStage"]=2,["questID"]=1418,["sourceHash"]="402aa03adca25fc46d4f8133a30d60d3c724d3d6ec39f7ceb420687b6064af91"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-1442",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Helgrum maintained contact with Kargath through reports from its head scout, Neeka Bloodscar.",["title"]="Helgrum the Swift"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1418:description:1-160","1418:description:165-183","1418:description:186-274","1418:description:277-328","1418:objective:1-27"},["minimumStage"]=2,["questID"]=1418,["sourceHash"]="402aa03adca25fc46d4f8133a30d60d3c724d3d6ec39f7ceb420687b6064af91"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-1442",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The harsh Badlands and nearby Alliance-held Loch Modan often severed communication with Stonard, making a capable courier valuable.",["title"]="Helgrum the Swift"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1478:description:9-101","1478:description:106-141","1478:description:143-228","1478:description:233-328","1478:objective:1-44"},["minimumStage"]=2,["questID"]=1478,["sourceHash"]="b3dc44cf5e7bb477cb1ff2c7dcfdc016875e36c1ec1744a3ea544c89c1c2bdbd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-5724",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ageron Kargal passed Halgar’s summons to a promising young warlock for further training.",["title"]="Ageron Kargal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1478:description:9-101","1478:description:106-141","1478:description:143-228","1478:description:233-328","1478:objective:1-44"},["minimumStage"]=2,["questID"]=1478,["sourceHash"]="b3dc44cf5e7bb477cb1ff2c7dcfdc016875e36c1ec1744a3ea544c89c1c2bdbd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5724",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He regarded personal instruction from Halgar near the Undercity’s Temple of the Damned as an uncommon honor.",["title"]="Ageron Kargal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1506:description:1-10","1506:description:12-21","1506:description:26-102","1506:description:104-167","1506:description:172-272","1506:objective:1-41"},["minimumStage"]=2,["questID"]=1506,["sourceHash"]="5b406de284491dcb3854afb18c3af8185dcd0a05fcb4352b821dab5b7504a21a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3294",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ophek carried Gan’rul’s urgent summons and directed the recipient toward the senior warlocks in the Cleft of Shadow.",["title"]="Ophek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1506:description:1-10","1506:description:12-21","1506:description:26-102","1506:description:104-167","1506:description:172-272","1506:objective:1-41"},["minimumStage"]=2,["questID"]=1506,["sourceHash"]="5b406de284491dcb3854afb18c3af8185dcd0a05fcb4352b821dab5b7504a21a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3294",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Past dealings left him unsure whether the attention promised favor or trouble.",["title"]="Ophek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1508:description:1-6","1508:description:8-70","1508:description:75-192","1508:description:197-202","1508:description:204-257","1508:description:259-330","1508:description:332-368","1508:description:373-382","1508:objective:1-32"},["minimumStage"]=2,["questID"]=1508,["sourceHash"]="c22302445fde173f2141bd9f07bb5d2a2aab425f24c69371e2e0491927ea5b49"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-5909",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cazul openly identified himself as blind while offering guidance to Gan’rul’s student.",["title"]="Cazul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1508:description:1-6","1508:description:8-70","1508:description:75-192","1508:description:197-202","1508:description:204-257","1508:description:259-330","1508:description:332-368","1508:description:373-382","1508:objective:1-32"},["minimumStage"]=2,["questID"]=1508,["sourceHash"]="c22302445fde173f2141bd9f07bb5d2a2aab425f24c69371e2e0491927ea5b49"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5909",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="For a succubus’s enticement, he directed the search to Zankaja, waiting for her mate in Orgrimmar’s bluffs west of the wind rider tower.",["title"]="Cazul"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1512:description:1-31","1512:description:33-62","1512:description:64-109","1512:description:114-126","1512:description:128-141","1512:description:143-207","1512:description:212-269","1512:description:271-308","1512:objective:1-62"},["minimumStage"]=2,["questID"]=1512,["sourceHash"]="e7abe267ba62a6f2d8de1b9f9a50917983ecacceecbe62c8ac88f989e72bd0ef"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5908",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dogran feared his injuries would condemn the young Zankaja to caring for an invalid, a future he refused to impose upon her.",["title"]="Grunt Dogran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1512:description:1-31","1512:description:33-62","1512:description:64-109","1512:description:114-126","1512:description:128-141","1512:description:143-207","1512:description:212-269","1512:description:271-308","1512:objective:1-62"},["minimumStage"]=2,["questID"]=1512,["sourceHash"]="e7abe267ba62a6f2d8de1b9f9a50917983ecacceecbe62c8ac88f989e72bd0ef"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5908",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He preferred the chance to face battle again and asked that his mate not be told, hoping to spare her guilt.",["title"]="Grunt Dogran"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1560:description:1-13","1560:description:18-106","1560:description:111-159","1560:description:161-213","1560:objective:1-43"},["minimumStage"]=2,["questID"]=1560,["sourceHash"]="0ac566e2fff805f8cac5668045b416077c141e265abb246c250df83901bfe155"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-5955",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tooga became lost after his wife sent him to fetch dinner and he took a wrong turn.",["title"]="Tooga"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1560:description:1-13","1560:description:18-106","1560:description:111-159","1560:description:161-213","1560:objective:1-43"},["minimumStage"]=2,["questID"]=1560,["sourceHash"]="0ac566e2fff805f8cac5668045b416077c141e265abb246c250df83901bfe155"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5955",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Torta waited south of Steamwheedle Port while Tooga asked a traveler to guide him home.",["title"]="Tooga"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1582:description:1-57","1582:description:60-162","1582:description:167-284","1582:objective:1-114"},["minimumStage"]=2,["questID"]=1582,["sourceHash"]="c913777dd114fb84859a3e0034f5024dc4074a0e3a07908736cf5af2f393a78f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6034",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lotherias filled Darnassus’s orders for leather goods needed by young adventurers entering the wilderness.",["title"]="Lotherias"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1582:description:1-57","1582:description:60-162","1582:description:167-284","1582:objective:1-114"},["minimumStage"]=2,["questID"]=1582,["sourceHash"]="c913777dd114fb84859a3e0034f5024dc4074a0e3a07908736cf5af2f393a78f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6034",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Help with those orders could earn instruction in a more advanced leatherworking technique.",["title"]="Lotherias"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1639:description:1-22","1639:description:25-74","1639:description:79-126","1639:description:129-137","1639:description:140-165","1639:description:170-242","1639:objective:1-20"},["minimumStage"]=2,["questID"]=1639,["sourceHash"]="7d021b783efddb092dd434407ddbab4c84fa6471f62d86b38a6f54d95537d007"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6089",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Harry Burlguard offered warrior instruction only after seeing what a pupil could already do.",["title"]="Harry Burlguard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1639:description:1-22","1639:description:25-74","1639:description:79-126","1639:description:129-137","1639:description:140-165","1639:description:170-242","1639:objective:1-20"},["minimumStage"]=2,["questID"]=1639,["sourceHash"]="7d021b783efddb092dd434407ddbab4c84fa6471f62d86b38a6f54d95537d007"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6089",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He tested a newcomer by demanding Bartleby’s mug from the drunk at the bar, knowing it would not be surrendered willingly.",["title"]="Harry Burlguard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1651:description:1-68","1651:description:73-107","1651:description:109-193","1651:description:198-291","1651:description:296-350","1651:description:352-369","1651:description:371-393","1651:description:398-430","1651:objective:1-46","1651:objective:51-138","1651:objective:143-199"},["minimumStage"]=2,["questID"]=1651,["sourceHash"]="b930f9e16f769d082f70d0d2a0b430dadadadc0a428f179452cf81a088d531ca"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6182",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Daphne prepared a gun from her house for another attack, intending to help hold the ground nearby while warning that the next raiders might be more numerous.",["title"]="Daphne Stilwell"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1678:description:1-75","1678:description:78-174","1678:description:179-265","1678:description:268-325","1678:description:330-382","1678:objective:1-52"},["minimumStage"]=2,["questID"]=1678,["sourceHash"]="efba08b7e8bafcb16ba74d3e294cddaaeb80f964e05201d7042685fca7bf9cf4"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6114",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Muren Stormpike trained warriors who could prove themselves against a genuine foe.",["title"]="Muren Stormpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1678:description:1-75","1678:description:78-174","1678:description:179-265","1678:description:268-325","1678:description:330-382","1678:objective:1-52"},["minimumStage"]=2,["questID"]=1678,["sourceHash"]="efba08b7e8bafcb16ba74d3e294cddaaeb80f964e05201d7042685fca7bf9cf4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6114",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He chose Vejrek as a test of mettle, directing the pupil toward the troll’s hut south of Frostmane Hold and demanding proof in the form of his head.",["title"]="Muren Stormpike"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1679:description:1-15","1679:description:18-135","1679:description:140-212","1679:description:215-280","1679:objective:1-27"},["minimumStage"]=2,["questID"]=1679,["sourceHash"]="1440ff21ec2652898f4484373688e8a92908e63db5503bd7976a647c35a595ed"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-1229",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Granis Swiftaxe referred promising warriors to Muren at the Hall of Arms in Ironforge’s Military Ward for their next instruction.",["title"]="Granis Swiftaxe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1678:description:1-75","1678:description:78-174","1678:description:179-265","1678:description:268-325","1678:description:330-382","1678:objective:1-52"},["minimumStage"]=2,["questID"]=1678,["sourceHash"]="efba08b7e8bafcb16ba74d3e294cddaaeb80f964e05201d7042685fca7bf9cf4"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-unit-6113",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vejrek occupied a hut in the foothills south of Frostmane Hold.",["title"]="Vejrek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1678:description:1-75","1678:description:78-174","1678:description:179-265","1678:description:268-325","1678:description:330-382","1678:objective:1-52"},["minimumStage"]=2,["questID"]=1678,["sourceHash"]="efba08b7e8bafcb16ba74d3e294cddaaeb80f964e05201d7042685fca7bf9cf4"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6113",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Muren regarded him as the toughest nearby troll and made confronting him a trial for an aspiring warrior.",["title"]="Vejrek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1700:description:1-118","1700:description:121-174","1700:description:179-214","1700:description:217-307","1700:objective:1-38"},["minimumStage"]=2,["questID"]=1700,["sourceHash"]="1fb5dd3a9481dc72408009992317462e5084caf1b5d3ffb5fb29a4ca50e71b2d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5413",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Furen Longbeard copied the techniques learned while making the warrior’s armor and sent the notes to Grimand Elmore.",["title"]="Furen Longbeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1700:description:1-118","1700:description:121-174","1700:description:179-214","1700:description:217-307","1700:objective:1-38"},["minimumStage"]=2,["questID"]=1700,["sourceHash"]="1fb5dd3a9481dc72408009992317462e5084caf1b5d3ffb5fb29a4ca50e71b2d"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5413",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned that Elmore’s fierce pride in his craft might make the offer of instruction unwelcome.",["title"]="Furen Longbeard"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1823:description:1-46","1823:description:49-97","1823:description:100-152","1823:description:157-201","1823:objective:1-26"},["minimumStage"]=2,["questID"]=1823,["sourceHash"]="b6820acaabaa8d3e9e50c0847e9f710ad6260fe731dbc3e0194ce585a658846a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3354",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sorek judged when a warrior of growing skill was ready for Ruga Ragetotem’s trial at Camp Taurajo.",["title"]="Sorek"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1824:description:1-65","1824:description:68-124","1824:description:127-189","1824:description:194-305","1824:description:308-378","1824:objective:1-60"},["minimumStage"]=2,["questID"]=1824,["sourceHash"]="c1ca02eeb41241b6f50fcfed3ed785480576fe6a7651a35e3f71193fe6b0be17"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6394",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ruga’s trial demanded fresh, still-twitching antennae from the creatures crawling across the Field of Giants, making speed part of the test.",["title"]="Ruga Ragetotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1824:description:1-65","1824:description:68-124","1824:description:127-189","1824:description:194-305","1824:description:308-378","1824:objective:1-60"},["minimumStage"]=2,["questID"]=1824,["sourceHash"]="c1ca02eeb41241b6f50fcfed3ed785480576fe6a7651a35e3f71193fe6b0be17"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6394",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The insects were newcomers to the Barrens in his account, and he distrusted what their arrival might herald.",["title"]="Ruga Ragetotem"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1846:description:1-66","1846:description:69-130","1846:description:133-149","1846:description:154-177","1846:description:180-229","1846:description:232-321","1846:objective:1-69"},["minimumStage"]=2,["questID"]=1846,["sourceHash"]="346aeb94b20d6b383cd273148d5c201ee30865f12f466f7e9689f7a492046451"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6411",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Velora Nitely fashioned brutal leg guards using sturdy Dragonmaw shinbones.",["title"]="Velora Nitely"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1846:description:1-66","1846:description:69-130","1846:description:133-149","1846:description:154-177","1846:description:180-229","1846:description:232-321","1846:objective:1-69"},["minimumStage"]=2,["questID"]=1846,["sourceHash"]="346aeb94b20d6b383cd273148d5c201ee30865f12f466f7e9689f7a492046451"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6411",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She required bones strong enough to resist being snapped by hand, rejecting weaker pieces as unsuitable for the work.",["title"]="Velora Nitely"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1859:description:1-21","1859:description:23-45","1859:description:47-105","1859:description:110-235","1859:description:240-250","1859:description:255-302","1859:description:304-337","1859:objective:1-55"},["minimumStage"]=2,["questID"]=1859,["sourceHash"]="887791067e7acc75c67b795ba7924ace2137a0a7b33f22fa67eea0b6f829dba8"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-3170",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kaplak had been told to recognize a particular recruit by description and direct the newcomer toward Therzok’s offer in Orgrimmar.",["title"]="Kaplak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1859:description:1-21","1859:description:23-45","1859:description:47-105","1859:description:110-235","1859:description:240-250","1859:description:255-302","1859:description:304-337","1859:objective:1-55"},["minimumStage"]=2,["questID"]=1859,["sourceHash"]="887791067e7acc75c67b795ba7924ace2137a0a7b33f22fa67eea0b6f829dba8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-3170",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The approach was quiet and selective, based on reports of combat ability paired with a willingness to use stealth.",["title"]="Kaplak"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1860:description:1-38","1860:description:41-103","1860:description:108-137","1860:description:140-210","1860:description:213-255","1860:objective:1-38"},["minimumStage"]=2,["questID"]=1860,["sourceHash"]="4ca4219e17911b0f4da28c1d1cfb9de62e371c2743fdecb8cec087629000d6fc"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-328",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zaldimar Wefhellt directed a mage toward Jennea Cannon for work important to Stormwind and Elwynn’s safety.",["title"]="Zaldimar Wefhellt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1860:description:1-38","1860:description:41-103","1860:description:108-137","1860:description:140-210","1860:description:213-255","1860:objective:1-38"},["minimumStage"]=2,["questID"]=1860,["sourceHash"]="4ca4219e17911b0f4da28c1d1cfb9de62e371c2743fdecb8cec087629000d6fc"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-328",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jennea held the details at the Wizard’s Sanctum in Stormwind’s Mage Quarter.",["title"]="Zaldimar Wefhellt"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1879:description:6-55","1879:description:58-134","1879:description:137-158","1879:description:163-190","1879:description:193-269","1879:objective:1-29"},["minimumStage"]=2,["questID"]=1879,["sourceHash"]="2f254ae7ee2be4c3cd30e4a526ca3e5efd0cffdb3d05afdbebcc5fc900551fa3"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-1228",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Magis Sparkmantle passed along word from Bink, the gnomish colleague who worked in Ironforge’s Hall of Mysteries.",["title"]="Magis Sparkmantle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1879:description:6-55","1879:description:58-134","1879:description:137-158","1879:description:163-190","1879:description:193-269","1879:objective:1-29"},["minimumStage"]=2,["questID"]=1879,["sourceHash"]="2f254ae7ee2be4c3cd30e4a526ca3e5efd0cffdb3d05afdbebcc5fc900551fa3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-1228",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bink’s request called specifically for a mage, making the referral a matter of magical expertise rather than ordinary errand work.",["title"]="Magis Sparkmantle"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1881:description:1-62","1881:description:65-189","1881:objective:1-30"},["minimumStage"]=2,["questID"]=1881,["sourceHash"]="928aea9b32d1b6ed4e117a29a1e34b86e79b4f61fc48ade5c684c6d9f6f5bc39"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2128",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Cain Firesong prepared a promising mage to meet Anastasia Hartwell in the Undercity’s Magic Quarter for the first work assigned by the Forsaken’s mages.",["title"]="Cain Firesong"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1884:description:1-89","1884:description:92-200","1884:description:205-328","1884:description:333-414","1884:objective:1-66"},["minimumStage"]=2,["questID"]=1884,["sourceHash"]="9b6564f19c65bfdbc023d16aac1e0c4d4202d60dba86e53e64f37d6b0196d416"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-5880",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Un’Thuwa blamed Zalazane’s tainted ju-ju heaps for disrupting Durotar’s flow of magic and corrupting its wildlife.",["title"]="Un'Thuwa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1884:description:1-89","1884:description:92-200","1884:description:205-328","1884:description:333-414","1884:objective:1-66"},["minimumStage"]=2,["questID"]=1884,["sourceHash"]="9b6564f19c65bfdbc023d16aac1e0c4d4202d60dba86e53e64f37d6b0196d416"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-5880",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The fetishes among the Echo Isles’ huts also empowered warlocks and infernal creatures, making their destruction a defense against lasting magical harm.",["title"]="Un'Thuwa"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1885:description:5-92","1885:description:94-130","1885:description:135-188","1885:description:190-278","1885:objective:1-65"},["minimumStage"]=2,["questID"]=1885,["sourceHash"]="b1310ed62de83dcf2b4832907ed0d03acfadc351d38ce762c86dacede0a24e23"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2130",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marion Call passed Mennet Carkad’s summons to the recruit who had attracted his attention.",["title"]="Marion Call"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1885:description:5-92","1885:description:94-130","1885:description:135-188","1885:description:190-278","1885:objective:1-65"},["minimumStage"]=2,["questID"]=1885,["sourceHash"]="b1310ed62de83dcf2b4832907ed0d03acfadc351d38ce762c86dacede0a24e23"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2130",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Marion warned against ignoring the invitation, alluding to the fate of earlier people who had done so without explaining it.",["title"]="Marion Call"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1899:description:1-91","1899:description:93-251","1899:objective:1-75"},["minimumStage"]=2,["questID"]=1899,["sourceHash"]="e7dd42bc6abc4b84584f371db764862ada56bd791dc75edaf9b72793fc937711"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6522",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Andron Gant supplied a ledger of information from his own bookshelf for a messenger’s employers.",["title"]="Andron Gant"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"1899:description:1-91","1899:description:93-251","1899:objective:1-75"},["minimumStage"]=2,["questID"]=1899,["sourceHash"]="e7dd42bc6abc4b84584f371db764862ada56bd791dc75edaf9b72793fc937711"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6522",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He welcomed further dealings if they valued the material, asking that the same messenger return rather than someone new.",["title"]="Andron Gant"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2038:description:1-160","2038:description:162-226","2038:description:231-289","2038:description:291-305","2038:objective:1-34","2038:objective:39-121"},["minimumStage"]=2,["questID"]=2038,["sourceHash"]="50dec45d3f359bee001014fd03c546f4b4ffe4e263346bbcce2d582470ba21c4"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-6577",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Bingles crashed into the Loch, then lost tools and special Blastencapper explosives when troggs from a nearby island attacked.",["title"]="Bingles Blastenheimer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2038:description:1-160","2038:description:162-226","2038:description:231-289","2038:description:291-305","2038:objective:1-34","2038:objective:39-121"},["minimumStage"]=2,["questID"]=2038,["sourceHash"]="50dec45d3f359bee001014fd03c546f4b4ffe4e263346bbcce2d582470ba21c4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6577",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Without his gyrocopter and explosives he feared the effort for Gnomeregan had no chance, making their recovery urgent.",["title"]="Bingles Blastenheimer"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2158:description:1-139","2158:description:144-199","2158:description:201-291","2158:description:296-384","2158:objective:1-52"},["minimumStage"]=2,["questID"]=2158,["sourceHash"]="c1853695ccaf1db612fcf5a9f5d1379eb66ca9fba96571c1513c04577007c9a9"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6774",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Falkhaan Isenstrider’s best friend Farley ran the Lion’s Pride Inn, which he recommended to weary adventurers.",["title"]="Falkhaan Isenstrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2158:description:1-139","2158:description:144-199","2158:description:201-291","2158:description:296-384","2158:objective:1-52"},["minimumStage"]=2,["questID"]=2158,["sourceHash"]="c1853695ccaf1db612fcf5a9f5d1379eb66ca9fba96571c1513c04577007c9a9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6774",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He thought that a referral might earn favorable prices for food and drink.",["title"]="Falkhaan Isenstrider"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2159:description:1-20","2159:description:23-43","2159:description:46-115","2159:description:118-194","2159:description:199-234","2159:description:237-295","2159:description:298-334","2159:objective:1-50"},["minimumStage"]=2,["questID"]=2159,["sourceHash"]="6df9db7a763c51eeeeae88d1876ff8c6edc52e88a0ea1d9f3faae4261b3a3663"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-6780",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Business with Shadowglen’s druids kept Porthannius from delivering a package of herbs to Dolanaar himself.",["title"]="Porthannius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2159:description:1-20","2159:description:23-43","2159:description:46-115","2159:description:118-194","2159:description:199-234","2159:description:237-295","2159:description:298-334","2159:objective:1-50"},["minimumStage"]=2,["questID"]=2159,["sourceHash"]="6df9db7a763c51eeeeae88d1876ff8c6edc52e88a0ea1d9f3faae4261b3a3663"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6780",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The intended recipient was Keldamyr at Dolanaar’s inn, south along the road.",["title"]="Porthannius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2205:description:1-10","2205:description:12-68","2205:description:70-194","2205:description:196-279","2205:description:284-374","2205:description:379-391","2205:objective:1-81"},["minimumStage"]=2,["questID"]=2205,["sourceHash"]="888664f0e5e4b8e34995f57834078d673ecf19c2baf7e64635797bc0ef90761f"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-917",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Keryn Sylvius carried out a promised assignment and used a package for Mathias to introduce a new rogue to his work.",["title"]="Keryn Sylvius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2205:description:1-10","2205:description:12-68","2205:description:70-194","2205:description:196-279","2205:description:284-374","2205:description:379-391","2205:objective:1-81"},["minimumStage"]=2,["questID"]=2205,["sourceHash"]="888664f0e5e4b8e34995f57834078d673ecf19c2baf7e64635797bc0ef90761f"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-917",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her dismissive manner contrasted with her determination to complete the job, warning that Mathias would expect more than the appearance of an ordinary delivery helper.",["title"]="Keryn Sylvius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2260:description:1-47","2260:description:49-119","2260:description:124-235","2260:description:240-266","2260:description:268-360","2260:objective:1-65"},["minimumStage"]=2,["questID"]=2260,["sourceHash"]="78c1d67dc26d097e1b460c107fa2a691be47d03eeeff6d537735586fc913b0ab"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-4214",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Erion Shadewhisper relayed Stormwind Intelligence’s invitation to a rogue whose deeds had drawn attention beyond the local trainers.",["title"]="Erion Shadewhisper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2260:description:1-47","2260:description:49-119","2260:description:124-235","2260:description:240-266","2260:description:268-360","2260:objective:1-65"},["minimumStage"]=2,["questID"]=2260,["sourceHash"]="78c1d67dc26d097e1b460c107fa2a691be47d03eeeff6d537735586fc913b0ab"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4214",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He treated the dangerous journey to Renzik in Old Town as an opportunity for training under SI:7 worth taking seriously.",["title"]="Erion Shadewhisper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2281:description:1-50","2281:description:52-103","2281:description:105-168","2281:description:173-261","2281:description:263-357","2281:objective:1-75"},["minimumStage"]=2,["questID"]=2281,["sourceHash"]="c3868691dd028cb81effcbbc98dd56c7cbaccd02873695cf90cb0cab411b5c1f"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-6946",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Renzik refused to send an unprepared rogue into the field and sought to bring the recruit up to speed first.",["title"]="Renzik \"The Shiv\""},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2281:description:1-50","2281:description:52-103","2281:description:105-168","2281:description:173-261","2281:description:263-357","2281:objective:1-75"},["minimumStage"]=2,["questID"]=2281,["sourceHash"]="c3868691dd028cb81effcbbc98dd56c7cbaccd02873695cf90cb0cab411b5c1f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-6946",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed training toward Lucius, an SI:7 associate among the people at Lakeshire’s docks.",["title"]="Renzik \"The Shiv\""},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2282:description:1-43","2282:description:45-126","2282:description:131-177","2282:description:179-233","2282:description:235-251","2282:description:253-322","2282:objective:1-90"},["minimumStage"]=2,["questID"]=2282,["sourceHash"]="34e1e74ffd38eb8f312531725b51cfad875fc12bd6e828cac23f122ce5c5f899"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6966",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lucius trained thieves near Lakeshire and used a chest at Alther’s Mill to test their finesse.",["title"]="Lucius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2282:description:1-43","2282:description:45-126","2282:description:131-177","2282:description:179-233","2282:description:235-251","2282:description:253-322","2282:objective:1-90"},["minimumStage"]=2,["questID"]=2282,["sourceHash"]="34e1e74ffd38eb8f312531725b51cfad875fc12bd6e828cac23f122ce5c5f899"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-6966",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A token recovered from the chest would earn his Certificate of Thievery, a practical challenge suited to the skill he proudly claimed for himself.",["title"]="Lucius"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2358:description:1-70","2358:description:72-208","2358:description:213-287","2358:description:289-339","2358:description:344-405","2358:objective:1-60"},["minimumStage"]=2,["questID"]=2358,["sourceHash"]="0cd7f5f1ba7ddc456584b18903ba78fde459f5ef5a4ad97b3b38afcf9fb7a3e5"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-7009",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Arantir had searched across continents and oceans for the Horns of Nez’ra, stolen from Ravenholdt years earlier.",["title"]="Arantir"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2358:description:1-70","2358:description:72-208","2358:description:213-287","2358:description:289-339","2358:description:344-405","2358:objective:1-60"},["minimumStage"]=2,["questID"]=2358,["sourceHash"]="0cd7f5f1ba7ddc456584b18903ba78fde459f5ef5a4ad97b3b38afcf9fb7a3e5"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7009",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Learning that Blackrock orcs held the horns, he offered recognition at Ravenholdt to the helper who returned them to him in Lakeshire.",["title"]="Arantir"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2382:description:1-22","2382:description:24-42","2382:description:44-60","2382:description:62-128","2382:description:130-157","2382:description:166-193","2382:description:195-280","2382:objective:1-53"},["minimumStage"]=2,["questID"]=2382,["sourceHash"]="929374783120fd5759e80c8a9b4f85991aad040b03740b75d18c91842bd4ee2a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3402",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zando’zan claimed to foresee Thrall’s death by a poisoned dagger, then abruptly cut his account short.",["title"]="Zando'zan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2382:description:1-22","2382:description:24-42","2382:description:44-60","2382:description:62-128","2382:description:130-157","2382:description:166-193","2382:description:195-280","2382:objective:1-53"},["minimumStage"]=2,["questID"]=2382,["sourceHash"]="929374783120fd5759e80c8a9b4f85991aad040b03740b75d18c91842bd4ee2a"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3402",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sent the recruit onward to Wrenix the Wretched in Ratchet, east of the Crossroads.",["title"]="Zando'zan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2480:description:1-54","2480:description:56-70","2480:description:72-154","2480:description:159-236","2480:description:241-287","2480:objective:1-43"},["minimumStage"]=2,["questID"]=2480,["sourceHash"]="01c3f443255c1a6db93525d7582a7eab7d8cd68c1c579608b61a23cb1861d303"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-2391",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Serge Hinott agreed to examine Zanzil’s toxin with the intention of curing its victim and teaching a use for the poison.",["title"]="Serge Hinott"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2480:description:1-54","2480:description:56-70","2480:description:72-154","2480:description:159-236","2480:description:241-287","2480:objective:1-43"},["minimumStage"]=2,["questID"]=2480,["sourceHash"]="01c3f443255c1a6db93525d7582a7eab7d8cd68c1c579608b61a23cb1861d303"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-2391",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He had not heard of Zanzil but admired the concoction’s striking effects, separating curiosity about the craft from knowledge of its maker.",["title"]="Serge Hinott"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2519:description:1-59","2519:description:64-107","2519:description:112-177","2519:description:179-243","2519:objective:1-83"},["minimumStage"]=2,["questID"]=2519,["sourceHash"]="a83017d6df01a3dc9534ebbb502d513b7a91714dd1458ac6a4c8236e7e9fa3cd"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7316",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sister Aquinne sought help for a once-great forest creature and directed the difficult matter to Priestess A’moora in the Temple of the Moon.",["title"]="Sister Aquinne"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2742:description:1-7","2742:description:12-44","2742:description:46-72","2742:description:74-140","2742:description:142-162","2742:description:167-257","2742:description:262-318","2742:objective:1-106"},["minimumStage"]=2,["questID"]=2742,["sourceHash"]="3146a33aaddf7abdfb1033c85cc71568b3d6dea55c2612714356da12047a6594"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7780",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Rin’ji lost his axe and was captured, fearing that a stranger’s dislike for his people might outweigh his plea to escape.",["title"]="Rin'ji"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2742:description:1-7","2742:description:12-44","2742:description:46-72","2742:description:74-140","2742:description:142-162","2742:description:167-257","2742:description:262-318","2742:objective:1-106"},["minimumStage"]=2,["questID"]=2742,["sourceHash"]="3146a33aaddf7abdfb1033c85cc71568b3d6dea55c2612714356da12047a6594"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7780",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He promised something hidden at the Overlook Cliffs as an inducement to a willing rescuer.",["title"]="Rin'ji"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2757:description:1-65","2757:description:70-98","2757:description:100-139","2757:description:141-204","2757:description:209-224","2757:description:226-299","2757:description:304-344","2757:description:346-403","2757:objective:1-32"},["minimumStage"]=2,["questID"]=2757,["sourceHash"]="83291e18173615fafac374d99725517a4c2a8acc027c86573f25556d89ead8e4"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7793",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ox referred a blacksmith ready for more demanding work to McGavan near Booty Bay’s smithy, providing an insignia to show commitment.",["title"]="Ox"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2760:description:1-52","2760:description:54-152","2760:description:154-251","2760:description:256-301","2760:description:303-383","2760:objective:1-52"},["minimumStage"]=2,["questID"]=2760,["sourceHash"]="ab2ffd528d1e668c7c9c151720190e4eebffc4aca03a028d1eef4e9e78b3f718"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7794",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="McGavan screened the Mithril Order’s recruits and sent the committed onward to Galvan the Ancient.",["title"]="McGavan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2760:description:1-52","2760:description:54-152","2760:description:154-251","2760:description:256-301","2760:description:303-383","2760:objective:1-52"},["minimumStage"]=2,["questID"]=2760,["sourceHash"]="ab2ffd528d1e668c7c9c151720190e4eebffc4aca03a028d1eef4e9e78b3f718"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7794",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He lamented that the insignia’s shine tempted many recruits away before they reached Booty Bay, contrasting that small prize with the craft’s greater possibilities.",["title"]="McGavan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2873:description:1-90","2873:description:93-192","2873:description:197-336","2873:objective:1-55"},["minimumStage"]=2,["questID"]=2873,["sourceHash"]="f1fe1d1def302bc5d4e24a6492a472581308d04b92958ac26863010e0800848b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-7881",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Stoley owed Sea Wolf MacKinley rum after a bet, but Captain Cuergo had stolen his last shipment.",["title"]="Stoley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2873:description:1-90","2873:description:93-192","2873:description:197-336","2873:objective:1-55"},["minimumStage"]=2,["questID"]=2873,["sourceHash"]="f1fe1d1def302bc5d4e24a6492a472581308d04b92958ac26863010e0800848b"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-7881",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He wanted the shipment recovered from the southern pirate town to prove his boast that Kalimdor’s drink surpassed Booty Bay’s.",["title"]="Stoley"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2923:description:1-85","2923:description:88-191","2923:description:196-204","2923:description:207-244","2923:description:249-309","2923:description:312-338","2923:objective:1-45"},["minimumStage"]=2,["questID"]=2923,["sourceHash"]="3fec1c0168359ef58564961563d399a37eb332d638711549de81a19a956304e8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-7917",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Sarno remembered Techbot as a kind, useful aid to the gnomes and hoped its reported malfunction could be repaired.",["title"]="Brother Sarno"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2923:description:1-85","2923:description:88-191","2923:description:196-204","2923:description:207-244","2923:description:249-309","2923:description:312-338","2923:objective:1-45"},["minimumStage"]=2,["questID"]=2923,["sourceHash"]="3fec1c0168359ef58564961563d399a37eb332d638711549de81a19a956304e8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7917",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed help toward Tinkmaster Overspark in Ironforge, knowing how distressed the inventor was about his creation.",["title"]="Brother Sarno"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2944:description:1-44","2944:description:46-142","2944:description:147-209","2944:description:211-220","2944:description:222-249","2944:description:251-323","2944:description:328-365","2944:description:367-375","2944:objective:1-111"},["minimumStage"]=2,["questID"]=2944,["sourceHash"]="ce6b5e1c8ae8f74d701353d88fd3652fec90ae90d85907d2541b21480741f6a1"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-7763",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Curgle Cranklehop invented the Super Snapper FX, a camera operated by aiming at a subject and pressing its button.",["title"]="Curgle Cranklehop"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"2944:description:1-44","2944:description:46-142","2944:description:147-209","2944:description:211-220","2944:description:222-249","2944:description:251-323","2944:description:328-365","2944:description:367-375","2944:objective:1-111"},["minimumStage"]=2,["questID"]=2944,["sourceHash"]="ce6b5e1c8ae8f74d701353d88fd3652fec90ae90d85907d2541b21480741f6a1"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-7763",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He expected Daryn to welcome a photograph of the Hinterlands turtle Gammerita, the suggested subject for trying the device.",["title"]="Curgle Cranklehop"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"539:description:1-88","539:description:91-168","539:description:173-309","539:description:314-350","539:description:353-412","539:description:415-438","539:description:441-489","539:objective:1-87"},["minimumStage"]=2,["questID"]=539,["sourceHash"]="fcdc77db9b40ad007ebf807befb378ae80c4c833e8e145219042fd81e15966fd"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-287",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The town’s registry identified Azureload Mine as an Alliance-held source of iron for its armories.",["title"]="Hillsbrad"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"539:description:1-88","539:description:91-168","539:description:173-309","539:description:314-350","539:description:353-412","539:description:415-438","539:description:441-489","539:objective:1-87"},["minimumStage"]=2,["questID"]=539,["sourceHash"]="fcdc77db9b40ad007ebf807befb378ae80c4c833e8e145219042fd81e15966fd"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-287",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Alliance protection of the mine continued after the attack on the town, drawing the Forsaken campaign toward its foreman and miners.",["title"]="Hillsbrad"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"541:description:1-26","541:description:29-60","541:description:65-117","541:description:120-216","541:description:219-278","541:description:283-380","541:description:383-448","541:description:451-491","541:objective:1-132"},["minimumStage"]=2,["questID"]=541,["sourceHash"]="4f9229e5b1ca6bb9e16a3b5b1a613dda743aefb7f5e148c3d4a1771bf1318184"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-1057",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dun Garok’s dwarven barracks stood along the wall in southeastern Hillsbrad, supporting the Alliance’s local defenses.",["title"]="Thoradin's Wall"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"549:description:1-106","549:description:108-179","549:description:181-284","549:description:289-382","549:objective:1-51","549:objective:53-117"},["minimumStage"]=2,["questID"]=549,["sourceHash"]="4f1b50b5f5726546fee5e1c8852ee65412fa6438077bcb6d9ad5d3f804312764"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-2370",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The ruined keep lay southeast of Tarren Mill.",["title"]="Durnholde Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"549:description:1-106","549:description:108-179","549:description:181-284","549:description:289-382","549:objective:1-51","549:objective:53-117"},["minimumStage"]=2,["questID"]=549,["sourceHash"]="4f1b50b5f5726546fee5e1c8852ee65412fa6438077bcb6d9ad5d3f804312764"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2370",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Syndicate gathered in its ruins, where Sylvanas’s wanted notice authorized death for members captured or confronted.",["title"]="Durnholde Keep"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"561:description:1-120","561:description:122-177","561:objective:1-52"},["minimumStage"]=2,["questID"]=561,["sourceHash"]="db32c1961cdc6dc9850f36348b65472ccb336f64622b4c3178debdf1ee872d96"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2373",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Naga along the Eastern Strand became the next priority for Orinelle’s patrol after his commander redirected the coastal effort.",["title"]="Eastern Strand"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"569:description:1-87","569:description:90-146","569:description:149-178","569:description:181-261","569:description:264-325","569:description:330-398","569:description:403-462","569:description:465-510","569:objective:1-105"},["minimumStage"]=2,["questID"]=569,["sourceHash"]="214ec4a20210e135300a5e55718c150d98bf36fe0f735b4e3587748393d08495"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-129",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mizjah stood southeast of Grom’gol in Stranglethorn’s jungle.",["title"]="Mizjah Ruins"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"569:description:1-87","569:description:90-146","569:description:149-178","569:description:181-261","569:description:264-325","569:description:330-398","569:description:403-462","569:description:465-510","569:objective:1-105"},["minimumStage"]=2,["questID"]=569,["sourceHash"]="214ec4a20210e135300a5e55718c150d98bf36fe0f735b4e3587748393d08495"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-129",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ogres occupying the ruins ambushed the caravans on which Grom’gol’s supply mission to Stonard depended.",["title"]="Mizjah Ruins"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"592:description:1-47","592:description:50-165","592:description:170-200","592:description:205-329","592:objective:1-37"},["minimumStage"]=2,["questID"]=592,["sourceHash"]="faa08c9a3deb08bc1a51f046c5d7131236a7502a4c89400a09ba7e167bd75a48"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-311",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Aboraz ruins lay along the Crystal Shore on Stranglethorn’s distant cape.",["title"]="Ruins of Aboraz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"592:description:1-47","592:description:50-165","592:description:170-200","592:description:205-329","592:objective:1-37"},["minimumStage"]=2,["questID"]=592,["sourceHash"]="faa08c9a3deb08bc1a51f046c5d7131236a7502a4c89400a09ba7e167bd75a48"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-311",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Zanzil kept Yenniku there, making the ruins the destination of a plan to stun the captive and draw his soul into a specially prepared gem.",["title"]="Ruins of Aboraz"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"594:description:1-43","594:description:48-70","594:description:75-107","594:description:109-172","594:description:177-364","594:description:369-417","594:objective:1-43"},["minimumStage"]=2,["questID"]=594,["sourceHash"]="c49d669eeb196e93de971ff8ca5c6973a02b5330b204cb62a1e0a3b776c2b9db"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-43",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A captive’s bottled note placed Wild Shore northwest of the jungle island where a great creature held the writer, with large sailing ships visible in another direction.",["title"]="Wild Shore"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"609:description:1-61","609:description:66-148","609:description:153-251","609:description:254-329","609:description:332-388","609:description:393-467","609:description:470-492","609:objective:1-115"},["minimumStage"]=2,["questID"]=609,["sourceHash"]="bf2663932abf0b75b14ac2e7d0e813af536676088dd33c879837d85355677deb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-477",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Mackinley’s search for overdue debtors led through Jubuwal and Aboraz after he heard that the missing men had been cursed and were wandering the ruins.",["title"]="Ruins of Jubuwal"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"634:description:1-38","634:description:41-75","634:description:78-176","634:description:181-220","634:description:223-332","634:objective:1-40"},["minimumStage"]=2,["questID"]=634,["sourceHash"]="4e358cb5dbbb14b87dca47f1a549b4bc7b2d4fed31f9e9f6cc462108a234c85c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-320",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Captain Nials’s Alliance camp was asked to spare soldiers for the effort to retake Dun Modr and the Thandol Span.",["title"]="Refuge Pointe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"718:description:1-126","718:description:128-229","718:description:231-262","718:description:264-288","718:description:293-365","718:description:367-441","718:description:446-508","718:objective:1-45"},["minimumStage"]=2,["questID"]=718,["sourceHash"]="5372f4aae751039cb4e2ac7cf09fecb56a85e6625caed32365e02d4356b4a7e8"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-location-area-341",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ogres from Camp Kosh seized equipment abandoned during the hurried withdrawal from the Uldaman excavation.",["title"]="Camp Kosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"718:description:1-126","718:description:128-229","718:description:231-262","718:description:264-288","718:description:293-365","718:description:367-441","718:description:446-508","718:objective:1-45"},["minimumStage"]=2,["questID"]=718,["sourceHash"]="5372f4aae751039cb4e2ac7cf09fecb56a85e6625caed32365e02d4356b4a7e8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-341",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The stolen cart held the expedition’s weapons, leaving its members unable to hunt for food until their supplies were recovered.",["title"]="Camp Kosh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"729:description:1-118","729:description:120-194","729:description:199-229","729:description:237-269","729:description:274-318","729:description:320-385","729:description:387-419","729:description:421-453","729:description:458-511","729:objective:1-47"},["minimumStage"]=2,["questID"]=729,["sourceHash"]="7ecfde41549bee21251229f58ef877c8c0227fd728f4fdad992724f8bbe941c9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-442",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Remtravel’s assistant fled to Auberdine for help after golems rose from an excavation to the south and overran the work, while the distracted prospector failed to notice.",["title"]="Auberdine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"732:description:1-59","732:description:61-93","732:description:95-204","732:description:209-341","732:description:346-464","732:description:466-506","732:objective:1-41"},["minimumStage"]=2,["questID"]=732,["sourceHash"]="d2c0672c46f2ea8d79fd6afdc0e7eb8f441f1279b16d3e46767d1ab5a7a0375f"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-342",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wandering ogres sometimes seen near Camp Boff stole the Sign of the Earth from Krasus’s agent, disrupting a secret mission concerning Lethlor Ravine.",["title"]="Camp Boff"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"733:description:1-131","733:description:133-214","733:description:216-297","733:description:302-425","733:description:430-504","733:objective:1-39"},["minimumStage"]=2,["questID"]=733,["sourceHash"]="3d3395cab9af7629ce68a2c22c1aec2f267e9cdeace171d46137971f16469b32"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-347",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dustbelch Grotto was the main camp of the local ogres, whose scrap metal could supply the prospectors’ defenses and other necessities.",["title"]="Dustbelch Grotto"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"792:description:1-59","792:description:64-147","792:description:152-236","792:description:239-352","792:description:357-436","792:description:438-481","792:objective:1-23","792:objective:28-70"},["minimumStage"]=2,["questID"]=792,["sourceHash"]="f617be7151bc12f89cf32bd187297a4af64283e47a52ddc856543dcecbde2414"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-363",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Burning Blade’s hidden coven tainted the training grounds, with vile familiars emerging from its cave to spread havoc.",["title"]="Valley of Trials"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"794:description:1-129","794:description:134-237","794:description:242-421","794:description:435-491","794:objective:1-71"},["minimumStage"]=2,["questID"]=794,["sourceHash"]="058bb692ee26bd0b2207427b9b066d4e9b1e762e6b68ac623e883789867baf52"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-365",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A powerful medallion lay deep in the coven, protected by beasts and dark magic and possibly held by a cult agent stronger than the outer familiars.",["title"]="Burning Blade Coven"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"805:description:1-53","805:description:55-73","805:description:76-114","805:description:119-180","805:description:183-248","805:description:253-334","805:description:337-387","805:description:392-412","805:description:415-502","805:objective:1-44"},["minimumStage"]=2,["questID"]=805,["sourceHash"]="b99a46354f4af7907d2902b1414151ec3d676791e749a17683a11c3f2f358bc2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-367",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gadrin received reports from the Valley of Trials so that its discovery of the Burning Blade could be compared with dangers nearer the troll village.",["title"]="Sen'jin Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"823:description:1-86","823:description:89-169","823:description:174-288","823:description:291-378","823:description:381-414","823:description:419-447","823:objective:1-41"},["minimumStage"]=2,["questID"]=823,["sourceHash"]="8f81beb9e2d9f0aaa56b88d14aad03e27ddb5f9b53dfa01615b5f82439482dcc"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-367",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="News of the cult was to pass onward to Orgnil Soulscar in Razor Hill, linking the village’s concerns to the defense of wider Durotar.",["title"]="Sen'jin Village"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"809:description:1-128","809:description:131-174","809:description:179-263","809:description:266-344","809:description:347-367","809:description:372-474","809:description:477-503","809:objective:1-36"},["minimumStage"]=2,["questID"]=809,["sourceHash"]="912fa453c13f3ff0cbac71e6ed3e8f206bb50d9ff66d060167c501a147ffd120"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-379",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Far Watch Post stood at the Barrens border, the next contact for an inquiry arriving from Durotar.",["title"]="Far Watch Post"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"809:description:1-128","809:description:131-174","809:description:179-263","809:description:266-344","809:description:347-367","809:description:372-474","809:description:477-503","809:objective:1-36"},["minimumStage"]=2,["questID"]=809,["sourceHash"]="912fa453c13f3ff0cbac71e6ed3e8f206bb50d9ff66d060167c501a147ffd120"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-379",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ak’Zeloth waited there to direct action against the Demon Seed atop Dreadmist Peak.",["title"]="Far Watch Post"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"816:description:1-28","816:description:30-93","816:description:95-168","816:description:170-186","816:description:191-264","816:description:266-324","816:description:326-355","816:description:360-421","816:description:423-509","816:objective:1-87"},["minimumStage"]=2,["questID"]=816,["sourceHash"]="36059bc06795d3ee508d6c8952c083ebe541938a021c6d8e242b46f13ff943f3"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-16011",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Crocolisks along the Southfury attracted hunters despite warnings of their strength and viciousness; Kron went missing after setting out for them.",["title"]="Southfury River"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"823:description:1-86","823:description:89-169","823:description:174-288","823:description:291-378","823:description:381-414","823:description:419-447","823:objective:1-41"},["minimumStage"]=2,["questID"]=823,["sourceHash"]="8f81beb9e2d9f0aaa56b88d14aad03e27ddb5f9b53dfa01615b5f82439482dcc"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-362",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Orgnil Soulscar used his posting in Razor Hill to oppose evils such as the Burning Blade across Durotar.",["title"]="Razor Hill"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"824:description:1-90","824:description:93-198","824:description:203-270","824:description:273-372","824:description:375-438","824:objective:1-81"},["minimumStage"]=2,["questID"]=824,["sourceHash"]="ec1a1ac29fb71a443e612df9140fbdfb0ba5b606f4df3543cb02e0a4f4d84539"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-2897",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Je’neu Sancrea of the Earthen Ring studied elemental matters at the coastal outpost, making it a destination for mysterious relics such as the recovered globe.",["title"]="Zoram'gar Outpost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"824:description:1-90","824:description:93-198","824:description:203-270","824:description:273-372","824:description:375-438","824:objective:1-81"},["minimumStage"]=2,["questID"]=824,["sourceHash"]="ec1a1ac29fb71a443e612df9140fbdfb0ba5b606f4df3543cb02e0a4f4d84539"}},["questSourceProofsMode"]="ALL"},["field"]="location",["id"]="catalog-location-area-2897",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The outpost stood on Ashenvale’s Zoram Strand coast.",["title"]="Zoram'gar Outpost"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"828:description:1-73","828:description:76-155","828:description:157-211","828:description:216-261","828:description:264-300","828:description:305-373","828:description:378-467","828:objective:1-18"},["minimumStage"]=2,["questID"]=828,["sourceHash"]="89fc29ffd99452c6e5fbab8cfeefa02a9a1394b077fc48f120a945c92fbefc61"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-location-area-370",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Margoz’s camp lay between Drygulch Ravine and the coast, where he offered counsel before a confrontation with the Burning Blade at Skull Rock.",["title"]="Drygulch Ravine"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"838:description:1-101","838:description:104-191","838:description:194-277","838:description:282-367","838:description:370-469","838:description:472-501","838:objective:1-66"},["minimumStage"]=2,["questID"]=838,["sourceHash"]="b55d44971e2b2527e33a315be011ab316d9861a0978433c1a4c979ce02e6436c"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-2298",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The island held Scholomance, a school and stronghold where the Scourge pursued research that increased its power.",["title"]="Caer Darrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"838:description:1-101","838:description:104-191","838:description:194-277","838:description:282-367","838:description:370-469","838:description:472-501","838:objective:1-66"},["minimumStage"]=2,["questID"]=838,["sourceHash"]="b55d44971e2b2527e33a315be011ab316d9861a0978433c1a4c979ce02e6436c"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-2298",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A locked door barred entry to the school, directing the effort against it toward Dithers’s knowledge of how to obtain a key.",["title"]="Caer Darrow"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"852:description:1-69","852:description:72-104","852:description:107-196","852:description:201-212","852:description:215-262","852:description:267-325","852:objective:1-65"},["minimumStage"]=2,["questID"]=852,["sourceHash"]="7a6e37e93fd30ff02dcf390e64d5ec255a134950b1402ef5637b7dd90aa0da82"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-location-area-387",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Hezrul Bloodmark led the Barrens’ Kolkar from the oasis, making his command the target of a plan to fracture the tribe’s strength.",["title"]="Lushwater Oasis"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"853:description:1-56","853:description:59-111","853:description:114-211","853:description:216-290","853:description:293-375","853:description:380-388","853:description:391-500","853:objective:1-92"},["minimumStage"]=2,["questID"]=853,["sourceHash"]="1b9428f087c3502ca8e440e38229e49bd75ee7935785747760dcbf9580d37f5b"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-location-area-1640",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The bluff concealed the path into the Pools of Vision beneath Thunder Bluff’s shamans, where Apothecary Zamah received a time-sensitive spore emulsion.",["title"]="Spirit Rise"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="REFERENCE_ONLY",["questSourceProofs"]={{["atomIDs"]={"920:description:12-56","920:description:58-108","920:description:113-184","920:objective:1-58"},["minimumStage"]=2,["questID"]=920,["sourceHash"]="fc6d00e4a35a2ddfb531e647af1017f948ef20ed443ced97129bb5ba40544393"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-location-area-256",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tenaron received those he summoned in the highest room atop Aldrassil.",["title"]="Aldrassil"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3182:description:1-43","3182:description:45-122","3182:description:127-189","3182:description:191-254","3182:description:256-330","3182:description:335-344","3182:objective:1-60"},["minimumStage"]=2,["questID"]=3182,["sourceHash"]="119b65b0547cff301eb2897b08a1880c057fd6791b043c42fc2b6ce92b287936"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3836",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Pebblebitty doubted the recovered horn because her broken axe head was not visibly lodged in it as she expected.",["title"]="Mountaineer Pebblebitty"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3182:description:1-43","3182:description:45-122","3182:description:127-189","3182:description:191-254","3182:description:256-330","3182:description:335-344","3182:objective:1-60"},["minimumStage"]=2,["questID"]=3182,["sourceHash"]="119b65b0547cff301eb2897b08a1880c057fd6791b043c42fc2b6ce92b287936"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-3836",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She required Thorius to authenticate the claim before surrendering the key to the Searing Gorge.",["title"]="Mountaineer Pebblebitty"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3365:description:1-22","3365:description:25-131","3365:description:136-218","3365:objective:1-37"},["minimumStage"]=2,["questID"]=3365,["sourceHash"]="ce8e77b872c441d71ff4451f194383adbf810b48ca9bc0ad9f26c194b86e4119"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-836",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Durnan Furcutter enjoyed a scalding mornbrew against the winter cold and asked that its empty mug be returned to Nori.",["title"]="Durnan Furcutter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3372:description:1-17","3372:description:19-113","3372:description:118-149","3372:description:151-194","3372:description:196-227","3372:description:229-277","3372:description:282-317","3372:objective:1-178"},["minimumStage"]=2,["questID"]=3372,["sourceHash"]="200f7e41fd85bd56bbeec0da98c4e5fbbd52e2d9d645159d6b1758834ebbfef8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8417",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The dying archaeologist wanted workers freed from Suntara’s power, which compelled their tasks even after their bodies failed.",["title"]="Dying Archaeologist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3372:description:1-17","3372:description:19-113","3372:description:118-149","3372:description:151-194","3372:description:196-227","3372:description:229-277","3372:description:282-317","3372:objective:1-178"},["minimumStage"]=2,["questID"]=3372,["sourceHash"]="200f7e41fd85bd56bbeec0da98c4e5fbbd52e2d9d645159d6b1758834ebbfef8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8417",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A relic guarded by the Twilight’s Hammer in the hills was to be placed on Suntara’s altar as the means of release; the warning ended as the speaker collapsed.",["title"]="Dying Archaeologist"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3451:description:1-27","3451:description:29-59","3451:description:61-72","3451:description:74-96","3451:description:98-132","3451:description:134-177","3451:description:179-190","3451:description:195-288","3451:description:290-331","3451:description:333-383","3451:description:385-408","3451:objective:1-84"},["minimumStage"]=2,["questID"]=3451,["sourceHash"]="6aaeaea7aa9d1f887cbd478f32541e4747831fcd8d59d1eee79c4653f475f344"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-8517",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Xiggs owed Tymor favors and agreed to collect the object his associate wanted moved.",["title"]="Xiggs Fuselighter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3451:description:1-27","3451:description:29-59","3451:description:61-72","3451:description:74-96","3451:description:98-132","3451:description:134-177","3451:description:179-190","3451:description:195-288","3451:description:290-331","3451:description:333-383","3451:description:385-408","3451:objective:1-84"},["minimumStage"]=2,["questID"]=3451,["sourceHash"]="6aaeaea7aa9d1f887cbd478f32541e4747831fcd8d59d1eee79c4653f475f344"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-8517",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="A flare fired from a prepared landing pad on an island off Azshara’s southern peninsula would signal him to arrive for pickup.",["title"]="Xiggs Fuselighter"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3519:description:1-8","3519:description:10-120","3519:description:122-180","3519:description:185-216","3519:description:218-245","3519:description:250-257","3519:description:259-273","3519:objective:1-43"},["minimumStage"]=2,["questID"]=3519,["sourceHash"]="e5c489424f37178c7e5a66d9b768d4de683df3e704275e0f3503531ee8bd5a91"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-8584",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Iverron was badly bitten by Githyiss the Vile while exploring a nearby spider cave.",["title"]="Iverron"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3519:description:1-8","3519:description:10-120","3519:description:122-180","3519:description:185-216","3519:description:218-245","3519:description:250-257","3519:description:259-273","3519:objective:1-43"},["minimumStage"]=2,["questID"]=3519,["sourceHash"]="e5c489424f37178c7e5a66d9b768d4de683df3e704275e0f3503531ee8bd5a91"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-8584",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Dizzy and fearing serious poison, he asked that Dirania Silvershine be told quickly so she could help.",["title"]="Iverron"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3741:description:1-57","3741:description:60-132","3741:description:135-194","3741:description:197-244","3741:description:246-345","3741:description:350-383","3741:objective:1-61"},["minimumStage"]=2,["questID"]=3741,["sourceHash"]="8c559422ac00b28048e0cc605165f3ff1288c3250dcb022f732f7dc36da782a4"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-8965",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shawn had spent the day fishing with Hilary when the pair failed to find her missing necklace.",["title"]="Shawn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3741:description:1-57","3741:description:60-132","3741:description:135-194","3741:description:197-244","3741:description:246-345","3741:description:350-383","3741:objective:1-61"},["minimumStage"]=2,["questID"]=3741,["sourceHash"]="8c559422ac00b28048e0cc605165f3ff1288c3250dcb022f732f7dc36da782a4"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-8965",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He suspected it had fallen into the lake, but warnings from their parents kept them from swimming among its dangers, prompting his appeal for help.",["title"]="Shawn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3765:description:1-45","3765:description:50-88","3765:description:90-154","3765:description:159-213","3765:description:215-258","3765:description:263-297","3765:description:299-374","3765:objective:1-45"},["minimumStage"]=2,["questID"]=3765,["sourceHash"]="8a345913ae1dae359d36116ed3a5d3e36179d349492485b6f28e4e06197f0f44"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-4984",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Argos Nightwhisper traveled far to Stormwind in search of adventurers able to help his brother Gershala in Auberdine.",["title"]="Argos Nightwhisper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3765:description:1-45","3765:description:50-88","3765:description:90-154","3765:description:159-213","3765:description:215-258","3765:description:263-297","3765:description:299-374","3765:objective:1-45"},["minimumStage"]=2,["questID"]=3765,["sourceHash"]="8a345913ae1dae359d36116ed3a5d3e36179d349492485b6f28e4e06197f0f44"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4984",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He emphasized the length of the Darkshore journey when seeking an experienced traveler willing to go.",["title"]="Argos Nightwhisper"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3861:description:1-9","3861:description:11-18","3861:description:20-27","3861:description:29-34","3861:description:39-46","3861:description:48-55","3861:description:57-63","3861:description:68-148","3861:description:150-218","3861:description:220-233","3861:description:250-320","3861:objective:1-69","3861:objective:71-151"},["minimumStage"]=2,["questID"]=3861,["sourceHash"]="39358355a5f5e4d223bbf7068305c777f3fed1187abef38cff2dbb04a85f25a8"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-620",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="In one unusual exchange, a chicken scratched the ground as though forming a word, although the observer could not be sure before it turned away.",["title"]="Chicken"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3906:description:1-56","3906:description:58-181","3906:description:183-228","3906:description:233-306","3906:description:308-375","3906:description:380-415","3906:objective:1-69","3906:objective:71-133"},["minimumStage"]=2,["questID"]=3906,["sourceHash"]="5060c0869b2827f8988f77a630ae5d92e1a1c406e8efb22b576b2859a9b73825"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9084",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Thunderheart’s elders sensed elemental disharmony after the Dark Irons summoned a foul spirit that threatened the land.",["title"]="Thunderheart"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3906:description:1-56","3906:description:58-181","3906:description:183-228","3906:description:233-306","3906:description:308-375","3906:description:380-415","3906:objective:1-69","3906:objective:71-133"},["minimumStage"]=2,["questID"]=3906,["sourceHash"]="5060c0869b2827f8988f77a630ae5d92e1a1c406e8efb22b576b2859a9b73825"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9084",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the investigation through Blackrock’s Chasm of Flame toward the quarry and Overmaster Pyron, seeking an end to the disruption.",["title"]="Thunderheart"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"3913:description:1-71","3913:description:73-137","3913:description:139-160","3913:description:165-221","3913:objective:1-71"},["minimumStage"]=2,["questID"]=3913,["sourceHash"]="02250a2e44475aff9e22bf18dd510455a95df86f53286097c1ce6b87ffbe1866"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9299",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gaeriyan revealed that an unusual gravestone concealed secrets and instructed the seeker to push upon it after returning to the graveyard.",["title"]="Gaeriyan"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4121:description:1-87","4121:description:89-252","4121:description:257-278","4121:objective:1-113","4121:objective:118-227","4121:objective:232-303"},["minimumStage"]=2,["questID"]=4121,["sourceHash"]="0304aa2d84f718c5d1cd13abb36297565ec6a7448ea6d06c580c1340e10e6215"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-9520",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Grark Lorkrub was captured as a valued Blackrock asset from a heavily defended fortress.",["title"]="Grark Lorkrub"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4121:description:1-87","4121:description:89-252","4121:description:257-278","4121:objective:1-113","4121:objective:118-227","4121:objective:232-303"},["minimumStage"]=2,["questID"]=4121,["sourceHash"]="0304aa2d84f718c5d1cd13abb36297565ec6a7448ea6d06c580c1340e10e6215"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-9520",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He warned his captor that the seizure could not have gone unnoticed and doubted the escort would reach its rendezvous alive.",["title"]="Grark Lorkrub"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4128:description:10-88","4128:description:91-155","4128:description:160-195","4128:description:198-259","4128:objective:1-30"},["minimumStage"]=2,["questID"]=4128,["sourceHash"]="0ff05ad48acf2676868d592b606d8e95fb0662e94580631e400c7a2eecc1f782"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9540",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Enohar heard of Ragnar Thunderbrew’s stolen ale and directed potential helpers to the Thunderbrew Distillery in Kharanos.",["title"]="Enohar Thunderbrew"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4492:description:1-26","4492:description:28-136","4492:description:138-167","4492:description:172-203","4492:description:205-291","4492:objective:1-31"},["minimumStage"]=2,["questID"]=4492,["sourceHash"]="b3e570c128cf7cb1b8906f49619bd0c11fc227b51ccbe711147674aedb4dc0f6"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-9997",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Spraggle worried when Ringo failed to return from exploring the southern volcano, asking that someone find the overdue friend.",["title"]="Spraggle Frock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4492:description:1-26","4492:description:28-136","4492:description:138-167","4492:description:172-203","4492:description:205-291","4492:objective:1-31"},["minimumStage"]=2,["questID"]=4492,["sourceHash"]="b3e570c128cf7cb1b8906f49619bd0c11fc227b51ccbe711147674aedb4dc0f6"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-9997",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The offered canteen anticipated Ringo’s need for water if he were found, making the search a practical rescue rather than merely a report.",["title"]="Spraggle Frock"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4542:description:1-71","4542:description:73-138","4542:description:140-233","4542:description:238-282","4542:description:284-330","4542:objective:1-67"},["minimumStage"]=2,["questID"]=4542,["sourceHash"]="48d2232afe58ed6ba895c13cfd062c1c62bb42928477cf54957d1da9600e9374"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10079",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Moonhorn reported renewed centaur attacks and wanted Freewind Post warned through Cliffwatcher Longhorn.",["title"]="Brave Moonhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4542:description:1-71","4542:description:73-138","4542:description:140-233","4542:description:238-282","4542:description:284-330","4542:objective:1-67"},["minimumStage"]=2,["questID"]=4542,["sourceHash"]="48d2232afe58ed6ba895c13cfd062c1c62bb42928477cf54957d1da9600e9374"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10079",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He also urged caution around nearby Grimtotem, whose altered behavior troubled him without yet explaining its cause.",["title"]="Brave Moonhorn"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4809:description:1-102","4809:description:105-234","4809:description:237-291","4809:description:296-373","4809:objective:1-56"},["minimumStage"]=2,["questID"]=4809,["sourceHash"]="2cc9c8bd8cc9e9b0b3c38d337911fba5f1fd4887234c8a57ccbb48c7bc3d065d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10468",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Felnok prepared an order for Tinkee whose missing component was a supply of undamaged chillwind horns.",["title"]="Felnok Steelspring"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"4809:description:1-102","4809:description:105-234","4809:description:237-291","4809:description:296-373","4809:objective:1-56"},["minimumStage"]=2,["questID"]=4809,["sourceHash"]="2cc9c8bd8cc9e9b0b3c38d337911fba5f1fd4887234c8a57ccbb48c7bc3d065d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10468",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Winterspring chimaeras’ horns concentrated cold, but cracks made them unsuitable for the intended work.",["title"]="Felnok Steelspring"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5151:description:1-62","5151:description:64-141","5151:description:143-146","5151:description:148-212","5151:description:217-244","5151:description:246-292","5151:description:294-366","5151:description:371-412","5151:objective:1-99"},["minimumStage"]=2,["questID"]=5151,["sourceHash"]="cd7498fd65a6f171d832d713aa7b8fa9c45a4313502f0eaed5520c085ee7d31b"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-10941",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Wizlo Bearingshiner described himself as the sole survivor of a centaur attack on his caravan.",["title"]="Wizlo Bearingshiner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5151:description:1-62","5151:description:64-141","5151:description:143-146","5151:description:148-212","5151:description:217-244","5151:description:246-292","5151:description:294-366","5151:description:371-412","5151:objective:1-99"},["minimumStage"]=2,["questID"]=5151,["sourceHash"]="cd7498fd65a6f171d832d713aa7b8fa9c45a4313502f0eaed5520c085ee7d31b"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10941",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="His hypercapacitor hung around the neck of a powerful caged panther the centaur feared to approach, leaving him dependent on a helper to recover it.",["title"]="Wizlo Bearingshiner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5164:description:1-59","5164:description:61-118","5164:description:123-143","5164:description:145-181","5164:description:183-203","5164:description:205-225","5164:objective:1-39"},["minimumStage"]=2,["questID"]=5164,["sourceHash"]="0f6fb3df12a8f245d735e7662bd199fb0a90730f522cddfc7b18ca185d288421"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-10976",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Jeziba recognized Haleh’s chosen champion and offered the Catalogue of the Wayward as guidance toward demanding deeds and the possibility of heroism.",["title"]="Jeziba"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5249:description:1-74","5249:description:76-142","5249:description:147-243","5249:description:245-284","5249:description:289-334","5249:description:336-416","5249:objective:1-70"},["minimumStage"]=2,["questID"]=5249,["sourceHash"]="e65e515b65aebae61fc710b524258c5099a233fac0f61ad9cb8e7ba532986f44"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-10924",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Work in Felwood had kept Ivy Leafrunner from exploring Winterspring’s ancient elven ruins.",["title"]="Ivy Leafrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5249:description:1-74","5249:description:76-142","5249:description:147-243","5249:description:245-284","5249:description:289-334","5249:description:336-416","5249:objective:1-70"},["minimumStage"]=2,["questID"]=5249,["sourceHash"]="e65e515b65aebae61fc710b524258c5099a233fac0f61ad9cb8e7ba532986f44"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-10924",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She recommended Wynd Nightchaser of Starfall Village as a knowledgeable guide to the harsh northern region.",["title"]="Ivy Leafrunner"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5252:description:1-6","5252:description:8-21","5252:description:26-80","5252:description:85-159","5252:description:161-291","5252:description:296-318","5252:description:323-349","5252:objective:1-109"},["minimumStage"]=2,["questID"]=5252,["sourceHash"]="b5ee54ee758659ac05b081633c9d0aa91fbf684ec3e13472d3b3fbfa958d4a21"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-10684",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The remorseful Highborne recognized an old error amid the misery clouding the other Highborne and accepted that the past could not be changed.",["title"]="Remorseful Highborne"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5252:description:1-6","5252:description:8-21","5252:description:26-80","5252:description:85-159","5252:description:161-291","5252:description:296-318","5252:description:323-349","5252:objective:1-109"},["minimumStage"]=2,["questID"]=5252,["sourceHash"]="b5ee54ee758659ac05b081633c9d0aa91fbf684ec3e13472d3b3fbfa958d4a21"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-10684",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Recovery of Zin-Malor’s crystal brought a measure of peace, but the figure urgently insisted that it still had to be returned.",["title"]="Remorseful Highborne"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5265:description:1-54","5265:description:56-153","5265:description:158-196","5265:objective:1-43"},["minimumStage"]=2,["questID"]=5265,["sourceHash"]="81d6117aee47dd7049cc481025644e956f93e3af4fc20879bfd8ca20f8db5a6d"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11034",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Tyrosus permitted a worthy ally access to the long-closed Argent Hold, presenting its power as something earlier claimants had not earned.",["title"]="Lord Maxwell Tyrosus"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5302:description:1-42","5302:description:44-71","5302:description:76-100","5302:description:102-112","5302:description:114-195","5302:description:197-250","5302:description:255-298","5302:description:300-340","5302:objective:1-177"},["minimumStage"]=2,["questID"]=5302,["sourceHash"]="1a7be8ad5f3c5e90d4f418b76e04d88820a6d7a4a9a884e7276920d94baee41d"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="npc-11178",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Borgosh Corebender devoted his life’s work to creating a legendary hammer worthy of a warchief.",["title"]="Borgosh Corebender"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5302:description:1-42","5302:description:44-71","5302:description:76-100","5302:description:102-112","5302:description:114-195","5302:description:197-250","5302:description:255-298","5302:description:300-340","5302:objective:1-177"},["minimumStage"]=2,["questID"]=5302,["sourceHash"]="1a7be8ad5f3c5e90d4f418b76e04d88820a6d7a4a9a884e7276920d94baee41d"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="npc-11178",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered to guide a promising craftsperson toward weaponsmithing after a practical task demonstrated that potential.",["title"]="Borgosh Corebender"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5305:description:1-63","5305:description:65-120","5305:description:122-155","5305:description:157-249","5305:objective:1-54","5305:objective:56-116"},["minimumStage"]=2,["questID"]=5305,["sourceHash"]="18f6b124ce66de444d721bff8bc0448ff1c5719bddd1418f1a569f968ea8a463"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11191",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Lilith the Lithe offered enchanted battlehammer knowledge in return for the Crimson Hammersmith’s apron.",["title"]="Lilith the Lithe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5305:description:1-63","5305:description:65-120","5305:description:122-155","5305:description:157-249","5305:objective:1-54","5305:objective:56-116"},["minimumStage"]=2,["questID"]=5305,["sourceHash"]="18f6b124ce66de444d721bff8bc0448ff1c5719bddd1418f1a569f968ea8a463"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11191",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Her request led into the Scarlet Bastion, where the hammersmith guarded the recipe known as Serenity.",["title"]="Lilith the Lithe"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5306:description:1-34","5306:description:36-90","5306:description:95-134","5306:description:139-188","5306:description:193-232","5306:description:237-279","5306:description:281-326","5306:description:328-391","5306:objective:1-60","5306:objective:62-114"},["minimumStage"]=2,["questID"]=5306,["sourceHash"]="ddf54be104ce6a1e0c74b2a10a852803f2645426594cea853c758107ee0999e8"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-11192",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kilram bore a visible scar on his face, which he pointed out while recounting his encounter with Vosh’gajin.",["title"]="Kilram"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5306:description:1-34","5306:description:36-90","5306:description:95-134","5306:description:139-188","5306:description:193-232","5306:description:237-279","5306:description:281-326","5306:description:328-391","5306:objective:1-60","5306:objective:62-114"},["minimumStage"]=2,["questID"]=5306,["sourceHash"]="ddf54be104ce6a1e0c74b2a10a852803f2645426594cea853c758107ee0999e8"}},["questSourceProofsMode"]="ALL"},["field"]="history",["id"]="catalog-unit-11192",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He said the shadow huntress had given him the wound and called it a love tap.",["title"]="Kilram"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5306:description:1-34","5306:description:36-90","5306:description:95-134","5306:description:139-188","5306:description:193-232","5306:description:237-279","5306:description:281-326","5306:description:328-391","5306:objective:1-60","5306:objective:62-114"},["minimumStage"]=2,["questID"]=5306,["sourceHash"]="ddf54be104ce6a1e0c74b2a10a852803f2645426594cea853c758107ee0999e8"}},["questSourceProofsMode"]="ALL"},["field"]="motivation",["id"]="catalog-unit-11192",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Vengeance and the recovery of her snakestone were the price of his instruction in crafting Dawn’s Edge.",["title"]="Kilram"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5307:description:1-43","5307:description:45-180","5307:description:185-219","5307:description:224-284","5307:description:286-293","5307:description:298-408","5307:objective:1-62","5307:objective:64-135"},["minimumStage"]=2,["questID"]=5307,["sourceHash"]="b12dd53c1cf74efea3ab5aa31c01e591a9af3e0143fafb52e394b02fe87c5ee2"}},["questSourceProofsMode"]="ALL"},["field"]="conflict",["id"]="catalog-unit-11193",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Seril’s plans for Corruption had been stolen by Rivendare’s Black Guard, leaving their swordsmith in possession of the design.",["title"]="Seril Scourgebane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5307:description:1-43","5307:description:45-180","5307:description:185-219","5307:description:224-284","5307:description:286-293","5307:description:298-408","5307:objective:1-62","5307:objective:64-135"},["minimumStage"]=2,["questID"]=5307,["sourceHash"]="b12dd53c1cf74efea3ab5aa31c01e591a9af3e0143fafb52e394b02fe87c5ee2"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11193",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He offered knowledge of a blazing rapier to the helper who confronted the undead smith and returned proof.",["title"]="Seril Scourgebane"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5385:description:1-122","5385:description:124-228","5385:objective:1-67"},["minimumStage"]=2,["questID"]=5385,["sourceHash"]="6c8b274ba071c4019854ccaf5c7b5c2dbfe2db47f93c7d3fbb3f662f91d80333"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11020",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Trey Lightforge’s remains were gathered for return to Jessir Moonbow at the Felwood–Ashenvale border, in hope that the paladin’s friends could honor him properly.",["title"]="Remains of Trey Lightforge"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5481:description:1-18","5481:description:20-61","5481:description:63-94","5481:description:96-114","5481:description:116-152","5481:description:157-227","5481:objective:1-90"},["minimumStage"]=2,["questID"]=5481,["sourceHash"]="adc17ab136e99d1f56952544eacfafd48c2ffd4954ed5628384dbbcc18d23936"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-10666",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Gordo described his large hands as poorly suited to the delicate work of picking weeds.",["title"]="Gordo"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5481:description:1-18","5481:description:20-61","5481:description:63-94","5481:description:96-114","5481:description:116-152","5481:description:157-227","5481:objective:1-90"},["minimumStage"]=2,["questID"]=5481,["sourceHash"]="adc17ab136e99d1f56952544eacfafd48c2ffd4954ed5628384dbbcc18d23936"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-10666",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He sought help gathering gloom weed for Holland at Brill’s graveyard.",["title"]="Gordo"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5622:description:1-78","5622:description:80-120","5622:description:122-287","5622:description:292-344","5622:objective:1-43"},["minimumStage"]=2,["questID"]=5622,["sourceHash"]="de63ffddca3a95089dfcee61199a1d96f14d312ca6187e4637094a5b01a28234"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-3595",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Shanda sent a priest of Elune onward from Shadowglen to Laurna Morninglight in Dolanaar.",["title"]="Shanda"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5622:description:1-78","5622:description:80-120","5622:description:122-287","5622:description:292-344","5622:objective:1-43"},["minimumStage"]=2,["questID"]=5622,["sourceHash"]="de63ffddca3a95089dfcee61199a1d96f14d312ca6187e4637094a5b01a28234"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3595",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Laurna’s instruction would bring the first garments marking the initiate’s religious station.",["title"]="Shanda"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5623:description:1-39","5623:description:41-99","5623:description:101-214","5623:description:216-308","5623:description:310-348","5623:objective:1-44"},["minimumStage"]=2,["questID"]=5623,["sourceHash"]="62265de16d6e4d18973b267b147ced1f37832b93a016a3d38a020ca915f9f834"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-375",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Anetta prepared Northshire’s young priests to continue their religious learning under Josetta in Goldshire.",["title"]="Priestess Anetta"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5623:description:1-39","5623:description:41-99","5623:description:101-214","5623:description:216-308","5623:description:310-348","5623:objective:1-44"},["minimumStage"]=2,["questID"]=5623,["sourceHash"]="62265de16d6e4d18973b267b147ced1f37832b93a016a3d38a020ca915f9f834"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-375",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The referral followed growing strength in the Light, placing further tutoring beyond the novice’s first work in Northshire.",["title"]="Priestess Anetta"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5306:description:1-34","5306:description:36-90","5306:description:95-134","5306:description:139-188","5306:description:193-232","5306:description:237-279","5306:description:281-326","5306:description:328-391","5306:objective:1-60","5306:objective:62-114"},["minimumStage"]=2,["questID"]=5306,["sourceHash"]="ddf54be104ce6a1e0c74b2a10a852803f2645426594cea853c758107ee0999e8"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-9236",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Kilram attributed the scar across his face to Vosh’gajin, recalling that she had mockingly called the wound a love tap.",["title"]="Shadow Hunter Vosh'gajin"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5305:description:1-63","5305:description:65-120","5305:description:122-155","5305:description:157-249","5305:objective:1-54","5305:objective:56-116"},["minimumStage"]=2,["questID"]=5305,["sourceHash"]="18f6b124ce66de444d721bff8bc0448ff1c5719bddd1418f1a569f968ea8a463"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11120",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The Crimson Hammersmith guarded Serenity’s recipe within Stratholme’s Scarlet Bastion; Lilith sought his apron in exchange for the craft’s secrets.",["title"]="Crimson Hammersmith"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5307:description:1-43","5307:description:45-180","5307:description:185-219","5307:description:224-284","5307:description:286-293","5307:description:298-408","5307:objective:1-62","5307:objective:64-135"},["minimumStage"]=2,["questID"]=5307,["sourceHash"]="b12dd53c1cf74efea3ab5aa31c01e591a9af3e0143fafb52e394b02fe87c5ee2"}},["questSourceProofsMode"]="ALL"},["field"]="appearance",["id"]="catalog-unit-11121",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The swordsmith belonged to Rivendare’s elite skeletal Black Guard in Stratholme.",["title"]="Black Guard Swordsmith"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5307:description:1-43","5307:description:45-180","5307:description:185-219","5307:description:224-284","5307:description:286-293","5307:description:298-408","5307:objective:1-62","5307:objective:64-135"},["minimumStage"]=2,["questID"]=5307,["sourceHash"]="b12dd53c1cf74efea3ab5aa31c01e591a9af3e0143fafb52e394b02fe87c5ee2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11121",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He guarded the stolen plans for Corruption, drawing Seril’s retaliation and the search for proof of the smith’s defeat.",["title"]="Black Guard Swordsmith"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5626:description:1-4","5626:description:10-23","5626:description:28-125","5626:description:127-280","5626:description:285-298","5626:description:300-374","5626:objective:1-35"},["minimumStage"]=2,["questID"]=5626,["sourceHash"]="ab085714045f56a2451832c34a7eae335570ea1f08b75fcaee2875debb324c60"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-837",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Branstock Khalder directed a developing priest of the Light through the tunnel to Maxan Anvol in Kharanos.",["title"]="Branstock Khalder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5626:description:1-4","5626:description:10-23","5626:description:28-125","5626:description:127-280","5626:description:285-298","5626:description:300-374","5626:objective:1-35"},["minimumStage"]=2,["questID"]=5626,["sourceHash"]="ab085714045f56a2451832c34a7eae335570ea1f08b75fcaee2875debb324c60"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-837",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Further instruction and proof of worth would bring robes marking the novice’s religious station.",["title"]="Branstock Khalder"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5632:description:1-19","5632:description:21-30","5632:description:32-100","5632:description:102-235","5632:description:237-280","5632:description:282-356","5632:description:361-400","5632:objective:1-40"},["minimumStage"]=2,["questID"]=5632,["sourceHash"]="ba6f20cde13606dcc96235af5eea7d05458f04092f21a136036a3e4f6fdc6146"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11397",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nara Meideros relayed an order messenger’s request that the promising priest return to Alathea at Darnassus’s Temple of the Moon.",["title"]="Nara Meideros"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5632:description:1-19","5632:description:21-30","5632:description:32-100","5632:description:102-235","5632:description:237-280","5632:description:282-356","5632:description:361-400","5632:objective:1-40"},["minimumStage"]=2,["questID"]=5632,["sourceHash"]="ba6f20cde13606dcc96235af5eea7d05458f04092f21a136036a3e4f6fdc6146"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-11397",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Nara understood the summons to concern progress in their religious ways but did not claim to know its full purpose.",["title"]="Nara Meideros"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5633:description:1-25","5633:description:27-66","5633:description:68-102","5633:description:107-199","5633:description:201-279","5633:description:281-340","5633:description:342-398","5633:objective:1-40"},["minimumStage"]=2,["questID"]=5633,["sourceHash"]="ec73a2b7a7318a56ed6576240900086f85ab5b02d96daf3160d5c5c04c97003e"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5142",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Braenna Flintcrag passed along word from a visiting priestess seeking the traveler’s return to the Temple of the Moon.",["title"]="Braenna Flintcrag"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5633:description:1-25","5633:description:27-66","5633:description:68-102","5633:description:107-199","5633:description:201-279","5633:description:281-340","5633:description:342-398","5633:objective:1-40"},["minimumStage"]=2,["questID"]=5633,["sourceHash"]="ec73a2b7a7318a56ed6576240900086f85ab5b02d96daf3160d5c5c04c97003e"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5142",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She welcomed the visitor with a blessing, then stressed the importance of meeting Alathea despite having little more information herself.",["title"]="Braenna Flintcrag"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5641:description:1-72","5641:description:74-137","5641:description:139-226","5641:description:228-273","5641:description:275-339","5641:description:341-359","5641:objective:1-40"},["minimumStage"]=2,["questID"]=5641,["sourceHash"]="3137e6f25601f6748e2d059aba443b2cad7191e04ac6c1767d977459a1be36a4"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-376",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Laurena conveyed Rohan’s wish to meet a priest in Ironforge’s Mystic Ward for a new test.",["title"]="High Priestess Laurena"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5641:description:1-72","5641:description:74-137","5641:description:139-226","5641:description:228-273","5641:description:275-339","5641:description:341-359","5641:objective:1-40"},["minimumStage"]=2,["questID"]=5641,["sourceHash"]="3137e6f25601f6748e2d059aba443b2cad7191e04ac6c1767d977459a1be36a4"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-376",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="She wished she could witness the traveler’s distinct racial rites but remained at her own post, offering the Light’s blessing for the journey.",["title"]="High Priestess Laurena"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5642:description:1-43","5642:description:48-142","5642:description:144-193","5642:description:195-232","5642:description:234-289","5642:objective:1-29"},["minimumStage"]=2,["questID"]=5642,["sourceHash"]="8a8ff90ebf9da1ac082887330602c7b95ce4ebbf20fe20c4cdf14c519182bcc2"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3044",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Miles Welsh noticed that messengers seeking troll priests had become unusually hurried and urged a prompt return from Thunder Bluff to Orgrimmar’s Valley of Spirits.",["title"]="Miles Welsh"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5643:description:1-79","5643:description:81-163","5643:description:165-211","5643:description:213-286","5643:description:288-346","5643:objective:1-29"},["minimumStage"]=2,["questID"]=5643,["sourceHash"]="da005e8ce863704dfef114b638e87b299576155695ade3fc230e43db75efabc9"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="npc-4607",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Father Lankester understood tribal rites as preparation for survival, teaching special abilities when a priest reached the proper stage.",["title"]="Father Lankester"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5643:description:1-79","5643:description:81-163","5643:description:165-211","5643:description:213-286","5643:description:288-346","5643:objective:1-29"},["minimumStage"]=2,["questID"]=5643,["sourceHash"]="da005e8ce863704dfef114b638e87b299576155695ade3fc230e43db75efabc9"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="npc-4607",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the initiate toward Ur’kyo in Orgrimmar rather than claiming that instruction for himself.",["title"]="Father Lankester"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5645:description:1-72","5645:description:74-137","5645:description:139-226","5645:description:228-273","5645:description:275-339","5645:description:341-359","5645:objective:1-40"},["minimumStage"]=2,["questID"]=5645,["sourceHash"]="a06321d76a0dc906a34a86290e0eaa42654959e9753b136754a32360477ff5cb"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-5143",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Toldren Deepiron conveyed Rohan’s summons to the Mystic Ward for a test particular to the traveler’s people.",["title"]="Toldren Deepiron"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5645:description:1-72","5645:description:74-137","5645:description:139-226","5645:description:228-273","5645:description:275-339","5645:description:341-359","5645:objective:1-40"},["minimumStage"]=2,["questID"]=5645,["sourceHash"]="a06321d76a0dc906a34a86290e0eaa42654959e9753b136754a32360477ff5cb"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-5143",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He expressed interest in those special rites while acknowledging that duty prevented him from witnessing them.",["title"]="Toldren Deepiron"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5646:description:1-124","5646:description:129-160","5646:description:162-252","5646:description:254-284","5646:objective:1-38"},["minimumStage"]=2,["questID"]=5646,["sourceHash"]="57e04fcbbfb82683d15f013e2ee22d2936d0c3c7983ec402ce9788610e4e6f4a"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-3046",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Father Cobb reciprocated Aelthalyste’s practice of sending priests back to the teachers of their own people.",["title"]="Father Cobb"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5646:description:1-124","5646:description:129-160","5646:description:162-252","5646:description:254-284","5646:objective:1-38"},["minimumStage"]=2,["questID"]=5646,["sourceHash"]="57e04fcbbfb82683d15f013e2ee22d2936d0c3c7983ec402ce9788610e4e6f4a"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-3046",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="He directed the recipient to the Undercity’s War Quarter to learn more about that people’s traditions.",["title"]="Father Cobb"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5654:description:1-43","5654:description:45-91","5654:description:93-118","5654:description:120-173","5654:description:175-249","5654:objective:1-29"},["minimumStage"]=2,["questID"]=5654,["sourceHash"]="f617acfd85d590b017872e5c63cbe422c50d015a08d7d0d08c5d8874ebb7d255"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-11407",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Var’jun guided a developing troll priest toward Ur’kyo and fuller initiation into the tribe’s old ways.",["title"]="Var'jun"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5654:description:1-43","5654:description:45-91","5654:description:93-118","5654:description:120-173","5654:description:175-249","5654:objective:1-29"},["minimumStage"]=2,["questID"]=5654,["sourceHash"]="f617acfd85d590b017872e5c63cbe422c50d015a08d7d0d08c5d8874ebb7d255"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"]="catalog-unit-11407",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="The next teacher waited in Orgrimmar’s Valley of Spirits.",["title"]="Var'jun"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5654:description:1-43","5654:description:45-91","5654:description:93-118","5654:description:120-173","5654:description:175-249","5654:objective:1-29"},["minimumStage"]=2,["questID"]=5654,["sourceHash"]="f617acfd85d590b017872e5c63cbe422c50d015a08d7d0d08c5d8874ebb7d255"}},["questSourceProofsMode"]="ALL"},["field"]="role",["id"]="catalog-unit-6018",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Ur’kyo taught the old priestly ways in Orgrimmar’s Valley of Spirits, receiving initiates referred by Var’jun.",["title"]="Ur'kyo"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5674:description:1-29","5674:description:31-136","5674:description:138-171","5674:description:173-288","5674:description:290-381","5674:objective:1-40"},["minimumStage"]=2,["questID"]=5674,["sourceHash"]="4c42ab1f5d45c0c23346a81d0bd6401de7a198ba24da596b618b743d56a33879"}},["questSourceProofsMode"]="ALL"},["field"]="context",["id"]="catalog-unit-4090",["qualification"]="Source-attributed description; not native appearance capture, current spawn verification or a personal encounter.",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVersion"]="retained-quest-biography-2026-10-26-r3",["text"]="Astarii recognized the stage at which night elf priests learned abilities particular to their people, including Elune’s Grace.",["title"]="Astarii Starseeker"},{["evidence"]={["method"]="RETAINED_QUEST_SOURCE_ACCOUNT",["narrativeUse"]="CONTEXTUAL_RECALL",["questSourceProofs"]={{["atomIDs"]={"5674:description:1-29","5674:description:31-136","5674:description:138-171","5674:description:173-288","5674:description:290-381","5674:objective:1-40"},["minimumStage"]=2,["questID"]=5674,["sourceHash"]="4c42ab1f5d45c0c23346a81d0bd6401de7a198ba24da596b618b743d56a33879"}},["questSourceProofsMode"]="ALL"},["field"]="relationships",["id"